CREATE OR REPLACE FUNCTION public.race_engine_get_non_destructive_stage_effect_plan_raw_v2(p_stage_id uuid, p_process_run_id uuid, p_effect_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_effect_key text :=
    lower(btrim(coalesce(p_effect_key,'')));

  v_config
    public.race_engine_non_destructive_effect_adapter_config_v2%rowtype;

  v_registry
    public.race_engine_effect_adapter_registry_v2%rowtype;

  v_global
    public.race_engine_effect_adapter_execution_config_v2%rowtype;

  v_state
    public.race_engine_effect_adapter_execution_state_v2%rowtype;

  v_process
    public.race_engine_stage_process_runs_v2%rowtype;

  v_effect
    public.race_engine_stage_effect_ledger_v2%rowtype;

  v_stage_id uuid;
  v_stage_race_id uuid;
  v_stage_simulation_run_id uuid;
  v_stage_simulation_status text;
  v_stage_process_plan jsonb;

  v_source jsonb;
  v_output jsonb;

  v_route_format text;
  v_source_status text;
  v_output_status text;
  v_source_hash text;
  v_output_hash text;

  v_writer_hash text;
  v_source_function_hash text;
  v_output_function_hash text;

  v_process_found boolean := false;
  v_process_exact boolean := false;
  v_effect_found boolean := false;

  v_prior_effects jsonb := '[]'::jsonb;
  v_unsatisfied_prior_count integer := 0;

  v_stage_closeout_status text;

  v_global_shadow_enabled boolean := false;
  v_state_shadow_enabled boolean := false;
  v_local_shadow_enabled boolean := false;
  v_allowed_shadow_effect boolean := false;
  v_a10_transition_shadow_enabled boolean := false;

  v_status text;
  v_plan jsonb;
begin
  if p_stage_id is null
     or v_effect_key not in ('weather_exposure','fatigue')
  then
    return jsonb_build_object(
      'status','blocked_invalid_non_destructive_effect_input',
      'stage_id',p_stage_id,
      'effect_key',v_effect_key,
      'writer_execution_allowed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  select *
  into v_config
  from public.race_engine_non_destructive_effect_adapter_config_v2 c
  where c.effect_key = v_effect_key;

  if not found then
    return jsonb_build_object(
      'status','blocked_non_destructive_effect_config_missing',
      'stage_id',p_stage_id,
      'effect_key',v_effect_key,
      'writer_execution_allowed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  select *
  into v_registry
  from public.race_engine_effect_adapter_registry_v2 r
  where r.registry_version = v_config.registry_version
    and r.effect_key = v_effect_key;

  select *
  into v_global
  from public.race_engine_effect_adapter_execution_config_v2 c
  where c.config_key = 'ordered_effect_adapters';

  select *
  into v_state
  from public.race_engine_effect_adapter_execution_state_v2 s
  where s.registry_version = v_config.registry_version
    and s.effect_key = v_effect_key;

  select
    s.id,
    s.race_id,
    run.id,
    lower(coalesce(run.status,'not_created')),
    public.race_engine_get_stage_process_plan_v2(s.id)
  into
    v_stage_id,
    v_stage_race_id,
    v_stage_simulation_run_id,
    v_stage_simulation_status,
    v_stage_process_plan
  from public.race_stages s
  left join public.race_stage_simulation_runs run
    on run.stage_id = s.id
  where s.id = p_stage_id
  limit 1;

  if v_stage_id is null then
    return jsonb_build_object(
      'status','stage_not_found',
      'stage_id',p_stage_id,
      'effect_key',v_effect_key,
      'writer_execution_allowed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  v_route_format :=
    lower(
      coalesce(
        v_stage_process_plan -> 'stage' ->> 'route_format',
        v_stage_process_plan -> 'stage' ->> 'normalized_stage_format',
        ''
      )
    );

  if v_effect_key = 'weather_exposure' then
    v_source :=
      public.race_engine_get_stage_weather_exposure_source_evidence_v2(
        p_stage_id
      );

    v_output :=
      public.race_engine_get_stage_weather_exposure_output_evidence_v2(
        p_stage_id
      );

    v_writer_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_apply_rain_jacket_weather_exposure_v1(uuid,uuid)'
          ::regprocedure
        )
      );

    v_source_function_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_get_stage_weather_exposure_source_evidence_v2(uuid)'
          ::regprocedure
        )
      );

    v_output_function_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_get_stage_weather_exposure_output_evidence_v2(uuid)'
          ::regprocedure
        )
      );
  else
    v_source :=
      public.race_engine_get_stage_fatigue_source_evidence_v2(
        p_stage_id
      );

    v_output :=
      public.race_engine_get_stage_fatigue_output_evidence_v2(
        p_stage_id
      );

    v_writer_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_apply_stage_fatigue_v1(uuid)'::regprocedure
        )
      );

    v_source_function_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_get_stage_fatigue_source_evidence_v2(uuid)'
          ::regprocedure
        )
      );

    v_output_function_hash :=
      md5(
        pg_get_functiondef(
          'public.race_engine_get_stage_fatigue_output_evidence_v2(uuid)'
          ::regprocedure
        )
      );
  end if;

  v_source_status := v_source ->> 'status';
  v_output_status := v_output ->> 'status';
  v_source_hash := v_source ->> 'source_payload_hash';
  v_output_hash := v_output ->> v_config.output_hash_key;

  if p_process_run_id is not null then
    select *
    into v_process
    from public.race_engine_stage_process_runs_v2 p
    where p.process_run_id = p_process_run_id;

    v_process_found := found;

    if v_process_found then
      v_process_exact :=
        v_process.stage_id = p_stage_id
        and v_process.race_id = v_stage_race_id
        and v_process.simulation_run_id = v_stage_simulation_run_id
        and v_process.status = 'started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run;
    end if;
  end if;

  select *
  into v_effect
  from public.race_engine_stage_effect_ledger_v2 e
  where e.stage_id = p_stage_id
    and e.effect_key = v_effect_key;

  v_effect_found := found;

  with prior as
  (
    select
      prior_key,
      coalesce(
        (
          select e.effect_status
          from public.race_engine_stage_effect_ledger_v2 e
          where e.stage_id = p_stage_id
            and e.effect_key = prior_key
          limit 1
        ),
        'missing'
      ) as effect_status
    from unnest(v_registry.prior_effect_keys) prior_key
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'effect_key',prior_key,
          'effect_status',effect_status,
          'dependency_satisfied',
            effect_status in ('verified','skipped')
        )
        order by array_position(v_registry.prior_effect_keys,prior_key)
      ),
      '[]'::jsonb
    ),
    count(*) filter(
      where effect_status not in ('verified','skipped')
    )::integer
  into
    v_prior_effects,
    v_unsatisfied_prior_count
  from prior;

  select e.effect_status
  into v_stage_closeout_status
  from public.race_engine_stage_effect_ledger_v2 e
  where e.stage_id = p_stage_id
    and e.effect_key = 'stage_closeout';

  v_global_shadow_enabled :=
    coalesce(v_global.adapter_shadow_execution_enabled,false);

  v_state_shadow_enabled :=
    coalesce(v_state.shadow_execution_enabled,false);

  v_local_shadow_enabled :=
    coalesce(v_config.shadow_execution_enabled,false);

  v_allowed_shadow_effect :=
    v_effect_key = any(
      coalesce(v_global.allowed_shadow_effect_keys,'{}'::text[])
    );

  select coalesce(c.transition_shadow_execution_enabled,false)
  into v_a10_transition_shadow_enabled
  from public.race_engine_effect_immutable_config_v2 c
  where c.config_key = 'effect_immutable';

  if v_registry.effect_key is null
     or v_state.effect_key is null
     or v_global.config_key is null
  then
    v_status :=
      'blocked_a11_non_destructive_registry_or_execution_state_missing';

  elsif v_registry.effect_order <> v_config.effect_order
        or v_registry.integration_class
           is distinct from 'non_destructive_stage_scoped_wrapper'
        or v_registry.canonical_writer_definition_hash
           is distinct from v_config.canonical_writer_definition_hash
  then
    v_status :=
      'blocked_a11_non_destructive_registry_contract_mismatch';

  elsif v_writer_hash
        is distinct from v_config.canonical_writer_definition_hash
        or v_source_function_hash
           is distinct from v_config.source_evidence_definition_hash
        or v_output_function_hash
           is distinct from v_config.output_evidence_definition_hash
  then
    v_status :=
      'blocked_a11_non_destructive_definition_drift';

  elsif p_stage_id =
        '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid
        or exists
           (
             select 1
             from public.race_engine_golden_stage_fixture_v1 f
             where f.stage_id = p_stage_id
               and f.fixture_status = 'frozen_and_validated'
           )
  then
    v_status := 'historical_golden_fixture_verify_only';

  elsif v_stage_simulation_status <> 'completed'
  then
    v_status :=
      'blocked_a11_non_destructive_simulation_run_not_completed';

  elsif v_route_format <> all(v_config.supported_route_formats)
  then
    v_status :=
      'blocked_a11_non_destructive_route_not_supported';

  elsif v_effect_key = 'weather_exposure'
        and v_source_status = 'route_skipped_weather_cancelled'
  then
    v_status := 'weather_cancelled_skip_normal_exposure';

  elsif v_source_status <> 'source_evidence_ready'
  then
    v_status :=
      'blocked_a11_non_destructive_source_not_ready';

  elsif nullif(v_source_hash,'') is null
  then
    v_status :=
      'blocked_a11_non_destructive_source_hash_missing';

  elsif v_stage_closeout_status is not null
  then
    v_status :=
      'blocked_a11_non_destructive_stage_closeout_exists';

  elsif v_unsatisfied_prior_count <> 0
  then
    v_status :=
      'blocked_a11_non_destructive_prior_effects_unsatisfied';

  elsif not v_process_found
  then
    v_status :=
      'blocked_a11_non_destructive_process_run_required';

  elsif not v_process_exact
  then
    v_status :=
      'blocked_a11_non_destructive_process_run_identity_mismatch';

  elsif not v_effect_found
  then
    v_status :=
      'blocked_a11_non_destructive_effect_reservation_required';

  elsif v_effect.effect_status = 'verified'
        and v_effect.source_payload_hash is not distinct from v_source_hash
        and nullif(v_effect.applied_payload_hash,'') is not null
  then
    v_status :=
      'duplicate_verified_effect_saved_evidence';

  elsif v_effect.effect_status <> 'planned'
  then
    v_status :=
      'blocked_a11_non_destructive_effect_not_planned';

  elsif v_effect.source_payload_hash is distinct from v_source_hash
  then
    v_status :=
      'blocked_a11_non_destructive_source_hash_mismatch';

  elsif v_config.allow_historical_reapply
        or v_config.allow_post_closeout_reapply
        or v_config.production_execution_enabled
        or coalesce(v_global.production_writer_execution_enabled,false)
        or coalesce(v_state.production_execution_enabled,false)
  then
    v_status :=
      'blocked_a11_non_destructive_production_contract_invalid';

  elsif not v_global_shadow_enabled
        or not v_state_shadow_enabled
        or not v_local_shadow_enabled
        or not v_allowed_shadow_effect
        or not v_a10_transition_shadow_enabled
  then
    v_status :=
      'blocked_a11_non_destructive_adapter_shadow_execution_disabled';

  else
    v_status :=
      'ready_for_a11_non_destructive_rollback_shadow_execution';
  end if;

  v_plan :=
    jsonb_build_object(
      'plan_version',
        'phase3ac_a11_non_destructive_stage_effect_plan_v1',

      'status',v_status,

      'registry_version',v_config.registry_version,
      'effect_order',v_config.effect_order,
      'effect_key',v_effect_key,

      'stage_id',v_stage_id,
      'race_id',v_stage_race_id,
      'simulation_run_id',v_stage_simulation_run_id,
      'simulation_status',v_stage_simulation_status,
      'route_format',v_route_format,

      'source_status',v_source_status,
      'source_payload_hash',v_source_hash,

      'output_status',v_output_status,
      'output_hash_key',v_config.output_hash_key,
      'current_output_payload_hash',v_output_hash,

      'writer_contract',
        jsonb_build_object(
          'signature',v_config.canonical_writer_signature,
          'expected_definition_hash',
            v_config.canonical_writer_definition_hash,
          'current_definition_hash',v_writer_hash,
          'definition_matches',
            v_writer_hash is not distinct from
            v_config.canonical_writer_definition_hash
        ),

      'source_evidence_contract',
        jsonb_build_object(
          'signature',v_config.source_evidence_signature,
          'expected_definition_hash',
            v_config.source_evidence_definition_hash,
          'current_definition_hash',v_source_function_hash,
          'definition_matches',
            v_source_function_hash is not distinct from
            v_config.source_evidence_definition_hash
        ),

      'output_evidence_contract',
        jsonb_build_object(
          'signature',v_config.output_evidence_signature,
          'expected_definition_hash',
            v_config.output_evidence_definition_hash,
          'current_definition_hash',v_output_function_hash,
          'definition_matches',
            v_output_function_hash is not distinct from
            v_config.output_evidence_definition_hash
        ),

      'source_evidence',v_source,
      'output_evidence',v_output,

      'process_run',
        jsonb_build_object(
          'requested_process_run_id',p_process_run_id,
          'found',v_process_found,
          'exact_active_identity',v_process_exact,
          'status',v_process.status,
          'finished_at',v_process.finished_at,
          'requested_dry_run',v_process.requested_dry_run,
          'linked_stage_id',v_process.stage_id,
          'linked_race_id',v_process.race_id,
          'linked_simulation_run_id',v_process.simulation_run_id
        ),

      'effect_ledger',
        case
          when not v_effect_found then null
          else jsonb_build_object(
            'effect_id',v_effect.effect_id,
            'effect_status',v_effect.effect_status,
            'source_payload_hash',v_effect.source_payload_hash,
            'applied_payload_hash',v_effect.applied_payload_hash,
            'idempotency_key',v_effect.idempotency_key,
            'metadata',v_effect.metadata
          )
        end,

      'prior_effects',v_prior_effects,
      'unsatisfied_prior_effect_count',v_unsatisfied_prior_count,
      'stage_closeout_effect_status',v_stage_closeout_status,

      'execution',
        jsonb_build_object(
          'global_shadow_execution_enabled',
            v_global_shadow_enabled,
          'effect_state_shadow_execution_enabled',
            v_state_shadow_enabled,
          'local_shadow_execution_enabled',
            v_local_shadow_enabled,
          'effect_allowed_for_shadow',
            v_allowed_shadow_effect,
          'a10_transition_shadow_execution_enabled',
            v_a10_transition_shadow_enabled,
          'production_writer_execution_enabled',
            false,
          'trigger_cutover_enabled',
            coalesce(v_global.trigger_cutover_enabled,false),
          'permission_cutover_enabled',
            coalesce(v_global.permission_cutover_enabled,false),
          'scheduler_cutover_enabled',
            coalesce(v_global.scheduler_cutover_enabled,false)
        ),

      'writer_execution_allowed',
        v_status =
        'ready_for_a11_non_destructive_rollback_shadow_execution',

      'duplicate_verified_effect',
        v_status =
        'duplicate_verified_effect_saved_evidence',

      'production_writer_execution_enabled',false
    );

  return
    v_plan
    ||
    jsonb_build_object(
      'plan_hash',md5(v_plan::text),
      'generated_at',clock_timestamp()
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_non_destructive_stage_effect_v2(p_stage_id uuid, p_process_run_id uuid, p_effect_key text, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_effect_key text :=
    lower(btrim(coalesce(p_effect_key,'')));

  v_plan jsonb;
  v_locked_plan jsonb;

  v_config
    public.race_engine_non_destructive_effect_adapter_config_v2%rowtype;

  v_transition_config
    public.race_engine_effect_immutable_config_v2%rowtype;

  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;

  v_writer_result jsonb;
  v_output jsonb;
  v_output_hash text;
  v_expected_output_statuses text[];

  v_simulation_run_id uuid;
  v_error_message text;
begin
  v_plan :=
    public.race_engine_get_non_destructive_stage_effect_plan_v2(
      p_stage_id,
      p_process_run_id,
      v_effect_key
    );

  if not coalesce(p_execute,false) then
    return jsonb_build_object(
      'status','a11_non_destructive_effect_plan_only_execution_disabled',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'plan',v_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan ->> 'status' =
     'historical_golden_fixture_verify_only'
  then
    return jsonb_build_object(
      'status','historical_golden_fixture_verify_only',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'rio_writer_calls',0,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan ->> 'status' =
     'duplicate_verified_effect_saved_evidence'
  then
    return jsonb_build_object(
      'status','duplicate_verified_effect_saved_evidence',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'saved_effect_evidence',v_plan -> 'effect_ledger',
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan ->> 'status' =
     'weather_cancelled_skip_normal_exposure'
  then
    return jsonb_build_object(
      'status','weather_cancelled_skip_normal_exposure',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan ->> 'status' =
     'blocked_a11_non_destructive_adapter_shadow_execution_disabled'
  then
    return jsonb_build_object(
      'status',
        'blocked_a11_non_destructive_adapter_shadow_execution_disabled',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'plan_status',v_plan ->> 'status',
      'confirmation_text_ignored',
        p_confirmation_text is not null,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  select *
  into v_config
  from public.race_engine_non_destructive_effect_adapter_config_v2 c
  where c.effect_key = v_effect_key;

  if v_config.effect_key is null then
    return jsonb_build_object(
      'status','blocked_non_destructive_effect_config_missing',
      'stage_id',p_stage_id,
      'effect_key',v_effect_key,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if md5(coalesce(p_confirmation_text,''))
     is distinct from v_config.required_confirmation_hash
  then
    return jsonb_build_object(
      'status',
        'blocked_a11_non_destructive_confirmation_mismatch',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan ->> 'status'
     is distinct from
     'ready_for_a11_non_destructive_rollback_shadow_execution'
  then
    return jsonb_build_object(
      'status','blocked_a11_non_destructive_plan_not_ready',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'plan',v_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      concat_ws(
        ':',
        'phase3ac_a11_non_destructive_effect',
        p_stage_id::text,
        v_effect_key
      ),
      0
    )
  );

  v_locked_plan :=
    public.race_engine_get_non_destructive_stage_effect_plan_v2(
      p_stage_id,
      p_process_run_id,
      v_effect_key
    );

  if v_locked_plan ->> 'status'
     is distinct from
     'ready_for_a11_non_destructive_rollback_shadow_execution'
     or v_locked_plan ->> 'source_payload_hash'
        is distinct from v_plan ->> 'source_payload_hash'
     or v_locked_plan ->> 'simulation_run_id'
        is distinct from v_plan ->> 'simulation_run_id'
  then
    return jsonb_build_object(
      'status',
        'blocked_a11_non_destructive_plan_changed_after_lock',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'effect_key',v_effect_key,
      'plan_before_lock',v_plan,
      'plan_after_lock',v_locked_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  select *
  into v_transition_config
  from public.race_engine_effect_immutable_config_v2 c
  where c.config_key = 'effect_immutable';

  if not coalesce(
           v_transition_config.transition_shadow_execution_enabled,
           false
         )
  then
    return jsonb_build_object(
      'status',
        'blocked_a11_non_destructive_a10_transition_shadow_disabled',
      'stage_id',p_stage_id,
      'effect_key',v_effect_key,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  v_simulation_run_id :=
    nullif(v_locked_plan ->> 'simulation_run_id','')::uuid;

  v_expected_output_statuses :=
    v_config.successful_output_statuses;

  begin
    v_started :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        v_effect_key,
        'started',
        null,
        jsonb_build_object(
          'a11_adapter_version',v_config.adapter_version,
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'writer_called',false
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_started ->> 'status'
       is distinct from 'effect_transition_applied_in_shadow_mode'
       or v_started ->> 'effect_status'
          is distinct from 'started'
    then
      raise exception
        'A11 non-destructive started transition failed: %',
        v_started;
    end if;

    if v_effect_key = 'weather_exposure' then
      v_writer_result :=
        public.race_engine_apply_rain_jacket_weather_exposure_v1(
          v_simulation_run_id,
          p_stage_id
        );

      v_output :=
        public.race_engine_get_stage_weather_exposure_output_evidence_v2(
          p_stage_id
        );
    elsif v_effect_key = 'fatigue' then
      v_writer_result :=
        public.race_engine_apply_stage_fatigue_v1(
          v_simulation_run_id
        );

      v_output :=
        public.race_engine_get_stage_fatigue_output_evidence_v2(
          p_stage_id
        );
    else
      raise exception
        'A11 non-destructive unknown effect key after lock: %',
        v_effect_key;
    end if;

    if not (
      v_output ->> 'status' = any(v_expected_output_statuses)
    ) then
      raise exception
        'A11 non-destructive output verification failed for %: %',
        v_effect_key,
        v_output ->> 'status';
    end if;

    v_output_hash :=
      nullif(v_output ->> v_config.output_hash_key,'');

    if v_output_hash is null then
      raise exception
        'A11 non-destructive output hash missing for %.',
        v_effect_key;
    end if;

    v_applied :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        v_effect_key,
        'applied',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',v_config.adapter_version,
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'writer_called',true,
          'writer_result',v_writer_result,
          'output_evidence',v_output
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_applied ->> 'status'
       is distinct from 'effect_transition_applied_in_shadow_mode'
       or v_applied ->> 'effect_status'
          is distinct from 'applied'
       or v_applied ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'A11 non-destructive applied transition failed: %',
        v_applied;
    end if;

    v_verified :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        v_effect_key,
        'verified',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',v_config.adapter_version,
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'writer_called',true,
          'output_verified',true
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_verified ->> 'status'
       is distinct from 'effect_transition_applied_in_shadow_mode'
       or v_verified ->> 'effect_status'
          is distinct from 'verified'
       or v_verified ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'A11 non-destructive verified transition failed: %',
        v_verified;
    end if;

  exception
    when others then
      v_error_message :=
        sqlstate || ': ' || sqlerrm;

      v_failed :=
        public.race_engine_transition_stage_effect_v2(
          p_stage_id,
          v_effect_key,
          'failed',
          null,
          jsonb_build_object(
            'a11_adapter_version',v_config.adapter_version,
            'process_run_id',p_process_run_id,
            'execution_mode','rollback_shadow_only',
            'writer_or_verification_error',v_error_message,
            'error_message',v_error_message
          ),
          true,
          'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
        );

      return jsonb_build_object(
        'status',
          'a11_non_destructive_effect_failed_in_shadow_mode',
        'stage_id',p_stage_id,
        'process_run_id',p_process_run_id,
        'effect_key',v_effect_key,
        'error_message',v_error_message,
        'failed_transition',v_failed,
        'canonical_writer_called',
          v_started ->> 'effect_status' = 'started',
        'writer_mutations_from_failed_inner_block_rolled_back',true,
        'production_writer_execution_enabled',false
      );
  end;

  return jsonb_build_object(
    'status',
      'a11_non_destructive_effect_applied_and_verified_in_shadow_mode',

    'stage_id',p_stage_id,
    'race_id',v_locked_plan ->> 'race_id',
    'simulation_run_id',v_simulation_run_id,
    'process_run_id',p_process_run_id,

    'effect_key',v_effect_key,
    'effect_order',v_config.effect_order,

    'source_payload_hash',
      v_locked_plan ->> 'source_payload_hash',

    'applied_payload_hash',v_output_hash,

    'writer_result',v_writer_result,
    'output_evidence',v_output,

    'started_transition',v_started,
    'applied_transition',v_applied,
    'verified_transition',v_verified,

    'canonical_writer_called',true,
    'effect_transition_count',3,

    'execution_mode','rollback_shadow_only',
    'production_writer_execution_enabled',false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_non_destructive_stage_effect_plan_v2(p_stage_id uuid, p_process_run_id uuid, p_effect_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_effect_key text :=
    lower(btrim(coalesce(p_effect_key,'')));

  v_base jsonb;
  v_adapter_plan jsonb;
  v_adapter jsonb;

  v_local
    public.race_engine_non_destructive_effect_adapter_config_v2%rowtype;

  v_global
    public.race_engine_effect_adapter_execution_config_v2%rowtype;

  v_state
    public.race_engine_effect_adapter_execution_state_v2%rowtype;

  v_transition
    public.race_engine_effect_immutable_config_v2%rowtype;

  v_status text;
  v_evidence_hash text;
  v_canonical_hash text;
  v_reserved_hash text;
  v_ledger_status text;
  v_applied_hash text;
  v_result jsonb;
begin
  v_base :=
    public.race_engine_get_non_destructive_stage_effect_plan_raw_v2(
      p_stage_id,
      p_process_run_id,
      v_effect_key
    );

  if p_stage_id is null
     or v_effect_key not in ('weather_exposure','fatigue')
  then
    return
      v_base
      ||
      jsonb_build_object(
        'source_contract_version',
          'phase3ac_a11_reserved_source_contract_alignment_v1',
        'production_writer_execution_enabled',false
      );
  end if;

  v_adapter_plan :=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(
      p_stage_id
    );

  select a.value
  into v_adapter
  from jsonb_array_elements(
         coalesce(v_adapter_plan -> 'adapters','[]'::jsonb)
       ) a(value)
  where a.value ->> 'effect_key' = v_effect_key
  limit 1;

  v_evidence_hash :=
    nullif(v_base ->> 'source_payload_hash','');

  v_canonical_hash :=
    nullif(v_adapter ->> 'source_payload_hash','');

  v_reserved_hash :=
    nullif(
      v_base -> 'effect_ledger' ->> 'source_payload_hash',
      ''
    );

  v_ledger_status :=
    nullif(
      v_base -> 'effect_ledger' ->> 'effect_status',
      ''
    );

  v_applied_hash :=
    nullif(
      v_base -> 'effect_ledger' ->> 'applied_payload_hash',
      ''
    );

  v_status := v_base ->> 'status';

  if v_adapter is null then
    v_status :=
      'blocked_a11_non_destructive_canonical_adapter_missing';

  elsif v_canonical_hash is null then
    v_status :=
      'blocked_a11_non_destructive_canonical_source_hash_missing';

  elsif v_status in
        (
          'blocked_invalid_non_destructive_effect_input',
          'blocked_non_destructive_effect_config_missing',
          'stage_not_found',
          'blocked_a11_non_destructive_registry_or_execution_state_missing',
          'blocked_a11_non_destructive_registry_contract_mismatch',
          'blocked_a11_non_destructive_definition_drift',
          'historical_golden_fixture_verify_only',
          'blocked_a11_non_destructive_simulation_run_not_completed',
          'blocked_a11_non_destructive_route_not_supported',
          'weather_cancelled_skip_normal_exposure',
          'blocked_a11_non_destructive_source_not_ready',
          'blocked_a11_non_destructive_source_hash_missing',
          'blocked_a11_non_destructive_stage_closeout_exists',
          'blocked_a11_non_destructive_prior_effects_unsatisfied',
          'blocked_a11_non_destructive_process_run_required',
          'blocked_a11_non_destructive_process_run_identity_mismatch',
          'blocked_a11_non_destructive_effect_reservation_required'
        )
  then
    null;

  elsif v_reserved_hash is distinct from v_canonical_hash then
    v_status :=
      'blocked_a11_non_destructive_reserved_source_hash_mismatch';

  elsif v_ledger_status = 'verified'
        and v_applied_hash is not null
  then
    v_status :=
      'duplicate_verified_effect_saved_evidence';

  elsif v_ledger_status is distinct from 'planned'
  then
    v_status :=
      'blocked_a11_non_destructive_effect_not_planned';

  else
    select *
    into v_local
    from public.race_engine_non_destructive_effect_adapter_config_v2
    where effect_key = v_effect_key;

    select *
    into v_global
    from public.race_engine_effect_adapter_execution_config_v2
    where config_key = 'ordered_effect_adapters';

    select *
    into v_state
    from public.race_engine_effect_adapter_execution_state_v2
    where registry_version =
          'phase3ac_a11_ordered_effect_adapter_registry_v1'
      and effect_key = v_effect_key;

    select *
    into v_transition
    from public.race_engine_effect_immutable_config_v2
    where config_key = 'effect_immutable';

    if coalesce(v_local.production_execution_enabled,false)
       or coalesce(v_global.production_writer_execution_enabled,false)
       or coalesce(v_state.production_execution_enabled,false)
       or coalesce(v_local.allow_historical_reapply,false)
       or coalesce(v_local.allow_post_closeout_reapply,false)
    then
      v_status :=
        'blocked_a11_non_destructive_production_contract_invalid';

    elsif not coalesce(
                v_global.adapter_shadow_execution_enabled,
                false
              )
          or not coalesce(v_state.shadow_execution_enabled,false)
          or not coalesce(v_local.shadow_execution_enabled,false)
          or not (
            v_effect_key = any(
              coalesce(
                v_global.allowed_shadow_effect_keys,
                '{}'::text[]
              )
            )
          )
          or not coalesce(
            v_transition.transition_shadow_execution_enabled,
            false
          )
    then
      v_status :=
        'blocked_a11_non_destructive_adapter_shadow_execution_disabled';

    else
      v_status :=
        'ready_for_a11_non_destructive_rollback_shadow_execution';
    end if;
  end if;

  v_result :=
    (
      v_base
      - 'status'
      - 'source_payload_hash'
      - 'plan_hash'
      - 'generated_at'
    )
    ||
    jsonb_build_object(
      'plan_version',
        'phase3ac_a11_non_destructive_stage_effect_plan_v3',

      'source_contract_version',
        'phase3ac_a11_reserved_source_contract_alignment_v1',

      'status',v_status,

      'source_payload_hash',v_canonical_hash,
      'canonical_reserved_source_payload_hash',v_canonical_hash,
      'evidence_source_payload_hash',v_evidence_hash,
      'reserved_source_payload_hash',v_reserved_hash,

      'source_contract_matches',
        v_reserved_hash is null
        or v_reserved_hash = v_canonical_hash,

      'canonical_adapter_contract',
        jsonb_build_object(
          'adapter_plan_status',
            v_adapter_plan ->> 'status',
          'adapter_plan_hash',
            v_adapter_plan ->> 'plan_hash',
          'effect_key',v_effect_key,
          'effect_order',v_adapter ->> 'adapter_order',
          'required_for_route',
            v_adapter ->> 'required_for_route',
          'canonical_source_payload_hash',v_canonical_hash,
          'raw_evidence_source_payload_hash',v_evidence_hash
        ),

      'writer_execution_allowed',
        v_status =
        'ready_for_a11_non_destructive_rollback_shadow_execution',

      'duplicate_verified_effect',
        v_status =
        'duplicate_verified_effect_saved_evidence',

      'production_writer_execution_enabled',false
    );

  return
    v_result
    ||
    jsonb_build_object(
      'plan_hash',md5(v_result::text),
      'generated_at',clock_timestamp()
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_daily_activity_ordered_plan_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_projection jsonb;
  v_output jsonb;
  v_ownership jsonb;
  v_adapter_plan jsonb;
  v_adapter jsonb;

  v_config
    public.race_engine_daily_activity_ordered_adapter_config_v2%rowtype;
  v_global
    public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state
    public.race_engine_effect_adapter_execution_state_v2%rowtype;
  v_transition
    public.race_engine_effect_immutable_config_v2%rowtype;
  v_process
    public.race_engine_stage_process_runs_v2%rowtype;
  v_effect
    public.race_engine_stage_effect_ledger_v2%rowtype;

  v_process_found boolean := false;
  v_exact_process boolean := false;
  v_effect_found boolean := false;

  v_canonical_hash text;
  v_raw_hash text;
  v_output_hash text;
  v_closeout_status text;

  v_dependencies jsonb := '[]'::jsonb;
  v_unsatisfied integer := 0;
  v_status text;
  v_result jsonb;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status','blocked_daily_activity_stage_id_required',
      'production_execution_enabled',false
    );
  end if;

  select * into v_config
  from public.race_engine_daily_activity_ordered_adapter_config_v2
  where config_key='daily_activity';

  select * into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key='ordered_effect_adapters';

  select * into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key='daily_activity';

  select * into v_transition
  from public.race_engine_effect_immutable_config_v2
  where config_key='effect_immutable';

  v_projection :=
    public.race_engine_get_stage_daily_activity_projection_v2(p_stage_id);
  v_output :=
    public.race_engine_get_stage_daily_activity_output_evidence_v2(p_stage_id);
  v_ownership :=
    public.race_engine_get_daily_activity_trigger_ownership_v2();

  v_adapter_plan :=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(p_stage_id);

  select a.value into v_adapter
  from jsonb_array_elements(
         coalesce(v_adapter_plan->'adapters','[]'::jsonb)
       ) a(value)
  where a.value->>'effect_key'='daily_activity'
  limit 1;

  v_canonical_hash := nullif(v_adapter->>'source_payload_hash','');
  v_raw_hash := nullif(v_projection->>'projection_hash','');
  v_output_hash := nullif(v_output->>'comparison_hash','');

  if p_process_run_id is not null then
    select * into v_process
    from public.race_engine_stage_process_runs_v2
    where process_run_id=p_process_run_id;

    v_process_found := found;

    if v_process_found then
      v_exact_process :=
        v_process.stage_id=p_stage_id
        and v_process.race_id =
            nullif(v_projection->>'race_id','')::uuid
        and v_process.status='started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run
        and v_process.simulation_run_id is not null;
    end if;
  end if;

  select * into v_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id=p_stage_id
    and effect_key='daily_activity';

  v_effect_found := found;

  select effect_status into v_closeout_status
  from public.race_engine_stage_effect_ledger_v2
  where stage_id=p_stage_id
    and effect_key='stage_closeout';

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'effect_key',r.effect_key,
          'effect_order',r.effect_order,
          'effect_status',coalesce(e.effect_status,'missing'),
          'dependency_satisfied',e.effect_status='verified'
        )
        order by r.effect_order
      ),
      '[]'::jsonb
    ),
    count(*) filter(
      where e.effect_status is distinct from 'verified'
    )::integer
  into v_dependencies,v_unsatisfied
  from public.race_engine_effect_adapter_registry_v2 r
  left join public.race_engine_stage_effect_ledger_v2 e
    on e.stage_id=p_stage_id
   and e.effect_key=r.effect_key
  where r.registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and r.effect_order < 5;

  if exists
     (
       select 1
       from public.race_engine_golden_stage_fixture_v1
       where stage_id=p_stage_id
         and fixture_status='frozen_and_validated'
     )
  then
    v_status := 'historical_golden_fixture_verify_only';

  elsif v_projection->>'status' <> 'projection_ready' then
    v_status := 'source_not_ready_for_daily_activity';

  elsif v_output->>'status' <>
        'daily_activity_projection_complete'
  then
    v_status := 'blocked_daily_activity_projection_not_complete';

  elsif v_ownership->>'status' <>
        'legacy_result_insert_trigger_active'
  then
    v_status := 'blocked_daily_activity_trigger_owner_unexpected';

  elsif not v_exact_process
        and v_projection->>'stage_process_status' =
            'verify_only_no_execution'
  then
    v_status := 'historical_trigger_projection_verify_only';

  elsif v_closeout_status is not null then
    v_status := 'blocked_stage_closeout_effect_exists';

  elsif v_unsatisfied > 0 then
    v_status := 'blocked_daily_activity_prior_effects_unsatisfied';

  elsif not v_process_found then
    v_status := 'blocked_daily_activity_process_run_required';

  elsif not v_exact_process then
    v_status := 'blocked_daily_activity_process_identity_mismatch';

  elsif not v_effect_found then
    v_status := 'blocked_daily_activity_effect_reservation_required';

  elsif v_effect.source_payload_hash
        is distinct from v_canonical_hash
  then
    v_status := 'blocked_daily_activity_reserved_source_hash_mismatch';

  elsif v_effect.effect_status='verified'
        and v_effect.applied_payload_hash is not null
  then
    v_status := 'duplicate_verified_effect_saved_evidence';

  elsif v_effect.effect_status <> 'planned' then
    v_status := 'blocked_daily_activity_effect_not_planned';

  elsif coalesce(v_config.production_execution_enabled,false)
        or coalesce(v_global.production_writer_execution_enabled,false)
        or coalesce(v_state.production_execution_enabled,false)
        or coalesce(v_global.trigger_cutover_enabled,false)
        or coalesce(v_state.trigger_cutover_enabled,false)
        or coalesce(v_config.allow_trigger_cutover,false)
  then
    v_status := 'blocked_daily_activity_production_contract_invalid';

  elsif not coalesce(v_config.shadow_execution_enabled,false)
        or not coalesce(v_global.adapter_shadow_execution_enabled,false)
        or not coalesce(v_state.shadow_execution_enabled,false)
        or not (
          'daily_activity' = any(
            coalesce(v_global.allowed_shadow_effect_keys,'{}'::text[])
          )
        )
        or not coalesce(
          v_transition.transition_shadow_execution_enabled,
          false
        )
  then
    v_status := 'blocked_daily_activity_shadow_execution_disabled';

  else
    v_status :=
      'ready_for_daily_activity_trigger_projection_verification_shadow';
  end if;

  v_result := jsonb_build_object(
    'plan_version',
      'phase3ac_a11_daily_activity_ordered_plan_v1',
    'status',v_status,
    'stage_id',p_stage_id,
    'race_id',v_projection->>'race_id',
    'simulation_run_id',
      case
        when v_process_found then v_process.simulation_run_id
        else null
      end,
    'process_run_id',p_process_run_id,
    'route_format',v_projection->>'route_format',
    'stage_process_status',
      v_projection->>'stage_process_status',

    'canonical_source_payload_hash',v_canonical_hash,
    'raw_projection_hash',v_raw_hash,
    'current_output_payload_hash',v_output_hash,

    'projection',v_projection,
    'output_evidence',v_output,
    'trigger_ownership',v_ownership,

    'dependencies',v_dependencies,
    'unsatisfied_prior_effect_count',v_unsatisfied,

    'process_run',jsonb_build_object(
      'found',v_process_found,
      'exact_active_identity',v_exact_process
    ),

    'effect_ledger',
      case
        when v_effect_found then
          jsonb_build_object(
            'effect_id',v_effect.effect_id,
            'effect_status',v_effect.effect_status,
            'source_payload_hash',v_effect.source_payload_hash,
            'applied_payload_hash',v_effect.applied_payload_hash
          )
        else null
      end,

    'verification_transition_allowed',
      v_status =
      'ready_for_daily_activity_trigger_projection_verification_shadow',

    'canonical_activity_writer_called',false,
    'legacy_trigger_cutover_enabled',false,
    'production_execution_enabled',false
  );

  return v_result || jsonb_build_object(
    'plan_hash',md5(v_result::text),
    'generated_at',clock_timestamp()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_daily_activity_ordered_adapter_v2(p_stage_id uuid, p_process_run_id uuid, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan jsonb;
  v_locked_plan jsonb;
  v_config
    public.race_engine_daily_activity_ordered_adapter_config_v2%rowtype;

  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;

  v_output jsonb;
  v_output_hash text;
  v_error text;
begin
  v_plan :=
    public.race_engine_get_daily_activity_ordered_plan_v2(
      p_stage_id,p_process_run_id
    );

  if not coalesce(p_execute,false) then
    return jsonb_build_object(
      'status','dry_run_daily_activity_ordered_plan',
      'stage_id',p_stage_id,
      'plan',v_plan,
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_plan->>'status' in
     (
       'historical_golden_fixture_verify_only',
       'historical_trigger_projection_verify_only'
     )
  then
    return jsonb_build_object(
      'status',v_plan->>'status',
      'stage_id',p_stage_id,
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_plan->>'status' <>
     'ready_for_daily_activity_trigger_projection_verification_shadow'
  then
    return jsonb_build_object(
      'status',v_plan->>'status',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  select * into v_config
  from public.race_engine_daily_activity_ordered_adapter_config_v2
  where config_key='daily_activity';

  if md5(coalesce(p_confirmation_text,'')) is distinct from
     v_config.required_confirmation_hash
  then
    return jsonb_build_object(
      'status','blocked_daily_activity_confirmation_mismatch',
      'stage_id',p_stage_id,
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'phase3ac:a11:stage-effect:' || p_stage_id::text,
      0
    )
  );

  v_locked_plan :=
    public.race_engine_get_daily_activity_ordered_plan_v2(
      p_stage_id,p_process_run_id
    );

  if v_locked_plan->>'status' =
     'duplicate_verified_effect_saved_evidence'
  then
    return jsonb_build_object(
      'status','duplicate_verified_effect_saved_evidence',
      'stage_id',p_stage_id,
      'effect_key','daily_activity',
      'process_run_id',p_process_run_id,
      'saved_effect_evidence',v_locked_plan->'effect_ledger',
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_locked_plan->>'status' <>
     'ready_for_daily_activity_trigger_projection_verification_shadow'
  then
    return jsonb_build_object(
      'status','blocked_daily_activity_plan_changed_after_lock',
      'stage_id',p_stage_id,
      'plan_after_lock',v_locked_plan,
      'canonical_activity_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  begin
    v_started :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'daily_activity',
        'started',
        null,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_daily_activity_trigger_projection_bridge_v1',
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'current_owner','legacy_result_insert_trigger',
          'writer_called',false
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_started->>'status' <>
       'effect_transition_applied_in_shadow_mode'
       or v_started->>'effect_status' <> 'started'
    then
      raise exception
        'Daily activity started transition failed: %',v_started;
    end if;

    v_output :=
      public.race_engine_get_stage_daily_activity_output_evidence_v2(
        p_stage_id
      );

    if v_output->>'status' <>
       'daily_activity_projection_complete'
    then
      raise exception
        'Daily activity output verification failed: %',v_output;
    end if;

    v_output_hash := nullif(v_output->>'comparison_hash','');

    if v_output_hash is null then
      raise exception
        'Daily activity comparison hash missing.';
    end if;

    v_applied :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'daily_activity',
        'applied',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_daily_activity_trigger_projection_bridge_v1',
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'current_owner','legacy_result_insert_trigger',
          'writer_called',false,
          'trigger_projection_verified',true,
          'output_evidence',v_output
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_applied->>'status' <>
       'effect_transition_applied_in_shadow_mode'
       or v_applied->>'effect_status' <> 'applied'
       or v_applied->>'applied_payload_hash' <> v_output_hash
    then
      raise exception
        'Daily activity applied transition failed: %',v_applied;
    end if;

    v_verified :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'daily_activity',
        'verified',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_daily_activity_trigger_projection_bridge_v1',
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'current_owner','legacy_result_insert_trigger',
          'writer_called',false,
          'output_verified',true
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_verified->>'status' <>
       'effect_transition_applied_in_shadow_mode'
       or v_verified->>'effect_status' <> 'verified'
       or v_verified->>'applied_payload_hash' <> v_output_hash
    then
      raise exception
        'Daily activity verified transition failed: %',v_verified;
    end if;

  exception
    when others then
      v_error := sqlstate || ': ' || sqlerrm;

      v_failed :=
        public.race_engine_transition_stage_effect_v2(
          p_stage_id,
          'daily_activity',
          'failed',
          null,
          jsonb_build_object(
            'a11_adapter_version',
              'phase3ac_a11_daily_activity_trigger_projection_bridge_v1',
            'process_run_id',p_process_run_id,
            'execution_mode','rollback_shadow_only',
            'writer_called',false,
            'error_message',v_error
          ),
          true,
          'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
        );

      return jsonb_build_object(
        'status',
          'daily_activity_trigger_projection_verification_failed_in_shadow_mode',
        'stage_id',p_stage_id,
        'process_run_id',p_process_run_id,
        'error_message',v_error,
        'failed_transition',v_failed,
        'canonical_activity_writer_called',false,
        'inner_mutations_rolled_back',true,
        'production_execution_enabled',false
      );
  end;

  return jsonb_build_object(
    'status',
      'daily_activity_trigger_projection_verified_in_shadow_mode',
    'stage_id',p_stage_id,
    'process_run_id',p_process_run_id,
    'effect_key','daily_activity',
    'source_payload_hash',
      v_locked_plan->>'canonical_source_payload_hash',
    'applied_payload_hash',v_output_hash,
    'output_evidence',v_output,
    'started_transition',v_started,
    'applied_transition',v_applied,
    'verified_transition',v_verified,
    'canonical_activity_writer_called',false,
    'trigger_projection_verified',true,
    'effect_transition_count',3,
    'production_execution_enabled',false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.advance_game_state_one_minute_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_season integer;
  v_old_month integer;
  v_old_day integer;
  v_old_hour integer;
  v_old_minute integer;
  v_old_tick bigint;
  v_old_ts timestamptz;
  v_new_ts timestamptz;
  v_old_date date;
  v_new_date date;
  v_days_crossed integer := 0;
  v_gate jsonb;
begin
  select
    gs.season_number,
    gs.month_number::integer,
    gs.day_number::integer,
    coalesce(gs.hour_number, 0)::integer,
    coalesce(gs.minute_number, 0)::integer,
    gs.tick_version
  into
    v_old_season,
    v_old_month,
    v_old_day,
    v_old_hour,
    v_old_minute,
    v_old_tick
  from public.game_state gs
  where gs.id = true
  for update;

  if not found then
    raise exception 'game_state is not initialized';
  end if;

  v_old_ts := make_timestamptz(
    1999 + v_old_season,
    v_old_month,
    v_old_day,
    v_old_hour,
    v_old_minute,
    0,
    'UTC'
  );

  v_new_ts := v_old_ts + interval '1 minute';
  v_old_date := v_old_ts::date;
  v_new_date := v_new_ts::date;
  v_days_crossed := greatest(0, v_new_date - v_old_date);

  if public.season_from_game_date(v_new_date) > public.season_from_game_date(v_old_date) then
    v_gate := public.season_transition_boundary_gate_v1(v_old_date, v_new_date);
    if not coalesce((v_gate ->> 'allowed')::boolean, false) then
      return jsonb_build_object(
        'status', 'blocked_season_transition',
        'old_game_timestamp', v_old_ts,
        'candidate_new_game_timestamp', v_new_ts,
        'transition_gate', v_gate
      );
    end if;
  end if;

  if v_new_date > v_old_date then
    insert into public.game_daily_tick_backlog_v1 (
      current_game_date,
      season_number,
      month_number,
      day_number,
      tick_version,
      status,
      source,
      payload
    )
    values (
      v_new_date,
      public.season_from_game_date(v_new_date),
      extract(month from v_new_date)::int,
      extract(day from v_new_date)::int,
      coalesce(v_old_tick, 0) + 1,
      'pending',
      'minute_clock_tick_v1',
      jsonb_build_object(
        'reason', 'daily processors deferred from minute clock tick',
        'old_clock_date', v_old_date,
        'new_clock_date', v_new_date,
        'old_clock_ts', v_old_ts,
        'new_clock_ts', v_new_ts,
        'created_by', 'advance_game_state_one_minute_v1',
        'created_at', now()
      )
    )
    on conflict (current_game_date) do update
    set
      status = case
        when public.game_daily_tick_backlog_v1.status = 'processed'
          then public.game_daily_tick_backlog_v1.status
        else 'pending'
      end,
      updated_at = now(),
      payload = public.game_daily_tick_backlog_v1.payload
        || excluded.payload
        || jsonb_build_object('touched_by_minute_clock_tick_v1_at', now());
  end if;

  update public.game_state
  set
    season_number = public.season_from_game_date(v_new_ts::date),
    month_number = extract(month from v_new_ts)::smallint,
    day_number = extract(day from v_new_ts)::smallint,
    hour_number = extract(hour from v_new_ts)::smallint,
    minute_number = extract(minute from v_new_ts)::smallint,
    tick_version = coalesce(v_old_tick, 0) + v_days_crossed,
    last_advanced_at = now()
  where id = true;

  return jsonb_build_object(
    'status', 'advanced_one_game_minute',
    'old_game_timestamp', v_old_ts,
    'new_game_timestamp', v_new_ts,
    'days_crossed', v_days_crossed
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_game_minute_tick_if_unpaused_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_state_paused boolean := true;
  v_config_paused boolean := true;
  v_result jsonb;
  v_old_ts timestamptz;
  v_new_ts timestamptz;
  v_crossed_season boolean := false;
  v_paused_after_transition boolean := false;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.run_game_minute_tick_if_unpaused_v1')::bigint) then
    return jsonb_build_object('status', 'skipped_already_running');
  end if;

  select coalesce(is_paused, true)
  into v_state_paused
  from public.game_state
  where id = true;

  select coalesce(is_paused, true)
  into v_config_paused
  from public.game_clock_config
  where id = true;

  if coalesce(v_state_paused, true) or coalesce(v_config_paused, true) then
    return jsonb_build_object(
      'status', 'skipped_paused',
      'game_state_paused', v_state_paused,
      'game_clock_config_paused', v_config_paused
    );
  end if;

  select public.advance_game_state_one_minute_v1()
  into v_result;

  if coalesce(v_result ->> 'status', '') = 'blocked_season_transition' then
    return jsonb_build_object(
      'status', 'blocked_season_transition',
      'tick_result', v_result,
      'current_game_timestamp', public.get_current_game_timestamp()
    );
  end if;

  v_old_ts := nullif(v_result ->> 'old_game_timestamp', '')::timestamptz;
  v_new_ts := nullif(v_result ->> 'new_game_timestamp', '')::timestamptz;

  if v_old_ts is not null and v_new_ts is not null then
    v_crossed_season :=
      public.season_from_game_date(v_new_ts::date)
      > public.season_from_game_date(v_old_ts::date);
  end if;

  if v_crossed_season then
    perform public.run_season_reset_if_due();

    select coalesce(gs.is_paused, false)
    into v_paused_after_transition
    from public.game_state gs
    where gs.id = true;

    if v_paused_after_transition then
      return jsonb_build_object(
        'status', 'season_transition_failed_clock_paused',
        'tick_result', v_result,
        'transition_status', public.get_season_transition_status_v1(),
        'current_game_timestamp', public.get_current_game_timestamp()
      );
    end if;
  end if;

  perform public.process_due_game_events();

  if extract(minute from public.get_current_game_timestamp())::int = 0 then
    if not v_crossed_season then
      perform public.run_season_reset_if_due();
    end if;
    perform public.complete_due_rider_scout_tasks();
    perform public.run_hourly_game_processors_v1(false);
  end if;

  return jsonb_build_object(
    'status', 'completed',
    'tick_result', v_result,
    'crossed_season', v_crossed_season,
    'current_game_timestamp', public.get_current_game_timestamp()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_verify_golden_stage_fixture_raw_v1(p_fixture_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_fixture record;
  v_relation record;

  v_current_row_count bigint;
  v_current_relation_hash text;

  v_current_total_rows bigint := 0;
  v_current_overall_input text := '';

  v_current_overall_hash text;

  v_all_relations_match boolean := true;

  v_relation_results jsonb := '[]'::jsonb;
begin
  select fixture.*
  into v_fixture
  from public.race_engine_golden_stage_fixture_v1 fixture
  where fixture.fixture_key = p_fixture_key;

  if not found then
    return jsonb_build_object(
      'status',
        'fixture_not_found',

      'fixture_key',
        p_fixture_key
    );
  end if;

  for v_relation in
    select fixture_relation.*
    from public.race_engine_golden_stage_fixture_relation_v1
         fixture_relation

    where fixture_relation.fixture_id =
          v_fixture.fixture_id

    order by fixture_relation.relation_order
  loop
    execute format(
      $sql$
        select
          count(*)::bigint,

          md5(
            coalesce(
              string_agg(
                to_jsonb(source_row)::text,
                '|'
                order by to_jsonb(source_row)::text
              ),
              ''
            )
          )

        from
        (
          %s
        ) source_row
      $sql$,
      v_relation.source_query_sql
    )
    into
      v_current_row_count,
      v_current_relation_hash;

    v_current_total_rows :=
      v_current_total_rows +
      v_current_row_count;

    v_current_overall_input :=
      v_current_overall_input
      ||
      case
        when v_current_overall_input = ''
          then ''
        else '||'
      end
      ||
      concat_ws(
        ':',
        v_relation.relation_order::text,
        v_relation.relation_key,
        v_current_row_count::text,
        v_current_relation_hash
      );

    if v_current_row_count is distinct from
       v_relation.row_count

       or v_current_relation_hash is distinct from
          v_relation.relation_hash then

      v_all_relations_match := false;
    end if;

    v_relation_results :=
      v_relation_results
      ||
      jsonb_build_array(
        jsonb_build_object(
          'relation_order',
            v_relation.relation_order,

          'relation_key',
            v_relation.relation_key,

          'expected_row_count',
            v_relation.row_count,

          'current_row_count',
            v_current_row_count,

          'row_count_matches',
            v_current_row_count =
            v_relation.row_count,

          'expected_relation_hash',
            v_relation.relation_hash,

          'current_relation_hash',
            v_current_relation_hash,

          'relation_hash_matches',
            v_current_relation_hash =
            v_relation.relation_hash,

          'relation_matches',
            (
              v_current_row_count =
              v_relation.row_count

              and v_current_relation_hash =
                  v_relation.relation_hash
            )
        )
      );
  end loop;

  v_current_overall_hash :=
    md5(v_current_overall_input);

  return jsonb_build_object(
    'verification_name',
      'race_engine_verify_golden_stage_fixture_v1',

    'status',
      case
        when v_all_relations_match
         and v_current_overall_hash =
             v_fixture.overall_fixture_hash
          then 'fixture_matches_current_state'
        else 'fixture_mismatch'
      end,

    'fixture_id',
      v_fixture.fixture_id,

    'fixture_key',
      v_fixture.fixture_key,

    'race_id',
      v_fixture.race_id,

    'stage_id',
      v_fixture.stage_id,

    'simulation_run_id',
      v_fixture.simulation_run_id,

    'fixture_version',
      v_fixture.fixture_version,

    'expected_relation_count',
      v_fixture.relation_count,

    'verified_relation_count',
      jsonb_array_length(v_relation_results),

    'expected_total_snapshot_rows',
      v_fixture.total_snapshot_rows,

    'current_total_snapshot_rows',
      v_current_total_rows,

    'expected_overall_fixture_hash',
      v_fixture.overall_fixture_hash,

    'current_overall_fixture_hash',
      v_current_overall_hash,

    'all_relations_match',
      v_all_relations_match,

    'overall_hash_matches',
      v_current_overall_hash =
      v_fixture.overall_fixture_hash,

    'relation_results',
      v_relation_results,

    'verified_at',
      clock_timestamp()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_weather_closeout_ordered_plan_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stage public.race_stages%rowtype;
  v_run public.race_stage_simulation_runs%rowtype;
  v_process public.race_engine_stage_process_runs_v2%rowtype;
  v_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_config
    public.race_engine_weather_closeout_ordered_adapter_config_v2%rowtype;
  v_global
    public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state
    public.race_engine_effect_adapter_execution_state_v2%rowtype;
  v_transition public.race_engine_effect_immutable_config_v2%rowtype;

  v_projection jsonb;
  v_output jsonb;
  v_ownership jsonb;
  v_adapter_plan jsonb;
  v_adapter jsonb;
  v_dependencies jsonb:='[]'::jsonb;

  v_process_found boolean:=false;
  v_exact_process boolean:=false;
  v_effect_found boolean:=false;
  v_unsatisfied integer:=0;

  v_source_hash text;
  v_output_hash text;
  v_status text;
  v_result jsonb;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status','blocked_weather_closeout_stage_id_required',
      'production_execution_enabled',false
    );
  end if;

  select * into v_stage
  from public.race_stages
  where id=p_stage_id;

  if not found then
    return jsonb_build_object(
      'status','blocked_weather_closeout_stage_not_found',
      'stage_id',p_stage_id,
      'production_execution_enabled',false
    );
  end if;

  if not coalesce(v_stage.weather_cancelled,false) then
    return jsonb_build_object(
      'status','source_not_ready_for_weather_closeout',
      'stage_id',p_stage_id,
      'race_id',v_stage.race_id,
      'reason','stage_not_weather_cancelled',
      'production_execution_enabled',false
    );
  end if;

  select * into v_run
  from public.race_stage_simulation_runs
  where stage_id=p_stage_id
    and status='completed'
    and engine_version='weather_cancellation_v1'
    and simulation_mode='weather_cancelled_no_simulation'
  order by coalesce(completed_at,updated_at,created_at) desc,id desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'status','source_not_ready_for_weather_closeout',
      'stage_id',p_stage_id,
      'race_id',v_stage.race_id,
      'reason','completed_weather_cancellation_run_missing',
      'production_execution_enabled',false
    );
  end if;

  select * into v_config
  from public.race_engine_weather_closeout_ordered_adapter_config_v2
  where config_key='weather_closeout';

  select * into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key='ordered_effect_adapters';

  select * into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version=
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key='weather_closeout';

  select * into v_transition
  from public.race_engine_effect_immutable_config_v2
  where config_key='effect_immutable';

  v_projection:=
    public.race_engine_get_weather_closeout_projection_v2(v_stage.race_id);
  v_output:=
    public.race_engine_get_weather_closeout_output_evidence_v2(v_stage.race_id);
  v_ownership:=
    public.race_engine_get_weather_closeout_trigger_ownership_v2();
  v_adapter_plan:=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(p_stage_id);

  select a.value into v_adapter
  from jsonb_array_elements(
    coalesce(v_adapter_plan->'adapters','[]'::jsonb)
  ) a(value)
  where a.value->>'effect_key'='weather_closeout'
  limit 1;

  v_source_hash:=nullif(v_adapter->>'source_payload_hash','');
  v_output_hash:=md5(v_output::text);

  if p_process_run_id is not null then
    select * into v_process
    from public.race_engine_stage_process_runs_v2
    where process_run_id=p_process_run_id;

    v_process_found:=found;

    if v_process_found then
      v_exact_process:=
        v_process.stage_id=p_stage_id
        and v_process.race_id=v_stage.race_id
        and v_process.simulation_run_id=v_run.id
        and v_process.status='started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run
        and not v_process.production_execution_enabled;
    end if;
  end if;

  select * into v_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id=p_stage_id
    and effect_key='weather_closeout';

  v_effect_found:=found;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'effect_key',a.value->>'effect_key',
          'effect_order',(a.value->>'adapter_order')::integer,
          'effect_status',coalesce(e.effect_status,'missing'),
          'dependency_satisfied',e.effect_status='verified'
        )
        order by (a.value->>'adapter_order')::integer
      ),
      '[]'::jsonb
    ),
    count(*) filter(
      where e.effect_status is distinct from 'verified'
    )::integer
  into v_dependencies,v_unsatisfied
  from jsonb_array_elements(
    coalesce(v_adapter_plan->'adapters','[]'::jsonb)
  ) a(value)
  left join public.race_engine_stage_effect_ledger_v2 e
    on e.stage_id=p_stage_id
   and e.effect_key=a.value->>'effect_key'
  where coalesce(
          (a.value->>'required_for_route')::boolean,
          false
        )
    and (a.value->>'adapter_order')::integer<8;

  if v_projection->>'status'<>'projection_ready'
     or v_projection->>'source_ready'<>'true'
  then
    v_status:='source_not_ready_for_weather_closeout';

  elsif v_output->>'status'<>
        'weather_closeout_output_evidence_complete'
  then
    v_status:='blocked_weather_closeout_output_not_complete';

  elsif v_ownership->>'status'<>
        'legacy_simulation_run_trigger_active'
  then
    v_status:='blocked_weather_closeout_trigger_owner_unexpected';

  elsif p_process_run_id is null then
    v_status:='historical_trigger_weather_closeout_verify_only';

  elsif v_unsatisfied>0 then
    v_status:='blocked_weather_closeout_prior_effects_unsatisfied';

  elsif not v_process_found then
    v_status:='blocked_weather_closeout_process_run_required';

  elsif not v_exact_process then
    v_status:='blocked_weather_closeout_process_identity_mismatch';

  elsif not v_effect_found then
    v_status:='blocked_weather_closeout_effect_reservation_required';

  elsif v_effect.source_payload_hash is distinct from v_source_hash then
    v_status:='blocked_weather_closeout_reserved_source_hash_mismatch';

  elsif v_effect.effect_status='verified'
        and v_effect.applied_payload_hash is not null
  then
    v_status:='duplicate_verified_effect_saved_evidence';

  elsif v_effect.effect_status<>'planned' then
    v_status:='blocked_weather_closeout_effect_not_planned';

  elsif coalesce(v_config.production_execution_enabled,false)
        or coalesce(v_global.production_writer_execution_enabled,false)
        or coalesce(v_state.production_execution_enabled,false)
        or coalesce(v_global.trigger_cutover_enabled,false)
        or coalesce(v_state.trigger_cutover_enabled,false)
        or coalesce(v_config.allow_trigger_cutover,false)
        or coalesce(v_config.allow_permission_cutover,false)
  then
    v_status:='blocked_weather_closeout_production_contract_invalid';

  elsif not coalesce(v_config.shadow_execution_enabled,false)
        or not coalesce(v_global.adapter_shadow_execution_enabled,false)
        or not coalesce(v_state.shadow_execution_enabled,false)
        or not (
          'weather_closeout'=any(
            coalesce(v_global.allowed_shadow_effect_keys,'{}'::text[])
          )
        )
        or not coalesce(
          v_transition.transition_shadow_execution_enabled,
          false
        )
  then
    v_status:='blocked_weather_closeout_shadow_execution_disabled';

  else
    v_status:=
      'ready_for_weather_closeout_trigger_projection_verification_shadow';
  end if;

  v_result:=jsonb_build_object(
    'plan_version',
      'phase3ac_a11_weather_closeout_ordered_plan_v1',
    'status',v_status,
    'stage_id',p_stage_id,
    'race_id',v_stage.race_id,
    'simulation_run_id',v_run.id,
    'process_run_id',p_process_run_id,
    'canonical_source_payload_hash',v_source_hash,
    'current_output_payload_hash',v_output_hash,
    'projection',v_projection,
    'output_evidence',v_output,
    'trigger_ownership',v_ownership,
    'dependencies',v_dependencies,
    'unsatisfied_prior_effect_count',v_unsatisfied,
    'process_run',jsonb_build_object(
      'found',v_process_found,
      'exact_active_identity',v_exact_process
    ),
    'effect_ledger',
      case when v_effect_found then jsonb_build_object(
        'effect_id',v_effect.effect_id,
        'effect_status',v_effect.effect_status,
        'source_payload_hash',v_effect.source_payload_hash,
        'applied_payload_hash',v_effect.applied_payload_hash
      ) else null end,
    'canonical_weather_closeout_writer_called',false,
    'trigger_cutover_enabled',false,
    'permission_cutover_enabled',false,
    'production_execution_enabled',false
  );

  return v_result||jsonb_build_object(
    'plan_hash',md5(v_result::text),
    'generated_at',clock_timestamp()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_weather_closeout_ordered_adapter_v2(p_stage_id uuid, p_process_run_id uuid, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan jsonb;
  v_locked jsonb;
  v_config
    public.race_engine_weather_closeout_ordered_adapter_config_v2%rowtype;
  v_output jsonb;
  v_hash text;
  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;
  v_error text;
begin
  v_plan:=public.race_engine_get_weather_closeout_ordered_plan_v2(
    p_stage_id,p_process_run_id
  );

  if not coalesce(p_execute,false) then
    return jsonb_build_object(
      'status','dry_run_weather_closeout_ordered_plan',
      'stage_id',p_stage_id,
      'plan',v_plan,
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_plan->>'status'=
     'historical_trigger_weather_closeout_verify_only'
  then
    return jsonb_build_object(
      'status',v_plan->>'status',
      'stage_id',p_stage_id,
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_plan->>'status'<>
     'ready_for_weather_closeout_trigger_projection_verification_shadow'
  then
    return jsonb_build_object(
      'status',v_plan->>'status',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  select * into v_config
  from public.race_engine_weather_closeout_ordered_adapter_config_v2
  where config_key='weather_closeout';

  if md5(coalesce(p_confirmation_text,'')) is distinct from
     v_config.required_confirmation_hash
  then
    return jsonb_build_object(
      'status','blocked_weather_closeout_confirmation_mismatch',
      'stage_id',p_stage_id,
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      concat('phase3ac:a11:stage-effect:',p_stage_id::text),
      0
    )
  );

  v_locked:=public.race_engine_get_weather_closeout_ordered_plan_v2(
    p_stage_id,p_process_run_id
  );

  if v_locked->>'status'='duplicate_verified_effect_saved_evidence' then
    return jsonb_build_object(
      'status','duplicate_verified_effect_saved_evidence',
      'stage_id',p_stage_id,
      'effect_key','weather_closeout',
      'saved_effect_evidence',v_locked->'effect_ledger',
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  if v_locked->>'status'<>
     'ready_for_weather_closeout_trigger_projection_verification_shadow'
  then
    return jsonb_build_object(
      'status','blocked_weather_closeout_plan_changed_after_lock',
      'stage_id',p_stage_id,
      'plan_after_lock',v_locked,
      'canonical_weather_closeout_writer_called',false,
      'effect_transition_count',0,
      'production_execution_enabled',false
    );
  end if;

  begin
    v_started:=public.race_engine_transition_stage_effect_v2(
      p_stage_id,'weather_closeout','started',null,
      jsonb_build_object(
        'adapter_version',
          'phase3ac_a11_weather_closeout_trigger_projection_bridge_v1',
        'process_run_id',p_process_run_id,
        'current_owner','legacy_simulation_run_trigger',
        'writer_called',false
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

    if v_started->>'status'<>
       'effect_transition_applied_in_shadow_mode'
       or v_started->>'effect_status'<>'started'
    then
      raise exception 'Weather-closeout started transition failed: %',
        v_started;
    end if;

    v_output:=
      public.race_engine_get_weather_closeout_output_evidence_v2(
        (v_locked->>'race_id')::uuid
      );

    if v_output->>'status'<>
       'weather_closeout_output_evidence_complete'
       or v_output->>'output_matches_projection'<>'true'
    then
      raise exception 'Weather-closeout output verification failed: %',
        v_output;
    end if;

    v_hash:=md5(v_output::text);

    v_applied:=public.race_engine_transition_stage_effect_v2(
      p_stage_id,'weather_closeout','applied',v_hash,
      jsonb_build_object(
        'adapter_version',
          'phase3ac_a11_weather_closeout_trigger_projection_bridge_v1',
        'process_run_id',p_process_run_id,
        'writer_called',false,
        'trigger_projection_verified',true,
        'output_evidence',v_output
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

    if v_applied->>'status'<>
       'effect_transition_applied_in_shadow_mode'
       or v_applied->>'effect_status'<>'applied'
       or v_applied->>'applied_payload_hash'<>v_hash
    then
      raise exception 'Weather-closeout applied transition failed: %',
        v_applied;
    end if;

    v_verified:=public.race_engine_transition_stage_effect_v2(
      p_stage_id,'weather_closeout','verified',v_hash,
      jsonb_build_object(
        'adapter_version',
          'phase3ac_a11_weather_closeout_trigger_projection_bridge_v1',
        'process_run_id',p_process_run_id,
        'writer_called',false,
        'output_verified',true
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

    if v_verified->>'status'<>
       'effect_transition_applied_in_shadow_mode'
       or v_verified->>'effect_status'<>'verified'
       or v_verified->>'applied_payload_hash'<>v_hash
    then
      raise exception 'Weather-closeout verified transition failed: %',
        v_verified;
    end if;

  exception
    when others then
      v_error:=sqlstate||': '||sqlerrm;

      v_failed:=public.race_engine_transition_stage_effect_v2(
        p_stage_id,'weather_closeout','failed',null,
        jsonb_build_object(
          'adapter_version',
            'phase3ac_a11_weather_closeout_trigger_projection_bridge_v1',
          'process_run_id',p_process_run_id,
          'writer_called',false,
          'error_message',v_error
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

      return jsonb_build_object(
        'status',
          'weather_closeout_trigger_projection_verification_failed_in_shadow_mode',
        'stage_id',p_stage_id,
        'error_message',v_error,
        'failed_transition',v_failed,
        'canonical_weather_closeout_writer_called',false,
        'inner_mutations_rolled_back',true,
        'production_execution_enabled',false
      );
  end;

  return jsonb_build_object(
    'status',
      'weather_closeout_trigger_projection_verified_in_shadow_mode',
    'stage_id',p_stage_id,
    'process_run_id',p_process_run_id,
    'effect_key','weather_closeout',
    'source_payload_hash',
      v_locked->>'canonical_source_payload_hash',
    'applied_payload_hash',v_hash,
    'output_evidence',v_output,
    'started_transition',v_started,
    'applied_transition',v_applied,
    'verified_transition',v_verified,
    'canonical_weather_closeout_writer_called',false,
    'trigger_projection_verified',true,
    'effect_transition_count',3,
    'production_execution_enabled',false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_ranking_awards_ordered_plan_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_process public.race_engine_stage_process_runs_v2%rowtype;
  v_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;

  v_legacy jsonb;
  v_source jsonb;
  v_output jsonb;
  v_manifest jsonb;
  v_adapter jsonb;
  v_process_found boolean:=false;
  v_process_exact boolean:=false;
  v_effect_found boolean:=false;
  v_rollback_test_only boolean:=false;
  v_downstream_effects integer:=0;
  v_status text;
  v_result jsonb;
begin
  select * into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key='ranking_awards';

  if not found then
    return jsonb_build_object(
      'status','blocked_ranking_high_risk_contract_missing',
      'stage_id',p_stage_id,
      'production_execution_enabled',false
    );
  end if;

  v_legacy:=
    public.race_engine_get_stage_ranking_awards_adapter_plan_v2(
      p_stage_id,p_process_run_id
    );
  v_source:=
    public.race_engine_get_stage_ranking_source_evidence_v2(p_stage_id);
  v_output:=
    public.race_engine_get_stage_ranking_output_evidence_v2(p_stage_id);
  v_manifest:=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(p_stage_id);

  select a.value into v_adapter
  from jsonb_array_elements(
    coalesce(v_manifest->'adapters','[]'::jsonb)
  ) a(value)
  where a.value->>'effect_key'='ranking_awards'
  limit 1;

  if p_process_run_id is not null then
    select * into v_process
    from public.race_engine_stage_process_runs_v2
    where process_run_id=p_process_run_id;

    v_process_found:=found;
    if v_process_found then
      v_process_exact:=
        v_process.stage_id=p_stage_id
        and v_process.race_id=
            nullif(v_legacy->>'race_id','')::uuid
        and v_process.simulation_run_id is not distinct from
            nullif(v_legacy->>'simulation_run_id','')::uuid
        and v_process.status='started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run;

      v_rollback_test_only:=
        v_process_exact
        and v_process.processor_version=
          'phase3ac_a11_branch04_ranking_awards_rollback_shadow_matrix_v1'
        and v_process.confirmation_text_hash=
          md5(
            'CONFIRM_PHASE3AC_A11_BRANCH04_RANKING_AWARDS_ROLLBACK_TEST_ONLY'
          )
        and v_process.metadata->>
              'ranking_awards_rollback_test_only'='true'
        and v_process.metadata->>
              'rollback_test_contract_version'=
              'phase3ac_a11_ranking_awards_rollback_test_only_v2'
        and v_process.metadata->>
              'ranking_source_payload_hash'=
              v_source->>'source_payload_hash'
        and v_legacy->>'status'=
              'historical_verify_only_completed_stage_missing_awards'
        and v_legacy->>'route_format'='team_time_trial'
        and v_source->>'status'='source_evidence_ready'
        and (v_output->>'row_count')::integer=0
        and (v_output->>'duplicate_natural_key_count')::integer=0;
    end if;
  end if;

  select * into v_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id=p_stage_id
    and effect_key='ranking_awards';
  v_effect_found:=found;

  select count(*)::integer into v_downstream_effects
  from public.race_engine_stage_effect_ledger_v2
  where stage_id=p_stage_id
    and effect_key=any(v_contract.forbid_regeneration_after_effect_keys)
    and effect_status in ('started','applied','verified','skipped');

  select * into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key='ordered_effect_adapters';

  select * into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version=
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key='ranking_awards';

  if v_legacy->>'status' in (
       'stage_not_found',
       'historical_verify_only_golden_fixture',
       'historical_verify_only_existing_awards',
       'historical_verify_only_completed_stage_missing_awards',
       'blocked_downstream_prize_or_finance_exists',
       'blocked_stage_closeout_effect_exists',
       'blocked_ranking_writer_definition_drift'
     )
     and not v_rollback_test_only
  then
    v_status:=v_legacy->>'status';

  elsif v_adapter is null then
    v_status:='blocked_ranking_manifest_adapter_missing';

  elsif not coalesce(
          (v_adapter->>'required_for_route')::boolean,
          false
        )
  then
    v_status:='route_skipped_ranking_awards_not_required';

  elsif v_source->>'status'<>'source_evidence_ready' then
    v_status:='source_not_ready_no_stage_results';

  elsif v_adapter->>'source_payload_hash' is distinct from
        v_source->>'source_payload_hash'
        and not v_rollback_test_only
  then
    v_status:='blocked_ranking_source_contract_mismatch';

  elsif v_downstream_effects>0 then
    v_status:='blocked_ranking_downstream_effect_already_started';

  elsif v_effect_found
        and v_effect.effect_status='verified'
        and v_effect.applied_payload_hash is not null
  then
    v_status:='duplicate_verified_effect_saved_evidence';

  elsif (v_output->>'row_count')::integer>0 then
    v_status:='blocked_ranking_existing_output_without_verified_effect';

  elsif not v_process_found then
    v_status:='blocked_ranking_process_run_required';

  elsif not v_process_exact then
    v_status:='blocked_ranking_process_identity_mismatch';

  elsif not v_effect_found then
    v_status:='blocked_ranking_effect_reservation_required';

  elsif v_effect.effect_status<>'planned' then
    v_status:='blocked_ranking_effect_not_planned';

  elsif v_effect.source_payload_hash is distinct from
        v_source->>'source_payload_hash'
  then
    v_status:='blocked_ranking_reserved_source_hash_mismatch';

  elsif not coalesce(v_contract.shadow_execution_enabled,false)
        and not coalesce(v_contract.production_execution_enabled,false)
  then
    v_status:='blocked_ranking_ordered_execution_disabled';

  elsif not coalesce(v_global.adapter_shadow_execution_enabled,false)
        and not coalesce(v_global.production_writer_execution_enabled,false)
  then
    v_status:='blocked_ranking_global_execution_disabled';

  elsif not coalesce(v_state.shadow_execution_enabled,false)
        and not coalesce(v_state.production_execution_enabled,false)
  then
    v_status:='blocked_ranking_effect_execution_disabled';

  else
    v_status:='ready_for_ranking_awards_ordered_execution';
  end if;

  v_result:=jsonb_build_object(
    'plan_version','phase3ac_a11_ranking_awards_ordered_plan_v1',
    'status',v_status,
    'stage_id',p_stage_id,
    'race_id',v_legacy->>'race_id',
    'simulation_run_id',v_legacy->>'simulation_run_id',
    'route_format',v_legacy->>'route_format',
    'stage_process_status',v_legacy->>'stage_process_status',
    'canonical_source_payload_hash',v_source->>'source_payload_hash',
    'manifest_source_payload_hash',v_adapter->>'source_payload_hash',
    'source_contract_matches',
      v_adapter->>'source_payload_hash' is not distinct from
      v_source->>'source_payload_hash',
    'effective_source_contract_matches',
      (
        v_adapter->>'source_payload_hash' is not distinct from
        v_source->>'source_payload_hash'
      )
      or v_rollback_test_only,
    'rollback_test_only_manifest_mismatch_bypassed',
      v_rollback_test_only
      and v_adapter->>'source_payload_hash' is distinct from
          v_source->>'source_payload_hash',
    'reservation_source_payload_hash',
      v_source->>'source_payload_hash',
    'source_evidence',v_source,
    'output_evidence',v_output,
    'process_run',jsonb_build_object(
      'requested_process_run_id',p_process_run_id,
      'found',v_process_found,
      'exact_active_identity',v_process_exact
    ),
    'effect_ledger',
      case when v_effect_found then jsonb_build_object(
        'effect_id',v_effect.effect_id,
        'effect_status',v_effect.effect_status,
        'source_payload_hash',v_effect.source_payload_hash,
        'applied_payload_hash',v_effect.applied_payload_hash
      ) else null end,
    'downstream_effect_count',v_downstream_effects,
    'expected_output_policy',
      case
        when v_legacy->>'route_format'='team_time_trial'
          then 'zero_rows_allowed_for_team_time_trial'
        else 'nonzero_rows_required_when_writer_executes'
      end,
    'identity_hash_for_equivalence',false,
    'semantic_hash_required',true,
    'rollback_test_only_contract_active',v_rollback_test_only,
    'rollback_test_only_contract_version',
      case
        when v_rollback_test_only then
          'phase3ac_a11_ranking_awards_rollback_test_only_v2'
        else null
      end,
    'rollback_test_only_never_production',true,
    'destructive_writer_called',false,
    'production_execution_enabled',false
  );

  return v_result||jsonb_build_object(
    'plan_hash',md5(v_result::text),
    'generated_at',clock_timestamp()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_ranking_awards_ordered_adapter_v2(p_stage_id uuid, p_process_run_id uuid, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;
  v_a10 public.race_engine_effect_immutable_config_v2%rowtype;

  v_plan jsonb;
  v_locked_plan jsonb;
  v_source_after jsonb;
  v_output jsonb;

  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;

  v_race_id uuid;
  v_source_hash text;
  v_output_hash text;
  v_route_format text;
  v_is_final_stage boolean;
  v_error_message text;
begin
  if public.race_engine_verify_golden_stage_fixture_v1(
       'rio_tour_stage1_phase3aa_golden_v1'
     )->>'status'<>'fixture_matches_current_state'
  then
    return jsonb_build_object(
      'status','blocked_golden_fixture_mismatch',
      'stage_id',p_stage_id,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  v_plan:=
    public.race_engine_get_ranking_awards_ordered_plan_v2(
      p_stage_id,p_process_run_id
    );

  if not coalesce(p_execute,false) then
    return jsonb_build_object(
      'status','dry_run_ranking_awards_ordered_plan',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'plan',v_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'effect_ledger_changed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan->>'status'='duplicate_verified_effect_saved_evidence' then
    return jsonb_build_object(
      'status','duplicate_verified_effect_saved_evidence',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'saved_effect_evidence',v_plan->'effect_ledger',
      'output_evidence',v_plan->'output_evidence',
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'effect_ledger_changed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  if v_plan->>'status'<>
       'ready_for_ranking_awards_ordered_execution'
  then
    return jsonb_build_object(
      'status',v_plan->>'status',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'plan',v_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'effect_ledger_changed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  select * into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key='ranking_awards';

  select * into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key='ordered_effect_adapters';

  select * into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version=
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key='ranking_awards';

  select * into v_a10
  from public.race_engine_effect_immutable_config_v2
  where config_key='effect_immutable';

  if coalesce(v_contract.production_execution_enabled,false)
     or coalesce(v_global.production_writer_execution_enabled,false)
     or coalesce(v_state.production_execution_enabled,false)
     or coalesce(v_a10.production_effect_transition_enabled,false)
  then
    return jsonb_build_object(
      'status','blocked_ranking_production_cutover_not_supported',
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  if not coalesce(v_contract.shadow_execution_enabled,false)
     or not coalesce(v_global.adapter_shadow_execution_enabled,false)
     or not (
       'ranking_awards'=any(
         coalesce(v_global.allowed_shadow_effect_keys,'{}'::text[])
       )
     )
     or not coalesce(v_state.shadow_execution_enabled,false)
     or not coalesce(v_a10.transition_shadow_execution_enabled,false)
  then
    return jsonb_build_object(
      'status','blocked_ranking_awards_ordered_execution_disabled',
      'stage_id',p_stage_id,
      'process_run_id',p_process_run_id,
      'plan_status',v_plan->>'status',
      'execution',jsonb_build_object(
        'contract_shadow_execution_enabled',
          coalesce(v_contract.shadow_execution_enabled,false),
        'global_shadow_execution_enabled',
          coalesce(v_global.adapter_shadow_execution_enabled,false),
        'effect_allowed_for_shadow',
          'ranking_awards'=any(
            coalesce(v_global.allowed_shadow_effect_keys,'{}'::text[])
          ),
        'effect_state_shadow_execution_enabled',
          coalesce(v_state.shadow_execution_enabled,false),
        'a10_transition_shadow_execution_enabled',
          coalesce(v_a10.transition_shadow_execution_enabled,false)
      ),
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'effect_ledger_changed',false,
      'production_writer_execution_enabled',false
    );
  end if;

  if md5(coalesce(p_confirmation_text,'')) is distinct from
     nullif(
       v_contract.metadata->>'ordered_wrapper_confirmation_hash',
       ''
     )
  then
    return jsonb_build_object(
      'status','blocked_ranking_awards_ordered_confirmation_mismatch',
      'stage_id',p_stage_id,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'phase3ac:a11:b04:ranking-awards:'
      ||p_stage_id::text,
      0
    )
  );

  v_locked_plan:=
    public.race_engine_get_ranking_awards_ordered_plan_v2(
      p_stage_id,p_process_run_id
    );

  if v_locked_plan->>'status'<>
       'ready_for_ranking_awards_ordered_execution'
  then
    return jsonb_build_object(
      'status','blocked_ranking_awards_plan_changed_after_lock',
      'locked_plan_status',v_locked_plan->>'status',
      'locked_plan',v_locked_plan,
      'canonical_writer_called',false,
      'effect_transition_count',0,
      'production_writer_execution_enabled',false
    );
  end if;

  v_race_id:=nullif(v_locked_plan->>'race_id','')::uuid;
  v_source_hash:=
    v_locked_plan->>'canonical_source_payload_hash';
  v_route_format:=v_locked_plan->>'route_format';

  select not exists(
    select 1
    from public.race_stages later_stage
    join public.race_stages current_stage
      on current_stage.id=p_stage_id
    where later_stage.race_id=current_stage.race_id
      and (
        later_stage.stage_number>current_stage.stage_number
        or (
          later_stage.stage_number=current_stage.stage_number
          and later_stage.id>current_stage.id
        )
      )
  )
  into v_is_final_stage;

  v_started:=
    public.race_engine_transition_stage_effect_v2(
      p_stage_id,
      'ranking_awards',
      'started',
      null,
      jsonb_build_object(
        'a11_adapter_version',
          'phase3ac_a11_ranking_awards_ordered_adapter_v1',
        'process_run_id',p_process_run_id,
        'execution_mode','rollback_shadow_only',
        'writer_called',false,
        'source_payload_hash',v_source_hash
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

  if v_started->>'status'<>
       'effect_transition_applied_in_shadow_mode'
     or v_started->>'effect_status'<>'started'
  then
    raise exception
      'Ranking ordered started transition failed: %',
      v_started;
  end if;

  begin
    perform public.generate_race_ranking_point_awards_v1(
      v_race_id,
      p_stage_id,
      coalesce(v_is_final_stage,false)
    );

    v_source_after:=
      public.race_engine_get_stage_ranking_source_evidence_v2(
        p_stage_id
      );

    if v_source_after->>'source_payload_hash'
       is distinct from v_source_hash
    then
      raise exception
        'Ranking source drift detected during writer execution.';
    end if;

    v_output:=
      public.race_engine_get_stage_ranking_output_evidence_v2(
        p_stage_id
      );

    if v_output->>'status'<>'output_evidence_ready'
       or (v_output->>'duplicate_natural_key_count')::integer<>0
       or nullif(v_output->>'semantic_hash','') is null
       or (
         v_route_format<>'team_time_trial'
         and (v_output->>'row_count')::integer<=0
       )
       or (
         v_route_format='team_time_trial'
         and (v_output->>'row_count')::integer<0
       )
    then
      raise exception
        'Ranking ordered output verification failed: %',
        v_output;
    end if;

    v_output_hash:=v_output->>'semantic_hash';

    v_applied:=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'ranking_awards',
        'applied',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_ranking_awards_ordered_adapter_v1',
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'writer_called',true,
          'source_payload_hash',v_source_hash,
          'semantic_output_evidence',v_output,
          'identity_hash_excluded_from_equivalence',true
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_applied->>'status'<>
         'effect_transition_applied_in_shadow_mode'
       or v_applied->>'effect_status'<>'applied'
       or v_applied->>'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Ranking ordered applied transition failed: %',
        v_applied;
    end if;

    v_verified:=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'ranking_awards',
        'verified',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_ranking_awards_ordered_adapter_v1',
          'process_run_id',p_process_run_id,
          'execution_mode','rollback_shadow_only',
          'writer_called',true,
          'output_verified',true,
          'semantic_output_evidence',v_output
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_verified->>'status'<>
         'effect_transition_applied_in_shadow_mode'
       or v_verified->>'effect_status'<>'verified'
       or v_verified->>'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Ranking ordered verified transition failed: %',
        v_verified;
    end if;

  exception
    when others then
      v_error_message:=sqlstate||': '||sqlerrm;

      v_failed:=
        public.race_engine_transition_stage_effect_v2(
          p_stage_id,
          'ranking_awards',
          'failed',
          null,
          jsonb_build_object(
            'a11_adapter_version',
              'phase3ac_a11_ranking_awards_ordered_adapter_v1',
            'process_run_id',p_process_run_id,
            'execution_mode','rollback_shadow_only',
            'writer_or_verification_error',v_error_message,
            'error_message',v_error_message
          ),
          true,
          'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
        );

      return jsonb_build_object(
        'status',
          'ranking_awards_ordered_effect_failed_in_shadow_mode',
        'stage_id',p_stage_id,
        'process_run_id',p_process_run_id,
        'error_message',v_error_message,
        'failed_transition',v_failed,
        'canonical_writer_called',
          v_started->>'effect_status'='started',
        'writer_mutations_from_failed_inner_block_rolled_back',true,
        'effect_transition_count',
          case
            when v_failed->>'effect_status'='failed' then 2
            else 1
          end,
        'production_writer_execution_enabled',false
      );
  end;

  return jsonb_build_object(
    'status',
      'ranking_awards_applied_and_verified_in_rollback_shadow_mode',
    'stage_id',p_stage_id,
    'race_id',v_race_id,
    'process_run_id',p_process_run_id,
    'effect_key','ranking_awards',
    'effect_order',1,
    'source_payload_hash',v_source_hash,
    'applied_payload_hash',v_output_hash,
    'is_final_stage',coalesce(v_is_final_stage,false),
    'output_evidence',v_output,
    'started_transition',v_started,
    'applied_transition',v_applied,
    'verified_transition',v_verified,
    'canonical_writer_called',true,
    'effect_transition_count',3,
    'execution_mode','rollback_shadow_only',
    'production_writer_execution_enabled',false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_prize_awards_ordered_plan_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_process public.race_engine_stage_process_runs_v2%rowtype;
  v_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_ranking_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;

  v_legacy jsonb;
  v_source jsonb;
  v_output jsonb;
  v_manifest jsonb;
  v_adapter jsonb;

  v_process_found boolean := false;
  v_process_exact boolean := false;
  v_effect_found boolean := false;
  v_ranking_effect_found boolean := false;
  v_rollback_test_only boolean := false;
  v_downstream_effects integer := 0;

  v_status text;
  v_result jsonb;
begin
  select *
  into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key = 'prize_awards';

  if not found then
    return jsonb_build_object(
      'status', 'blocked_prize_high_risk_contract_missing',
      'stage_id', p_stage_id,
      'production_execution_enabled', false
    );
  end if;

  v_legacy :=
    public.race_engine_get_stage_prize_awards_adapter_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  v_source :=
    public.race_engine_get_stage_prize_source_evidence_v2(
      p_stage_id
    );

  v_output :=
    public.race_engine_get_stage_prize_award_snapshot_v2(
      p_stage_id
    );

  v_manifest :=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(
      p_stage_id
    );

  select a.value
  into v_adapter
  from jsonb_array_elements(
    coalesce(v_manifest -> 'adapters', '[]'::jsonb)
  ) a(value)
  where a.value ->> 'effect_key' = 'prize_awards'
  limit 1;

  if p_process_run_id is not null then
    select *
    into v_process
    from public.race_engine_stage_process_runs_v2
    where process_run_id = p_process_run_id;

    v_process_found := found;

    if v_process_found then
      v_process_exact :=
        v_process.stage_id = p_stage_id
        and v_process.race_id =
            nullif(v_source ->> 'race_id', '')::uuid
        and v_process.simulation_run_id is not distinct from
            nullif(v_legacy ->> 'simulation_run_id', '')::uuid
        and v_process.status = 'started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run;
    end if;
  end if;

  select *
  into v_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = 'prize_awards';

  v_effect_found := found;

  select *
  into v_ranking_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = 'ranking_awards';

  v_ranking_effect_found := found;

  select count(*)::integer
  into v_downstream_effects
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = any(v_contract.forbid_regeneration_after_effect_keys)
    and effect_status in ('started', 'applied', 'verified', 'skipped');

  select *
  into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key = 'ordered_effect_adapters';

  select *
  into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key = 'prize_awards';

  v_rollback_test_only :=
    p_stage_id =
      '165d71b8-d823-451b-be66-cb0fc52c3811'::uuid
    and v_process_found
    and v_process_exact
    and v_process.processor_version =
        'phase3ac_a11_branch04_prize_awards_rollback_shadow_matrix_v3'
    and v_process.confirmation_text_hash =
        md5(
          'CONFIRM_PHASE3AC_A11_BRANCH04_PRIZE_AWARDS_ROLLBACK_TEST_ONLY'
        )
    and v_process.metadata ->>
          'prize_awards_rollback_test_only' = 'true'
    and v_process.metadata ->>
          'rollback_test_contract_version' =
          'phase3ac_a11_prize_awards_rollback_test_only_v3'
    and v_process.metadata ->>
          'prize_source_payload_hash' =
          v_source ->> 'source_payload_hash'
    and v_process.metadata ->>
          'manifest_source_payload_hash' =
          v_adapter ->> 'source_payload_hash'
    and v_process.metadata ->>
          'existing_prize_identity_hash' =
          '9cb81f6e95919fd87dc91098813c4655'
    and v_process.metadata ->>
          'existing_prize_semantic_hash' =
          '4f85b320c0d0b80a2c8660f034a8b3ac'
    and v_process.metadata ->>
          'ranking_source_payload_hash' =
          'c818c8f761d5f4e165ef8c85e0395b76'
    and v_process.metadata ->>
          'ranking_output_semantic_hash' =
          '99c665ef9bb260ba8619b7ffea83ead2'
    and v_source ->> 'race_id' =
        '505db435-ecb9-463d-b946-1158c549a8c9'
    and v_source ->> 'route_format' = 'road_race'
    and v_source ->> 'stage_process_status' =
        'future_execution_candidate'
    and v_source ->> 'status' = 'source_evidence_ready'
    and v_source ->> 'source_payload_hash' =
        '23e13e643a0a64447d0375ded1e5ddb0'
    and v_adapter is not null
    and v_adapter ->> 'source_payload_hash' =
        '5887642a3de316675b4ab6007cdad996'
    and v_ranking_effect_found
    and v_ranking_effect.effect_status = 'verified'
    and v_ranking_effect.applied_payload_hash =
        '99c665ef9bb260ba8619b7ffea83ead2'
    and v_effect_found
    and v_effect.source_payload_hash =
        '23e13e643a0a64447d0375ded1e5ddb0'
    and (
      (
        v_legacy ->> 'status' =
          'blocked_process_run_not_execution_capable'
        and v_effect.effect_status = 'planned'
        and v_effect.applied_payload_hash is null
        and (v_output ->> 'row_count')::integer = 0
        and (v_output ->> 'paid_row_count')::integer = 0
        and (v_output ->> 'duplicate_natural_key_count')::integer = 0
        and (v_output ->> 'finance_event_lock_count')::integer = 0
        and (v_output ->> 'linked_finance_transaction_count')::integer = 0
      )
      or
      (
        v_legacy ->> 'status' in (
          'historical_verify_only_existing_unpaid_prizes',
          'blocked_process_run_not_execution_capable'
        )
        and v_effect.effect_status = 'verified'
        and v_effect.applied_payload_hash =
          '4f85b320c0d0b80a2c8660f034a8b3ac'
        and (v_output ->> 'row_count')::integer = 10
        and (v_output ->> 'pending_row_count')::integer = 10
        and (v_output ->> 'paid_row_count')::integer = 0
        and (v_output ->> 'total_amount_cash')::bigint = 8751
        and (v_output ->> 'duplicate_natural_key_count')::integer = 0
        and (v_output ->> 'finance_event_lock_count')::integer = 0
        and (v_output ->> 'linked_finance_transaction_count')::integer = 0
        and v_output ->> 'semantic_hash' =
          '4f85b320c0d0b80a2c8660f034a8b3ac'
      )
    );

  if v_legacy ->> 'status' in (
       'stage_not_found',
       'blocked_prize_adapter_config_missing',
       'historical_verify_only_golden_fixture',
       'historical_verify_only_paid_prize_identity_immutable',
       'historical_verify_only_existing_unpaid_prizes',
       'historical_verify_only_completed_stage_missing_prizes',
       'blocked_paid_or_finance_locked_prize_identity',
       'blocked_prize_payment_effect_exists',
       'blocked_stage_closeout_effect_exists',
       'blocked_prize_writer_definition_drift'
     )
     and not v_rollback_test_only
  then
    v_status := v_legacy ->> 'status';

  elsif v_adapter is null then
    v_status := 'blocked_prize_manifest_adapter_missing';

  elsif not coalesce(
          (v_adapter ->> 'required_for_route')::boolean,
          false
        )
  then
    v_status := 'route_skipped_prize_awards_not_required';

  elsif v_legacy ->> 'status' = 'blocked_unsupported_route' then
    v_status := 'blocked_prize_unsupported_required_route';

  elsif v_source ->> 'status' <> 'source_evidence_ready' then
    v_status := 'source_not_ready_no_stage_results';

  elsif v_adapter ->> 'source_payload_hash' is distinct from
        v_source ->> 'source_payload_hash'
        and not v_rollback_test_only
  then
    v_status := 'blocked_prize_source_contract_mismatch';

  elsif v_downstream_effects > 0 then
    v_status := 'blocked_prize_downstream_effect_already_started';

  elsif not v_ranking_effect_found
        or v_ranking_effect.effect_status <> 'verified'
  then
    v_status := 'blocked_verified_ranking_effect_required';

  elsif v_effect_found
        and v_effect.effect_status = 'verified'
        and v_effect.applied_payload_hash is not null
  then
    v_status := 'duplicate_verified_effect_saved_evidence';

  elsif (v_output ->> 'row_count')::integer > 0 then
    v_status := 'blocked_prize_existing_output_without_verified_effect';

  elsif not v_process_found then
    v_status := 'blocked_prize_process_run_required';

  elsif not v_process_exact then
    v_status := 'blocked_prize_process_identity_mismatch';

  elsif not v_effect_found then
    v_status := 'blocked_prize_effect_reservation_required';

  elsif v_effect.effect_status <> 'planned' then
    v_status := 'blocked_prize_effect_not_planned';

  elsif v_effect.source_payload_hash is distinct from
        v_source ->> 'source_payload_hash'
  then
    v_status := 'blocked_prize_reserved_source_hash_mismatch';

  elsif not coalesce(v_contract.shadow_execution_enabled, false)
        and not coalesce(v_contract.production_execution_enabled, false)
  then
    v_status := 'blocked_prize_ordered_execution_disabled';

  elsif not coalesce(v_global.adapter_shadow_execution_enabled, false)
        and not coalesce(v_global.production_writer_execution_enabled, false)
  then
    v_status := 'blocked_prize_global_execution_disabled';

  elsif not coalesce(v_state.shadow_execution_enabled, false)
        and not coalesce(v_state.production_execution_enabled, false)
  then
    v_status := 'blocked_prize_effect_execution_disabled';

  else
    v_status := 'ready_for_prize_awards_ordered_execution';
  end if;

  v_result :=
    jsonb_build_object(
      'plan_version',
        'phase3ac_a11_prize_awards_ordered_plan_v1',
      'status',
        v_status,
      'stage_id',
        p_stage_id,
      'race_id',
        v_source ->> 'race_id',
      'simulation_run_id',
        v_legacy ->> 'simulation_run_id',
      'route_format',
        v_source ->> 'route_format',
      'stage_process_status',
        v_source ->> 'stage_process_status',
      'legacy_plan_status',
        v_legacy ->> 'status',
      'is_final_stage',
        v_source -> 'is_final_stage',
      'canonical_source_payload_hash',
        v_source ->> 'source_payload_hash',
      'manifest_source_payload_hash',
        v_adapter ->> 'source_payload_hash',
      'source_contract_matches',
        v_adapter ->> 'source_payload_hash' is not distinct from
        v_source ->> 'source_payload_hash',
      'effective_source_contract_matches',
        (
          v_adapter ->> 'source_payload_hash' is not distinct from
          v_source ->> 'source_payload_hash'
        )
        or v_rollback_test_only,
      'rollback_test_only_manifest_mismatch_bypassed',
        v_rollback_test_only
        and v_adapter ->> 'source_payload_hash' is distinct from
            v_source ->> 'source_payload_hash',
      'reservation_source_payload_hash',
        v_source ->> 'source_payload_hash',
      'source_evidence',
        v_source,
      'output_evidence',
        v_output,
      'process_run',
        jsonb_build_object(
          'requested_process_run_id', p_process_run_id,
          'found', v_process_found,
          'exact_active_identity', v_process_exact
        ),
      'predecessor_effect',
        case
          when v_ranking_effect_found then
            jsonb_build_object(
              'effect_key', 'ranking_awards',
              'effect_id', v_ranking_effect.effect_id,
              'effect_status', v_ranking_effect.effect_status,
              'source_payload_hash', v_ranking_effect.source_payload_hash,
              'applied_payload_hash', v_ranking_effect.applied_payload_hash
            )
          else null
        end,
      'effect_ledger',
        case
          when v_effect_found then
            jsonb_build_object(
              'effect_id', v_effect.effect_id,
              'effect_status', v_effect.effect_status,
              'source_payload_hash', v_effect.source_payload_hash,
              'applied_payload_hash', v_effect.applied_payload_hash
            )
          else null
        end,
      'downstream_effect_count',
        v_downstream_effects,
      'expected_output_policy',
        'nonzero_semantic_output_required_when_writer_executes',
      'semantic_hash_required',
        true,
      'identity_hash_for_equivalence',
        false,
      'rollback_test_only_contract_active',
        v_rollback_test_only,
      'rollback_test_only_contract_version',
        case
          when v_rollback_test_only then
            'phase3ac_a11_prize_awards_rollback_test_only_v3'
          else null
        end,
      'rollback_test_only_never_production',
        true,
      'rollback_test_only_verified_duplicate_state',
        v_rollback_test_only
        and v_effect_found
        and v_effect.effect_status = 'verified'
        and (v_output ->> 'row_count')::integer = 10,
      'destructive_writer_called',
        false,
      'production_execution_enabled',
        false
    );

  return
    v_result
    ||
    jsonb_build_object(
      'plan_hash', md5(v_result::text),
      'generated_at', clock_timestamp()
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_prize_awards_ordered_adapter_v2(p_stage_id uuid, p_process_run_id uuid, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;
  v_a10 public.race_engine_effect_immutable_config_v2%rowtype;

  v_plan jsonb;
  v_locked_plan jsonb;
  v_source_after jsonb;
  v_output jsonb;

  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;

  v_race_id uuid;
  v_source_hash text;
  v_output_hash text;
  v_is_final_stage boolean;
  v_error_message text;
begin
  if public.race_engine_verify_golden_stage_fixture_v1(
       'rio_tour_stage1_phase3aa_golden_v1'
     ) ->> 'status' <> 'fixture_matches_current_state'
  then
    return jsonb_build_object(
      'status', 'blocked_golden_fixture_mismatch',
      'stage_id', p_stage_id,
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'production_writer_execution_enabled', false
    );
  end if;

  v_plan :=
    public.race_engine_get_prize_awards_ordered_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  if not coalesce(p_execute, false) then
    return jsonb_build_object(
      'status', 'dry_run_prize_awards_ordered_plan',
      'stage_id', p_stage_id,
      'process_run_id', p_process_run_id,
      'plan', v_plan,
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'effect_ledger_changed', false,
      'production_writer_execution_enabled', false
    );
  end if;

  if v_plan ->> 'status' = 'duplicate_verified_effect_saved_evidence' then
    return jsonb_build_object(
      'status', 'duplicate_verified_effect_saved_evidence',
      'stage_id', p_stage_id,
      'process_run_id', p_process_run_id,
      'saved_effect_evidence', v_plan -> 'effect_ledger',
      'output_evidence', v_plan -> 'output_evidence',
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'effect_ledger_changed', false,
      'production_writer_execution_enabled', false
    );
  end if;

  if v_plan ->> 'status' <>
       'ready_for_prize_awards_ordered_execution'
  then
    return jsonb_build_object(
      'status', v_plan ->> 'status',
      'stage_id', p_stage_id,
      'process_run_id', p_process_run_id,
      'plan', v_plan,
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'effect_ledger_changed', false,
      'production_writer_execution_enabled', false
    );
  end if;

  select * into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key = 'prize_awards';

  select * into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key = 'ordered_effect_adapters';

  select * into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key = 'prize_awards';

  select * into v_a10
  from public.race_engine_effect_immutable_config_v2
  where config_key = 'effect_immutable';

  if coalesce(v_contract.production_execution_enabled, false)
     or coalesce(v_global.production_writer_execution_enabled, false)
     or coalesce(v_state.production_execution_enabled, false)
     or coalesce(v_a10.production_effect_transition_enabled, false)
  then
    return jsonb_build_object(
      'status', 'blocked_prize_production_cutover_not_supported',
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'production_writer_execution_enabled', false
    );
  end if;

  if not coalesce(v_contract.shadow_execution_enabled, false)
     or not coalesce(v_global.adapter_shadow_execution_enabled, false)
     or not (
       'prize_awards' = any(
         coalesce(v_global.allowed_shadow_effect_keys, '{}'::text[])
       )
     )
     or not coalesce(v_state.shadow_execution_enabled, false)
     or not coalesce(v_a10.transition_shadow_execution_enabled, false)
  then
    return jsonb_build_object(
      'status', 'blocked_prize_awards_ordered_execution_disabled',
      'stage_id', p_stage_id,
      'process_run_id', p_process_run_id,
      'plan_status', v_plan ->> 'status',
      'execution', jsonb_build_object(
        'contract_shadow_execution_enabled',
          coalesce(v_contract.shadow_execution_enabled, false),
        'global_shadow_execution_enabled',
          coalesce(v_global.adapter_shadow_execution_enabled, false),
        'effect_allowed_for_shadow',
          'prize_awards' = any(
            coalesce(v_global.allowed_shadow_effect_keys, '{}'::text[])
          ),
        'effect_state_shadow_execution_enabled',
          coalesce(v_state.shadow_execution_enabled, false),
        'a10_transition_shadow_execution_enabled',
          coalesce(v_a10.transition_shadow_execution_enabled, false)
      ),
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'effect_ledger_changed', false,
      'production_writer_execution_enabled', false
    );
  end if;

  if md5(coalesce(p_confirmation_text, '')) is distinct from
     nullif(
       v_contract.metadata ->> 'ordered_wrapper_confirmation_hash',
       ''
     )
  then
    return jsonb_build_object(
      'status', 'blocked_prize_awards_ordered_confirmation_mismatch',
      'stage_id', p_stage_id,
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'production_writer_execution_enabled', false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'phase3ac:a11:b04:prize-awards:' || p_stage_id::text,
      0
    )
  );

  v_locked_plan :=
    public.race_engine_get_prize_awards_ordered_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  if v_locked_plan ->> 'status' <>
       'ready_for_prize_awards_ordered_execution'
  then
    return jsonb_build_object(
      'status', 'blocked_prize_awards_plan_changed_after_lock',
      'locked_plan_status', v_locked_plan ->> 'status',
      'locked_plan', v_locked_plan,
      'canonical_writer_called', false,
      'effect_transition_count', 0,
      'production_writer_execution_enabled', false
    );
  end if;

  v_race_id := nullif(v_locked_plan ->> 'race_id', '')::uuid;
  v_source_hash :=
    v_locked_plan ->> 'canonical_source_payload_hash';
  v_is_final_stage :=
    coalesce((v_locked_plan ->> 'is_final_stage')::boolean, false);

  v_started :=
    public.race_engine_transition_stage_effect_v2(
      p_stage_id,
      'prize_awards',
      'started',
      null,
      jsonb_build_object(
        'a11_adapter_version',
          'phase3ac_a11_prize_awards_ordered_adapter_v1',
        'process_run_id', p_process_run_id,
        'execution_mode', 'rollback_shadow_only',
        'writer_called', false,
        'source_payload_hash', v_source_hash,
        'is_final_stage', v_is_final_stage
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

  if v_started ->> 'status' <>
       'effect_transition_applied_in_shadow_mode'
     or v_started ->> 'effect_status' <> 'started'
  then
    raise exception
      'Prize ordered started transition failed: %',
      v_started;
  end if;

  begin
    perform public.generate_race_prize_awards_v1(
      v_race_id,
      p_stage_id,
      v_is_final_stage
    );

    v_source_after :=
      public.race_engine_get_stage_prize_source_evidence_v2(
        p_stage_id
      );

    if v_source_after ->> 'source_payload_hash'
       is distinct from v_source_hash
    then
      raise exception
        'Prize source drift detected during writer execution.';
    end if;

    v_output :=
      public.race_engine_get_stage_prize_award_snapshot_v2(
        p_stage_id
      );

    if (v_output ->> 'row_count')::integer <= 0
       or (v_output ->> 'duplicate_natural_key_count')::integer <> 0
       or (v_output ->> 'paid_row_count')::integer <> 0
       or (v_output ->> 'finance_event_lock_count')::integer <> 0
       or (v_output ->> 'linked_finance_transaction_count')::integer <> 0
       or nullif(v_output ->> 'semantic_hash', '') is null
    then
      raise exception
        'Prize ordered output verification failed: %',
        v_output;
    end if;

    v_output_hash := v_output ->> 'semantic_hash';

    v_applied :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'prize_awards',
        'applied',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_prize_awards_ordered_adapter_v1',
          'process_run_id', p_process_run_id,
          'execution_mode', 'rollback_shadow_only',
          'writer_called', true,
          'source_payload_hash', v_source_hash,
          'semantic_output_evidence', v_output,
          'identity_hash_excluded_from_equivalence', true,
          'paid_identity_is_immutable_after_payment', true
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_applied ->> 'status' <>
         'effect_transition_applied_in_shadow_mode'
       or v_applied ->> 'effect_status' <> 'applied'
       or v_applied ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Prize ordered applied transition failed: %',
        v_applied;
    end if;

    v_verified :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'prize_awards',
        'verified',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_prize_awards_ordered_adapter_v1',
          'process_run_id', p_process_run_id,
          'execution_mode', 'rollback_shadow_only',
          'writer_called', true,
          'output_verified', true,
          'semantic_output_evidence', v_output,
          'paid_identity_is_immutable_after_payment', true
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_verified ->> 'status' <>
         'effect_transition_applied_in_shadow_mode'
       or v_verified ->> 'effect_status' <> 'verified'
       or v_verified ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Prize ordered verified transition failed: %',
        v_verified;
    end if;

  exception
    when others then
      v_error_message := sqlstate || ': ' || sqlerrm;

      v_failed :=
        public.race_engine_transition_stage_effect_v2(
          p_stage_id,
          'prize_awards',
          'failed',
          null,
          jsonb_build_object(
            'a11_adapter_version',
              'phase3ac_a11_prize_awards_ordered_adapter_v1',
            'process_run_id', p_process_run_id,
            'execution_mode', 'rollback_shadow_only',
            'writer_or_verification_error', v_error_message,
            'error_message', v_error_message
          ),
          true,
          'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
        );

      return jsonb_build_object(
        'status',
          'prize_awards_ordered_effect_failed_in_shadow_mode',
        'stage_id', p_stage_id,
        'process_run_id', p_process_run_id,
        'error_message', v_error_message,
        'failed_transition', v_failed,
        'canonical_writer_called',
          v_started ->> 'effect_status' = 'started',
        'writer_mutations_from_failed_inner_block_rolled_back', true,
        'effect_transition_count',
          case
            when v_failed ->> 'effect_status' = 'failed' then 2
            else 1
          end,
        'production_writer_execution_enabled', false
      );
  end;

  return jsonb_build_object(
    'status',
      'prize_awards_applied_and_verified_in_rollback_shadow_mode',
    'stage_id', p_stage_id,
    'race_id', v_race_id,
    'process_run_id', p_process_run_id,
    'effect_key', 'prize_awards',
    'effect_order', 2,
    'source_payload_hash', v_source_hash,
    'applied_payload_hash', v_output_hash,
    'is_final_stage', v_is_final_stage,
    'output_evidence', v_output,
    'started_transition', v_started,
    'applied_transition', v_applied,
    'verified_transition', v_verified,
    'canonical_writer_called', true,
    'effect_transition_count', 3,
    'execution_mode', 'rollback_shadow_only',
    'production_writer_execution_enabled', false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_prize_payment_ordered_plan_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_process public.race_engine_stage_process_runs_v2%rowtype;
  v_payment_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_prize_effect public.race_engine_stage_effect_ledger_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;

  v_legacy jsonb;
  v_source jsonb;
  v_output jsonb;
  v_prize_output jsonb;
  v_manifest jsonb;
  v_adapter jsonb;

  v_process_found boolean := false;
  v_process_exact boolean := false;
  v_payment_effect_found boolean := false;
  v_prize_effect_found boolean := false;
  v_downstream_effect_count integer := 0;

  v_rollback_test_only_base boolean := false;
  v_rollback_test_only_pre_execution boolean := false;
  v_rollback_test_only_duplicate boolean := false;
  v_rollback_test_only boolean := false;

  v_status text;
  v_result jsonb;
begin
  select *
  into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key = 'prize_payment';

  if not found then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_high_risk_contract_missing',
      'stage_id',
        p_stage_id,
      'payment_writer_called',
        false,
      'production_execution_enabled',
        false
    );
  end if;

  v_legacy :=
    public.race_engine_get_stage_prize_payment_adapter_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  v_source :=
    public.race_engine_get_stage_prize_payment_source_evidence_v2(
      p_stage_id
    );

  v_output :=
    public.race_engine_get_stage_prize_payment_output_evidence_v2(
      p_stage_id
    );

  v_prize_output :=
    public.race_engine_get_stage_prize_award_snapshot_v2(
      p_stage_id
    );

  v_manifest :=
    public.race_engine_get_stage_effect_writer_adapter_plan_v2(
      p_stage_id
    );

  select adapter.value
  into v_adapter
  from jsonb_array_elements(
    coalesce(v_manifest -> 'adapters', '[]'::jsonb)
  ) adapter(value)
  where adapter.value ->> 'effect_key' = 'prize_payment'
  limit 1;

  if p_process_run_id is not null then
    select *
    into v_process
    from public.race_engine_stage_process_runs_v2
    where process_run_id = p_process_run_id;

    v_process_found := found;

    if v_process_found then
      v_process_exact :=
        v_process.stage_id = p_stage_id
        and v_process.race_id =
            nullif(v_source ->> 'race_id', '')::uuid
        and v_process.simulation_run_id is not distinct from
            nullif(v_legacy ->> 'simulation_run_id', '')::uuid
        and v_process.status = 'started'
        and v_process.finished_at is null
        and not v_process.requested_dry_run;
    end if;
  end if;

  select *
  into v_payment_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = 'prize_payment';

  v_payment_effect_found := found;

  select *
  into v_prize_effect
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = 'prize_awards';

  v_prize_effect_found := found;

  select count(*)::integer
  into v_downstream_effect_count
  from public.race_engine_stage_effect_ledger_v2
  where stage_id = p_stage_id
    and effect_key = any(
          v_contract.forbid_regeneration_after_effect_keys
        )
    and effect_status in (
          'started',
          'applied',
          'verified',
          'skipped'
        );

  select *
  into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key = 'ordered_effect_adapters';

  select *
  into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key = 'prize_payment';

  /*
   * Rollback-test-only base identity. This is intentionally narrower than the
   * normal execution contract and is valid only for one exact synthetic
   * process on Tour del Solis Stage 2.
   */
  v_rollback_test_only_base :=
    p_stage_id =
      '165d71b8-d823-451b-be66-cb0fc52c3811'::uuid
    and v_process_found
    and v_process_exact
    and v_process.processor_version =
        'phase3ac_a11_branch04_prize_payment_rollback_shadow_matrix_v1'
    and v_process.confirmation_text_hash =
        md5(
          'CONFIRM_PHASE3AC_A11_BRANCH04_PRIZE_PAYMENT_ROLLBACK_TEST_ONLY'
        )
    and v_process.metadata ->>
          'prize_payment_rollback_test_only' = 'true'
    and v_process.metadata ->>
          'rollback_test_contract_version' =
          'phase3ac_a11_prize_payment_rollback_test_only_v1'
    and v_process.metadata ->>
          'payment_source_payload_hash' =
          'df3c73fb8c81dee9916d564ecf8aba30'
    and v_process.metadata ->>
          'manifest_source_payload_hash' =
          'e90c3dd95ea888fdda545af43cf3e649'
    and v_process.metadata ->>
          'paid_manifest_source_policy' =
          'dynamic_current_adapter_hash_after_verified_finance'
    and v_process.metadata ->>
          'existing_prize_identity_hash' =
          '9cb81f6e95919fd87dc91098813c4655'
    and v_process.metadata ->>
          'existing_prize_semantic_hash' =
          '4f85b320c0d0b80a2c8660f034a8b3ac'
    and v_process.metadata ->>
          'prize_awards_source_payload_hash' =
          '23e13e643a0a64447d0375ded1e5ddb0'
    and v_process.metadata ->>
          'prize_awards_applied_payload_hash' =
          '4f85b320c0d0b80a2c8660f034a8b3ac'
    and v_process.metadata ->>
          'service_role_claim_method' =
          'transaction_local_request_jwt_claim_role'
    and v_process.metadata ->>
          'physical_prize_award_id_is_payment_identity' = 'true'
    and v_process.metadata ->> 'repayment_allowed' = 'false'
    and v_adapter is not null
    and v_prize_effect_found
    and v_prize_effect.effect_status = 'verified'
    and v_prize_effect.source_payload_hash =
        '23e13e643a0a64447d0375ded1e5ddb0'
    and v_prize_effect.applied_payload_hash =
        '4f85b320c0d0b80a2c8660f034a8b3ac'
    and v_payment_effect_found
    and v_payment_effect.source_payload_hash =
        'df3c73fb8c81dee9916d564ecf8aba30'
    and v_source ->> 'race_id' =
        '505db435-ecb9-463d-b946-1158c549a8c9'
    and v_source ->> 'route_format' = 'road_race'
    and v_source ->> 'stage_process_status' =
        'future_execution_candidate'
    and v_downstream_effect_count = 0;

  v_rollback_test_only_pre_execution :=
    v_rollback_test_only_base
    and v_adapter ->> 'source_payload_hash' =
        'e90c3dd95ea888fdda545af43cf3e649'
    and v_legacy ->> 'status' =
        'blocked_process_run_not_execution_capable'
    and v_source ->> 'status' =
        'source_ready_all_pending'
    and v_source ->> 'source_payload_hash' =
        'df3c73fb8c81dee9916d564ecf8aba30'
    and (v_source ->> 'award_row_count')::integer = 10
    and (v_source ->> 'payable_pending_row_count')::integer = 10
    and (v_source ->> 'paid_row_count')::integer = 0
    and (v_source ->> 'total_amount_cash')::bigint = 8751
    and v_output ->> 'status' =
        'unpaid_no_finance_evidence'
    and (v_output ->> 'award_row_count')::integer = 10
    and (v_output ->> 'paid_row_count')::integer = 0
    and (v_output ->> 'exactly_one_lock_count')::integer = 0
    and (v_output ->> 'duplicate_lock_count')::integer = 0
    and (v_output ->> 'linked_prize_transaction_count')::integer = 0
    and (v_output ->> 'fully_valid_finance_row_count')::integer = 0
    and (v_output ->> 'total_prize_amount_cash')::bigint = 8751
    and (v_output ->> 'total_paid_amount_cash')::bigint = 0
    and (v_output ->> 'total_gross_finance_credit')::bigint = 0
    and coalesce(
          (
            v_output
              ->> 'physical_award_id_is_finance_identity'
          )::boolean,
          false
        )
    and (v_prize_output ->> 'row_count')::integer = 10
    and (v_prize_output ->> 'pending_row_count')::integer = 10
    and (v_prize_output ->> 'paid_row_count')::integer = 0
    and (v_prize_output ->> 'total_amount_cash')::bigint = 8751
    and v_prize_output ->> 'identity_hash' =
        '9cb81f6e95919fd87dc91098813c4655'
    and v_prize_output ->> 'semantic_hash' =
        '4f85b320c0d0b80a2c8660f034a8b3ac'
    and v_payment_effect.effect_status = 'planned'
    and v_payment_effect.applied_payload_hash is null;

  v_rollback_test_only_duplicate :=
    v_rollback_test_only_base
    and nullif(v_adapter ->> 'source_payload_hash', '') is not null
    and v_adapter ->> 'source_payload_hash'
        is distinct from
        'e90c3dd95ea888fdda545af43cf3e649'
    and v_adapter ->> 'source_payload_hash'
        is distinct from
        'df3c73fb8c81dee9916d564ecf8aba30'
    and v_legacy ->> 'status' in (
          'historical_verify_only_paid_finance_verified',
          'blocked_process_run_not_execution_capable'
        )
    and v_source ->> 'status' =
        'source_historical_all_paid'
    and (v_source ->> 'award_row_count')::integer = 10
    and (v_source ->> 'payable_pending_row_count')::integer = 0
    and (v_source ->> 'paid_row_count')::integer = 10
    and (v_source ->> 'total_amount_cash')::bigint = 8751
    and v_output ->> 'status' =
        'paid_finance_evidence_complete'
    and (v_output ->> 'award_row_count')::integer = 10
    and (v_output ->> 'paid_row_count')::integer = 10
    and (v_output ->> 'exactly_one_lock_count')::integer = 10
    and (v_output ->> 'duplicate_lock_count')::integer = 0
    and (v_output ->> 'linked_prize_transaction_count')::integer = 10
    and (v_output ->> 'fully_valid_finance_row_count')::integer = 10
    and (v_output ->> 'invalid_finance_row_count')::integer = 0
    and (v_output ->> 'total_prize_amount_cash')::bigint = 8751
    and (v_output ->> 'total_paid_amount_cash')::bigint = 8751
    and (v_output ->> 'total_gross_finance_credit')::bigint = 8751
    and coalesce(
          (
            v_output
              ->> 'physical_award_id_is_finance_identity'
          )::boolean,
          false
        )
    and nullif(
          v_output ->> 'finance_evidence_hash',
          ''
        ) is not null
    and v_payment_effect.effect_status = 'verified'
    and v_payment_effect.applied_payload_hash =
        v_output ->> 'finance_evidence_hash';

  v_rollback_test_only :=
    v_rollback_test_only_pre_execution
    or v_rollback_test_only_duplicate;

  /*
   * Historical states are never adopted into a new payment effect.
   * They remain verify-only or manual-review exactly as the legacy plan says.
   */
  if v_legacy ->> 'status' in (
       'stage_not_found',
       'blocked_prize_payment_adapter_config_missing',
       'historical_verify_only_golden_fixture',
       'historical_verify_only_paid_finance_verified',
       'historical_paid_finance_inconsistent_manual_review',
       'historical_verify_only_unpaid_prizes_not_paid',
       'historical_verify_only_completed_stage_missing_prizes',
       'blocked_prize_payment_function_definition_drift',
       'blocked_unsupported_route'
     )
     and not v_rollback_test_only
  then
    v_status := v_legacy ->> 'status';

  elsif v_source ->> 'status' = 'stage_not_found' then
    v_status := 'stage_not_found';

  elsif v_adapter is null then
    v_status := 'blocked_prize_payment_manifest_adapter_missing';

  elsif not coalesce(
          (v_adapter ->> 'required_for_route')::boolean,
          false
        )
  then
    v_status := 'route_skipped_prize_payment_not_required';

  elsif v_source ->> 'status' =
        'source_not_ready_no_prize_awards'
  then
    v_status := 'source_not_ready_no_prize_awards';

  elsif v_source ->> 'status' in (
          'source_invalid_missing_payment_club',
          'source_invalid_nonpositive_prize_amount',
          'source_mixed_payment_state'
        )
  then
    v_status := 'blocked_prize_payment_source_invalid';

  /*
   * A completed verified payment is a strict saved-evidence duplicate.
   * Repayment is never considered.
   */
  elsif v_payment_effect_found
        and v_payment_effect.effect_status = 'verified'
        and v_output ->> 'status' =
            'paid_finance_evidence_complete'
        and v_payment_effect.applied_payload_hash
            is not distinct from
            v_output ->> 'finance_evidence_hash'
  then
    v_status := 'duplicate_verified_effect_saved_evidence';

  elsif v_output ->> 'status' =
        'paid_finance_evidence_complete'
  then
    v_status :=
      'blocked_existing_paid_finance_evidence_without_verified_effect';

  elsif v_output ->> 'status' <>
        'unpaid_no_finance_evidence'
  then
    v_status := 'blocked_existing_payment_finance_evidence';

  elsif v_source ->> 'status' <>
        'source_ready_all_pending'
  then
    v_status := 'blocked_prize_payment_source_not_all_pending';

  elsif v_adapter ->> 'source_payload_hash'
        is distinct from
        v_source ->> 'source_payload_hash'
        and not v_rollback_test_only
  then
    v_status := 'blocked_prize_payment_source_contract_mismatch';

  elsif v_downstream_effect_count > 0 then
    v_status := 'blocked_prize_payment_downstream_effect_already_started';

  elsif not v_prize_effect_found
        or v_prize_effect.effect_status <> 'verified'
        or v_prize_effect.applied_payload_hash is null
  then
    v_status := 'blocked_verified_prize_awards_effect_required';

  /*
   * Before payment, the verified prize-awards semantic output must still match
   * the current unpaid prize rows. This check is intentionally skipped in the
   * verified duplicate branch because payment changes status/paid_at.
   */
  elsif v_prize_effect.applied_payload_hash
        is distinct from
        v_prize_output ->> 'semantic_hash'
  then
    v_status := 'blocked_prize_awards_predecessor_output_mismatch';

  elsif not v_process_found then
    v_status := 'blocked_prize_payment_process_run_required';

  elsif not v_process_exact then
    v_status := 'blocked_prize_payment_process_identity_mismatch';

  elsif not v_payment_effect_found then
    v_status := 'blocked_prize_payment_effect_reservation_required';

  elsif v_payment_effect.effect_status <> 'planned' then
    v_status := 'blocked_prize_payment_effect_not_planned';

  elsif v_payment_effect.source_payload_hash
        is distinct from
        v_source ->> 'source_payload_hash'
  then
    v_status := 'blocked_prize_payment_reserved_source_hash_mismatch';

  elsif not coalesce(v_contract.shadow_execution_enabled, false)
        and not coalesce(v_contract.production_execution_enabled, false)
  then
    v_status := 'blocked_prize_payment_ordered_execution_disabled';

  elsif not coalesce(
          v_global.adapter_shadow_execution_enabled,
          false
        )
        and not coalesce(
          v_global.production_writer_execution_enabled,
          false
        )
  then
    v_status := 'blocked_prize_payment_global_execution_disabled';

  elsif not coalesce(v_state.shadow_execution_enabled, false)
        and not coalesce(v_state.production_execution_enabled, false)
  then
    v_status := 'blocked_prize_payment_effect_execution_disabled';

  else
    v_status := 'ready_for_prize_payment_ordered_execution';
  end if;

  v_result :=
    jsonb_build_object(
      'plan_version',
        'phase3ac_a11_prize_payment_ordered_plan_v1',
      'status',
        v_status,
      'stage_id',
        p_stage_id,
      'race_id',
        v_source ->> 'race_id',
      'simulation_run_id',
        v_legacy ->> 'simulation_run_id',
      'route_format',
        v_source ->> 'route_format',
      'stage_process_status',
        v_source ->> 'stage_process_status',
      'canonical_source_payload_hash',
        v_source ->> 'source_payload_hash',
      'manifest_source_payload_hash',
        v_adapter ->> 'source_payload_hash',
      'source_contract_matches',
        v_adapter ->> 'source_payload_hash'
        is not distinct from
        v_source ->> 'source_payload_hash',
      'reservation_source_payload_hash',
        v_source ->> 'source_payload_hash',
      'source_evidence',
        v_source,
      'output_evidence',
        v_output,
      'current_prize_output_evidence',
        v_prize_output,
      'process_run',
        jsonb_build_object(
          'requested_process_run_id',
            p_process_run_id,
          'found',
            v_process_found,
          'exact_active_identity',
            v_process_exact
        ),
      'predecessor_effect',
        case
          when v_prize_effect_found then
            jsonb_build_object(
              'effect_key',
                'prize_awards',
              'effect_id',
                v_prize_effect.effect_id,
              'effect_status',
                v_prize_effect.effect_status,
              'source_payload_hash',
                v_prize_effect.source_payload_hash,
              'applied_payload_hash',
                v_prize_effect.applied_payload_hash,
              'current_prize_semantic_hash',
                v_prize_output ->> 'semantic_hash'
            )
          else null
        end,
      'effect_ledger',
        case
          when v_payment_effect_found then
            jsonb_build_object(
              'effect_id',
                v_payment_effect.effect_id,
              'effect_status',
                v_payment_effect.effect_status,
              'idempotency_key',
                v_payment_effect.idempotency_key,
              'source_payload_hash',
                v_payment_effect.source_payload_hash,
              'applied_payload_hash',
                v_payment_effect.applied_payload_hash
            )
          else null
        end,
      'downstream_effect_count',
        v_downstream_effect_count,
      'expected_output_policy',
        'paid_finance_evidence_complete_with_physical_award_identity',
      'applied_payload_hash_policy',
        'finance_evidence_hash',
      'physical_prize_award_id_is_payment_identity',
        true,
      'repayment_allowed',
        false,
      'rollback_test_only_contract_active',
        v_rollback_test_only,
      'rollback_test_only_contract_version',
        case
          when v_rollback_test_only then
            'phase3ac_a11_prize_payment_rollback_test_only_v1'
          else null
        end,
      'rollback_test_only_pre_execution_state',
        v_rollback_test_only_pre_execution,
      'rollback_test_only_verified_duplicate_state',
        v_rollback_test_only_duplicate,
      'rollback_test_only_current_manifest_source_hash',
        case
          when v_rollback_test_only then
            v_adapter ->> 'source_payload_hash'
          else null
        end,
      'rollback_test_only_paid_manifest_source_policy',
        case
          when v_rollback_test_only then
            'dynamic_current_adapter_hash_after_verified_finance'
          else null
        end,
      'rollback_test_only_manifest_hash_is_state_sensitive',
        true,
      'rollback_test_only_manifest_mismatch_bypass_applied',
        v_rollback_test_only
        and v_adapter ->> 'source_payload_hash'
            is distinct from
            v_source ->> 'source_payload_hash',
      'rollback_test_only_service_role_claim_required',
        v_rollback_test_only,
      'rollback_test_only_never_production',
        true,
      'payment_writer_called',
        false,
      'production_execution_enabled',
        false
    );

  return
    v_result
    ||
    jsonb_build_object(
      'plan_hash',
        md5(v_result::text),
      'generated_at',
        clock_timestamp()
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_prize_payment_ordered_adapter_v2(p_stage_id uuid, p_process_run_id uuid DEFAULT NULL::uuid, p_execute boolean DEFAULT false, p_confirmation_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'auth', 'pg_temp'
AS $function$
declare
  v_contract public.race_engine_high_risk_writer_contract_v2%rowtype;
  v_global public.race_engine_effect_adapter_execution_config_v2%rowtype;
  v_state public.race_engine_effect_adapter_execution_state_v2%rowtype;
  v_a10 public.race_engine_effect_immutable_config_v2%rowtype;

  v_plan jsonb;
  v_locked_plan jsonb;
  v_source_before jsonb;
  v_source_after jsonb;
  v_output jsonb;
  v_payment_result jsonb;

  v_started jsonb;
  v_applied jsonb;
  v_verified jsonb;
  v_failed jsonb;

  v_race_id uuid;
  v_source_hash text;
  v_output_hash text;
  v_expected_paid_count integer;
  v_expected_total_cash bigint;
  v_error_message text;
begin
  if public.race_engine_verify_golden_stage_fixture_v1(
       'rio_tour_stage1_phase3aa_golden_v1'
     ) ->> 'status' <> 'fixture_matches_current_state'
  then
    return jsonb_build_object(
      'status',
        'blocked_golden_fixture_mismatch',
      'stage_id',
        p_stage_id,
      'canonical_writer_called',
        false,
      'effect_transition_count',
        0,
      'production_writer_execution_enabled',
        false
    );
  end if;

  v_plan :=
    public.race_engine_get_prize_payment_ordered_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  if not coalesce(p_execute, false) then
    return jsonb_build_object(
      'status',
        'dry_run_prize_payment_ordered_plan',
      'stage_id',
        p_stage_id,
      'process_run_id',
        p_process_run_id,
      'plan',
        v_plan,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'effect_ledger_changed',
        false,
      'production_writer_execution_enabled',
        false
    );
  end if;

  if v_plan ->> 'status' =
       'duplicate_verified_effect_saved_evidence'
  then
    return jsonb_build_object(
      'status',
        'duplicate_verified_effect_saved_evidence',
      'stage_id',
        p_stage_id,
      'process_run_id',
        p_process_run_id,
      'saved_effect_evidence',
        v_plan -> 'effect_ledger',
      'output_evidence',
        v_plan -> 'output_evidence',
      'physical_prize_award_id_is_payment_identity',
        true,
      'repayment_allowed',
        false,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'effect_ledger_changed',
        false,
      'production_writer_execution_enabled',
        false
    );
  end if;

  if v_plan ->> 'status' <>
       'ready_for_prize_payment_ordered_execution'
  then
    return jsonb_build_object(
      'status',
        v_plan ->> 'status',
      'stage_id',
        p_stage_id,
      'process_run_id',
        p_process_run_id,
      'plan',
        v_plan,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'effect_ledger_changed',
        false,
      'production_writer_execution_enabled',
        false
    );
  end if;

  select *
  into v_contract
  from public.race_engine_high_risk_writer_contract_v2
  where effect_key = 'prize_payment';

  select *
  into v_global
  from public.race_engine_effect_adapter_execution_config_v2
  where config_key = 'ordered_effect_adapters';

  select *
  into v_state
  from public.race_engine_effect_adapter_execution_state_v2
  where registry_version =
        'phase3ac_a11_ordered_effect_adapter_registry_v1'
    and effect_key = 'prize_payment';

  select *
  into v_a10
  from public.race_engine_effect_immutable_config_v2
  where config_key = 'effect_immutable';

  if coalesce(v_contract.production_execution_enabled, false)
     or coalesce(v_global.production_writer_execution_enabled, false)
     or coalesce(v_state.production_execution_enabled, false)
     or coalesce(v_a10.production_effect_transition_enabled, false)
  then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_production_cutover_not_supported',
      'stage_id',
        p_stage_id,
      'canonical_writer_called',
        false,
      'effect_transition_count',
        0,
      'production_writer_execution_enabled',
        false
    );
  end if;

  if not coalesce(v_contract.shadow_execution_enabled, false)
     or not coalesce(v_global.adapter_shadow_execution_enabled, false)
     or not (
       'prize_payment' = any(
         coalesce(v_global.allowed_shadow_effect_keys, '{}'::text[])
       )
     )
     or not coalesce(v_state.shadow_execution_enabled, false)
     or not coalesce(v_a10.transition_shadow_execution_enabled, false)
  then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_ordered_execution_disabled',
      'stage_id',
        p_stage_id,
      'process_run_id',
        p_process_run_id,
      'plan_status',
        v_plan ->> 'status',
      'execution',
        jsonb_build_object(
          'contract_shadow_execution_enabled',
            coalesce(v_contract.shadow_execution_enabled, false),
          'global_shadow_execution_enabled',
            coalesce(v_global.adapter_shadow_execution_enabled, false),
          'effect_allowed_for_shadow',
            'prize_payment' = any(
              coalesce(
                v_global.allowed_shadow_effect_keys,
                '{}'::text[]
              )
            ),
          'effect_state_shadow_execution_enabled',
            coalesce(v_state.shadow_execution_enabled, false),
          'a10_transition_shadow_execution_enabled',
            coalesce(
              v_a10.transition_shadow_execution_enabled,
              false
            )
        ),
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'effect_ledger_changed',
        false,
      'production_writer_execution_enabled',
        false
    );
  end if;

  if md5(coalesce(p_confirmation_text, '')) is distinct from
     nullif(
       v_contract.metadata
       ->> 'ordered_wrapper_confirmation_hash',
       ''
     )
  then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_ordered_confirmation_mismatch',
      'stage_id',
        p_stage_id,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'production_writer_execution_enabled',
        false
    );
  end if;

  /*
   * The finance primitive performs its own auth.role() service-role check.
   * Expose the same requirement before starting the effect.
   */
  if coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_service_role_required',
      'stage_id',
        p_stage_id,
      'observed_auth_role',
        nullif(coalesce(auth.role(), ''), ''),
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'effect_ledger_changed',
        false,
      'production_writer_execution_enabled',
        false
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'phase3ac:a11:b04:prize-payment:' || p_stage_id::text,
      0
    )
  );

  v_locked_plan :=
    public.race_engine_get_prize_payment_ordered_plan_v2(
      p_stage_id,
      p_process_run_id
    );

  if v_locked_plan ->> 'status' <>
       'ready_for_prize_payment_ordered_execution'
  then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_plan_changed_after_lock',
      'locked_plan_status',
        v_locked_plan ->> 'status',
      'locked_plan',
        v_locked_plan,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'production_writer_execution_enabled',
        false
    );
  end if;

  v_race_id :=
    nullif(v_locked_plan ->> 'race_id', '')::uuid;

  v_source_hash :=
    v_locked_plan ->> 'canonical_source_payload_hash';

  v_source_before :=
    v_locked_plan -> 'source_evidence';

  v_expected_paid_count :=
    coalesce(
      (
        v_source_before
        ->> 'payable_pending_row_count'
      )::integer,
      0
    );

  v_expected_total_cash :=
    coalesce(
      (
        v_source_before
        ->> 'total_amount_cash'
      )::bigint,
      0
    );

  if v_expected_paid_count <= 0
     or v_expected_total_cash <= 0
  then
    return jsonb_build_object(
      'status',
        'blocked_prize_payment_invalid_expected_payment_scope',
      'stage_id',
        p_stage_id,
      'source_evidence',
        v_source_before,
      'canonical_writer_called',
        false,
      'finance_primitive_called_directly',
        false,
      'effect_transition_count',
        0,
      'production_writer_execution_enabled',
        false
    );
  end if;

  v_started :=
    public.race_engine_transition_stage_effect_v2(
      p_stage_id,
      'prize_payment',
      'started',
      null,
      jsonb_build_object(
        'a11_adapter_version',
          'phase3ac_a11_prize_payment_ordered_adapter_v1',
        'process_run_id',
          p_process_run_id,
        'execution_mode',
          'rollback_shadow_only',
        'writer_called',
          false,
        'source_payload_hash',
          v_source_hash,
        'expected_paid_count',
          v_expected_paid_count,
        'expected_total_cash',
          v_expected_total_cash,
        'physical_prize_award_id_is_payment_identity',
          true,
        'repayment_allowed',
          false
      ),
      true,
      'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
    );

  if v_started ->> 'status' <>
       'effect_transition_applied_in_shadow_mode'
     or v_started ->> 'effect_status' <> 'started'
  then
    raise exception
      'Prize-payment ordered started transition failed: %',
      v_started;
  end if;

  begin
    v_payment_result :=
      public.race_engine_pay_prize_awards_v1(
        v_race_id,
        p_stage_id
      );

    if v_payment_result ->> 'status' <> 'completed'
       or (
            v_payment_result ->> 'paid_count'
          )::integer <> v_expected_paid_count
       or (
            v_payment_result ->> 'total_cash_paid'
          )::bigint <> v_expected_total_cash
    then
      raise exception
        'Prize-payment canonical writer result verification failed: %',
        v_payment_result;
    end if;

    v_source_after :=
      public.race_engine_get_stage_prize_payment_source_evidence_v2(
        p_stage_id
      );

    if v_source_after ->> 'status' <>
         'source_historical_all_paid'
       or (
            v_source_after ->> 'paid_row_count'
          )::integer <> v_expected_paid_count
       or (
            v_source_after ->> 'pending_row_count'
          )::integer <> 0
       or (
            v_source_after ->> 'total_amount_cash'
          )::bigint <> v_expected_total_cash
    then
      raise exception
        'Prize-payment source-after verification failed: %',
        v_source_after;
    end if;

    v_output :=
      public.race_engine_get_stage_prize_payment_output_evidence_v2(
        p_stage_id
      );

    if v_output ->> 'status' <>
         'paid_finance_evidence_complete'
       or (
            v_output ->> 'award_row_count'
          )::integer <> v_expected_paid_count
       or (
            v_output ->> 'paid_row_count'
          )::integer <> v_expected_paid_count
       or (
            v_output ->> 'exactly_one_lock_count'
          )::integer <> v_expected_paid_count
       or (
            v_output ->> 'duplicate_lock_count'
          )::integer <> 0
       or (
            v_output ->> 'linked_prize_transaction_count'
          )::integer <> v_expected_paid_count
       or (
            v_output ->> 'fully_valid_finance_row_count'
          )::integer <> v_expected_paid_count
       or (
            v_output ->> 'invalid_finance_row_count'
          )::integer <> 0
       or (
            v_output ->> 'total_prize_amount_cash'
          )::bigint <> v_expected_total_cash
       or (
            v_output ->> 'total_paid_amount_cash'
          )::bigint <> v_expected_total_cash
       or (
            v_output ->> 'total_gross_finance_credit'
          )::bigint <> v_expected_total_cash
       or not coalesce(
            (
              v_output
              ->> 'physical_award_id_is_finance_identity'
            )::boolean,
            false
          )
       or nullif(
            v_output ->> 'finance_evidence_hash',
            ''
          ) is null
    then
      raise exception
        'Prize-payment finance output verification failed: %',
        v_output;
    end if;

    v_output_hash :=
      v_output ->> 'finance_evidence_hash';

    v_applied :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'prize_payment',
        'applied',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_prize_payment_ordered_adapter_v1',
          'process_run_id',
            p_process_run_id,
          'execution_mode',
            'rollback_shadow_only',
          'writer_called',
            true,
          'source_payload_hash',
            v_source_hash,
          'payment_result',
            v_payment_result,
          'source_after_payment',
            v_source_after,
          'finance_output_evidence',
            v_output,
          'physical_prize_award_id_is_payment_identity',
            true,
          'repayment_allowed',
            false
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_applied ->> 'status' <>
         'effect_transition_applied_in_shadow_mode'
       or v_applied ->> 'effect_status' <> 'applied'
       or v_applied ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Prize-payment ordered applied transition failed: %',
        v_applied;
    end if;

    v_verified :=
      public.race_engine_transition_stage_effect_v2(
        p_stage_id,
        'prize_payment',
        'verified',
        v_output_hash,
        jsonb_build_object(
          'a11_adapter_version',
            'phase3ac_a11_prize_payment_ordered_adapter_v1',
          'process_run_id',
            p_process_run_id,
          'execution_mode',
            'rollback_shadow_only',
          'writer_called',
            true,
          'output_verified',
            true,
          'finance_output_evidence',
            v_output,
          'physical_prize_award_id_is_payment_identity',
            true,
          'repayment_allowed',
            false
        ),
        true,
        'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
      );

    if v_verified ->> 'status' <>
         'effect_transition_applied_in_shadow_mode'
       or v_verified ->> 'effect_status' <> 'verified'
       or v_verified ->> 'applied_payload_hash'
          is distinct from v_output_hash
    then
      raise exception
        'Prize-payment ordered verified transition failed: %',
        v_verified;
    end if;

  exception
    when others then
      v_error_message :=
        sqlstate || ': ' || sqlerrm;

      v_failed :=
        public.race_engine_transition_stage_effect_v2(
          p_stage_id,
          'prize_payment',
          'failed',
          null,
          jsonb_build_object(
            'a11_adapter_version',
              'phase3ac_a11_prize_payment_ordered_adapter_v1',
            'process_run_id',
              p_process_run_id,
            'execution_mode',
              'rollback_shadow_only',
            'writer_or_verification_error',
              v_error_message,
            'error_message',
              v_error_message,
            'writer_mutations_from_failed_inner_block_rolled_back',
              true,
            'physical_prize_award_id_is_payment_identity',
              true,
            'repayment_allowed',
              false
          ),
          true,
          'CONFIRM_PHASE3AC_A10_EFFECT_TRANSITION_ROLLBACK_SHADOW'
        );

      return jsonb_build_object(
        'status',
          'prize_payment_ordered_effect_failed_in_shadow_mode',
        'stage_id',
          p_stage_id,
        'process_run_id',
          p_process_run_id,
        'error_message',
          v_error_message,
        'failed_transition',
          v_failed,
        'canonical_writer_called',
          v_started ->> 'effect_status' = 'started',
        'finance_primitive_called_directly',
          false,
        'writer_mutations_from_failed_inner_block_rolled_back',
          true,
        'effect_transition_count',
          case
            when v_failed ->> 'effect_status' = 'failed'
              then 2
            else 1
          end,
        'production_writer_execution_enabled',
          false
      );
  end;

  return jsonb_build_object(
    'status',
      'prize_payment_applied_and_verified_in_rollback_shadow_mode',
    'stage_id',
      p_stage_id,
    'race_id',
      v_race_id,
    'process_run_id',
      p_process_run_id,
    'effect_key',
      'prize_payment',
    'effect_order',
      3,
    'source_payload_hash',
      v_source_hash,
    'applied_payload_hash',
      v_output_hash,
    'payment_result',
      v_payment_result,
    'source_after_payment',
      v_source_after,
    'output_evidence',
      v_output,
    'started_transition',
      v_started,
    'applied_transition',
      v_applied,
    'verified_transition',
      v_verified,
    'physical_prize_award_id_is_payment_identity',
      true,
    'repayment_allowed',
      false,
    'canonical_writer_called',
      true,
    'finance_primitive_called_directly',
      false,
    'effect_transition_count',
      3,
    'execution_mode',
      'rollback_shadow_only',
    'production_writer_execution_enabled',
      false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_enforce_replay_display_continuity_v5_exact(p_simulation_run_id uuid, p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_stage_id uuid;
  v_run_stage_id uuid;
  v_first_frame integer;
  v_last_frame integer;
  v_frame integer;
  v_group_row_count integer := 0;
  v_already_processed_count integer := 0;

  v_before_backward_count integer := 0;
  v_after_backward_count integer := 0;
  v_before_order_violation_count integer := 0;
  v_after_order_violation_count integer := 0;
  v_duplicate_track_key_count integer := 0;

  v_first_frame_rows_updated integer := 0;
  v_frame_matched_count integer := 0;
  v_frame_unmatched_count integer := 0;
  v_frame_km_clamp_count integer := 0;
  v_frame_maximum_km_clamp_adjustment numeric := 0;
  v_total_matched_rows integer := 0;
  v_total_unmatched_rows integer := 0;
  v_total_km_clamp_rows integer := 0;
  v_maximum_km_clamp_adjustment numeric := 0;

  v_stage_format text;
  v_apply_gap_continuity boolean := false;
  v_gap_frame integer;
  v_gap_frame_changed_count integer := 0;
  v_gap_frame_temporal_reduction_count integer := 0;
  v_gap_frame_spatial_reduction_count integer := 0;
  v_gap_frame_maximum_reduction numeric := 0;
  v_gap_changed_row_count integer := 0;
  v_gap_temporal_reduction_count integer := 0;
  v_gap_spatial_reduction_count integer := 0;
  v_gap_maximum_reduction_seconds numeric := 0;
  v_before_gap_closure_count integer := 0;
  v_after_gap_closure_count integer := 0;
  v_after_gap_order_violation_count integer := 0;
  v_gap_increase_count integer := 0;
  v_negative_gap_count integer := 0;
  v_final_frame_gap_change_count integer := 0;
  v_leader_gap_change_count integer := 0;
begin
  if p_simulation_run_id is null then
    raise exception using
      errcode = '22023',
      message = 'Simulation run ID is required.';
  end if;

  select simulation.stage_id
  into v_run_stage_id
  from public.race_stage_simulation_runs simulation
  where simulation.id = p_simulation_run_id;

  if v_run_stage_id is null then
    raise exception using
      errcode = '22023',
      message = format(
        'Simulation run %s does not exist.',
        p_simulation_run_id
      );
  end if;

  v_stage_id := coalesce(p_stage_id, v_run_stage_id);

  if v_stage_id is distinct from v_run_stage_id then
    raise exception using
      errcode = '22023',
      message = format(
        'Stage %s does not match simulation run %s stage %s.',
        v_stage_id,
        p_simulation_run_id,
        v_run_stage_id
      );
  end if;

  select lower(coalesce(stage.stage_format, ''))
  into v_stage_format
  from public.race_stages stage
  where stage.id = v_stage_id;

  v_apply_gap_continuity :=
    not (
      coalesce(v_stage_format, '') like '%trial%'
      or coalesce(v_stage_format, '') in (
        'itt',
        'ttt',
        'prologue'
      )
    );

  perform pg_advisory_xact_lock(
    hashtextextended(
      'race-engine:replay-display-continuity-v5:'
      || p_simulation_run_id::text,
      0
    )
  );

  select
    count(*)::integer,
    min(frame.frame_number)::integer,
    max(frame.frame_number)::integer,
    count(*) filter(
      where frame.metadata
            ->> 'replay_display_continuity_model'
            = 'mutual_best_rider_overlap_v5'
    )::integer
  into
    v_group_row_count,
    v_first_frame,
    v_last_frame,
    v_already_processed_count
  from public.race_stage_replay_frames frame
  where frame.simulation_run_id = p_simulation_run_id
    and frame.stage_id = v_stage_id
    and frame.entity_type = 'group';

  if v_group_row_count = 0 then
    return jsonb_build_object(
      'status', 'skipped_no_group_replay_rows',
      'simulation_run_id', p_simulation_run_id,
      'stage_id', v_stage_id,
      'updated_rows', 0,
      'km_clamp_rows', 0
    );
  end if;

  with sequenced as
  (
    select
      frame.id,
      frame.km_marker,
      lag(frame.km_marker) over(
        partition by
          frame.simulation_run_id,
          coalesce(
            nullif(frame.entity_key, ''),
            'row_id:' || frame.id::text
          )
        order by frame.frame_number, frame.id
      ) as previous_km_marker
    from public.race_stage_replay_frames frame
    where frame.simulation_run_id = p_simulation_run_id
      and frame.stage_id = v_stage_id
      and frame.entity_type = 'group'
  )
  select count(*)::integer
  into v_before_backward_count
  from sequenced
  where previous_km_marker is not null
    and km_marker < previous_km_marker - 0.001;

  with ordered as
  (
    select
      frame.id,
      frame.km_marker,
      lag(frame.km_marker) over(
        partition by
          frame.simulation_run_id,
          frame.frame_number
        order by
          frame.group_order nulls last,
          frame.km_marker desc,
          frame.id
      ) as preceding_group_km_marker
    from public.race_stage_replay_frames frame
    where frame.simulation_run_id = p_simulation_run_id
      and frame.stage_id = v_stage_id
      and frame.entity_type = 'group'
  )
  select count(*)::integer
  into v_before_order_violation_count
  from ordered
  where preceding_group_km_marker is not null
    and km_marker > preceding_group_km_marker + 0.001;

  if v_already_processed_count = v_group_row_count then
    return jsonb_build_object(
      'status', 'already_applied',
      'simulation_run_id', p_simulation_run_id,
      'stage_id', v_stage_id,
      'group_row_count', v_group_row_count,
      'backward_count', v_before_backward_count,
      'order_violation_count', v_before_order_violation_count
    );
  end if;

  drop table if exists pg_temp.replay_display_continuity_matches_v5;

  create temporary table replay_display_continuity_matches_v5
  (
    current_id uuid primary key,
    previous_id uuid not null unique,
    overlap_count integer not null,
    overlap_pct numeric
  )
  on commit drop;

  update public.race_stage_replay_frames frame
  set
    entity_key =
      'display_track_' || replace(frame.id::text, '-', ''),
    metadata =
      coalesce(frame.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'replay_display_continuity_v5', true,
        'replay_display_continuity_model',
          'mutual_best_rider_overlap_v5',
        'replay_display_continuity_original_entity_key',
          frame.entity_key,
        'replay_display_continuity_track_started', true,
        'replay_display_continuity_updated_at', now()
      )
  where frame.simulation_run_id = p_simulation_run_id
    and frame.stage_id = v_stage_id
    and frame.entity_type = 'group'
    and frame.frame_number = v_first_frame;

  get diagnostics v_first_frame_rows_updated = row_count;

  if v_last_frame > v_first_frame then
    for v_frame in
      v_first_frame + 1 .. v_last_frame
    loop
      truncate table pg_temp.replay_display_continuity_matches_v5;

      with candidates as
      (
        select
          current_frame.id as current_id,
          previous_frame.id as previous_id,
          current_frame.km_marker as current_km_marker,
          previous_frame.km_marker as previous_km_marker,
          current_frame.group_order as current_group_order,
          previous_frame.group_order as previous_group_order,
          cardinality(current_frame.rider_ids)
            as current_rider_count,
          cardinality(previous_frame.rider_ids)
            as previous_rider_count,
          (
            select count(*)::integer
            from (
              select unnest(
                coalesce(
                  current_frame.rider_ids,
                  '{}'::uuid[]
                )
              ) as rider_id
              intersect
              select unnest(
                coalesce(
                  previous_frame.rider_ids,
                  '{}'::uuid[]
                )
              ) as rider_id
            ) overlap_set
          ) as overlap_count
        from public.race_stage_replay_frames current_frame
        join public.race_stage_replay_frames previous_frame
          on previous_frame.simulation_run_id =
             current_frame.simulation_run_id
         and previous_frame.stage_id =
             current_frame.stage_id
         and previous_frame.entity_type = 'group'
         and previous_frame.frame_number =
             current_frame.frame_number - 1
        where current_frame.simulation_run_id =
              p_simulation_run_id
          and current_frame.stage_id = v_stage_id
          and current_frame.entity_type = 'group'
          and current_frame.frame_number = v_frame
      ),
      ranked as
      (
        select
          candidate.*,
          row_number() over(
            partition by candidate.current_id
            order by
              candidate.overlap_count desc,
              (
                candidate.overlap_count::numeric
                / nullif(
                    greatest(
                      coalesce(
                        candidate.current_rider_count,
                        0
                      ),
                      coalesce(
                        candidate.previous_rider_count,
                        0
                      )
                    ),
                    0
                  )
              ) desc nulls last,
              abs(
                candidate.current_km_marker
                - candidate.previous_km_marker
              ),
              abs(
                coalesce(
                  candidate.current_group_order,
                  999999
                )
                - coalesce(
                    candidate.previous_group_order,
                    999999
                  )
              ),
              candidate.previous_id
          )::integer as current_candidate_rank,
          row_number() over(
            partition by candidate.previous_id
            order by
              candidate.overlap_count desc,
              (
                candidate.overlap_count::numeric
                / nullif(
                    greatest(
                      coalesce(
                        candidate.current_rider_count,
                        0
                      ),
                      coalesce(
                        candidate.previous_rider_count,
                        0
                      )
                    ),
                    0
                  )
              ) desc nulls last,
              abs(
                candidate.current_km_marker
                - candidate.previous_km_marker
              ),
              abs(
                coalesce(
                  candidate.current_group_order,
                  999999
                )
                - coalesce(
                    candidate.previous_group_order,
                    999999
                  )
              ),
              candidate.current_id
          )::integer as previous_candidate_rank
        from candidates candidate
      )
      insert into pg_temp.replay_display_continuity_matches_v5
      (
        current_id,
        previous_id,
        overlap_count,
        overlap_pct
      )
      select
        ranked.current_id,
        ranked.previous_id,
        ranked.overlap_count,
        round(
          100.0 * ranked.overlap_count
          / nullif(
              greatest(
                coalesce(ranked.current_rider_count, 0),
                coalesce(ranked.previous_rider_count, 0)
              ),
              0
            ),
          2
        )
      from ranked
      where ranked.overlap_count > 0
        and ranked.current_candidate_rank = 1
        and ranked.previous_candidate_rank = 1;

      select
        count(*)::integer,
        count(*) filter(
          where current_frame.km_marker <
                previous_frame.km_marker - 0.001
        )::integer,
        coalesce(
          max(
            previous_frame.km_marker
            - current_frame.km_marker
          ) filter(
            where current_frame.km_marker <
                  previous_frame.km_marker - 0.001
          ),
          0
        )
      into
        v_frame_matched_count,
        v_frame_km_clamp_count,
        v_frame_maximum_km_clamp_adjustment
      from pg_temp.replay_display_continuity_matches_v5 match
      join public.race_stage_replay_frames current_frame
        on current_frame.id = match.current_id
      join public.race_stage_replay_frames previous_frame
        on previous_frame.id = match.previous_id;

      v_total_matched_rows :=
        v_total_matched_rows + v_frame_matched_count;

      v_total_km_clamp_rows :=
        v_total_km_clamp_rows + v_frame_km_clamp_count;

      v_maximum_km_clamp_adjustment :=
        greatest(
          v_maximum_km_clamp_adjustment,
          coalesce(v_frame_maximum_km_clamp_adjustment, 0)
        );

      update public.race_stage_replay_frames current_frame
      set
        entity_key = previous_frame.entity_key,
        km_marker =
          greatest(
            current_frame.km_marker,
            previous_frame.km_marker
          ),
        metadata =
          coalesce(current_frame.metadata, '{}'::jsonb)
          || jsonb_build_object(
            'replay_display_continuity_v5', true,
            'replay_display_continuity_model',
              'mutual_best_rider_overlap_v5',
            'replay_display_continuity_original_entity_key',
              current_frame.entity_key,
            'replay_display_continuity_original_km_marker',
              current_frame.km_marker,
            'replay_display_continuity_matched_previous_id',
              previous_frame.id,
            'replay_display_continuity_overlap_count',
              match.overlap_count,
            'replay_display_continuity_overlap_pct',
              match.overlap_pct,
            'replay_display_continuity_km_clamped',
              current_frame.km_marker
              < previous_frame.km_marker - 0.001,
            'replay_display_continuity_updated_at', now()
          )
      from pg_temp.replay_display_continuity_matches_v5 match
      join public.race_stage_replay_frames previous_frame
        on previous_frame.id = match.previous_id
      where current_frame.id = match.current_id;

      update public.race_stage_replay_frames current_frame
      set
        entity_key =
          'display_track_'
          || replace(current_frame.id::text, '-', ''),
        metadata =
          coalesce(current_frame.metadata, '{}'::jsonb)
          || jsonb_build_object(
            'replay_display_continuity_v5', true,
            'replay_display_continuity_model',
              'mutual_best_rider_overlap_v5',
            'replay_display_continuity_original_entity_key',
              current_frame.entity_key,
            'replay_display_continuity_track_started', true,
            'replay_display_continuity_updated_at', now()
          )
      where current_frame.simulation_run_id =
            p_simulation_run_id
        and current_frame.stage_id = v_stage_id
        and current_frame.entity_type = 'group'
        and current_frame.frame_number = v_frame
        and not exists(
          select 1
          from pg_temp.replay_display_continuity_matches_v5 match
          where match.current_id = current_frame.id
        );

      get diagnostics v_frame_unmatched_count = row_count;

      v_total_unmatched_rows :=
        v_total_unmatched_rows + v_frame_unmatched_count;
    end loop;
  end if;

  /*
   * Reverse final-frame-anchored gap continuity.
   *
   * The final frame remains immutable. Earlier frames are processed in
   * descending order so the already-safe next-frame gap provides the upper
   * bound for the same physical display track. A reverse cumulative minimum
   * then preserves non-decreasing same-frame gaps without inflating later
   * groups.
   */
  drop table if exists pg_temp.replay_gap_continuity_snapshot_v1;

  create temporary table replay_gap_continuity_snapshot_v1
  (
    id uuid primary key,
    frame_number integer not null,
    group_order integer,
    gap_seconds numeric not null
  )
  on commit drop;

  insert into pg_temp.replay_gap_continuity_snapshot_v1
  (
    id,
    frame_number,
    group_order,
    gap_seconds
  )
  select
    frame.id,
    frame.frame_number,
    frame.group_order,
    greatest(0, coalesce(frame.gap_seconds, 0))::numeric
  from public.race_stage_replay_frames frame
  where frame.simulation_run_id = p_simulation_run_id
    and frame.stage_id = v_stage_id
    and frame.entity_type = 'group';

  if v_apply_gap_continuity
     and v_last_frame > v_first_frame
  then
    select count(*)::integer
    into v_before_gap_closure_count
    from public.race_stage_replay_frames previous_frame
    join public.race_stage_replay_frames current_frame
      on current_frame.simulation_run_id =
         previous_frame.simulation_run_id
     and current_frame.stage_id =
         previous_frame.stage_id
     and current_frame.entity_type = 'group'
     and current_frame.frame_number =
         previous_frame.frame_number + 1
     and current_frame.entity_key =
         previous_frame.entity_key
    where previous_frame.simulation_run_id =
          p_simulation_run_id
      and previous_frame.stage_id = v_stage_id
      and previous_frame.entity_type = 'group'
      and greatest(
            0,
            coalesce(previous_frame.gap_seconds, 0)
          )
          - greatest(
              0,
              coalesce(current_frame.gap_seconds, 0)
            )
          > 30;

    for v_gap_frame in reverse
      (v_last_frame - 1) .. v_first_frame
    loop
      with temporal as
      (
        select
          current_frame.id,
          current_frame.group_order,
          greatest(
            0,
            coalesce(current_frame.gap_seconds, 0)
          )::numeric as raw_gap_seconds,

          case
            when next_frame.id is null then
              greatest(
                0,
                coalesce(current_frame.gap_seconds, 0)
              )::numeric
            else
              least(
                greatest(
                  0,
                  coalesce(current_frame.gap_seconds, 0)
                )::numeric,
                greatest(
                  0,
                  coalesce(next_frame.gap_seconds, 0)
                )::numeric + 30
              )
          end::numeric as temporal_safe_gap
        from public.race_stage_replay_frames current_frame
        left join public.race_stage_replay_frames next_frame
          on next_frame.simulation_run_id =
             current_frame.simulation_run_id
         and next_frame.stage_id =
             current_frame.stage_id
         and next_frame.entity_type = 'group'
         and next_frame.frame_number =
             current_frame.frame_number + 1
         and next_frame.entity_key =
             current_frame.entity_key
        where current_frame.simulation_run_id =
              p_simulation_run_id
          and current_frame.stage_id = v_stage_id
          and current_frame.entity_type = 'group'
          and current_frame.frame_number =
              v_gap_frame
      ),
      ordered as
      (
        select
          temporal.*,
          min(temporal.temporal_safe_gap) over(
            order by
              coalesce(temporal.group_order, 999999) desc,
              temporal.temporal_safe_gap desc,
              temporal.id desc
            rows between unbounded preceding
                 and current row
          )::numeric as safe_gap_seconds
        from temporal
      ),
      updated as
      (
        update public.race_stage_replay_frames frame
        set
          gap_seconds =
            floor(ordered.safe_gap_seconds)::integer,
          metadata =
            coalesce(frame.metadata, '{}'::jsonb)
            || jsonb_build_object(
              'replay_gap_continuity_applied', true,
              'replay_gap_continuity_model',
                'reverse_final_anchor_gap30_v1',
              'replay_gap_continuity_original_gap_seconds',
                ordered.raw_gap_seconds,
              'replay_gap_continuity_temporal_safe_gap_seconds',
                ordered.temporal_safe_gap,
              'replay_gap_continuity_safe_gap_seconds',
                ordered.safe_gap_seconds,
              'replay_gap_continuity_reduction_seconds',
                ordered.raw_gap_seconds
                - ordered.safe_gap_seconds,
              'replay_gap_continuity_temporal_reduction',
                ordered.temporal_safe_gap
                < ordered.raw_gap_seconds - 0.001,
              'replay_gap_continuity_spatial_reduction',
                ordered.safe_gap_seconds
                < ordered.temporal_safe_gap - 0.001,
              'replay_gap_continuity_updated_at',
                now()
            )
        from ordered
        where frame.id = ordered.id
          and ordered.safe_gap_seconds
              < greatest(
                  0,
                  coalesce(frame.gap_seconds, 0)
                ) - 0.001
        returning
          ordered.raw_gap_seconds,
          ordered.temporal_safe_gap,
          ordered.safe_gap_seconds
      )
      select
        count(*)::integer,
        count(*) filter(
          where updated.temporal_safe_gap
                < updated.raw_gap_seconds - 0.001
        )::integer,
        count(*) filter(
          where updated.safe_gap_seconds
                < updated.temporal_safe_gap - 0.001
        )::integer,
        coalesce(
          max(
            updated.raw_gap_seconds
            - updated.safe_gap_seconds
          ),
          0
        )::numeric
      into
        v_gap_frame_changed_count,
        v_gap_frame_temporal_reduction_count,
        v_gap_frame_spatial_reduction_count,
        v_gap_frame_maximum_reduction
      from updated;

      v_gap_changed_row_count :=
        v_gap_changed_row_count
        + v_gap_frame_changed_count;

      v_gap_temporal_reduction_count :=
        v_gap_temporal_reduction_count
        + v_gap_frame_temporal_reduction_count;

      v_gap_spatial_reduction_count :=
        v_gap_spatial_reduction_count
        + v_gap_frame_spatial_reduction_count;

      v_gap_maximum_reduction_seconds :=
        greatest(
          v_gap_maximum_reduction_seconds,
          coalesce(v_gap_frame_maximum_reduction, 0)
        );
    end loop;

    select count(*)::integer
    into v_after_gap_closure_count
    from public.race_stage_replay_frames previous_frame
    join public.race_stage_replay_frames current_frame
      on current_frame.simulation_run_id =
         previous_frame.simulation_run_id
     and current_frame.stage_id =
         previous_frame.stage_id
     and current_frame.entity_type = 'group'
     and current_frame.frame_number =
         previous_frame.frame_number + 1
     and current_frame.entity_key =
         previous_frame.entity_key
    where previous_frame.simulation_run_id =
          p_simulation_run_id
      and previous_frame.stage_id = v_stage_id
      and previous_frame.entity_type = 'group'
      and greatest(
            0,
            coalesce(previous_frame.gap_seconds, 0)
          )
          - greatest(
              0,
              coalesce(current_frame.gap_seconds, 0)
            )
          > 30;

    with ordered as
    (
      select
        frame.id,
        frame.gap_seconds,
        lag(frame.gap_seconds) over(
          partition by
            frame.simulation_run_id,
            frame.frame_number
          order by
            frame.group_order nulls last,
            frame.gap_seconds,
            frame.id
        ) as preceding_gap_seconds
      from public.race_stage_replay_frames frame
      where frame.simulation_run_id =
            p_simulation_run_id
        and frame.stage_id = v_stage_id
        and frame.entity_type = 'group'
    )
    select count(*)::integer
    into v_after_gap_order_violation_count
    from ordered
    where preceding_gap_seconds is not null
      and gap_seconds
          < preceding_gap_seconds;

    select
      count(*) filter(
        where current_frame.gap_seconds
              > snapshot.gap_seconds + 0.001
      )::integer,
      count(*) filter(
        where current_frame.gap_seconds < 0
      )::integer,
      count(*) filter(
        where snapshot.frame_number = v_last_frame
          and current_frame.gap_seconds
              is distinct from snapshot.gap_seconds
      )::integer,
      count(*) filter(
        where snapshot.group_order = 1
          and current_frame.gap_seconds
              is distinct from snapshot.gap_seconds
      )::integer
    into
      v_gap_increase_count,
      v_negative_gap_count,
      v_final_frame_gap_change_count,
      v_leader_gap_change_count
    from pg_temp.replay_gap_continuity_snapshot_v1 snapshot
    join public.race_stage_replay_frames current_frame
      on current_frame.id = snapshot.id;

    if v_after_gap_closure_count <> 0 then
      raise exception
        'Replay gap continuity left % physical closures above 30 seconds.',
        v_after_gap_closure_count;
    end if;

    if v_after_gap_order_violation_count <> 0 then
      raise exception
        'Replay gap continuity left % same-frame gap-order violations.',
        v_after_gap_order_violation_count;
    end if;

    if v_gap_increase_count <> 0 then
      raise exception
        'Replay gap continuity increased % raw replay gaps.',
        v_gap_increase_count;
    end if;

    if v_negative_gap_count <> 0 then
      raise exception
        'Replay gap continuity created % negative gaps.',
        v_negative_gap_count;
    end if;

    if v_final_frame_gap_change_count <> 0 then
      raise exception
        'Replay gap continuity changed % final-frame gaps.',
        v_final_frame_gap_change_count;
    end if;

    if v_leader_gap_change_count <> 0 then
      raise exception
        'Replay gap continuity changed % leader-group gaps.',
        v_leader_gap_change_count;
    end if;
  end if;

  with sequenced as
  (
    select
      frame.id,
      frame.km_marker,
      lag(frame.km_marker) over(
        partition by
          frame.simulation_run_id,
          frame.entity_key
        order by frame.frame_number, frame.id
      ) as previous_km_marker
    from public.race_stage_replay_frames frame
    where frame.simulation_run_id = p_simulation_run_id
      and frame.stage_id = v_stage_id
      and frame.entity_type = 'group'
  )
  select count(*)::integer
  into v_after_backward_count
  from sequenced
  where previous_km_marker is not null
    and km_marker < previous_km_marker - 0.001;

  select count(*)::integer
  into v_duplicate_track_key_count
  from (
    select
      frame.frame_number,
      frame.entity_key
    from public.race_stage_replay_frames frame
    where frame.simulation_run_id = p_simulation_run_id
      and frame.stage_id = v_stage_id
      and frame.entity_type = 'group'
    group by frame.frame_number, frame.entity_key
    having count(*) > 1
  ) duplicate_key;

  with ordered as
  (
    select
      frame.id,
      frame.km_marker,
      lag(frame.km_marker) over(
        partition by
          frame.simulation_run_id,
          frame.frame_number
        order by
          frame.group_order nulls last,
          frame.km_marker desc,
          frame.id
      ) as preceding_group_km_marker
    from public.race_stage_replay_frames frame
    where frame.simulation_run_id = p_simulation_run_id
      and frame.stage_id = v_stage_id
      and frame.entity_type = 'group'
  )
  select count(*)::integer
  into v_after_order_violation_count
  from ordered
  where preceding_group_km_marker is not null
    and km_marker > preceding_group_km_marker + 0.001;

  if v_after_backward_count <> 0 then
    raise exception
      'Replay display continuity v5 left % backward group-track transitions.',
      v_after_backward_count;
  end if;

  if v_duplicate_track_key_count <> 0 then
    raise exception
      'Replay display continuity v5 created % duplicate track-key buckets.',
      v_duplicate_track_key_count;
  end if;

  if v_after_order_violation_count >
     v_before_order_violation_count
  then
    raise exception
      'Replay display continuity v5 increased same-frame order violations from % to %.',
      v_before_order_violation_count,
      v_after_order_violation_count;
  end if;

  return jsonb_build_object(
    'status', 'replay_display_continuity_v5_applied',
    'simulation_run_id', p_simulation_run_id,
    'stage_id', v_stage_id,
    'group_row_count', v_group_row_count,
    'first_frame_number', v_first_frame,
    'last_frame_number', v_last_frame,
    'first_frame_rows_updated',
      v_first_frame_rows_updated,
    'matched_rows', v_total_matched_rows,
    'new_track_rows', v_total_unmatched_rows,
    'km_clamp_rows', v_total_km_clamp_rows,
    'maximum_km_clamp_adjustment',
      v_maximum_km_clamp_adjustment,
    'before_backward_count', v_before_backward_count,
    'after_backward_count', v_after_backward_count,
    'duplicate_track_key_count',
      v_duplicate_track_key_count,
    'before_order_violation_count',
      v_before_order_violation_count,
    'after_order_violation_count',
      v_after_order_violation_count,
    'gap_continuity_applied',
      v_apply_gap_continuity,
    'gap_continuity_model',
      case
        when v_apply_gap_continuity
          then 'reverse_final_anchor_gap30_v1'
        else null
      end,
    'before_gap_closure_count',
      v_before_gap_closure_count,
    'after_gap_closure_count',
      v_after_gap_closure_count,
    'gap_changed_row_count',
      v_gap_changed_row_count,
    'gap_temporal_reduction_count',
      v_gap_temporal_reduction_count,
    'gap_spatial_reduction_count',
      v_gap_spatial_reduction_count,
    'gap_maximum_reduction_seconds',
      v_gap_maximum_reduction_seconds,
    'after_gap_order_violation_count',
      v_after_gap_order_violation_count,
    'gap_increase_count',
      v_gap_increase_count,
    'negative_gap_count',
      v_negative_gap_count,
    'final_frame_gap_change_count',
      v_final_frame_gap_change_count,
    'leader_gap_change_count',
      v_leader_gap_change_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_forward_daily_automation_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '300s'
AS $function$
declare
  v_lock_key bigint :=
    hashtext('public.process_forward_daily_automation_v1')::bigint;
  v_clock_lock_key bigint :=
    hashtext('public.run_daily_tick_if_needed')::bigint;

  v_activation public.automation_forward_activation_v1%rowtype;
  v_backlog public.game_daily_tick_backlog_v1%rowtype;
  v_original_state public.game_state%rowtype;
  v_original_config public.game_clock_config%rowtype;
  v_have_snapshot boolean := false;

  v_core_already_ok boolean := false;
  v_core_ok boolean := false;
  v_due_events_ok boolean := false;
  v_game_processors_result jsonb := null;
  v_game_processors_ok boolean := false;
  v_tax_result jsonb := null;
  v_error text := null;
  v_sqlstate text := null;
begin
  if not pg_try_advisory_xact_lock(v_lock_key) then
    return jsonb_build_object(
      'status', 'skipped_forward_daily_processor_busy',
      'success', false
    );
  end if;

  if not pg_try_advisory_xact_lock(v_clock_lock_key) then
    return jsonb_build_object(
      'status', 'skipped_clock_tick_busy',
      'success', false
    );
  end if;

  select *
  into v_activation
  from public.automation_forward_activation_v1
  where id = true;

  if not found then
    return jsonb_build_object(
      'status', 'blocked_missing_forward_activation',
      'success', false
    );
  end if;

  select *
  into v_backlog
  from public.game_daily_tick_backlog_v1
  where status = 'pending'
    and current_game_date >= v_activation.daily_processing_starts_on
  order by current_game_date
  limit 1
  for update skip locked;

  if not found then
    return jsonb_build_object(
      'status', 'no_forward_daily_backlog_due',
      'success', true,
      'daily_processing_starts_on', v_activation.daily_processing_starts_on
    );
  end if;

  v_core_already_ok := coalesce(
    (v_backlog.payload ->> 'forward_core_daily_ok')::boolean,
    false
  );

  select *
  into v_original_state
  from public.game_state
  where id = true
  for update;

  select *
  into v_original_config
  from public.game_clock_config
  where id = true
  for update;

  if v_original_state.id is null or v_original_config.id is null then
    raise exception 'Could not snapshot live game clock.';
  end if;

  v_have_snapshot := true;

  update public.game_daily_tick_backlog_v1
  set
    status = 'running',
    attempts = attempts + 1,
    last_error = null,
    updated_at = now()
  where id = v_backlog.id;

  update public.game_clock_config
  set is_paused = true
  where id = true;

  update public.game_state
  set
    season_number = public.season_from_game_date(v_backlog.current_game_date),
    month_number = extract(month from v_backlog.current_game_date)::smallint,
    day_number = extract(day from v_backlog.current_game_date)::smallint,
    hour_number = 0,
    minute_number = 0,
    tick_version = coalesce(v_backlog.tick_version, v_original_state.tick_version),
    is_paused = false,
    last_advanced_at = clock_timestamp()
  where id = true;

  begin
    if not v_core_already_ok then
      perform public.process_daily_tick();
      v_core_ok := true;

      perform public.process_due_game_events();
      v_due_events_ok := true;

      if to_regprocedure(
           'public.finance_run_due_monthly_tax_audits_guarded_v1(boolean)'
         ) is not null then
        execute
          'select public.finance_run_due_monthly_tax_audits_guarded_v1(true)'
        into v_tax_result;
      end if;

      if to_regprocedure(
           'public.finance_process_weekly_emergency_loan_repayments()'
         ) is not null then
        perform public.finance_process_weekly_emergency_loan_repayments();
      end if;

      update public.game_daily_tick_backlog_v1
      set
        status = 'pending',
        updated_at = now(),
        last_error = null,
        payload = payload || jsonb_build_object(
          'forward_core_daily_ok', true,
          'forward_core_daily_completed_at', now(),
          'forward_due_game_events_ok', true,
          'forward_tax_result', v_tax_result
        )
      where id = v_backlog.id;
    else
      v_core_ok := true;
      v_due_events_ok := true;
    end if;

    select public.run_daily_game_processors_v1(true)
    into v_game_processors_result;

    v_game_processors_ok := coalesce(
      (v_game_processors_result ->> 'success')::boolean,
      false
    );

  exception when others then
    v_sqlstate := sqlstate;
    v_error := sqlerrm;
  end;

  /* Always restore the exact live clock before final backlog bookkeeping. */
  update public.game_state
  set
    season_number = v_original_state.season_number,
    month_number = v_original_state.month_number,
    day_number = v_original_state.day_number,
    hour_number = v_original_state.hour_number,
    minute_number = v_original_state.minute_number,
    tick_version = v_original_state.tick_version,
    is_paused = v_original_state.is_paused,
    last_advanced_at = v_original_state.last_advanced_at
  where id = true;

  update public.game_clock_config
  set
    base_real_at = v_original_config.base_real_at,
    base_game_at = v_original_config.base_game_at,
    base_season = v_original_config.base_season,
    speed_multiplier = v_original_config.speed_multiplier,
    is_paused = v_original_config.is_paused
  where id = true;

  v_have_snapshot := false;

  if v_core_ok and v_due_events_ok and v_game_processors_ok
     and v_error is null then
    insert into public.game_daily_tick_log (
      season_number,
      month_number,
      day_number,
      tick_version,
      ran_at
    )
    values (
      v_backlog.season_number,
      v_backlog.month_number,
      v_backlog.day_number,
      coalesce(v_backlog.tick_version, v_original_state.tick_version),
      now()
    )
    on conflict do nothing;

    update public.game_daily_tick_backlog_v1
    set
      status = 'processed',
      processed_at = now(),
      updated_at = now(),
      last_error = null,
      payload = payload || jsonb_build_object(
        'forward_daily_automation_success', true,
        'forward_daily_automation_completed_at', now(),
        'forward_game_processors_result', v_game_processors_result
      )
    where id = v_backlog.id;
  else
    update public.game_daily_tick_backlog_v1
    set
      status = 'pending',
      processed_at = null,
      updated_at = now(),
      last_error = concat_ws(
        ': ',
        v_sqlstate,
        coalesce(
          v_error,
          v_game_processors_result ->> 'error',
          'forward_daily_game_processors_returned_success_false'
        )
      ),
      payload = payload || jsonb_build_object(
        'forward_daily_automation_success', false,
        'forward_daily_automation_last_failed_at', now(),
        'forward_game_processors_result', v_game_processors_result,
        'forward_sqlstate', v_sqlstate,
        'forward_error', v_error
      )
    where id = v_backlog.id;
  end if;

  return jsonb_build_object(
    'status', case
      when v_core_ok and v_due_events_ok and v_game_processors_ok
           and v_error is null
        then 'forward_daily_processed'
      else 'forward_daily_pending_retry'
    end,
    'success',
      v_core_ok and v_due_events_ok and v_game_processors_ok
      and v_error is null,
    'processed_game_date', v_backlog.current_game_date,
    'daily_processing_starts_on', v_activation.daily_processing_starts_on,
    'core_daily_ok', v_core_ok,
    'due_game_events_ok', v_due_events_ok,
    'game_processors_ok', v_game_processors_ok,
    'game_processors_result', v_game_processors_result,
    'sqlstate', v_sqlstate,
    'error', v_error
  );

exception when others then
  if v_have_snapshot then
    begin
      update public.game_state
      set
        season_number = v_original_state.season_number,
        month_number = v_original_state.month_number,
        day_number = v_original_state.day_number,
        hour_number = v_original_state.hour_number,
        minute_number = v_original_state.minute_number,
        tick_version = v_original_state.tick_version,
        is_paused = v_original_state.is_paused,
        last_advanced_at = v_original_state.last_advanced_at
      where id = true;

      update public.game_clock_config
      set
        base_real_at = v_original_config.base_real_at,
        base_game_at = v_original_config.base_game_at,
        base_season = v_original_config.base_season,
        speed_multiplier = v_original_config.speed_multiplier,
        is_paused = v_original_config.is_paused
      where id = true;
    exception when others then
      null;
    end;
  end if;

  if v_backlog.id is not null then
    update public.game_daily_tick_backlog_v1
    set
      status = 'pending',
      processed_at = null,
      updated_at = now(),
      last_error = concat_ws(': ', sqlstate, sqlerrm)
    where id = v_backlog.id;
  end if;

  return jsonb_build_object(
    'status', 'forward_daily_processor_error',
    'success', false,
    'sqlstate', sqlstate,
    'error', sqlerrm
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_forward_due_game_events_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_activation public.automation_forward_activation_v1%rowtype;
begin
  select *
  into v_activation
  from public.automation_forward_activation_v1
  where id = true;

  if not found then
    return jsonb_build_object(
      'status', 'blocked_missing_forward_activation',
      'success', false
    );
  end if;

  perform public.process_due_game_events();

  return jsonb_build_object(
    'status', 'forward_due_game_events_checked',
    'success', true,
    'activation_game_timestamp', v_activation.activated_game_timestamp,
    'checked_at_game_timestamp', public.get_current_game_timestamp()
  );

exception when others then
  return jsonb_build_object(
    'status', 'forward_due_game_events_failed',
    'success', false,
    'sqlstate', sqlstate,
    'error', sqlerrm
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_forward_only_scheduler_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '300s'
AS $function$
declare
  v_lock_key bigint :=
    hashtext('public.race_engine_forward_only_scheduler_tick_v1')::bigint;

  v_activation public.automation_forward_activation_v1%rowtype;
  v_game_ts timestamptz;
  v_stage record;
  v_result jsonb;
begin
  if not pg_try_advisory_xact_lock(v_lock_key) then
    return jsonb_build_object(
      'status', 'skipped_forward_race_scheduler_busy',
      'success', false
    );
  end if;

  select *
  into v_activation
  from public.automation_forward_activation_v1
  where id = true;

  if not found then
    return jsonb_build_object(
      'status', 'blocked_missing_forward_activation',
      'success', false
    );
  end if;

  v_game_ts := public.get_current_game_timestamp();

  with stage_candidates as (
    select
      s.id as stage_id,
      s.race_id,
      r.name as race_name,
      s.stage_number,
      coalesce(s.stage_format, 'road_race') as stage_format,
      s.stage_date,
      (
        s.stage_date::timestamp
        + make_interval(
            hours => s.planned_start_hour_number,
            mins => coalesce(s.planned_start_minute, 0)
          )
      ) at time zone 'UTC' as planned_game_start
    from public.race_stages s
    join public.races r
      on r.id = s.race_id
    where s.planned_start_hour_number is not null
      and coalesce(s.weather_cancelled, false) = false
      and r.status in ('scheduled', 'active')
      and not exists (
        select 1
        from public.race_stage_results rr
        where rr.stage_id = s.id
          and rr.status = 'finished'
      )
      and not exists (
        select 1
        from public.race_stage_simulation_runs terminal_sim
        where terminal_sim.stage_id = s.id
          and terminal_sim.status = 'completed'
          and (
            terminal_sim.simulation_mode =
              'weather_cancelled_no_simulation'
            or coalesce(
              (terminal_sim.result_summary_json ->> 'cancelled')::boolean,
              false
            )
          )
      )
  )
  select c.*
  into v_stage
  from stage_candidates c
  where c.planned_game_start
          >= v_activation.activated_game_timestamp
    and c.planned_game_start <= v_game_ts
    and not exists (
      select 1
      from public.race_stages previous_stage
      where previous_stage.race_id = c.race_id
        and previous_stage.stage_number < c.stage_number
        and coalesce(previous_stage.weather_cancelled, false) = false
        and not (
          exists (
            select 1
            from public.race_stage_results previous_result
            where previous_result.stage_id = previous_stage.id
              and previous_result.status = 'finished'
          )
          or exists (
            select 1
            from public.race_stage_simulation_runs previous_terminal
            where previous_terminal.stage_id = previous_stage.id
              and previous_terminal.status = 'completed'
              and (
                previous_terminal.simulation_mode =
                  'weather_cancelled_no_simulation'
                or coalesce(
                  (
                    previous_terminal.result_summary_json
                    ->> 'cancelled'
                  )::boolean,
                  false
                )
              )
          )
        )
    )
  order by
    c.planned_game_start,
    c.race_name,
    c.stage_number
  limit 1;

  if not found then
    return jsonb_build_object(
      'status', 'no_forward_race_stage_due',
      'success', true,
      'activation_game_timestamp',
        v_activation.activated_game_timestamp,
      'current_game_timestamp',
        v_game_ts
    );
  end if;

  if v_stage.stage_format = 'road_race' then
    v_result :=
      public.race_engine_admin_process_next_due_stage_once_v1(
        v_stage.stage_date,
        v_stage.race_id,
        false,
        'CONFIRM_PROCESS_NEXT_DUE_STAGE_ONCE',
        true,
        10,
        4900,
        20
      );
  else
    v_result :=
      public.run_race_stage_simulation_v1(v_stage.stage_id);
  end if;

  return jsonb_build_object(
    'status', 'forward_race_stage_action_executed',
    'success', true,
    'activation_game_timestamp',
      v_activation.activated_game_timestamp,
    'current_game_timestamp',
      v_game_ts,
    'stage_id',
      v_stage.stage_id,
    'race_id',
      v_stage.race_id,
    'race_name',
      v_stage.race_name,
    'stage_number',
      v_stage.stage_number,
    'stage_format',
      v_stage.stage_format,
    'planned_game_start',
      v_stage.planned_game_start,
    'result',
      v_result
  );

exception when others then
  return jsonb_build_object(
    'status', 'forward_race_scheduler_failed',
    'success', false,
    'sqlstate', sqlstate,
    'error', sqlerrm
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refill_ai_transfer_market_to_target_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_policy public.transfer_market_stock_policy_v1%rowtype;
  v_today date;

  v_active_before integer := 0;
  v_active_after integer := 0;
  v_needed integer := 0;
  v_attempt_limit integer := 0;

  v_candidates_selected integer := 0;
  v_created integer := 0;
  v_skipped integer := 0;

  v_candidate record;
  v_listing_id uuid;

  v_lock_key bigint :=
    hashtext('public.refill_ai_transfer_market_to_target_v1')::bigint;
begin
  if not pg_try_advisory_xact_lock(v_lock_key) then
    return jsonb_build_object(
      'success', true,
      'status', 'skipped_refill_already_running'
    );
  end if;

  select *
  into v_policy
  from public.transfer_market_stock_policy_v1
  where id = true;

  if not found then
    raise exception 'Transfer market stock policy is missing.';
  end if;

  v_today := public.get_market_game_date();

  select count(*)::integer
  into v_active_before
  from public.rider_transfer_listings listing_row
  where listing_row.status = 'listed'
    and (
      listing_row.expires_on_game_date is null
      or listing_row.expires_on_game_date >= v_today
    );

  v_needed := greatest(
    0,
    v_policy.target_active_listings - v_active_before
  );

  v_attempt_limit := least(
    v_needed,
    v_policy.max_new_listings_per_refill
  );

  if v_attempt_limit <= 0 then
    return jsonb_build_object(
      'success', true,
      'status', 'target_already_satisfied',
      'market_game_date', v_today,
      'target_active_listings',
        v_policy.target_active_listings,
      'visible_rpc_page_size',
        v_policy.visible_rpc_page_size,
      'active_before', v_active_before,
      'active_after', v_active_before,
      'created', 0,
      'skipped', 0
    );
  end if;

  for v_candidate in
    with club_state as
    (
      select
        club.id as club_id,
        club.name as club_name,

        (
          select count(*)::integer
          from public.club_riders roster
          where roster.club_id = club.id
        ) as roster_count,

        (
          select count(*)::integer
          from public.rider_transfer_listings flow_listing
          where flow_listing.seller_club_id = club.id
            and flow_listing.status in (
              'listed',
              'club_accepted'
            )
        ) as active_transfer_flow_count
      from public.clubs club
      where club.deleted_at is null
        and club.is_active = true
        and club.is_ai = true
        and club.club_type = 'main'
        and club.parent_club_id is null
    ),
    ranked_candidates as
    (
      select
        state.club_id,
        state.club_name,
        state.roster_count,
        state.active_transfer_flow_count,
        rider.id as rider_id,

        (
          coalesce(
            extract(year from age(current_date, rider.birth_date)),
            0
          ) * 1.0
          + (
              100 - coalesce(rider.potential, 50)
            ) * 0.25
          + (
              100 - coalesce(rider.morale, 50)
            ) * 0.20
          + coalesce(rider.market_value, 0) / 50000.0
        ) as sell_score,

        row_number() over
        (
          partition by state.club_id
          order by
            (
              coalesce(
                extract(
                  year from age(
                    current_date,
                    rider.birth_date
                  )
                ),
                0
              ) * 1.0
              + (
                  100 - coalesce(rider.potential, 50)
                ) * 0.25
              + (
                  100 - coalesce(rider.morale, 50)
                ) * 0.20
              + coalesce(rider.market_value, 0) / 50000.0
            ) desc,
            rider.market_value desc nulls last,
            rider.id
        ) as candidate_rank,

        least(
          greatest(
            0,
            v_policy.max_active_transfer_flow_per_ai_club
              - state.active_transfer_flow_count
          ),
          greatest(
            0,
            state.roster_count
              - v_policy.min_roster_after_potential_sales
          )
        ) as available_listing_slots
      from club_state state
      join public.club_riders roster
        on roster.club_id = state.club_id
      join public.riders rider
        on rider.id = roster.rider_id
      where state.roster_count >
              v_policy.min_roster_after_potential_sales
        and state.active_transfer_flow_count <
              v_policy.max_active_transfer_flow_per_ai_club
        and rider.market_value is not null
        and not exists
        (
          select 1
          from public.rider_transfer_listings existing_listing
          where existing_listing.rider_id = rider.id
            and existing_listing.status in (
              'listed',
              'club_accepted'
            )
        )
        and not exists
        (
          select 1
          from public.rider_free_agents free_agent
          where free_agent.rider_id = rider.id
            and free_agent.status = 'available'
        )
    )
    select
      candidate.club_id,
      candidate.club_name,
      candidate.rider_id,
      candidate.sell_score,
      candidate.candidate_rank,
      candidate.available_listing_slots
    from ranked_candidates candidate
    where candidate.candidate_rank <=
            candidate.available_listing_slots
      and candidate.sell_score >= 35
    order by
      candidate.active_transfer_flow_count,
      candidate.candidate_rank,
      candidate.sell_score desc,
      random()
    limit v_attempt_limit
  loop
    v_candidates_selected := v_candidates_selected + 1;

    begin
      v_listing_id :=
        public.ai_create_rider_transfer_listing(
          v_candidate.rider_id,
          v_candidate.club_id,
          v_policy.listing_duration_game_days
        );

      if v_listing_id is not null then
        v_created := v_created + 1;
      else
        v_skipped := v_skipped + 1;
      end if;

    exception
      when unique_violation then
        v_skipped := v_skipped + 1;

      when raise_exception then
        if sqlerrm like 'Rider is already in transfer flow:%'
           or sqlerrm like 'Rider is already in free-agent flow:%'
           or sqlerrm like 'Rider % is not owned by club %' then
          v_skipped := v_skipped + 1;
        else
          raise;
        end if;
    end;
  end loop;

  select count(*)::integer
  into v_active_after
  from public.rider_transfer_listings listing_row
  where listing_row.status = 'listed'
    and (
      listing_row.expires_on_game_date is null
      or listing_row.expires_on_game_date >= v_today
    );

  return jsonb_build_object(
    'success', true,
    'status',
      case
        when v_active_after >= v_policy.target_active_listings
          then 'target_satisfied'
        when v_created > 0
          then 'target_partially_filled'
        else 'no_eligible_candidates'
      end,
    'market_game_date', v_today,
    'target_active_listings',
      v_policy.target_active_listings,
    'visible_rpc_page_size',
      v_policy.visible_rpc_page_size,
    'buffer_active_listings',
      v_policy.buffer_active_listings,
    'max_active_transfer_flow_per_ai_club',
      v_policy.max_active_transfer_flow_per_ai_club,
    'min_roster_after_potential_sales',
      v_policy.min_roster_after_potential_sales,
    'listing_duration_game_days',
      v_policy.listing_duration_game_days,
    'active_before', v_active_before,
    'needed_before', v_needed,
    'attempt_limit', v_attempt_limit,
    'candidates_selected', v_candidates_selected,
    'created', v_created,
    'skipped', v_skipped,
    'active_after', v_active_after,
    'remaining_to_target',
      greatest(
        0,
        v_policy.target_active_listings - v_active_after
      )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_build_incident_multichannel_shadow_plan_v1(p_simulation_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_race_id uuid;
  v_stage_id uuid;
  v_result jsonb;
begin
  if p_simulation_run_id is null then
    raise exception
      'Simulation run id is required for incident multichannel shadow plan.';
  end if;

  select
    simulation_row.race_id,
    simulation_row.stage_id
  into
    v_race_id,
    v_stage_id
  from public.race_stage_simulation_runs simulation_row
  where simulation_row.id = p_simulation_run_id
    and simulation_row.status = 'completed';

  if v_stage_id is null or v_race_id is null then
    raise exception
      'Completed simulation run % was not found.',
      p_simulation_run_id;
  end if;

  with
  stage_context as (
    select
      p_simulation_run_id as simulation_run_id,
      v_race_id as race_id,
      v_stage_id as stage_id,
      public.race_engine_stage_rain_jacket_requirement_v1(
        v_stage_id
      ) as weather_requirement,
      public.race_stage_weather_avg_temp_c_v1(
        v_stage_id
      ) as avg_temp_c,
      public.race_stage_weather_condition_text_v2(
        v_stage_id
      ) as weather_condition
  ),
  stage_risk as (
    select
      max(
        case when segment_row.terrain_type = 'technical_descent'
          then 1 else 0 end
      ) as has_technical_descent,
      max(
        case when segment_row.terrain_type = 'descent'
          then 1 else 0 end
      ) as has_descent,
      max(
        case when segment_row.terrain_type in ('climb', 'steep_climb')
          then 1 else 0 end
      ) as has_climbs,
      coalesce(max(segment_row.km_end), 0)::numeric
        as stage_distance_km,
      count(*)::integer as segment_count,
      md5(coalesce(string_agg(
        to_jsonb(segment_row)::text,
        '|' order by segment_row.km_start, segment_row.km_end
      ), '')) as segment_source_hash
    from public.race_engine_get_stage_segments_v1(
      v_stage_id
    ) segment_row
  ),
  preparation as (
    select preparation_row.*
    from public.race_engine_get_stage_rider_preparation_modifiers_v2(
      v_stage_id
    ) preparation_row
  ),
  rider_sources as (
    select
      context_row.simulation_run_id,
      context_row.race_id,
      context_row.stage_id,
      rider_state.rider_id,
      rider_state.team_id,
      rider_state.finish_stamina,
      rider_state.fatigue_after_stage,
      rider_state.stage_status,
      coalesce(
        nullif(rider_state.metadata ->> 'effort_multiplier', '')::numeric,
        1
      )::numeric as effort_multiplier,

      risk_row.has_technical_descent,
      risk_row.has_descent,
      risk_row.has_climbs,
      risk_row.stage_distance_km,
      risk_row.segment_count,
      risk_row.segment_source_hash,

      coalesce(preparation_row.preparation_applied, false)
        as preparation_applied,
      coalesce(
        preparation_row.health_incident_risk_multiplier,
        1
      )::numeric as health_incident_risk_multiplier,
      coalesce(
        preparation_row.mechanical_incident_risk_multiplier,
        1
      )::numeric as mechanical_incident_risk_multiplier,
      coalesce(
        preparation_row.mechanical_time_loss_multiplier,
        1
      )::numeric as mechanical_time_loss_multiplier,

      context_row.weather_requirement,
      context_row.avg_temp_c,
      context_row.weather_condition,

      (
        0.015
        + case when risk_row.has_technical_descent = 1
            then 0.020 else 0 end
        + case when risk_row.has_descent = 1
            then 0.010 else 0 end
        + case when risk_row.has_climbs = 1
            then 0.006 else 0 end
        + case
            when rider_state.finish_stamina < 15 then 0.030
            when rider_state.finish_stamina < 30 then 0.015
            else 0
          end
        + case
            when rider_state.fatigue_after_stage >= 80 then 0.030
            when rider_state.fatigue_after_stage >= 60 then 0.015
            when rider_state.fatigue_after_stage >= 40 then 0.007
            else 0
          end
        + case
            when coalesce(
              nullif(
                rider_state.metadata ->> 'effort_multiplier',
                ''
              )::numeric,
              1
            ) >= 1.30 then 0.018
            when coalesce(
              nullif(
                rider_state.metadata ->> 'effort_multiplier',
                ''
              )::numeric,
              1
            ) >= 1.15 then 0.010
            else 0
          end
      )::numeric(12,6) as canonical_base_probability,

      md5(
        concat_ws(
          '|',
          context_row.simulation_run_id::text,
          rider_state.rider_id::text,
          rider_state.team_id::text,
          rider_state.finish_stamina::text,
          rider_state.fatigue_after_stage::text,
          coalesce(rider_state.metadata ->> 'effort_multiplier', '1'),
          risk_row.segment_source_hash,
          md5(context_row.weather_requirement::text),
          coalesce(
            preparation_row.health_incident_risk_multiplier::text,
            '1'
          ),
          coalesce(
            preparation_row.mechanical_incident_risk_multiplier::text,
            '1'
          ),
          coalesce(
            preparation_row.mechanical_time_loss_multiplier::text,
            '1'
          )
        )
      ) as per_rider_source_hash
    from stage_context context_row
    cross join stage_risk risk_row
    join public.race_stage_rider_states rider_state
      on rider_state.simulation_run_id = context_row.simulation_run_id
     and rider_state.stage_id = context_row.stage_id
     and rider_state.stage_status = 'finished'
    left join preparation preparation_row
      on preparation_row.stage_id = rider_state.stage_id
     and preparation_row.rider_id = rider_state.rider_id
     and preparation_row.team_id = rider_state.team_id
  ),
  shadow_rolls as (
    select
      source_row.*,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:baseline_selection'
      ) as baseline_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:incident_type'
      ) as incident_type_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:location'
      ) as location_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:dnf'
      ) as dnf_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:mechanical'
      ) as mechanical_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:health_eligibility'
      ) as health_roll_key,

      concat(
        source_row.simulation_run_id::text,
        ':',
        source_row.rider_id::text,
        ':shadow:group_identity'
      ) as group_roll_key
    from rider_sources source_row
  ),
  shadow_plan as (
    select
      roll_row.*,

      public.race_engine_hash_roll_v1(
        roll_row.baseline_roll_key
      ) as baseline_selection_roll,

      public.race_engine_hash_roll_v1(
        roll_row.incident_type_roll_key
      ) as incident_type_roll,

      public.race_engine_hash_roll_v1(
        roll_row.location_roll_key
      ) as location_roll,

      public.race_engine_hash_roll_v1(
        roll_row.dnf_roll_key
      ) as dnf_roll,

      public.race_engine_hash_roll_v1(
        roll_row.mechanical_roll_key
      ) as mechanical_roll,

      public.race_engine_hash_roll_v1(
        roll_row.health_roll_key
      ) as health_eligibility_roll,

      public.race_engine_hash_roll_v1(
        roll_row.group_roll_key
      ) as group_identity_roll
    from shadow_rolls roll_row
  ),
  shadow_contract as (
    select
      plan_row.*,

      (
        plan_row.baseline_selection_roll <
        plan_row.canonical_base_probability
      ) as baseline_selected,

      case
        when plan_row.incident_type_roll < 0.45 then 'crash'
        when plan_row.incident_type_roll < 0.70 then 'puncture'
        else 'mechanical'
      end as deterministic_shadow_incident_type,

      case
        when plan_row.canonical_base_probability >= 0.080 then 'major'
        when plan_row.canonical_base_probability >= 0.045 then 'moderate'
        else 'minor'
      end as deterministic_shadow_severity,

      case
        when plan_row.canonical_base_probability >= 0.080 then 90
        when plan_row.canonical_base_probability >= 0.045 then 35
        else 12
      end as canonical_time_loss_seconds_reference,

      round(
        (
          plan_row.stage_distance_km *
          (0.20 + plan_row.location_roll * 0.70)
        )::numeric,
        1
      ) as deterministic_shadow_km_marker,

      greatest(
        1,
        least(
          4,
          floor((0.20 + plan_row.location_roll * 0.70) * 4)::integer + 1
        )
      ) as deterministic_shadow_phase_number,

      (
        plan_row.canonical_base_probability >= 0.10
        and plan_row.dnf_roll < 0.20
      ) as dnf_candidate,

      jsonb_build_object(
        'weather_probability_activation_ready', false,
        'weather_evidence_only', true,
        'equipment_probability_activation_ready', false,
        'equipment_evidence_only', true,
        'mechanical_channel_activation_ready', false,
        'mechanical_multiplier_recorded_only', true,
        'health_case_activation_ready', false,
        'health_multiplier_recorded_only', true,
        'group_crash_activation_ready', false,
        'group_identity_source_missing', true
      ) as unresolved_channel_flags
    from shadow_plan plan_row
  ),
  row_payloads as (
    select
      contract_row.rider_id,
      jsonb_build_object(
        'simulation_run_id', contract_row.simulation_run_id,
        'race_id', contract_row.race_id,
        'stage_id', contract_row.stage_id,
        'rider_id', contract_row.rider_id,
        'team_id', contract_row.team_id,
        'stage_status', contract_row.stage_status,
        'per_rider_source_hash', contract_row.per_rider_source_hash,

        'canonical_formula_components', jsonb_build_object(
          'base_probability', 0.015,
          'has_technical_descent',
            contract_row.has_technical_descent = 1,
          'technical_descent_addition',
            case when contract_row.has_technical_descent = 1
              then 0.020 else 0 end,
          'has_descent', contract_row.has_descent = 1,
          'descent_addition',
            case when contract_row.has_descent = 1
              then 0.010 else 0 end,
          'has_climbs', contract_row.has_climbs = 1,
          'climb_addition',
            case when contract_row.has_climbs = 1
              then 0.006 else 0 end,
          'finish_stamina', contract_row.finish_stamina,
          'fatigue_after_stage', contract_row.fatigue_after_stage,
          'effort_multiplier', contract_row.effort_multiplier,
          'canonical_base_probability',
            contract_row.canonical_base_probability,
          'severity',
            contract_row.deterministic_shadow_severity,
          'canonical_time_loss_seconds_reference',
            contract_row.canonical_time_loss_seconds_reference
        ),

        'baseline_selection_channel', jsonb_build_object(
          'roll_key', contract_row.baseline_roll_key,
          'roll', contract_row.baseline_selection_roll,
          'selected', contract_row.baseline_selected,
          'official_behavior_changed', false
        ),

        'incident_type_channel', jsonb_build_object(
          'roll_key', contract_row.incident_type_roll_key,
          'roll', contract_row.incident_type_roll,
          'shadow_incident_type',
            contract_row.deterministic_shadow_incident_type,
          'official_behavior_changed', false
        ),

        'location_channel', jsonb_build_object(
          'roll_key', contract_row.location_roll_key,
          'roll', contract_row.location_roll,
          'shadow_km_marker',
            contract_row.deterministic_shadow_km_marker,
          'shadow_phase_number',
            contract_row.deterministic_shadow_phase_number,
          'official_behavior_changed', false
        ),

        'dnf_candidate_channel', jsonb_build_object(
          'roll_key', contract_row.dnf_roll_key,
          'roll', contract_row.dnf_roll,
          'candidate', contract_row.dnf_candidate,
          'official_behavior_changed', false
        ),

        'mechanical_candidate_channel', jsonb_build_object(
          'roll_key', contract_row.mechanical_roll_key,
          'roll', contract_row.mechanical_roll,
          'preparation_applied', contract_row.preparation_applied,
          'mechanical_incident_risk_multiplier',
            contract_row.mechanical_incident_risk_multiplier,
          'mechanical_time_loss_multiplier',
            contract_row.mechanical_time_loss_multiplier,
          'multiplier_applied_to_official_behavior', false
        ),

        'health_eligibility_channel', jsonb_build_object(
          'roll_key', contract_row.health_roll_key,
          'roll', contract_row.health_eligibility_roll,
          'preparation_applied', contract_row.preparation_applied,
          'health_incident_risk_multiplier',
            contract_row.health_incident_risk_multiplier,
          'health_case_created', false,
          'exact_health_mapping_available', false
        ),

        'weather_evidence_channel', jsonb_build_object(
          'weather_requirement', contract_row.weather_requirement,
          'avg_temp_c', contract_row.avg_temp_c,
          'weather_condition', contract_row.weather_condition,
          'probability_coefficient_available', false,
          'applied_to_official_probability', false
        ),

        'equipment_condition_evidence_channel', jsonb_build_object(
          'condition_source_exists', true,
          'probability_coefficient_available', false,
          'applied_to_official_probability', false,
          'equipment_condition_changed', false
        ),

        'group_identity_requirement_channel', jsonb_build_object(
          'roll_key', contract_row.group_roll_key,
          'roll', contract_row.group_identity_roll,
          'exact_involved_rider_ids_available', false,
          'shared_official_incident_identity_available', false,
          'group_crash_fanout_performed', false
        ),

        'unresolved_channel_flags',
          contract_row.unresolved_channel_flags
      ) as row_json,

      jsonb_build_object(
        'rider_id', contract_row.rider_id,
        'team_id', contract_row.team_id,
        'canonical_base_probability',
          contract_row.canonical_base_probability,
        'baseline_roll', contract_row.baseline_selection_roll,
        'incident_type_roll', contract_row.incident_type_roll,
        'location_roll', contract_row.location_roll,
        'dnf_roll', contract_row.dnf_roll,
        'mechanical_roll', contract_row.mechanical_roll,
        'health_roll', contract_row.health_eligibility_roll,
        'group_roll', contract_row.group_identity_roll,
        'health_incident_risk_multiplier',
          contract_row.health_incident_risk_multiplier,
        'mechanical_incident_risk_multiplier',
          contract_row.mechanical_incident_risk_multiplier,
        'mechanical_time_loss_multiplier',
          contract_row.mechanical_time_loss_multiplier,
        'weather_requirement', contract_row.weather_requirement,
        'avg_temp_c', contract_row.avg_temp_c,
        'weather_condition', contract_row.weather_condition
      ) as hash_json,

      contract_row.baseline_selected,
      contract_row.deterministic_shadow_severity,
      contract_row.dnf_candidate,
      contract_row.canonical_base_probability,
      contract_row.health_incident_risk_multiplier,
      contract_row.mechanical_incident_risk_multiplier,
      contract_row.mechanical_time_loss_multiplier,
      contract_row.segment_count,
      contract_row.segment_source_hash,
      contract_row.weather_requirement,
      contract_row.avg_temp_c,
      contract_row.weather_condition
    from shadow_contract contract_row
  ),
  aggregate_result as (
    select jsonb_build_object(
      'version',
        'phase3ad_incident_multichannel_shadow_plan_v1',
      'classification',
        'nonwriting_nonexecuting_shadow_evidence',
      'simulation_run_id', p_simulation_run_id,
      'race_id', v_race_id,
      'stage_id', v_stage_id,

      'summary', jsonb_build_object(
        'row_count', count(*)::integer,
        'distinct_rider_count',
          count(distinct payload_row.rider_id)::integer,
        'segment_count', max(payload_row.segment_count),
        'segment_source_hash', max(payload_row.segment_source_hash),
        'baseline_selected_count',
          count(*) filter (
            where payload_row.baseline_selected
          )::integer,
        'major_reference_count',
          count(*) filter (
            where payload_row.deterministic_shadow_severity = 'major'
          )::integer,
        'moderate_reference_count',
          count(*) filter (
            where payload_row.deterministic_shadow_severity = 'moderate'
          )::integer,
        'minor_reference_count',
          count(*) filter (
            where payload_row.deterministic_shadow_severity = 'minor'
          )::integer,
        'dnf_candidate_count',
          count(*) filter (
            where payload_row.dnf_candidate
          )::integer,
        'minimum_base_probability',
          min(payload_row.canonical_base_probability),
        'maximum_base_probability',
          max(payload_row.canonical_base_probability),
        'minimum_health_multiplier',
          min(payload_row.health_incident_risk_multiplier),
        'maximum_health_multiplier',
          max(payload_row.health_incident_risk_multiplier),
        'minimum_mechanical_risk_multiplier',
          min(payload_row.mechanical_incident_risk_multiplier),
        'maximum_mechanical_risk_multiplier',
          max(payload_row.mechanical_incident_risk_multiplier),
        'minimum_mechanical_time_multiplier',
          min(payload_row.mechanical_time_loss_multiplier),
        'maximum_mechanical_time_multiplier',
          max(payload_row.mechanical_time_loss_multiplier)
      ),

      'weather_evidence', jsonb_build_object(
        'weather_requirement',
          min(payload_row.weather_requirement::text)::jsonb,
        'avg_temp_c', max(payload_row.avg_temp_c),
        'weather_condition', max(payload_row.weather_condition),
        'probability_coefficient_available', false,
        'applied_to_official_probability', false
      ),

      'activation_boundaries', jsonb_build_object(
        'writes_any_relation', false,
        'creates_official_incidents', false,
        'changes_official_probability', false,
        'changes_official_time_loss', false,
        'changes_rider_state', false,
        'creates_health_cases', false,
        'changes_equipment_condition', false,
        'fans_out_group_crashes', false,
        'called_by_road_runner', false,
        'called_by_dispatcher', false,
        'called_by_scheduler', false,
        'production_execution_enabled', false
      ),

      'plan_hash', md5(coalesce(string_agg(
        payload_row.hash_json::text,
        '|' order by payload_row.rider_id
      ), '')),

      'rows', coalesce(
        jsonb_agg(
          payload_row.row_json
          order by payload_row.rider_id
        ),
        '[]'::jsonb
      )
    ) as result_json
    from row_payloads payload_row
  )
  select aggregate_row.result_json
  into v_result
  from aggregate_result aggregate_row;

  if v_result is null then
    raise exception
      'No finished rider states were available for completed simulation run %.',
      p_simulation_run_id;
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_regular_training_coach_automation_v1(p_club_id uuid, p_enabled boolean, p_manager_staff_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_type text;
  v_parent_club_id uuid;
  v_expected_role text;
  v_staff record;
  v_generation jsonb;
  v_academy_level integer := 0;
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception 'You do not have permission to manage training for this team.';
  end if;

  select c.club_type, c.parent_club_id
  into v_club_type, v_parent_club_id
  from public.clubs c
  where c.id = p_club_id;

  if not found then raise exception 'Club not found.'; end if;

  v_expected_role := case
    when v_club_type = 'developing' then 'u23_head_coach'
    else 'head_coach'
  end;

  if coalesce(p_enabled,false)
     and v_expected_role='u23_head_coach'
     and not public.user_has_premium_access_v1(
       (select club.owner_user_id from public.clubs club where club.id=p_club_id)
     ) then
    raise exception 'Premium membership is required for U23 Head Coach training automation.';
  end if;

  if v_club_type = 'developing' then
    select coalesce(e.youth_academy_level, 0)
    into v_academy_level
    from public.get_youth_academy_effects(p_club_id) e
    limit 1;
  end if;

  if coalesce(p_enabled, false) and v_expected_role = 'u23_head_coach' and coalesce(v_academy_level, 0) < 1 then
    raise exception 'Youth Academy Lv 1 is required before U23 Head Coach training automation can be enabled.';
  end if;

  if coalesce(p_enabled, false) then
    if p_manager_staff_id is null then
      raise exception 'Select an active % before enabling automation.', replace(v_expected_role, '_', ' ');
    end if;

    select
      cs.id, cs.club_id, cs.staff_name, cs.role_type, cs.team_scope, cs.is_active
    into v_staff
    from public.club_staff cs
    where cs.id = p_manager_staff_id
      and cs.is_active = true
      and cs.role_type = v_expected_role
      and cs.club_id in (p_club_id, coalesce(v_parent_club_id, p_club_id))
      and (
        (v_expected_role = 'head_coach' and cs.team_scope in ('first_team', 'all'))
        or
        (v_expected_role = 'u23_head_coach' and cs.team_scope in ('u23', 'all'))
      )
    limit 1;

    if not found then
      raise exception 'The selected staff member is not an active % available for this team.', replace(v_expected_role, '_', ' ');
    end if;
  end if;

  insert into public.club_regular_training_automation (
    club_id, manager_staff_id, manager_role, is_enabled, planning_mode,
    horizon_days, metadata, created_at, updated_at
  )
  values (
    p_club_id,
    p_manager_staff_id,
    v_expected_role,
    coalesce(p_enabled, false),
    'rolling_daily',
    3,
    jsonb_build_object(
      'configured_by_user_id', auth.uid(),
      'configured_at', now(),
      'generator_version', 'head_coach_three_day_generator_v1',
      'generator_installed', true
    ),
    now(),
    now()
  )
  on conflict (club_id)
  do update set
    manager_staff_id = excluded.manager_staff_id,
    manager_role = excluded.manager_role,
    is_enabled = excluded.is_enabled,
    planning_mode = 'rolling_daily',
    horizon_days = 3,
    metadata = public.club_regular_training_automation.metadata || excluded.metadata,
    updated_at = now();

  if coalesce(p_enabled, false) then
    v_generation := public.generate_coach_regular_training_plan_v1(
      p_club_id,
      public.get_current_game_date_date()
    );
  else
    update public.rider_regular_training_daily_plans
    set
      status = 'superseded',
      decision_reason_json = coalesce(decision_reason_json, '{}'::jsonb) || jsonb_build_object(
        'superseded_reason', 'automation_disabled',
        'superseded_at', now()
      ),
      updated_at = now()
    where club_id = p_club_id
      and plan_date >= public.get_current_game_date_date()
      and source_type in ('head_coach', 'u23_head_coach')
      and status = 'planned';

    v_generation := jsonb_build_object(
      'ok', true,
      'generated', false,
      'reason', 'automation_disabled'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'is_enabled', coalesce(p_enabled, false),
    'manager_staff_id', p_manager_staff_id,
    'manager_role', v_expected_role,
    'planning_mode', 'rolling_daily',
    'horizon_days', 3,
    'generator_installed', true,
    'generation', v_generation
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_rider_regular_training_management_v1(p_club_id uuid, p_rider_id uuid, p_management_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_generation jsonb;
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception
      'You do not have permission to manage training for this team.';
  end if;

  if p_management_mode not in (
    'inherit',
    'coach',
    'manual'
  ) then
    raise exception 'Invalid management mode.';
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider does not belong to this team.';
  end if;

  insert into public.rider_regular_training_management (
    club_id,
    rider_id,
    management_mode,
    updated_by_user_id,
    metadata,
    created_at,
    updated_at
  )
  values (
    p_club_id,
    p_rider_id,
    p_management_mode,
    auth.uid(),
    jsonb_build_object(
      'changed_at', now()
    ),
    now(),
    now()
  )
  on conflict (club_id, rider_id)
  do update
  set
    management_mode = excluded.management_mode,
    updated_by_user_id = excluded.updated_by_user_id,
    metadata =
      public.rider_regular_training_management.metadata
      || excluded.metadata,
    updated_at = now();

  if p_management_mode = 'manual' then
    update public.rider_regular_training_daily_plans
    set
      status = 'superseded',
      decision_reason_json =
        coalesce(decision_reason_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_reason', 'rider_is_manually_managed',
          'superseded_at', now()
        ),
      updated_at = now()
    where club_id = p_club_id
      and rider_id = p_rider_id
      and plan_date >= public.get_current_game_date_date()
      and source_type in ('head_coach', 'u23_head_coach')
      and status = 'planned';

    v_generation := jsonb_build_object(
      'ok', true,
      'generated', false,
      'reason', 'rider_is_manually_managed'
    );
  else
    v_generation :=
      public.generate_coach_regular_training_plan_v1(
        p_club_id,
        public.get_current_game_date_date()
      );
  end if;

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'rider_id', p_rider_id,
    'management_mode', p_management_mode,
    'generation', v_generation
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_rider_daily_training_override_v1(p_club_id uuid, p_rider_id uuid, p_plan_date date, p_focus_code text, p_intensity text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date;
  v_saved_intensity text;
  v_generation jsonb;

  v_availability_status text;
  v_has_existing_activity boolean;
  v_has_health_block boolean;
  v_has_training_camp boolean;
  v_has_race_commitment boolean;
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception
      'You do not have permission to manage training for this team.';
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider does not belong to this team.';
  end if;

  v_today := public.get_current_game_date_date();

  if v_today is null then
    raise exception 'Current game date could not be resolved.';
  end if;

  if p_plan_date < v_today
     or p_plan_date > v_today + 2 then
    raise exception
      'A one-day override must be inside Today, Tomorrow or Day +2.';
  end if;

  if p_focus_code not in (
    'general',
    'recovery',
    'sprint',
    'climbing',
    'flat',
    'time_trial',
    'endurance',
    'resistance',
    'race_iq',
    'teamwork',
    'day_off'
  ) then
    raise exception 'Invalid regular-training focus.';
  end if;

  if p_intensity not in (
    'recovery',
    'light',
    'normal',
    'hard'
  ) then
    raise exception 'Invalid regular-training intensity.';
  end if;

  select
    coalesce(r.availability_status, 'fit')
  into v_availability_status
  from public.riders r
  where r.id = p_rider_id;

  v_has_existing_activity := exists (
    select 1
    from public.rider_daily_activity a
    where a.rider_id = p_rider_id
      and a.activity_date = p_plan_date
  );

  v_has_health_block := exists (
    select 1
    from public.rider_health_cases hc
    where hc.rider_id = p_rider_id
      and hc.status in ('active', 'recovering')
      and hc.training_blocked = true
      and p_plan_date between
        hc.started_on
        and coalesce(
          hc.recovery_until,
          hc.active_until
        )
  );

  v_has_training_camp := exists (
    select 1
    from public.training_camp_participants tcp
    join public.training_camp_bookings tcb
      on tcb.id = tcp.booking_id
    where tcp.rider_id = p_rider_id
      and tcb.status in ('planned', 'active')
      and p_plan_date between
        tcb.start_date
        and tcb.end_date
  );

  v_has_race_commitment := exists (
    select 1
    from public.race_preparation_riders rpr
    join public.race_preparations rp
      on rp.id = rpr.race_preparation_id
    join public.races rr
      on rr.id = rp.race_id
    where rpr.rider_id = p_rider_id
      and rp.participating_club_id = p_club_id
      and rp.status in ('submitted', 'locked')
      and p_plan_date between rr.start_date and rr.end_date
      and exists (
        select 1
        from public.race_stages rs
        where rs.race_id = rr.id
          and coalesce(rs.weather_cancelled, false) = false
      )
  );

  if v_has_existing_activity then
    raise exception
      'This rider already has an activity on the selected game date.';
  end if;

  if p_plan_date = v_today
     and v_availability_status in ('injured', 'sick') then
    raise exception
      'This rider is currently unavailable for regular training.';
  end if;

  if v_has_health_block then
    raise exception
      'A health case blocks regular training on the selected game date.';
  end if;

  if v_has_training_camp then
    raise exception
      'Training camp controls this rider on the selected game date.';
  end if;

  if v_has_race_commitment then
    raise exception
      'Race commitment controls this rider on the selected game date.';
  end if;

  v_saved_intensity :=
    case
      when p_focus_code = 'day_off'
        then 'normal'
      when p_focus_code = 'recovery'
           and p_intensity = 'hard'
        then 'normal'
      else p_intensity
    end;

  insert into public.rider_regular_training_daily_plans (
    club_id,
    rider_id,
    plan_date,
    focus_code,
    intensity,
    source_type,
    source_staff_id,
    status,
    decision_reason_json,
    generated_on_game_date,
    generated_at,
    updated_at
  )
  values (
    p_club_id,
    p_rider_id,
    p_plan_date,
    p_focus_code,
    v_saved_intensity,
    'manual_override',
    null,
    'planned',
    jsonb_build_object(
      'version', 'manual_one_day_override_v1',
      'entered_by_user_id', auth.uid(),
      'entered_at', now(),
      'coach_resumes_after_date', p_plan_date + 1
    ),
    v_today,
    now(),
    now()
  )
  on conflict (
    club_id,
    rider_id,
    plan_date
  )
  do update
  set
    focus_code = excluded.focus_code,
    intensity = excluded.intensity,
    source_type = 'manual_override',
    source_staff_id = null,
    status = 'planned',
    decision_quality_score = null,
    coach_availability_factor = null,
    fatigue_snapshot = null,
    availability_status_snapshot = null,
    projected_fatigue_after = null,
    decision_reason_json = excluded.decision_reason_json,
    generated_on_game_date = excluded.generated_on_game_date,
    generated_at = excluded.generated_at,
    consumed_at = null,
    updated_at = now();

  v_generation :=
    public.generate_coach_regular_training_plan_v1(
      p_club_id,
      v_today
    );

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'rider_id', p_rider_id,
    'plan_date', p_plan_date,
    'focus_code', p_focus_code,
    'intensity', v_saved_intensity,
    'source_type', 'manual_override',
    'coach_resumes_after_date', p_plan_date + 1,
    'generation', v_generation
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_rider_daily_training_override_v1(p_club_id uuid, p_rider_id uuid, p_plan_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted_rows integer;
  v_generation jsonb;
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception
      'You do not have permission to manage training for this team.';
  end if;

  delete from public.rider_regular_training_daily_plans
  where club_id = p_club_id
    and rider_id = p_rider_id
    and plan_date = p_plan_date
    and source_type = 'manual_override';

  get diagnostics v_deleted_rows = row_count;

  v_generation :=
    public.generate_coach_regular_training_plan_v1(
      p_club_id,
      public.get_current_game_date_date()
    );

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'rider_id', p_rider_id,
    'plan_date', p_plan_date,
    'deleted_override_rows', v_deleted_rows,
    'generation', v_generation
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_regular_training_coach_dashboard_v1(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date;
  v_result jsonb;
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception 'You do not have permission to view training for this team.';
  end if;

  v_today := public.get_current_game_date_date();

  if v_today is null then
    raise exception 'Current game date could not be resolved.';
  end if;

  select jsonb_build_object(
    'version', 'head_coach_three_day_foundation_v1',
    'club_id', p_club_id,
    'current_game_date', v_today,
    'through_date', v_today + 2,
    'horizon_days', 3,

    'setting', (
      select to_jsonb(a)
      from public.club_regular_training_automation a
      where a.club_id = p_club_id
    ),

    'manager', (
      select jsonb_build_object(
        'id', cs.id,
        'club_id', cs.club_id,
        'staff_name', cs.staff_name,
        'role_type', cs.role_type,
        'team_scope', cs.team_scope,
        'specialization', cs.specialization,
        'expertise', cs.expertise,
        'efficiency', cs.efficiency,
        'potential', cs.potential,
        'experience', cs.experience,
        'leadership', cs.leadership,
        'loyalty', cs.loyalty,
        'is_active', cs.is_active
      )
      from public.club_regular_training_automation a
      join public.club_staff cs
        on cs.id = a.manager_staff_id
      where a.club_id = p_club_id
    ),

    'summary', jsonb_build_object(
      'total_riders', (
        select count(*)
        from public.club_riders cr
        where cr.club_id = p_club_id
      ),
      'manual_riders', (
        select count(*)
        from public.rider_regular_training_management m
        where m.club_id = p_club_id
          and m.management_mode = 'manual'
      ),
      'explicit_coach_riders', (
        select count(*)
        from public.rider_regular_training_management m
        where m.club_id = p_club_id
          and m.management_mode = 'coach'
      ),
      'manual_overrides_in_window', (
        select count(*)
        from public.rider_regular_training_daily_plans p
        where p.club_id = p_club_id
          and p.plan_date between v_today and v_today + 2
          and p.source_type = 'manual_override'
          and p.status = 'planned'
      ),
      'coach_plans_in_window', (
        select count(*)
        from public.rider_regular_training_daily_plans p
        where p.club_id = p_club_id
          and p.plan_date between v_today and v_today + 2
          and p.source_type in (
            'head_coach',
            'u23_head_coach'
          )
          and p.status = 'planned'
      )
    ),

    'riders', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'rider_id', cr.rider_id,
          'assigned_role', cr.assigned_role::text,
          'availability_status', r.availability_status,
          'fatigue', r.fatigue,
          'management_mode',
            coalesce(m.management_mode, 'inherit'),
          'days', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', p.id,
                'plan_date', p.plan_date,
                'focus_code', p.focus_code,
                'intensity', p.intensity,
                'source_type', p.source_type,
                'source_staff_id', p.source_staff_id,
                'status', p.status,
                'decision_quality_score',
                  p.decision_quality_score,
                'coach_availability_factor',
                  p.coach_availability_factor,
                'fatigue_snapshot',
                  p.fatigue_snapshot,
                'availability_status_snapshot',
                  p.availability_status_snapshot,
                'projected_fatigue_after',
                  p.projected_fatigue_after,
                'decision_reason',
                  p.decision_reason_json
              )
              order by p.plan_date
            )
            from public.rider_regular_training_daily_plans p
            where p.club_id = p_club_id
              and p.rider_id = cr.rider_id
              and p.plan_date between v_today and v_today + 2
          ), '[]'::jsonb)
        )
        order by cr.rider_id
      )
      from public.club_riders cr
      join public.riders r
        on r.id = cr.rider_id
      left join public.rider_regular_training_management m
        on m.club_id = cr.club_id
       and m.rider_id = cr.rider_id
      where cr.club_id = p_club_id
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_coach_regular_training_plan_v1(p_club_id uuid, p_anchor_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_anchor_date date;
  v_through_date date;

  v_setting public.club_regular_training_automation%rowtype;
  v_club_type text;
  v_parent_club_id uuid;
  v_expected_role text;

  v_staff public.club_staff%rowtype;
  v_staff_factor numeric;
  v_has_active_course boolean;

  v_generated integer := 0;
  v_skipped integer := 0;
  v_manual_preserved integer := 0;
  v_manual_riders integer := 0;
  v_managed_riders integer := 0;

  r record;

  v_management_mode text;
  v_plan_date date;
  v_day_offset integer;
  v_existing_source text;
  v_existing_focus text;
  v_existing_intensity text;

  v_age integer;
  v_quality numeric;
  v_training_score numeric;
  v_recovery_planning_score numeric;
  v_youth_score numeric;
  v_experience_score numeric;
  v_leadership_score numeric;
  v_loyalty_score numeric;

  v_specialization_focus text;
  v_preferred_focus text;
  v_focus_candidates text[];
  v_primary_focus text;
  v_target_focus text;
  v_focus_code text;
  v_intensity text;

  v_status text;
  v_block_reason text;
  v_has_existing_activity boolean;
  v_has_health_block boolean;
  v_has_training_camp boolean;
  v_has_race_commitment boolean;
  v_has_upcoming_race boolean;
  v_previous_external_load boolean := false;

  v_projected_fatigue integer;
  v_projected_after integer;
  v_fatigue_load integer;
  v_recovery_bonus integer;
  v_daily_recovery integer;
  v_projected_heavy_days integer;
  v_heavy_bonus integer;
  v_hard_used boolean;

  v_reason jsonb;
begin
  v_anchor_date :=
    coalesce(
      p_anchor_date,
      public.get_current_game_date_date()
    );

  if v_anchor_date is null then
    raise exception
      'generate_coach_regular_training_plan_v1: game date is missing';
  end if;

  v_through_date := v_anchor_date + 2;

  select
    a.*
  into v_setting
  from public.club_regular_training_automation a
  where a.club_id = p_club_id;

  if not found
     or coalesce(v_setting.is_enabled, false) = false then
    return jsonb_build_object(
      'ok', true,
      'generated', false,
      'reason', 'automation_disabled',
      'club_id', p_club_id,
      'anchor_date', v_anchor_date,
      'through_date', v_through_date
    );
  end if;

  select
    c.club_type,
    c.parent_club_id
  into
    v_club_type,
    v_parent_club_id
  from public.clubs c
  where c.id = p_club_id
    and c.deleted_at is null;

  if not found then
    raise exception 'Club not found.';
  end if;

  v_expected_role :=
    case
      when v_club_type = 'developing'
        then 'u23_head_coach'
      else 'head_coach'
    end;

  if v_expected_role = 'u23_head_coach'
     and not public.user_has_premium_access_v1(
       (
         select owner_club.owner_user_id
         from public.clubs owner_club
         where owner_club.id = coalesce(v_parent_club_id, p_club_id)
       )
     ) then
    update public.club_regular_training_automation
    set
      is_enabled = false,
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
          'premium_access_required', true,
          'disabled_reason', 'premium_required_for_developing_team',
          'disabled_at', now()
        ),
      updated_at = now()
    where club_id = p_club_id;

    update public.rider_regular_training_daily_plans
    set
      status = 'superseded',
      decision_reason_json = coalesce(decision_reason_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_reason', 'premium_required_for_developing_team',
          'superseded_at', now()
        ),
      updated_at = now()
    where club_id = p_club_id
      and plan_date >= v_anchor_date
      and source_type = 'u23_head_coach'
      and status = 'planned';

    return jsonb_build_object(
      'ok', false,
      'generated', false,
      'reason', 'premium_required',
      'club_id', p_club_id,
      'expected_role', v_expected_role
    );
  end if;

  if v_setting.manager_role <> v_expected_role then
    raise exception
      'Configured manager role % does not match expected role %.',
      v_setting.manager_role,
      v_expected_role;
  end if;

  select
    cs.*
  into v_staff
  from public.club_staff cs
  where cs.id = v_setting.manager_staff_id
    and cs.is_active = true
    and cs.role_type = v_expected_role
    and cs.club_id in (
      p_club_id,
      coalesce(v_parent_club_id, p_club_id)
    )
    and (
      (
        v_expected_role = 'head_coach'
        and cs.team_scope in ('first_team', 'all')
      )
      or
      (
        v_expected_role = 'u23_head_coach'
        and cs.team_scope in ('u23', 'all')
      )
    )
  limit 1;

  if not found then
    update public.club_regular_training_automation
    set
      last_generated_game_date = v_anchor_date,
      last_generated_through = v_through_date,
      last_generation_summary = jsonb_build_object(
        'ok', false,
        'reason', 'active_manager_not_found',
        'expected_role', v_expected_role
      ),
      updated_at = now()
    where club_id = p_club_id;

    return jsonb_build_object(
      'ok', false,
      'generated', false,
      'reason', 'active_manager_not_found',
      'expected_role', v_expected_role
    );
  end if;

  -- Old automatic forecasts outside the new rolling window are obsolete.
  update public.rider_regular_training_daily_plans p
  set
    status = 'superseded',
    decision_reason_json =
      coalesce(p.decision_reason_json, '{}'::jsonb)
      || jsonb_build_object(
        'superseded_reason', 'outside_new_rolling_window',
        'superseded_at', now()
      ),
    updated_at = now()
  where p.club_id = p_club_id
    and p.plan_date > v_through_date
    and p.source_type in ('head_coach', 'u23_head_coach')
    and p.status = 'planned';

  for r in
    select
      rd.id as rider_id,
      rd.birth_date,
      coalesce(rd.availability_status, 'fit') as availability_status,
      greatest(0, least(100, coalesce(rd.fatigue, 0)))::integer as fatigue,
      greatest(0, least(100, coalesce(rd.recovery, 50)))::integer as recovery_stat,
      greatest(0, least(100, coalesce(rd.morale, 50)))::integer as morale_value,
      greatest(0, coalesce(rd.consecutive_heavy_days, 0))::integer
        as consecutive_heavy_days,

      greatest(0, least(100, coalesce(rd.sprint, 50)))::integer as sprint,
      greatest(0, least(100, coalesce(rd.climbing, 50)))::integer as climbing,
      greatest(0, least(100, coalesce(rd.flat, 50)))::integer as flat,
      greatest(0, least(100, coalesce(rd.time_trial, 50)))::integer as time_trial,
      greatest(0, least(100, coalesce(rd.endurance, 50)))::integer as endurance,
      greatest(0, least(100, coalesce(rd.resistance, 50)))::integer as resistance,
      greatest(0, least(100, coalesce(rd.race_iq, 50)))::integer as race_iq,
      greatest(0, least(100, coalesce(rd.teamwork, 50)))::integer as teamwork,

      cr.assigned_role::text as assigned_role,

      rp.focus_code as preferred_focus_code
    from public.club_riders cr
    join public.riders rd
      on rd.id = cr.rider_id
    left join lateral (
      select
        p.focus_code
      from public.rider_regular_training_plans p
      where p.club_id = p_club_id
        and p.rider_id = rd.id
        and coalesce(p.is_active, true) = true
      order by
        p.updated_at desc nulls last,
        p.created_at desc nulls last
      limit 1
    ) rp on true
    where cr.club_id = p_club_id
    order by rd.id
  loop
    select
      m.management_mode
    into v_management_mode
    from public.rider_regular_training_management m
    where m.club_id = p_club_id
      and m.rider_id = r.rider_id;

    v_management_mode :=
      coalesce(v_management_mode, 'inherit');

    if v_management_mode = 'manual' then
      v_manual_riders := v_manual_riders + 1;

      update public.rider_regular_training_daily_plans p
      set
        status = 'superseded',
        decision_reason_json =
          coalesce(p.decision_reason_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_reason', 'rider_is_manually_managed',
            'superseded_at', now()
          ),
        updated_at = now()
      where p.club_id = p_club_id
        and p.rider_id = r.rider_id
        and p.plan_date between v_anchor_date and v_through_date
        and p.source_type in ('head_coach', 'u23_head_coach')
        and p.status = 'planned';

      continue;
    end if;

    v_managed_riders := v_managed_riders + 1;
    v_projected_fatigue := r.fatigue;
    v_projected_heavy_days := r.consecutive_heavy_days;
    v_hard_used := false;
    v_previous_external_load := false;

    v_age :=
      case
        when r.birth_date is null then 25
        else extract(
          year from age(v_anchor_date, r.birth_date)
        )::integer
      end;

    v_preferred_focus :=
      case
        when r.preferred_focus_code in (
          'general',
          'sprint',
          'climbing',
          'flat',
          'time_trial',
          'endurance',
          'resistance',
          'race_iq',
          'teamwork'
        )
        then r.preferred_focus_code
        else null
      end;

    v_specialization_focus :=
      case
        when lower(coalesce(v_staff.specialization, '')) like '%sprint%'
          then 'sprint'
        when lower(coalesce(v_staff.specialization, '')) like '%climb%'
          or lower(coalesce(v_staff.specialization, '')) like '%mountain%'
          then 'climbing'
        when lower(coalesce(v_staff.specialization, '')) like '%time trial%'
          or lower(coalesce(v_staff.specialization, '')) like '%tt%'
          then 'time_trial'
        when lower(coalesce(v_staff.specialization, '')) like '%endurance%'
          then 'endurance'
        when lower(coalesce(v_staff.specialization, '')) like '%flat%'
          then 'flat'
        when lower(coalesce(v_staff.specialization, '')) like '%team%'
          then 'teamwork'
        else null
      end;

    for v_day_offset in 0..2
    loop
      v_plan_date := v_anchor_date + v_day_offset;

      v_existing_source := null;
      v_existing_focus := null;
      v_existing_intensity := null;

      select
        p.source_type,
        p.focus_code,
        p.intensity
      into
        v_existing_source,
        v_existing_focus,
        v_existing_intensity
      from public.rider_regular_training_daily_plans p
      where p.club_id = p_club_id
        and p.rider_id = r.rider_id
        and p.plan_date = v_plan_date;


      v_has_existing_activity := exists (
        select 1
        from public.rider_daily_activity a
        where a.rider_id = r.rider_id
          and a.activity_date = v_plan_date
      );

      v_has_health_block := exists (
        select 1
        from public.rider_health_cases hc
        where hc.rider_id = r.rider_id
          and hc.status in ('active', 'recovering')
          and hc.training_blocked = true
          and v_plan_date between
            hc.started_on
            and coalesce(
              hc.recovery_until,
              hc.active_until
            )
      );

      v_has_training_camp := exists (
        select 1
        from public.training_camp_participants tcp
        join public.training_camp_bookings tcb
          on tcb.id = tcp.booking_id
        where tcp.rider_id = r.rider_id
          and tcb.status in ('planned', 'active')
          and v_plan_date between
            tcb.start_date
            and tcb.end_date
      );

      v_has_race_commitment := exists (
        select 1
        from public.race_preparation_riders rpr
        join public.race_preparations rp
          on rp.id = rpr.race_preparation_id
        join public.races rr
          on rr.id = rp.race_id
        where rpr.rider_id = r.rider_id
          and rp.participating_club_id = p_club_id
          and rp.status in ('submitted', 'locked')
          and v_plan_date between rr.start_date and rr.end_date
          and exists (
            select 1
            from public.race_stages rs
            where rs.race_id = rr.id
              and coalesce(rs.weather_cancelled, false) = false
          )
      );

      v_has_upcoming_race := exists (
        select 1
        from public.race_preparation_riders rpr
        join public.race_preparations rp
          on rp.id = rpr.race_preparation_id
        join public.races rr
          on rr.id = rp.race_id
        where rpr.rider_id = r.rider_id
          and rp.participating_club_id = p_club_id
          and rp.status in ('submitted', 'locked')
          and rr.start_date between
            v_plan_date
            and v_plan_date + 2
          and exists (
            select 1
            from public.race_stages rs
            where rs.race_id = rr.id
              and coalesce(rs.weather_cancelled, false) = false
          )
      );

      v_status := 'planned';
      v_block_reason := null;
      v_focus_code := null;
      v_intensity := null;

      if v_has_existing_activity then
        v_status := 'skipped';
        v_block_reason := 'activity_already_exists';

      elsif v_day_offset = 0
        and r.availability_status in ('injured', 'sick') then
        v_status := 'skipped';
        v_block_reason := 'rider_unavailable';

      elsif v_has_health_block then
        v_status := 'skipped';
        v_block_reason := 'health_case_blocks_training';

      elsif v_has_training_camp then
        v_status := 'skipped';
        v_block_reason := 'training_camp_controls_activity';

      elsif v_has_race_commitment then
        v_status := 'skipped';
        v_block_reason := 'race_commitment_controls_activity';
      end if;


      if v_existing_source = 'manual_override' then
        if v_status <> 'planned' then
          update public.rider_regular_training_daily_plans p
          set
            status = 'skipped',
            decision_reason_json =
              coalesce(p.decision_reason_json, '{}'::jsonb)
              || jsonb_build_object(
                'blocked_after_override',
                  true,
                'block_reason',
                  v_block_reason,
                'blocked_at',
                  now()
              ),
            updated_at = now()
          where p.club_id = p_club_id
            and p.rider_id = r.rider_id
            and p.plan_date = v_plan_date
            and p.source_type = 'manual_override';

          v_skipped := v_skipped + 1;

          if v_block_reason in (
            'training_camp_controls_activity',
            'race_commitment_controls_activity',
            'activity_already_exists'
          ) then
            v_previous_external_load := true;
          end if;

          continue;
        end if;

        v_manual_preserved := v_manual_preserved + 1;

        if v_existing_focus = 'day_off' then
          v_fatigue_load := 0;
          v_recovery_bonus := 3;

        elsif v_existing_focus = 'recovery' then
          v_fatigue_load := 0;
          v_recovery_bonus := 2;

        elsif v_existing_intensity = 'light' then
          v_fatigue_load := 6;
          v_recovery_bonus := 0;

        elsif v_existing_intensity = 'hard' then
          v_fatigue_load := 14;
          v_recovery_bonus := 0;
          v_hard_used := true;

        else
          v_fatigue_load := 10;
          v_recovery_bonus := 0;
        end if;

        if v_fatigue_load >= 13 then
          v_projected_heavy_days :=
            v_projected_heavy_days + 1;
        else
          v_projected_heavy_days := 0;
        end if;

        v_heavy_bonus :=
          case
            when v_projected_heavy_days <= 1 then 0
            when v_projected_heavy_days = 2 then 3
            when v_projected_heavy_days = 3 then 6
            else 9
          end;

        v_daily_recovery := round(
          6
          + (r.recovery_stat * 0.1)
          + case
              when v_fatigue_load = 0 then 2
              else 0
            end
          + case
              when r.morale_value >= 80 then 1
              else 0
            end
          - case
              when r.morale_value < 40 then 1
              else 0
            end
          - case
              when v_age >= 31 then 1
              else 0
            end
        )::integer;

        v_daily_recovery :=
          greatest(3, v_daily_recovery)
          + v_recovery_bonus;

        v_projected_fatigue :=
          greatest(
            0,
            least(
              100,
              round(
                v_projected_fatigue
                + v_fatigue_load
                + v_heavy_bonus
                - v_daily_recovery
              )::integer
            )
          );

        v_previous_external_load := false;
        continue;
      end if;

      v_staff_factor :=
        coalesce(
          public.get_staff_assignment_availability_factor(
            v_staff.id,
            v_plan_date
          ),
          1.0
        );

      select exists (
        select 1
        from public.staff_courses sc
        where sc.staff_id = v_staff.id
          and sc.status = 'active'
          and sc.started_game_date <= v_plan_date
          and sc.completes_on_game_date >= v_plan_date
      )
      into v_has_active_course;

      if v_has_active_course then
        v_staff_factor := 0;
      end if;

      v_staff_factor :=
        greatest(
          0,
          least(1, v_staff_factor)
        );

      if v_status = 'planned'
         and v_staff_factor <= 0 then
        v_status := 'skipped';
        v_block_reason := 'head_coach_unavailable';
      end if;

      v_training_score :=
        greatest(0, least(100, v_staff.expertise));
      v_recovery_planning_score :=
        greatest(0, least(100, v_staff.efficiency));
      v_youth_score :=
        greatest(0, least(100, v_staff.potential));
      v_experience_score :=
        greatest(0, least(100, v_staff.experience));
      v_leadership_score :=
        greatest(0, least(100, v_staff.leadership));
      v_loyalty_score :=
        greatest(0, least(100, v_staff.loyalty));

      if v_age <= 23 then
        v_quality := round(
          (
            v_training_score * 0.30
            + v_recovery_planning_score * 0.25
            + v_youth_score * 0.20
            + v_experience_score * 0.10
            + v_leadership_score * 0.10
            + v_loyalty_score * 0.05
          )
          * v_staff_factor,
          2
        );
      else
        v_quality := round(
          (
            v_training_score * 0.35
            + v_recovery_planning_score * 0.25
            + v_experience_score * 0.20
            + v_leadership_score * 0.15
            + v_loyalty_score * 0.05
          )
          * v_staff_factor,
          2
        );
      end if;

      v_primary_focus :=
        case r.assigned_role
          when 'Leader' then 'climbing'
          when 'Sprinter' then 'sprint'
          when 'Climber' then 'climbing'
          when 'TT' then 'time_trial'
          when 'Domestique' then 'teamwork'
          when 'Breakaway' then 'endurance'
          else 'general'
        end;

      v_focus_candidates :=
        case r.assigned_role
          when 'Leader' then
            array[
              'climbing',
              'endurance',
              'resistance',
              'race_iq',
              'time_trial'
            ]
          when 'Sprinter' then
            array[
              'sprint',
              'flat',
              'teamwork',
              'endurance',
              'resistance'
            ]
          when 'Climber' then
            array[
              'climbing',
              'endurance',
              'resistance',
              'race_iq'
            ]
          when 'TT' then
            array[
              'time_trial',
              'flat',
              'endurance',
              'resistance'
            ]
          when 'Domestique' then
            array[
              'teamwork',
              'endurance',
              'flat',
              'resistance',
              'race_iq'
            ]
          when 'Breakaway' then
            array[
              'endurance',
              'resistance',
              'flat',
              'race_iq',
              'climbing'
            ]
          else
            array[
              'sprint',
              'climbing',
              'flat',
              'time_trial',
              'endurance',
              'resistance',
              'race_iq',
              'teamwork'
            ]
        end;

      if v_preferred_focus is not null then
        v_target_focus := v_preferred_focus;

      elsif v_quality < 45 then
        v_target_focus := 'general';

      elsif v_quality < 65 then
        if v_specialization_focus = any(v_focus_candidates) then
          v_target_focus := v_specialization_focus;
        else
          v_target_focus := v_primary_focus;
        end if;

      else
        select
          x.focus_code
        into v_target_focus
        from (
          values
            ('sprint', r.sprint),
            ('climbing', r.climbing),
            ('flat', r.flat),
            ('time_trial', r.time_trial),
            ('endurance', r.endurance),
            ('resistance', r.resistance),
            ('race_iq', r.race_iq),
            ('teamwork', r.teamwork)
        ) as x(focus_code, skill_value)
        where x.focus_code = any(v_focus_candidates)
        order by
          x.skill_value asc,
          case
            when x.focus_code = v_specialization_focus then 0
            else 1
          end,
          x.focus_code
        limit 1;
      end if;

      if v_status = 'planned' then
        if v_projected_fatigue >= 70 then
          v_focus_code := 'day_off';
          v_intensity := 'normal';

        elsif v_projected_fatigue >= 60 then
          v_focus_code := 'recovery';
          v_intensity := 'normal';

        elsif v_previous_external_load then
          v_focus_code := 'recovery';
          v_intensity := 'normal';

        elsif v_has_upcoming_race
          and v_projected_fatigue >= 35 then
          v_focus_code := 'recovery';
          v_intensity := 'normal';

        elsif v_has_upcoming_race then
          v_focus_code :=
            coalesce(v_target_focus, 'general');
          v_intensity := 'light';

        elsif v_projected_fatigue >= 50
          and v_recovery_planning_score >= 65 then
          v_focus_code := 'recovery';
          v_intensity := 'normal';

        elsif v_projected_fatigue >= 45 then
          v_focus_code :=
            coalesce(v_target_focus, 'general');
          v_intensity := 'light';

        elsif
          v_quality >= 85
          and v_recovery_planning_score >= 80
          and v_training_score >= 75
          and v_projected_fatigue <= 15
          and v_staff_factor >= 0.75
          and v_hard_used = false
        then
          v_focus_code :=
            coalesce(v_target_focus, 'general');
          v_intensity := 'hard';
          v_hard_used := true;

        else
          v_focus_code :=
            coalesce(v_target_focus, 'general');
          v_intensity := 'normal';
        end if;

        if v_focus_code = 'day_off' then
          v_fatigue_load := 0;
          v_recovery_bonus := 3;

        elsif v_focus_code = 'recovery' then
          v_fatigue_load := 0;
          v_recovery_bonus := 2;

        elsif v_intensity = 'light' then
          v_fatigue_load := 6;
          v_recovery_bonus := 0;

        elsif v_intensity = 'normal' then
          v_fatigue_load := 10;
          v_recovery_bonus := 0;

        else
          v_fatigue_load := 14;
          v_recovery_bonus := 0;
        end if;

        if v_fatigue_load >= 13 then
          v_projected_heavy_days :=
            v_projected_heavy_days + 1;
        else
          v_projected_heavy_days := 0;
        end if;

        v_heavy_bonus :=
          case
            when v_projected_heavy_days <= 1 then 0
            when v_projected_heavy_days = 2 then 3
            when v_projected_heavy_days = 3 then 6
            else 9
          end;

        v_daily_recovery := round(
          6
          + (r.recovery_stat * 0.1)
          + case
              when v_fatigue_load = 0 then 2
              else 0
            end
          + case
              when r.morale_value >= 80 then 1
              else 0
            end
          - case
              when r.morale_value < 40 then 1
              else 0
            end
          - case
              when v_age >= 31 then 1
              else 0
            end
        )::integer;

        v_daily_recovery :=
          greatest(3, v_daily_recovery)
          + v_recovery_bonus;

        v_projected_after :=
          greatest(
            0,
            least(
              100,
              round(
                v_projected_fatigue
                + v_fatigue_load
                + v_heavy_bonus
                - v_daily_recovery
              )::integer
            )
          );

        v_previous_external_load := false;
      else
        v_projected_after := v_projected_fatigue;

        if v_block_reason in (
          'training_camp_controls_activity',
          'race_commitment_controls_activity',
          'activity_already_exists'
        ) then
          v_previous_external_load := true;
        end if;
      end if;

      v_reason := jsonb_build_object(
        'version',
          'head_coach_three_day_generator_v1',
        'rolling_horizon_days',
          3,
        'day_offset',
          v_day_offset,
        'management_mode',
          v_management_mode,
        'block_reason',
          v_block_reason,
        'assigned_role',
          r.assigned_role,
        'coach_specialization',
          v_staff.specialization,
        'specialization_focus',
          v_specialization_focus,
        'preferred_focus',
          v_preferred_focus,
        'selected_focus',
          v_focus_code,
        'selected_intensity',
          v_intensity,
        'upcoming_race_within_two_days',
          v_has_upcoming_race,
        'previous_external_load',
          v_previous_external_load,
        'fatigue_before',
          v_projected_fatigue,
        'fatigue_after_estimate',
          v_projected_after,
        'coach_scores',
          jsonb_build_object(
            'training',
              v_training_score,
            'recovery_planning',
              v_recovery_planning_score,
            'youth_development',
              v_youth_score,
            'experience',
              v_experience_score,
            'leadership',
              v_leadership_score,
            'loyalty',
              v_loyalty_score,
            'availability_factor',
              v_staff_factor,
            'decision_quality',
              v_quality
          ),
        'forecast_notice',
          'Tomorrow and Day +2 are forecasts and are recalculated every game day.'
      );

      insert into public.rider_regular_training_daily_plans (
        club_id,
        rider_id,
        plan_date,
        focus_code,
        intensity,
        source_type,
        source_staff_id,
        status,
        decision_quality_score,
        coach_availability_factor,
        fatigue_snapshot,
        availability_status_snapshot,
        projected_fatigue_after,
        decision_reason_json,
        generated_on_game_date,
        generated_at,
        consumed_at,
        updated_at
      )
      values (
        p_club_id,
        r.rider_id,
        v_plan_date,
        v_focus_code,
        v_intensity,
        v_expected_role,
        v_staff.id,
        v_status,
        v_quality,
        v_staff_factor,
        v_projected_fatigue::smallint,
        r.availability_status,
        v_projected_after::smallint,
        v_reason,
        v_anchor_date,
        now(),
        null,
        now()
      )
      on conflict (
        club_id,
        rider_id,
        plan_date
      )
      do update
      set
        focus_code = excluded.focus_code,
        intensity = excluded.intensity,
        source_type = excluded.source_type,
        source_staff_id = excluded.source_staff_id,
        status = excluded.status,
        decision_quality_score =
          excluded.decision_quality_score,
        coach_availability_factor =
          excluded.coach_availability_factor,
        fatigue_snapshot =
          excluded.fatigue_snapshot,
        availability_status_snapshot =
          excluded.availability_status_snapshot,
        projected_fatigue_after =
          excluded.projected_fatigue_after,
        decision_reason_json =
          excluded.decision_reason_json,
        generated_on_game_date =
          excluded.generated_on_game_date,
        generated_at =
          excluded.generated_at,
        consumed_at = null,
        updated_at = now()
      where
        public.rider_regular_training_daily_plans.source_type
          <> 'manual_override';

      if v_status = 'planned' then
        v_generated := v_generated + 1;
        v_projected_fatigue := v_projected_after;
      else
        v_skipped := v_skipped + 1;
      end if;
    end loop;
  end loop;

  update public.club_regular_training_automation
  set
    last_generated_game_date = v_anchor_date,
    last_generated_through = v_through_date,
    last_generation_summary = jsonb_build_object(
      'ok', true,
      'version', 'head_coach_three_day_generator_v1',
      'manager_staff_id', v_staff.id,
      'manager_staff_name', v_staff.staff_name,
      'manager_role', v_expected_role,
      'managed_riders', v_managed_riders,
      'manual_riders', v_manual_riders,
      'planned_rows', v_generated,
      'skipped_rows', v_skipped,
      'manual_overrides_preserved', v_manual_preserved,
      'anchor_date', v_anchor_date,
      'through_date', v_through_date
    ),
    metadata =
      coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'generator_version',
          'head_coach_three_day_generator_v1',
        'generator_installed',
          true
      ),
    updated_at = now()
  where club_id = p_club_id;

  return jsonb_build_object(
    'ok', true,
    'generated', true,
    'version', 'head_coach_three_day_generator_v1',
    'club_id', p_club_id,
    'manager_staff_id', v_staff.id,
    'manager_staff_name', v_staff.staff_name,
    'manager_role', v_expected_role,
    'managed_riders', v_managed_riders,
    'manual_riders', v_manual_riders,
    'planned_rows', v_generated,
    'skipped_rows', v_skipped,
    'manual_overrides_preserved', v_manual_preserved,
    'anchor_date', v_anchor_date,
    'through_date', v_through_date
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_coach_training_plans_v1(p_anchor_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_anchor_date date;
  v_results jsonb := '[]'::jsonb;
  v_result jsonb;
  a record;
begin
  v_anchor_date :=
    coalesce(
      p_anchor_date,
      public.get_current_game_date_date()
    );

  if v_anchor_date is null then
    raise exception
      'process_daily_coach_training_plans_v1: game date is missing';
  end if;

  for a in
    select
      club_id
    from public.club_regular_training_automation
    where is_enabled = true
    order by club_id
  loop
    begin
      v_result :=
        public.generate_coach_regular_training_plan_v1(
          a.club_id,
          v_anchor_date
        );

      v_results :=
        v_results || jsonb_build_array(v_result);

    exception
      when others then
        update public.club_regular_training_automation
        set
          last_generated_game_date = v_anchor_date,
          last_generated_through = v_anchor_date + 2,
          last_generation_summary = jsonb_build_object(
            'ok', false,
            'version', 'head_coach_three_day_generator_v1',
            'error', sqlerrm,
            'anchor_date', v_anchor_date
          ),
          updated_at = now()
        where club_id = a.club_id;

        v_results :=
          v_results
          || jsonb_build_array(
            jsonb_build_object(
              'ok', false,
              'club_id', a.club_id,
              'error', sqlerrm
            )
          );
    end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'version', 'head_coach_three_day_generator_v1',
    'anchor_date', v_anchor_date,
    'enabled_team_count',
      jsonb_array_length(v_results),
    'results', v_results
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_regular_training_coach_plan_v1(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_manage_club_training_v1(p_club_id) then
    raise exception
      'You do not have permission to refresh this team plan.';
  end if;

  return public.generate_coach_regular_training_plan_v1(
    p_club_id,
    public.get_current_game_date_date()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_regular_training_base_head_coach_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_current_game_date date;
  v_processed_date date;
  v_iso_dow integer;

  r record;

  v_birth_date date;
  v_club_id uuid;
  v_country_code text;
  v_team_scope text;

  v_focus_code text;
  v_resolved_intensity text;
  v_auto_when_free boolean;
  v_preferred_days integer[];

  v_used_rider_plan boolean;
  v_used_club_default boolean;

  v_activity_type text;
  v_fatigue_load integer;
  v_recovery_bonus integer;
  v_development_value_base numeric;
  v_development_eligible boolean;

  v_weather_state text;
  v_weather_modifier numeric;

  v_availability_modifier numeric;
  v_rider_age integer;

  v_has_blocking_case boolean;

  v_coach_training_multiplier numeric := 1.0;
  v_coach_development_multiplier numeric := 1.0;
  v_coach_youth_multiplier numeric := 1.0;

  v_final_development_value numeric := 0;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'process_daily_regular_training: could not resolve current game date';
  end if;

  v_processed_date := (v_current_game_date - interval '1 day')::date;
  v_iso_dow := extract(isodow from v_processed_date)::int;

  for r in
    with rider_base as (
      select
        rd.id as rider_id,
        rd.birth_date,
        coalesce(rd.availability_status, 'fit') as availability_status,
        cr.club_id,
        c.country_code,
        case
          when coalesce(c.club_type, 'main') = 'developing' then 'u23'
          else 'first_team'
        end as team_scope
      from public.riders rd
      join public.club_riders cr
        on cr.rider_id = rd.id
      join public.clubs c
        on c.id = cr.club_id
      where c.deleted_at is null
    )
    select
      rb.rider_id,
      rb.birth_date,
      rb.availability_status,
      rb.club_id,
      rb.country_code,
      rb.team_scope,

      rp.focus_code as rider_plan_focus_code,
      rp.intensity as rider_plan_intensity,
      rp.auto_when_free as rider_plan_auto_when_free,
      rp.preferred_days as rider_plan_preferred_days,

      cd.focus_code as default_focus_code,
      cd.intensity as default_intensity,
      cd.auto_when_free as default_auto_when_free
    from rider_base rb
    left join lateral (
      select
        p.focus_code,
        p.intensity,
        p.auto_when_free,
        p.preferred_days
      from public.rider_regular_training_plans p
      where p.rider_id = rb.rider_id
        and p.club_id = rb.club_id
        and coalesce(p.is_active, true) = true
      order by p.updated_at desc nulls last, p.created_at desc nulls last
      limit 1
    ) rp on true
    left join lateral (
      select
        d.focus_code,
        d.intensity,
        d.auto_when_free
      from public.club_regular_training_defaults d
      where d.club_id = rb.club_id
        and d.team_scope in (rb.team_scope, 'all')
      order by
        case
          when d.team_scope = rb.team_scope then 0
          when d.team_scope = 'all' then 1
          else 2
        end,
        d.updated_at desc nulls last,
        d.created_at desc nulls last
      limit 1
    ) cd on true
  loop
    if exists (
      select 1
      from public.rider_daily_activity a
      where a.rider_id = r.rider_id
        and a.activity_date = v_processed_date
    ) then
      continue;
    end if;

    v_birth_date := r.birth_date;
    v_club_id := r.club_id;
    v_country_code := r.country_code;
    v_team_scope := r.team_scope;

    v_focus_code := coalesce(r.rider_plan_focus_code, r.default_focus_code);
    v_resolved_intensity := coalesce(r.rider_plan_intensity, r.default_intensity);
    v_auto_when_free := coalesce(r.rider_plan_auto_when_free, r.default_auto_when_free, false);

    v_used_rider_plan := r.rider_plan_focus_code is not null;
    v_used_club_default := r.rider_plan_focus_code is null and r.default_focus_code is not null;

    if v_focus_code is null or v_resolved_intensity is null then
      continue;
    end if;

    if coalesce(v_auto_when_free, false) = false then
      continue;
    end if;

    v_preferred_days := r.rider_plan_preferred_days;

    if v_preferred_days is not null and array_length(v_preferred_days, 1) is not null then
      if not (v_iso_dow = any(v_preferred_days)) then
        continue;
      end if;
    end if;

    if r.availability_status in ('injured', 'sick') then
      continue;
    end if;

    select exists (
      select 1
      from public.rider_health_cases hc
      where hc.rider_id = r.rider_id
        and hc.status in ('active', 'recovering')
        and hc.training_blocked = true
    )
    into v_has_blocking_case;

    if v_has_blocking_case then
      continue;
    end if;

    v_activity_type := 'training';
    v_development_eligible := true;
    v_recovery_bonus := 0;

    if v_focus_code = 'day_off' then
      -- Day off is intentionally not training.
      -- Store it as recovery-type activity to avoid needing a new activity_type constraint.
      v_activity_type := 'recovery';
      v_development_eligible := false;
      v_resolved_intensity := 'normal';
    elsif v_focus_code = 'recovery' then
      v_activity_type := 'recovery';
      v_development_eligible := false;
    end if;

    if v_resolved_intensity = 'hard' and r.availability_status = 'not_fully_fit' then
      v_resolved_intensity := 'normal';
    end if;

    if v_focus_code = 'recovery' and v_resolved_intensity = 'hard' then
      v_resolved_intensity := 'normal';
    end if;

    if v_focus_code = 'day_off' then
      -- Full rest day:
      -- no skill gain, no fatigue load, stronger recovery support.
      v_fatigue_load := 0;
      v_recovery_bonus := 3;
      v_development_value_base := 0;

    elsif v_activity_type = 'recovery' then
      if v_resolved_intensity = 'light' then
        v_fatigue_load := 0;
        v_recovery_bonus := 2;
        v_development_value_base := 0;
      elsif v_resolved_intensity = 'normal' then
        v_fatigue_load := 0;
        v_recovery_bonus := 2;
        v_development_value_base := 0;
      else
        v_fatigue_load := 0;
        v_recovery_bonus := 0;
        v_development_value_base := 0;
      end if;

    else
      if v_resolved_intensity = 'light' then
        v_fatigue_load := 6;
        v_development_value_base := 0.006;
      elsif v_resolved_intensity = 'normal' then
        v_fatigue_load := 10;
        v_development_value_base := 0.012;
      else
        v_fatigue_load := 14;
        v_development_value_base := 0.018;
      end if;
    end if;

    begin
      select
        ws.weather_state,
        ws.weather_modifier
      into
        v_weather_state,
        v_weather_modifier
      from public.get_regular_training_weather_state(v_country_code, v_processed_date) ws
      limit 1;
    exception
      when others then
        v_weather_state := 'normal';
        v_weather_modifier := 1.0;
    end;

    v_weather_state := coalesce(v_weather_state, 'normal');
    v_weather_modifier := coalesce(v_weather_modifier, 1.0);

    v_availability_modifier :=
      case
        when r.availability_status = 'fit' then 1.00
        when r.availability_status = 'not_fully_fit' then 0.80
        else 0.00
      end;

    v_coach_training_multiplier := 1.0;
    v_coach_development_multiplier := 1.0;
    v_coach_youth_multiplier := 1.0;

    if v_club_id is not null then
      select
        training_efficiency_multiplier,
        development_multiplier,
        youth_dev_multiplier
      into
        v_coach_training_multiplier,
        v_coach_development_multiplier,
        v_coach_youth_multiplier
      from public.get_head_coach_effects(v_club_id);
    end if;

    if v_birth_date is not null then
      v_rider_age := extract(year from age(v_processed_date, v_birth_date))::int;
    else
      v_rider_age := 0;
    end if;

    v_final_development_value :=
      v_development_value_base
      * coalesce(v_weather_modifier, 1.0)
      * coalesce(v_availability_modifier, 1.0)
      * coalesce(v_coach_training_multiplier, 1.0)
      * coalesce(v_coach_development_multiplier, 1.0);

    if v_rider_age > 0 and v_rider_age <= 23 then
      v_final_development_value :=
        v_final_development_value
        * coalesce(v_coach_youth_multiplier, 1.0);
    end if;

    insert into public.rider_daily_activity (
      rider_id,
      activity_date,
      participated,
      source,
      activity_type,
      intensity,
      fatigue_load,
      recovery_bonus,
      metadata
    )
    values (
      r.rider_id,
      v_processed_date,
      case when v_focus_code = 'day_off' then false else true end,
      'regular_training',
      v_activity_type,
      v_resolved_intensity,
      v_fatigue_load,
      v_recovery_bonus,
      jsonb_build_object(
        'training_system', 'regular_training',
        'focus_code', v_focus_code,
        'regular_training_display_label',
          case
            when v_focus_code = 'day_off' then 'Day Off'
            else v_focus_code
          end,
        'is_day_off', v_focus_code = 'day_off',
        'resolved_intensity',
          case
            when v_focus_code = 'day_off' then null
            else v_resolved_intensity
          end,
        'weather_state', v_weather_state,
        'weather_modifier', v_weather_modifier,
        'availability_modifier', v_availability_modifier,
        'development_value_base', v_final_development_value,
        'used_rider_plan', v_used_rider_plan,
        'used_club_default', v_used_club_default,
        'development_eligible', v_development_eligible,
        'coach_training_multiplier', coalesce(v_coach_training_multiplier, 1.0),
        'coach_development_multiplier', coalesce(v_coach_development_multiplier, 1.0),
        'coach_youth_multiplier',
          case
            when v_rider_age > 0 and v_rider_age <= 23 then coalesce(v_coach_youth_multiplier, 1.0)
            else 1.0
          end,
        'staff_training_modifier_applied',
          case when v_focus_code = 'day_off' then false else true end,
        'team_scope', v_team_scope
      )
    )
    on conflict do nothing;
  end loop;

  return;
end;$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_tick_base_head_coach_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season int;
  v_month smallint;
  v_day smallint;
  v_paused boolean;

begin
  select season_number, month_number, day_number, is_paused
    into v_season, v_month, v_day, v_paused
  from public.game_state
  where id = true;

  if coalesce(v_paused, false) then
    return;
  end if;

  begin
    perform public.run_retirement_daily_jobs();
  exception when others then
    raise warning 'run_retirement_daily_jobs failed: %', sqlerrm;
  end;

  begin
    perform public.process_daily_training_camp_activities();
  exception when others then
    raise warning 'process_daily_training_camp_activities failed: %', sqlerrm;
  end;

  begin
    perform public.process_daily_regular_training();
  exception when others then
    raise warning 'process_daily_regular_training failed: %', sqlerrm;
  end;

  /*
    Training camp processor is intentionally before fatigue.

    Reason:
    process_daily_training_camps() can touch rider_daily_activity,
    fatigue_load, and recovery_bonus. Therefore it must run before
    process_daily_fatigue(), so same-day camp load is available to
    the fatigue engine.
  */
  begin
    perform public.process_daily_training_camps();
  exception when others then
    raise warning 'process_daily_training_camps failed: %', sqlerrm;
  end;

  begin
    perform public.process_weekly_rider_development();
  exception when others then
    raise warning 'process_weekly_rider_development failed: %', sqlerrm;
  end;

  begin
    perform public.finance_process_weekly_rider_wages_guarded_v1();
  exception when others then
    raise warning 'finance_process_weekly_rider_wages_guarded_v1 failed: %', sqlerrm;
  end;

  begin
    perform public.finance_process_weekly_team_policy_costs();
  exception when others then
    raise warning 'finance_process_weekly_team_policy_costs failed: %', sqlerrm;
  end;

  begin
    perform public.process_daily_fatigue();
  exception when others then
    raise warning 'process_daily_fatigue failed: %', sqlerrm;
  end;

  begin
    perform public.process_daily_health_cases();
  exception when others then
    raise warning 'process_daily_health_cases failed: %', sqlerrm;
  end;

  begin
    perform public.process_daily_morale_v1();
  exception when others then
    raise warning 'process_daily_morale_v1 failed: %', sqlerrm;
  end;

  begin
    perform public.process_staff_courses();
  exception when others then
    raise warning 'process_staff_courses failed: %', sqlerrm;
  end;

  begin
    perform public.staff_market_run_daily_refresh(150, 72);
  exception when others then
    raise warning 'staff_market_run_daily_refresh failed: %', sqlerrm;
  end;

  begin
    perform public.complete_due_rider_scout_tasks();
  exception when others then
    raise warning 'complete_due_rider_scout_tasks failed: %', sqlerrm;
  end;

  begin
    perform public.create_staff_contract_expiry_notifications();
  exception when others then
    raise warning 'create_staff_contract_expiry_notifications failed: %', sqlerrm;
  end;

  begin
    perform public.run_daily_market_jobs_detailed();
  exception when others then
    raise warning 'run_daily_market_jobs_detailed failed: %', sqlerrm;
  end;

  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_coach_regular_training_v1(p_processed_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_game_date date;
  v_processed_date date;

  r record;

  v_focus_code text;
  v_resolved_intensity text;

  v_activity_type text;
  v_fatigue_load integer;
  v_recovery_bonus integer;
  v_development_value_base numeric;
  v_development_eligible boolean;

  v_weather_state text;
  v_weather_modifier numeric;

  v_availability_modifier numeric;
  v_rider_age integer;

  v_has_blocking_case boolean;
  v_has_training_camp boolean;
  v_has_race_commitment boolean;
  v_manager_is_valid boolean;

  v_coach_training_multiplier numeric := 1.0;
  v_coach_development_multiplier numeric := 1.0;
  v_coach_youth_multiplier numeric := 1.0;

  v_final_development_value numeric := 0;

  v_inserted_rows integer := 0;
  v_consumed_rows integer := 0;
  v_skipped_rows integer := 0;
  v_superseded_rows integer := 0;
  v_row_count integer;
begin
  v_current_game_date :=
    public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception
      'process_daily_coach_regular_training_v1: could not resolve current game date';
  end if;

  v_processed_date :=
    coalesce(
      p_processed_date,
      (v_current_game_date - interval '1 day')::date
    );

  for r in
    select
      p.id as daily_plan_id,
      p.club_id,
      p.rider_id,
      p.plan_date,
      p.focus_code,
      p.intensity,
      p.source_type,
      p.source_staff_id,
      p.decision_quality_score,
      p.coach_availability_factor,
      p.fatigue_snapshot,
      p.projected_fatigue_after,
      p.decision_reason_json,

      rd.birth_date,
      coalesce(
        rd.availability_status,
        'fit'
      ) as availability_status,

      c.country_code,

      case
        when coalesce(c.club_type, 'main') = 'developing'
          then 'u23'
        else 'first_team'
      end as team_scope,

      coalesce(
        m.management_mode,
        'inherit'
      ) as management_mode

    from public.rider_regular_training_daily_plans p

    join public.club_riders cr
      on cr.club_id = p.club_id
     and cr.rider_id = p.rider_id

    join public.riders rd
      on rd.id = p.rider_id

    join public.clubs c
      on c.id = p.club_id
     and c.deleted_at is null

    left join public.rider_regular_training_management m
      on m.club_id = p.club_id
     and m.rider_id = p.rider_id

    where p.plan_date = v_processed_date
      and p.status = 'planned'
      and p.source_type in (
        'head_coach',
        'u23_head_coach',
        'manual_override'
      )

    order by
      p.club_id,
      p.rider_id
  loop
    -- A permanent Manual rider must not consume an old automatic forecast.
    if r.source_type in (
         'head_coach',
         'u23_head_coach'
       )
       and r.management_mode = 'manual' then

      update public.rider_regular_training_daily_plans
      set
        status = 'superseded',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'superseded',
            'consumption_reason',
              'rider_is_manually_managed',
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_superseded_rows :=
        v_superseded_rows + 1;

      continue;
    end if;

    -- Automatic plans are valid only while the same automation owner remains
    -- enabled. A manual one-day override remains valid independently.
    if r.source_type in (
         'head_coach',
         'u23_head_coach'
       ) then

      select exists (
        select 1
        from public.club_regular_training_automation a
        where a.club_id = r.club_id
          and a.is_enabled = true
          and a.manager_role = r.source_type
          and a.manager_staff_id = r.source_staff_id
      )
      into v_manager_is_valid;

      if not v_manager_is_valid then
        update public.rider_regular_training_daily_plans
        set
          status = 'superseded',
          decision_reason_json =
            coalesce(
              decision_reason_json,
              '{}'::jsonb
            )
            || jsonb_build_object(
              'consumption_status',
                'superseded',
              'consumption_reason',
                'automation_owner_changed_or_disabled',
              'consumption_checked_at',
                now()
            ),
          updated_at = now()
        where id = r.daily_plan_id;

        v_superseded_rows :=
          v_superseded_rows + 1;

        continue;
      end if;
    end if;

    -- Another processor (race, camp, etc.) always has priority.
    if exists (
      select 1
      from public.rider_daily_activity a
      where a.rider_id = r.rider_id
        and a.activity_date = v_processed_date
    ) then
      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              'daily_activity_already_exists',
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;

      continue;
    end if;

    -- Re-check live health/availability at consumption time.
    if r.availability_status in (
         'injured',
         'sick'
       ) then
      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              'rider_unavailable_at_consumption',
            'availability_status',
              r.availability_status,
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;

      continue;
    end if;

    select exists (
      select 1
      from public.rider_health_cases hc
      where hc.rider_id = r.rider_id
        and hc.status in (
          'active',
          'recovering'
        )
        and hc.training_blocked = true
    )
    into v_has_blocking_case;

    if v_has_blocking_case then
      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              'health_case_blocks_training',
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;

      continue;
    end if;

    -- Defensive race/camp check in addition to the activity-table priority.
    select exists (
      select 1
      from public.training_camp_participants tcp
      join public.training_camp_bookings tcb
        on tcb.id = tcp.booking_id
      where tcp.rider_id = r.rider_id
        and tcb.status in (
          'planned',
          'active'
        )
        and v_processed_date between
          tcb.start_date
          and tcb.end_date
    )
    into v_has_training_camp;

    select exists (
      select 1
      from public.race_preparation_riders rpr
      join public.race_preparations rp
        on rp.id = rpr.race_preparation_id
      join public.races rr
        on rr.id = rp.race_id
      where rpr.rider_id = r.rider_id
        and rp.participating_club_id = r.club_id
        and rp.status in (
          'submitted',
          'locked'
        )
        and v_processed_date between
          rr.start_date
          and rr.end_date
        and exists (
          select 1
          from public.race_stages rs
          where rs.race_id = rr.id
            and rs.stage_date = v_processed_date
            and coalesce(
              rs.weather_cancelled,
              false
            ) = false
        )
    )
    into v_has_race_commitment;

    if v_has_training_camp
       or v_has_race_commitment then

      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              case
                when v_has_training_camp
                  then 'training_camp_controls_activity'
                else 'race_day_controls_activity'
              end,
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;

      continue;
    end if;

    v_focus_code :=
      r.focus_code;

    v_resolved_intensity :=
      r.intensity;

    if v_focus_code is null
       or v_resolved_intensity is null then

      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              'plan_values_missing',
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;

      continue;
    end if;

    -- Exact production regular-training activity rules.
    v_activity_type := 'training';
    v_development_eligible := true;
    v_recovery_bonus := 0;

    if v_focus_code = 'day_off' then
      v_activity_type := 'recovery';
      v_development_eligible := false;
      v_resolved_intensity := 'normal';

    elsif v_focus_code = 'recovery' then
      v_activity_type := 'recovery';
      v_development_eligible := false;
    end if;

    if v_resolved_intensity = 'hard'
       and r.availability_status = 'not_fully_fit' then
      v_resolved_intensity := 'normal';
    end if;

    if v_focus_code = 'recovery'
       and v_resolved_intensity = 'hard' then
      v_resolved_intensity := 'normal';
    end if;

    if v_focus_code = 'day_off' then
      v_fatigue_load := 0;
      v_recovery_bonus := 3;
      v_development_value_base := 0;

    elsif v_activity_type = 'recovery' then
      if v_resolved_intensity in (
           'light',
           'normal'
         ) then
        v_fatigue_load := 0;
        v_recovery_bonus := 2;
        v_development_value_base := 0;
      else
        v_fatigue_load := 0;
        v_recovery_bonus := 0;
        v_development_value_base := 0;
      end if;

    else
      if v_resolved_intensity = 'light' then
        v_fatigue_load := 6;
        v_development_value_base := 0.006;

      elsif v_resolved_intensity = 'normal' then
        v_fatigue_load := 10;
        v_development_value_base := 0.012;

      else
        v_fatigue_load := 14;
        v_development_value_base := 0.018;
      end if;
    end if;

    begin
      select
        ws.weather_state,
        ws.weather_modifier
      into
        v_weather_state,
        v_weather_modifier
      from public.get_regular_training_weather_state(
        r.country_code,
        v_processed_date
      ) ws
      limit 1;

    exception
      when others then
        v_weather_state := 'normal';
        v_weather_modifier := 1.0;
    end;

    v_weather_state :=
      coalesce(
        v_weather_state,
        'normal'
      );

    v_weather_modifier :=
      coalesce(
        v_weather_modifier,
        1.0
      );

    v_availability_modifier :=
      case
        when r.availability_status = 'fit'
          then 1.00
        when r.availability_status = 'not_fully_fit'
          then 0.80
        else 0.00
      end;

    v_coach_training_multiplier := 1.0;
    v_coach_development_multiplier := 1.0;
    v_coach_youth_multiplier := 1.0;

    select
      training_efficiency_multiplier,
      development_multiplier,
      youth_dev_multiplier
    into
      v_coach_training_multiplier,
      v_coach_development_multiplier,
      v_coach_youth_multiplier
    from public.get_head_coach_effects(
      r.club_id
    );

    if r.birth_date is not null then
      v_rider_age :=
        extract(
          year from age(
            v_processed_date,
            r.birth_date
          )
        )::integer;
    else
      v_rider_age := 0;
    end if;

    v_final_development_value :=
      v_development_value_base
      * coalesce(
          v_weather_modifier,
          1.0
        )
      * coalesce(
          v_availability_modifier,
          1.0
        )
      * coalesce(
          v_coach_training_multiplier,
          1.0
        )
      * coalesce(
          v_coach_development_multiplier,
          1.0
        );

    if v_rider_age > 0
       and v_rider_age <= 23 then
      v_final_development_value :=
        v_final_development_value
        * coalesce(
            v_coach_youth_multiplier,
            1.0
          );
    end if;

    insert into public.rider_daily_activity (
      rider_id,
      activity_date,
      participated,
      source,
      activity_type,
      intensity,
      fatigue_load,
      recovery_bonus,
      metadata
    )
    values (
      r.rider_id,
      v_processed_date,
      case
        when v_focus_code = 'day_off'
          then false
        else true
      end,
      'regular_training',
      v_activity_type,
      v_resolved_intensity,
      v_fatigue_load,
      v_recovery_bonus,
      jsonb_build_object(
        'training_system',
          'regular_training',

        'focus_code',
          v_focus_code,

        'regular_training_display_label',
          case
            when v_focus_code = 'day_off'
              then 'Day Off'
            else v_focus_code
          end,

        'is_day_off',
          v_focus_code = 'day_off',

        'resolved_intensity',
          case
            when v_focus_code = 'day_off'
              then null
            else v_resolved_intensity
          end,

        'weather_state',
          v_weather_state,

        'weather_modifier',
          v_weather_modifier,

        'availability_modifier',
          v_availability_modifier,

        'development_value_base',
          v_final_development_value,

        'used_rider_plan',
          false,

        'used_club_default',
          false,

        'used_head_coach_daily_plan',
          r.source_type in (
            'head_coach',
            'u23_head_coach'
          ),

        'used_manual_daily_override',
          r.source_type = 'manual_override',

        'daily_plan_id',
          r.daily_plan_id,

        'daily_plan_source_type',
          r.source_type,

        'daily_plan_source_staff_id',
          r.source_staff_id,

        'decision_quality_score',
          r.decision_quality_score,

        'coach_availability_factor',
          r.coach_availability_factor,

        'fatigue_snapshot',
          r.fatigue_snapshot,

        'projected_fatigue_after',
          r.projected_fatigue_after,

        'decision_reason',
          coalesce(
            r.decision_reason_json,
            '{}'::jsonb
          ),

        'development_eligible',
          v_development_eligible,

        'coach_training_multiplier',
          coalesce(
            v_coach_training_multiplier,
            1.0
          ),

        'coach_development_multiplier',
          coalesce(
            v_coach_development_multiplier,
            1.0
          ),

        'coach_youth_multiplier',
          case
            when v_rider_age > 0
             and v_rider_age <= 23
              then coalesce(
                v_coach_youth_multiplier,
                1.0
              )
            else 1.0
          end,

        'staff_training_modifier_applied',
          case
            when v_focus_code = 'day_off'
              then false
            else true
          end,

        'team_scope',
          r.team_scope,

        'processor_version',
          'head_coach_daily_plan_consumer_v1'
      )
    )
    on conflict do nothing;

    get diagnostics
      v_row_count = row_count;

    if v_row_count = 1 then
      update public.rider_regular_training_daily_plans
      set
        status = 'consumed',
        consumed_at = now(),
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'consumed',
            'consumption_processor',
              'process_daily_coach_regular_training_v1',
            'consumed_activity_date',
              v_processed_date,
            'consumed_at',
              now(),
            'applied_focus_code',
              v_focus_code,
            'applied_intensity',
              v_resolved_intensity,
            'applied_fatigue_load',
              v_fatigue_load,
            'applied_recovery_bonus',
              v_recovery_bonus,
            'applied_development_value',
              v_final_development_value
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_inserted_rows :=
        v_inserted_rows + 1;

      v_consumed_rows :=
        v_consumed_rows + 1;

    else
      update public.rider_regular_training_daily_plans
      set
        status = 'skipped',
        decision_reason_json =
          coalesce(
            decision_reason_json,
            '{}'::jsonb
          )
          || jsonb_build_object(
            'consumption_status',
              'skipped',
            'consumption_reason',
              'activity_insert_conflict',
            'consumption_checked_at',
              now()
          ),
        updated_at = now()
      where id = r.daily_plan_id;

      v_skipped_rows :=
        v_skipped_rows + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',
      true,
    'version',
      'head_coach_daily_plan_consumer_v1',
    'processed_date',
      v_processed_date,
    'inserted_activity_rows',
      v_inserted_rows,
    'consumed_plan_rows',
      v_consumed_rows,
    'skipped_plan_rows',
      v_skipped_rows,
    'superseded_plan_rows',
      v_superseded_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_race_preparation_planner_context_v1(p_race_preparation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context jsonb;
begin
  select jsonb_build_object(
    'race_preparation_id', rp.id,
    'race_id', rp.race_id,
    'race_preparation_status', rp.status,
    'startlist_status', rp.startlist_status,

    'owner_club_id', rp.club_id,
    'owner_club_name', owner_club.name,
    'owner_user_id', owner_club.owner_user_id,

    'participating_club_id', rp.participating_club_id,
    'participating_club_name', participating_club.name,
    'participating_club_type', participating_club.club_type,
    'participating_parent_club_id', participating_club.parent_club_id,

    'is_developing_team',
      participating_club.club_type = 'developing',

    'developing_team_belongs_to_owner',
      participating_club.club_type = 'developing'
      and participating_club.parent_club_id = rp.club_id,

    'can_current_user_manage',
      owner_club.owner_user_id = auth.uid(),

    'automation_eligible',
      owner_club.owner_user_id = auth.uid()
      and participating_club.club_type = 'developing'
      and participating_club.parent_club_id = rp.club_id
      and rp.status in (
        'submitted',
        'locked',
        'sent_to_engine'
      ),

    'current_game_date',
      public.get_current_game_date_date()
  )
  into v_context
  from public.race_preparations rp
  join public.clubs owner_club
    on owner_club.id = rp.club_id
  join public.clubs participating_club
    on participating_club.id = rp.participating_club_id
  where rp.id = p_race_preparation_id
    and owner_club.deleted_at is null
    and participating_club.deleted_at is null;

  if v_context is null then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message', 'Race preparation or participating squad was not found.'
    );
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'version', 'race_preparation_planner_context_v1',
    'context', v_context
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_u23_stage_plan_automation_v1(p_race_preparation_id uuid, p_enabled boolean, p_planner_staff_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep record;
  v_staff record;
  v_existing_setting record;
  v_target_stage record;

  v_enabled boolean :=
    coalesce(p_enabled, false);

  v_effective_planner_staff_id uuid;

  v_current_game_date date;
  v_current_game_ts timestamp without time zone;

  v_initial_generation jsonb;

  v_generation_error_message text;
  v_generation_error_detail text;
  v_generation_error_hint text;

  v_removed_sport_director_count integer := 0;
begin
  if not public.can_manage_race_preparation_v1(
    p_race_preparation_id
  ) then
    raise exception
      'You do not have permission to manage this race preparation.';
  end if;

  if v_enabled and not public.current_user_has_premium_v1() then
    raise exception 'Premium membership is required for U23 Head Coach Stage Plan automation.';
  end if;

  v_current_game_date :=
    public.get_current_game_date_date();

  v_current_game_ts :=
    public.get_current_game_timestamp();

  select
    rp.id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,
    rp.status,
    rp.startlist_status,

    participating_club.name
      as participating_club_name,

    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  where rp.id = p_race_preparation_id
    and participating_club.deleted_at is null;

  if not found then
    raise exception
      'Race preparation was not found.';
  end if;

  if v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    raise exception
      'U23 Head Coach Stage Plan automation is available only when the Developing Team is the participating squad.';
  end if;

  select *
  into v_existing_setting
  from public.race_preparation_stage_plan_automation automation
  where automation.race_preparation_id =
    p_race_preparation_id;

  if v_enabled then
    if v_prep.status not in (
         'submitted',
         'locked',
         'sent_to_engine'
       )
       or v_prep.startlist_status not in (
         'submitted',
         'locked',
         'sent_to_engine'
       ) then
      raise exception
        'Submit the Race Plan before enabling U23 Head Coach Stage Plan automation.';
    end if;

    if p_planner_staff_id is null then
      raise exception
        'Select an active U23 Head Coach before enabling automation.';
    end if;

    v_effective_planner_staff_id :=
      p_planner_staff_id;

    select
      eligible.staff_id,
      eligible.staff_name,
      eligible.staff_club_id,
      eligible.team_scope,
      eligible.specialization,
      eligible.expertise,
      eligible.efficiency,
      eligible.potential,
      eligible.experience,
      eligible.leadership,
      eligible.loyalty,
      eligible.current_availability_factor,
      eligible.contract_expires_at
    into v_staff
    from public.get_eligible_u23_head_coaches_for_race_v1(
      p_race_preparation_id
    ) eligible
    where eligible.staff_id =
      v_effective_planner_staff_id
    limit 1;

    if not found then
      raise exception
        'The selected staff member is not an eligible active U23 Head Coach for this Developing Team.';
    end if;

    if coalesce(
         v_staff.current_availability_factor,
         0
       ) <= 0 then
      raise exception
        'The selected U23 Head Coach is currently unavailable because of another assignment or course.';
    end if;

  else
    v_effective_planner_staff_id :=
      coalesce(
        p_planner_staff_id,
        v_existing_setting.planner_staff_id
      );
  end if;

  if v_enabled then
    delete from public.race_preparation_staff race_staff
    where race_staff.race_preparation_id =
        p_race_preparation_id
      and race_staff.role_type =
        'sport_director';

    get diagnostics
      v_removed_sport_director_count =
        row_count;

    if v_removed_sport_director_count > 0 then
      update public.race_preparations preparation
      set
        staff_count =
          (
            select count(*)::integer
            from public.race_preparation_staff race_staff
            where race_staff.race_preparation_id =
              preparation.id
          ),

        metadata =
          coalesce(
            preparation.metadata,
            '{}'::jsonb
          )
          || jsonb_build_object(
               'planner_exclusivity_v1',
                 jsonb_build_object(
                   'selected_planner',
                     'u23_head_coach',

                   'removed_sport_director_assignment_count',
                     v_removed_sport_director_count,

                   'changed_at',
                     clock_timestamp(),

                   'changed_by_user_id',
                     auth.uid()
                 )
             ),

        updated_at =
          now()

      where preparation.id =
        p_race_preparation_id;
    end if;
  end if;

  insert into public.race_preparation_stage_plan_automation (
    race_preparation_id,
    owner_club_id,
    participating_club_id,

    planner_role,
    planner_staff_id,

    is_enabled,
    automation_mode,
    resume_after_manual_stage,

    last_generation_status,
    last_generation_summary,
    metadata,

    created_at,
    updated_at
  )
  values (
    p_race_preparation_id,
    v_prep.owner_club_id,
    v_prep.participating_club_id,

    'u23_head_coach',
    v_effective_planner_staff_id,

    v_enabled,
    'stage_by_stage',
    true,

    case
      when v_enabled
        then 'enabled_pending_initial_generation'
      else 'disabled'
    end,

    case
      when v_enabled
        then jsonb_build_object(
          'status',
            'pending',
          'reason',
            'automation_enabled',
          'configured_at',
            clock_timestamp()
        )
      else jsonb_build_object(
        'status',
          'disabled',
        'configured_at',
          clock_timestamp()
      )
    end,

    jsonb_build_object(
      'configured_by_user_id',
        auth.uid(),

      'configured_at',
        clock_timestamp(),

      'race_id',
        v_prep.race_id,

      'participating_club_name',
        v_prep.participating_club_name,

      'generator_installed',
        true,

      'save_integration_installed',
        true,

      'automatic_writer_installed',
        true,

      'initial_stage_invocation_installed',
        true,

      'planner_exclusivity_installed',
        true,

      'selected_planner',
        case
          when v_enabled
            then 'u23_head_coach'
          else 'none'
        end,

      'removed_sport_director_assignment_count',
        v_removed_sport_director_count,

      'race_plan_submit_hook_installed',
        false,

      'post_stage_hook_installed',
        true
    ),

    now(),
    now()
  )
  on conflict (race_preparation_id)
  do update
  set
    owner_club_id =
      excluded.owner_club_id,

    participating_club_id =
      excluded.participating_club_id,

    planner_role =
      'u23_head_coach',

    planner_staff_id =
      excluded.planner_staff_id,

    is_enabled =
      excluded.is_enabled,

    automation_mode =
      'stage_by_stage',

    resume_after_manual_stage =
      true,

    last_generation_status =
      excluded.last_generation_status,

    last_generation_summary =
      excluded.last_generation_summary,

    metadata =
      public.race_preparation_stage_plan_automation
        .metadata
      || excluded.metadata,

    updated_at =
      now();

  if not v_enabled then
    return jsonb_build_object(
      'ok', true,
      'status', 'ok',

      'version',
        'u23_stage_plan_automation_setter_v1_2',

      'race_preparation_id',
        p_race_preparation_id,

      'race_id',
        v_prep.race_id,

      'owner_club_id',
        v_prep.owner_club_id,

      'participating_club_id',
        v_prep.participating_club_id,

      'participating_club_name',
        v_prep.participating_club_name,

      'is_enabled',
        false,

      'planner_role',
        'u23_head_coach',

      'planner_staff_id',
        v_effective_planner_staff_id,

      'planner_choice',
        case
          when v_enabled
            then 'u23_head_coach'
          else 'none'
        end,

      'sport_director_assignment_removed',
        v_removed_sport_director_count > 0,

      'removed_sport_director_assignment_count',
        v_removed_sport_director_count,

      'automation_mode',
        'stage_by_stage',

      'resume_after_manual_stage',
        true,

      'initial_generation',
        jsonb_build_object(
          'status', 'skipped',
          'code', 'automation_disabled',
          'applied', false
        ),

      'generator_installed',
        true,

      'save_integration_installed',
        true,

      'automatic_writer_installed',
        true,

      'initial_stage_invocation_installed',
        true,

      'post_stage_hook_installed',
        true
    );
  end if;

  -- Earliest Stage Plan that the writer is allowed to own.
  select
    rsp.id as race_stage_plan_id,
    rsp.stage_id,
    rsp.stage_number,
    rsp.stage_date,

    (
      rs.stage_date::timestamp
      + make_interval(
          hours =>
            coalesce(
              rs.planned_start_hour_number,
              12
            ),

          mins =>
            coalesce(
              rs.planned_start_minute,
              0
            )
        )
    ) as stage_start_game_ts,

    (
      rs.stage_date::timestamp
      + make_interval(
          hours =>
            coalesce(
              rs.planned_start_hour_number,
              12
            ),

          mins =>
            coalesce(
              rs.planned_start_minute,
              0
            )
        )
      - interval '3 hours'
    ) as lock_game_ts

  into v_target_stage

  from public.race_stage_plans rsp

  join public.race_stages rs
    on rs.id = rsp.stage_id

  left join public.race_stage_plan_management management
    on management.race_stage_plan_id =
      rsp.id

  where rsp.race_preparation_id =
      p_race_preparation_id

    and rsp.race_id =
      v_prep.race_id

    and rsp.status =
      'draft'

    and rsp.locked_at is null

    and rsp.submitted_at is null

    and rsp.stage_id is not null

    and rsp.race_id is not distinct from
      rs.race_id

    and rsp.stage_number is not distinct from
      rs.stage_number

    and rsp.stage_date is not distinct from
      rs.stage_date

    and coalesce(
      rs.weather_cancelled,
      false
    ) = false

    and (
      rs.stage_date::timestamp
      + make_interval(
          hours =>
            coalesce(
              rs.planned_start_hour_number,
              12
            ),

          mins =>
            coalesce(
              rs.planned_start_minute,
              0
            )
        )
      - interval '3 hours'
    ) > v_current_game_ts

    and coalesce(
      management.management_mode,
      'coach'
    ) <> 'manual'

    and (
      rsp.last_saved_at is null

      or (
        management.management_mode =
          'coach'

        and management.source_type =
          'u23_head_coach'
      )
    )

  order by
    rsp.stage_number,
    rs.stage_date,
    rsp.created_at,
    rsp.id

  limit 1;

  if v_target_stage.race_stage_plan_id is null then
    v_initial_generation :=
      jsonb_build_object(
        'status', 'skipped',
        'code',
          'no_eligible_initial_stage',

        'message',
          'Automation was enabled, but no open Stage Plan is currently eligible for automatic generation.',

        'applied', false
      );

    update public.race_preparation_stage_plan_automation
    set
      last_generation_status =
        'enabled_no_eligible_initial_stage',

      last_generation_summary =
        v_initial_generation,

      metadata =
        coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
             'initial_stage_invocation_installed',
               true,

             'last_enable_attempt_at',
               clock_timestamp(),

             'initial_generation_applied',
               false
           ),

      updated_at =
        now()

    where race_preparation_id =
      p_race_preparation_id;

  else
    begin
      v_initial_generation :=
        public.apply_u23_stage_plan_automation_v1(
          p_race_preparation_id,
          v_target_stage.stage_id,
          'automation_enabled'
        );

    exception
      when others then
        get stacked diagnostics
          v_generation_error_message =
            message_text,

          v_generation_error_detail =
            pg_exception_detail,

          v_generation_error_hint =
            pg_exception_hint;

        v_initial_generation :=
          jsonb_build_object(
            'status', 'error',
            'code',
              'initial_stage_generation_exception',

            'message',
              v_generation_error_message,

            'detail',
              v_generation_error_detail,

            'hint',
              v_generation_error_hint,

            'applied', false,

            'stage_id',
              v_target_stage.stage_id,

            'stage_number',
              v_target_stage.stage_number,

            'stage_date',
              v_target_stage.stage_date
          );

        update public.race_preparation_stage_plan_automation
        set
          last_generation_status =
            'initial_stage_generation_exception',

          last_generation_summary =
            v_initial_generation,

          metadata =
            coalesce(metadata, '{}'::jsonb)
            || jsonb_build_object(
                 'initial_stage_invocation_installed',
                   true,

                 'last_enable_attempt_at',
                   clock_timestamp(),

                 'initial_generation_applied',
                   false
               ),

          updated_at =
            now()

        where race_preparation_id =
          p_race_preparation_id;
    end;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', 'ok',

    'version',
      'u23_stage_plan_automation_setter_v1_2',

    'race_preparation_id',
      p_race_preparation_id,

    'race_id',
      v_prep.race_id,

    'owner_club_id',
      v_prep.owner_club_id,

    'participating_club_id',
      v_prep.participating_club_id,

    'participating_club_name',
      v_prep.participating_club_name,

    'is_enabled',
      true,

    'planner_role',
      'u23_head_coach',

    'planner_staff_id',
      v_effective_planner_staff_id,

    'planner_choice',
      'u23_head_coach',

    'sport_director_assignment_removed',
      v_removed_sport_director_count > 0,

    'removed_sport_director_assignment_count',
      v_removed_sport_director_count,

    'planner_staff_name',
      v_staff.staff_name,

    'current_availability_factor',
      v_staff.current_availability_factor,

    'automation_mode',
      'stage_by_stage',

    'resume_after_manual_stage',
      true,

    'initial_target',
      case
        when v_target_stage.race_stage_plan_id
             is null
          then null
        else jsonb_build_object(
          'race_stage_plan_id',
            v_target_stage.race_stage_plan_id,

          'stage_id',
            v_target_stage.stage_id,

          'stage_number',
            v_target_stage.stage_number,

          'stage_date',
            v_target_stage.stage_date,

          'stage_start_game_ts',
            v_target_stage.stage_start_game_ts,

          'lock_game_ts',
            v_target_stage.lock_game_ts
        )
      end,

    'initial_generation',
      coalesce(
        v_initial_generation,
        jsonb_build_object(
          'status', 'error',
          'code',
            'initial_generation_result_missing',
          'applied', false
        )
      ),

    'generator_installed',
      true,

    'save_integration_installed',
      true,

    'automatic_writer_installed',
      true,

    'initial_stage_invocation_installed',
      true,

    'race_plan_submit_hook_installed',
      false,

    'post_stage_hook_installed',
      true
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_race_stage_plan_manual_v1(p_race_stage_plan_id uuid, p_reason text DEFAULT 'manager_saved_stage_plan'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_plan record;
begin
  select
    rsp.id,
    rsp.race_preparation_id,
    rsp.race_id,
    rsp.stage_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id
  into v_plan
  from public.race_stage_plans rsp
  join public.race_preparations rp
    on rp.id = rsp.race_preparation_id
  where rsp.id = p_race_stage_plan_id;

  if not found then
    raise exception
      'Race Stage Plan was not found.';
  end if;

  if not public.can_manage_race_preparation_v1(
    v_plan.race_preparation_id
  ) then
    raise exception
      'You do not have permission to manage this Stage Plan.';
  end if;

  insert into public.race_stage_plan_management (
    race_stage_plan_id,
    race_preparation_id,
    race_id,
    stage_id,
    owner_club_id,
    participating_club_id,
    management_mode,
    source_type,
    planner_role,
    planner_staff_id,
    source_snapshot_json,
    decision_summary_json,
    metadata,
    generated_at,
    manually_overridden_at,
    created_at,
    updated_at
  )
  values (
    v_plan.id,
    v_plan.race_preparation_id,
    v_plan.race_id,
    v_plan.stage_id,
    v_plan.owner_club_id,
    v_plan.participating_club_id,
    'manual',
    'manual',
    null,
    null,
    '{}'::jsonb,
    '{}'::jsonb,
    jsonb_build_object(
      'manual_reason',
        coalesce(
          nullif(trim(p_reason), ''),
          'manager_saved_stage_plan'
        ),
      'manual_user_id',
        auth.uid(),
      'manual_marked_at',
        now(),
      'coach_resumes_next_stage',
        true
    ),
    null,
    now(),
    now(),
    now()
  )
  on conflict (race_stage_plan_id)
  do update
  set
    management_mode = 'manual',
    source_type = 'manual',
    planner_role = null,
    planner_staff_id = null,
    metadata =
      public.race_stage_plan_management.metadata
      || excluded.metadata,
    manually_overridden_at = now(),
    updated_at = now();

  return jsonb_build_object(
    'ok', true,
    'race_stage_plan_id',
      v_plan.id,
    'race_preparation_id',
      v_plan.race_preparation_id,
    'stage_id',
      v_plan.stage_id,
    'management_mode',
      'manual',
    'coach_resumes_next_stage',
      true
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_u23_stage_plan_automation_dashboard_v1(p_race_preparation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  if not public.can_manage_race_preparation_v1(
    p_race_preparation_id
  ) then
    raise exception
      'You do not have permission to view this race preparation.';
  end if;

  select jsonb_build_object(
    'version',
      'u23_stage_plan_automation_foundation_v1',

    'race_preparation_id',
      rp.id,

    'race_id',
      rp.race_id,

    'race_preparation_status',
      rp.status,

    'startlist_status',
      rp.startlist_status,

    'owner_club_id',
      rp.club_id,

    'owner_club_name',
      owner_club.name,

    'participating_club_id',
      rp.participating_club_id,

    'participating_club_name',
      participating_club.name,

    'participating_club_type',
      participating_club.club_type,

    'is_developing_team',
      participating_club.club_type = 'developing',

    'automation_eligible',
      participating_club.club_type = 'developing'
      and participating_club.parent_club_id = rp.club_id
      and rp.status in (
        'submitted',
        'locked',
        'sent_to_engine'
      ),

    'setting',
      (
        select to_jsonb(a)
        from public.race_preparation_stage_plan_automation a
        where a.race_preparation_id = rp.id
      ),

    'eligible_u23_head_coaches',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(eligible)
            order by
              eligible.current_availability_factor desc,
              eligible.expertise desc,
              eligible.experience desc,
              eligible.staff_id
          )
          from public.get_eligible_u23_head_coaches_for_race_v1(
            rp.id
          ) eligible
        ),
        '[]'::jsonb
      ),

    'stages',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'race_stage_plan_id',
                rsp.id,
              'stage_id',
                rsp.stage_id,
              'stage_number',
                rsp.stage_number,
              'stage_date',
                rsp.stage_date,
              'stage_plan_status',
                rsp.status,
              'last_saved_at',
                rsp.last_saved_at,
              'weather_cancelled',
                coalesce(rs.weather_cancelled, false),
              'weather_cancellation_reason',
                rs.weather_cancellation_reason,
              'management',
                case
                  when management.race_stage_plan_id is null
                    then null
                  else to_jsonb(management)
                end
            )
            order by
              rsp.stage_number,
              rsp.created_at
          )
          from public.race_stage_plans rsp
          left join public.race_stages rs
            on rs.id = rsp.stage_id
          left join public.race_stage_plan_management management
            on management.race_stage_plan_id = rsp.id
          where rsp.race_preparation_id = rp.id
        ),
        '[]'::jsonb
      ),

    'generation_history',
      coalesce(
        (
          select jsonb_agg(
            to_jsonb(log_row)
            order by log_row.created_at desc
          )
          from (
            select *
            from public.race_stage_plan_generation_log history
            where history.race_preparation_id = rp.id
            order by history.created_at desc
            limit 20
          ) log_row
        ),
        '[]'::jsonb
      ),

    'generator_installed',
      false,

    'save_integration_installed',
      false,

    'post_stage_hook_installed',
      false
  )
  into v_result
  from public.race_preparations rp
  join public.clubs owner_club
    on owner_club.id = rp.club_id
  join public.clubs participating_club
    on participating_club.id = rp.participating_club_id
  where rp.id = p_race_preparation_id;

  if v_result is null then
    raise exception
      'Race preparation was not found.';
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_u23_race_planner_quality_v1(p_race_preparation_id uuid, p_stage_id uuid, p_planner_staff_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prep record;
  v_staff record;

  v_planner_staff_id uuid;
  v_stage_date date;

  v_active_assignment_load_pct numeric := 0;
  v_availability_factor numeric := 0;

  v_race_readiness_score numeric := 0;
  v_youth_coach_ability_score numeric := 0;
  v_effective_quality_score numeric := 0;

  v_quality_tier text;
begin
  select
    rp.id as race_preparation_id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,
    rp.status as race_preparation_status,

    participating_club.name as participating_club_name,
    participating_club.club_type,
    participating_club.parent_club_id,

    rs.stage_date,
    rs.stage_number,
    rs.weather_cancelled,

    coalesce(
      p_planner_staff_id,
      automation.planner_staff_id
    ) as resolved_planner_staff_id
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  join public.race_stages rs
    on rs.id = p_stage_id
   and rs.race_id = rp.race_id
  left join public.race_preparation_stage_plan_automation automation
    on automation.race_preparation_id = rp.id
  where rp.id = p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'planner_context_not_found',
      'message',
        'Race preparation or stage was not found.'
    );
  end if;

  if v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'not_developing_team_preparation',
      'message',
        'U23 Head Coach planning is available only when the Developing Team is the participating squad.'
    );
  end if;

  if coalesce(
       v_prep.weather_cancelled,
       false
     ) then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_weather_cancelled',
      'message',
        'This stage was cancelled due to weather and does not need a Stage Plan.'
    );
  end if;

  v_planner_staff_id :=
    v_prep.resolved_planner_staff_id;

  v_stage_date :=
    v_prep.stage_date;

  if v_planner_staff_id is null then
    return jsonb_build_object(
      'status', 'error',
      'code', 'u23_head_coach_not_selected',
      'message',
        'No U23 Head Coach is selected for this race preparation.'
    );
  end if;

  select
    cs.id,
    cs.staff_name,
    cs.club_id,
    cs.team_scope,
    cs.specialization,
    cs.expertise,
    cs.efficiency,
    cs.potential,
    cs.experience,
    cs.leadership,
    cs.loyalty,
    cs.contract_expires_at,
    cs.is_active
  into v_staff
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  join public.club_staff cs
    on cs.id = v_planner_staff_id
   and cs.club_id in (
     rp.club_id,
     rp.participating_club_id
   )
  where rp.id = p_race_preparation_id
    and participating_club.club_type =
      'developing'
    and participating_club.parent_club_id =
      rp.club_id
    and cs.role_type = 'u23_head_coach'
    and cs.team_scope in ('u23', 'all')
    and cs.is_active = true
    and (
      cs.contract_expires_at is null
      or cs.contract_expires_at >=
        v_stage_date
    );

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'u23_head_coach_not_eligible',
      'message',
        'The selected staff member is not an eligible active U23 Head Coach for this Developing Team and stage date.'
    );
  end if;

  -- Direct, stage-date assignment calculation.
  select coalesce(
    sum(
      greatest(
        0,
        least(
          100,
          assignment.load_pct
        )
      )
    ),
    0
  )
  into v_active_assignment_load_pct
  from public.staff_assignment_load assignment
  where assignment.staff_id = v_staff.id
    and assignment.status = 'active'
    and v_stage_date between
      assignment.starts_on
      and assignment.ends_on;

  v_active_assignment_load_pct :=
    greatest(
      0,
      least(
        100,
        coalesce(
          v_active_assignment_load_pct,
          0
        )
      )
    );

  v_availability_factor :=
    greatest(
      0,
      least(
        1,
        1
        - (
            v_active_assignment_load_pct
            / 100.0
          )
      )
    );

  -- Existing Staff-page Race Readiness formula.
  v_race_readiness_score :=
      coalesce(v_staff.expertise, 0) * 0.40
    + coalesce(v_staff.leadership, 0) * 0.30
    + coalesce(v_staff.experience, 0) * 0.20
    + coalesce(v_staff.loyalty, 0) * 0.10;

  -- Existing Youth Coach Ability formula.
  v_youth_coach_ability_score :=
      coalesce(v_staff.expertise, 0) * 0.35
    + coalesce(v_staff.potential, 0) * 0.35
    + coalesce(v_staff.leadership, 0) * 0.20
    + coalesce(v_staff.experience, 0) * 0.10;

  v_effective_quality_score :=
    greatest(
      0,
      least(
        100,
        v_race_readiness_score
        * v_availability_factor
      )
    );

  v_quality_tier :=
    case
      when v_effective_quality_score >= 85
        then 'elite'
      when v_effective_quality_score >= 70
        then 'strong'
      when v_effective_quality_score >= 55
        then 'solid'
      else 'basic'
    end;

  return jsonb_build_object(
    'status', 'ok',
    'version',
      'u23_race_planner_quality_v1_1',

    'planner_staff_id',
      v_staff.id,

    'planner_staff_name',
      v_staff.staff_name,

    'staff_club_id',
      v_staff.club_id,

    'team_scope',
      v_staff.team_scope,

    'specialization',
      v_staff.specialization,

    'stage_id',
      p_stage_id,

    'stage_date',
      v_stage_date,

    'attributes',
      jsonb_build_object(
        'youth_training',
          v_staff.expertise,
        'youth_development',
          v_staff.potential,
        'u23_race_tactics',
          v_staff.leadership,
        'experience',
          v_staff.experience,
        'planning',
          v_staff.efficiency,
        'loyalty',
          v_staff.loyalty
      ),

    'active_assignment_load_pct',
      round(
        v_active_assignment_load_pct,
        2
      ),

    'race_readiness_score',
      round(
        v_race_readiness_score,
        2
      ),

    'youth_coach_ability_score',
      round(
        v_youth_coach_ability_score,
        2
      ),

    'availability_factor',
      round(
        v_availability_factor,
        4
      ),

    'effective_quality_score',
      round(
        v_effective_quality_score,
        2
      ),

    'quality_tier',
      v_quality_tier,

    'planning_precision',
      case v_quality_tier
        when 'elite'
          then 'highly_specific'
        when 'strong'
          then 'specific'
        when 'solid'
          then 'moderately_specific'
        else 'generic'
      end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_u23_stage_plan_adaptation_context_v1(p_race_preparation_id uuid, p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prep record;
  v_stage record;
  v_previous_stage_id uuid;
  v_previous_stage_number integer;
  v_selected_riders jsonb;
  v_previous_results jsonb;
  v_classifications jsonb;
  v_remaining_supplies jsonb;
  v_existing_plan jsonb;
  v_summary jsonb;
begin
  select
    rp.id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,
    rp.status,
    rp.startlist_status,
    participating_club.name as participating_club_name,
    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id = rp.participating_club_id
  where rp.id = p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message', 'Race preparation was not found.'
    );
  end if;

  select
    rs.id,
    rs.race_id,
    rs.stage_number,
    rs.stage_date,
    to_jsonb(rs) as stage_json
  into v_stage
  from public.race_stages rs
  where rs.id = p_stage_id
    and rs.race_id = v_prep.race_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_not_found',
      'message', 'Stage was not found in this race.'
    );
  end if;

  select
    prior.id,
    prior.stage_number
  into
    v_previous_stage_id,
    v_previous_stage_number
  from public.race_stages prior
  where prior.race_id = v_prep.race_id
    and prior.stage_number < v_stage.stage_number
  order by prior.stage_number desc
  limit 1;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rider_id', rpr.rider_id,
        'race_role', rpr.race_role,
        'start_number', rpr.start_number,
        'default_equipment_setup_id',
          rpr.default_equipment_setup_id,

        'rider_snapshot',
          rpr.rider_snapshot_json,

        'availability_snapshot',
          rpr.availability_snapshot_json,

        'current_rider',
          to_jsonb(rider),

        'age_on_stage_date',
          case
            when rider.birth_date is null
              then null
            else extract(
              year from age(
                v_stage.stage_date,
                rider.birth_date
              )
            )::integer
          end,

        'open_health_case',
          case
            when health_case.id is null
              then null
            else to_jsonb(health_case)
          end
      )
      order by
        coalesce(rpr.start_number, 9999),
        rpr.rider_id
    ),
    '[]'::jsonb
  )
  into v_selected_riders
  from public.race_preparation_riders rpr
  join public.riders rider
    on rider.id = rpr.rider_id
  left join lateral (
    select hc.*
    from public.rider_health_cases hc
    where hc.rider_id = rpr.rider_id
      and hc.status in ('active', 'recovering')
    order by hc.started_on desc
    limit 1
  ) health_case on true
  where rpr.race_preparation_id =
    p_race_preparation_id;

  if v_previous_stage_id is null then
    v_previous_results := '[]'::jsonb;
    v_classifications := '[]'::jsonb;
  else
    select coalesce(
      jsonb_agg(
        to_jsonb(result_row)
        order by
          coalesce(
            nullif(
              to_jsonb(result_row)->>'rank',
              ''
            )::integer,
            999999
          ),
          result_row.rider_id
      ),
      '[]'::jsonb
    )
    into v_previous_results
    from public.race_stage_results result_row
    join public.race_preparation_riders rpr
      on rpr.rider_id = result_row.rider_id
     and rpr.race_preparation_id =
       p_race_preparation_id
    where result_row.stage_id =
      v_previous_stage_id;

    select coalesce(
      jsonb_agg(
        to_jsonb(standing)
        order by
          standing.classification_type,
          standing.rank,
          standing.rider_id
      ),
      '[]'::jsonb
    )
    into v_classifications
    from public.race_classification_standings standing
    join public.race_preparation_riders rpr
      on rpr.rider_id = standing.rider_id
     and rpr.race_preparation_id =
       p_race_preparation_id
    where standing.race_id = v_prep.race_id
      and standing.after_stage_id =
        v_previous_stage_id
      and standing.entity_type = 'rider';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'supply_key', supply.supply_key,
        'quantity_reserved',
          supply.quantity_reserved,
        'quantity_consumed',
          supply.quantity_consumed,
        'quantity_remaining',
          greatest(
            0,
            supply.quantity_reserved
            - supply.quantity_consumed
          ),
        'snapshot',
          supply.supply_snapshot_json,
        'bonus_snapshot',
          supply.bonus_snapshot_json
      )
      order by supply.supply_key
    ),
    '[]'::jsonb
  )
  into v_remaining_supplies
  from public.race_preparation_supplies supply
  where supply.race_preparation_id =
    p_race_preparation_id;

  select to_jsonb(plan_row)
  into v_existing_plan
  from public.race_stage_plans plan_row
  where plan_row.race_preparation_id =
      p_race_preparation_id
    and plan_row.stage_id = p_stage_id
  order by plan_row.created_at desc
  limit 1;

  select jsonb_build_object(
    'rider_count',
      count(*),

    'high_fatigue_count',
      count(*) filter (
        where coalesce(rider.fatigue, 0) >= 60
      ),

    'very_high_fatigue_count',
      count(*) filter (
        where coalesce(rider.fatigue, 0) >= 75
      ),

    'not_fully_fit_count',
      count(*) filter (
        where rider.availability_status =
          'not_fully_fit'
      ),

    'injured_or_sick_count',
      count(*) filter (
        where rider.availability_status in (
          'injured',
          'sick'
        )
      ),

    'open_health_case_count',
      count(*) filter (
        where exists (
          select 1
          from public.rider_health_cases hc
          where hc.rider_id = rider.id
            and hc.status in (
              'active',
              'recovering'
            )
        )
      ),

    'young_rider_count',
      count(*) filter (
        where rider.birth_date is not null
          and extract(
            year from age(
              v_stage.stage_date,
              rider.birth_date
            )
          ) <= 23
      )
  )
  into v_summary
  from public.race_preparation_riders rpr
  join public.riders rider
    on rider.id = rpr.rider_id
  where rpr.race_preparation_id =
    p_race_preparation_id;

  return jsonb_build_object(
    'status', 'ok',
    'version',
      'u23_stage_plan_adaptation_context_v1_1',

    'race_preparation', jsonb_build_object(
      'race_preparation_id', v_prep.id,
      'race_id', v_prep.race_id,
      'owner_club_id', v_prep.owner_club_id,
      'participating_club_id',
        v_prep.participating_club_id,
      'participating_club_name',
        v_prep.participating_club_name,
      'participating_club_type',
        v_prep.club_type,
      'status', v_prep.status,
      'startlist_status',
        v_prep.startlist_status
    ),

    'stage',
      v_stage.stage_json,

    'weather',
      jsonb_build_object(
        'weather_snapshot',
          coalesce(
            v_stage.stage_json->'weather_snapshot',
            '{}'::jsonb
          ),
        'weather_summary',
          v_stage.stage_json->>'weather_summary',
        'weather_cancelled',
          coalesce(
            (
              v_stage.stage_json
                ->>'weather_cancelled'
            )::boolean,
            false
          ),
        'weather_cancellation_reason',
          v_stage.stage_json
            ->>'weather_cancellation_reason'
      ),

    'previous_stage', jsonb_build_object(
      'stage_id', v_previous_stage_id,
      'stage_number', v_previous_stage_number
    ),

    'selected_rider_summary',
      v_summary,

    'selected_riders',
      v_selected_riders,

    'previous_stage_results',
      v_previous_results,

    'classifications_after_previous_stage',
      v_classifications,

    'remaining_race_supplies',
      v_remaining_supplies,

    'existing_stage_plan',
      v_existing_plan
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_stage_plan_u23_head_coach_suggestion_v1(p_race_preparation_id uuid, p_stage_id uuid, p_planner_staff_id uuid DEFAULT NULL::uuid, p_generation_reason text DEFAULT 'manual_refresh'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prep record;
  v_stage_plan record;
  v_setting record;

  v_quality jsonb;
  v_context jsonb;
  v_base jsonb;

  v_quality_status text;
  v_context_status text;
  v_base_status text;

  v_quality_tier text;
  v_effective_quality numeric;
  v_availability_factor numeric;

  v_suggestion jsonb;
  v_equipment_json jsonb;
  v_equipment_fallback_count integer := 0;
  v_team_tactic jsonb;
  v_original_team_plan text;
  v_final_team_plan text;

  v_summary jsonb;
  v_rider_count integer;
  v_high_fatigue_count integer;
  v_open_health_case_count integer;
  v_not_fully_fit_count integer;
  v_pressure_count integer;

  v_generation_log_id uuid;
  v_explanation jsonb;
begin
  if not public.can_manage_race_preparation_v1(
    p_race_preparation_id
  ) then
    raise exception
      'You do not have permission to manage this race preparation.';
  end if;

  if p_generation_reason not in (
    'automation_enabled',
    'race_plan_submitted',
    'stage_result_finalized',
    'manual_refresh',
    'manual_override_cleared'
  ) then
    raise exception
      'Invalid U23 Stage Plan generation reason.';
  end if;

  select
    rp.id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,
    rp.status,
    rp.startlist_status,
    participating_club.club_type,
    participating_club.parent_club_id,
    participating_club.name as participating_club_name
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  where rp.id = p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message', 'Race preparation was not found.'
    );
  end if;

  if v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'not_developing_team_preparation',
      'message',
        'U23 Head Coach planning is available only when the Developing Team is participating.'
    );
  end if;

  if exists (
    select 1
    from public.race_preparation_staff race_staff
    where race_staff.race_preparation_id =
        p_race_preparation_id
      and race_staff.role_type =
        'sport_director'
  ) then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'planner_choice_conflict',
      'message',
        'Choose either the Sport Director or the U23 Head Coach for this Developing Team race, not both.'
    );
  end if;

  if v_prep.status not in (
       'submitted',
       'locked',
       'sent_to_engine'
     ) then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_plan_not_submitted',
      'message',
        'Submit the Race Plan before asking the U23 Head Coach for a Stage Plan.'
    );
  end if;

  select
    rsp.id,
    rsp.race_id,
    rsp.stage_id,
    rsp.stage_number,
    rsp.stage_date,
    rsp.status,
    rsp.locked_at,
    rsp.last_saved_at,
    rsp.metadata
  into v_stage_plan
  from public.race_stage_plans rsp
  where rsp.race_preparation_id =
      p_race_preparation_id
    and rsp.stage_id = p_stage_id
  order by rsp.created_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_plan_not_found',
      'message',
        'The Stage Plan row was not found for this race preparation and stage.'
    );
  end if;

  if v_stage_plan.locked_at is not null
     or v_stage_plan.status in (
       'locked',
       'submitted',
       'sent_to_engine'
     ) then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_plan_locked',
      'message',
        'This Stage Plan is locked and cannot be regenerated.'
    );
  end if;

  if exists (
    select 1
    from public.race_stages rs
    where rs.id = p_stage_id
      and coalesce(
        rs.weather_cancelled,
        false
      ) = true
  ) then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_weather_cancelled',
      'message',
        'This stage was cancelled due to weather and does not need a Stage Plan.'
    );
  end if;

  select *
  into v_setting
  from public.race_preparation_stage_plan_automation a
  where a.race_preparation_id =
    p_race_preparation_id;

  v_quality :=
    public.get_u23_race_planner_quality_v1(
      p_race_preparation_id,
      p_stage_id,
      coalesce(
        p_planner_staff_id,
        v_setting.planner_staff_id
      )
    );

  v_quality_status :=
    coalesce(
      v_quality->>'status',
      'error'
    );

  if v_quality_status <> 'ok' then
    insert into public.race_stage_plan_generation_log (
      race_stage_plan_id,
      race_preparation_id,
      race_id,
      stage_id,
      owner_club_id,
      participating_club_id,
      planner_role,
      planner_staff_id,
      generation_reason,
      generation_status,
      generation_version,
      input_snapshot_json,
      result_json,
      error_json,
      metadata
    )
    values (
      v_stage_plan.id,
      p_race_preparation_id,
      v_prep.race_id,
      p_stage_id,
      v_prep.owner_club_id,
      v_prep.participating_club_id,
      'u23_head_coach',
      coalesce(
        p_planner_staff_id,
        v_setting.planner_staff_id
      ),
      p_generation_reason,
      'failed',
      'u23_head_coach_suggestion_v3',
      jsonb_build_object(
        'quality', v_quality
      ),
      '{}'::jsonb,
      v_quality,
      jsonb_build_object(
        'suggestion_only', true
      )
    )
    returning id
    into v_generation_log_id;

    return v_quality
      || jsonb_build_object(
        'generation_log_id',
          v_generation_log_id
      );
  end if;

  v_effective_quality :=
    coalesce(
      nullif(
        v_quality->>'effective_quality_score',
        ''
      )::numeric,
      0
    );

  v_availability_factor :=
    coalesce(
      nullif(
        v_quality->>'availability_factor',
        ''
      )::numeric,
      0
    );

  v_quality_tier :=
    coalesce(
      v_quality->>'quality_tier',
      'basic'
    );

  if v_availability_factor <= 0 then
    insert into public.race_stage_plan_generation_log (
      race_stage_plan_id,
      race_preparation_id,
      race_id,
      stage_id,
      owner_club_id,
      participating_club_id,
      planner_role,
      planner_staff_id,
      generation_reason,
      generation_status,
      generation_version,
      decision_quality_score,
      input_snapshot_json,
      result_json,
      error_json,
      metadata
    )
    values (
      v_stage_plan.id,
      p_race_preparation_id,
      v_prep.race_id,
      p_stage_id,
      v_prep.owner_club_id,
      v_prep.participating_club_id,
      'u23_head_coach',
      (v_quality->>'planner_staff_id')::uuid,
      p_generation_reason,
      'failed',
      'u23_head_coach_suggestion_v3',
      v_effective_quality,
      jsonb_build_object(
        'quality', v_quality
      ),
      '{}'::jsonb,
      jsonb_build_object(
        'status', 'error',
        'code',
          'u23_head_coach_unavailable',
        'message',
          'The U23 Head Coach is unavailable on the stage date.'
      ),
      jsonb_build_object(
        'suggestion_only', true
      )
    )
    returning id
    into v_generation_log_id;

    return jsonb_build_object(
      'status', 'error',
      'code', 'u23_head_coach_unavailable',
      'message',
        'The U23 Head Coach is unavailable on the stage date.',
      'u23_head_coach', v_quality,
      'generation_log_id',
        v_generation_log_id
    );
  end if;

  v_context :=
    public.get_u23_stage_plan_adaptation_context_v1(
      p_race_preparation_id,
      p_stage_id
    );

  v_context_status :=
    coalesce(
      v_context->>'status',
      'error'
    );

  if v_context_status <> 'ok' then
    return v_context;
  end if;

  v_base :=
    public.generate_stage_plan_canonical_planner_suggestion_v1(
      p_race_preparation_id,
      p_stage_id,
      jsonb_build_object(
        'role_type',
          'u23_head_coach',

        'staff_id',
          v_quality->>'planner_staff_id',

        'staff_name',
          v_quality->>'planner_staff_name',

        'quality_tier',
          v_quality_tier,

        'effective_quality_score',
          v_effective_quality,

        'race_readiness_score',
          v_quality->>'race_readiness_score',

        'youth_coach_ability_score',
          v_quality->>'youth_coach_ability_score',

        'availability_factor',
          v_availability_factor,

        'planning_precision',
          v_quality->>'planning_precision',

        'participating_club_id',
          v_prep.participating_club_id
      )
    );

  v_base_status :=
    coalesce(
      v_base->>'status',
      'error'
    );

  if v_base_status <> 'ok' then
    insert into public.race_stage_plan_generation_log (
      race_stage_plan_id,
      race_preparation_id,
      race_id,
      stage_id,
      owner_club_id,
      participating_club_id,
      planner_role,
      planner_staff_id,
      generation_reason,
      generation_status,
      generation_version,
      decision_quality_score,
      input_snapshot_json,
      result_json,
      error_json,
      metadata
    )
    values (
      v_stage_plan.id,
      p_race_preparation_id,
      v_prep.race_id,
      p_stage_id,
      v_prep.owner_club_id,
      v_prep.participating_club_id,
      'u23_head_coach',
      (v_quality->>'planner_staff_id')::uuid,
      p_generation_reason,
      'failed',
      'u23_head_coach_suggestion_v3',
      v_effective_quality,
      jsonb_build_object(
        'quality', v_quality,
        'adaptation_context', v_context
      ),
      '{}'::jsonb,
      v_base,
      jsonb_build_object(
        'suggestion_only', true,
        'base_generator',
          'generate_stage_plan_canonical_planner_suggestion_v1'
      )
    )
    returning id
    into v_generation_log_id;

    return jsonb_build_object(
      'status', 'error',
      'code',
        coalesce(
          v_base->>'code',
          'base_planner_failed'
        ),
      'message',
        coalesce(
          v_base->>'message',
          'The shared race planner could not create a suggestion.'
        ),
      'base_planner_result', v_base,
      'u23_head_coach', v_quality,
      'generation_log_id',
        v_generation_log_id
    );
  end if;

  v_suggestion :=
    coalesce(
      v_base->'suggestion',
      '{}'::jsonb
    );

  /*
   * Stage Plan readiness requires one explicit equipment value per selected
   * rider. The shared planner preserves a rider-level default setup when one
   * exists. When the Race Plan uses the club's virtual Default Race Setup,
   * there is intentionally no UUID in race_preparation_riders, so we write the
   * same canonical marker already used by the Stage Plans frontend.
   */
  v_equipment_json :=
    coalesce(
      v_suggestion->'rider_equipment_json',
      '{}'::jsonb
    );

  select
    coalesce(
      jsonb_object_agg(
        rpr.rider_id::text,
        coalesce(
          nullif(
            v_equipment_json
              ->> rpr.rider_id::text,
            ''
          ),
          rpr.default_equipment_setup_id::text,
          '__default_race_setup__'
        )
      ),
      '{}'::jsonb
    ),

    count(*) filter (
      where nullif(
        v_equipment_json
          ->> rpr.rider_id::text,
        ''
      ) is null
    )::integer

  into
    v_equipment_json,
    v_equipment_fallback_count

  from public.race_preparation_riders rpr
  where rpr.race_preparation_id =
    p_race_preparation_id;

  v_team_tactic :=
    coalesce(
      v_suggestion->'team_tactic_json',
      '{}'::jsonb
    );

  v_original_team_plan :=
    coalesce(
      nullif(
        v_team_tactic->>'plan',
        ''
      ),
      'balanced'
    );

  v_summary :=
    coalesce(
      v_context->'selected_rider_summary',
      '{}'::jsonb
    );

  v_rider_count :=
    coalesce(
      nullif(
        v_summary->>'rider_count',
        ''
      )::integer,
      0
    );

  v_high_fatigue_count :=
    coalesce(
      nullif(
        v_summary->>'high_fatigue_count',
        ''
      )::integer,
      0
    );

  v_open_health_case_count :=
    coalesce(
      nullif(
        v_summary->>'open_health_case_count',
        ''
      )::integer,
      0
    );

  v_not_fully_fit_count :=
    coalesce(
      nullif(
        v_summary->>'not_fully_fit_count',
        ''
      )::integer,
      0
    );

  v_pressure_count :=
      v_high_fatigue_count
    + v_open_health_case_count
    + v_not_fully_fit_count;

  v_final_team_plan :=
    v_original_team_plan;

  -- Poor coach: generic, safe plan instead of precise stage-specific control.
  if v_quality_tier = 'basic' then
    v_final_team_plan := 'balanced';

  -- Solid or better coach: recognizes excessive squad pressure and avoids
  -- maintaining an aggressive plan when at least one third of the squad has
  -- fatigue/health/fitness pressure.
  elsif v_original_team_plan = 'aggressive'
        and v_rider_count > 0
        and v_pressure_count * 3 >=
          v_rider_count then
    v_final_team_plan := 'balanced';
  end if;

  v_team_tactic :=
    v_team_tactic
    || jsonb_build_object(
      'plan',
        v_final_team_plan,

      'notes',
        'Prepared and saved automatically by the U23 Head Coach. This Stage Plan is view-only while U23 automation is active.',

      'engine_model_version',
        'u23_head_coach_suggestion_v3',

      'suggestion_source',
        'generate_stage_plan_u23_head_coach_suggestion_v3',

      'base_suggestion_source',
        'generate_stage_plan_canonical_planner_suggestion_v1',

      'planner_role',
        'u23_head_coach',

      'planner_staff_id',
        v_quality->>'planner_staff_id',

      'planner_staff_name',
        v_quality->>'planner_staff_name',

      'participating_club_id',
        v_prep.participating_club_id,

      'decision_quality_score',
        v_effective_quality,

      'quality_tier',
        v_quality_tier,

      'availability_factor',
        v_availability_factor,

      'original_shared_planner_team_plan',
        v_original_team_plan,

      'u23_plan_was_generalized',
        v_final_team_plan <>
          v_original_team_plan,

      'adaptation_summary',
        v_summary,

      'generation_reason',
        p_generation_reason,

      'suggestion_only',
        true
    );

  v_suggestion :=
    v_suggestion
    || jsonb_build_object(
      'team_tactic_json',
        v_team_tactic,

      'rider_equipment_json',
        v_equipment_json,

      'equipment_assignment_source',
        case
          when v_equipment_fallback_count > 0
            then 'rider_default_or_virtual_default'
          else 'canonical_shared_planner'
        end,

      'equipment_fallback_count',
        v_equipment_fallback_count,

      'planner_role',
        'u23_head_coach',

      'planner_staff_id',
        v_quality->>'planner_staff_id',

      'participating_club_id',
        v_prep.participating_club_id,

      'decision_quality_score',
        v_effective_quality,

      'generation_version',
        'u23_head_coach_suggestion_v3'
    );

  v_explanation :=
    jsonb_build_array(
      'The Developing Team was resolved through race_preparations.participating_club_id.',
      'The canonical shared planner supplied valid role, tactic, equipment and supply codes without requiring a Sport Director assignment.',
      case
        when v_equipment_fallback_count > 0
          then v_equipment_fallback_count::text
            || ' rider equipment assignment(s) used the rider default or the club Default Race Setup marker.'
        else
          'All rider equipment assignments came from the canonical shared planner.'
      end,
      'U23 Head Coach race readiness is '
        || round(v_effective_quality, 1)::text
        || ' (' || v_quality_tier || ').',
      'Stage-date staff availability factor is '
        || round(
             v_availability_factor * 100,
             0
           )::text || '%.',
      'Current U23 squad pressure: '
        || v_high_fatigue_count::text
        || ' high-fatigue, '
        || v_not_fully_fit_count::text
        || ' not-fully-fit and '
        || v_open_health_case_count::text
        || ' open health-case rider records.',
      case
        when v_final_team_plan <>
             v_original_team_plan
          then
            'The canonical planner team tactic was generalized from '
            || v_original_team_plan
            || ' to balanced because of coach quality or squad pressure.'
        else
          'The canonical planner team tactic was preserved.'
      end,
      'This is a suggestion only. No Stage Plan row was changed.'
    );

  insert into public.race_stage_plan_generation_log (
    race_stage_plan_id,
    race_preparation_id,
    race_id,
    stage_id,
    owner_club_id,
    participating_club_id,
    planner_role,
    planner_staff_id,
    generation_reason,
    generation_status,
    based_on_stage_id,
    generation_version,
    decision_quality_score,
    input_snapshot_json,
    suggestion_json,
    result_json,
    error_json,
    metadata
  )
  values (
    v_stage_plan.id,
    p_race_preparation_id,
    v_prep.race_id,
    p_stage_id,
    v_prep.owner_club_id,
    v_prep.participating_club_id,
    'u23_head_coach',
    (v_quality->>'planner_staff_id')::uuid,
    p_generation_reason,
    'generated',
    nullif(
      v_context
        ->'previous_stage'
        ->>'stage_id',
      ''
    )::uuid,
    'u23_head_coach_suggestion_v3',
    v_effective_quality,
    jsonb_build_object(
      'quality', v_quality,
      'adaptation_context', v_context,
      'base_planner_result', v_base
    ),
    v_suggestion,
    jsonb_build_object(
      'status', 'ok',
      'original_team_plan',
        v_original_team_plan,
      'final_team_plan',
        v_final_team_plan,
      'generalized',
        v_final_team_plan <>
          v_original_team_plan
    ),
    '{}'::jsonb,
    jsonb_build_object(
      'suggestion_only', true,
      'existing_stage_plan_unchanged', true,
      'shared_planner',
        'generate_stage_plan_canonical_planner_suggestion_v1'
    )
  )
  returning id
  into v_generation_log_id;

  return jsonb_build_object(
    'status', 'ok',
    'version',
      'u23_head_coach_suggestion_v3',

    'safe_note',
      'Suggestion only. No Stage Plan row was changed.',

    'race_preparation_id',
      p_race_preparation_id,

    'race_id',
      v_prep.race_id,

    'stage_id',
      p_stage_id,

    'stage_number',
      v_stage_plan.stage_number,

    'owner_club_id',
      v_prep.owner_club_id,

    'participating_club_id',
      v_prep.participating_club_id,

    'participating_club_name',
      v_prep.participating_club_name,

    'u23_head_coach',
      v_quality,

    'adaptation_context',
      v_context,

    'shared_planner',
      jsonb_build_object(
        'version', v_base->>'version',
        'planner',
          v_base->'planner',
        'profile',
          v_base->'profile',
        'stage_kind',
          v_base->>'stage_kind'
      ),

    'suggestion',
      v_suggestion,

    'explanation',
      v_explanation,

    'generation_log_id',
      v_generation_log_id,

    'saved',
      false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_u23_stage_plan_suggestion_v1(p_race_preparation_id uuid, p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_setting record;
begin
  if not public.can_manage_race_preparation_v1(
    p_race_preparation_id
  ) then
    raise exception
      'You do not have permission to manage this race preparation.';
  end if;

  select *
  into v_setting
  from public.race_preparation_stage_plan_automation a
  where a.race_preparation_id =
      p_race_preparation_id
    and a.is_enabled = true
    and a.planner_role =
      'u23_head_coach';

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'u23_stage_plan_automation_not_enabled',
      'message',
        'U23 Head Coach Stage Plan automation is not enabled for this race preparation.'
    );
  end if;

  return
    public.generate_stage_plan_u23_head_coach_suggestion_v1(
      p_race_preparation_id,
      p_stage_id,
      v_setting.planner_staff_id,
      'manual_refresh'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_u23_stage_plan_automation_dashboard_v2(p_race_preparation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base jsonb;
begin
  v_base :=
    public.get_u23_stage_plan_automation_dashboard_v1(
      p_race_preparation_id
    );

  return
    v_base
    || jsonb_build_object(
      'version',
        'u23_stage_plan_automation_generator_v1',
      'generator_installed',
        true,
      'generator_mode',
        'suggestion_only',
      'save_integration_installed',
        false,
      'post_stage_hook_installed',
        false,
      'generator_function',
        'generate_stage_plan_u23_head_coach_suggestion_v1'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_build_incident_official_activation_plan_v1(p_simulation_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run public.race_stage_simulation_runs%ROWTYPE;
  v_contract public.race_engine_incident_official_activation_contract_v1%ROWTYPE;
  v_shadow_plan jsonb;
  v_weather jsonb;
  v_equipment_rows jsonb := '[]'::jsonb;
  v_equipment_summary jsonb := '{}'::jsonb;
  v_result jsonb;
BEGIN
  IF p_simulation_run_id IS NULL THEN
    RAISE EXCEPTION 'simulation_run_id is required';
  END IF;

  SELECT *
  INTO STRICT v_run
  FROM public.race_stage_simulation_runs
  WHERE id = p_simulation_run_id;

  SELECT *
  INTO STRICT v_contract
  FROM public.race_engine_incident_official_activation_contract_v1
  WHERE contract_key = 'incident_official_activation';

  IF NOT (
    v_contract.weather_contract_approved
    AND v_contract.equipment_contract_approved
    AND v_contract.group_identity_contract_approved
    AND v_contract.health_mapping_contract_approved
  ) THEN
    RAISE EXCEPTION
      'Official incident activation channel contracts are not fully approved.';
  END IF;

  IF NOT v_contract.plan_builder_enabled THEN
    RAISE EXCEPTION
      'Official incident activation plan builder is installed but disabled.';
  END IF;

  v_shadow_plan :=
    public.race_engine_build_incident_multichannel_shadow_plan_v1(
      p_simulation_run_id
    );

  v_weather :=
    public.race_engine_calculate_weather_incident_multiplier_v1(
      v_run.stage_id
    );

  SELECT
    coalesce(
      jsonb_agg(
        to_jsonb(condition_row)
        || jsonb_build_object(
          'equipment_multiplier',
          public.race_engine_calculate_equipment_condition_incident_multiplier_v1(
            condition_row.effective_condition_percent,
            1.0::numeric
          )
        )
        ORDER BY condition_row.team_id::text,
                 condition_row.rider_id::text
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'rider_count', count(*),
      'complete_source_count',
        count(*) FILTER (WHERE condition_row.complete_source),
      'neutral_missing_source_count',
        count(*) FILTER (WHERE NOT condition_row.complete_source),
      'minimum_effective_condition_percent',
        min(condition_row.effective_condition_percent),
      'maximum_effective_condition_percent',
        max(condition_row.effective_condition_percent),
      'assigned_rider_fallback_used', false,
      'modulo_reuse_used', false,
      'persistent_writes', false
    )
  INTO v_equipment_rows, v_equipment_summary
  FROM public.race_engine_resolve_stage_rider_equipment_condition_v1(
    p_simulation_run_id
  ) condition_row;

  v_result := jsonb_build_object(
    'package_version',
      'phase3ad_incident_official_activation_plan_builder_v1',
    'simulation_run_id', p_simulation_run_id,
    'race_id', v_run.race_id,
    'stage_id', v_run.stage_id,
    'forward_only', true,
    'historical_rewrite', false,
    'official_write_status', 'planned_disabled',
    'authoritative_shadow_plan', v_shadow_plan,
    'weather_channel', jsonb_build_object(
      'helper',
        'public.race_engine_calculate_weather_incident_multiplier_v1(uuid)',
      'definition_hash',
        '475d1582a42b4993195c3e31d2977e64',
      'evidence', coalesce(v_weather, '{}'::jsonb)
    ),
    'equipment_channel', jsonb_build_object(
      'reader',
        'public.race_engine_resolve_stage_rider_equipment_condition_v1(uuid)',
      'reader_definition_hash',
        '015574f09c1398548f7f73d4441eeb88',
      'multiplier_helper',
        'public.race_engine_calculate_equipment_condition_incident_multiplier_v1(numeric,numeric)',
      'multiplier_helper_definition_hash',
        '15bae31b15cf10ef0aaf2f31fcea7760',
      'summary', v_equipment_summary,
      'rows', v_equipment_rows
    ),
    'group_identity_channel', jsonb_build_object(
      'helper',
        'public.race_engine_select_group_incident_members_v1(uuid,uuid,integer,text)',
      'definition_hash',
        'fce5daa7630995e30b77599436660c75',
      'source_outcome_required', true,
      'fallback_allowed', false,
      'operational_writes', false
    ),
    'health_mapping_channel', jsonb_build_object(
      'helper',
        'public.race_engine_resolve_incident_health_mapping_v1(text,text,text)',
      'definition_hash',
        'f12c1beff171a068d9584fac5b276a7f',
      'approved_mapping_pairs', 12,
      'puncture_health_eligible', false,
      'mechanical_health_eligible', false,
      'operational_writes', false
    ),
    'safety', jsonb_build_object(
      'plan_rows_written', 0,
      'incident_rows_written', 0,
      'group_rows_written', 0,
      'group_member_rows_written', 0,
      'health_rows_written', 0,
      'runner_calls', 0,
      'writer_calls', 0,
      'scheduler_calls', 0,
      'dispatcher_calls', 0
    )
  );

  RETURN v_result;
END
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_write_incidents_multichannel_v1(p_simulation_run_id uuid, p_dry_run boolean DEFAULT true, p_consumer text DEFAULT 'official_disabled'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_contract public.race_engine_incident_official_activation_contract_v1%rowtype;
  v_plan jsonb;
  v_shadow jsonb;
  v_weather jsonb;
  v_equipment_rows jsonb;

  v_plan_row_count integer := 0;
  v_selected_count integer := 0;
  v_blocked_group_count integer := 0;
  v_incident_insert_count integer := 0;
begin
  if $1 is null then
    raise exception 'simulation_run_id is required';
  end if;

  select *
  into strict v_contract
  from public.race_engine_incident_official_activation_contract_v1
  where contract_key = 'incident_official_activation';

  if not (
    v_contract.plan_builder_enabled
    and v_contract.replacement_writer_enabled
    and v_contract.weather_contract_approved
    and v_contract.equipment_contract_approved
    and v_contract.group_identity_contract_approved
    and v_contract.health_mapping_contract_approved
  ) then
    raise exception
      'Official multichannel incident writer is installed but disabled.';
  end if;

  if not $2 and not (
    (
      v_contract.runtime_canary_enabled
      and v_contract.execution_enabled
      and not v_contract.production_execution_enabled
      and not v_contract.runner_integration_enabled
      and not v_contract.historical_rewrite_enabled
    )
    or
    (
      not v_contract.runtime_canary_enabled
      and v_contract.execution_enabled
      and v_contract.production_execution_enabled
      and v_contract.runner_integration_enabled
      and not v_contract.historical_rewrite_enabled
    )
  ) then
    raise exception
      'Operational incident writes require either the complete runtime-canary gate or the complete production cutover gate.';
  end if;

  if v_contract.historical_rewrite_enabled then
    raise exception
      'Writer package refuses historical execution.';
  end if;

  if v_contract.production_execution_enabled
     is distinct from v_contract.runner_integration_enabled then
    raise exception
      'Writer package refuses partial production/runner activation.';
  end if;

  v_plan :=
    public.race_engine_build_incident_official_activation_plan_v1(
      $1
    );

  v_shadow := v_plan->'authoritative_shadow_plan';
  v_weather := v_plan->'weather_channel'->'evidence';
  v_equipment_rows := v_plan->'equipment_channel'->'rows';

  if jsonb_typeof(v_shadow->'rows') <> 'array'
     or jsonb_typeof(v_equipment_rows) <> 'array' then
    raise exception
      'Official plan-builder source shape does not match the approved writer contract.';
  end if;

  create temporary table if not exists
    pg_temp.phase3ad_writer_bound_rows_v1 (
      plan_row_id uuid primary key,
      simulation_run_id uuid not null,
      race_id uuid not null,
      stage_id uuid not null,
      rider_id uuid not null,
      team_id uuid not null,
      canonical_base_probability numeric not null,
      final_incident_probability numeric not null,
      deterministic_selection_key text not null,
      deterministic_selection_roll numeric not null,
      selected boolean not null,
      planned_incident_type text not null,
      planned_incident_severity text not null,
      planned_time_loss_seconds integer not null,
      planned_dnf boolean not null,
      planned_event_km numeric,
      planned_phase_number integer,
      weather_evidence jsonb not null,
      equipment_evidence jsonb not null,
      preparation_evidence jsonb not null,
      group_identity_evidence jsonb not null,
      health_mapping_evidence jsonb not null,
      group_identity_blocked boolean not null,
      source_row jsonb not null
    ) on commit drop;

  truncate pg_temp.phase3ad_writer_bound_rows_v1;

  insert into pg_temp.phase3ad_writer_bound_rows_v1 (
    plan_row_id,
    simulation_run_id,
    race_id,
    stage_id,
    rider_id,
    team_id,
    canonical_base_probability,
    final_incident_probability,
    deterministic_selection_key,
    deterministic_selection_roll,
    selected,
    planned_incident_type,
    planned_incident_severity,
    planned_time_loss_seconds,
    planned_dnf,
    planned_event_km,
    planned_phase_number,
    weather_evidence,
    equipment_evidence,
    preparation_evidence,
    group_identity_evidence,
    health_mapping_evidence,
    group_identity_blocked,
    source_row
  )
  select
    (
      substr(md5(
        jsonb_extract_path_text(source_row::jsonb,'simulation_run_id')
        || '|official_incident_plan_v1|'
        || jsonb_extract_path_text(source_row::jsonb,'rider_id')
      ),1,8) || '-'
      || substr(md5(
        jsonb_extract_path_text(source_row::jsonb,'simulation_run_id')
        || '|official_incident_plan_v1|'
        || jsonb_extract_path_text(source_row::jsonb,'rider_id')
      ),9,4) || '-'
      || substr(md5(
        jsonb_extract_path_text(source_row::jsonb,'simulation_run_id')
        || '|official_incident_plan_v1|'
        || jsonb_extract_path_text(source_row::jsonb,'rider_id')
      ),13,4) || '-'
      || substr(md5(
        jsonb_extract_path_text(source_row::jsonb,'simulation_run_id')
        || '|official_incident_plan_v1|'
        || jsonb_extract_path_text(source_row::jsonb,'rider_id')
      ),17,4) || '-'
      || substr(md5(
        jsonb_extract_path_text(source_row::jsonb,'simulation_run_id')
        || '|official_incident_plan_v1|'
        || jsonb_extract_path_text(source_row::jsonb,'rider_id')
      ),21,12)
    )::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'simulation_run_id'))::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'race_id'))::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'stage_id'))::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'rider_id'))::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'team_id'))::uuid,
    (jsonb_extract_path_text(source_row::jsonb,'canonical_formula_components','canonical_base_probability'))::numeric,
    least(
      1::numeric,
      greatest(
        0::numeric,
        (jsonb_extract_path_text(source_row::jsonb,'canonical_formula_components','canonical_base_probability'))::numeric
        *
        case jsonb_extract_path_text(source_row::jsonb,'incident_type_channel','shadow_incident_type')
          when 'crash' then
            coalesce(
              nullif(jsonb_extract_path_text(v_weather::jsonb,'crash_probability_multiplier'),'')::numeric,
              nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
              1::numeric
            )
          when 'mechanical' then
            coalesce(
              nullif(jsonb_extract_path_text(v_weather::jsonb,'mechanical_probability_multiplier'),'')::numeric,
              nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
              1::numeric
            )
          else
            coalesce(
              nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
              1::numeric
            )
        end
        *
        coalesce(
          nullif(
            jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','combined_probability_multiplier'),
            ''
          )::numeric,
          nullif(
            jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','combined_incident_probability_multiplier'),
            ''
          )::numeric,
          nullif(
            jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','final_mechanical_incident_risk_multiplier'),
            ''
          )::numeric,
          1::numeric
        )
      )
    ),
    jsonb_extract_path_text(source_row::jsonb,'baseline_selection_channel','roll_key'),
    (jsonb_extract_path_text(source_row::jsonb,'baseline_selection_channel','roll'))::numeric,
    (
      (jsonb_extract_path_text(source_row::jsonb,'baseline_selection_channel','roll'))::numeric
      <
      least(
        1::numeric,
        greatest(
          0::numeric,
          (jsonb_extract_path_text(source_row::jsonb,'canonical_formula_components','canonical_base_probability'))::numeric
          *
          case jsonb_extract_path_text(source_row::jsonb,'incident_type_channel','shadow_incident_type')
            when 'crash' then
              coalesce(
                nullif(jsonb_extract_path_text(v_weather::jsonb,'crash_probability_multiplier'),'')::numeric,
                nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
                1::numeric
              )
            when 'mechanical' then
              coalesce(
                nullif(jsonb_extract_path_text(v_weather::jsonb,'mechanical_probability_multiplier'),'')::numeric,
                nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
                1::numeric
              )
            else
              coalesce(
                nullif(jsonb_extract_path_text(v_weather::jsonb,'incident_probability_multiplier'),'')::numeric,
                1::numeric
              )
          end
          *
          coalesce(
            nullif(
              jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','combined_probability_multiplier'),
              ''
            )::numeric,
            nullif(
              jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','combined_incident_probability_multiplier'),
              ''
            )::numeric,
            nullif(
              jsonb_extract_path_text(equipment_row::jsonb,'equipment_multiplier','final_mechanical_incident_risk_multiplier'),
              ''
            )::numeric,
            1::numeric
          )
        )
      )
    ),
    jsonb_extract_path_text(source_row::jsonb,'incident_type_channel','shadow_incident_type'),
    jsonb_extract_path_text(source_row::jsonb,'canonical_formula_components','severity'),
    (jsonb_extract_path_text(source_row::jsonb,'canonical_formula_components','canonical_time_loss_seconds_reference'))::integer,
    coalesce(
      (jsonb_extract_path_text(source_row::jsonb,'dnf_candidate_channel','candidate'))::boolean,
      false
    ),
    nullif(jsonb_extract_path_text(source_row::jsonb,'location_channel','shadow_km_marker'),'')::numeric,
    nullif(jsonb_extract_path_text(source_row::jsonb,'location_channel','shadow_phase_number'),'')::integer,
    coalesce(v_weather,'{}'::jsonb),
    coalesce(equipment_row,'{}'::jsonb),
    jsonb_build_object(
      'mechanical_candidate_channel',
        jsonb_extract_path(source_row::jsonb,'mechanical_candidate_channel')
    ),
    coalesce(
      jsonb_extract_path(source_row::jsonb,'group_identity_requirement_channel'),
      '{}'::jsonb
    ),
    coalesce(
      jsonb_extract_path(source_row::jsonb,'health_eligibility_channel'),
      '{}'::jsonb
    ),
    (
      jsonb_extract_path_text(source_row::jsonb,'incident_type_channel','shadow_incident_type') = 'crash'
      and not coalesce(
        (
          jsonb_extract_path_text(source_row::jsonb,'group_identity_requirement_channel','exact_involved_rider_ids_available')
        )::boolean,
        false
      )
    ),
    source_row
  from jsonb_array_elements(v_shadow->'rows')
       as source_items(source_value)
  cross join lateral (
    select source_value::jsonb as source_row
  ) source_binding
  left join lateral (
    select equipment_candidate.value::jsonb as equipment_row
    from jsonb_array_elements(v_equipment_rows)
         as equipment_candidate(value)
    where jsonb_extract_path_text(equipment_candidate.value::jsonb,'rider_id') =
          jsonb_extract_path_text(source_row::jsonb,'rider_id')
    limit 1
  ) equipment_match on true;

  select
    count(*)::integer,
    count(*) filter (where selected)::integer,
    count(*) filter (
      where selected and group_identity_blocked
    )::integer
  into
    v_plan_row_count,
    v_selected_count,
    v_blocked_group_count
  from pg_temp.phase3ad_writer_bound_rows_v1;

  if v_plan_row_count <> jsonb_array_length(v_shadow->'rows') then
    raise exception
      'Writer binding row count does not match authoritative shadow rows.';
  end if;

  if $2 then
    return jsonb_build_object(
      'status', 'dry_run_complete',
      'simulation_run_id', $1,
      'execution_source', $3,
      'plan_row_count', v_plan_row_count,
      'selected_count', v_selected_count,
      'blocked_group_count', v_blocked_group_count,
      'incident_insert_count', 0,
      'persistent_writes', 0,
      'production_execution_allowed', false,
      'runner_calls', 0,
      'historical_rewrite', false
    );
  end if;

  insert into public.race_engine_incident_official_plan_rows_v1 (
    plan_row_id,
    simulation_run_id,
    race_id,
    stage_id,
    rider_id,
    team_id,
    plan_version,
    canonical_base_probability,
    final_incident_probability,
    deterministic_selection_key,
    deterministic_selection_roll,
    selected,
    planned_incident_type,
    planned_incident_severity,
    planned_time_loss_seconds,
    planned_dnf,
    weather_evidence,
    equipment_evidence,
    preparation_evidence,
    group_identity_evidence,
    health_mapping_evidence,
    group_incident_id,
    health_mapping_key,
    official_write_status,
    metadata
  )
  select
    b.plan_row_id,
    b.simulation_run_id,
    b.race_id,
    b.stage_id,
    b.rider_id,
    b.team_id,
    'phase3ad_official_incident_plan_v1',
    b.canonical_base_probability,
    b.final_incident_probability,
    b.deterministic_selection_key,
    b.deterministic_selection_roll,
    b.selected,
    b.planned_incident_type,
    b.planned_incident_severity,
    b.planned_time_loss_seconds,
    b.planned_dnf,
    b.weather_evidence,
    b.equipment_evidence,
    b.preparation_evidence,
    b.group_identity_evidence,
    b.health_mapping_evidence,
    null,
    null,
    case
      when b.selected and b.group_identity_blocked
        then 'official_skipped'
      when b.selected
        then 'canary_planned'
      else 'official_skipped'
    end,
    jsonb_build_object(
      'execution_source', $3,
      'source_row', b.source_row,
      'forward_only', true,
      'historical_rewrite', false
    )
  from pg_temp.phase3ad_writer_bound_rows_v1 b
  on conflict (plan_row_id) do nothing;

  insert into public.race_stage_incidents (
    id,
    simulation_run_id,
    race_id,
    stage_id,
    rider_id,
    team_id,
    incident_type,
    incident_severity,
    km_marker,
    phase_number,
    terrain_type,
    time_loss_seconds,
    caused_dnf,
    created_health_case_id,
    metadata
  )
  select
    b.plan_row_id,
    b.simulation_run_id,
    b.race_id,
    b.stage_id,
    b.rider_id,
    b.team_id,
    b.planned_incident_type,
    b.planned_incident_severity,
    b.planned_event_km,
    b.planned_phase_number,
    null,
    b.planned_time_loss_seconds,
    b.planned_dnf,
    null,
    jsonb_build_object(
      'official_activation_version',
        'phase3ad_official_incident_writer_v1',
      'official_plan_row_id', b.plan_row_id,
      'execution_source', $3,
      'weather_evidence', b.weather_evidence,
      'equipment_evidence', b.equipment_evidence,
      'preparation_evidence', b.preparation_evidence,
      'forward_only', true,
      'historical_rewrite', false
    )
  from pg_temp.phase3ad_writer_bound_rows_v1 b
  where b.selected
    and not b.group_identity_blocked
  on conflict (id) do nothing;

  get diagnostics v_incident_insert_count = row_count;

  update public.race_engine_incident_official_plan_rows_v1 p
  set
    official_write_status =
      case
        when b.group_identity_blocked
          then 'official_skipped'
        else 'official_written'
      end,
    updated_at = clock_timestamp()
  from pg_temp.phase3ad_writer_bound_rows_v1 b
  where p.plan_row_id = b.plan_row_id
    and b.selected;

  return jsonb_build_object(
    'status', 'runtime_canary_write_complete',
    'simulation_run_id', $1,
    'execution_source', $3,
    'plan_row_count', v_plan_row_count,
    'selected_count', v_selected_count,
    'blocked_group_count', v_blocked_group_count,
    'incident_insert_count', v_incident_insert_count,
    'group_incident_insert_count', 0,
    'group_member_insert_count', 0,
    'health_case_insert_count', 0,
    'production_execution_allowed', false,
    'runner_calls', 0,
    'historical_rewrite', false
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.sync_race_stage_plan_shell_from_race_stage_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stage_start_ts timestamp without time zone;
  v_lock_ts timestamp without time zone;
  v_updated_rows integer := 0;
begin
  if new.stage_date is null then
    return new;
  end if;

  v_stage_start_ts :=
    new.stage_date::timestamp
    + make_interval(
        hours =>
          coalesce(
            new.planned_start_hour_number,
            12
          ),
        mins =>
          coalesce(
            new.planned_start_minute,
            0
          )
      );

  v_lock_ts :=
    v_stage_start_ts
    - interval '3 hours';

  update public.race_stage_plans rsp
  set
    race_id =
      new.race_id,

    stage_number =
      new.stage_number,

    stage_date =
      new.stage_date,

    opens_on_game_date =
      new.stage_date - 4,

    locks_on_game_date =
      new.stage_date - 1,

    metadata =
      coalesce(
        rsp.metadata,
        '{}'::jsonb
      )

      -- Saved Stage Plans carry exact stage-start and three-hour lock
      -- timestamps. Keep those timestamps aligned with the canonical Stage.
      || case
           when coalesce(
                  rsp.metadata,
                  '{}'::jsonb
                ) ? 'stage_start_game_ts'
             then jsonb_build_object(
               'stage_start_game_ts',
                 to_char(
                   v_stage_start_ts,
                   'YYYY-MM-DD"T"HH24:MI:SS'
                 )
             )
           else '{}'::jsonb
         end

      || case
           when coalesce(
                  rsp.metadata,
                  '{}'::jsonb
                ) ? 'lock_game_ts'
             then jsonb_build_object(
               'lock_game_ts',
                 to_char(
                   v_lock_ts,
                   'YYYY-MM-DD"T"HH24:MI:SS'
                 )
             )
           else '{}'::jsonb
         end

      || jsonb_build_object(
           'canonical_stage_shell_sync_v1',
             jsonb_build_object(
               'synced_at',
                 clock_timestamp(),

               'source',
                 'race_stages_update_trigger',

               'trigger_name',
                 tg_name,

               'previous',
                 jsonb_build_object(
                   'race_id',
                     rsp.race_id,

                   'stage_number',
                     rsp.stage_number,

                   'stage_date',
                     rsp.stage_date,

                   'opens_on_game_date',
                     rsp.opens_on_game_date,

                   'locks_on_game_date',
                     rsp.locks_on_game_date,

                   'stage_start_game_ts',
                     rsp.metadata
                       ->>'stage_start_game_ts',

                   'lock_game_ts',
                     rsp.metadata
                       ->>'lock_game_ts'
                 ),

               'canonical',
                 jsonb_build_object(
                   'race_id',
                     new.race_id,

                   'stage_number',
                     new.stage_number,

                   'stage_date',
                     new.stage_date,

                   'opens_on_game_date',
                     new.stage_date - 4,

                   'locks_on_game_date',
                     new.stage_date - 1,

                   'stage_start_game_ts',
                     to_char(
                       v_stage_start_ts,
                       'YYYY-MM-DD"T"HH24:MI:SS'
                     ),

                   'lock_game_ts',
                     to_char(
                       v_lock_ts,
                       'YYYY-MM-DD"T"HH24:MI:SS'
                     )
                 )
             )
         ),

    updated_at =
      now()

  where rsp.stage_id = new.id
    and (
      rsp.race_id is distinct from
        new.race_id

      or rsp.stage_number is distinct from
        new.stage_number

      or rsp.stage_date is distinct from
        new.stage_date

      or rsp.opens_on_game_date is distinct from
        new.stage_date - 4

      or rsp.locks_on_game_date is distinct from
        new.stage_date - 1

      or (
        coalesce(
          rsp.metadata,
          '{}'::jsonb
        ) ? 'stage_start_game_ts'
        and rsp.metadata
              ->>'stage_start_game_ts'
            is distinct from
              to_char(
                v_stage_start_ts,
                'YYYY-MM-DD"T"HH24:MI:SS'
              )
      )

      or (
        coalesce(
          rsp.metadata,
          '{}'::jsonb
        ) ? 'lock_game_ts'
        and rsp.metadata
              ->>'lock_game_ts'
            is distinct from
              to_char(
                v_lock_ts,
                'YYYY-MM-DD"T"HH24:MI:SS'
              )
      )
    );

  get diagnostics
    v_updated_rows = row_count;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.capture_u23_stage_plan_manual_save_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_write_source text;
  v_prep record;

  v_manual_reason text :=
    'manager_saved_stage_plan';
begin
  -- UPDATE OF last_saved_at already scopes this trigger to the canonical
  -- Stage Plan save operation. Do not compare OLD and NEW timestamps:
  -- save_race_stage_plan_v1 uses transaction-stable now(), so two valid saves
  -- inside one transaction can intentionally carry the same timestamp.

  if coalesce(
       new.metadata
         ->>'stage_plan_saved_from_rpc',
       ''
     ) <> 'save_race_stage_plan_v1' then
    return new;
  end if;

  v_write_source :=
    lower(
      coalesce(
        nullif(
          current_setting(
            'app.u23_stage_plan_write_source',
            true
          ),
          ''
        ),
        'manual'
      )
    );

  if v_write_source in (
       'u23_head_coach',
       'coach',
       'automation',
       'system'
     ) then
    return new;
  end if;

  select
    rp.id as race_preparation_id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,

    participating_club.name
      as participating_club_name,

    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  where rp.id = new.race_preparation_id;

  if not found then
    return new;
  end if;

  if v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return new;
  end if;

  insert into public.race_stage_plan_management (
    race_stage_plan_id,
    race_preparation_id,
    race_id,
    stage_id,

    owner_club_id,
    participating_club_id,

    management_mode,
    source_type,

    planner_role,
    planner_staff_id,

    source_snapshot_json,
    decision_summary_json,
    metadata,

    generated_at,
    manually_overridden_at,

    created_at,
    updated_at
  )
  values (
    new.id,
    new.race_preparation_id,
    new.race_id,
    new.stage_id,

    v_prep.owner_club_id,
    v_prep.participating_club_id,

    'manual',
    'manual',

    null,
    null,

    jsonb_build_object(
      'stage_plan_last_saved_at',
        new.last_saved_at,

      'stage_plan_last_saved_game_ts',
        new.last_saved_game_ts,

      'team_plan',
        coalesce(
          nullif(
            new.team_tactic_json->>'plan',
            ''
          ),
          new.team_strategy,
          'balanced'
        )
    ),

    jsonb_build_object(
      'manager_saved_current_stage',
        true,

      'coach_resumes_next_stage',
        true
    ),

    jsonb_build_object(
      'manual_reason',
        v_manual_reason,

      'manual_user_id',
        auth.uid(),

      'manual_marked_at',
        clock_timestamp(),

      'write_source',
        v_write_source,

      'save_rpc',
        'save_race_stage_plan_v1',

      'trigger_version',
        'u23_manual_save_capture_v1_1',

      'same_transaction_repeat_save_supported',
        true,

      'participating_club_name',
        v_prep.participating_club_name,

      'coach_resumes_next_stage',
        true
    ),

    null,
    clock_timestamp(),

    now(),
    now()
  )
  on conflict (race_stage_plan_id)
  do update
  set
    race_preparation_id =
      excluded.race_preparation_id,

    race_id =
      excluded.race_id,

    stage_id =
      excluded.stage_id,

    owner_club_id =
      excluded.owner_club_id,

    participating_club_id =
      excluded.participating_club_id,

    management_mode =
      'manual',

    source_type =
      'manual',

    planner_role =
      null,

    planner_staff_id =
      null,

    source_snapshot_json =
      public.race_stage_plan_management
        .source_snapshot_json
      || excluded.source_snapshot_json,

    decision_summary_json =
      public.race_stage_plan_management
        .decision_summary_json
      || excluded.decision_summary_json,

    metadata =
      public.race_stage_plan_management
        .metadata
      || excluded.metadata,

    manually_overridden_at =
      excluded.manually_overridden_at,

    updated_at =
      now();

  -- Current-stage manual ownership never disables race-level automation.
  update public.race_preparation_stage_plan_automation automation
  set
    last_generation_status =
      'manual_override_current_stage',

    last_generation_summary =
      jsonb_build_object(
        'race_stage_plan_id',
          new.id,

        'stage_id',
          new.stage_id,

        'stage_number',
          new.stage_number,

        'stage_date',
          new.stage_date,

        'management_mode',
          'manual',

        'manual_saved_at',
          new.last_saved_at,

        'coach_resumes_next_stage',
          automation.resume_after_manual_stage
      ),

    metadata =
      coalesce(
        automation.metadata,
        '{}'::jsonb
      )
      || jsonb_build_object(
           'save_integration_installed',
             true,

           'manual_save_trigger_version',
             'u23_manual_save_capture_v1_1',

           'same_transaction_repeat_save_supported',
             true,

           'last_manual_override',
             jsonb_build_object(
               'race_stage_plan_id',
                 new.id,

               'stage_id',
                 new.stage_id,

               'stage_number',
                 new.stage_number,

               'marked_at',
                 clock_timestamp(),

               'manual_user_id',
                 auth.uid(),

               'coach_resumes_next_stage',
                 automation.resume_after_manual_stage
             )
         ),

    updated_at =
      now()

  where automation.race_preparation_id =
    new.race_preparation_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_u23_stage_plan_automation_v1(p_race_preparation_id uuid, p_stage_id uuid, p_generation_reason text DEFAULT 'manual_refresh'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep record;
  v_stage_plan record;
  v_stage record;
  v_automation record;
  v_management record;

  v_suggestion_result jsonb;
  v_suggestion jsonb;
  v_quality jsonb;
  v_adaptation_context jsonb;

  v_team_tactic_json jsonb;
  v_rider_roles_json jsonb;
  v_rider_equipment_json jsonb;
  v_rider_individual_tactics_json jsonb;
  v_rider_supplies_json jsonb;

  v_selected_rider_count integer := 0;
  v_role_count integer := 0;
  v_individual_tactic_count integer := 0;
  v_equipment_count integer := 0;
  v_supply_count integer := 0;

  v_planner_staff_id uuid;
  v_quality_score numeric;
  v_quality_tier text;
  v_based_on_stage_id uuid;
  v_suggestion_log_id uuid;
  v_application_log_id uuid;

  v_save_result jsonb;
  v_saved_plan record;

  v_previous_write_source text;

  v_error_message text;
  v_error_detail text;
  v_error_hint text;
begin
  -- ------------------------------------------------------------------------
  -- 1. Owner permission and supported generation reason
  -- ------------------------------------------------------------------------

  if not public.can_manage_race_preparation_v1(
    p_race_preparation_id
  ) then
    raise exception
      'You do not have permission to manage this race preparation.';
  end if;

  if p_generation_reason not in (
    'automation_enabled',
    'race_plan_submitted',
    'stage_result_finalized',
    'manual_refresh',
    'manual_override_cleared'
  ) then
    raise exception
      'Invalid U23 Stage Plan generation reason.';
  end if;

  -- ------------------------------------------------------------------------
  -- 2. Resolve Developing Team preparation
  -- ------------------------------------------------------------------------

  select
    rp.id,
    rp.race_id,
    rp.club_id as owner_club_id,
    rp.participating_club_id,
    rp.status,
    rp.startlist_status,

    participating_club.name
      as participating_club_name,

    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations rp
  join public.clubs participating_club
    on participating_club.id =
      rp.participating_club_id
  where rp.id = p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message',
        'Race preparation was not found.',
      'applied', false
    );
  end if;

  if v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'not_developing_team_preparation',
      'message',
        'U23 Head Coach automation is available only when the Developing Team is participating.',
      'applied', false
    );
  end if;

  if not public.user_has_premium_access_v1(
    (select owner.owner_user_id from public.clubs owner where owner.id=v_prep.owner_club_id)
  ) then
    return jsonb_build_object(
      'status','skipped',
      'code','premium_required',
      'message','Premium membership is required for U23 Head Coach automation.',
      'applied',false
    );
  end if;

  if v_prep.status not in (
       'submitted',
       'locked',
       'sent_to_engine'
     )
     or v_prep.startlist_status not in (
       'submitted',
       'locked',
       'sent_to_engine'
     ) then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_plan_not_submitted',
      'message',
        'Submit the Race Plan before applying an automated Stage Plan.',
      'applied', false
    );
  end if;

  -- ------------------------------------------------------------------------
  -- 3. Enabled automation setting
  -- ------------------------------------------------------------------------

  select *
  into v_automation
  from public.race_preparation_stage_plan_automation automation
  where automation.race_preparation_id =
    p_race_preparation_id
  for update;

  if not found
     or coalesce(
          v_automation.is_enabled,
          false
        ) = false then
    return jsonb_build_object(
      'status', 'skipped',
      'code', 'u23_automation_not_enabled',
      'message',
        'U23 Head Coach Stage Plan automation is not enabled for this race.',
      'applied', false
    );
  end if;

  if v_automation.planner_staff_id is null then
    return jsonb_build_object(
      'status', 'error',
      'code', 'u23_head_coach_not_selected',
      'message',
        'No U23 Head Coach is selected for this automation.',
      'applied', false
    );
  end if;

  -- ------------------------------------------------------------------------
  -- 4. Stage Plan and canonical Stage
  -- ------------------------------------------------------------------------

  select
    rsp.id,
    rsp.race_preparation_id,
    rsp.race_id,
    rsp.stage_id,
    rsp.stage_number,
    rsp.stage_date,
    rsp.status,
    rsp.locked_at,
    rsp.submitted_at,
    rsp.last_saved_at,
    rsp.last_saved_game_ts,
    rsp.metadata,

    rsp.team_tactic_json,
    rsp.rider_roles_json,
    rsp.rider_equipment_json,
    rsp.rider_individual_tactics_json,
    rsp.rider_supplies_json
  into v_stage_plan
  from public.race_stage_plans rsp
  where rsp.race_preparation_id =
      p_race_preparation_id
    and rsp.stage_id = p_stage_id
  order by rsp.created_at desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_plan_not_found',
      'message',
        'The Stage Plan row was not found.',
      'applied', false
    );
  end if;

  select
    rs.id,
    rs.race_id,
    rs.stage_number,
    rs.stage_date,
    rs.planned_start_hour_number,
    rs.planned_start_minute,
    rs.weather_cancelled
  into v_stage
  from public.race_stages rs
  where rs.id = p_stage_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'canonical_stage_not_found',
      'message',
        'The canonical race stage was not found.',
      'applied', false
    );
  end if;

  if v_stage_plan.race_id is distinct from
       v_stage.race_id
     or v_stage_plan.stage_number is distinct from
       v_stage.stage_number
     or v_stage_plan.stage_date is distinct from
       v_stage.stage_date then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_plan_canonical_mismatch',
      'message',
        'The Stage Plan shell is not synchronized with the canonical race stage.',
      'applied', false,
      'stage_plan',
        jsonb_build_object(
          'race_id', v_stage_plan.race_id,
          'stage_number',
            v_stage_plan.stage_number,
          'stage_date', v_stage_plan.stage_date
        ),
      'canonical_stage',
        jsonb_build_object(
          'race_id', v_stage.race_id,
          'stage_number', v_stage.stage_number,
          'stage_date', v_stage.stage_date
        )
    );
  end if;

  if v_stage_plan.locked_at is not null
     or v_stage_plan.status in (
       'locked',
       'submitted',
       'sent_to_engine'
     ) then
    return jsonb_build_object(
      'status', 'skipped',
      'code', 'stage_plan_locked',
      'message',
        'This Stage Plan is locked and cannot be generated.',
      'applied', false
    );
  end if;

  if coalesce(
       v_stage.weather_cancelled,
       false
     ) then
    return jsonb_build_object(
      'status', 'skipped',
      'code', 'stage_weather_cancelled',
      'message',
        'This stage was cancelled due to weather.',
      'applied', false
    );
  end if;

  -- ------------------------------------------------------------------------
  -- 5. Protect manager-owned and legacy-saved stages
  -- ------------------------------------------------------------------------

  select *
  into v_management
  from public.race_stage_plan_management management
  where management.race_stage_plan_id =
    v_stage_plan.id;

  if found
     and v_management.management_mode =
       'manual' then
    return jsonb_build_object(
      'status', 'skipped',
      'code', 'manual_override_current_stage',
      'message',
        'The manager owns this Stage Plan. U23 automation will resume with the next stage.',
      'applied', false,
      'race_stage_plan_id',
        v_stage_plan.id,
      'coach_resumes_next_stage',
        v_automation.resume_after_manual_stage
    );
  end if;

  if v_stage_plan.last_saved_at is not null
     and (
       not found
       or v_management.management_mode <>
          'coach'
       or v_management.source_type <>
          'u23_head_coach'
     ) then
    return jsonb_build_object(
      'status', 'skipped',
      'code',
        'existing_manual_or_legacy_stage_plan',
      'message',
        'An existing saved Stage Plan is protected from automatic overwrite.',
      'applied', false,
      'race_stage_plan_id',
        v_stage_plan.id,
      'last_saved_at',
        v_stage_plan.last_saved_at
    );
  end if;

  -- ------------------------------------------------------------------------
  -- 6. Generate suggestion
  -- ------------------------------------------------------------------------

  v_suggestion_result :=
    public.generate_stage_plan_u23_head_coach_suggestion_v1(
      p_race_preparation_id,
      p_stage_id,
      v_automation.planner_staff_id,
      p_generation_reason
    );

  if coalesce(
       v_suggestion_result->>'status',
       'error'
     ) <> 'ok' then
    update public.race_preparation_stage_plan_automation
    set
      last_generation_status =
        coalesce(
          v_suggestion_result->>'code',
          'suggestion_failed'
        ),

      last_generation_summary =
        jsonb_build_object(
          'stage_id',
            p_stage_id,
          'stage_number',
            v_stage_plan.stage_number,
          'stage_date',
            v_stage_plan.stage_date,
          'applied',
            false,
          'generator_result',
            v_suggestion_result
        ),

      metadata =
        coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object(
             'automatic_writer_installed',
               true,
             'last_apply_attempt_at',
               clock_timestamp()
           ),

      updated_at =
        now()

    where race_preparation_id =
      p_race_preparation_id;

    return v_suggestion_result
      || jsonb_build_object(
           'applied', false,
           'writer_version',
             'u23_stage_plan_auto_apply_v1'
         );
  end if;

  v_suggestion :=
    coalesce(
      v_suggestion_result->'suggestion',
      '{}'::jsonb
    );

  v_quality :=
    coalesce(
      v_suggestion_result->'u23_head_coach',
      '{}'::jsonb
    );

  v_adaptation_context :=
    coalesce(
      v_suggestion_result
        ->'adaptation_context',
      '{}'::jsonb
    );

  v_team_tactic_json :=
    coalesce(
      v_suggestion->'team_tactic_json',
      '{}'::jsonb
    );

  v_rider_roles_json :=
    coalesce(
      v_suggestion->'rider_roles_json',
      '{}'::jsonb
    );

  v_rider_equipment_json :=
    coalesce(
      v_suggestion->'rider_equipment_json',
      '{}'::jsonb
    );

  v_rider_individual_tactics_json :=
    coalesce(
      v_suggestion
        ->'rider_individual_tactics_json',
      '{}'::jsonb
    );

  v_rider_supplies_json :=
    coalesce(
      v_suggestion->'rider_supplies_json',
      '{}'::jsonb
    );

  select count(*)
  into v_selected_rider_count
  from public.race_preparation_riders rpr
  where rpr.race_preparation_id =
    p_race_preparation_id;

  v_role_count :=
    public.jsonb_object_key_count_v1(
      v_rider_roles_json
    );

  v_individual_tactic_count :=
    public.jsonb_object_key_count_v1(
      v_rider_individual_tactics_json
    );

  v_equipment_count :=
    public.jsonb_object_key_count_v1(
      v_rider_equipment_json
    );

  v_supply_count :=
    public.jsonb_object_key_count_v1(
      v_rider_supplies_json
    );

  if v_selected_rider_count <= 0 then
    return jsonb_build_object(
      'status', 'error',
      'code', 'no_selected_riders',
      'message',
        'No riders are attached to this submitted Race Plan.',
      'applied', false
    );
  end if;

  if v_role_count <>
       v_selected_rider_count then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'incomplete_u23_role_suggestion',
      'message',
        'The U23 suggestion does not contain one rider role for every selected rider.',
      'applied', false,
      'selected_rider_count',
        v_selected_rider_count,
      'role_count',
        v_role_count
    );
  end if;

  if v_individual_tactic_count <>
       v_selected_rider_count then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'incomplete_u23_individual_tactics',
      'message',
        'The U23 suggestion does not contain individual tactics for every selected rider.',
      'applied', false,
      'selected_rider_count',
        v_selected_rider_count,
      'individual_tactic_count',
        v_individual_tactic_count
    );
  end if;

  if jsonb_typeof(v_team_tactic_json) <>
       'object'
     or coalesce(
          nullif(
            v_team_tactic_json->>'plan',
            ''
          ),
          ''
        ) = '' then
    return jsonb_build_object(
      'status', 'error',
      'code', 'invalid_u23_team_tactic',
      'message',
        'The U23 suggestion does not contain a valid team tactic.',
      'applied', false
    );
  end if;

  v_planner_staff_id :=
    nullif(
      v_quality->>'planner_staff_id',
      ''
    )::uuid;

  v_quality_score :=
    coalesce(
      nullif(
        v_quality
          ->>'effective_quality_score',
        ''
      )::numeric,
      0
    );

  v_quality_tier :=
    coalesce(
      v_quality->>'quality_tier',
      'basic'
    );

  v_based_on_stage_id :=
    nullif(
      v_adaptation_context
        ->'previous_stage'
        ->>'stage_id',
      ''
    )::uuid;

  v_suggestion_log_id :=
    nullif(
      v_suggestion_result
        ->>'generation_log_id',
      ''
    )::uuid;

  -- ------------------------------------------------------------------------
  -- 7. Save through the canonical Stage Plan RPC
  -- ------------------------------------------------------------------------

  v_previous_write_source :=
    current_setting(
      'app.u23_stage_plan_write_source',
      true
    );

  perform set_config(
    'app.u23_stage_plan_write_source',
    'u23_head_coach',
    true
  );

  begin
    v_save_result :=
      public.save_race_stage_plan_v1(
        v_prep.owner_club_id,
        p_race_preparation_id,
        v_prep.race_id,
        p_stage_id,
        v_stage_plan.stage_number,
        v_team_tactic_json,
        v_rider_roles_json,
        v_rider_equipment_json,
        v_rider_individual_tactics_json,
        v_rider_supplies_json
      );

  exception
    when others then
      get stacked diagnostics
        v_error_message = message_text,
        v_error_detail =
          pg_exception_detail,
        v_error_hint =
          pg_exception_hint;

      perform set_config(
        'app.u23_stage_plan_write_source',
        coalesce(
          v_previous_write_source,
          ''
        ),
        true
      );

      insert into
        public.race_stage_plan_generation_log (
          race_stage_plan_id,
          race_preparation_id,
          race_id,
          stage_id,
          owner_club_id,
          participating_club_id,

          planner_role,
          planner_staff_id,

          generation_reason,
          generation_status,
          based_on_stage_id,
          generation_version,
          decision_quality_score,

          input_snapshot_json,
          suggestion_json,
          result_json,
          error_json,
          metadata
        )
      values (
        v_stage_plan.id,
        p_race_preparation_id,
        v_prep.race_id,
        p_stage_id,
        v_prep.owner_club_id,
        v_prep.participating_club_id,

        'u23_head_coach',
        v_planner_staff_id,

        p_generation_reason,
        'failed',
        v_based_on_stage_id,
        'u23_stage_plan_auto_apply_v1',
        v_quality_score,

        jsonb_build_object(
          'suggestion_log_id',
            v_suggestion_log_id,
          'quality',
            v_quality,
          'adaptation_context',
            v_adaptation_context
        ),

        v_suggestion,

        '{}'::jsonb,

        jsonb_build_object(
          'status', 'error',
          'code', 'stage_plan_save_failed',
          'message', v_error_message,
          'detail', v_error_detail,
          'hint', v_error_hint
        ),

        jsonb_build_object(
          'automatic_writer',
            true,
          'canonical_save_rpc',
            'save_race_stage_plan_v1'
        )
      )
      returning id
      into v_application_log_id;

      update
        public.race_preparation_stage_plan_automation
      set
        last_generation_status =
          'stage_plan_save_failed',

        last_generation_summary =
          jsonb_build_object(
            'stage_id', p_stage_id,
            'stage_number',
              v_stage_plan.stage_number,
            'stage_date',
              v_stage_plan.stage_date,
            'applied', false,
            'application_log_id',
              v_application_log_id,
            'error',
              jsonb_build_object(
                'message',
                  v_error_message,
                'detail',
                  v_error_detail,
                'hint',
                  v_error_hint
              )
          ),

        metadata =
          coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
               'automatic_writer_installed',
                 true,
               'last_apply_attempt_at',
                 clock_timestamp()
             ),

        updated_at =
          now()

      where race_preparation_id =
        p_race_preparation_id;

      return jsonb_build_object(
        'status', 'error',
        'code', 'stage_plan_save_failed',
        'message',
          coalesce(
            v_error_message,
            'The generated Stage Plan could not be saved.'
          ),
        'detail', v_error_detail,
        'hint', v_error_hint,
        'applied', false,
        'suggestion_log_id',
          v_suggestion_log_id,
        'application_log_id',
          v_application_log_id
      );
  end;

  perform set_config(
    'app.u23_stage_plan_write_source',
    coalesce(
      v_previous_write_source,
      ''
    ),
    true
  );

  if coalesce(
       (
         v_save_result->>'success'
       )::boolean,
       false
     ) = false then
    return jsonb_build_object(
      'status', 'error',
      'code',
        'stage_plan_save_returned_unsuccessful',
      'message',
        coalesce(
          v_save_result->>'message',
          'The canonical Stage Plan save RPC did not report success.'
        ),
      'applied', false,
      'save_result', v_save_result,
      'suggestion_log_id',
        v_suggestion_log_id
    );
  end if;

  -- Read back the canonical payload because the TT wrapper may normalize it.
  select
    rsp.id,
    rsp.last_saved_at,
    rsp.last_saved_game_ts,
    rsp.team_strategy,
    rsp.team_tactic_json,
    rsp.rider_roles_json,
    rsp.rider_equipment_json,
    rsp.rider_individual_tactics_json,
    rsp.rider_supplies_json,
    rsp.metadata
  into v_saved_plan
  from public.race_stage_plans rsp
  where rsp.id = v_stage_plan.id;

  -- ------------------------------------------------------------------------
  -- 8. Coach ownership and application audit
  -- ------------------------------------------------------------------------

  insert into public.race_stage_plan_generation_log (
    race_stage_plan_id,
    race_preparation_id,
    race_id,
    stage_id,
    owner_club_id,
    participating_club_id,

    planner_role,
    planner_staff_id,

    generation_reason,
    generation_status,
    based_on_stage_id,
    generation_version,
    decision_quality_score,

    input_snapshot_json,
    suggestion_json,
    result_json,
    error_json,
    metadata
  )
  values (
    v_stage_plan.id,
    p_race_preparation_id,
    v_prep.race_id,
    p_stage_id,
    v_prep.owner_club_id,
    v_prep.participating_club_id,

    'u23_head_coach',
    v_planner_staff_id,

    p_generation_reason,
    'generated',
    v_based_on_stage_id,
    'u23_stage_plan_auto_apply_v1',
    v_quality_score,

    jsonb_build_object(
      'suggestion_log_id',
        v_suggestion_log_id,
      'quality',
        v_quality,
      'adaptation_context',
        v_adaptation_context,
      'counts',
        jsonb_build_object(
          'selected_riders',
            v_selected_rider_count,
          'roles',
            v_role_count,
          'individual_tactics',
            v_individual_tactic_count,
          'equipment',
            v_equipment_count,
          'supplies',
            v_supply_count
        )
    ),

    v_suggestion,

    jsonb_build_object(
      'status', 'ok',
      'applied', true,
      'save_result', v_save_result,
      'saved_payload',
        jsonb_build_object(
          'team_strategy',
            v_saved_plan.team_strategy,
          'team_tactic_json',
            v_saved_plan.team_tactic_json,
          'rider_roles_json',
            v_saved_plan.rider_roles_json,
          'rider_equipment_json',
            v_saved_plan.rider_equipment_json,
          'rider_individual_tactics_json',
            v_saved_plan
              .rider_individual_tactics_json,
          'rider_supplies_json',
            v_saved_plan.rider_supplies_json,
          'last_saved_at',
            v_saved_plan.last_saved_at,
          'last_saved_game_ts',
            v_saved_plan.last_saved_game_ts
        )
    ),

    '{}'::jsonb,

    jsonb_build_object(
      'automatic_writer', true,
      'canonical_save_rpc',
        'save_race_stage_plan_v1',
      'manual_save_trigger_bypassed',
        true,
      'writer_version',
        'u23_stage_plan_auto_apply_v1'
    )
  )
  returning id
  into v_application_log_id;

  insert into public.race_stage_plan_management (
    race_stage_plan_id,
    race_preparation_id,
    race_id,
    stage_id,

    owner_club_id,
    participating_club_id,

    management_mode,
    source_type,

    planner_role,
    planner_staff_id,

    based_on_stage_id,
    generation_version,
    decision_quality_score,

    source_snapshot_json,
    decision_summary_json,
    metadata,

    generated_at,
    manually_overridden_at,

    created_at,
    updated_at
  )
  values (
    v_stage_plan.id,
    p_race_preparation_id,
    v_prep.race_id,
    p_stage_id,

    v_prep.owner_club_id,
    v_prep.participating_club_id,

    'coach',
    'u23_head_coach',

    'u23_head_coach',
    v_planner_staff_id,

    v_based_on_stage_id,
    'u23_stage_plan_auto_apply_v1',
    v_quality_score,

    jsonb_build_object(
      'suggestion_log_id',
        v_suggestion_log_id,
      'application_log_id',
        v_application_log_id,
      'quality',
        v_quality,
      'adaptation_context',
        v_adaptation_context
    ),

    jsonb_build_object(
      'applied',
        true,
      'team_plan',
        coalesce(
          nullif(
            v_saved_plan
              .team_tactic_json
              ->>'plan',
            ''
          ),
          v_saved_plan.team_strategy,
          'balanced'
        ),
      'quality_tier',
        v_quality_tier,
      'counts',
        jsonb_build_object(
          'selected_riders',
            v_selected_rider_count,
          'roles',
            v_role_count,
          'individual_tactics',
            v_individual_tactic_count,
          'equipment',
            v_equipment_count,
          'supplies',
            v_supply_count
        )
    ),

    jsonb_build_object(
      'writer_version',
        'u23_stage_plan_auto_apply_v1',
      'generation_reason',
        p_generation_reason,
      'canonical_save_rpc',
        'save_race_stage_plan_v1',
      'manual_save_trigger_bypassed',
        true,
      'coach_resumes_after_manual_stage',
        v_automation.resume_after_manual_stage
    ),

    clock_timestamp(),
    null,

    now(),
    now()
  )
  on conflict (race_stage_plan_id)
  do update
  set
    race_preparation_id =
      excluded.race_preparation_id,

    race_id =
      excluded.race_id,

    stage_id =
      excluded.stage_id,

    owner_club_id =
      excluded.owner_club_id,

    participating_club_id =
      excluded.participating_club_id,

    management_mode =
      'coach',

    source_type =
      'u23_head_coach',

    planner_role =
      'u23_head_coach',

    planner_staff_id =
      excluded.planner_staff_id,

    based_on_stage_id =
      excluded.based_on_stage_id,

    generation_version =
      excluded.generation_version,

    decision_quality_score =
      excluded.decision_quality_score,

    source_snapshot_json =
      excluded.source_snapshot_json,

    decision_summary_json =
      excluded.decision_summary_json,

    metadata =
      public.race_stage_plan_management
        .metadata
      || excluded.metadata,

    generated_at =
      excluded.generated_at,

    manually_overridden_at =
      null,

    updated_at =
      now();

  update public.race_preparation_stage_plan_automation
  set
    last_generated_stage_id =
      p_stage_id,

    last_source_stage_id =
      v_based_on_stage_id,

    last_generated_at =
      clock_timestamp(),

    last_generation_status =
      'applied',

    last_generation_summary =
      jsonb_build_object(
        'race_stage_plan_id',
          v_stage_plan.id,
        'stage_id',
          p_stage_id,
        'stage_number',
          v_stage_plan.stage_number,
        'stage_date',
          v_stage_plan.stage_date,
        'team_plan',
          coalesce(
            nullif(
              v_saved_plan
                .team_tactic_json
                ->>'plan',
              ''
            ),
            v_saved_plan.team_strategy,
            'balanced'
          ),
        'quality_score',
          v_quality_score,
        'quality_tier',
          v_quality_tier,
        'suggestion_log_id',
          v_suggestion_log_id,
        'application_log_id',
          v_application_log_id,
        'applied',
          true
      ),

    metadata =
      coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
           'generator_installed',
             true,
           'save_integration_installed',
             true,
           'automatic_writer_installed',
             true,
           'post_stage_hook_installed',
             false,
           'last_apply_attempt_at',
             clock_timestamp()
         ),

    updated_at =
      now()

  where race_preparation_id =
    p_race_preparation_id;

  return jsonb_build_object(
    'status', 'ok',
    'version',
      'u23_stage_plan_auto_apply_v1',
    'applied', true,

    'race_preparation_id',
      p_race_preparation_id,
    'race_id',
      v_prep.race_id,
    'race_stage_plan_id',
      v_stage_plan.id,
    'stage_id',
      p_stage_id,
    'stage_number',
      v_stage_plan.stage_number,
    'stage_date',
      v_stage_plan.stage_date,

    'owner_club_id',
      v_prep.owner_club_id,
    'participating_club_id',
      v_prep.participating_club_id,
    'participating_club_name',
      v_prep.participating_club_name,

    'planner_staff_id',
      v_planner_staff_id,
    'quality_score',
      v_quality_score,
    'quality_tier',
      v_quality_tier,

    'suggestion_log_id',
      v_suggestion_log_id,
    'application_log_id',
      v_application_log_id,

    'counts',
      jsonb_build_object(
        'selected_riders',
          v_selected_rider_count,
        'roles',
          v_role_count,
        'individual_tactics',
          v_individual_tactic_count,
        'equipment',
          v_equipment_count,
        'supplies',
          v_supply_count
      ),

    'management',
      jsonb_build_object(
        'management_mode', 'coach',
        'source_type',
          'u23_head_coach',
        'coach_resumes_after_manual_stage',
          v_automation.resume_after_manual_stage
      ),

    'save_result',
      v_save_result
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_calculate_weather_incident_multiplier_v1(p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract
    public.race_engine_incident_gap_resolution_contract_v1%rowtype;
  v_condition_text text;
  v_condition_family text;
  v_temperature numeric;
  v_rain_evidence jsonb;
  v_rain_requirement text;
  v_rule
    public.race_engine_incident_weather_probability_rule_v1%rowtype;
  v_match_count integer;
begin
  select *
  into strict v_contract
  from public.race_engine_incident_gap_resolution_contract_v1
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  if not v_contract.weather_contract_approved
     or not v_contract.candidate_functions_enabled
  then
    raise exception
      'weather incident multiplier is not enabled by the approved activation contract.';
  end if;

  if p_stage_id is null then
    raise exception 'stage id is required.';
  end if;

  v_condition_text :=
    lower(trim(coalesce(
      public.race_stage_weather_condition_text_v2(
        p_stage_id
      ),
      ''
    )));

  v_temperature :=
    public.race_stage_weather_avg_temp_c_v1(
      p_stage_id
    );

  v_rain_evidence :=
    public.race_engine_stage_rain_jacket_requirement_v1(
      p_stage_id
    );

  v_rain_requirement :=
    case
      when coalesce(
        (
          v_rain_evidence ->>
            'rain_jacket_required'
        )::boolean,
        false
      )
      then 'required'
      else 'not_required'
    end;

  v_condition_family :=
    case
      when v_condition_text = '' then 'unknown'
      when v_condition_text ~
        '(rain|drizzle|shower|storm|thunder|sleet)'
      then 'wet'
      when v_condition_text ~ '(snow)'
      then 'snow'
      else 'dry'
    end;

  if v_condition_family = 'snow' then
    return jsonb_build_object(
      'status',
        'blocked_weather_cancelled_family',
      'stage_id', p_stage_id,
      'condition_text', v_condition_text,
      'condition_family', v_condition_family,
      'temperature_c', v_temperature,
      'rain_requirement', v_rain_requirement,
      'source', jsonb_build_object(
        'condition_reader',
          'race_stage_weather_condition_text_v2',
        'temperature_reader',
          'race_stage_weather_avg_temp_c_v1',
        'rain_requirement_reader',
          'race_engine_stage_rain_jacket_requirement_v1'
      )
    );
  end if;

  select count(*)::integer
  into v_match_count
  from public.race_engine_incident_weather_probability_rule_v1
    rule_row
  where rule_row.approved
    and rule_row.active
    and rule_row.weather_condition_key =
      v_condition_family
    and (
      rule_row.rain_requirement = '*'
      or rule_row.rain_requirement =
        v_rain_requirement
    )
    and (
      rule_row.minimum_temperature_c is null
      or v_temperature >=
         rule_row.minimum_temperature_c
    )
    and (
      rule_row.maximum_temperature_c is null
      or v_temperature <
         rule_row.maximum_temperature_c
    );

  if v_match_count <> 1 then
    raise exception
      'weather incident multiplier requires exactly one approved active rule; matched %.',
      v_match_count;
  end if;

  select *
  into strict v_rule
  from public.race_engine_incident_weather_probability_rule_v1
    rule_row
  where rule_row.approved
    and rule_row.active
    and rule_row.weather_condition_key =
      v_condition_family
    and (
      rule_row.rain_requirement = '*'
      or rule_row.rain_requirement =
        v_rain_requirement
    )
    and (
      rule_row.minimum_temperature_c is null
      or v_temperature >=
         rule_row.minimum_temperature_c
    )
    and (
      rule_row.maximum_temperature_c is null
      or v_temperature <
         rule_row.maximum_temperature_c
    );

  return jsonb_build_object(
    'status', 'resolved',
    'stage_id', p_stage_id,
    'condition_text', v_condition_text,
    'condition_family', v_condition_family,
    'temperature_c', v_temperature,
    'rain_requirement', v_rain_requirement,
    'rain_evidence', v_rain_evidence,
    'rule_id', v_rule.rule_id,
    'rule_key', v_rule.rule_key,
    'incident_probability_multiplier',
      v_rule.incident_probability_multiplier,
    'crash_probability_multiplier',
      v_rule.crash_probability_multiplier,
    'mechanical_probability_multiplier',
      v_rule.mechanical_probability_multiplier,
    'dnf_probability_multiplier',
      v_rule.dnf_probability_multiplier,
    'approved', v_rule.approved,
    'active', v_rule.active
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_calculate_equipment_condition_incident_multiplier_v(p_condition_percent numeric, p_mechanical_reliability numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract
    public.race_engine_incident_gap_resolution_contract_v1%rowtype;
  v_rule
    public.race_engine_incident_equipment_condition_rule_v1%rowtype;
  v_match_count integer;
  v_existing_mechanical_incident_risk_multiplier numeric;
  v_condition_multiplier numeric := 1.0;
  v_floor numeric := 0.78;
  v_ceiling numeric := 1.50;
  v_combined numeric;
  v_missing_condition boolean;
begin
  select *
  into strict v_contract
  from public.race_engine_incident_gap_resolution_contract_v1
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  if not v_contract.equipment_contract_approved
     or not v_contract.candidate_functions_enabled
  then
    raise exception
      'equipment condition incident multiplier is not enabled by the approved activation contract.';
  end if;

  v_existing_mechanical_incident_risk_multiplier :=
    coalesce(p_mechanical_reliability, 1.0);

  if v_existing_mechanical_incident_risk_multiplier <= 0
     or v_existing_mechanical_incident_risk_multiplier > 5
  then
    raise exception
      'existing mechanical incident risk multiplier must be greater than 0 and at most 5; got %.',
      v_existing_mechanical_incident_risk_multiplier;
  end if;

  v_missing_condition :=
    p_condition_percent is null;

  if not v_missing_condition
     and (
       p_condition_percent < 0
       or p_condition_percent > 100
     )
  then
    raise exception
      'equipment condition percent must be between 0 and 100; got %.',
      p_condition_percent;
  end if;

  if not v_missing_condition then
    select count(*)::integer
    into v_match_count
    from public.race_engine_incident_equipment_condition_rule_v1
      rule_row
    where rule_row.approved
      and rule_row.active
      and p_condition_percent >=
          rule_row.minimum_condition_percent
      and (
        p_condition_percent <
          rule_row.maximum_condition_percent
        or (
          rule_row.maximum_condition_percent = 100
          and p_condition_percent <= 100
        )
      )
      and (
        rule_row.minimum_mechanical_reliability is null
        or v_existing_mechanical_incident_risk_multiplier >=
           rule_row.minimum_mechanical_reliability
      )
      and (
        rule_row.maximum_mechanical_reliability is null
        or v_existing_mechanical_incident_risk_multiplier <
           rule_row.maximum_mechanical_reliability
      );

    if v_match_count <> 1 then
      raise exception
        'equipment condition multiplier requires exactly one approved active rule; matched %.',
        v_match_count;
    end if;

    select *
    into strict v_rule
    from public.race_engine_incident_equipment_condition_rule_v1
      rule_row
    where rule_row.approved
      and rule_row.active
      and p_condition_percent >=
          rule_row.minimum_condition_percent
      and (
        p_condition_percent <
          rule_row.maximum_condition_percent
        or (
          rule_row.maximum_condition_percent = 100
          and p_condition_percent <= 100
        )
      )
      and (
        rule_row.minimum_mechanical_reliability is null
        or v_existing_mechanical_incident_risk_multiplier >=
           rule_row.minimum_mechanical_reliability
      )
      and (
        rule_row.maximum_mechanical_reliability is null
        or v_existing_mechanical_incident_risk_multiplier <
           rule_row.maximum_mechanical_reliability
      );

    v_condition_multiplier :=
      v_rule.condition_incident_probability_multiplier;
    v_floor := v_rule.combined_probability_floor;
    v_ceiling := v_rule.combined_probability_ceiling;
  end if;

  v_combined :=
    least(
      v_ceiling,
      greatest(
        v_floor,
        v_existing_mechanical_incident_risk_multiplier *
          v_condition_multiplier
      )
    );

  return jsonb_build_object(
    'status',
      case
        when v_missing_condition
        then 'resolved_missing_condition_neutral'
        else 'resolved'
      end,
    'condition_percent', p_condition_percent,
    'missing_condition', v_missing_condition,
    'input_semantics',
      'p_mechanical_reliability is the existing preparation mechanical_incident_risk_multiplier',
    'existing_mechanical_incident_risk_multiplier',
      v_existing_mechanical_incident_risk_multiplier,
    'rule_id',
      case when v_missing_condition then null
           else v_rule.rule_id end,
    'rule_key',
      case when v_missing_condition then null
           else v_rule.rule_key end,
    'condition_incident_probability_multiplier',
      v_condition_multiplier,
    'combined_probability_floor', v_floor,
    'combined_probability_ceiling', v_ceiling,
    'combined_mechanical_incident_risk_multiplier',
      v_combined,
    'double_application_forbidden', true
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_select_group_incident_members_v1(p_simulation_run_id uuid, p_source_event_id uuid, p_involved_rider_count integer, p_source_context text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract
    public.race_engine_incident_gap_resolution_contract_v1%rowtype;
  v_rule
    public.race_engine_group_identity_selection_rule_v1%rowtype;
  v_source_outcome record;
  v_source_interaction record;
  v_source_state record;
  v_rule_count integer;
  v_eligible_count integer;
  v_source_rider_count integer;
  v_target_count integer;
  v_member_rows jsonb;
  v_member_ids jsonb;
  v_shared_group_incident_id uuid;
begin
  select *
  into strict v_contract
  from public.race_engine_incident_gap_resolution_contract_v1
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  if not v_contract.group_contract_approved
     or not v_contract.candidate_functions_enabled
  then
    raise exception
      'group incident member selection is not enabled by the approved activation contract.';
  end if;

  if p_simulation_run_id is null
     or p_source_event_id is null
  then
    raise exception
      'simulation run id and source command-outcome id are required.';
  end if;

  select count(*)::integer
  into v_rule_count
  from public.race_engine_group_identity_selection_rule_v1
  where approved
    and active
    and selection_mode =
      'canonical_live_state_same_physical_group';

  if v_rule_count <> 1 then
    raise exception
      'group member selection requires exactly one approved active rule; matched %.',
      v_rule_count;
  end if;

  select *
  into strict v_rule
  from public.race_engine_group_identity_selection_rule_v1
  where approved
    and active
    and selection_mode =
      'canonical_live_state_same_physical_group';

  select
    outcome_row.id,
    outcome_row.simulation_run_id,
    outcome_row.race_id,
    outcome_row.stage_id,
    outcome_row.rider_id,
    outcome_row.source_interaction_event_id,
    outcome_row.incident_triggered,
    outcome_row.incident_type,
    outcome_row.involved_rider_count
  into v_source_outcome
  from public.race_engine_stage_command_outcomes
    outcome_row
  where outcome_row.id = p_source_event_id
    and outcome_row.simulation_run_id =
      p_simulation_run_id;

  if v_source_outcome.id is null then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'source_command_outcome_not_found',
      'simulation_run_id',
        p_simulation_run_id,
      'source_event_id',
        p_source_event_id,
      'source_context',
        p_source_context
    );
  end if;

  if not coalesce(
       v_source_outcome.incident_triggered,
       false
     )
     or lower(coalesce(
       v_source_outcome.incident_type,
       ''
     )) <> 'crash'
     or coalesce(
       v_source_outcome.involved_rider_count,
       p_involved_rider_count,
       0
     ) <= 1
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'source_outcome_not_eligible_multi_rider_crash',
      'source_event_id',
        p_source_event_id,
      'source_outcome',
        to_jsonb(v_source_outcome)
    );
  end if;

  if p_involved_rider_count is not null
     and v_source_outcome.involved_rider_count is not null
     and p_involved_rider_count <>
         v_source_outcome.involved_rider_count
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'involved_rider_count_mismatch',
      'requested_count',
        p_involved_rider_count,
      'source_count',
        v_source_outcome.involved_rider_count
    );
  end if;

  select
    interaction_row.id,
    interaction_row.race_id,
    interaction_row.stage_id,
    interaction_row.event_km,
    interaction_row.phase_number
  into v_source_interaction
  from public.race_engine_stage_interaction_events
    interaction_row
  where interaction_row.id =
      v_source_outcome.source_interaction_event_id
    and interaction_row.race_id =
      v_source_outcome.race_id
    and interaction_row.stage_id =
      v_source_outcome.stage_id;

  if v_source_interaction.id is null
     or v_source_interaction.event_km is null
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'source_interaction_event_not_resolved',
      'source_event_id',
        p_source_event_id,
      'source_interaction_event_id',
        v_source_outcome.source_interaction_event_id
    );
  end if;

  select
    live_row.race_id,
    live_row.stage_id,
    live_row.rider_id,
    live_row.team_id,
    live_row.phase_number,
    live_row.step_order,
    live_row.km_end,
    live_row.effective_physical_group_key,
    live_row.effective_live_group_size,
    live_row.effective_rider_elapsed_seconds
  into v_source_state
  from public.race_engine_phase3y_canonical_live_state_cache_v1
    live_row
  where live_row.race_id =
      v_source_outcome.race_id
    and live_row.stage_id =
      v_source_outcome.stage_id
    and live_row.rider_id =
      v_source_outcome.rider_id
    and (
      v_source_interaction.phase_number is null
      or live_row.phase_number =
         v_source_interaction.phase_number
    )
  order by
    abs(
      live_row.km_end -
      v_source_interaction.event_km
    ),
    case
      when live_row.km_end <=
           v_source_interaction.event_km
      then 0
      else 1
    end,
    live_row.step_order,
    live_row.rider_id
  limit 1;

  if v_source_state.rider_id is null
     or v_source_state.effective_physical_group_key is null
     or coalesce(
       v_source_state.effective_live_group_size,
       0
     ) < 2
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'source_rider_phase_step_or_group_not_resolved',
      'source_event_id',
        p_source_event_id,
      'source_rider_id',
        v_source_outcome.rider_id
    );
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where live_row.rider_id =
        v_source_outcome.rider_id
    )::integer
  into
    v_eligible_count,
    v_source_rider_count
  from public.race_engine_phase3y_canonical_live_state_cache_v1
    live_row
  where live_row.race_id =
      v_source_state.race_id
    and live_row.stage_id =
      v_source_state.stage_id
    and live_row.phase_number =
      v_source_state.phase_number
    and live_row.step_order =
      v_source_state.step_order
    and live_row.effective_physical_group_key =
      v_source_state.effective_physical_group_key;

  v_target_count :=
    greatest(
      v_rule.minimum_member_count,
      least(
        coalesce(
          p_involved_rider_count,
          v_source_outcome.involved_rider_count,
          v_rule.minimum_member_count
        ),
        v_source_state.effective_live_group_size,
        v_rule.maximum_member_count
      )
    );

  if v_source_rider_count <> 1
     or v_eligible_count < v_target_count
     or v_target_count >
        v_source_state.effective_live_group_size
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'group_cardinality_or_source_rider_guard_failed',
      'source_rider_count',
        v_source_rider_count,
      'eligible_candidate_count',
        v_eligible_count,
      'target_count',
        v_target_count,
      'effective_live_group_size',
        v_source_state.effective_live_group_size
    );
  end if;

  v_shared_group_incident_id :=
    md5(
      p_simulation_run_id::text ||
      '|group_incident_v1|' ||
      p_source_event_id::text
    )::uuid;

  with ordered_members as (
    select
      live_row.rider_id,
      live_row.team_id,
      row_number() over (
        order by
          case
            when live_row.rider_id =
                 v_source_outcome.rider_id
            then 0
            else 1
          end,
          md5(
            p_simulation_run_id::text ||
            '|group_incident_member_v1|' ||
            p_source_event_id::text ||
            '|' ||
            live_row.rider_id::text
          ),
          live_row.rider_id
      )::integer as member_order,
      md5(
        p_simulation_run_id::text ||
        '|group_incident_member_v1|' ||
        p_source_event_id::text ||
        '|' ||
        live_row.rider_id::text
      ) as deterministic_member_key
    from public.race_engine_phase3y_canonical_live_state_cache_v1
      live_row
    where live_row.race_id =
        v_source_state.race_id
      and live_row.stage_id =
        v_source_state.stage_id
      and live_row.phase_number =
        v_source_state.phase_number
      and live_row.step_order =
        v_source_state.step_order
      and live_row.effective_physical_group_key =
        v_source_state.effective_physical_group_key
  ),
  selected_members as (
    select *
    from ordered_members
    where member_order <= v_target_count
  )
  select
    jsonb_agg(
      jsonb_build_object(
        'member_order', member_order,
        'rider_id', rider_id,
        'team_id', team_id,
        'deterministic_member_key',
          deterministic_member_key
      )
      order by member_order
    ),
    jsonb_agg(
      to_jsonb(rider_id)
      order by member_order
    )
  into
    v_member_rows,
    v_member_ids
  from selected_members;

  if jsonb_array_length(
       coalesce(v_member_ids, '[]'::jsonb)
     ) <> v_target_count
  then
    return jsonb_build_object(
      'status',
        'blocked_no_authoritative_group_members',
      'reason',
        'selected_member_cardinality_mismatch',
      'target_count',
        v_target_count,
      'selected_count',
        jsonb_array_length(
          coalesce(v_member_ids, '[]'::jsonb)
        )
    );
  end if;

  return jsonb_build_object(
    'status', 'resolved',
    'selection_mode',
      v_rule.selection_mode,
    'simulation_run_id',
      p_simulation_run_id,
    'source_event_id',
      p_source_event_id,
    'source_context',
      p_source_context,
    'source_interaction_event_id',
      v_source_outcome.source_interaction_event_id,
    'source_rider_id',
      v_source_outcome.rider_id,
    'race_id',
      v_source_state.race_id,
    'stage_id',
      v_source_state.stage_id,
    'phase_number',
      v_source_state.phase_number,
    'step_order',
      v_source_state.step_order,
    'event_km',
      v_source_interaction.event_km,
    'resolved_km_end',
      v_source_state.km_end,
    'effective_physical_group_key',
      v_source_state.effective_physical_group_key,
    'effective_live_group_size',
      v_source_state.effective_live_group_size,
    'target_member_count',
      v_target_count,
    'shared_group_incident_id',
      v_shared_group_incident_id,
    'shared_group_key',
      'group_crash:' ||
      p_source_event_id::text,
    'member_ids',
      v_member_ids,
    'members',
      v_member_rows,
    'fallback_used', false,
    'writes_performed', false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_resolve_incident_health_mapping_v1(p_incident_type text, p_incident_severity text, p_source_context text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract
    public.race_engine_incident_gap_resolution_contract_v1%rowtype;
  v_mapping
    public.race_engine_incident_health_mapping_v1%rowtype;
  v_incident_type text :=
    lower(trim(coalesce(p_incident_type, '')));
  v_incident_severity text :=
    lower(trim(coalesce(p_incident_severity, '')));
  v_match_count integer;
begin
  select *
  into strict v_contract
  from public.race_engine_incident_gap_resolution_contract_v1
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  if not v_contract.health_contract_approved
     or not v_contract.candidate_functions_enabled
  then
    raise exception
      'incident health mapping is not enabled by the approved activation contract.';
  end if;

  if v_incident_type not in (
       'crash',
       'puncture',
       'mechanical',
       'exhaustion'
     )
     or v_incident_severity not in (
       'minor',
       'moderate',
       'major'
     )
  then
    raise exception
      'unsupported incident type/severity combination: %/%.',
      v_incident_type,
      v_incident_severity;
  end if;

  select count(*)::integer
  into v_match_count
  from public.race_engine_incident_health_mapping_v1
    mapping_row
  where mapping_row.approved
    and mapping_row.active
    and mapping_row.incident_type =
      v_incident_type
    and mapping_row.incident_severity =
      v_incident_severity;

  if v_match_count <> 1 then
    raise exception
      'incident health mapping requires exactly one approved active mapping; matched % for %/%.',
      v_match_count,
      v_incident_type,
      v_incident_severity;
  end if;

  select *
  into strict v_mapping
  from public.race_engine_incident_health_mapping_v1
    mapping_row
  where mapping_row.approved
    and mapping_row.active
    and mapping_row.incident_type =
      v_incident_type
    and mapping_row.incident_severity =
      v_incident_severity;

  return jsonb_build_object(
    'status', 'resolved',
    'source_context', p_source_context,
    'mapping_key', v_mapping.mapping_key,
    'incident_type', v_mapping.incident_type,
    'incident_severity',
      v_mapping.incident_severity,
    'health_case_eligible',
      v_mapping.health_case_eligible,
    'case_code', v_mapping.case_code,
    'minimum_duration_days',
      v_mapping.minimum_duration_days,
    'maximum_duration_days',
      v_mapping.maximum_duration_days,
    'duration_source',
      v_mapping.duration_source,
    'performance_penalty',
      v_mapping.performance_penalty,
    'body_part_policy',
      v_mapping.body_part_policy,
    'health_case_creation_probability',
      v_mapping.health_case_creation_probability,
    'dnf_health_case_required',
      v_mapping.dnf_health_case_required,
    'mapping_source',
      v_mapping.mapping_source,
    'approved', v_mapping.approved,
    'active', v_mapping.active,
    'health_case_created', false,
    'writes_performed', false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_u23_next_stage_from_completed_run_v1(p_simulation_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run record;
  v_candidate record;
  v_event record;
  v_target record;

  v_writer_result jsonb;
  v_candidate_results jsonb :=
    '[]'::jsonb;

  v_final_event_statuses constant text[] :=
    array[
      'applied',
      'already_applied',
      'no_next_stage',
      'target_weather_cancelled',
      'target_manual_override',
      'target_locked',
      'target_protected_saved',
      'writer_skipped'
    ];

  v_processing_status text;
  v_writer_code text;

  v_current_game_ts timestamp without time zone;

  v_previous_claim_sub text;
  v_previous_claim_role text;
  v_previous_claims text;

  v_error_message text;
  v_error_detail text;
  v_error_hint text;

  v_processed integer := 0;
  v_applied integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
begin
  if p_simulation_run_id is null then
    return jsonb_build_object(
      'status', 'error',
      'code', 'simulation_run_id_required',
      'message',
        'Simulation run ID is required.'
    );
  end if;

  select
    simulation_run.id,
    simulation_run.race_id,
    simulation_run.stage_id,
    simulation_run.status,
    simulation_run.completed_at,
    simulation_run.updated_at,
    simulation_run.engine_version,
    simulation_run.simulation_mode,
    simulation_run.result_summary_json,

    source_stage.stage_number,
    source_stage.stage_date,
    source_stage.stage_format,
    source_stage.weather_cancelled
  into v_run
  from public.race_stage_simulation_runs
    simulation_run
  join public.race_stages source_stage
    on source_stage.id =
      simulation_run.stage_id
  where simulation_run.id =
      p_simulation_run_id;

  if not found then
    return jsonb_build_object(
      'status', 'skipped',
      'code', 'simulation_run_not_found',
      'simulation_run_id',
        p_simulation_run_id,
      'processed', 0
    );
  end if;

  if lower(
       coalesce(
         v_run.status,
         ''
       )
     ) <> 'completed'
     or v_run.completed_at is null then
    return jsonb_build_object(
      'status', 'skipped',
      'code',
        'simulation_run_not_completed',
      'simulation_run_id',
        p_simulation_run_id,
      'run_status',
        v_run.status,
      'completed_at',
        v_run.completed_at,
      'processed', 0
    );
  end if;

  v_current_game_ts :=
    public.get_current_game_timestamp();

  /*
   * A separate processor call or a deferred trigger at transaction end sees
   * only a committed/full race-engine transaction. The completed run is the
   * common source for road, ITT, TTT, and weather-cancelled stages.
   */
  for v_candidate in
    select
      automation.race_preparation_id,
      automation.owner_club_id,
      automation.participating_club_id,
      automation.planner_staff_id,
      automation.resume_after_manual_stage,
      automation.created_at
        as automation_created_at,
      automation.updated_at
        as automation_updated_at,

      coalesce(
        nullif(
          automation.metadata
            ->>'configured_at',
          ''
        )::timestamptz,
        automation.updated_at,
        automation.created_at
      ) as automation_enabled_at,

      preparation.status
        as preparation_status,
      preparation.startlist_status,

      owner_club.owner_user_id,

      participating_club.name
        as participating_club_name

    from
      public.race_preparation_stage_plan_automation
        automation

    join public.race_preparations preparation
      on preparation.id =
        automation.race_preparation_id

    join public.clubs owner_club
      on owner_club.id =
        preparation.club_id

    join public.clubs participating_club
      on participating_club.id =
        preparation.participating_club_id

    where automation.is_enabled = true

      and automation.planner_role =
        'u23_head_coach'

      and automation.planner_staff_id
        is not null

      and preparation.race_id =
        v_run.race_id

      and preparation.club_id =
        automation.owner_club_id

      and preparation.participating_club_id =
        automation.participating_club_id

      and preparation.status in (
        'submitted',
        'locked',
        'sent_to_engine'
      )

      and preparation.startlist_status in (
        'submitted',
        'locked',
        'sent_to_engine'
      )

      and participating_club.club_type =
        'developing'

      and participating_club.parent_club_id =
        preparation.club_id

      and owner_club.owner_user_id
        is not null

      /*
       * Do not backfill stages completed before the current automation
       * configuration. Enabling automation already invokes the first eligible
       * Stage Plan through the upgraded setter.
       */
      and coalesce(
        nullif(
          automation.metadata
            ->>'configured_at',
          ''
        )::timestamptz,
        automation.updated_at,
        automation.created_at
      ) <= v_run.completed_at

    order by
      automation.race_preparation_id
  loop
    perform pg_advisory_xact_lock(
      hashtextextended(
        v_candidate.race_preparation_id::text
        || ':'
        || v_run.stage_id::text
        || ':u23-next-stage-v1',
        0
      )
    );

    select *
    into v_event
    from public.race_stage_plan_automation_stage_events
      event_row
    where event_row.race_preparation_id =
        v_candidate.race_preparation_id
      and event_row.source_stage_id =
        v_run.stage_id
    for update;

    if found
       and v_event.processing_status =
         any(v_final_event_statuses) then
      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'status',
                 'already_processed',

               'processing_status',
                 v_event.processing_status,

               'event_id',
                 v_event.id,

               'source_stage_id',
                 v_run.stage_id,

               'target_stage_id',
                 v_event.target_stage_id
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    insert into
      public.race_stage_plan_automation_stage_events (
        race_preparation_id,
        source_simulation_run_id,
        source_stage_id,

        event_type,
        processing_status,

        attempt_count,
        last_attempt_at,

        result_json,
        error_json,
        metadata,

        created_at,
        updated_at
      )
    values (
      v_candidate.race_preparation_id,
      p_simulation_run_id,
      v_run.stage_id,

      'stage_result_finalized',
      'processing',

      1,
      clock_timestamp(),

      '{}'::jsonb,
      '{}'::jsonb,

      jsonb_build_object(
        'source_stage_number',
          v_run.stage_number,

        'source_stage_date',
          v_run.stage_date,

        'source_stage_format',
          v_run.stage_format,

        'source_weather_cancelled',
          v_run.weather_cancelled,

        'simulation_mode',
          v_run.simulation_mode,

        'engine_version',
          v_run.engine_version,

        'automation_enabled_at',
          v_candidate.automation_enabled_at,

        'processor_version',
          'u23_post_stage_deferred_hook_v1'
      ),

      now(),
      now()
    )
    on conflict (
      race_preparation_id,
      source_stage_id
    )
    do update
    set
      source_simulation_run_id =
        excluded.source_simulation_run_id,

      processing_status =
        'processing',

      attempt_count =
        public.race_stage_plan_automation_stage_events
          .attempt_count
        + 1,

      last_attempt_at =
        excluded.last_attempt_at,

      error_json =
        '{}'::jsonb,

      metadata =
        public.race_stage_plan_automation_stage_events
          .metadata
        || excluded.metadata,

      updated_at =
        now()

    returning *
    into v_event;

    v_processed :=
      v_processed + 1;

    /*
     * Exact next scheduled stage only.
     *
     * We do not jump over a manager-owned or weather-cancelled stage. That
     * stage remains the next source event in the stage-by-stage sequence.
     */
    select
      next_stage.id
        as target_stage_id,

      next_stage.stage_number
        as target_stage_number,

      next_stage.stage_date
        as target_stage_date,

      next_stage.stage_format
        as target_stage_format,

      next_stage.weather_cancelled
        as target_weather_cancelled,

      next_plan.id
        as race_stage_plan_id,

      next_plan.status
        as target_plan_status,

      next_plan.locked_at
        as target_locked_at,

      next_plan.submitted_at
        as target_submitted_at,

      next_plan.last_saved_at
        as target_last_saved_at,

      next_plan.race_id
        as target_plan_race_id,

      next_plan.stage_number
        as target_plan_stage_number,

      next_plan.stage_date
        as target_plan_stage_date,

      management.management_mode,
      management.source_type,
      management.planner_role,
      management.planner_staff_id,
      management.based_on_stage_id,

      (
        next_stage.stage_date::timestamp
        + make_interval(
            hours =>
              coalesce(
                next_stage
                  .planned_start_hour_number,
                12
              ),

            mins =>
              coalesce(
                next_stage
                  .planned_start_minute,
                0
              )
          )
      ) as target_start_game_ts,

      (
        next_stage.stage_date::timestamp
        + make_interval(
            hours =>
              coalesce(
                next_stage
                  .planned_start_hour_number,
                12
              ),

            mins =>
              coalesce(
                next_stage
                  .planned_start_minute,
                0
              )
          )
        - interval '3 hours'
      ) as target_lock_game_ts

    into v_target

    from public.race_stages next_stage

    left join public.race_stage_plans next_plan
      on next_plan.race_preparation_id =
          v_candidate.race_preparation_id
     and next_plan.stage_id =
          next_stage.id

    left join public.race_stage_plan_management
      management
      on management.race_stage_plan_id =
        next_plan.id

    where next_stage.race_id =
        v_run.race_id

      and next_stage.stage_number >
        v_run.stage_number

    order by
      next_stage.stage_number,
      next_stage.stage_date,
      next_stage.id

    limit 1;

    if v_target.target_stage_id is null then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'no_next_stage',

        target_stage_id =
          null,

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status', 'completed',
            'code', 'no_next_stage',
            'source_stage_id',
              v_run.stage_id,
            'source_stage_number',
              v_run.stage_number,
            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status',
                 'completed',

               'code',
                 'no_next_stage',

               'source_stage_id',
                 v_run.stage_id,

               'applied',
                 false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    update
      public.race_stage_plan_automation_stage_events
    set
      target_stage_id =
        v_target.target_stage_id,

      metadata =
        metadata
        || jsonb_build_object(
             'target_stage_number',
               v_target.target_stage_number,

             'target_stage_date',
               v_target.target_stage_date,

             'target_stage_format',
               v_target.target_stage_format,

             'target_start_game_ts',
               v_target.target_start_game_ts,

             'target_lock_game_ts',
               v_target.target_lock_game_ts
           ),

      updated_at =
        now()

    where id = v_event.id;

    if v_target.race_stage_plan_id is null then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_stage_plan_missing',

        error_json =
          jsonb_build_object(
            'status', 'error',
            'code',
              'target_stage_plan_missing',

            'message',
              'The exact next Stage does not have a Stage Plan shell.',

            'target_stage_id',
              v_target.target_stage_id,

            'target_stage_number',
              v_target.target_stage_number
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'error',

               'code',
                 'target_stage_plan_missing',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_failed := v_failed + 1;
      continue;
    end if;

    if v_target.target_plan_race_id
         is distinct from
       v_run.race_id
       or v_target.target_plan_stage_number
         is distinct from
       v_target.target_stage_number
       or v_target.target_plan_stage_date
         is distinct from
       v_target.target_stage_date then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_stage_plan_missing',

        error_json =
          jsonb_build_object(
            'status', 'error',
            'code',
              'target_stage_plan_canonical_mismatch',

            'message',
              'The next Stage Plan shell is not synchronized with its canonical Stage.'
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'error',

               'code',
                 'target_stage_plan_canonical_mismatch',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_failed := v_failed + 1;
      continue;
    end if;

    if coalesce(
         v_target.target_weather_cancelled,
         false
       ) then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_weather_cancelled',

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status', 'skipped',
            'code',
              'target_weather_cancelled',

            'message',
              'The exact next stage is weather-cancelled. Its own completed synthetic run will advance automation afterward.',

            'target_stage_id',
              v_target.target_stage_id,

            'target_stage_number',
              v_target.target_stage_number,

            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'skipped',

               'code',
                 'target_weather_cancelled',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    if v_target.management_mode =
         'manual' then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_manual_override',

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status', 'skipped',
            'code',
              'manual_override_current_stage',

            'message',
              'The manager owns the exact next Stage Plan. The coach will resume after that stage finishes.',

            'target_stage_id',
              v_target.target_stage_id,

            'target_stage_number',
              v_target.target_stage_number,

            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'skipped',

               'code',
                 'manual_override_current_stage',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    if v_target.target_locked_at is not null
       or v_target.target_submitted_at is not null
       or v_target.target_plan_status in (
         'locked',
         'submitted',
         'sent_to_engine'
       )
       or v_target.target_lock_game_ts <=
         v_current_game_ts then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_locked',

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status', 'skipped',
            'code', 'stage_plan_locked',
            'message',
              'The exact next Stage Plan is already locked.',
            'target_stage_id',
              v_target.target_stage_id,
            'target_stage_number',
              v_target.target_stage_number,
            'target_lock_game_ts',
              v_target.target_lock_game_ts,
            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'skipped',

               'code',
                 'stage_plan_locked',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    if v_target.target_last_saved_at
         is not null
       and not (
         v_target.management_mode =
           'coach'
         and v_target.source_type =
           'u23_head_coach'
       ) then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'target_protected_saved',

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status', 'skipped',
            'code',
              'existing_manual_or_legacy_stage_plan',

            'message',
              'The exact next Stage Plan already contains a protected manager or legacy save.',

            'target_stage_id',
              v_target.target_stage_id,

            'target_stage_number',
              v_target.target_stage_number,

            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status', 'skipped',

               'code',
                 'existing_manual_or_legacy_stage_plan',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    if v_target.management_mode =
         'coach'
       and v_target.source_type =
         'u23_head_coach'
       and v_target.based_on_stage_id =
         v_run.stage_id
       and v_target.target_last_saved_at
         is not null then
      update
        public.race_stage_plan_automation_stage_events
      set
        processing_status =
          'already_applied',

        processed_at =
          clock_timestamp(),

        result_json =
          jsonb_build_object(
            'status',
              'already_processed',

            'code',
              'target_already_generated_from_source_stage',

            'target_stage_id',
              v_target.target_stage_id,

            'target_stage_number',
              v_target.target_stage_number,

            'applied', false
          ),

        updated_at =
          now()

      where id = v_event.id;

      v_candidate_results :=
        v_candidate_results
        || jsonb_build_array(
             jsonb_build_object(
               'race_preparation_id',
                 v_candidate.race_preparation_id,

               'event_id',
                 v_event.id,

               'status',
                 'already_processed',

               'code',
                 'target_already_generated_from_source_stage',

               'target_stage_id',
                 v_target.target_stage_id,

               'applied', false
             )
           );

      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_previous_claim_sub :=
      current_setting(
        'request.jwt.claim.sub',
        true
      );

    v_previous_claim_role :=
      current_setting(
        'request.jwt.claim.role',
        true
      );

    v_previous_claims :=
      current_setting(
        'request.jwt.claims',
        true
      );

    begin
      /*
       * The public writer retains its normal owner authorization contract.
       * This trusted SECURITY DEFINER processor supplies the actual owner claim
       * only for the duration of this internal call.
       */
      perform set_config(
        'request.jwt.claim.sub',
        v_candidate.owner_user_id::text,
        true
      );

      perform set_config(
        'request.jwt.claim.role',
        'authenticated',
        true
      );

      perform set_config(
        'request.jwt.claims',
        jsonb_build_object(
          'sub',
            v_candidate.owner_user_id,

          'role',
            'authenticated'
        )::text,
        true
      );

      v_writer_result :=
        public.apply_u23_stage_plan_automation_v1(
          v_candidate.race_preparation_id,
          v_target.target_stage_id,
          'stage_result_finalized'
        );

      perform set_config(
        'request.jwt.claim.sub',
        coalesce(
          v_previous_claim_sub,
          ''
        ),
        true
      );

      perform set_config(
        'request.jwt.claim.role',
        coalesce(
          v_previous_claim_role,
          ''
        ),
        true
      );

      perform set_config(
        'request.jwt.claims',
        coalesce(
          v_previous_claims,
          '{}'
        ),
        true
      );

    exception
      when others then
        get stacked diagnostics
          v_error_message =
            message_text,

          v_error_detail =
            pg_exception_detail,

          v_error_hint =
            pg_exception_hint;

        perform set_config(
          'request.jwt.claim.sub',
          coalesce(
            v_previous_claim_sub,
            ''
          ),
          true
        );

        perform set_config(
          'request.jwt.claim.role',
          coalesce(
            v_previous_claim_role,
            ''
          ),
          true
        );

        perform set_config(
          'request.jwt.claims',
          coalesce(
            v_previous_claims,
            '{}'
          ),
          true
        );

        v_writer_result :=
          jsonb_build_object(
            'status', 'error',
            'code',
              'u23_post_stage_writer_exception',

            'message',
              v_error_message,

            'detail',
              v_error_detail,

            'hint',
              v_error_hint,

            'applied', false
          );
    end;

    v_writer_code :=
      coalesce(
        v_writer_result->>'code',
        ''
      );

    if coalesce(
         (
           v_writer_result->>'applied'
         )::boolean,
         false
       )
       and v_writer_result->>'status' =
         'ok' then
      v_processing_status :=
        'applied';

      v_applied :=
        v_applied + 1;

    elsif v_writer_result->>'status' =
            'skipped'
          and v_writer_code in (
            'manual_override_current_stage',
            'stage_plan_locked',
            'stage_weather_cancelled',
            'existing_manual_or_legacy_stage_plan'
          ) then
      v_processing_status :=
        'writer_skipped';

      v_skipped :=
        v_skipped + 1;

    else
      v_processing_status :=
        'failed';

      v_failed :=
        v_failed + 1;
    end if;

    update
      public.race_stage_plan_automation_stage_events
    set
      processing_status =
        v_processing_status,

      processed_at =
        case
          when v_processing_status in (
            'applied',
            'writer_skipped'
          )
            then clock_timestamp()
          else null
        end,

      result_json =
        case
          when v_processing_status in (
            'applied',
            'writer_skipped'
          )
            then v_writer_result
          else '{}'::jsonb
        end,

      error_json =
        case
          when v_processing_status =
            'failed'
            then v_writer_result
          else '{}'::jsonb
        end,

      metadata =
        metadata
        || jsonb_build_object(
             'writer_called_at',
               clock_timestamp(),

             'writer_version',
               'u23_stage_plan_auto_apply_v1',

             'generation_reason',
               'stage_result_finalized'
           ),

      updated_at =
        now()

    where id = v_event.id;

    v_candidate_results :=
      v_candidate_results
      || jsonb_build_array(
           jsonb_build_object(
             'race_preparation_id',
               v_candidate.race_preparation_id,

             'event_id',
               v_event.id,

             'processing_status',
               v_processing_status,

             'source_stage_id',
               v_run.stage_id,

             'source_stage_number',
               v_run.stage_number,

             'target_stage_id',
               v_target.target_stage_id,

             'target_stage_number',
               v_target.target_stage_number,

             'writer_result',
               v_writer_result
           )
         );
  end loop;

  return jsonb_build_object(
    'status', 'completed',

    'version',
      'u23_post_stage_deferred_hook_v1',

    'simulation_run_id',
      p_simulation_run_id,

    'race_id',
      v_run.race_id,

    'source_stage_id',
      v_run.stage_id,

    'source_stage_number',
      v_run.stage_number,

    'source_stage_date',
      v_run.stage_date,

    'source_stage_format',
      v_run.stage_format,

    'source_weather_cancelled',
      v_run.weather_cancelled,

    'completed_at',
      v_run.completed_at,

    'processed',
      v_processed,

    'applied',
      v_applied,

    'skipped',
      v_skipped,

    'failed',
      v_failed,

    'results',
      v_candidate_results
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_process_u23_next_stage_from_completed_run_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  /*
   * This trigger is deferred to transaction end. Querying the current run row
   * inside the processor therefore sees the final state after all statements
   * in the race-engine transaction.
   */
  begin
    v_result :=
      public.process_u23_next_stage_from_completed_run_v1(
        new.id
      );

  exception
    when others then
      /*
       * U23 planning must never roll back official race completion.
       * A retry sweep can revisit the completed simulation run later.
       */
      raise warning
        'Deferred U23 next-stage processing failed for simulation run %: %',
        new.id,
        sqlerrm;
  end;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_due_u23_next_stage_automation_v1(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_limit integer :=
    greatest(
      1,
      least(
        coalesce(p_limit, 50),
        250
      )
    );

  v_run record;
  v_result jsonb;

  v_results jsonb :=
    '[]'::jsonb;

  v_examined integer := 0;
begin
  /*
   * The sweep handles:
   *   - a deferred trigger error that was caught to protect race completion;
   *   - retryable failed events;
   *   - a trigger temporarily disabled during maintenance.
   *
   * Final event statuses are never replayed.
   */
  for v_run in
    select distinct on (
      simulation_run.id
    )
      simulation_run.id,
      simulation_run.completed_at,
      simulation_run.stage_id

    from public.race_stage_simulation_runs
      simulation_run

    join public.race_preparations preparation
      on preparation.race_id =
        simulation_run.race_id

    join public.race_preparation_stage_plan_automation
      automation
      on automation.race_preparation_id =
        preparation.id

    left join
      public.race_stage_plan_automation_stage_events
        event_row
      on event_row.race_preparation_id =
          preparation.id
     and event_row.source_stage_id =
          simulation_run.stage_id

    where simulation_run.status =
        'completed'

      and simulation_run.completed_at
        is not null

      and automation.is_enabled =
        true

      and automation.planner_staff_id
        is not null

      and coalesce(
        nullif(
          automation.metadata
            ->>'configured_at',
          ''
        )::timestamptz,
        automation.updated_at,
        automation.created_at
      ) <= simulation_run.completed_at

      and (
        event_row.id is null

        or event_row.processing_status in (
          'pending',
          'processing',
          'target_stage_plan_missing',
          'failed'
        )
      )

    order by
      simulation_run.id,
      simulation_run.completed_at,
      preparation.id

    limit v_limit
  loop
    v_examined :=
      v_examined + 1;

    begin
      v_result :=
        public.process_u23_next_stage_from_completed_run_v1(
          v_run.id
        );

    exception
      when others then
        v_result :=
          jsonb_build_object(
            'status', 'error',
            'code',
              'u23_retry_sweep_exception',

            'simulation_run_id',
              v_run.id,

            'message',
              sqlerrm
          );
    end;

    v_results :=
      v_results
      || jsonb_build_array(
           v_result
         );
  end loop;

  return jsonb_build_object(
    'status', 'completed',

    'version',
      'u23_post_stage_retry_sweep_v1',

    'limit',
      v_limit,

    'examined',
      v_examined,

    'results',
      v_results
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_stage_plan_canonical_planner_suggestion_v1(p_race_preparation_id uuid, p_stage_id uuid, p_planner_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prep public.race_preparations%rowtype;
  v_stage_plan public.race_stage_plans%rowtype;

  v_planner jsonb := '{}'::jsonb;
  v_planner_score numeric := 1;
  v_planner_quality text := 'basic';
  v_accuracy_factor numeric := 0.65;

  v_profile jsonb := '{}'::jsonb;
  v_stage_name text := null;
  v_profile_type text := '';
  v_terrain_type text := '';
  v_finish_type text := '';
  v_stage_format text := '';
  v_distance_km numeric := 0;
  v_elevation_gain_m numeric := 0;
  v_sprint_count integer := 0;
  v_kom_count integer := 0;
  v_bad_weather boolean := false;
  v_stage_kind text := 'balanced';

  v_phase_ranges jsonb := '[]'::jsonb;
  v_team_plan text := 'balanced';

  v_roles_json jsonb := '{}'::jsonb;
  v_equipment_json jsonb := '{}'::jsonb;
  v_supplies_json jsonb := '{}'::jsonb;
  v_individual_tactics_json jsonb := '{}'::jsonb;
  v_team_tactic_json jsonb := '{}'::jsonb;
  v_explanations jsonb := '[]'::jsonb;

  v_rider_count integer := 0;
begin
  select *
  into v_prep
  from public.race_preparations rp
  where rp.id = p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message', 'Race preparation was not found.'
    );
  end if;

  select *
  into v_stage_plan
  from public.race_stage_plans rsp
  where rsp.race_preparation_id = p_race_preparation_id
    and rsp.stage_id = p_stage_id
  order by rsp.created_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'stage_plan_not_found',
      'message', 'Stage plan row was not found for this race preparation and stage.'
    );
  end if;

  v_planner :=
    coalesce(
      p_planner_json,
      '{}'::jsonb
    );

  if jsonb_typeof(v_planner) <> 'object' then
    return jsonb_build_object(
      'status', 'error',
      'code', 'planner_context_invalid',
      'message',
        'The canonical planner context must be a JSON object.'
    );
  end if;

  if coalesce(
       nullif(
         v_planner->>'role_type',
         ''
       ),
       ''
     ) = '' then
    return jsonb_build_object(
      'status', 'error',
      'code', 'planner_role_required',
      'message',
        'The canonical planner context must include role_type.'
    );
  end if;

  v_planner_score :=
    greatest(
      0,
      least(
        100,
        public.jsonb_number_any_v1(
          v_planner,
          array[
            'effective_quality_score',
            'race_readiness_score',
            'quality_score',
            'overall',
            'overall_rating',
            'rating'
          ],
          50
        )
      )
    );

  v_planner_quality :=
    coalesce(
      nullif(
        v_planner->>'quality_tier',
        ''
      ),
      nullif(
        v_planner->>'quality',
        ''
      ),
      'planner'
    );

  v_accuracy_factor :=
    greatest(
      0,
      least(
        1,
        v_planner_score / 100.0
      )
    );

  v_profile := coalesce(v_stage_plan.stage_profile_snapshot_json, '{}'::jsonb);
  v_stage_name := nullif(v_profile ->> 'name', '');
  v_profile_type := lower(coalesce(v_profile ->> 'profile_type', ''));
  v_terrain_type := lower(coalesce(v_profile ->> 'terrain_type', ''));
  v_finish_type := lower(coalesce(v_profile ->> 'finish_type', ''));
  v_stage_format := lower(coalesce(v_profile ->> 'stage_format', ''));
  v_distance_km := public.jsonb_number_any_v1(v_profile, array['distance_km'], 0);
  v_elevation_gain_m := public.jsonb_number_any_v1(v_profile, array['elevation_gain_m'], 0);

  v_sprint_count :=
    case
      when jsonb_typeof(v_profile -> 'intermediate_sprints_json') = 'array'
      then jsonb_array_length(v_profile -> 'intermediate_sprints_json')
      else 0
    end;

  v_kom_count :=
    case
      when jsonb_typeof(v_profile -> 'mountain_climbs_json') = 'array'
      then jsonb_array_length(v_profile -> 'mountain_climbs_json')
      else 0
    end;

  v_bad_weather :=
    lower(coalesce(v_profile #>> '{weather_snapshot,condition}', '')) in (
      'rain',
      'heavy_rain',
      'storm',
      'snow',
      'wind_rain'
    );

  v_stage_kind :=
    case
      when v_stage_format in ('prologue', 'individual_time_trial', 'team_time_trial')
        then 'time_trial'
      when v_profile_type in ('climber', 'mountain') or v_terrain_type = 'mountain' or v_elevation_gain_m >= 1500
        then 'mountain'
      when v_profile_type in ('puncheur', 'hilly') or v_terrain_type = 'hilly' or v_kom_count >= 2
        then 'hilly'
      when v_profile_type in ('sprinter', 'flat') or v_finish_type = 'flat_finish' or v_sprint_count >= 2
        then 'sprint'
      else 'balanced'
    end;

  v_team_plan :=
    case
      when v_stage_kind = 'time_trial' then 'balanced'
      when v_stage_kind = 'mountain' then 'climber_support'
      when v_stage_kind = 'hilly' then 'breakaway'
      when v_stage_kind = 'sprint' then 'sprint_control'
      else 'balanced'
    end;

  if v_distance_km > 0 then
    v_phase_ranges := jsonb_build_array(
      jsonb_build_object(
        'key', 'phase_1',
        'number', 1,
        'label', 'Phase 1',
        'fromKm', 0,
        'toKm', round((v_distance_km * 0.25)::numeric, 1),
        'rangeLabel', '0–' || round((v_distance_km * 0.25)::numeric, 1)::text || ' km'
      ),
      jsonb_build_object(
        'key', 'phase_2',
        'number', 2,
        'label', 'Phase 2',
        'fromKm', round((v_distance_km * 0.25)::numeric, 1),
        'toKm', round((v_distance_km * 0.50)::numeric, 1),
        'rangeLabel', round((v_distance_km * 0.25)::numeric, 1)::text || '–' || round((v_distance_km * 0.50)::numeric, 1)::text || ' km'
      ),
      jsonb_build_object(
        'key', 'phase_3',
        'number', 3,
        'label', 'Phase 3',
        'fromKm', round((v_distance_km * 0.50)::numeric, 1),
        'toKm', round((v_distance_km * 0.75)::numeric, 1),
        'rangeLabel', round((v_distance_km * 0.50)::numeric, 1)::text || '–' || round((v_distance_km * 0.75)::numeric, 1)::text || ' km'
      ),
      jsonb_build_object(
        'key', 'phase_4',
        'number', 4,
        'label', 'Phase 4',
        'fromKm', round((v_distance_km * 0.75)::numeric, 1),
        'toKm', round(v_distance_km::numeric, 1),
        'rangeLabel', round((v_distance_km * 0.75)::numeric, 1)::text || '–' || round(v_distance_km::numeric, 1)::text || ' km'
      )
    );
  else
    v_phase_ranges := jsonb_build_array(
      jsonb_build_object('key', 'phase_1', 'number', 1, 'label', 'Phase 1', 'fromKm', 0, 'toKm', 25, 'rangeLabel', '0–25%'),
      jsonb_build_object('key', 'phase_2', 'number', 2, 'label', 'Phase 2', 'fromKm', 25, 'toKm', 50, 'rangeLabel', '25–50%'),
      jsonb_build_object('key', 'phase_3', 'number', 3, 'label', 'Phase 3', 'fromKm', 50, 'toKm', 75, 'rangeLabel', '50–75%'),
      jsonb_build_object('key', 'phase_4', 'number', 4, 'label', 'Phase 4', 'fromKm', 75, 'toKm', 100, 'rangeLabel', '75–100%')
    );
  end if;

  with rider_source as (
    select
      rpr.rider_id,
      rpr.start_number,
      rpr.race_role,
      rpr.default_equipment_setup_id,
      coalesce(rpr.rider_snapshot_json, '{}'::jsonb) as rider_snapshot,
      coalesce(rpr.bonus_snapshot_json, '{}'::jsonb) as bonus_snapshot
    from public.race_preparation_riders rpr
    where rpr.race_preparation_id = p_race_preparation_id
  ),
  scored as (
    select
      rs.*,

      coalesce(
        nullif(rs.rider_snapshot ->> 'full_name', ''),
        nullif(trim(coalesce(rs.rider_snapshot ->> 'first_name', '') || ' ' || coalesce(rs.rider_snapshot ->> 'last_name', '')), ''),
        rs.rider_id::text
      ) as rider_name,

      public.jsonb_number_any_v1(rs.rider_snapshot, array['sprint', 'sprint_skill'], 50) as sprint_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['climbing', 'mountain', 'climb', 'climbing_skill'], 50) as climb_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['flat', 'flat_skill'], 50) as flat_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['hills', 'hill', 'hilly'], 50) as hill_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['time_trial', 'timetrial', 'tt'], 50) as tt_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['endurance', 'stamina'], 50) as endurance_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['teamwork', 'team_work'], 50) as teamwork_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['race_iq', 'race_intelligence', 'intelligence'], 50) as race_iq_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['recovery'], 50) as recovery_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['fatigue'], 0) as fatigue_score,
      public.jsonb_number_any_v1(rs.rider_snapshot, array['race_sharpness', 'race_sharpness_percent', 'sharpness'], 50) as sharpness_score
    from rider_source rs
  ),
  ranked as (
    select
      s.*,
      (
        s.sprint_score * 0.45 +
        s.flat_score * 0.20 +
        s.endurance_score * 0.15 +
        s.race_iq_score * 0.10 +
        s.teamwork_score * 0.10 -
        s.fatigue_score * 0.08 +
        s.sharpness_score * 0.05
      ) as sprint_rank_score,

      (
        s.climb_score * 0.38 +
        s.hill_score * 0.18 +
        s.endurance_score * 0.18 +
        s.recovery_score * 0.10 +
        s.race_iq_score * 0.10 -
        s.fatigue_score * 0.08 +
        s.sharpness_score * 0.05
      ) as climb_rank_score,

      (
        s.climb_score * 0.25 +
        s.endurance_score * 0.25 +
        s.recovery_score * 0.15 +
        s.race_iq_score * 0.15 +
        s.flat_score * 0.10 +
        s.hill_score * 0.10 -
        s.fatigue_score * 0.08 +
        s.sharpness_score * 0.05
      ) as gc_rank_score,

      (
        s.flat_score * 0.30 +
        s.endurance_score * 0.25 +
        s.teamwork_score * 0.20 +
        s.race_iq_score * 0.10 +
        s.hill_score * 0.10 -
        s.fatigue_score * 0.05
      ) as helper_rank_score,

      (
        s.tt_score * 0.40 +
        s.flat_score * 0.20 +
        s.endurance_score * 0.20 +
        s.teamwork_score * 0.10 +
        s.race_iq_score * 0.10 -
        s.fatigue_score * 0.07
      ) as tt_rank_score
    from scored s
  ),
  numbered as (
    select
      r.*,
      row_number() over (order by r.sprint_rank_score desc, r.start_number nulls last) as sprint_rank,
      row_number() over (order by r.climb_rank_score desc, r.start_number nulls last) as climb_rank,
      row_number() over (order by r.gc_rank_score desc, r.start_number nulls last) as gc_rank,
      row_number() over (order by r.helper_rank_score desc, r.start_number nulls last) as helper_rank,
      row_number() over (order by r.tt_rank_score desc, r.start_number nulls last) as tt_rank
    from ranked r
  ),
  assigned as (
    select
      n.*,
      case
        when v_stage_kind = 'time_trial'
          then 'free_role'

        when v_stage_kind = 'sprint' and n.sprint_rank = 1
          then 'sprinter'
        when v_stage_kind = 'sprint' and n.sprint_rank = 2
          then 'lead_out_rider'
        when v_stage_kind = 'sprint' and n.sprint_rank = 3
          then 'sprint_train_rider'
        when v_stage_kind = 'sprint' and n.gc_rank = 1
          then 'team_leader_gc'
        when v_stage_kind = 'sprint' and n.helper_rank <= 5
          then 'helper_domestique'

        when v_stage_kind = 'mountain' and n.gc_rank = 1
          then 'team_leader_gc'
        when v_stage_kind = 'mountain' and n.climb_rank = 1
          then 'climber'
        when v_stage_kind = 'mountain' and n.climb_rank <= 3
          then 'mountain_domestique'
        when v_stage_kind = 'mountain' and n.helper_rank <= 5
          then 'helper_domestique'

        when v_stage_kind = 'hilly' and n.gc_rank = 1
          then 'team_leader_gc'
        when v_stage_kind = 'hilly' and n.climb_rank = 1
          then 'climber'
        when v_stage_kind = 'hilly' and n.helper_rank = 1
          then 'breakaway_rider'
        when v_stage_kind = 'hilly' and n.helper_rank <= 3
          then 'rouleur'
        when v_stage_kind = 'hilly' and n.sprint_rank = 1
          then 'sprinter'

        when n.gc_rank = 1
          then 'team_leader_gc'
        when n.sprint_rank = 1
          then 'sprinter'
        when n.climb_rank = 1
          then 'climber'
        when n.helper_rank <= 4
          then 'helper_domestique'
        else 'free_role'
      end as suggested_role
    from numbered n
  ),
  commands as (
    select
      a.*,
      case
        when a.suggested_role = 'team_leader_gc' and v_stage_kind in ('mountain', 'hilly')
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'avoid_risks'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'stay_near_front'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'climb_hard'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'follow_team_plan')
          )

        when a.suggested_role = 'team_leader_gc'
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'avoid_risks'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'avoid_risks'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'stay_near_front'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'follow_team_plan')
          )

        when a.suggested_role = 'sprinter'
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'conserve_energy'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'stay_near_front'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'sprint')
          )

        when a.suggested_role in ('lead_out_rider', 'sprint_train_rider')
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'conserve_energy'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'stay_near_front'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'lead_out')
          )

        when a.suggested_role in ('climber', 'mountain_domestique')
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'conserve_energy'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'climb_hard'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'follow_team_plan')
          )

        when a.suggested_role = 'breakaway_rider'
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'attack'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'join_breakaway'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'follow_team_plan')
          )

        when a.suggested_role in ('helper_domestique', 'rouleur')
          then jsonb_build_object(
            'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'protect_leader'),
            'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'protect_leader'),
            'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'control_tempo'),
            'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'protect_leader')
          )

        else jsonb_build_object(
          'phase_1', jsonb_build_object('label', 'Phase 1', 'from_km', (v_phase_ranges -> 0 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 0 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
          'phase_2', jsonb_build_object('label', 'Phase 2', 'from_km', (v_phase_ranges -> 1 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 1 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
          'phase_3', jsonb_build_object('label', 'Phase 3', 'from_km', (v_phase_ranges -> 2 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 2 ->> 'toKm')::numeric, 'command', 'follow_team_plan'),
          'phase_4', jsonb_build_object('label', 'Phase 4', 'from_km', (v_phase_ranges -> 3 ->> 'fromKm')::numeric, 'to_km', (v_phase_ranges -> 3 ->> 'toKm')::numeric, 'command', 'follow_team_plan')
        )
      end as suggested_commands,

      jsonb_build_object(
        'gels', case when v_stage_kind = 'time_trial' then 0 when v_distance_km >= 130 then 3 else 2 end,
        'bidons', case when v_stage_kind = 'time_trial' then 0 when v_distance_km >= 130 or v_bad_weather = false then 3 else 2 end,
        'nutrition_packs', case when v_stage_kind = 'time_trial' then 0 when v_distance_km >= 90 then 1 else 0 end,
        'rain_jacket', case when v_stage_kind = 'time_trial' then false else v_bad_weather end,
        'race_jersey_complete', case when v_stage_kind = 'time_trial' then false else true end
      ) as suggested_supplies
    from assigned a
  )
  select
    coalesce(jsonb_object_agg(c.rider_id::text, c.suggested_role), '{}'::jsonb),
    coalesce(
      jsonb_object_agg(c.rider_id::text, c.default_equipment_setup_id::text)
        filter (where c.default_equipment_setup_id is not null),
      '{}'::jsonb
    ),
    coalesce(jsonb_object_agg(c.rider_id::text, c.suggested_supplies), '{}'::jsonb),
    coalesce(jsonb_object_agg(c.rider_id::text, c.suggested_commands), '{}'::jsonb),
    count(*)::integer
  into
    v_roles_json,
    v_equipment_json,
    v_supplies_json,
    v_individual_tactics_json,
    v_rider_count
  from commands c;

  if v_rider_count = 0 then
    return jsonb_build_object(
      'status', 'error',
      'code', 'no_riders_found',
      'message', 'No riders were found in the Race Plan for this race preparation.'
    );
  end if;

  v_team_tactic_json := jsonb_build_object(
    'plan', v_team_plan,
    'notes', 'Prepared by the selected tactical planner. Review and save to apply it.',
    'phase_count', 4,
    'stage_phase_ranges', v_phase_ranges,
    'is_time_trial_stage', v_stage_kind = 'time_trial',
    'is_team_time_trial_stage', v_stage_format = 'team_time_trial',
    'engine_model_version', 'canonical_stage_planner_v1',
    'suggestion_source', 'generate_stage_plan_canonical_planner_suggestion_v1',
    'individual_tactics_by_rider', v_individual_tactics_json
  );

  v_explanations := jsonb_build_array(
    'Stage profile detected as ' || v_stage_kind || '.',
    'Team tactic suggested as ' || v_team_plan || '.',
    'Rider roles were selected from Race Plan rider snapshots, weighted by stage profile, rider skills, fatigue and sharpness where available.',
    'Planner quality is ' || v_planner_quality || ' with effective score ' || round(v_planner_score, 1)::text || '.',
    'This suggestion is not saved automatically. Review it and save it through the canonical Stage Plan workflow.'
  );

  return jsonb_build_object(
    'status', 'ok',
    'version', 'v25_canonical_stage_planner_v1',
    'safe_note', 'Canonical planner suggestion only. No database rows were changed.',
    'race_preparation_id', p_race_preparation_id,
    'race_id', v_stage_plan.race_id,
    'stage_id', p_stage_id,
    'stage_number', v_stage_plan.stage_number,
    'stage_name', v_stage_name,
    'stage_kind', v_stage_kind,
    'profile', jsonb_build_object(
      'profile_type', v_profile_type,
      'terrain_type', v_terrain_type,
      'finish_type', v_finish_type,
      'stage_format', v_stage_format,
      'distance_km', v_distance_km,
      'elevation_gain_m', v_elevation_gain_m,
      'sprint_count', v_sprint_count,
      'kom_count', v_kom_count,
      'bad_weather', v_bad_weather
    ),
    'planner',
      v_planner
      || jsonb_build_object(
           'effective_quality_score',
             v_planner_score,
           'quality',
             v_planner_quality,
           'accuracy_factor',
             v_accuracy_factor,
           'canonical_planner_source',
             'generate_stage_plan_canonical_planner_suggestion_v1'
         ),
    'suggestion', jsonb_build_object(
      'team_tactic_json', v_team_tactic_json,
      'rider_roles_json', v_roles_json,
      'rider_equipment_json', v_equipment_json,
      'rider_supplies_json', v_supplies_json,
      'rider_individual_tactics_json', v_individual_tactics_json
    ),
    'explanation', v_explanations
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_race_preparation_tactical_planner_v1(p_race_preparation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
begin
  select
    preparation.id,
    preparation.race_id,
    preparation.club_id as owner_club_id,
    preparation.participating_club_id,

    participating_club.name
      as participating_club_name,

    participating_club.club_type,
    participating_club.parent_club_id,

    sport_director.staff_id
      as sport_director_staff_id,

    sport_director_staff.staff_name
      as sport_director_name,

    automation.planner_staff_id
      as u23_head_coach_staff_id,

    u23_staff.staff_name
      as u23_head_coach_name,

    coalesce(
      automation.is_enabled,
      false
    ) as u23_automation_enabled
  into v_row
  from public.race_preparations preparation

  join public.clubs participating_club
    on participating_club.id =
      preparation.participating_club_id

  left join public.race_preparation_staff
    sport_director
    on sport_director.race_preparation_id =
        preparation.id
   and sport_director.role_type =
        'sport_director'

  left join public.club_staff
    sport_director_staff
    on sport_director_staff.id =
      sport_director.staff_id

  left join
    public.race_preparation_stage_plan_automation
      automation
    on automation.race_preparation_id =
      preparation.id

  left join public.club_staff u23_staff
    on u23_staff.id =
      automation.planner_staff_id

  where preparation.id =
    p_race_preparation_id;

  if not found then
    return jsonb_build_object(
      'status', 'error',
      'code', 'race_preparation_not_found',
      'message',
        'Race preparation was not found.'
    );
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'version',
      'race_preparation_tactical_planner_v1',

    'race_preparation_id',
      v_row.id,

    'race_id',
      v_row.race_id,

    'owner_club_id',
      v_row.owner_club_id,

    'participating_club_id',
      v_row.participating_club_id,

    'participating_club_name',
      v_row.participating_club_name,

    'participating_club_type',
      v_row.club_type,

    'is_owner_developing_team',
      v_row.club_type = 'developing'
      and v_row.parent_club_id =
        v_row.owner_club_id,

    'planner_choice',
      case
        when v_row.sport_director_staff_id
               is not null
         and v_row.u23_head_coach_staff_id
               is not null
         and v_row.u23_automation_enabled
          then 'conflict'

        when v_row.sport_director_staff_id
               is not null
          then 'sport_director'

        when v_row.u23_head_coach_staff_id
               is not null
         and v_row.u23_automation_enabled
          then 'u23_head_coach'

        else 'none'
      end,

    'sport_director',
      case
        when v_row.sport_director_staff_id
             is null
          then null
        else jsonb_build_object(
          'staff_id',
            v_row.sport_director_staff_id,
          'staff_name',
            v_row.sport_director_name
        )
      end,

    'u23_head_coach',
      case
        when v_row.u23_head_coach_staff_id
             is null
          then null
        else jsonb_build_object(
          'staff_id',
            v_row.u23_head_coach_staff_id,
          'staff_name',
            v_row.u23_head_coach_name,
          'automation_enabled',
            v_row.u23_automation_enabled
        )
      end,

    'both_allowed',
      false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_sport_director_selection_clears_u23_planner_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep record;
begin
  if new.role_type <> 'sport_director' then
    return new;
  end if;

  select
    preparation.id,
    preparation.club_id as owner_club_id,
    preparation.participating_club_id,
    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations preparation
  join public.clubs participating_club
    on participating_club.id =
      preparation.participating_club_id
  where preparation.id =
    new.race_preparation_id;

  if not found
     or v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return new;
  end if;

  update
    public.race_preparation_stage_plan_automation
  set
    is_enabled =
      false,

    planner_staff_id =
      null,

    last_generation_status =
      'disabled_by_sport_director_selection',

    last_generation_summary =
      jsonb_build_object(
        'status', 'disabled',
        'code',
          'sport_director_selected',
        'selected_planner',
          'sport_director',
        'sport_director_staff_id',
          new.staff_id,
        'changed_at',
          clock_timestamp()
      ),

    metadata =
      coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
           'planner_exclusivity_installed',
             true,

           'selected_planner',
             'sport_director',

           'u23_selection_cleared',
             true,

           'sport_director_staff_id',
             new.staff_id,

           'changed_at',
             clock_timestamp()
         ),

    updated_at =
      now()

  where race_preparation_id =
    new.race_preparation_id;

  update public.race_preparations preparation
  set
    staff_count =
      (
        select count(*)::integer
        from public.race_preparation_staff
          race_staff
        where race_staff.race_preparation_id =
          preparation.id
      ),

    metadata =
      coalesce(
        preparation.metadata,
        '{}'::jsonb
      )
      || jsonb_build_object(
           'planner_exclusivity_v1',
             jsonb_build_object(
               'selected_planner',
                 'sport_director',

               'sport_director_staff_id',
                 new.staff_id,

               'u23_selection_cleared',
                 true,

               'changed_at',
                 clock_timestamp()
             )
         ),

    updated_at =
      now()

  where preparation.id =
    new.race_preparation_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_u23_planner_selection_clears_sport_director_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prep record;
  v_removed integer := 0;
begin
  if coalesce(new.is_enabled, false) = false
     or new.planner_staff_id is null then
    return new;
  end if;

  select
    preparation.id,
    preparation.club_id as owner_club_id,
    preparation.participating_club_id,
    participating_club.club_type,
    participating_club.parent_club_id
  into v_prep
  from public.race_preparations preparation
  join public.clubs participating_club
    on participating_club.id =
      preparation.participating_club_id
  where preparation.id =
    new.race_preparation_id;

  if not found
     or v_prep.club_type <> 'developing'
     or v_prep.parent_club_id <>
       v_prep.owner_club_id then
    return new;
  end if;

  delete from public.race_preparation_staff
    race_staff
  where race_staff.race_preparation_id =
      new.race_preparation_id
    and race_staff.role_type =
      'sport_director';

  get diagnostics
    v_removed = row_count;

  if v_removed > 0 then
    update public.race_preparations preparation
    set
      staff_count =
        (
          select count(*)::integer
          from public.race_preparation_staff
            race_staff
          where race_staff.race_preparation_id =
            preparation.id
        ),

      metadata =
        coalesce(
          preparation.metadata,
          '{}'::jsonb
        )
        || jsonb_build_object(
             'planner_exclusivity_v1',
               jsonb_build_object(
                 'selected_planner',
                   'u23_head_coach',

                 'u23_head_coach_staff_id',
                   new.planner_staff_id,

                 'removed_sport_director_assignment_count',
                   v_removed,

                 'changed_at',
                   clock_timestamp()
               )
           ),

      updated_at =
        now()

    where preparation.id =
      new.race_preparation_id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_u23_managed_stage_plan_read_only_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_write_source text :=
    current_setting(
      'app.u23_stage_plan_write_source',
      true
    );
begin
  if v_write_source = 'u23_head_coach' then
    return new;
  end if;

  if exists (
    select 1
    from public.race_preparation_stage_plan_automation automation
    where automation.race_preparation_id =
        new.race_preparation_id
      and automation.is_enabled = true
      and automation.planner_role =
        'u23_head_coach'
      and automation.planner_staff_id
        is not null
  ) then
    raise exception using
      errcode = 'P0001',
      message =
        'This Stage Plan is managed by the U23 Head Coach and is view-only. Switch the Tactical Planner to Sport Director in the Race Plan before making manual changes.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_activate_incident_forward_only_cutover_v1(p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_weather_rows integer := 0;
  v_equipment_rows integer := 0;
  v_group_rows integer := 0;
  v_health_rows integer := 0;
  v_gap_rows integer := 0;
  v_official_rows integer := 0;
  v_activation_time timestamptz := clock_timestamp();
begin
  if p_confirmation is distinct from
       'ACTIVATE_FORWARD_ONLY_INCIDENT_CUTOVER' then
    raise exception
      'Forward-only incident cutover activation refused: exact confirmation token required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'race_engine_incident_forward_only_cutover_v1',
      0
    )
  );

  if md5(pg_get_functiondef(
       'public.race_engine_write_incidents_v1(uuid)'::regprocedure::oid
     )) <> '90976b47e3572e5706a1141b24c3cd40'
     or (
       select md5(p.prosrc)
       from pg_proc p
       where p.oid =
         'public.race_engine_write_incidents_v1(uuid)'::regprocedure::oid
     ) <> '86d584f8c0c97434e9409a9122c1345e'
     or md5(pg_get_functiondef(
       'public.race_engine_write_incidents_multichannel_v1(uuid,boolean,text)'::regprocedure::oid
     )) <> '2934c2be703cabb23700c041790362f9'
     or (
       select md5(p.prosrc)
       from pg_proc p
       where p.oid =
         'public.race_engine_write_incidents_multichannel_v1(uuid,boolean,text)'::regprocedure::oid
     ) <> '3eb3728d34444f78dc61d67b33f62f6b'
     or md5(pg_get_functiondef(
       'public.race_engine_build_incident_official_activation_plan_v1(uuid)'::regprocedure::oid
     )) <> '47f57fca630ecf7835a3e3fe29bb444e'
     or (
       select md5(p.prosrc)
       from pg_proc p
       where p.oid =
         'public.race_engine_build_incident_official_activation_plan_v1(uuid)'::regprocedure::oid
     ) <> 'e628b26d982324c567df9059f794db1c'
     or md5(pg_get_functiondef(
       'public.run_race_stage_simulation_v1(uuid)'::regprocedure::oid
     )) <> '60467d03157178c6fd82c74653a79e93'
     or md5(pg_get_functiondef(
       'public.run_race_stage_road_race_v1(uuid)'::regprocedure::oid
     )) <> '0de7f247dc3e01645a3bf4fa39bebd83'
     or md5(pg_get_functiondef(
       'public.race_engine_forward_only_scheduler_tick_v1()'::regprocedure::oid
     )) <> 'ebbdb84ec17367c725642ca881a03d6e' then
    raise exception
      'Forward-only incident cutover activation refused: frozen execution-path drift.';
  end if;

  perform 1
  from public.race_engine_incident_official_activation_contract_v1 c
  where c.contract_key = 'incident_official_activation'
  for update;

  perform 1
  from public.race_engine_incident_gap_resolution_contract_v1 c
  where c.contract_key =
    'incident_gap_resolution_disabled_specification'
  for update;

  if not exists (
    select 1
    from public.race_engine_incident_official_activation_contract_v1 c
    where c.contract_key = 'incident_official_activation'
      and c.weather_contract_approved
      and c.equipment_contract_approved
      and c.group_identity_contract_approved
      and c.health_mapping_contract_approved
      and not c.plan_builder_enabled
      and not c.replacement_writer_enabled
      and not c.runtime_canary_enabled
      and not c.execution_enabled
      and not c.production_execution_enabled
      and not c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  ) then
    raise exception
      'Forward-only incident cutover activation refused: official contract is not in the fully disabled baseline.';
  end if;

  if not exists (
    select 1
    from public.race_engine_incident_gap_resolution_contract_v1 c
    where c.contract_key =
        'incident_gap_resolution_disabled_specification'
      and c.weather_contract_approved
      and c.equipment_contract_approved
      and c.group_contract_approved
      and c.health_contract_approved
      and not c.candidate_functions_enabled
      and not c.runtime_canary_enabled
      and not c.execution_enabled
      and not c.production_execution_enabled
      and not c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  ) then
    raise exception
      'Forward-only incident cutover activation refused: gap contract is not in the fully disabled baseline.';
  end if;

  if exists (
    select 1
    from public.race_engine_incident_official_plan_rows_v1 p
    join public.race_stage_simulation_runs r
      on r.id = p.simulation_run_id
    where r.status = 'completed'
  ) then
    raise exception
      'Forward-only incident cutover activation refused: completed historical simulations contain official plan rows.';
  end if;

  if (
    select count(*)
    from public.race_engine_incident_weather_probability_rule_v1
    where approved and not active
  ) <> 6
  or (
    select count(*)
    from public.race_engine_incident_equipment_condition_rule_v1
    where approved and not active
  ) <> 5
  or (
    select count(*)
    from public.race_engine_group_identity_selection_rule_v1
    where approved and not active
  ) <> 1
  or (
    select count(*)
    from public.race_engine_incident_health_mapping_v1
    where approved and not active
  ) <> 12 then
    raise exception
      'Forward-only incident cutover activation refused: approved inactive rule cardinality drift.';
  end if;

  update public.race_engine_incident_weather_probability_rule_v1
  set active = true
  where approved
    and not active;

  get diagnostics v_weather_rows = row_count;

  update public.race_engine_incident_equipment_condition_rule_v1
  set active = true
  where approved
    and not active;

  get diagnostics v_equipment_rows = row_count;

  update public.race_engine_group_identity_selection_rule_v1
  set active = true
  where approved
    and not active;

  get diagnostics v_group_rows = row_count;

  update public.race_engine_incident_health_mapping_v1
  set active = true
  where approved
    and not active;

  get diagnostics v_health_rows = row_count;

  update public.race_engine_incident_gap_resolution_contract_v1
  set
    candidate_functions_enabled = true,
    runtime_canary_enabled = false,
    execution_enabled = false,
    production_execution_enabled = false,
    runner_integration_enabled = false,
    historical_rewrite_enabled = false
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  get diagnostics v_gap_rows = row_count;

  update public.race_engine_incident_official_activation_contract_v1
  set
    plan_builder_enabled = true,
    replacement_writer_enabled = true,
    runtime_canary_enabled = false,
    execution_enabled = true,
    production_execution_enabled = true,
    runner_integration_enabled = true,
    historical_rewrite_enabled = false
  where contract_key = 'incident_official_activation';

  get diagnostics v_official_rows = row_count;

  if v_weather_rows <> 6
     or v_equipment_rows <> 5
     or v_group_rows <> 1
     or v_health_rows <> 12
     or v_gap_rows <> 1
     or v_official_rows <> 1 then
    raise exception
      'Forward-only incident cutover activation failed cardinality check: weather %, equipment %, group %, health %, gap %, official %.',
      v_weather_rows,
      v_equipment_rows,
      v_group_rows,
      v_health_rows,
      v_gap_rows,
      v_official_rows;
  end if;

  if not exists (
    select 1
    from public.race_engine_incident_official_activation_contract_v1 c
    where c.contract_key = 'incident_official_activation'
      and c.plan_builder_enabled
      and c.replacement_writer_enabled
      and not c.runtime_canary_enabled
      and c.execution_enabled
      and c.production_execution_enabled
      and c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  )
  or not exists (
    select 1
    from public.race_engine_incident_gap_resolution_contract_v1 c
    where c.contract_key =
        'incident_gap_resolution_disabled_specification'
      and c.candidate_functions_enabled
      and not c.runtime_canary_enabled
      and not c.execution_enabled
      and not c.production_execution_enabled
      and not c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  ) then
    raise exception
      'Forward-only incident cutover activation failed final contract verification.';
  end if;

  return jsonb_build_object(
    'status',
      'forward_only_incident_cutover_activated',
    'activated_at', v_activation_time,
    'historical_rewrite_enabled', false,
    'historical_backfill_performed', false,
    'engine_function_calls', 0,
    'activated_rule_rows', jsonb_build_object(
      'weather', v_weather_rows,
      'equipment', v_equipment_rows,
      'group_identity', v_group_rows,
      'health_mapping', v_health_rows,
      'total',
        v_weather_rows
        + v_equipment_rows
        + v_group_rows
        + v_health_rows
    ),
    'official_activation', jsonb_build_object(
      'plan_builder_enabled', true,
      'replacement_writer_enabled', true,
      'runtime_canary_enabled', false,
      'execution_enabled', true,
      'production_execution_enabled', true,
      'runner_integration_enabled', true,
      'historical_rewrite_enabled', false
    ),
    'gap_activation', jsonb_build_object(
      'candidate_functions_enabled', true,
      'runtime_canary_enabled', false,
      'execution_enabled', false,
      'production_execution_enabled', false,
      'runner_integration_enabled', false,
      'historical_rewrite_enabled', false
    ),
    'rollback_function',
      'public.race_engine_rollback_incident_forward_only_cutover_v1(text)'
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_rollback_incident_forward_only_cutover_v1(p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_weather_rows integer := 0;
  v_equipment_rows integer := 0;
  v_group_rows integer := 0;
  v_health_rows integer := 0;
  v_gap_rows integer := 0;
  v_official_rows integer := 0;
  v_rollback_time timestamptz := clock_timestamp();
begin
  if p_confirmation is distinct from
       'ROLLBACK_FORWARD_ONLY_INCIDENT_CUTOVER' then
    raise exception
      'Forward-only incident cutover rollback refused: exact confirmation token required.';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      'race_engine_incident_forward_only_cutover_v1',
      0
    )
  );

  update public.race_engine_incident_official_activation_contract_v1
  set
    plan_builder_enabled = false,
    replacement_writer_enabled = false,
    runtime_canary_enabled = false,
    execution_enabled = false,
    production_execution_enabled = false,
    runner_integration_enabled = false,
    historical_rewrite_enabled = false
  where contract_key = 'incident_official_activation';

  get diagnostics v_official_rows = row_count;

  update public.race_engine_incident_gap_resolution_contract_v1
  set
    candidate_functions_enabled = false,
    runtime_canary_enabled = false,
    execution_enabled = false,
    production_execution_enabled = false,
    runner_integration_enabled = false,
    historical_rewrite_enabled = false
  where contract_key =
    'incident_gap_resolution_disabled_specification';

  get diagnostics v_gap_rows = row_count;

  update public.race_engine_incident_weather_probability_rule_v1
  set active = false
  where approved
    and active;

  get diagnostics v_weather_rows = row_count;

  update public.race_engine_incident_equipment_condition_rule_v1
  set active = false
  where approved
    and active;

  get diagnostics v_equipment_rows = row_count;

  update public.race_engine_group_identity_selection_rule_v1
  set active = false
  where approved
    and active;

  get diagnostics v_group_rows = row_count;

  update public.race_engine_incident_health_mapping_v1
  set active = false
  where approved
    and active;

  get diagnostics v_health_rows = row_count;

  if v_gap_rows <> 1 or v_official_rows <> 1 then
    raise exception
      'Forward-only incident cutover rollback failed: activation contract row missing.';
  end if;

  if not exists (
    select 1
    from public.race_engine_incident_official_activation_contract_v1 c
    where c.contract_key = 'incident_official_activation'
      and not c.plan_builder_enabled
      and not c.replacement_writer_enabled
      and not c.runtime_canary_enabled
      and not c.execution_enabled
      and not c.production_execution_enabled
      and not c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  )
  or not exists (
    select 1
    from public.race_engine_incident_gap_resolution_contract_v1 c
    where c.contract_key =
        'incident_gap_resolution_disabled_specification'
      and not c.candidate_functions_enabled
      and not c.runtime_canary_enabled
      and not c.execution_enabled
      and not c.production_execution_enabled
      and not c.runner_integration_enabled
      and not c.historical_rewrite_enabled
  )
  or exists (
    select 1
    from public.race_engine_incident_weather_probability_rule_v1
    where approved and active
  )
  or exists (
    select 1
    from public.race_engine_incident_equipment_condition_rule_v1
    where approved and active
  )
  or exists (
    select 1
    from public.race_engine_group_identity_selection_rule_v1
    where approved and active
  )
  or exists (
    select 1
    from public.race_engine_incident_health_mapping_v1
    where approved and active
  ) then
    raise exception
      'Forward-only incident cutover rollback failed final disabled-state verification.';
  end if;

  return jsonb_build_object(
    'status',
      'forward_only_incident_cutover_rolled_back',
    'rolled_back_at', v_rollback_time,
    'engine_function_calls', 0,
    'historical_rewrite_enabled', false,
    'deactivated_rule_rows', jsonb_build_object(
      'weather', v_weather_rows,
      'equipment', v_equipment_rows,
      'group_identity', v_group_rows,
      'health_mapping', v_health_rows,
      'total',
        v_weather_rows
        + v_equipment_rows
        + v_group_rows
        + v_health_rows
    ),
    'production_execution_enabled', false,
    'runner_integration_enabled', false,
    'replacement_writer_enabled', false
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_stage_plan_lock_context_v1(p_race_stage_plan_id uuid, p_effective_game_ts timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan_json jsonb;
  v_stage_json jsonb;
  v_preparation_json jsonb;

  v_effective_game_ts timestamptz;
  v_stage_start_text text;
  v_stage_start_game_ts timestamptz;
  v_lock_game_ts timestamptz;

  v_stage_date date;
  v_start_hour integer;
  v_start_minute integer;
begin
  if p_race_stage_plan_id is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'race_stage_plan_id_required'
    );
  end if;

  select
    to_jsonb(rsp),
    to_jsonb(rs),
    to_jsonb(rp)
  into
    v_plan_json,
    v_stage_json,
    v_preparation_json
  from public.race_stage_plans rsp
  left join public.race_stages rs
    on rs.id = rsp.stage_id
  left join public.race_preparations rp
    on rp.id = rsp.race_preparation_id
  where rsp.id = p_race_stage_plan_id;

  if not found then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'race_stage_plan_not_found',
      'race_stage_plan_id', p_race_stage_plan_id
    );
  end if;

  v_effective_game_ts :=
    coalesce(
      p_effective_game_ts,
      public.get_current_game_timestamp()
    );

  v_stage_start_text :=
    coalesce(
      nullif(v_plan_json #>> '{metadata,stage_start_game_ts}', ''),
      nullif(v_plan_json #>> '{stage_profile_snapshot_json,stage_start_game_ts}', ''),
      nullif(v_stage_json #>> '{metadata,stage_start_game_ts}', '')
    );

  if v_stage_start_text is not null then
    begin
      v_stage_start_game_ts := v_stage_start_text::timestamptz;
    exception
      when others then
        v_stage_start_game_ts := null;
    end;
  end if;

  if v_stage_start_game_ts is null then
    v_stage_date :=
      coalesce(
        nullif(v_plan_json ->> 'stage_date', '')::date,
        nullif(v_stage_json ->> 'stage_date', '')::date
      );

    v_start_hour :=
      coalesce(
        nullif(v_stage_json ->> 'planned_start_hour_number', '')::integer,
        nullif(v_plan_json #>> '{metadata,planned_start_hour_number}', '')::integer
      );

    v_start_minute :=
      coalesce(
        nullif(v_stage_json ->> 'planned_start_minute', '')::integer,
        nullif(v_plan_json #>> '{metadata,planned_start_minute}', '')::integer,
        0
      );

    if v_stage_date is not null and v_start_hour is not null then
      v_stage_start_game_ts :=
        (
          v_stage_date::timestamp
          + make_interval(
              hours => v_start_hour,
              mins => v_start_minute
            )
        ) at time zone 'UTC';
    end if;
  end if;

  if v_stage_start_game_ts is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'stage_start_game_timestamp_unresolved',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_plan_json -> 'stage_id',
      'stage_date',
        coalesce(
          v_plan_json -> 'stage_date',
          v_stage_json -> 'stage_date'
        ),
      'planned_start_hour_number',
        v_stage_json -> 'planned_start_hour_number',
      'planned_start_minute',
        v_stage_json -> 'planned_start_minute',
      'effective_game_ts', v_effective_game_ts
    );
  end if;

  v_lock_game_ts :=
    v_stage_start_game_ts - interval '3 hours';

  return jsonb_build_object(
    'status', 'resolved',
    'race_stage_plan_id', p_race_stage_plan_id,
    'race_preparation_id', v_plan_json -> 'race_preparation_id',
    'race_id', v_plan_json -> 'race_id',
    'stage_id', v_plan_json -> 'stage_id',
    'club_id',
      coalesce(
        v_preparation_json -> 'participating_club_id',
        v_preparation_json -> 'club_id'
      ),
    'stage_plan_status', v_plan_json ->> 'status',
    'race_preparation_status', v_preparation_json ->> 'status',
    'effective_game_ts', v_effective_game_ts,
    'stage_start_game_ts', v_stage_start_game_ts,
    'lock_game_ts', v_lock_game_ts,
    'minutes_until_lock',
      round(
        (
          extract(
            epoch from (
              v_lock_game_ts - v_effective_game_ts
            )
          ) / 60.0
        )::numeric,
        2
      ),
    'before_lock_cutoff',
      v_effective_game_ts < v_lock_game_ts,
    'at_or_after_lock_cutoff',
      v_effective_game_ts >= v_lock_game_ts,
    'stage_already_started',
      v_effective_game_ts >= v_stage_start_game_ts,
    'lock_rule',
      'stage_start_game_ts_minus_3_hours',
    'authoritative_time_function',
      'public.get_current_game_timestamp()'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_build_locked_stage_plan_snapshot_v1(p_race_stage_plan_id uuid, p_dry_run boolean DEFAULT true, p_effective_game_ts timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_plan public.race_stage_plans%rowtype;
  v_stage_json jsonb;
  v_preparation_json jsonb;

  v_lock_context jsonb;
  v_effective_game_ts timestamptz;
  v_lock_game_ts timestamptz;
  v_stage_start_game_ts timestamptz;

  v_staff_snapshots jsonb := '[]'::jsonb;
  v_asset_snapshots jsonb := '[]'::jsonb;
  v_supply_reservation_snapshots jsonb := '[]'::jsonb;

  v_selected_rider_count integer := 0;
  v_role_count integer := 0;
  v_equipment_count integer := 0;
  v_individual_tactic_count integer := 0;
  v_supply_count integer := 0;

  v_missing_sections jsonb := '[]'::jsonb;
  v_snapshot_base jsonb;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_existing_hash text;
  v_applied boolean := false;
begin
  if p_race_stage_plan_id is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'race_stage_plan_id_required',
      'dry_run', coalesce(p_dry_run, true)
    );
  end if;

  if not coalesce(p_dry_run, true)
     and p_effective_game_ts is not null then
    raise exception
      'effective_game_ts override is allowed only in dry-run mode';
  end if;

  select rsp.*
  into v_plan
  from public.race_stage_plans rsp
  where rsp.id = p_race_stage_plan_id
  for update;

  if not found then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'race_stage_plan_not_found',
      'race_stage_plan_id', p_race_stage_plan_id,
      'dry_run', coalesce(p_dry_run, true)
    );
  end if;

  select to_jsonb(rs)
  into v_stage_json
  from public.race_stages rs
  where rs.id = v_plan.stage_id;

  select to_jsonb(rp)
  into v_preparation_json
  from public.race_preparations rp
  where rp.id = v_plan.race_preparation_id;

  v_lock_context :=
    public.race_engine_get_stage_plan_lock_context_v1(
      p_race_stage_plan_id,
      p_effective_game_ts
    );

  if coalesce(v_lock_context ->> 'status', '') <> 'resolved' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        coalesce(
          v_lock_context ->> 'reason',
          'lock_context_unresolved'
        ),
      'race_stage_plan_id', p_race_stage_plan_id,
      'dry_run', coalesce(p_dry_run, true),
      'lock_context', v_lock_context
    );
  end if;

  v_effective_game_ts :=
    (v_lock_context ->> 'effective_game_ts')::timestamptz;
  v_lock_game_ts :=
    (v_lock_context ->> 'lock_game_ts')::timestamptz;
  v_stage_start_game_ts :=
    (v_lock_context ->> 'stage_start_game_ts')::timestamptz;

  if v_effective_game_ts < v_lock_game_ts then
    return jsonb_build_object(
      'status', 'before_lock_cutoff',
      'race_stage_plan_id', p_race_stage_plan_id,
      'dry_run', coalesce(p_dry_run, true),
      'eligible_to_finalize', false,
      'lock_context', v_lock_context
    );
  end if;

  if v_effective_game_ts >= v_stage_start_game_ts then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'stage_already_started_forward_only_guard',
      'race_stage_plan_id', p_race_stage_plan_id,
      'race_preparation_id', v_plan.race_preparation_id,
      'race_id', v_plan.race_id,
      'stage_id', v_plan.stage_id,
      'dry_run', coalesce(p_dry_run, true),
      'eligible_to_finalize', false,
      'effective_game_ts', v_effective_game_ts,
      'stage_start_game_ts', v_stage_start_game_ts,
      'historical_processing', false,
      'historical_rewrite', false,
      'lock_context', v_lock_context
    );
  end if;

  if exists (
    select 1
    from public.race_stage_simulation_runs simulation
    where simulation.stage_id = v_plan.stage_id
      and simulation.status = 'completed'
  ) then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'completed_stage_historical_rewrite_forbidden',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_plan.stage_id,
      'dry_run', coalesce(p_dry_run, true),
      'historical_rewrite', false
    );
  end if;

  if coalesce(v_plan.engine_stage_payload_json, '{}'::jsonb)
     <> '{}'::jsonb then
    v_existing_hash :=
      coalesce(
        v_plan.engine_stage_payload_json ->> 'snapshot_hash',
        md5(v_plan.engine_stage_payload_json::text)
      );

    return jsonb_build_object(
      'status', 'already_snapshotted',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_plan.stage_id,
      'dry_run', coalesce(p_dry_run, true),
      'eligible_to_finalize', true,
      'snapshot_hash', v_existing_hash,
      'immutable_existing_snapshot', true,
      'lock_context', v_lock_context
    );
  end if;

  if jsonb_typeof(v_plan.team_tactic_json) is distinct from 'object' then
    v_missing_sections :=
      v_missing_sections || jsonb_build_array('team_tactic_json');
  end if;

  if jsonb_typeof(v_plan.rider_roles_json) is distinct from 'object' then
    v_missing_sections :=
      v_missing_sections || jsonb_build_array('rider_roles_json');
  end if;

  if jsonb_typeof(v_plan.rider_individual_tactics_json)
     is distinct from 'object' then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('rider_individual_tactics_json');
  end if;

  if jsonb_typeof(v_plan.rider_equipment_json)
     is distinct from 'object' then
    v_missing_sections :=
      v_missing_sections || jsonb_build_array('rider_equipment_json');
  end if;

  if jsonb_typeof(v_plan.rider_supplies_json)
     is distinct from 'object' then
    v_missing_sections :=
      v_missing_sections || jsonb_build_array('rider_supplies_json');
  end if;

  select count(*)::integer
  into v_selected_rider_count
  from public.race_preparation_riders preparation_rider
  where preparation_rider.race_preparation_id =
    v_plan.race_preparation_id;

  select count(*)::integer
  into v_role_count
  from jsonb_object_keys(
    coalesce(v_plan.rider_roles_json, '{}'::jsonb)
  );

  select count(*)::integer
  into v_equipment_count
  from jsonb_object_keys(
    coalesce(v_plan.rider_equipment_json, '{}'::jsonb)
  );

  select count(*)::integer
  into v_individual_tactic_count
  from jsonb_object_keys(
    coalesce(
      v_plan.rider_individual_tactics_json,
      '{}'::jsonb
    )
  );

  select count(*)::integer
  into v_supply_count
  from jsonb_object_keys(
    coalesce(v_plan.rider_supplies_json, '{}'::jsonb)
  );

  if coalesce(v_preparation_json ->> 'status', '') not in (
    'submitted',
    'locked',
    'sent_to_engine'
  ) then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('submitted_race_preparation');
  end if;

  if v_selected_rider_count <= 0 then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('selected_riders');
  end if;

  if v_role_count <= 0 then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('rider_roles');
  end if;

  if v_equipment_count <= 0 then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('rider_equipment');
  end if;

  if v_individual_tactic_count <= 0 then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('rider_individual_tactics');
  end if;

  if v_supply_count <= 0 then
    v_missing_sections :=
      v_missing_sections
      || jsonb_build_array('rider_supplies');
  end if;

  if jsonb_array_length(v_missing_sections) > 0 then
    return jsonb_build_object(
      'status', 'incomplete_plan_blocked',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_plan.stage_id,
      'race_preparation_id', v_plan.race_preparation_id,
      'dry_run', coalesce(p_dry_run, true),
      'eligible_to_finalize', false,
      'missing_or_invalid_sections', v_missing_sections,
      'counts', jsonb_build_object(
        'selected_riders', v_selected_rider_count,
        'rider_roles', v_role_count,
        'rider_equipment', v_equipment_count,
        'rider_individual_tactics', v_individual_tactic_count,
        'rider_supplies', v_supply_count
      ),
      'lock_context', v_lock_context
    );
  end if;

  select coalesce(
    jsonb_agg(
      to_jsonb(staff_assignment)
      order by to_jsonb(staff_assignment)::text
    ),
    '[]'::jsonb
  )
  into v_staff_snapshots
  from public.race_preparation_staff staff_assignment
  where staff_assignment.race_preparation_id =
    v_plan.race_preparation_id;

  select coalesce(
    jsonb_agg(
      to_jsonb(asset_assignment)
      order by to_jsonb(asset_assignment)::text
    ),
    '[]'::jsonb
  )
  into v_asset_snapshots
  from public.race_preparation_assets asset_assignment
  where asset_assignment.race_preparation_id =
    v_plan.race_preparation_id;

  select coalesce(
    jsonb_agg(
      to_jsonb(supply_reservation)
      order by to_jsonb(supply_reservation)::text
    ),
    '[]'::jsonb
  )
  into v_supply_reservation_snapshots
  from public.race_preparation_supplies supply_reservation
  where supply_reservation.race_preparation_id =
    v_plan.race_preparation_id;

  v_snapshot_base :=
    jsonb_build_object(
      'snapshot_schema_version',
        'race_engine_stage_plan_input_snapshot_v1',
      'source_version',
        'issue01a_general_locked_stage_plan_snapshot_v1',
      'scope',
        'general_race_engine_v1_all_future_road_stages',
      'immutable', true,

      'race_stage_plan_id', v_plan.id,
      'race_preparation_id', v_plan.race_preparation_id,
      'race_id', v_plan.race_id,
      'stage_id', v_plan.stage_id,
      'stage_number', v_plan.stage_number,

      'club_id',
        coalesce(
          nullif(
            v_preparation_json ->> 'participating_club_id',
            ''
          )::uuid,
          nullif(
            v_preparation_json ->> 'club_id',
            ''
          )::uuid
        ),

      'built_at_game_ts', v_effective_game_ts,
      'stage_start_game_ts', v_stage_start_game_ts,
      'lock_game_ts', v_lock_game_ts,

      'stage_plan_status_before_snapshot', v_plan.status,
      'race_preparation_status',
        v_preparation_json ->> 'status',
      'startlist_status',
        v_preparation_json ->> 'startlist_status',

      'team_tactic_json',
        coalesce(v_plan.team_tactic_json, '{}'::jsonb),
      'rider_roles_json',
        coalesce(v_plan.rider_roles_json, '{}'::jsonb),
      'rider_individual_tactics_json',
        coalesce(
          v_plan.rider_individual_tactics_json,
          '{}'::jsonb
        ),
      'rider_equipment_json',
        coalesce(v_plan.rider_equipment_json, '{}'::jsonb),
      'rider_supplies_json',
        coalesce(v_plan.rider_supplies_json, '{}'::jsonb),

      'stage_objective', v_plan.stage_objective,
      'team_strategy', v_plan.team_strategy,
      'risk_level', v_plan.risk_level,

      'stage_profile_snapshot_json',
        coalesce(
          v_plan.stage_profile_snapshot_json,
          '{}'::jsonb
        ),
      'bonus_snapshot_json',
        coalesce(v_plan.bonus_snapshot_json, '{}'::jsonb),
      'stage_snapshot_json',
        coalesce(v_stage_json, '{}'::jsonb),
      'race_preparation_validation_snapshot_json',
        coalesce(
          v_preparation_json -> 'validation_snapshot_json',
          '{}'::jsonb
        ),

      'race_preparation_staff_snapshots',
        v_staff_snapshots,
      'race_preparation_asset_snapshots',
        v_asset_snapshots,
      'race_preparation_supply_reservation_snapshots',
        v_supply_reservation_snapshots,

      'authoritative_input_counts',
        jsonb_build_object(
          'selected_riders', v_selected_rider_count,
          'rider_roles', v_role_count,
          'rider_equipment', v_equipment_count,
          'rider_individual_tactics',
            v_individual_tactic_count,
          'rider_supplies', v_supply_count,
          'staff_assignments',
            jsonb_array_length(v_staff_snapshots),
          'asset_assignments',
            jsonb_array_length(v_asset_snapshots),
          'supply_reservations',
            jsonb_array_length(
              v_supply_reservation_snapshots
            )
        ),

      'hidden_engine_multiplier_contract',
        jsonb_build_object(
          'equipment_percentage_multiplier', 5,
          'race_supply_percentage_multiplier', 3,
          'ui_values_unchanged', true,
          'apply_equipment_multiplier_after_weighting', true,
          'apply_equipment_condition_after_weighting', true,
          'reuse_existing_caps', true,
          'do_not_multiply_non_percentage_state', true,
          'do_not_multiply_inventory_quantity', true,
          'do_not_multiply_durability_uses', true,
          'do_not_multiply_mandatory_blockers', true
        ),

      'source_hashes',
        jsonb_build_object(
          'team_tactic_json',
            md5(
              coalesce(
                v_plan.team_tactic_json,
                '{}'::jsonb
              )::text
            ),
          'rider_roles_json',
            md5(
              coalesce(
                v_plan.rider_roles_json,
                '{}'::jsonb
              )::text
            ),
          'rider_individual_tactics_json',
            md5(
              coalesce(
                v_plan.rider_individual_tactics_json,
                '{}'::jsonb
              )::text
            ),
          'rider_equipment_json',
            md5(
              coalesce(
                v_plan.rider_equipment_json,
                '{}'::jsonb
              )::text
            ),
          'rider_supplies_json',
            md5(
              coalesce(
                v_plan.rider_supplies_json,
                '{}'::jsonb
              )::text
            ),
          'bonus_snapshot_json',
            md5(
              coalesce(
                v_plan.bonus_snapshot_json,
                '{}'::jsonb
              )::text
            ),
          'staff_snapshots',
            md5(v_staff_snapshots::text),
          'asset_snapshots',
            md5(v_asset_snapshots::text),
          'supply_reservation_snapshots',
            md5(
              v_supply_reservation_snapshots::text
            )
        ),

      'hard_rejections',
        jsonb_build_array(
          'unsaved_frontend_state',
          'unaccepted_sport_director_suggestion',
          'invented_human_team_command',
          'mutable_equipment_after_lock',
          'mutable_supplies_after_lock',
          'historical_completed_stage_rewrite',
          'stage_specific_hard_coded_ids'
        )
    );

  v_snapshot_hash := md5(v_snapshot_base::text);

  v_snapshot :=
    v_snapshot_base
    || jsonb_build_object(
         'snapshot_hash',
         v_snapshot_hash
       );

  if not coalesce(p_dry_run, true) then
    update public.race_stage_plans rsp
    set
      status = 'locked',
      locked_at = coalesce(rsp.locked_at, clock_timestamp()),
      engine_stage_payload_json = v_snapshot,
      metadata =
        coalesce(rsp.metadata, '{}'::jsonb)
        || jsonb_build_object(
             'engine_stage_payload_snapshot_hash',
             v_snapshot_hash,
             'engine_stage_payload_snapshot_version',
             'race_engine_stage_plan_input_snapshot_v1',
             'engine_stage_payload_built_at_game_ts',
             v_effective_game_ts,
             'engine_stage_payload_lock_game_ts',
             v_lock_game_ts,
             'engine_stage_payload_stage_start_game_ts',
             v_stage_start_game_ts
           )
    where rsp.id = p_race_stage_plan_id
      and coalesce(
            rsp.engine_stage_payload_json,
            '{}'::jsonb
          ) = '{}'::jsonb;

    v_applied := found;
  end if;

  return jsonb_build_object(
    'status',
      case
        when coalesce(p_dry_run, true)
          then 'dry_run_snapshot_ready'
        when v_applied
          then 'locked_snapshot_applied'
        else 'snapshot_not_applied_concurrent_change'
      end,
    'race_stage_plan_id', p_race_stage_plan_id,
    'race_preparation_id', v_plan.race_preparation_id,
    'race_id', v_plan.race_id,
    'stage_id', v_plan.stage_id,
    'dry_run', coalesce(p_dry_run, true),
    'eligible_to_finalize', true,
    'applied', v_applied,
    'snapshot_hash', v_snapshot_hash,
    'snapshot', v_snapshot,
    'lock_context', v_lock_context,
    'historical_rewrite', false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_finalize_due_stage_plan_snapshots_v1(p_limit integer DEFAULT 100, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_limit integer;
  v_current_game_ts timestamptz;
  v_plan record;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_processed integer := 0;
  v_ready integer := 0;
  v_applied integer := 0;
  v_blocked integer := 0;
begin
  v_limit := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_current_game_ts := public.get_current_game_timestamp();

  for v_plan in
    select
      rsp.id,
      rsp.stage_date,
      rsp.stage_number,
      lock_state.lock_context
    from public.race_stage_plans rsp
    cross join lateral (
      select
        public.race_engine_get_stage_plan_lock_context_v1(
          rsp.id,
          v_current_game_ts
        ) as lock_context
    ) lock_state
    where rsp.stage_id is not null
      and rsp.status in (
        'draft',
        'submitted',
        'defaulted',
        'locked'
      )
      and coalesce(
            rsp.engine_stage_payload_json,
            '{}'::jsonb
          ) = '{}'::jsonb
      and lock_state.lock_context ->> 'status' = 'resolved'
      and coalesce(
            (
              lock_state.lock_context ->>
                'at_or_after_lock_cutoff'
            )::boolean,
            false
          ) = true
      and coalesce(
            (
              lock_state.lock_context ->>
                'stage_already_started'
            )::boolean,
            false
          ) = false
      and not exists (
        select 1
        from public.race_stage_simulation_runs simulation
        where simulation.stage_id = rsp.stage_id
          and simulation.status = 'completed'
      )
    order by
      (
        lock_state.lock_context ->> 'lock_game_ts'
      )::timestamptz,
      rsp.stage_number,
      rsp.id
    limit v_limit
  loop
    v_processed := v_processed + 1;

    v_result :=
      public.race_engine_build_locked_stage_plan_snapshot_v1(
        v_plan.id,
        coalesce(p_dry_run, true),
        null
      );

    v_results :=
      v_results
      || jsonb_build_array(v_result);

    if coalesce(v_result ->> 'status', '') in (
      'dry_run_snapshot_ready',
      'already_snapshotted'
    ) then
      v_ready := v_ready + 1;

    elsif coalesce(v_result ->> 'status', '') =
          'locked_snapshot_applied' then
      v_applied := v_applied + 1;

    elsif coalesce(v_result ->> 'status', '') not in (
      'before_lock_cutoff'
    ) then
      v_blocked := v_blocked + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'status',
      case
        when coalesce(p_dry_run, true)
          then 'due_stage_plan_snapshot_dry_run_completed'
        else 'due_stage_plan_snapshot_apply_completed'
      end,
    'dry_run', coalesce(p_dry_run, true),
    'authoritative_game_ts', v_current_game_ts,
    'processed_count', v_processed,
    'ready_count', v_ready,
    'applied_count', v_applied,
    'blocked_count', v_blocked,
    'forward_only_window',
      'lock_game_ts <= current_game_ts < stage_start_game_ts',
    'started_stage_candidates_selected', 0,
    'historical_processing', false,
    'historical_rewrite', false,
    'results', v_results
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_finalize_due_stage_plan_snapshots_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lock_acquired boolean;
  v_result jsonb;
begin
  v_lock_acquired :=
    pg_try_advisory_xact_lock(
      hashtextextended(
        'race_engine_finalize_due_stage_plan_snapshots_tick_v1',
        0
      )
    );

  if not v_lock_acquired then
    return jsonb_build_object(
      'status',
        'race_engine_stage_plan_snapshot_tick_skipped_busy',
      'lock_acquired', false,
      'historical_processing', false,
      'historical_rewrite', false
    );
  end if;

  v_result :=
    public.race_engine_finalize_due_stage_plan_snapshots_v1(
      100,
      false
    );

  return jsonb_build_object(
    'status',
      'race_engine_stage_plan_snapshot_tick_completed',
    'lock_acquired', true,
    'authoritative_game_ts',
      v_result -> 'authoritative_game_ts',
    'finalizer_status', v_result ->> 'status',
    'processed_count', v_result -> 'processed_count',
    'ready_count', v_result -> 'ready_count',
    'applied_count', v_result -> 'applied_count',
    'blocked_count', v_result -> 'blocked_count',
    'started_stage_candidates_selected',
      v_result -> 'started_stage_candidates_selected',
    'forward_only_window',
      v_result ->> 'forward_only_window',
    'historical_processing', false,
    'historical_rewrite', false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_resolve_locked_stage_tactical_plan_v1(p_race_stage_plan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_payload jsonb;
  v_payload_without_hash jsonb;
  v_snapshot_hash text;
  v_calculated_snapshot_hash text;

  v_team_tactic_json jsonb;
  v_rider_roles_json jsonb;
  v_individual_tactics_json jsonb;
  v_source_hashes jsonb;

  v_team_plan text;
  v_rider record;
  v_rider_key text;
  v_rider_id uuid;
  v_role_raw text;
  v_role_code text;

  v_phase_number integer;
  v_phase_key text;
  v_explicit_raw text;
  v_explicit_command text;
  v_role_default text;
  v_team_base text;
  v_resolved_command text;
  v_resolved_source text;
  v_precedence_rank integer;

  v_rider_phases jsonb;
  v_rider_plan jsonb;
  v_rider_plans jsonb := '{}'::jsonb;
  v_action_counts jsonb := '{}'::jsonb;

  v_invalid_roles jsonb := '[]'::jsonb;
  v_invalid_commands jsonb := '[]'::jsonb;
  v_source_hash_mismatches jsonb := '[]'::jsonb;

  v_rider_count integer := 0;
  v_phase_count integer := 0;
  v_explicit_count integer := 0;
  v_role_default_count integer := 0;
  v_team_base_count integer := 0;
  v_command_count integer;

  v_plan_base jsonb;
  v_resolver_hash text;
begin
  if p_race_stage_plan_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'race_stage_plan_id_required'
    );
  end if;

  select
    coalesce(
      rsp.engine_stage_payload_json,
      '{}'::jsonb
    )
  into v_payload
  from public.race_stage_plans rsp
  where rsp.id = p_race_stage_plan_id;

  if not found then
    return jsonb_build_object(
      'status', 'not_found',
      'race_stage_plan_id', p_race_stage_plan_id
    );
  end if;

  if v_payload = '{}'::jsonb then
    return jsonb_build_object(
      'status', 'missing_locked_snapshot',
      'race_stage_plan_id', p_race_stage_plan_id,
      'mutable_stage_plan_fallback_allowed', false,
      'human_command_invention_allowed', false
    );
  end if;

  if coalesce(
       v_payload ->> 'snapshot_schema_version',
       ''
     ) <> 'race_engine_stage_plan_input_snapshot_v1'
  then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'unsupported_snapshot_schema_version',
      'race_stage_plan_id', p_race_stage_plan_id,
      'actual_snapshot_schema_version',
        v_payload ->> 'snapshot_schema_version'
    );
  end if;

  if coalesce(
       (v_payload ->> 'immutable')::boolean,
       false
     ) is not true
  then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'snapshot_not_marked_immutable',
      'race_stage_plan_id', p_race_stage_plan_id
    );
  end if;

  v_snapshot_hash :=
    nullif(v_payload ->> 'snapshot_hash', '');

  v_payload_without_hash :=
    v_payload - 'snapshot_hash';

  v_calculated_snapshot_hash :=
    md5(v_payload_without_hash::text);

  if v_snapshot_hash is null
     or v_snapshot_hash <>
        v_calculated_snapshot_hash
  then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'snapshot_hash_mismatch',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stored_snapshot_hash', v_snapshot_hash,
      'calculated_snapshot_hash',
        v_calculated_snapshot_hash
    );
  end if;

  v_team_tactic_json :=
    coalesce(
      v_payload -> 'team_tactic_json',
      '{}'::jsonb
    );

  v_rider_roles_json :=
    coalesce(
      v_payload -> 'rider_roles_json',
      '{}'::jsonb
    );

  v_individual_tactics_json :=
    coalesce(
      v_payload -> 'rider_individual_tactics_json',
      '{}'::jsonb
    );

  v_source_hashes :=
    coalesce(
      v_payload -> 'source_hashes',
      '{}'::jsonb
    );

  if jsonb_typeof(v_team_tactic_json)
       is distinct from 'object'
     or jsonb_typeof(v_rider_roles_json)
       is distinct from 'object'
     or jsonb_typeof(v_individual_tactics_json)
       is distinct from 'object'
  then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'tactical_input_sections_must_be_objects',
      'race_stage_plan_id', p_race_stage_plan_id
    );
  end if;

  if nullif(
       v_source_hashes ->> 'team_tactic_json',
       ''
     ) is not null
     and v_source_hashes ->> 'team_tactic_json'
       <> md5(v_team_tactic_json::text)
  then
    v_source_hash_mismatches :=
      v_source_hash_mismatches
      || jsonb_build_array('team_tactic_json');
  end if;

  if nullif(
       v_source_hashes ->> 'rider_roles_json',
       ''
     ) is not null
     and v_source_hashes ->> 'rider_roles_json'
       <> md5(v_rider_roles_json::text)
  then
    v_source_hash_mismatches :=
      v_source_hash_mismatches
      || jsonb_build_array('rider_roles_json');
  end if;

  if nullif(
       v_source_hashes
         ->> 'rider_individual_tactics_json',
       ''
     ) is not null
     and v_source_hashes
           ->> 'rider_individual_tactics_json'
       <> md5(v_individual_tactics_json::text)
  then
    v_source_hash_mismatches :=
      v_source_hash_mismatches
      || jsonb_build_array(
           'rider_individual_tactics_json'
         );
  end if;

  if jsonb_array_length(
       v_source_hash_mismatches
     ) > 0
  then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'snapshot_source_hash_mismatch',
      'race_stage_plan_id', p_race_stage_plan_id,
      'mismatched_sections',
        v_source_hash_mismatches
    );
  end if;

  v_team_plan :=
    lower(
      coalesce(
        nullif(v_team_tactic_json ->> 'plan', ''),
        nullif(
          v_team_tactic_json ->> 'team_tactic',
          ''
        ),
        nullif(v_team_tactic_json ->> 'tactic', ''),
        'balanced'
      )
    );

  if v_team_plan not in (
    'balanced',
    'aggressive',
    'sprint_control',
    'breakaway',
    'gc_protection',
    'climber_support'
  ) then
    return jsonb_build_object(
      'status', 'not_road_tactical_plan',
      'reason', 'unsupported_road_team_tactic',
      'race_stage_plan_id', p_race_stage_plan_id,
      'team_plan', v_team_plan,
      'supported_team_plans',
        jsonb_build_array(
          'balanced',
          'aggressive',
          'sprint_control',
          'breakaway',
          'gc_protection',
          'climber_support'
        )
    );
  end if;

  if not exists (
    select 1
    from jsonb_object_keys(v_rider_roles_json)
  ) then
    return jsonb_build_object(
      'status', 'invalid_locked_snapshot',
      'reason', 'no_saved_rider_roles',
      'race_stage_plan_id', p_race_stage_plan_id
    );
  end if;

  for v_rider in
    select
      role_entry.key,
      role_entry.value
    from jsonb_each(v_rider_roles_json)
      role_entry
    order by role_entry.key
  loop
    v_rider_key := v_rider.key;
    v_rider_count := v_rider_count + 1;

    begin
      v_rider_id := v_rider_key::uuid;
    exception
      when invalid_text_representation then
        v_invalid_roles :=
          v_invalid_roles
          || jsonb_build_array(
               jsonb_build_object(
                 'rider_key', v_rider_key,
                 'reason', 'rider_key_not_uuid'
               )
             );
        continue;
    end;

    if jsonb_typeof(v_rider.value)
         is distinct from 'string'
    then
      v_invalid_roles :=
        v_invalid_roles
        || jsonb_build_array(
             jsonb_build_object(
               'rider_id', v_rider_id,
               'reason', 'role_value_not_string',
               'value_type',
                 jsonb_typeof(v_rider.value)
             )
           );
      continue;
    end if;

    v_role_raw :=
      lower(
        coalesce(
          nullif(v_rider.value #>> '{}', ''),
          'free_role'
        )
      );

    v_role_code :=
      case v_role_raw
        when 'leader' then 'team_leader_gc'
        when 'gc_leader' then 'team_leader_gc'
        when 'team_leader' then 'team_leader_gc'
        when 'lead_out' then 'lead_out_rider'
        when 'sprint_train' then 'sprint_train_rider'
        when 'breakaway' then 'breakaway_rider'
        when 'protected' then 'protected_rider'
        when 'helper' then 'helper_domestique'
        when 'domestique' then 'helper_domestique'
        when 'mountain_helper'
          then 'mountain_domestique'
        else v_role_raw
      end;

    if v_role_code not in (
      'team_leader_gc',
      'sprinter',
      'lead_out_rider',
      'sprint_train_rider',
      'climber',
      'mountain_domestique',
      'helper_domestique',
      'breakaway_rider',
      'breakaway_chaser',
      'rouleur',
      'protected_rider',
      'free_role'
    ) then
      v_invalid_roles :=
        v_invalid_roles
        || jsonb_build_array(
             jsonb_build_object(
               'rider_id', v_rider_id,
               'saved_role', v_role_raw,
               'reason', 'unsupported_saved_role'
             )
           );
      continue;
    end if;

    v_rider_phases := '{}'::jsonb;

    for v_phase_number in 1..4
    loop
      v_phase_key :=
        'phase_' || v_phase_number::text;

      v_explicit_raw :=
        lower(
          nullif(
            coalesce(
              v_individual_tactics_json
                #>> array[
                      v_rider_key,
                      v_phase_key,
                      'command'
                    ],
              v_team_tactic_json
                #>> array[
                      'individual_tactics_by_rider',
                      v_rider_key,
                      v_phase_key,
                      'command'
                    ]
            ),
            ''
          )
        );

      if v_explicit_raw is not null
         and v_explicit_raw not in (
           'follow_team_plan',
           'ride_naturally',
           'protect_leader',
           'conserve_energy',
           'stay_near_front',
           'control_tempo',
           'chase_breakaway',
           'attack',
           'join_breakaway',
           'lead_out',
           'sprint',
           'climb_hard',
           'avoid_risks'
         )
      then
        v_invalid_commands :=
          v_invalid_commands
          || jsonb_build_array(
               jsonb_build_object(
                 'rider_id', v_rider_id,
                 'phase', v_phase_key,
                 'saved_command', v_explicit_raw,
                 'reason',
                   'unsupported_saved_individual_command'
               )
             );
      end if;

      v_explicit_command :=
        case
          when v_explicit_raw is null
            then null
          when v_explicit_raw =
               'follow_team_plan'
            then null
          when v_explicit_raw in (
            'ride_naturally',
            'protect_leader',
            'conserve_energy',
            'stay_near_front',
            'control_tempo',
            'chase_breakaway',
            'attack',
            'join_breakaway',
            'lead_out',
            'sprint',
            'climb_hard',
            'avoid_risks'
          )
            then v_explicit_raw
          else null
        end;

      v_role_default :=
        case v_role_code
          when 'team_leader_gc' then
            case v_phase_number
              when 1 then 'avoid_risks'
              when 2 then 'conserve_energy'
              when 3 then 'stay_near_front'
              when 4 then 'stay_near_front'
            end

          when 'sprinter' then
            case v_phase_number
              when 1 then 'conserve_energy'
              when 2 then 'conserve_energy'
              when 3 then 'stay_near_front'
              when 4 then 'sprint'
            end

          when 'lead_out_rider' then
            case v_phase_number
              when 1 then 'conserve_energy'
              when 2 then 'control_tempo'
              when 3 then 'stay_near_front'
              when 4 then 'lead_out'
            end

          when 'sprint_train_rider' then
            case v_phase_number
              when 1 then 'control_tempo'
              when 2 then 'control_tempo'
              when 3 then 'chase_breakaway'
              when 4 then 'lead_out'
            end

          when 'climber' then
            case v_phase_number
              when 1 then 'conserve_energy'
              when 2 then 'stay_near_front'
              when 3 then 'climb_hard'
              when 4 then 'climb_hard'
            end

          when 'mountain_domestique' then
            case v_phase_number
              when 1 then 'protect_leader'
              when 2 then 'control_tempo'
              when 3 then 'climb_hard'
              when 4 then 'protect_leader'
            end

          when 'helper_domestique' then
            case v_phase_number
              when 1 then 'protect_leader'
              when 2 then 'control_tempo'
              when 3 then 'chase_breakaway'
              when 4 then 'protect_leader'
            end

          when 'breakaway_rider' then
            case v_phase_number
              when 1 then 'attack'
              when 2 then 'join_breakaway'
              when 3 then 'control_tempo'
              when 4 then 'stay_near_front'
            end

          when 'breakaway_chaser' then
            case v_phase_number
              when 1 then 'chase_breakaway'
              when 2 then 'chase_breakaway'
              when 3 then 'chase_breakaway'
              when 4 then 'stay_near_front'
            end

          when 'rouleur' then
            case v_phase_number
              when 1 then 'control_tempo'
              when 2 then 'chase_breakaway'
              when 3 then 'control_tempo'
              when 4 then 'stay_near_front'
            end

          when 'protected_rider' then
            case v_phase_number
              when 1 then 'avoid_risks'
              when 2 then 'conserve_energy'
              when 3 then 'stay_near_front'
              when 4 then 'stay_near_front'
            end

          when 'free_role' then null
        end;

      v_team_base :=
        case v_team_plan
          when 'balanced' then
            case v_phase_number
              when 1 then 'control_tempo'
              when 2 then 'control_tempo'
              when 3 then 'stay_near_front'
              when 4 then 'stay_near_front'
            end

          when 'aggressive' then
            case v_phase_number
              when 1 then 'stay_near_front'
              when 2 then 'control_tempo'
              when 3 then 'stay_near_front'
              when 4 then 'stay_near_front'
            end

          when 'sprint_control' then
            case v_phase_number
              when 1 then 'control_tempo'
              when 2 then 'control_tempo'
              when 3 then 'chase_breakaway'
              when 4 then 'stay_near_front'
            end

          when 'breakaway' then
            case v_phase_number
              when 1 then 'stay_near_front'
              when 2 then 'stay_near_front'
              when 3 then 'control_tempo'
              when 4 then 'stay_near_front'
            end

          when 'gc_protection' then
            case v_phase_number
              when 1 then 'protect_leader'
              when 2 then 'protect_leader'
              when 3 then 'stay_near_front'
              when 4 then 'protect_leader'
            end

          when 'climber_support' then
            case v_phase_number
              when 1 then 'protect_leader'
              when 2 then 'control_tempo'
              when 3 then 'climb_hard'
              when 4 then 'protect_leader'
            end
        end;

      if v_explicit_command is not null then
        v_resolved_command :=
          v_explicit_command;
        v_resolved_source :=
          'explicit_individual_command';
        v_precedence_rank := 1;
        v_explicit_count :=
          v_explicit_count + 1;

      elsif v_role_default is not null then
        v_resolved_command :=
          v_role_default;
        v_resolved_source :=
          'saved_role_default';
        v_precedence_rank := 2;
        v_role_default_count :=
          v_role_default_count + 1;

      else
        v_resolved_command :=
          v_team_base;
        v_resolved_source :=
          'saved_team_tactic_base';
        v_precedence_rank := 3;
        v_team_base_count :=
          v_team_base_count + 1;
      end if;

      v_phase_count :=
        v_phase_count + 1;

      v_command_count :=
        coalesce(
          (
            v_action_counts
              ->> v_resolved_command
          )::integer,
          0
        ) + 1;

      v_action_counts :=
        jsonb_set(
          v_action_counts,
          array[v_resolved_command],
          to_jsonb(v_command_count),
          true
        );

      v_rider_phases :=
        v_rider_phases
        || jsonb_build_object(
             v_phase_key,
             jsonb_build_object(
               'phase_number', v_phase_number,
               'saved_explicit_command',
                 v_explicit_raw,
               'follow_team_plan_requested',
                 v_explicit_raw =
                   'follow_team_plan',
               'saved_role_default',
                 v_role_default,
               'saved_team_tactic_base',
                 v_team_base,
               'resolved_command',
                 v_resolved_command,
               'resolved_source',
                 v_resolved_source,
               'precedence_rank',
                 v_precedence_rank,
               'road_action_class_valid',
                 v_resolved_command in (
                   'ride_naturally',
                   'protect_leader',
                   'conserve_energy',
                   'stay_near_front',
                   'control_tempo',
                   'chase_breakaway',
                   'attack',
                   'join_breakaway',
                   'lead_out',
                   'sprint',
                   'climb_hard',
                   'avoid_risks'
                 ),
               'attack_wave_candidate',
                 v_resolved_command =
                   'attack',
               'bridge_candidate',
                 v_resolved_command =
                   'join_breakaway',
               'chase_candidate',
                 v_resolved_command =
                   'chase_breakaway',
               'physical_execution_status',
                 'deferred_to_issue_01c_01d'
             )
           );
    end loop;

    v_rider_plan :=
      jsonb_build_object(
        'rider_id', v_rider_id,
        'saved_role', v_role_raw,
        'canonical_role', v_role_code,
        'team_plan', v_team_plan,
        'phases', v_rider_phases
      );

    v_rider_plans :=
      v_rider_plans
      || jsonb_build_object(
           v_rider_key,
           v_rider_plan
         );
  end loop;

  if jsonb_array_length(v_invalid_roles) > 0 then
    return jsonb_build_object(
      'status', 'invalid_snapshot_roles',
      'race_stage_plan_id', p_race_stage_plan_id,
      'snapshot_hash', v_snapshot_hash,
      'invalid_roles', v_invalid_roles,
      'human_command_invention_allowed', false
    );
  end if;

  if jsonb_array_length(v_invalid_commands) > 0 then
    return jsonb_build_object(
      'status', 'invalid_snapshot_commands',
      'race_stage_plan_id', p_race_stage_plan_id,
      'snapshot_hash', v_snapshot_hash,
      'invalid_commands', v_invalid_commands,
      'human_command_invention_allowed', false
    );
  end if;

  v_plan_base :=
    jsonb_build_object(
      'resolver_schema_version',
        'race_engine_pre_stage_tactical_plan_v1',
      'resolver_source',
        'issue01b_locked_snapshot_only',
      'immutable_snapshot_hash',
        v_snapshot_hash,
      'race_stage_plan_id',
        p_race_stage_plan_id,
      'race_preparation_id',
        nullif(
          v_payload ->> 'race_preparation_id',
          ''
        )::uuid,
      'race_id',
        nullif(v_payload ->> 'race_id', '')::uuid,
      'stage_id',
        nullif(v_payload ->> 'stage_id', '')::uuid,
      'stage_number',
        nullif(
          v_payload ->> 'stage_number',
          ''
        )::integer,
      'participant_club_id',
        nullif(v_payload ->> 'club_id', '')::uuid,
      'team_plan', v_team_plan,
      'precedence_contract',
        jsonb_build_array(
          'explicit_individual_command',
          'saved_role_default',
          'saved_team_tactic_base',
          'physical_race_constraints_issue_01c_01d'
        ),
      'human_team_contract',
        jsonb_build_object(
          'locked_snapshot_only', true,
          'mutable_stage_plan_fallback', false,
          'unsaved_frontend_state_used', false,
          'unaccepted_suggestion_used', false,
          'invented_human_command', false
        ),
      'ai_contract',
        jsonb_build_object(
          'own_saved_or_generated_snapshot_plan_only',
            true,
          'ai_follower_addition_deferred_to_issue_01c',
            true
        ),
      'mass_escape_guard',
        jsonb_build_object(
          'team_tactic_direct_mass_attack',
            false,
          'attack_intent_requires_explicit_or_breakaway_role',
            true,
          'wave_limit_deferred_to_issue_01c',
            true
        ),
      'counts',
        jsonb_build_object(
          'riders', v_rider_count,
          'phase_actions', v_phase_count,
          'explicit_individual_actions',
            v_explicit_count,
          'saved_role_default_actions',
            v_role_default_count,
          'saved_team_tactic_base_actions',
            v_team_base_count
        ),
      'resolved_action_counts',
        v_action_counts,
      'rider_plans', v_rider_plans
    );

  v_resolver_hash :=
    md5(v_plan_base::text);

  return jsonb_build_object(
    'status', 'resolved',
    'race_stage_plan_id',
      p_race_stage_plan_id,
    'snapshot_hash', v_snapshot_hash,
    'resolver_hash', v_resolver_hash,
    'resolved_plan', v_plan_base
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_build_locked_attack_waves_v1(p_stage_id uuid, p_phase_number integer, p_canary_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stage_json jsonb;
  v_race_json jsonb;
  v_race_id uuid;
  v_stage_number integer;
  v_previous_stage_id uuid;
  v_terrain_type text;
  v_race_category text;
  v_stage_distance_km numeric;

  v_context_source text;
  v_candidate_array jsonb := '[]'::jsonb;
  v_gc_top10_map jsonb := '{}'::jsonb;
  v_plan_evidence jsonb := '[]'::jsonb;
  v_invalid_plan_results jsonb := '[]'::jsonb;

  v_plan record;
  v_resolver_result jsonb;
  v_rider_entry record;
  v_phase_key text;
  v_phase_json jsonb;

  v_participant_club_id uuid;
  v_rider_id uuid;
  v_is_ai boolean;
  v_action text;
  v_action_source text;
  v_role_code text;
  v_snapshot_hash text;
  v_resolver_hash text;

  v_flat numeric;
  v_climbing numeric;
  v_endurance numeric;
  v_resistance numeric;
  v_race_iq numeric;
  v_teamwork numeric;

  v_total_rider_count integer := 0;
  v_team_count integer := 0;
  v_base_wave_cap integer;
  v_average_team_size_cap integer;
  v_effective_wave_cap integer;

  v_selection jsonb;
  v_result_without_hash jsonb;
  v_wave_hash text;

  v_canary_mode boolean;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_required'
    );
  end if;

  if p_phase_number not between 1 and 4 then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'phase_number_must_be_between_1_and_4',
      'phase_number', p_phase_number
    );
  end if;

  v_phase_key :=
    'phase_' || p_phase_number::text;

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01c_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if p_canary_context_json is not null
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'canary_context_requires_transaction_local_issue01c_canary_mode',
      'production_context_used', false
    );
  end if;

  if p_canary_context_json is not null then
    v_context_source :=
      'rollback_canary_context';

    v_candidate_array :=
      coalesce(
        p_canary_context_json -> 'candidates',
        '[]'::jsonb
      );

    if jsonb_typeof(v_candidate_array)
         is distinct from 'array'
    then
      return jsonb_build_object(
        'status', 'invalid_canary_context',
        'reason', 'candidates_must_be_array'
      );
    end if;

    v_total_rider_count :=
      greatest(
        coalesce(
          nullif(
            p_canary_context_json
              ->> 'total_rider_count',
            ''
          )::integer,
          jsonb_array_length(v_candidate_array)
        ),
        0
      );

    v_team_count :=
      greatest(
        coalesce(
          nullif(
            p_canary_context_json
              ->> 'team_count',
            ''
          )::integer,
          (
            select count(
              distinct candidate.value
                ->> 'participant_club_id'
            )::integer
            from jsonb_array_elements(
              v_candidate_array
            ) candidate
          )
        ),
        0
      );

    v_stage_json :=
      coalesce(
        p_canary_context_json -> 'stage_context',
        '{}'::jsonb
      );

    v_race_id :=
      nullif(
        v_stage_json ->> 'race_id',
        ''
      )::uuid;

    v_stage_number :=
      coalesce(
        nullif(
          v_stage_json ->> 'stage_number',
          ''
        )::integer,
        1
      );

    v_terrain_type :=
      lower(
        coalesce(
          nullif(
            v_stage_json ->> 'terrain_type',
            ''
          ),
          'flat'
        )
      );

    v_race_category :=
      coalesce(
        nullif(
          v_stage_json ->> 'race_category',
          ''
        ),
        'unknown'
      );

    v_stage_distance_km :=
      coalesce(
        nullif(
          v_stage_json ->> 'distance_km',
          ''
        )::numeric,
        0
      );

    v_plan_evidence :=
      coalesce(
        p_canary_context_json -> 'plan_evidence',
        '[]'::jsonb
      );

  else
    v_context_source :=
      'immutable_locked_stage_plans';

    select
      to_jsonb(stage_row),
      stage_row.race_id,
      lower(
        coalesce(
          nullif(stage_row.terrain_type, ''),
          'flat'
        )
      )
    into
      v_stage_json,
      v_race_id,
      v_terrain_type
    from public.race_stages stage_row
    where stage_row.id = p_stage_id;

    if not found then
      return jsonb_build_object(
        'status', 'not_found',
        'reason', 'stage_not_found',
        'stage_id', p_stage_id
      );
    end if;

    v_stage_number :=
      coalesce(
        nullif(
          v_stage_json ->> 'stage_number',
          ''
        )::integer,
        1
      );

    v_stage_distance_km :=
      coalesce(
        nullif(
          coalesce(
            v_stage_json ->> 'distance_km',
            v_stage_json ->> 'distance'
          ),
          ''
        )::numeric,
        0
      );

    select to_jsonb(race_row)
    into v_race_json
    from public.races race_row
    where race_row.id = v_race_id;

    v_race_category :=
      coalesce(
        nullif(v_race_json ->> 'category', ''),
        'unknown'
      );

    select previous_stage.id
    into v_previous_stage_id
    from public.race_stages previous_stage
    where previous_stage.race_id = v_race_id
      and coalesce(
            nullif(
              to_jsonb(previous_stage)
                ->> 'stage_number',
              ''
            )::integer,
            0
          ) < v_stage_number
    order by
      coalesce(
        nullif(
          to_jsonb(previous_stage)
            ->> 'stage_number',
          ''
        )::integer,
        0
      ) desc,
      previous_stage.id
    limit 1;

    if v_previous_stage_id is not null then
      select coalesce(
        jsonb_object_agg(
          standings.rider_id::text,
          to_jsonb(standings.rank)
          order by standings.rank,
                   standings.rider_id
        ),
        '{}'::jsonb
      )
      into v_gc_top10_map
      from public.race_classification_standings
        standings
      where standings.race_id = v_race_id
        and standings.after_stage_id =
          v_previous_stage_id
        and standings.rider_id is not null
        and standings.rank between 1 and 10
        and public.sponsor_is_general_classification_row_v1(
              to_jsonb(standings)
            );
    end if;

    select count(*)::integer
    into v_team_count
    from public.race_stage_plans stage_plan
    where stage_plan.stage_id = p_stage_id
      and coalesce(
            stage_plan.engine_stage_payload_json,
            '{}'::jsonb
          ) <> '{}'::jsonb;

    for v_plan in
      select
        stage_plan.id as race_stage_plan_id
      from public.race_stage_plans stage_plan
      where stage_plan.stage_id = p_stage_id
        and coalesce(
              stage_plan.engine_stage_payload_json,
              '{}'::jsonb
            ) <> '{}'::jsonb
      order by stage_plan.id
    loop
      v_resolver_result :=
        public.race_engine_resolve_locked_stage_tactical_plan_v1(
          v_plan.race_stage_plan_id
        );

      if coalesce(
           v_resolver_result ->> 'status',
           ''
         ) <> 'resolved'
      then
        v_invalid_plan_results :=
          v_invalid_plan_results
          || jsonb_build_array(
               jsonb_build_object(
                 'race_stage_plan_id',
                   v_plan.race_stage_plan_id,
                 'resolver_status',
                   v_resolver_result ->> 'status',
                 'resolver_reason',
                   v_resolver_result ->> 'reason'
               )
             );
        continue;
      end if;

      v_participant_club_id :=
        nullif(
          v_resolver_result
            #>> '{resolved_plan,participant_club_id}',
          ''
        )::uuid;

      v_snapshot_hash :=
        v_resolver_result ->> 'snapshot_hash';

      v_resolver_hash :=
        v_resolver_result ->> 'resolver_hash';

      select
        coalesce(club.is_ai, false)
        or coalesce(
             club.inactive_ai_controlled,
             false
           )
      into v_is_ai
      from public.clubs club
      where club.id = v_participant_club_id;

      v_is_ai := coalesce(v_is_ai, false);

      v_plan_evidence :=
        v_plan_evidence
        || jsonb_build_array(
             jsonb_build_object(
               'race_stage_plan_id',
                 v_plan.race_stage_plan_id,
               'participant_club_id',
                 v_participant_club_id,
               'is_ai', v_is_ai,
               'snapshot_hash', v_snapshot_hash,
               'resolver_hash', v_resolver_hash,
               'resolver_status', 'resolved'
             )
           );

      for v_rider_entry in
        select
          rider_plan.key as rider_key,
          rider_plan.value as rider_plan
        from jsonb_each(
          coalesce(
            v_resolver_result
              #> '{resolved_plan,rider_plans}',
            '{}'::jsonb
          )
        ) rider_plan
        order by rider_plan.key
      loop
        v_total_rider_count :=
          v_total_rider_count + 1;

        begin
          v_rider_id :=
            nullif(
              v_rider_entry.rider_plan
                ->> 'rider_id',
              ''
            )::uuid;
        exception
          when invalid_text_representation then
            continue;
        end;

        v_phase_json :=
          coalesce(
            v_rider_entry.rider_plan
              -> 'phases'
              -> v_phase_key,
            '{}'::jsonb
          );

        v_action :=
          lower(
            coalesce(
              nullif(
                v_phase_json
                  ->> 'resolved_command',
                ''
              ),
              'follow_team_plan'
            )
          );

        if v_action not in (
          'attack',
          'join_breakaway',
          'chase_breakaway'
        ) then
          continue;
        end if;

        v_action_source :=
          coalesce(
            nullif(
              v_phase_json ->> 'resolved_source',
              ''
            ),
            'unresolved'
          );

        v_role_code :=
          lower(
            coalesce(
              nullif(
                v_rider_entry.rider_plan
                  ->> 'canonical_role',
                ''
              ),
              'free_role'
            )
          );

        select
          rider.flat::numeric,
          rider.climbing::numeric,
          rider.endurance::numeric,
          rider.resistance::numeric,
          rider.race_iq::numeric,
          rider.teamwork::numeric
        into
          v_flat,
          v_climbing,
          v_endurance,
          v_resistance,
          v_race_iq,
          v_teamwork
        from public.riders rider
        where rider.id = v_rider_id;

        if not found then
          continue;
        end if;

        v_candidate_array :=
          v_candidate_array
          || jsonb_build_array(
               jsonb_build_object(
                 'rider_id', v_rider_id,
                 'participant_club_id',
                   v_participant_club_id,
                 'is_ai', v_is_ai,
                 'action', v_action,
                 'action_source', v_action_source,
                 'role_code', v_role_code,
                 'flat', coalesce(v_flat, 0),
                 'climbing',
                   coalesce(v_climbing, 0),
                 'endurance',
                   coalesce(v_endurance, 0),
                 'resistance',
                   coalesce(v_resistance, 0),
                 'race_iq',
                   coalesce(v_race_iq, 0),
                 'teamwork',
                   coalesce(v_teamwork, 0),
                 'pre_stage_gc_top10',
                   v_gc_top10_map
                     ? v_rider_id::text,
                 'pre_stage_gc_rank',
                   nullif(
                     v_gc_top10_map
                       ->> v_rider_id::text,
                     ''
                   )::integer,
                 'race_stage_plan_id',
                   v_plan.race_stage_plan_id,
                 'snapshot_hash',
                   v_snapshot_hash,
                 'resolver_hash',
                   v_resolver_hash,
                 'selection_origin',
                   'immutable_locked_resolved_plan'
               )
             );
      end loop;
    end loop;
  end if;

  if jsonb_typeof(v_candidate_array)
       is distinct from 'array'
  then
    return jsonb_build_object(
      'status', 'invalid_candidate_context',
      'reason', 'candidate_array_required'
    );
  end if;

  v_base_wave_cap :=
    4
    + abs(
        hashtext(
          p_stage_id::text
          || ':phase:'
          || p_phase_number::text
          || ':attack_count'
        ) % 3
      );

  v_average_team_size_cap :=
    case
      when v_team_count <= 0
        then v_base_wave_cap
      else greatest(
        1,
        ceil(
          greatest(v_total_rider_count, 1)::numeric
          / v_team_count::numeric
        )::integer
      )
    end;

  v_effective_wave_cap :=
    least(
      v_base_wave_cap,
      v_average_team_size_cap
    );

  with
  candidate_rows as (
    select
      nullif(
        candidate.value ->> 'rider_id',
        ''
      )::uuid as rider_id,

      nullif(
        candidate.value
          ->> 'participant_club_id',
        ''
      )::uuid as participant_club_id,

      coalesce(
        (
          candidate.value ->> 'is_ai'
        )::boolean,
        false
      ) as is_ai,

      lower(
        coalesce(
          candidate.value ->> 'action',
          ''
        )
      ) as action,

      coalesce(
        candidate.value ->> 'action_source',
        'unresolved'
      ) as action_source,

      lower(
        coalesce(
          candidate.value ->> 'role_code',
          'free_role'
        )
      ) as role_code,

      coalesce(
        nullif(
          candidate.value ->> 'flat',
          ''
        )::numeric,
        0
      ) as flat,

      coalesce(
        nullif(
          candidate.value ->> 'climbing',
          ''
        )::numeric,
        0
      ) as climbing,

      coalesce(
        nullif(
          candidate.value ->> 'endurance',
          ''
        )::numeric,
        0
      ) as endurance,

      coalesce(
        nullif(
          candidate.value ->> 'resistance',
          ''
        )::numeric,
        0
      ) as resistance,

      coalesce(
        nullif(
          candidate.value ->> 'race_iq',
          ''
        )::numeric,
        0
      ) as race_iq,

      coalesce(
        nullif(
          candidate.value ->> 'teamwork',
          ''
        )::numeric,
        0
      ) as teamwork,

      coalesce(
        (
          candidate.value
            ->> 'pre_stage_gc_top10'
        )::boolean,
        false
      ) as pre_stage_gc_top10,

      nullif(
        candidate.value
          ->> 'pre_stage_gc_rank',
        ''
      )::integer as pre_stage_gc_rank,

      candidate.value as source_json
    from jsonb_array_elements(
      v_candidate_array
    ) candidate
    where nullif(
            candidate.value ->> 'rider_id',
            ''
          ) is not null
      and nullif(
            candidate.value
              ->> 'participant_club_id',
            ''
          ) is not null
      and lower(
            coalesce(
              candidate.value ->> 'action',
              ''
            )
          ) in (
            'attack',
            'join_breakaway',
            'chase_breakaway'
          )
  ),
  deduplicated as (
    select distinct on (rider_id)
      candidate_rows.*
    from candidate_rows
    order by
      rider_id,
      case action
        when 'attack' then 1
        when 'join_breakaway' then 2
        when 'chase_breakaway' then 3
        else 9
      end,
      case action_source
        when 'explicit_individual_command' then 1
        when 'saved_role_default' then 2
        when 'saved_team_tactic_base' then 3
        else 9
      end
  ),
  attack_join as (
    select
      deduplicated.*,

      case
        when p_phase_number in (1, 2)
         and pre_stage_gc_top10
          then false
        else true
      end as controlled_wave_eligible,

      case action_source
        when 'explicit_individual_command' then 1
        when 'saved_role_default' then 2
        when 'saved_team_tactic_base' then 3
        else 9
      end as source_rank,

      case role_code
        when 'breakaway_rider' then 1
        when 'rouleur' then 2
        when 'breakaway_chaser' then 3
        when 'free_role' then 4
        when 'helper_domestique' then 5
        when 'mountain_domestique' then 6
        else 7
      end as role_rank,

      case
        when v_terrain_type in (
          'mountain',
          'hilly',
          'climb'
        )
          then climbing
        else flat
      end as terrain_skill,

      md5(
        p_stage_id::text
        || ':'
        || p_phase_number::text
        || ':'
        || rider_id::text
      ) as deterministic_tie_key
    from deduplicated
    where action in (
      'attack',
      'join_breakaway'
    )
  ),
  controlled_intents as (
    select *
    from attack_join
    where controlled_wave_eligible
  ),
  intent_stats as (
    select
      count(*) filter (
        where action = 'attack'
      )::integer as attacker_count,

      count(
        distinct participant_club_id
      ) filter (
        where not is_ai
          and action = 'attack'
      )::integer as human_attack_team_count,

      count(
        distinct participant_club_id
      ) filter (
        where not is_ai
          and action in (
            'attack',
            'join_breakaway'
          )
      )::integer as human_intent_team_count,

      (
        min(participant_club_id::text) filter (
          where not is_ai
            and action = 'attack'
        )
      )::uuid as single_human_attack_club
    from controlled_intents
  ),
  ranked_controlled as (
    select
      controlled_intents.*,

      row_number() over (
        order by
          case action
            when 'attack' then 1
            when 'join_breakaway' then 2
            else 9
          end,
          source_rank,
          role_rank,
          terrain_skill desc,
          endurance desc,
          race_iq desc,
          resistance desc,
          teamwork desc,
          deterministic_tie_key
      ) as global_rank,

      row_number() over (
        partition by is_ai
        order by
          case action
            when 'attack' then 1
            when 'join_breakaway' then 2
            else 9
          end,
          source_rank,
          role_rank,
          terrain_skill desc,
          endurance desc,
          race_iq desc,
          resistance desc,
          teamwork desc,
          deterministic_tie_key
      ) as ai_partition_rank
    from controlled_intents
  ),
  scenario_allowed as (
    select ranked.*
    from ranked_controlled ranked
    cross join intent_stats stats
    where stats.attacker_count > 0
      and (
        not (
          stats.human_attack_team_count = 1
          and stats.human_intent_team_count = 1
        )
        or (
          not ranked.is_ai
          and ranked.participant_club_id =
            stats.single_human_attack_club
        )
        or (
          ranked.is_ai
          and ranked.ai_partition_rank <= 2
        )
      )
  ),
  final_ranked as (
    select
      scenario_allowed.*,
      row_number() over (
        order by
          case action
            when 'attack' then 1
            when 'join_breakaway' then 2
            else 9
          end,
          source_rank,
          role_rank,
          terrain_skill desc,
          endurance desc,
          race_iq desc,
          resistance desc,
          teamwork desc,
          deterministic_tie_key
      ) as selected_rank
    from scenario_allowed
  ),
  selected as (
    select *
    from final_ranked
    where selected_rank <=
      v_effective_wave_cap
  ),
  selected_stats as (
    select
      count(*)::integer as selected_count,
      ceil(count(*)::numeric / 2.0)::integer
        as first_wave_size,
      count(*) filter (
        where is_ai
      )::integer as selected_ai_count,
      count(
        distinct participant_club_id
      )::integer as selected_team_count,
      count(*) -
        count(distinct rider_id)
        as duplicate_rider_count
    from selected
  ),
  selected_with_wave as (
    select
      selected.*,
      case
        when selected.selected_rank <=
          selected_stats.first_wave_size
          then 'first_wave'
        else 'second_wave'
      end as wave_code
    from selected
    cross join selected_stats
  ),
  chasers as (
    select
      deduplicated.*,
      case action_source
        when 'explicit_individual_command' then 1
        when 'saved_role_default' then 2
        when 'saved_team_tactic_base' then 3
        else 9
      end as source_rank,
      case
        when v_terrain_type in (
          'mountain',
          'hilly',
          'climb'
        )
          then climbing
        else flat
      end as terrain_skill,
      md5(
        p_stage_id::text
        || ':'
        || p_phase_number::text
        || ':chase:'
        || rider_id::text
      ) as deterministic_tie_key
    from deduplicated
    where action = 'chase_breakaway'
  ),
  team_intents as (
    select
      participant_club_id,
      is_ai,
      count(*) filter (
        where action = 'attack'
      )::integer as attack_count,
      count(*) filter (
        where action = 'join_breakaway'
      )::integer as join_count,
      count(*) filter (
        where action = 'chase_breakaway'
      )::integer as chase_count
    from deduplicated
    group by participant_club_id, is_ai
  )
  select jsonb_build_object(
    'raw_candidate_count',
      (select count(*) from candidate_rows),

    'deduplicated_candidate_count',
      (select count(*) from deduplicated),

    'eligible_attacker_count',
      (
        select count(*)
        from attack_join
        where action = 'attack'
          and controlled_wave_eligible
      ),

    'eligible_joiner_count',
      (
        select count(*)
        from attack_join
        where action = 'join_breakaway'
          and controlled_wave_eligible
      ),

    'eligible_chaser_count',
      (select count(*) from chasers),

    'dangerous_gc_intent_count',
      (
        select count(*)
        from attack_join
        where not controlled_wave_eligible
      ),

    'human_attack_team_count',
      (
        select human_attack_team_count
        from intent_stats
      ),

    'human_intent_team_count',
      (
        select human_intent_team_count
        from intent_stats
      ),

    'single_human_team_ai_follower_scenario',
      (
        select
          human_attack_team_count = 1
          and human_intent_team_count = 1
        from intent_stats
      ),

    'selected_count',
      (select selected_count from selected_stats),

    'selected_team_count',
      (
        select selected_team_count
        from selected_stats
      ),

    'ai_followers_added',
      case
        when (
          select
            human_attack_team_count = 1
            and human_intent_team_count = 1
          from intent_stats
        )
        then (
          select selected_ai_count
          from selected_stats
        )
        else 0
      end,

    'duplicate_rider_count',
      (
        select duplicate_rider_count
        from selected_stats
      ),

    'join_only_escape_blocked',
      (
        select
          attacker_count = 0
          and exists (
            select 1
            from controlled_intents
            where action = 'join_breakaway'
          )
          and (
            select selected_count
            from selected_stats
          ) = 0
        from intent_stats
      ),

    'mass_escape_guard_pass',
      (
        select
          selected_count <= v_effective_wave_cap
          and duplicate_rider_count = 0
        from selected_stats
      ),

    'first_wave',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'wave_code', wave_code,
                 'selected_rank', selected_rank,
                 'selection_source_rank',
                   source_rank,
                 'role_suitability_rank',
                   role_rank,
                 'terrain_skill',
                   terrain_skill,
                 'controlled_wave_eligible',
                   controlled_wave_eligible
               )
            order by selected_rank
          ),
          '[]'::jsonb
        )
        from selected_with_wave
        where wave_code = 'first_wave'
      ),

    'second_wave',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'wave_code', wave_code,
                 'selected_rank', selected_rank,
                 'selection_source_rank',
                   source_rank,
                 'role_suitability_rank',
                   role_rank,
                 'terrain_skill',
                   terrain_skill,
                 'controlled_wave_eligible',
                   controlled_wave_eligible
               )
            order by selected_rank
          ),
          '[]'::jsonb
        )
        from selected_with_wave
        where wave_code = 'second_wave'
      ),

    'eligible_attackers',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'controlled_wave_eligible',
                   controlled_wave_eligible,
                 'selection_source_rank',
                   source_rank,
                 'role_suitability_rank',
                   role_rank,
                 'terrain_skill',
                   terrain_skill
               )
            order by
              source_rank,
              role_rank,
              terrain_skill desc,
              endurance desc,
              race_iq desc,
              resistance desc,
              teamwork desc,
              deterministic_tie_key
          ),
          '[]'::jsonb
        )
        from attack_join
        where action = 'attack'
      ),

    'eligible_joiners',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'controlled_wave_eligible',
                   controlled_wave_eligible,
                 'selection_source_rank',
                   source_rank,
                 'role_suitability_rank',
                   role_rank,
                 'terrain_skill',
                   terrain_skill
               )
            order by
              source_rank,
              role_rank,
              terrain_skill desc,
              endurance desc,
              race_iq desc,
              resistance desc,
              teamwork desc,
              deterministic_tie_key
          ),
          '[]'::jsonb
        )
        from attack_join
        where action = 'join_breakaway'
      ),

    'eligible_chasers',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'selection_source_rank',
                   source_rank,
                 'terrain_skill',
                   terrain_skill
               )
            order by
              source_rank,
              terrain_skill desc,
              endurance desc,
              race_iq desc,
              resistance desc,
              teamwork desc,
              deterministic_tie_key
          ),
          '[]'::jsonb
        )
        from chasers
      ),

    'dangerous_gc_attack_intents',
      (
        select coalesce(
          jsonb_agg(
            source_json
            || jsonb_build_object(
                 'controlled_wave_eligible',
                   false,
                 'exclusion_reason',
                   'phase_1_2_pre_stage_gc_top10'
               )
            order by
              pre_stage_gc_rank,
              rider_id
          ),
          '[]'::jsonb
        )
        from attack_join
        where not controlled_wave_eligible
      ),

    'per_team_intents',
      (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'participant_club_id',
                participant_club_id,
              'is_ai', is_ai,
              'attack_count', attack_count,
              'join_count', join_count,
              'chase_count', chase_count
            )
            order by
              is_ai,
              participant_club_id
          ),
          '[]'::jsonb
        )
        from team_intents
      )
  )
  into v_selection;

  v_result_without_hash :=
    jsonb_build_object(
      'builder_schema_version',
        'race_engine_locked_attack_waves_v1',
      'status', 'built',
      'stage_id', p_stage_id,
      'race_id', v_race_id,
      'stage_number', v_stage_number,
      'phase_number', p_phase_number,
      'phase_key', v_phase_key,
      'context_source', v_context_source,
      'terrain_type', v_terrain_type,
      'race_category', v_race_category,
      'stage_distance_km', v_stage_distance_km,

      'selection_contract',
        jsonb_build_object(
          'human_commands_from_locked_resolver_only',
            p_canary_context_json is null,
          'canary_context_used',
            p_canary_context_json is not null,
          'join_requires_eligible_attack',
            true,
          'chase_separate_from_attack_wave',
            true,
          'phase_1_2_gc_top10_controlled_wave_exclusion',
            true,
          'single_human_team_ai_follower_limit',
            2,
          'current_selector_base_cap',
            v_base_wave_cap,
          'average_locked_team_size_cap',
            v_average_team_size_cap,
          'effective_wave_cap',
            v_effective_wave_cap,
          'physical_execution_deferred',
            true
        ),

      'population',
        jsonb_build_object(
          'locked_plan_count', v_team_count,
          'locked_rider_count',
            v_total_rider_count,
          'candidate_count',
            jsonb_array_length(v_candidate_array)
        ),

      'plan_evidence', v_plan_evidence,
      'invalid_plan_results',
        v_invalid_plan_results,
      'selection', v_selection
    );

  v_wave_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status', 'built',
    'stage_id', p_stage_id,
    'phase_number', p_phase_number,
    'wave_hash', v_wave_hash,
    'attack_wave_plan', v_result_without_hash
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_plan_locked_breakaway_physics_v1(p_stage_id uuid, p_phase_number integer, p_canary_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_canary_mode boolean;
  v_context_source text;

  v_wave_result jsonb;
  v_wave_plan jsonb;
  v_selection jsonb;
  v_first_wave jsonb;
  v_second_wave jsonb;
  v_chasers jsonb;

  v_stage_json jsonb := '{}'::jsonb;
  v_profile_json jsonb := '{}'::jsonb;
  v_stage_context jsonb := '{}'::jsonb;
  v_rider_state_context jsonb := '{}'::jsonb;
  v_support_evidence jsonb := '[]'::jsonb;

  v_race_id uuid;
  v_stage_distance_km numeric;
  v_stage_number integer;
  v_phase_start_km numeric;
  v_phase_end_km numeric;
  v_phase_length_km numeric;
  v_first_launch_km numeric;
  v_second_launch_km numeric;

  v_default_terrain text;
  v_weather_condition text;
  v_avg_wind_kmh numeric;

  v_first_peloton_speed_kmh numeric;
  v_second_peloton_speed_kmh numeric;
  v_first_speed_preview_target_step_km numeric;
  v_second_speed_preview_target_step_km numeric;
  v_first_speed_preview_row_count integer := 0;
  v_second_speed_preview_row_count integer := 0;
  v_first_speed_preview_numeric_speed_keys jsonb := '[]'::jsonb;
  v_second_speed_preview_numeric_speed_keys jsonb := '[]'::jsonb;
  v_speed_component_json jsonb;
  v_speed_component_numeric_speed_keys jsonb := '[]'::jsonb;

  v_item record;
  v_item_json jsonb;
  v_rider_id uuid;
  v_participant_club_id uuid;
  v_race_stage_plan_id uuid;
  v_action text;
  v_action_source text;
  v_role_code text;
  v_team_plan text;
  v_wave_code text;
  v_launch_km numeric;
  v_local_peloton_speed_kmh numeric;

  v_segment record;
  v_terrain_type text;
  v_slope_percent numeric;

  v_rider_state_json jsonb;
  v_resolver_json jsonb;
  v_intent_json jsonb;
  v_outcome_json jsonb;
  v_step_speed_json jsonb;
  v_step_energy_json jsonb;

  v_flat numeric;
  v_climbing numeric;
  v_endurance numeric;
  v_resistance numeric;
  v_race_iq numeric;
  v_teamwork numeric;
  v_recovery numeric;
  v_morale numeric;
  v_energy_before numeric;
  v_energy_after_baseline numeric;

  v_attack_intent_score numeric;
  v_attack_skill_score numeric;
  v_raw_effort_multiplier numeric;
  v_effective_effort_multiplier numeric;
  v_burst_duration_seconds numeric;
  v_energy_cost_pct numeric;
  v_stamina_cost_points numeric;
  v_fatigue_delta_basis numeric;

  v_initial_separation_seconds numeric;
  v_initial_separation_distance_km numeric;
  v_bridge_target_gap_seconds numeric;
  v_bridge_distance_km numeric;
  v_bridge_closing_speed_kmh numeric;
  v_bridge_duration_seconds numeric;

  v_attack_plans jsonb := '[]'::jsonb;
  v_bridge_plans jsonb := '[]'::jsonb;
  v_chase_plans jsonb := '[]'::jsonb;

  v_chase_team_count integer := 0;
  v_chase_multiplier numeric := 1.0;
  v_chase_increment numeric;
  v_chase_contributions jsonb := '[]'::jsonb;
  v_index integer;

  v_result_without_hash jsonb;
  v_physical_plan_hash text;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_required'
    );
  end if;

  if p_phase_number not between 1 and 4 then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'phase_number_must_be_between_1_and_4',
      'phase_number', p_phase_number
    );
  end if;

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01d_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if p_canary_context_json is not null
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'canary_context_requires_transaction_local_issue01d_canary_mode'
    );
  end if;

  if p_canary_context_json is not null then
    v_context_source := 'rollback_canary_context';

    v_wave_result :=
      coalesce(
        p_canary_context_json -> 'wave_result',
        '{}'::jsonb
      );

    v_stage_context :=
      coalesce(
        p_canary_context_json -> 'stage_context',
        '{}'::jsonb
      );

    v_rider_state_context :=
      coalesce(
        p_canary_context_json -> 'rider_states',
        '{}'::jsonb
      );

    v_support_evidence :=
      coalesce(
        p_canary_context_json -> 'support_evidence',
        '[]'::jsonb
      );

  else
    v_context_source :=
      'issue01c_locked_wave_builder';

    v_wave_result :=
      public.race_engine_build_locked_attack_waves_v1(
        p_stage_id,
        p_phase_number,
        null
      );

    select to_jsonb(stage_row)
    into v_stage_json
    from public.race_stages stage_row
    where stage_row.id = p_stage_id;

    if not found then
      return jsonb_build_object(
        'status', 'not_found',
        'reason', 'stage_not_found',
        'stage_id', p_stage_id
      );
    end if;

    select to_jsonb(profile_row)
    into v_profile_json
    from public.race_stage_profile_details profile_row
    where nullif(
            to_jsonb(profile_row) ->> 'stage_id',
            ''
          )::uuid = p_stage_id
    limit 1;

    v_profile_json :=
      coalesce(v_profile_json, '{}'::jsonb);

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'race_stage_plan_id',
            stage_plan.id,
          'participant_club_id',
            stage_plan.engine_stage_payload_json
              ->> 'club_id',
          'snapshot_hash',
            stage_plan.engine_stage_payload_json
              ->> 'snapshot_hash',
          'hidden_engine_multiplier_contract',
            stage_plan.engine_stage_payload_json
              -> 'hidden_engine_multiplier_contract',
          'authoritative_input_counts',
            stage_plan.engine_stage_payload_json
              -> 'authoritative_input_counts',
          'rider_equipment_json_hash',
            stage_plan.engine_stage_payload_json
              #>> '{source_hashes,rider_equipment_json}',
          'rider_supplies_json_hash',
            stage_plan.engine_stage_payload_json
              #>> '{source_hashes,rider_supplies_json}',
          'staff_snapshots_hash',
            stage_plan.engine_stage_payload_json
              #>> '{source_hashes,staff_snapshots}',
          'asset_snapshots_hash',
            stage_plan.engine_stage_payload_json
              #>> '{source_hashes,asset_snapshots}',
          'staff_assignment_count',
            jsonb_array_length(
              coalesce(
                stage_plan.engine_stage_payload_json
                  -> 'race_preparation_staff_snapshots',
                '[]'::jsonb
              )
            ),
          'asset_assignment_count',
            jsonb_array_length(
              coalesce(
                stage_plan.engine_stage_payload_json
                  -> 'race_preparation_asset_snapshots',
                '[]'::jsonb
              )
            ),
          'equipment_percentage_multiplier',
            stage_plan.engine_stage_payload_json
              #>> '{hidden_engine_multiplier_contract,equipment_percentage_multiplier}',
          'race_supply_percentage_multiplier',
            stage_plan.engine_stage_payload_json
              #>> '{hidden_engine_multiplier_contract,race_supply_percentage_multiplier}',
          'application_status',
            'evidence_only_until_issue01e'
        )
        order by stage_plan.id
      ),
      '[]'::jsonb
    )
    into v_support_evidence
    from public.race_stage_plans stage_plan
    where stage_plan.stage_id = p_stage_id
      and coalesce(
            stage_plan.engine_stage_payload_json,
            '{}'::jsonb
          ) <> '{}'::jsonb;
  end if;

  if coalesce(v_wave_result ->> 'status', '')
       <> 'built'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'issue01c_wave_plan_not_built',
      'stage_id', p_stage_id,
      'phase_number', p_phase_number,
      'wave_builder_status',
        v_wave_result ->> 'status',
      'wave_builder_reason',
        v_wave_result ->> 'reason'
    );
  end if;

  v_wave_plan :=
    coalesce(
      v_wave_result -> 'attack_wave_plan',
      '{}'::jsonb
    );

  v_selection :=
    coalesce(
      v_wave_plan -> 'selection',
      '{}'::jsonb
    );

  v_first_wave :=
    coalesce(
      v_selection -> 'first_wave',
      '[]'::jsonb
    );

  v_second_wave :=
    coalesce(
      v_selection -> 'second_wave',
      '[]'::jsonb
    );

  v_chasers :=
    coalesce(
      v_selection -> 'eligible_chasers',
      '[]'::jsonb
    );

  if jsonb_typeof(v_first_wave)
       is distinct from 'array'
     or jsonb_typeof(v_second_wave)
       is distinct from 'array'
     or jsonb_typeof(v_chasers)
       is distinct from 'array'
  then
    return jsonb_build_object(
      'status', 'invalid_wave_plan',
      'reason', 'wave_and_chaser_sections_must_be_arrays'
    );
  end if;

  if p_canary_context_json is not null then
    v_race_id :=
      nullif(
        v_stage_context ->> 'race_id',
        ''
      )::uuid;

    v_stage_number :=
      coalesce(
        nullif(
          v_stage_context ->> 'stage_number',
          ''
        )::integer,
        1
      );

    v_stage_distance_km :=
      coalesce(
        nullif(
          v_stage_context ->> 'distance_km',
          ''
        )::numeric,
        nullif(
          v_wave_plan ->> 'stage_distance_km',
          ''
        )::numeric,
        0
      );

    v_default_terrain :=
      lower(
        coalesce(
          nullif(
            v_stage_context ->> 'terrain_type',
            ''
          ),
          nullif(
            v_wave_plan ->> 'terrain_type',
            ''
          ),
          'flat'
        )
      );

    v_weather_condition :=
      lower(
        coalesce(
          nullif(
            v_stage_context
              ->> 'weather_condition',
            ''
          ),
          'clear'
        )
      );

    v_avg_wind_kmh :=
      coalesce(
        nullif(
          v_stage_context ->> 'avg_wind_kmh',
          ''
        )::numeric,
        0
      );

  else
    v_race_id :=
      coalesce(
        nullif(
          v_wave_plan ->> 'race_id',
          ''
        )::uuid,
        nullif(
          v_stage_json ->> 'race_id',
          ''
        )::uuid
      );

    v_stage_number :=
      coalesce(
        nullif(
          v_wave_plan ->> 'stage_number',
          ''
        )::integer,
        nullif(
          v_stage_json ->> 'stage_number',
          ''
        )::integer,
        1
      );

    v_stage_distance_km :=
      coalesce(
        nullif(
          v_wave_plan ->> 'stage_distance_km',
          ''
        )::numeric,
        nullif(
          coalesce(
            v_stage_json ->> 'distance_km',
            v_stage_json ->> 'distance'
          ),
          ''
        )::numeric,
        0
      );

    v_default_terrain :=
      lower(
        coalesce(
          nullif(
            v_wave_plan ->> 'terrain_type',
            ''
          ),
          nullif(
            v_profile_json ->> 'terrain_type',
            ''
          ),
          nullif(
            v_stage_json ->> 'terrain_type',
            ''
          ),
          'flat'
        )
      );

    v_weather_condition :=
      lower(
        coalesce(
          nullif(
            v_profile_json
              #>> '{weather_snapshot,condition}',
            ''
          ),
          nullif(
            v_profile_json
              #>> '{weather_snapshot,weather_condition}',
            ''
          ),
          nullif(
            v_profile_json ->> 'weather_summary',
            ''
          ),
          'clear'
        )
      );

    v_avg_wind_kmh :=
      coalesce(
        nullif(
          v_profile_json
            #>> '{weather_snapshot,avg_wind_kmh}',
          ''
        )::numeric,
        nullif(
          v_profile_json
            #>> '{weather_snapshot,wind_kmh}',
          ''
        )::numeric,
        0
      );
  end if;

  if coalesce(v_stage_distance_km, 0) <= 0 then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'stage_distance_required',
      'stage_id', p_stage_id
    );
  end if;

  v_phase_start_km :=
    round(
      (
        v_stage_distance_km
        * (p_phase_number - 1)::numeric
        / 4.0
      )::numeric,
      3
    );

  v_phase_end_km :=
    round(
      (
        v_stage_distance_km
        * p_phase_number::numeric
        / 4.0
      )::numeric,
      3
    );

  v_phase_length_km :=
    greatest(
      0.1::numeric,
      v_phase_end_km - v_phase_start_km
    );

  v_first_launch_km :=
    round(
      least(
        v_phase_end_km - 0.5,
        v_phase_start_km
        + greatest(
            0.5::numeric,
            least(
              2.0::numeric,
              v_phase_length_km * 0.10
            )
          )
      )::numeric,
      3
    );

  v_second_launch_km :=
    round(
      least(
        v_phase_end_km - 0.2,
        v_first_launch_km
        + least(
            3.5::numeric,
            greatest(
              1.5::numeric,
              v_phase_length_km * 0.15
            )
          )
      )::numeric,
      3
    );

  if jsonb_array_length(v_second_wave) > 0
     and v_second_launch_km <= v_first_launch_km
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'distinct_wave_launch_points_unavailable',
      'phase_start_km', v_phase_start_km,
      'phase_end_km', v_phase_end_km
    );
  end if;

  v_first_speed_preview_target_step_km :=
    round(
      least(
        5.0::numeric,
        greatest(
          0.1::numeric,
          v_first_launch_km - v_phase_start_km
        )
      )::numeric,
      3
    );

  v_second_speed_preview_target_step_km :=
    round(
      least(
        5.0::numeric,
        greatest(
          0.1::numeric,
          v_second_launch_km - v_phase_start_km
        )
      )::numeric,
      3
    );

  if p_canary_context_json is not null then
    v_first_peloton_speed_kmh :=
      nullif(
        v_stage_context
          ->> 'first_wave_peloton_speed_kmh',
        ''
      )::numeric;

    v_second_peloton_speed_kmh :=
      coalesce(
        nullif(
          v_stage_context
            ->> 'second_wave_peloton_speed_kmh',
          ''
        )::numeric,
        v_first_peloton_speed_kmh
      );

  else
    with preview_rows as (
      select to_jsonb(speed_row) as row_json
      from public.race_engine_get_stage_rider_step_speed_preview_v2(
        p_stage_id,
        v_first_speed_preview_target_step_km
      ) speed_row
    ),
    extracted as (
      select
        (
          select (field.value #>> '{}')::numeric
          from jsonb_each(preview.row_json) field
          where jsonb_typeof(field.value) = 'number'
            and lower(field.key) like '%speed%'
            and (field.value #>> '{}')::numeric > 0
          order by
            case lower(field.key)
              when 'rider_free_speed_kmh' then 1
              when 'final_speed_kmh' then 2
              when 'effective_speed_kmh' then 3
              when 'energy_adjusted_speed_kmh' then 4
              when 'adjusted_speed_kmh' then 5
              when 'projected_speed_kmh' then 6
              when 'terrain_adjusted_speed_kmh' then 7
              when 'weather_adjusted_speed_kmh' then 8
              when 'base_speed_kmh' then 9
              when 'speed_kmh' then 10
              else 50
            end,
            field.key
          limit 1
        ) as speed_value
      from preview_rows preview
    )
    select
      count(*)::integer,
      percentile_cont(0.5)
        within group (order by speed_value)
        filter (where speed_value > 0)
    into
      v_first_speed_preview_row_count,
      v_first_peloton_speed_kmh
    from extracted;

    select coalesce(
      jsonb_agg(distinct field.key order by field.key),
      '[]'::jsonb
    )
    into v_first_speed_preview_numeric_speed_keys
    from public.race_engine_get_stage_rider_step_speed_preview_v2(
      p_stage_id,
      v_first_speed_preview_target_step_km
    ) speed_row
    cross join lateral jsonb_each(
      to_jsonb(speed_row)
    ) field
    where jsonb_typeof(field.value) = 'number'
      and lower(field.key) like '%speed%';

    with preview_rows as (
      select to_jsonb(speed_row) as row_json
      from public.race_engine_get_stage_rider_step_speed_preview_v2(
        p_stage_id,
        v_second_speed_preview_target_step_km
      ) speed_row
    ),
    extracted as (
      select
        (
          select (field.value #>> '{}')::numeric
          from jsonb_each(preview.row_json) field
          where jsonb_typeof(field.value) = 'number'
            and lower(field.key) like '%speed%'
            and (field.value #>> '{}')::numeric > 0
          order by
            case lower(field.key)
              when 'rider_free_speed_kmh' then 1
              when 'final_speed_kmh' then 2
              when 'effective_speed_kmh' then 3
              when 'energy_adjusted_speed_kmh' then 4
              when 'adjusted_speed_kmh' then 5
              when 'projected_speed_kmh' then 6
              when 'terrain_adjusted_speed_kmh' then 7
              when 'weather_adjusted_speed_kmh' then 8
              when 'base_speed_kmh' then 9
              when 'speed_kmh' then 10
              else 50
            end,
            field.key
          limit 1
        ) as speed_value
      from preview_rows preview
    )
    select
      count(*)::integer,
      percentile_cont(0.5)
        within group (order by speed_value)
        filter (where speed_value > 0)
    into
      v_second_speed_preview_row_count,
      v_second_peloton_speed_kmh
    from extracted;

    select coalesce(
      jsonb_agg(distinct field.key order by field.key),
      '[]'::jsonb
    )
    into v_second_speed_preview_numeric_speed_keys
    from public.race_engine_get_stage_rider_step_speed_preview_v2(
      p_stage_id,
      v_second_speed_preview_target_step_km
    ) speed_row
    cross join lateral jsonb_each(
      to_jsonb(speed_row)
    ) field
    where jsonb_typeof(field.value) = 'number'
      and lower(field.key) like '%speed%';
  end if;

  if coalesce(v_first_peloton_speed_kmh, 0) <= 0 then
    select to_jsonb(speed_components)
    into v_speed_component_json
    from public.race_engine_calculate_step_speed_components_v2(
      v_default_terrain,
      0,
      v_weather_condition,
      v_avg_wind_kmh,
      50,
      1.0
    ) speed_components;

    select
      (field.value #>> '{}')::numeric
    into v_first_peloton_speed_kmh
    from jsonb_each(
      coalesce(v_speed_component_json, '{}'::jsonb)
    ) field
    where jsonb_typeof(field.value) = 'number'
      and lower(field.key) like '%speed%'
      and (field.value #>> '{}')::numeric > 0
    order by
      case lower(field.key)
        when 'final_speed_kmh' then 1
        when 'effective_speed_kmh' then 2
        when 'adjusted_speed_kmh' then 3
        when 'projected_speed_kmh' then 4
        when 'terrain_adjusted_speed_kmh' then 5
        when 'weather_adjusted_speed_kmh' then 6
        when 'base_speed_kmh' then 7
        when 'speed_kmh' then 8
        else 50
      end,
      field.key
    limit 1;

    select coalesce(
      jsonb_agg(field.key order by field.key),
      '[]'::jsonb
    )
    into v_speed_component_numeric_speed_keys
    from jsonb_each(
      coalesce(v_speed_component_json, '{}'::jsonb)
    ) field
    where jsonb_typeof(field.value) = 'number'
      and lower(field.key) like '%speed%';
  end if;

  if coalesce(v_second_peloton_speed_kmh, 0) <= 0 then
    v_second_peloton_speed_kmh :=
      v_first_peloton_speed_kmh;
  end if;

  if coalesce(v_first_peloton_speed_kmh, 0) <= 0
     or coalesce(v_second_peloton_speed_kmh, 0) <= 0
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'canonical_local_peloton_speed_unavailable',
      'first_wave_launch_km', v_first_launch_km,
      'second_wave_launch_km',
        v_second_launch_km,
      'first_speed_preview_target_step_km',
        v_first_speed_preview_target_step_km,
      'second_speed_preview_target_step_km',
        v_second_speed_preview_target_step_km,
      'preview_target_step_contract',
        'local_step_length_clamped_to_0_1_5_0_km_not_absolute_race_km',
      'first_speed_preview_row_count',
        v_first_speed_preview_row_count,
      'second_speed_preview_row_count',
        v_second_speed_preview_row_count,
      'first_speed_preview_numeric_speed_keys',
        v_first_speed_preview_numeric_speed_keys,
      'second_speed_preview_numeric_speed_keys',
        v_second_speed_preview_numeric_speed_keys,
      'canonical_speed_component_numeric_speed_keys',
        v_speed_component_numeric_speed_keys,
      'canonical_speed_component_evidence',
        v_speed_component_json
    );
  end if;

  for v_item in
    select
      'first_wave'::text as wave_code,
      wave_item.value as item_json
    from jsonb_array_elements(v_first_wave)
      wave_item

    union all

    select
      'second_wave'::text,
      wave_item.value
    from jsonb_array_elements(v_second_wave)
      wave_item
  loop
    v_wave_code := v_item.wave_code;
    v_item_json := v_item.item_json;

    begin
      v_rider_id :=
        nullif(
          v_item_json ->> 'rider_id',
          ''
        )::uuid;

      v_participant_club_id :=
        nullif(
          v_item_json
            ->> 'participant_club_id',
          ''
        )::uuid;

      v_race_stage_plan_id :=
        nullif(
          v_item_json
            ->> 'race_stage_plan_id',
          ''
        )::uuid;
    exception
      when invalid_text_representation then
        continue;
    end;

    v_action :=
      lower(
        coalesce(
          nullif(v_item_json ->> 'action', ''),
          'attack'
        )
      );

    if v_action not in (
      'attack',
      'join_breakaway'
    ) then
      continue;
    end if;

    v_action_source :=
      coalesce(
        nullif(
          v_item_json ->> 'action_source',
          ''
        ),
        'unresolved'
      );

    v_role_code :=
      lower(
        coalesce(
          nullif(
            v_item_json ->> 'role_code',
            ''
          ),
          'free_role'
        )
      );

    v_launch_km :=
      case v_wave_code
        when 'first_wave'
          then v_first_launch_km
        else v_second_launch_km
      end;

    v_local_peloton_speed_kmh :=
      case v_wave_code
        when 'first_wave'
          then v_first_peloton_speed_kmh
        else v_second_peloton_speed_kmh
      end;

    select segment_row.*
    into v_segment
    from public.race_engine_get_stage_segments_v1(
      p_stage_id
    ) segment_row
    where p_canary_context_json is null
      and v_launch_km >= segment_row.km_start
      and v_launch_km <
          greatest(
            segment_row.km_end,
            segment_row.km_start + 0.001
          )
    order by segment_row.segment_order
    limit 1;

    if p_canary_context_json is not null then
      v_terrain_type :=
        lower(
          coalesce(
            nullif(
              v_stage_context
                ->> 'terrain_type',
              ''
            ),
            v_default_terrain
          )
        );

      v_slope_percent :=
        coalesce(
          nullif(
            v_stage_context
              ->> 'slope_percent',
            ''
          )::numeric,
          0
        );
    else
      v_terrain_type :=
        lower(
          coalesce(
            nullif(v_segment.terrain_type, ''),
            v_default_terrain
          )
        );

      v_slope_percent :=
        coalesce(v_segment.slope_percent, 0);
    end if;

    if p_canary_context_json is not null then
      v_rider_state_json :=
        coalesce(
          v_rider_state_context
            -> v_rider_id::text,
          '{}'::jsonb
        );
    else
      select to_jsonb(input_row)
      into v_rider_state_json
      from public.race_engine_get_stage_rider_inputs_v1(
        p_stage_id
      ) input_row
      where input_row.rider_id = v_rider_id
      limit 1;

      v_rider_state_json :=
        coalesce(
          v_rider_state_json,
          '{}'::jsonb
        );
    end if;

    v_flat :=
      coalesce(
        nullif(
          v_item_json ->> 'flat',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'flat',
          ''
        )::numeric,
        50
      );

    v_climbing :=
      coalesce(
        nullif(
          v_item_json ->> 'climbing',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'climbing',
          ''
        )::numeric,
        50
      );

    v_endurance :=
      coalesce(
        nullif(
          v_item_json ->> 'endurance',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'endurance',
          ''
        )::numeric,
        50
      );

    v_resistance :=
      coalesce(
        nullif(
          v_item_json ->> 'resistance',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'resistance',
          ''
        )::numeric,
        50
      );

    v_race_iq :=
      coalesce(
        nullif(
          v_item_json ->> 'race_iq',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'race_iq',
          ''
        )::numeric,
        50
      );

    v_teamwork :=
      coalesce(
        nullif(
          v_item_json ->> 'teamwork',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'teamwork',
          ''
        )::numeric,
        50
      );

    v_recovery :=
      coalesce(
        nullif(
          v_rider_state_json ->> 'recovery',
          ''
        )::numeric,
        50
      );

    v_morale :=
      coalesce(
        nullif(
          v_rider_state_json ->> 'morale',
          ''
        )::numeric,
        50
      );

    v_energy_before :=
      coalesce(
        nullif(
          v_rider_state_json
            ->> 'energy_before_step',
          ''
        )::numeric,
        nullif(
          v_rider_state_json
            ->> 'start_stamina',
          ''
        )::numeric,
        100
      );

    v_energy_after_baseline :=
      coalesce(
        nullif(
          v_rider_state_json
            ->> 'energy_after_step',
          ''
        )::numeric,
        v_energy_before
      );

    v_team_plan :=
      lower(
        coalesce(
          nullif(
            v_item_json ->> 'team_plan',
            ''
          ),
          'balanced'
        )
      );

    if v_race_stage_plan_id is not null
       and p_canary_context_json is null
    then
      v_resolver_json :=
        public.race_engine_resolve_locked_stage_tactical_plan_v1(
          v_race_stage_plan_id
        );

      v_team_plan :=
        lower(
          coalesce(
            nullif(
              v_resolver_json
                #>> '{resolved_plan,team_plan}',
              ''
            ),
            v_team_plan
          )
        );
    end if;

    select to_jsonb(intent_components)
    into v_intent_json
    from public.race_engine_calculate_attack_intent_components_v2(
      v_role_code,
      v_team_plan,
      v_action,
      p_phase_number,
      v_launch_km,
      v_stage_distance_km,
      12,
      v_terrain_type,
      v_slope_percent,
      'main_peloton',
      v_energy_before,
      v_energy_after_baseline,
      v_flat,
      v_climbing,
      v_endurance,
      v_resistance,
      v_race_iq,
      v_morale,
      0,
      false
    ) intent_components;

    v_attack_intent_score :=
      coalesce(
        nullif(
          v_intent_json
            ->> 'attack_intent_score',
          ''
        )::numeric,
        50
      );

    select to_jsonb(outcome_components)
    into v_outcome_json
    from public.race_engine_calculate_attack_outcome_components_v2(
      v_role_code,
      v_terrain_type,
      v_slope_percent,
      greatest(
        0,
        least(
          1,
          v_launch_km
          / nullif(v_stage_distance_km, 0)
        )
      ),
      v_attack_intent_score,
      v_energy_before,
      v_energy_after_baseline,
      v_flat,
      v_climbing,
      v_endurance,
      v_resistance,
      v_race_iq,
      v_morale,
      v_action_source =
        'explicit_individual_command',
      greatest(
        1,
        jsonb_array_length(
          case v_wave_code
            when 'first_wave' then v_first_wave
            else v_second_wave
          end
        )
      ),
      1,
      1
    ) outcome_components;

    v_attack_skill_score :=
      coalesce(
        nullif(
          v_outcome_json
            ->> 'attack_execution_skill_score',
          ''
        )::numeric,
        50
      );

    v_raw_effort_multiplier :=
      coalesce(
        nullif(
          v_outcome_json
            ->> 'projected_burst_speed_multiplier',
          ''
        )::numeric,
        1.10
      );

    v_effective_effort_multiplier :=
      least(
        1.20::numeric,
        greatest(
          1.10::numeric,
          v_raw_effort_multiplier
        )
      );

    v_burst_duration_seconds :=
      greatest(
        5::numeric,
        coalesce(
          nullif(
            v_outcome_json
              ->> 'projected_burst_duration_seconds',
            ''
          )::numeric,
          20
        )
      );

    v_energy_cost_pct :=
      greatest(
        0::numeric,
        coalesce(
          nullif(
            v_outcome_json
              ->> 'projected_attack_energy_cost_pct',
            ''
          )::numeric,
          0
        )
      );

    v_stamina_cost_points :=
      round(
        (
          greatest(v_energy_before, 0)
          * v_energy_cost_pct
          / 100.0
        )::numeric,
        3
      );

    v_fatigue_delta_basis :=
      round(v_energy_cost_pct::numeric, 3);

    select to_jsonb(speed_components)
    into v_step_speed_json
    from public.race_engine_calculate_step_speed_components_v2(
      v_terrain_type,
      v_slope_percent,
      v_weather_condition,
      v_avg_wind_kmh,
      v_attack_skill_score,
      v_effective_effort_multiplier
    ) speed_components;

    select to_jsonb(energy_components)
    into v_step_energy_json
    from public.race_engine_calculate_step_energy_components_v2(
      v_terrain_type,
      v_slope_percent,
      greatest(
        0.1::numeric,
        (
          v_local_peloton_speed_kmh
          * v_burst_duration_seconds
          / 3600.0
        )
      ),
      v_weather_condition,
      v_avg_wind_kmh,
      v_effective_effort_multiplier,
      v_endurance,
      v_resistance,
      v_recovery,
      1.0
    ) energy_components;

    if v_action = 'join_breakaway' then
      v_bridge_target_gap_seconds :=
        case v_wave_code
          when 'first_wave' then 8
          else 20
        end;

      v_bridge_distance_km :=
        round(
          (
            v_local_peloton_speed_kmh
            * v_bridge_target_gap_seconds
            / 3600.0
          )::numeric,
          4
        );

      v_bridge_closing_speed_kmh :=
        round(
          (
            v_local_peloton_speed_kmh
            * greatest(
                0.01::numeric,
                v_effective_effort_multiplier - 1.0
              )
          )::numeric,
          3
        );

      v_bridge_duration_seconds :=
        round(
          (
            v_bridge_distance_km
            / nullif(
                v_bridge_closing_speed_kmh,
                0
              )
            * 3600.0
          )::numeric,
          2
        );

      v_bridge_plans :=
        v_bridge_plans
        || jsonb_build_array(
             v_item_json
             || jsonb_build_object(
                  'wave_code', v_wave_code,
                  'launch_km', v_launch_km,
                  'local_peloton_speed_kmh',
                    round(
                      v_local_peloton_speed_kmh::numeric,
                      3
                    ),
                  'terrain_type', v_terrain_type,
                  'slope_percent', v_slope_percent,
                  'weather_condition',
                    v_weather_condition,
                  'avg_wind_kmh',
                    v_avg_wind_kmh,
                  'raw_effort_multiplier',
                    round(
                      v_raw_effort_multiplier::numeric,
                      4
                    ),
                  'effective_effort_multiplier',
                    round(
                      v_effective_effort_multiplier::numeric,
                      4
                    ),
                  'bridge_target_gap_seconds',
                    v_bridge_target_gap_seconds,
                  'bridge_distance_km',
                    v_bridge_distance_km,
                  'bridge_closing_speed_kmh',
                    v_bridge_closing_speed_kmh,
                  'bridge_duration_seconds',
                    v_bridge_duration_seconds,
                  'teleport_allowed', false,
                  'direct_group_attachment_allowed',
                    false,
                  'projected_live_energy_cost_pct',
                    round(v_energy_cost_pct::numeric, 3),
                  'projected_stamina_cost_points',
                    v_stamina_cost_points,
                  'projected_post_stage_fatigue_delta',
                    v_fatigue_delta_basis,
                  'fatigue_delta_contract',
                    'additional_energy_cost_basis_only_final_conversion_issue01g',
                  'canonical_attack_intent_components',
                    v_intent_json,
                  'canonical_attack_outcome_components',
                    v_outcome_json,
                  'canonical_step_speed_components',
                    v_step_speed_json,
                  'canonical_step_energy_components',
                    v_step_energy_json
                )
           );

    else
      v_initial_separation_seconds :=
        round(
          (
            v_burst_duration_seconds
            * greatest(
                0::numeric,
                v_effective_effort_multiplier - 1.0
              )
          )::numeric,
          2
        );

      v_initial_separation_distance_km :=
        round(
          (
            v_local_peloton_speed_kmh
            * greatest(
                0::numeric,
                v_effective_effort_multiplier - 1.0
              )
            * v_burst_duration_seconds
            / 3600.0
          )::numeric,
          4
        );

      v_attack_plans :=
        v_attack_plans
        || jsonb_build_array(
             v_item_json
             || jsonb_build_object(
                  'wave_code', v_wave_code,
                  'launch_km', v_launch_km,
                  'local_peloton_speed_kmh',
                    round(
                      v_local_peloton_speed_kmh::numeric,
                      3
                    ),
                  'terrain_type', v_terrain_type,
                  'slope_percent', v_slope_percent,
                  'weather_condition',
                    v_weather_condition,
                  'avg_wind_kmh',
                    v_avg_wind_kmh,
                  'raw_effort_multiplier',
                    round(
                      v_raw_effort_multiplier::numeric,
                      4
                    ),
                  'effective_effort_multiplier',
                    round(
                      v_effective_effort_multiplier::numeric,
                      4
                    ),
                  'burst_duration_seconds',
                    round(
                      v_burst_duration_seconds::numeric,
                      2
                    ),
                  'initial_separation_seconds',
                    v_initial_separation_seconds,
                  'initial_separation_distance_km',
                    v_initial_separation_distance_km,
                  'projected_live_energy_cost_pct',
                    round(v_energy_cost_pct::numeric, 3),
                  'projected_stamina_cost_points',
                    v_stamina_cost_points,
                  'projected_post_stage_fatigue_delta',
                    v_fatigue_delta_basis,
                  'fatigue_delta_contract',
                    'additional_energy_cost_basis_only_final_conversion_issue01g',
                  'canonical_attack_intent_components',
                    v_intent_json,
                  'canonical_attack_outcome_components',
                    v_outcome_json,
                  'canonical_step_speed_components',
                    v_step_speed_json,
                  'canonical_step_energy_components',
                    v_step_energy_json
                )
           );
    end if;
  end loop;

  select count(
    distinct nullif(
      chase_item.value
        ->> 'participant_club_id',
      ''
    )
  )::integer
  into v_chase_team_count
  from jsonb_array_elements(v_chasers)
    chase_item;

  v_chase_team_count :=
    coalesce(v_chase_team_count, 0);

  v_chase_multiplier := 1.0;
  v_chase_contributions := '[]'::jsonb;

  if v_chase_team_count >= 1 then
    v_chase_multiplier := 1.04;

    v_chase_contributions :=
      jsonb_build_array(
        jsonb_build_object(
          'team_sequence', 1,
          'increment', 0.04,
          'contract',
            'first_committed_chase_team_3_to_5_percent'
        )
      );

    if v_chase_team_count > 1 then
      for v_index in 2..v_chase_team_count
      loop
        v_chase_increment :=
          greatest(
            0.010::numeric,
            0.015::numeric
            - ((v_index - 2)::numeric * 0.001)
          );

        if v_chase_multiplier >= 1.10 then
          v_chase_increment := 0;
        elsif v_chase_multiplier
              + v_chase_increment
              > 1.10
        then
          v_chase_increment :=
            1.10 - v_chase_multiplier;
        end if;

        v_chase_multiplier :=
          least(
            1.10::numeric,
            v_chase_multiplier
            + v_chase_increment
          );

        v_chase_contributions :=
          v_chase_contributions
          || jsonb_build_array(
               jsonb_build_object(
                 'team_sequence', v_index,
                 'increment',
                   round(
                     v_chase_increment::numeric,
                     4
                   ),
                 'contract',
                   'additional_chase_team_1_to_2_percent_diminishing'
               )
             );
      end loop;
    end if;
  end if;

  for v_item in
    select chase_item.value as item_json
    from jsonb_array_elements(v_chasers)
      chase_item
  loop
    v_item_json := v_item.item_json;

    begin
      v_rider_id :=
        nullif(
          v_item_json ->> 'rider_id',
          ''
        )::uuid;
    exception
      when invalid_text_representation then
        continue;
    end;

    v_action_source :=
      coalesce(
        nullif(
          v_item_json ->> 'action_source',
          ''
        ),
        'unresolved'
      );

    v_role_code :=
      lower(
        coalesce(
          nullif(
            v_item_json ->> 'role_code',
            ''
          ),
          'breakaway_chaser'
        )
      );

    if p_canary_context_json is not null then
      v_rider_state_json :=
        coalesce(
          v_rider_state_context
            -> v_rider_id::text,
          '{}'::jsonb
        );
    else
      select to_jsonb(input_row)
      into v_rider_state_json
      from public.race_engine_get_stage_rider_inputs_v1(
        p_stage_id
      ) input_row
      where input_row.rider_id = v_rider_id
      limit 1;

      v_rider_state_json :=
        coalesce(
          v_rider_state_json,
          '{}'::jsonb
        );
    end if;

    v_flat :=
      coalesce(
        nullif(
          v_item_json ->> 'flat',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'flat',
          ''
        )::numeric,
        50
      );

    v_climbing :=
      coalesce(
        nullif(
          v_item_json ->> 'climbing',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'climbing',
          ''
        )::numeric,
        50
      );

    v_endurance :=
      coalesce(
        nullif(
          v_item_json ->> 'endurance',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'endurance',
          ''
        )::numeric,
        50
      );

    v_resistance :=
      coalesce(
        nullif(
          v_item_json ->> 'resistance',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'resistance',
          ''
        )::numeric,
        50
      );

    v_race_iq :=
      coalesce(
        nullif(
          v_item_json ->> 'race_iq',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'race_iq',
          ''
        )::numeric,
        50
      );

    v_teamwork :=
      coalesce(
        nullif(
          v_item_json ->> 'teamwork',
          ''
        )::numeric,
        nullif(
          v_rider_state_json ->> 'teamwork',
          ''
        )::numeric,
        50
      );

    v_recovery :=
      coalesce(
        nullif(
          v_rider_state_json ->> 'recovery',
          ''
        )::numeric,
        50
      );

    v_morale :=
      coalesce(
        nullif(
          v_rider_state_json ->> 'morale',
          ''
        )::numeric,
        50
      );

    v_energy_before :=
      coalesce(
        nullif(
          v_rider_state_json
            ->> 'energy_before_step',
          ''
        )::numeric,
        nullif(
          v_rider_state_json
            ->> 'start_stamina',
          ''
        )::numeric,
        100
      );

    v_energy_after_baseline :=
      coalesce(
        nullif(
          v_rider_state_json
            ->> 'energy_after_step',
          ''
        )::numeric,
        v_energy_before
      );

    v_launch_km := v_second_launch_km;
    v_terrain_type := v_default_terrain;
    v_slope_percent :=
      coalesce(
        nullif(
          v_stage_context ->> 'slope_percent',
          ''
        )::numeric,
        0
      );

    if p_canary_context_json is null then
      select segment_row.*
      into v_segment
      from public.race_engine_get_stage_segments_v1(
        p_stage_id
      ) segment_row
      where v_launch_km >= segment_row.km_start
        and v_launch_km <
            greatest(
              segment_row.km_end,
              segment_row.km_start + 0.001
            )
      order by segment_row.segment_order
      limit 1;

      v_terrain_type :=
        lower(
          coalesce(
            nullif(v_segment.terrain_type, ''),
            v_default_terrain
          )
        );

      v_slope_percent :=
        coalesce(v_segment.slope_percent, 0);
    end if;

    select to_jsonb(intent_components)
    into v_intent_json
    from public.race_engine_calculate_attack_intent_components_v2(
      v_role_code,
      'balanced',
      'chase_breakaway',
      p_phase_number,
      v_launch_km,
      v_stage_distance_km,
      12,
      v_terrain_type,
      v_slope_percent,
      'main_peloton',
      v_energy_before,
      v_energy_after_baseline,
      v_flat,
      v_climbing,
      v_endurance,
      v_resistance,
      v_race_iq,
      v_morale,
      0,
      false
    ) intent_components;

    v_attack_intent_score :=
      coalesce(
        nullif(
          v_intent_json
            ->> 'attack_intent_score',
          ''
        )::numeric,
        50
      );

    select to_jsonb(outcome_components)
    into v_outcome_json
    from public.race_engine_calculate_attack_outcome_components_v2(
      v_role_code,
      v_terrain_type,
      v_slope_percent,
      greatest(
        0,
        least(
          1,
          v_launch_km
          / nullif(v_stage_distance_km, 0)
        )
      ),
      v_attack_intent_score,
      v_energy_before,
      v_energy_after_baseline,
      v_flat,
      v_climbing,
      v_endurance,
      v_resistance,
      v_race_iq,
      v_morale,
      v_action_source =
        'explicit_individual_command',
      1,
      1,
      1
    ) outcome_components;

    v_energy_cost_pct :=
      greatest(
        0::numeric,
        coalesce(
          nullif(
            v_outcome_json
              ->> 'projected_attack_energy_cost_pct',
            ''
          )::numeric,
          0
        )
      );

    v_stamina_cost_points :=
      round(
        (
          greatest(v_energy_before, 0)
          * v_energy_cost_pct
          / 100.0
        )::numeric,
        3
      );

    v_fatigue_delta_basis :=
      round(v_energy_cost_pct::numeric, 3);

    select to_jsonb(speed_components)
    into v_step_speed_json
    from public.race_engine_calculate_step_speed_components_v2(
      v_terrain_type,
      v_slope_percent,
      v_weather_condition,
      v_avg_wind_kmh,
      coalesce(
        nullif(
          v_outcome_json
            ->> 'attack_execution_skill_score',
          ''
        )::numeric,
        50
      ),
      v_chase_multiplier
    ) speed_components;

    select to_jsonb(energy_components)
    into v_step_energy_json
    from public.race_engine_calculate_step_energy_components_v2(
      v_terrain_type,
      v_slope_percent,
      1.0,
      v_weather_condition,
      v_avg_wind_kmh,
      v_chase_multiplier,
      v_endurance,
      v_resistance,
      v_recovery,
      1.0
    ) energy_components;

    v_chase_plans :=
      v_chase_plans
      || jsonb_build_array(
           v_item_json
           || jsonb_build_object(
                'launch_km', v_launch_km,
                'front_position_required', true,
                'peloton_chase_team_count',
                  v_chase_team_count,
                'peloton_chase_speed_multiplier',
                  round(
                    v_chase_multiplier::numeric,
                    4
                  ),
                'projected_live_energy_cost_pct',
                  round(v_energy_cost_pct::numeric, 3),
                'projected_stamina_cost_points',
                  v_stamina_cost_points,
                'projected_post_stage_fatigue_delta',
                  v_fatigue_delta_basis,
                'fatigue_delta_contract',
                  'additional_energy_cost_basis_only_final_conversion_issue01g',
                'canonical_attack_intent_components',
                  v_intent_json,
                'canonical_attack_outcome_components',
                  v_outcome_json,
                'canonical_step_speed_components',
                  v_step_speed_json,
                'canonical_step_energy_components',
                  v_step_energy_json
              )
         );
  end loop;

  v_result_without_hash :=
    jsonb_build_object(
      'planner_schema_version',
        'race_engine_locked_breakaway_physics_v1',
      'status', 'planned',
      'stage_id', p_stage_id,
      'race_id', v_race_id,
      'stage_number', v_stage_number,
      'phase_number', p_phase_number,
      'context_source', v_context_source,
      'source_wave_hash',
        v_wave_result ->> 'wave_hash',

      'stage_context',
        jsonb_build_object(
          'distance_km', v_stage_distance_km,
          'default_terrain', v_default_terrain,
          'weather_condition',
            v_weather_condition,
          'avg_wind_kmh', v_avg_wind_kmh,
          'phase_start_km', v_phase_start_km,
          'phase_end_km', v_phase_end_km,
          'first_wave_launch_km',
            v_first_launch_km,
          'second_wave_launch_km',
            v_second_launch_km,
          'first_wave_local_peloton_speed_kmh',
            round(
              v_first_peloton_speed_kmh::numeric,
              3
            ),
          'second_wave_local_peloton_speed_kmh',
            round(
              v_second_peloton_speed_kmh::numeric,
              3
            ),
          'first_speed_preview_target_step_km',
            v_first_speed_preview_target_step_km,
          'second_speed_preview_target_step_km',
            v_second_speed_preview_target_step_km,
          'preview_target_step_contract',
            'local_step_length_clamped_to_0_1_5_0_km_not_absolute_race_km',
          'first_speed_preview_row_count',
            v_first_speed_preview_row_count,
          'second_speed_preview_row_count',
            v_second_speed_preview_row_count,
          'first_speed_preview_numeric_speed_keys',
            v_first_speed_preview_numeric_speed_keys,
          'second_speed_preview_numeric_speed_keys',
            v_second_speed_preview_numeric_speed_keys,
          'canonical_speed_component_numeric_speed_keys',
            v_speed_component_numeric_speed_keys
        ),

      'physical_contract',
        jsonb_build_object(
          'attack_effort_target_range',
            jsonb_build_array(1.10, 1.20),
          'join_teleport_allowed', false,
          'distinct_wave_launch_points',
            v_first_launch_km
            <> v_second_launch_km
            or jsonb_array_length(
                 v_second_wave
               ) = 0,
          'wave_spacing_max_km', 3.5,
          'first_chase_team_increment', 0.04,
          'additional_chase_team_increment_range',
            jsonb_build_array(0.01, 0.015),
          'peloton_chase_multiplier_cap',
            1.10,
          'replay_write_allowed', false,
          'group_membership_write_allowed',
            false,
          'direct_gap_write_allowed', false,
          'direct_speed_write_allowed', false,
          'runner_integration_allowed', false
        ),

      'attack_plans', v_attack_plans,
      'bridge_plans', v_bridge_plans,
      'chase_plans', v_chase_plans,

      'peloton_chase_plan',
        jsonb_build_object(
          'committed_team_count',
            v_chase_team_count,
          'speed_multiplier',
            round(
              v_chase_multiplier::numeric,
              4
            ),
          'team_contributions',
            v_chase_contributions,
          'diminishing_returns', true,
          'physical_cap', 1.10
        ),

      'locked_support_evidence',
        jsonb_build_object(
          'evidence_rows', v_support_evidence,
          'equipment_percentage_multiplier_expected',
            5,
          'race_supply_percentage_multiplier_expected',
            3,
          'performance_application_status',
            'deferred_to_issue01e',
          'replacement_coefficients_invented',
            false
        ),

      'energy_fatigue_contract',
        jsonb_build_object(
          'attack_bridge_chase_extra_costs_planned',
            true,
          'stamina_cost_points_planned', true,
          'post_stage_fatigue_delta_field_is_energy_cost_basis',
            true,
          'final_fatigue_conversion_deferred_to_issue01g',
            true,
          'next_stage_energy_carryover_deferred_to_issue01g',
            true
        ),

      'counts',
        jsonb_build_object(
          'attack_plans',
            jsonb_array_length(v_attack_plans),
          'bridge_plans',
            jsonb_array_length(v_bridge_plans),
          'chase_plans',
            jsonb_array_length(v_chase_plans),
          'support_evidence_rows',
            jsonb_array_length(
              coalesce(v_support_evidence, '[]'::jsonb)
            )
        )
    );

  v_physical_plan_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status', 'planned',
    'stage_id', p_stage_id,
    'phase_number', p_phase_number,
    'physical_plan_hash',
      v_physical_plan_hash,
    'physical_plan', v_result_without_hash
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_integrate_locked_phase_performance_v1(p_stage_id uuid, p_phase_number integer, p_canary_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_canary_mode boolean;
  v_context_source text;

  v_physical_result jsonb;
  v_physical_plan jsonb;
  v_attack_plans jsonb;
  v_bridge_plans jsonb;
  v_chase_plans jsonb;
  v_action_rows jsonb;

  v_locked_payloads jsonb := '[]'::jsonb;
  v_rider_snapshot_rows jsonb := '[]'::jsonb;
  v_supply_snapshot_rows jsonb := '[]'::jsonb;
  v_rain_requirement jsonb := '{}'::jsonb;

  v_action_record record;
  v_action_json jsonb;
  v_action_kind text;
  v_rider_id uuid;
  v_club_id uuid;
  v_stage_plan_id uuid;

  v_payload jsonb;
  v_multiplier_contract jsonb;
  v_equipment_multiplier numeric;
  v_supply_multiplier numeric;
  v_rider_supplies jsonb;
  v_equipment_selection jsonb;

  v_rider_snapshot jsonb;
  v_equipment_snapshot jsonb;
  v_final_bonus_snapshot jsonb;
  v_standardized_bonus jsonb;

  v_weighted_bonuses jsonb;
  v_caps jsonb;
  v_terrain_type text;
  v_terrain_bonus_key text;

  v_ui_equipment_pct numeric;
  v_ui_equipment_fatigue_pct numeric;
  v_equipment_stage_cap_pct numeric;
  v_equipment_fatigue_cap_pct numeric;
  v_condition_factor numeric;
  v_engine_equipment_pct numeric;
  v_engine_equipment_fatigue_pct numeric;

  v_race_support_pct numeric;
  v_fatigue_control_pct numeric;
  v_mechanical_reliability_pct numeric;

  v_bidons integer;
  v_gels integer;
  v_nutrition integer;
  v_rain_jacket boolean;
  v_race_jersey_complete boolean;
  v_active_gels integer;
  v_gel_ui_value_pct numeric := 5;
  v_gel_engine_live_energy_pct numeric;
  v_green_cap_pct numeric := 45;

  v_rain_required boolean;
  v_rain_efficiency_ui_pct numeric;
  v_rain_efficiency_engine_pct numeric;
  v_rain_sickness_risk_multiplier numeric;

  v_supply_effect_rows jsonb;
  v_supply_speed_ui_pct numeric;
  v_supply_energy_ui_pct numeric;
  v_supply_speed_engine_pct numeric;
  v_supply_energy_engine_pct numeric;
  v_unmapped_supply_effects jsonb;

  v_base_effort_multiplier numeric;
  v_equipment_speed_multiplier numeric;
  v_team_support_speed_multiplier numeric;
  v_supply_speed_multiplier numeric;
  v_rain_efficiency_multiplier numeric;
  v_integrated_speed_multiplier numeric;

  v_equipment_energy_multiplier numeric;
  v_team_fatigue_multiplier numeric;
  v_supply_energy_multiplier numeric;
  v_integrated_energy_cost_multiplier numeric;

  v_base_energy_cost_pct numeric;
  v_adjusted_energy_cost_pct numeric;
  v_base_stamina_cost_points numeric;
  v_adjusted_stamina_cost_points numeric;

  v_rider_plans jsonb := '[]'::jsonb;
  v_result_without_hash jsonb;
  v_integration_hash text;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_required'
    );
  end if;

  if p_phase_number not between 1 and 4 then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'phase_number_must_be_between_1_and_4',
      'phase_number', p_phase_number
    );
  end if;

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01e_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if p_canary_context_json is not null
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'canary_context_requires_transaction_local_issue01e_canary_mode'
    );
  end if;

  if p_canary_context_json is not null then
    v_context_source :=
      'rollback_canary_context';

    v_physical_result :=
      coalesce(
        p_canary_context_json
          -> 'physical_plan_result',
        '{}'::jsonb
      );

    v_locked_payloads :=
      coalesce(
        p_canary_context_json
          -> 'locked_payloads',
        '[]'::jsonb
      );

    v_rider_snapshot_rows :=
      coalesce(
        p_canary_context_json
          -> 'rider_snapshot_rows',
        '[]'::jsonb
      );

    v_supply_snapshot_rows :=
      coalesce(
        p_canary_context_json
          -> 'supply_snapshot_rows',
        '[]'::jsonb
      );

    v_rain_requirement :=
      coalesce(
        p_canary_context_json
          -> 'rain_requirement',
        '{}'::jsonb
      );

  else
    v_context_source :=
      'issue01d_physical_plan_and_immutable_stage_plan_snapshots';

    v_physical_result :=
      public.race_engine_plan_locked_breakaway_physics_v1(
        p_stage_id,
        p_phase_number,
        null
      );

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'race_stage_plan_id',
            stage_plan.id,
          'club_id',
            stage_plan.engine_stage_payload_json
              ->> 'club_id',
          'payload',
            stage_plan.engine_stage_payload_json
        )
        order by stage_plan.id
      ),
      '[]'::jsonb
    )
    into v_locked_payloads
    from public.race_stage_plans stage_plan
    where stage_plan.stage_id = p_stage_id
      and coalesce(
            stage_plan.engine_stage_payload_json,
            '{}'::jsonb
          ) <> '{}'::jsonb;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'race_stage_plan_id',
            plan_rider.race_stage_plan_id,
          'rider_id',
            plan_rider.rider_id,
          'equipment_bonus_snapshot_json',
            plan_rider.equipment_bonus_snapshot_json,
          'final_bonus_snapshot_json',
            plan_rider.final_bonus_snapshot_json,
          'rider_stage_snapshot_json',
            plan_rider.rider_stage_snapshot_json,
          'equipment_setup_id',
            plan_rider.equipment_setup_id
        )
        order by
          plan_rider.race_stage_plan_id,
          plan_rider.rider_id
      ),
      '[]'::jsonb
    )
    into v_rider_snapshot_rows
    from public.race_stage_plan_riders plan_rider
    join public.race_stage_plans stage_plan
      on stage_plan.id =
        plan_rider.race_stage_plan_id
    where stage_plan.stage_id = p_stage_id;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'race_stage_plan_id',
            plan_supply.race_stage_plan_id,
          'supply_key',
            plan_supply.supply_key,
          'quantity_planned',
            plan_supply.quantity_planned,
          'bonus_snapshot_json',
            plan_supply.bonus_snapshot_json,
          'supply_snapshot_json',
            plan_supply.supply_snapshot_json
        )
        order by
          plan_supply.race_stage_plan_id,
          plan_supply.supply_key
      ),
      '[]'::jsonb
    )
    into v_supply_snapshot_rows
    from public.race_stage_plan_supplies
      plan_supply
    join public.race_stage_plans stage_plan
      on stage_plan.id =
        plan_supply.race_stage_plan_id
    where stage_plan.stage_id = p_stage_id;

    v_rain_requirement :=
      public.race_engine_stage_rain_jacket_requirement_v1(
        p_stage_id
      );
  end if;

  if coalesce(
       v_physical_result ->> 'status',
       ''
     ) <> 'planned'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01d_physical_plan_not_planned',
      'physical_plan_status',
        v_physical_result ->> 'status',
      'physical_plan_reason',
        v_physical_result ->> 'reason'
    );
  end if;

  v_physical_plan :=
    coalesce(
      v_physical_result -> 'physical_plan',
      '{}'::jsonb
    );

  v_attack_plans :=
    coalesce(
      v_physical_plan -> 'attack_plans',
      '[]'::jsonb
    );

  v_bridge_plans :=
    coalesce(
      v_physical_plan -> 'bridge_plans',
      '[]'::jsonb
    );

  v_chase_plans :=
    coalesce(
      v_physical_plan -> 'chase_plans',
      '[]'::jsonb
    );

  v_action_rows :=
    (
      select coalesce(
        jsonb_agg(action_row),
        '[]'::jsonb
      )
      from (
        select
          action.value
          || jsonb_build_object(
               'integration_action_kind',
               'attack'
             ) as action_row
        from jsonb_array_elements(
          v_attack_plans
        ) action

        union all

        select
          action.value
          || jsonb_build_object(
               'integration_action_kind',
               'bridge'
             )
        from jsonb_array_elements(
          v_bridge_plans
        ) action

        union all

        select
          action.value
          || jsonb_build_object(
               'integration_action_kind',
               'chase'
             )
        from jsonb_array_elements(
          v_chase_plans
        ) action
      ) action_union
    );

  for v_action_record in
    select action.value as action_json
    from jsonb_array_elements(
      v_action_rows
    ) action
  loop
    v_action_json :=
      v_action_record.action_json;

    begin
      v_rider_id :=
        nullif(
          v_action_json ->> 'rider_id',
          ''
        )::uuid;

      v_club_id :=
        nullif(
          v_action_json
            ->> 'participant_club_id',
          ''
        )::uuid;
    exception
      when invalid_text_representation then
        continue;
    end;

    if v_rider_id is null
       or v_club_id is null
    then
      continue;
    end if;

    v_action_kind :=
      lower(
        coalesce(
          nullif(
            v_action_json
              ->> 'integration_action_kind',
            ''
          ),
          'unknown'
        )
      );

    select
      payload_row.value -> 'payload',
      nullif(
        payload_row.value
          ->> 'race_stage_plan_id',
        ''
      )::uuid
    into
      v_payload,
      v_stage_plan_id
    from jsonb_array_elements(
      v_locked_payloads
    ) payload_row
    where nullif(
            payload_row.value
              ->> 'club_id',
            ''
          )::uuid = v_club_id
      and (
        coalesce(
          payload_row.value
            #> '{payload,rider_supplies_json}',
          '{}'::jsonb
        ) ? v_rider_id::text
        or coalesce(
             payload_row.value
               #> '{payload,rider_equipment_json}',
             '{}'::jsonb
           ) ? v_rider_id::text
        or coalesce(
             payload_row.value
               #> '{payload,rider_roles_json}',
             '{}'::jsonb
           ) ? v_rider_id::text
      )
    order by
      payload_row.value
        ->> 'race_stage_plan_id'
    limit 1;

    if v_payload is null then
      v_rider_plans :=
        v_rider_plans
        || jsonb_build_array(
             v_action_json
             || jsonb_build_object(
                  'integration_status',
                    'blocked_missing_locked_payload',
                  'writes_allowed', false
                )
           );
      continue;
    end if;

    if coalesce(
         v_payload ->> 'snapshot_schema_version',
         ''
       ) <>
       'race_engine_stage_plan_input_snapshot_v1'
       or not coalesce(
            (
              v_payload ->> 'immutable'
            )::boolean,
            false
          )
    then
      v_rider_plans :=
        v_rider_plans
        || jsonb_build_array(
             v_action_json
             || jsonb_build_object(
                  'integration_status',
                    'blocked_invalid_locked_payload',
                  'snapshot_hash',
                    v_payload ->> 'snapshot_hash',
                  'writes_allowed', false
                )
           );
      continue;
    end if;

    v_multiplier_contract :=
      coalesce(
        v_payload
          -> 'hidden_engine_multiplier_contract',
        '{}'::jsonb
      );

    v_equipment_multiplier :=
      coalesce(
        nullif(
          v_multiplier_contract
            ->> 'equipment_percentage_multiplier',
          ''
        )::numeric,
        1
      );

    v_supply_multiplier :=
      coalesce(
        nullif(
          v_multiplier_contract
            ->> 'race_supply_percentage_multiplier',
          ''
        )::numeric,
        1
      );

    if v_equipment_multiplier <> 5
       or v_supply_multiplier <> 3
    then
      v_rider_plans :=
        v_rider_plans
        || jsonb_build_array(
             v_action_json
             || jsonb_build_object(
                  'integration_status',
                    'blocked_multiplier_contract_mismatch',
                  'equipment_multiplier',
                    v_equipment_multiplier,
                  'supply_multiplier',
                    v_supply_multiplier,
                  'writes_allowed', false
                )
           );
      continue;
    end if;

    v_rider_supplies :=
      coalesce(
        v_payload
          -> 'rider_supplies_json'
          -> v_rider_id::text,
        '{}'::jsonb
      );

    v_equipment_selection :=
      coalesce(
        v_payload
          -> 'rider_equipment_json'
          -> v_rider_id::text,
        'null'::jsonb
      );

    select
      snapshot_row.value
    into v_rider_snapshot
    from jsonb_array_elements(
      v_rider_snapshot_rows
    ) snapshot_row
    where nullif(
            snapshot_row.value
              ->> 'race_stage_plan_id',
            ''
          )::uuid =
          v_stage_plan_id
      and nullif(
            snapshot_row.value
              ->> 'rider_id',
            ''
          )::uuid =
          v_rider_id
    limit 1;

    v_rider_snapshot :=
      coalesce(
        v_rider_snapshot,
        '{}'::jsonb
      );

    v_equipment_snapshot :=
      coalesce(
        v_rider_snapshot
          -> 'equipment_bonus_snapshot_json',
        '{}'::jsonb
      );

    v_final_bonus_snapshot :=
      coalesce(
        v_rider_snapshot
          -> 'final_bonus_snapshot_json',
        '{}'::jsonb
      );

    v_standardized_bonus :=
      public.standardize_race_plan_bonus_preview_v1(
        coalesce(
          v_payload -> 'bonus_snapshot_json',
          '{}'::jsonb
        )
      );

    v_weighted_bonuses :=
      coalesce(
        jsonb_path_query_first(
          v_equipment_snapshot,
          '$.**.weighted_bonuses'
        ),
        jsonb_path_query_first(
          v_final_bonus_snapshot,
          '$.**.weighted_bonuses'
        ),
        '{}'::jsonb
      );

    v_caps :=
      coalesce(
        jsonb_path_query_first(
          v_equipment_snapshot,
          '$.**.caps'
        ),
        jsonb_path_query_first(
          v_final_bonus_snapshot,
          '$.**.caps'
        ),
        '{}'::jsonb
      );

    v_terrain_type :=
      lower(
        coalesce(
          nullif(
            v_action_json
              ->> 'terrain_type',
            ''
          ),
          nullif(
            v_physical_plan
              #>> '{stage_context,default_terrain}',
            ''
          ),
          'flat'
        )
      );

    v_terrain_bonus_key :=
      case
        when v_terrain_type ~
             '(time_trial|time trial|tt|prologue)'
          then 'time_trial_bonus_pct'
        when v_terrain_type ~
             '(mountain|climb|summit|steep)'
          then 'mountain_bonus_pct'
        when v_terrain_type ~
             '(hilly|rolling|undulating)'
          then 'hilly_bonus_pct'
        when v_terrain_type ~
             '(cobble|pav[eé])'
          then 'cobble_bonus_pct'
        when v_terrain_type ~
             '(sprint)'
          then 'sprint_bonus_pct'
        else 'flat_bonus_pct'
      end;

    v_equipment_stage_cap_pct :=
      coalesce(
        nullif(
          v_caps
            ->> 'equipment_stage_bonus_cap_pct',
          ''
        )::numeric,
        4
      );

    v_equipment_fatigue_cap_pct :=
      coalesce(
        nullif(
          v_caps
            ->> 'equipment_fatigue_cap_pct',
          ''
        )::numeric,
        4
      );

    v_ui_equipment_pct :=
      greatest(
        -v_equipment_stage_cap_pct,
        least(
          v_equipment_stage_cap_pct,
          coalesce(
            nullif(
              v_weighted_bonuses
                ->> v_terrain_bonus_key,
              ''
            )::numeric,
            0
          )
        )
      );

    v_ui_equipment_fatigue_pct :=
      greatest(
        0,
        least(
          v_equipment_fatigue_cap_pct,
          coalesce(
            nullif(
              v_weighted_bonuses
                ->> 'fatigue_reduction_pct',
              ''
            )::numeric,
            0
          )
        )
      );

    v_condition_factor :=
      coalesce(
        nullif(
          jsonb_path_query_first(
            v_final_bonus_snapshot,
            '$.**.equipment_condition_factor'
          ) #>> '{}',
          ''
        )::numeric,
        nullif(
          jsonb_path_query_first(
            v_equipment_snapshot,
            '$.**.equipment_condition_factor'
          ) #>> '{}',
          ''
        )::numeric,
        nullif(
          jsonb_path_query_first(
            v_rider_snapshot,
            '$.**.condition_factor'
          ) #>> '{}',
          ''
        )::numeric,
        1
      );

    v_condition_factor :=
      greatest(
        0,
        least(1, v_condition_factor)
      );

    v_engine_equipment_pct :=
      round(
        (
          v_ui_equipment_pct
          * v_equipment_multiplier
          * v_condition_factor
        )::numeric,
        4
      );

    v_engine_equipment_fatigue_pct :=
      round(
        (
          v_ui_equipment_fatigue_pct
          * v_equipment_multiplier
          * v_condition_factor
        )::numeric,
        4
      );

    v_race_support_pct :=
      coalesce(
        nullif(
          jsonb_path_query_first(
            v_final_bonus_snapshot,
            '$.**.race_support_bonus_pct'
          ) #>> '{}',
          ''
        )::numeric,
        nullif(
          v_standardized_bonus
            #>> '{standardized_bonus_totals,race_support}',
          ''
        )::numeric,
        0
      );

    v_fatigue_control_pct :=
      coalesce(
        nullif(
          jsonb_path_query_first(
            v_final_bonus_snapshot,
            '$.**.fatigue_control_bonus_pct'
          ) #>> '{}',
          ''
        )::numeric,
        nullif(
          v_standardized_bonus
            #>> '{standardized_bonus_totals,fatigue_control}',
          ''
        )::numeric,
        0
      );

    v_mechanical_reliability_pct :=
      coalesce(
        nullif(
          jsonb_path_query_first(
            v_final_bonus_snapshot,
            '$.**.mechanical_reliability_bonus_pct'
          ) #>> '{}',
          ''
        )::numeric,
        nullif(
          v_standardized_bonus
            #>> '{standardized_bonus_totals,mechanical_reliability}',
          ''
        )::numeric,
        0
      );

    v_bidons :=
      case
        when coalesce(
               v_rider_supplies ->> 'bidons',
               v_rider_supplies
                 ->> 'bidons_water_bottles',
               '0'
             ) ~ '^[0-9]+$'
          then coalesce(
                 v_rider_supplies
                   ->> 'bidons',
                 v_rider_supplies
                   ->> 'bidons_water_bottles',
                 '0'
               )::integer
        else 0
      end;

    v_gels :=
      case
        when coalesce(
               v_rider_supplies ->> 'gels',
               v_rider_supplies
                 ->> 'energy_gels',
               '0'
             ) ~ '^[0-9]+$'
          then coalesce(
                 v_rider_supplies ->> 'gels',
                 v_rider_supplies
                   ->> 'energy_gels',
                 '0'
               )::integer
        else 0
      end;

    v_nutrition :=
      case
        when coalesce(
               v_rider_supplies
                 ->> 'nutrition_packs',
               v_rider_supplies
                 ->> 'nutrition',
               '0'
             ) ~ '^[0-9]+$'
          then coalesce(
                 v_rider_supplies
                   ->> 'nutrition_packs',
                 v_rider_supplies
                   ->> 'nutrition',
                 '0'
               )::integer
        else 0
      end;

    v_rain_jacket :=
      lower(
        coalesce(
          v_rider_supplies
            ->> 'rain_jacket',
          v_rider_supplies
            ->> 'rain_jackets',
          'false'
        )
      ) in (
        'true', 't', '1', 'yes', 'y', 'all'
      );

    v_race_jersey_complete :=
      lower(
        coalesce(
          v_rider_supplies
            ->> 'race_jersey_complete',
          v_rider_supplies
            ->> 'race_jersey',
          'false'
        )
      ) in (
        'true', 't', '1', 'yes', 'y', 'all'
      );

    v_active_gels :=
      case
        when p_phase_number >= 4
          then least(greatest(v_gels, 0), 2)
        when p_phase_number = 3
             and v_gels >= 2
          then 1
        else 0
      end;

    v_gel_engine_live_energy_pct :=
      least(
        v_green_cap_pct,
        greatest(
          0,
          v_active_gels
          * v_gel_ui_value_pct
          * v_supply_multiplier
        )
      );

    v_rain_required :=
      coalesce(
        (
          v_rain_requirement
            ->> 'rain_jacket_required'
        )::boolean,
        false
      );

    v_rain_efficiency_ui_pct :=
      case
        when v_rain_required
             and v_rain_jacket
          then -1
        else 0
      end;

    v_rain_efficiency_engine_pct :=
      v_rain_efficiency_ui_pct
      * v_supply_multiplier;

    v_rain_sickness_risk_multiplier :=
      case
        when v_rain_required
             and v_rain_jacket
          then 0.50
        else 1.00
      end;

    with recursive
    supply_walk(
      race_stage_plan_id,
      supply_key,
      json_path,
      value
    ) as (
      select
        nullif(
          supply_row.value
            ->> 'race_stage_plan_id',
          ''
        )::uuid,
        supply_row.value
          ->> 'supply_key',
        array[
          supply_row.value
            ->> 'supply_key'
        ]::text[],
        coalesce(
          supply_row.value
            -> 'bonus_snapshot_json',
          '{}'::jsonb
        )
      from jsonb_array_elements(
        v_supply_snapshot_rows
      ) supply_row
      where nullif(
              supply_row.value
                ->> 'race_stage_plan_id',
              ''
            )::uuid =
            v_stage_plan_id

      union all

      select
        walk.race_stage_plan_id,
        walk.supply_key,
        walk.json_path || child.child_key,
        child.child_value
      from supply_walk walk
      cross join lateral (
        select
          object_child.key::text
            as child_key,
          object_child.value
            as child_value
        from jsonb_each(
          case
            when jsonb_typeof(walk.value)
                 = 'object'
              then walk.value
            else '{}'::jsonb
          end
        ) object_child

        union all

        select
          array_child.ordinality::text,
          array_child.value
        from jsonb_array_elements(
          case
            when jsonb_typeof(walk.value)
                 = 'array'
              then walk.value
            else '[]'::jsonb
          end
        ) with ordinality
          as array_child(
            value,
            ordinality
          )
      ) child
    ),
    numeric_effects as (
      select
        supply_key,
        json_path[
          array_length(json_path, 1)
        ] as effect_key,
        (value #>> '{}')::numeric
          as effect_value
      from supply_walk
      where jsonb_typeof(value) = 'number'
    ),
    classified as (
      select
        supply_key,
        effect_key,
        effect_value,

        effect_key ~
          '(_pct|percentage)$'
          and effect_key !~
            '(risk_multiplier|condition_factor|capacity|quantity|uses)'
          as is_percentage_effect,

        effect_key ~
          '(speed|efficiency|performance|attack|bridge|chase)'
          as is_speed_effect,

        effect_key ~
          '(energy|stamina|fatigue|hydration|nutrition|recovery)'
          as is_energy_effect
      from numeric_effects
    )
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'supply_key', supply_key,
            'effect_key', effect_key,
            'source_value', effect_value,
            'is_percentage_effect',
              is_percentage_effect,
            'hidden_multiplier_applied',
              case
                when is_percentage_effect
                  then v_supply_multiplier
                else 1
              end,
            'engine_value',
              case
                when is_percentage_effect
                  then effect_value
                       * v_supply_multiplier
                else effect_value
              end,
            'is_speed_effect',
              is_speed_effect,
            'is_energy_effect',
              is_energy_effect
          )
          order by supply_key, effect_key
        ),
        '[]'::jsonb
      ),

      coalesce(
        sum(effect_value) filter (
          where is_percentage_effect
            and is_speed_effect
        ),
        0
      ),

      coalesce(
        sum(effect_value) filter (
          where is_percentage_effect
            and is_energy_effect
        ),
        0
      ),

      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'supply_key', supply_key,
            'effect_key', effect_key,
            'source_value', effect_value,
            'reason',
              'not_a_confirmed_phase_percentage_effect'
          )
          order by supply_key, effect_key
        ) filter (
          where not is_percentage_effect
             or (
               not is_speed_effect
               and not is_energy_effect
             )
        ),
        '[]'::jsonb
      )
    into
      v_supply_effect_rows,
      v_supply_speed_ui_pct,
      v_supply_energy_ui_pct,
      v_unmapped_supply_effects
    from classified;

    v_supply_speed_engine_pct :=
      round(
        (
          coalesce(v_supply_speed_ui_pct, 0)
          * v_supply_multiplier
        )::numeric,
        4
      );

    v_supply_energy_engine_pct :=
      round(
        (
          coalesce(v_supply_energy_ui_pct, 0)
          * v_supply_multiplier
        )::numeric,
        4
      );

    v_base_effort_multiplier :=
      coalesce(
        nullif(
          v_action_json
            ->> 'effective_effort_multiplier',
          ''
        )::numeric,
        nullif(
          v_action_json
            ->> 'peloton_chase_speed_multiplier',
          ''
        )::numeric,
        1
      );

    v_equipment_speed_multiplier :=
      1 + v_engine_equipment_pct / 100.0;

    v_team_support_speed_multiplier :=
      1 + greatest(
            0,
            v_race_support_pct
          ) / 100.0;

    v_supply_speed_multiplier :=
      1 + v_supply_speed_engine_pct / 100.0;

    v_rain_efficiency_multiplier :=
      1 + v_rain_efficiency_engine_pct / 100.0;

    v_integrated_speed_multiplier :=
      round(
        (
          v_base_effort_multiplier
          * v_equipment_speed_multiplier
          * v_team_support_speed_multiplier
          * v_supply_speed_multiplier
          * v_rain_efficiency_multiplier
        )::numeric,
        6
      );

    v_equipment_energy_multiplier :=
      greatest(
        0,
        1
        - greatest(
            0,
            v_engine_equipment_fatigue_pct
          ) / 100.0
      );

    v_team_fatigue_multiplier :=
      greatest(
        0,
        1
        - greatest(
            0,
            v_fatigue_control_pct
          ) / 100.0
      );

    v_supply_energy_multiplier :=
      greatest(
        0,
        1
        - greatest(
            0,
            v_supply_energy_engine_pct
          ) / 100.0
      );

    v_integrated_energy_cost_multiplier :=
      round(
        (
          v_equipment_energy_multiplier
          * v_team_fatigue_multiplier
          * v_supply_energy_multiplier
        )::numeric,
        6
      );

    v_base_energy_cost_pct :=
      coalesce(
        nullif(
          v_action_json
            ->> 'projected_live_energy_cost_pct',
          ''
        )::numeric,
        0
      );

    v_adjusted_energy_cost_pct :=
      round(
        (
          v_base_energy_cost_pct
          * v_integrated_energy_cost_multiplier
        )::numeric,
        4
      );

    v_base_stamina_cost_points :=
      coalesce(
        nullif(
          v_action_json
            ->> 'projected_stamina_cost_points',
          ''
        )::numeric,
        0
      );

    v_adjusted_stamina_cost_points :=
      round(
        (
          v_base_stamina_cost_points
          * v_integrated_energy_cost_multiplier
        )::numeric,
        4
      );

    v_rider_plans :=
      v_rider_plans
      || jsonb_build_array(
           v_action_json
           || jsonb_build_object(
                'integration_status',
                  'integrated_read_only',
                'action_kind', v_action_kind,

                'locked_source',
                  jsonb_build_object(
                    'race_stage_plan_id',
                      v_stage_plan_id,
                    'snapshot_hash',
                      v_payload ->> 'snapshot_hash',
                    'snapshot_schema_version',
                      v_payload
                        ->> 'snapshot_schema_version',
                    'immutable', true,
                    'equipment_selection',
                      v_equipment_selection,
                    'rider_snapshot_row_found',
                      v_rider_snapshot
                      <> '{}'::jsonb
                  ),

                'equipment_effect',
                  jsonb_build_object(
                    'terrain_type',
                      v_terrain_type,
                    'terrain_bonus_key',
                      v_terrain_bonus_key,
                    'ui_weighted_percentage',
                      v_ui_equipment_pct,
                    'ui_fatigue_reduction_percentage',
                      v_ui_equipment_fatigue_pct,
                    'ui_stage_cap_percentage',
                      v_equipment_stage_cap_pct,
                    'ui_fatigue_cap_percentage',
                      v_equipment_fatigue_cap_pct,
                    'hidden_multiplier',
                      v_equipment_multiplier,
                    'condition_factor',
                      v_condition_factor,
                    'engine_speed_percentage',
                      v_engine_equipment_pct,
                    'engine_fatigue_reduction_percentage',
                      v_engine_equipment_fatigue_pct,
                    'application_order',
                      'weighted_ui_value_then_ui_cap_then_x5_then_condition',
                    'quantity_or_condition_multiplied',
                      false
                  ),

                'standardized_support_effect',
                  jsonb_build_object(
                    'race_support_bonus_pct',
                      v_race_support_pct,
                    'fatigue_control_bonus_pct',
                      v_fatigue_control_pct,
                    'mechanical_reliability_bonus_pct',
                      v_mechanical_reliability_pct,
                    'standardized_bonus_evidence',
                      v_standardized_bonus,
                    'unmapped_effect_policy',
                      'evidence_only_no_invented_coefficient'
                  ),

                'race_supply_effect',
                  jsonb_build_object(
                    'locked_quantities',
                      jsonb_build_object(
                        'bidons', v_bidons,
                        'gels', v_gels,
                        'nutrition_packs',
                          v_nutrition,
                        'rain_jacket',
                          v_rain_jacket,
                        'race_jersey_complete',
                          v_race_jersey_complete
                      ),
                    'hidden_multiplier',
                      v_supply_multiplier,
                    'quantities_multiplied',
                      false,
                    'active_gels_this_phase',
                      v_active_gels,
                    'gel_ui_value_green_pct',
                      v_gel_ui_value_pct,
                    'gel_engine_live_energy_bonus_pct',
                      v_gel_engine_live_energy_pct,
                    'gel_max_active_per_stage',
                      2,
                    'gel_green_cap_pct',
                      v_green_cap_pct,
                    'rain_jacket_required',
                      v_rain_required,
                    'rain_jacket_used',
                      v_rain_jacket,
                    'rain_efficiency_ui_pct',
                      v_rain_efficiency_ui_pct,
                    'rain_efficiency_engine_pct',
                      v_rain_efficiency_engine_pct,
                    'rain_sickness_risk_multiplier',
                      v_rain_sickness_risk_multiplier,
                    'rain_risk_multiplier_hidden_x3_applied',
                      false,
                    'snapshot_percentage_effects',
                      v_supply_effect_rows,
                    'snapshot_speed_ui_pct',
                      v_supply_speed_ui_pct,
                    'snapshot_speed_engine_pct',
                      v_supply_speed_engine_pct,
                    'snapshot_energy_ui_pct',
                      v_supply_energy_ui_pct,
                    'snapshot_energy_engine_pct',
                      v_supply_energy_engine_pct,
                    'unmapped_or_nonpercentage_effects',
                      v_unmapped_supply_effects
                  ),

                'integrated_phase_performance',
                  jsonb_build_object(
                    'base_physical_effort_multiplier',
                      v_base_effort_multiplier,
                    'equipment_speed_multiplier',
                      round(
                        v_equipment_speed_multiplier::numeric,
                        6
                      ),
                    'team_support_speed_multiplier',
                      round(
                        v_team_support_speed_multiplier::numeric,
                        6
                      ),
                    'supply_speed_multiplier',
                      round(
                        v_supply_speed_multiplier::numeric,
                        6
                      ),
                    'rain_efficiency_multiplier',
                      round(
                        v_rain_efficiency_multiplier::numeric,
                        6
                      ),
                    'integrated_speed_effort_multiplier',
                      v_integrated_speed_multiplier,
                    'equipment_energy_cost_multiplier',
                      round(
                        v_equipment_energy_multiplier::numeric,
                        6
                      ),
                    'team_fatigue_cost_multiplier',
                      round(
                        v_team_fatigue_multiplier::numeric,
                        6
                      ),
                    'supply_energy_cost_multiplier',
                      round(
                        v_supply_energy_multiplier::numeric,
                        6
                      ),
                    'integrated_energy_cost_multiplier',
                      v_integrated_energy_cost_multiplier,
                    'base_energy_cost_pct',
                      v_base_energy_cost_pct,
                    'adjusted_energy_cost_pct',
                      v_adjusted_energy_cost_pct,
                    'base_stamina_cost_points',
                      v_base_stamina_cost_points,
                    'adjusted_stamina_cost_points',
                      v_adjusted_stamina_cost_points,
                    'live_energy_support_delta_pct',
                      v_gel_engine_live_energy_pct,
                    'final_fatigue_conversion_status',
                      'deferred_to_issue01g'
                  ),

                'writes_allowed', false
              )
         );
  end loop;

  v_result_without_hash :=
    jsonb_build_object(
      'integrator_schema_version',
        'race_engine_locked_phase_performance_v1',
      'status', 'integrated',
      'stage_id', p_stage_id,
      'phase_number', p_phase_number,
      'context_source', v_context_source,
      'source_physical_plan_hash',
        v_physical_result
          ->> 'physical_plan_hash',

      'contracts',
        jsonb_build_object(
          'equipment_percentage_multiplier',
            5,
          'race_supply_percentage_multiplier',
            3,
          'equipment_multiplier_after_weighting',
            true,
          'equipment_condition_after_weighting',
            true,
          'reuse_existing_caps',
            true,
          'multiply_quantities_or_uses',
            false,
          'rain_sickness_risk_multiplier',
            0.50,
          'rain_risk_factor_converted_to_1_50',
            false,
          'unmapped_effects_invented',
            false,
          'replay_write_allowed',
            false,
          'energy_fatigue_write_allowed',
            false,
          'support_consumption_or_wear_allowed',
            false,
          'runner_integration_allowed',
            false
        ),

      'rider_phase_plans',
        v_rider_plans,

      'counts',
        jsonb_build_object(
          'physical_action_count',
            jsonb_array_length(v_action_rows),
          'integrated_rider_plan_count',
            jsonb_array_length(v_rider_plans),
          'blocked_rider_plan_count',
            (
              select count(*)::integer
              from jsonb_array_elements(
                v_rider_plans
              ) rider_plan
              where rider_plan.value
                      ->> 'integration_status'
                    <> 'integrated_read_only'
            )
        )
    );

  v_integration_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status', 'integrated',
    'stage_id', p_stage_id,
    'phase_number', p_phase_number,
    'integration_hash',
      v_integration_hash,
    'integration_plan',
      v_result_without_hash
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_plan_locked_breakaway_peloton_control_v1(p_stage_id uuid, p_phase_number integer, p_control_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_canary_mode boolean;
  v_context jsonb;
  v_runtime_state jsonb;

  v_physical_result jsonb;
  v_performance_result jsonb;
  v_physical_plan jsonb;
  v_performance_plan jsonb;

  v_attack_plans jsonb;
  v_bridge_plans jsonb;
  v_chase_plans jsonb;
  v_rider_phase_plans jsonb;

  v_stage_progress_fraction numeric;
  v_remaining_km numeric;
  v_current_gap_seconds numeric;
  v_baseline_peloton_pace_kmh numeric;
  v_escape_pace_kmh numeric;
  v_control_step_distance_km numeric;

  v_previous_response_mode text;
  v_previous_mode_age_steps integer;
  v_total_sprint_assets integer;
  v_total_protected_assets integer;
  v_is_point_gate_near boolean;
  v_is_finish_near boolean;

  v_escape_rider_count integer;
  v_escape_team_count integer;
  v_chasing_rider_count integer;
  v_chasing_team_count integer;
  v_available_chase_assets integer;

  v_escape_energy_cost_pct numeric;
  v_response_components jsonb;
  v_response_state jsonb;
  v_step_components jsonb;

  v_candidate_response_mode text;
  v_selected_response_mode text;
  v_selected_response_multiplier numeric;
  v_maximum_pursuit_multiplier numeric;
  v_projected_gap_delta_seconds numeric;
  v_projected_next_gap_seconds numeric;
  v_projected_gap_closure_seconds numeric;

  v_chase_rider_basis jsonb;
  v_escape_rider_basis jsonb;

  v_result_without_hash jsonb;
  v_planning_hash text;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_required'
    );
  end if;

  if p_phase_number not between 1 and 4 then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'phase_number_must_be_between_1_and_4',
      'phase_number', p_phase_number
    );
  end if;

  v_context :=
    coalesce(
      p_control_context_json,
      '{}'::jsonb
    );

  v_runtime_state :=
    coalesce(
      v_context -> 'runtime_state',
      '{}'::jsonb
    );

  begin
    v_stage_progress_fraction :=
      nullif(
        v_runtime_state
          ->> 'stage_progress_fraction',
        ''
      )::numeric;

    v_remaining_km :=
      nullif(
        v_runtime_state
          ->> 'remaining_km',
        ''
      )::numeric;

    v_current_gap_seconds :=
      nullif(
        v_runtime_state
          ->> 'current_gap_seconds',
        ''
      )::numeric;

    v_baseline_peloton_pace_kmh :=
      nullif(
        v_runtime_state
          ->> 'baseline_peloton_pace_kmh',
        ''
      )::numeric;

    v_escape_pace_kmh :=
      nullif(
        v_runtime_state
          ->> 'escape_pace_kmh',
        ''
      )::numeric;

    v_control_step_distance_km :=
      nullif(
        v_runtime_state
          ->> 'control_step_distance_km',
        ''
      )::numeric;

    v_previous_mode_age_steps :=
      coalesce(
        nullif(
          v_runtime_state
            ->> 'previous_mode_age_steps',
          ''
        )::integer,
        0
      );

    v_total_sprint_assets :=
      coalesce(
        nullif(
          v_runtime_state
            ->> 'total_sprint_assets',
          ''
        )::integer,
        0
      );

    v_total_protected_assets :=
      coalesce(
        nullif(
          v_runtime_state
            ->> 'total_protected_assets',
          ''
        )::integer,
        0
      );

  exception
    when invalid_text_representation
      or numeric_value_out_of_range
    then
      return jsonb_build_object(
        'status', 'invalid_request',
        'reason',
          'runtime_state_contains_invalid_numeric_value'
      );
  end;

  if v_stage_progress_fraction is null
     or v_remaining_km is null
     or v_current_gap_seconds is null
     or v_baseline_peloton_pace_kmh is null
     or v_escape_pace_kmh is null
     or v_control_step_distance_km is null
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'runtime_state_requires_stage_progress_remaining_gap_baseline_escape_and_step_distance',
      'required_keys',
        jsonb_build_array(
          'stage_progress_fraction',
          'remaining_km',
          'current_gap_seconds',
          'baseline_peloton_pace_kmh',
          'escape_pace_kmh',
          'control_step_distance_km'
        )
    );
  end if;

  if v_stage_progress_fraction < 0
     or v_stage_progress_fraction > 1
     or v_remaining_km < 0
     or v_current_gap_seconds < 0
     or v_baseline_peloton_pace_kmh <= 0
     or v_escape_pace_kmh <= 0
     or v_control_step_distance_km <= 0
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'runtime_state_numeric_bounds_invalid'
    );
  end if;

  v_previous_response_mode :=
    lower(
      coalesce(
        nullif(
          v_runtime_state
            ->> 'previous_response_mode',
          ''
        ),
        'no_active_escape'
      )
    );

  v_is_point_gate_near :=
    lower(
      coalesce(
        v_runtime_state
          ->> 'is_point_gate_near',
        'false'
      )
    ) in (
      'true', 't', '1', 'yes', 'y'
    );

  v_is_finish_near :=
    lower(
      coalesce(
        v_runtime_state
          ->> 'is_finish_near',
        'false'
      )
    ) in (
      'true', 't', '1', 'yes', 'y'
    );

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01f_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if (
       v_context ? 'physical_plan_result'
       or v_context ? 'phase_performance_result'
     )
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'precomputed_issue01_results_require_transaction_local_issue01f_canary_mode'
    );
  end if;

  if v_canary_mode
     and v_context ? 'physical_plan_result'
  then
    v_physical_result :=
      coalesce(
        v_context -> 'physical_plan_result',
        '{}'::jsonb
      );
  else
    v_physical_result :=
      public.race_engine_plan_locked_breakaway_physics_v1(
        p_stage_id,
        p_phase_number,
        null
      );
  end if;

  if coalesce(
       v_physical_result ->> 'status',
       ''
     ) <> 'planned'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01d_physical_plan_not_planned',
      'physical_status',
        v_physical_result ->> 'status',
      'physical_reason',
        v_physical_result ->> 'reason'
    );
  end if;

  if v_canary_mode
     and v_context ? 'phase_performance_result'
  then
    v_performance_result :=
      coalesce(
        v_context -> 'phase_performance_result',
        '{}'::jsonb
      );
  else
    v_performance_result :=
      public.race_engine_integrate_locked_phase_performance_v1(
        p_stage_id,
        p_phase_number,
        null
      );
  end if;

  if coalesce(
       v_performance_result ->> 'status',
       ''
     ) <> 'integrated'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01e_phase_performance_not_integrated',
      'performance_status',
        v_performance_result ->> 'status',
      'performance_reason',
        v_performance_result ->> 'reason'
    );
  end if;

  v_physical_plan :=
    coalesce(
      v_physical_result
        -> 'physical_plan',
      '{}'::jsonb
    );

  v_performance_plan :=
    coalesce(
      v_performance_result
        -> 'integration_plan',
      '{}'::jsonb
    );

  v_attack_plans :=
    coalesce(
      v_physical_plan -> 'attack_plans',
      '[]'::jsonb
    );

  v_bridge_plans :=
    coalesce(
      v_physical_plan -> 'bridge_plans',
      '[]'::jsonb
    );

  v_chase_plans :=
    coalesce(
      v_physical_plan -> 'chase_plans',
      '[]'::jsonb
    );

  v_rider_phase_plans :=
    coalesce(
      v_performance_plan
        -> 'rider_phase_plans',
      '[]'::jsonb
    );

  if jsonb_typeof(v_attack_plans) <> 'array'
     or jsonb_typeof(v_bridge_plans) <> 'array'
     or jsonb_typeof(v_chase_plans) <> 'array'
     or jsonb_typeof(v_rider_phase_plans) <> 'array'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01_action_or_performance_sections_must_be_arrays'
    );
  end if;

  with escape_actions as (
    select action.value
    from jsonb_array_elements(
      v_attack_plans
    ) action

    union all

    select action.value
    from jsonb_array_elements(
      v_bridge_plans
    ) action
  )
  select
    count(
      distinct nullif(
        action.value ->> 'rider_id',
        ''
      )
    )::integer,

    count(
      distinct nullif(
        coalesce(
          action.value
            ->> 'participant_club_id',
          action.value ->> 'team_id'
        ),
        ''
      )
    )::integer

  into
    v_escape_rider_count,
    v_escape_team_count

  from escape_actions action;

  with chase_actions as (
    select action.value
    from jsonb_array_elements(
      v_chase_plans
    ) action
  )
  select
    count(
      distinct nullif(
        action.value ->> 'rider_id',
        ''
      )
    )::integer,

    count(
      distinct nullif(
        coalesce(
          action.value
            ->> 'participant_club_id',
          action.value ->> 'team_id'
        ),
        ''
      )
    )::integer

  into
    v_chasing_rider_count,
    v_chasing_team_count

  from chase_actions action;

  v_available_chase_assets :=
    coalesce(
      v_chasing_rider_count,
      0
    );

  select coalesce(
    avg(
      nullif(
        rider_plan.value
          #>> '{integrated_phase_performance,adjusted_energy_cost_pct}',
        ''
      )::numeric
    ),
    0
  )
  into v_escape_energy_cost_pct
  from jsonb_array_elements(
    v_rider_phase_plans
  ) rider_plan
  where lower(
          coalesce(
            rider_plan.value
              ->> 'integration_action_kind',
            rider_plan.value
              ->> 'action_kind',
            ''
          )
        ) in (
          'attack',
          'bridge'
        );

  select to_jsonb(response_row)
  into v_response_components
  from public.race_engine_calculate_peloton_response_components_v2(
    v_stage_progress_fraction,
    v_remaining_km,
    v_current_gap_seconds,

    coalesce(
      v_escape_rider_count,
      0
    ),

    coalesce(
      v_escape_team_count,
      0
    ),

    coalesce(
      v_chasing_team_count,
      0
    ),

    v_available_chase_assets,
    greatest(
      0,
      v_total_sprint_assets
    ),
    greatest(
      0,
      v_total_protected_assets
    ),

    v_baseline_peloton_pace_kmh,
    v_escape_pace_kmh,
    v_is_point_gate_near,
    v_is_finish_near
  ) response_row;

  if v_response_components is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'authoritative_peloton_response_component_returned_no_row'
    );
  end if;

  v_candidate_response_mode :=
    coalesce(
      nullif(
        v_response_components
          ->> 'response_mode',
        ''
      ),
      'no_active_escape'
    );

  select to_jsonb(state_row)
  into v_response_state
  from public.race_engine_resolve_peloton_response_state_v2(
    v_previous_response_mode,
    greatest(
      0,
      v_previous_mode_age_steps
    ),
    v_candidate_response_mode,
    v_stage_progress_fraction,
    v_current_gap_seconds,

    coalesce(
      nullif(
        v_response_components
          ->> 'target_gap_lower_seconds',
        ''
      )::numeric,
      0
    ),

    coalesce(
      nullif(
        v_response_components
          ->> 'target_gap_upper_seconds',
        ''
      )::numeric,
      0
    ),

    coalesce(
      nullif(
        v_response_components
          ->> 'required_hold_multiplier',
        ''
      )::numeric,
      1
    ),

    coalesce(
      nullif(
        v_response_components
          ->> 'maximum_pursuit_multiplier',
        ''
      )::numeric,
      1
    ),

    coalesce(
      nullif(
        v_response_components
          ->> 'chase_urgency_score',
        ''
      )::numeric,
      0
    ),

    coalesce(
      v_escape_rider_count,
      0
    ) > 0,

    v_is_finish_near
  ) state_row;

  if v_response_state is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'authoritative_peloton_response_state_returned_no_row'
    );
  end if;

  v_selected_response_mode :=
    coalesce(
      nullif(
        v_response_state
          ->> 'selected_response_mode',
        ''
      ),
      v_candidate_response_mode
    );

  v_selected_response_multiplier :=
    coalesce(
      nullif(
        v_response_state
          ->> 'selected_response_multiplier',
        ''
      )::numeric,
      nullif(
        v_response_components
          ->> 'selected_response_multiplier',
        ''
      )::numeric,
      1
    );

  v_maximum_pursuit_multiplier :=
    coalesce(
      nullif(
        v_response_components
          ->> 'maximum_pursuit_multiplier',
        ''
      )::numeric,
      v_selected_response_multiplier
    );

  select to_jsonb(step_row)
  into v_step_components
  from public.race_engine_calculate_escape_step_components_v2(
    v_control_step_distance_km,
    v_baseline_peloton_pace_kmh,
    v_escape_pace_kmh,
    v_selected_response_multiplier,
    greatest(
      0,
      v_escape_energy_cost_pct
    )
  ) step_row;

  if v_step_components is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'authoritative_escape_step_component_returned_no_row'
    );
  end if;

  v_projected_gap_delta_seconds :=
    coalesce(
      nullif(
        v_step_components
          ->> 'projected_gap_delta_seconds',
        ''
      )::numeric,
      0
    );

  v_projected_next_gap_seconds :=
    greatest(
      0,
      v_current_gap_seconds
      + v_projected_gap_delta_seconds
    );

  v_projected_gap_closure_seconds :=
    greatest(
      0,
      -v_projected_gap_delta_seconds
    );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rider_id',
          rider_plan.value
            ->> 'rider_id',

        'participant_club_id',
          coalesce(
            rider_plan.value
              ->> 'participant_club_id',
            rider_plan.value
              ->> 'team_id'
          ),

        'action_kind', 'chase',

        'front_position_required',
          true,

        'front_position_contract',
          'peloton_front_chase_work',

        'integrated_speed_effort_multiplier',
          rider_plan.value
            #>> '{integrated_phase_performance,integrated_speed_effort_multiplier}',

        'integrated_energy_cost_multiplier',
          rider_plan.value
            #>> '{integrated_phase_performance,integrated_energy_cost_multiplier}',

        'adjusted_energy_cost_pct',
          rider_plan.value
            #>> '{integrated_phase_performance,adjusted_energy_cost_pct}',

        'adjusted_stamina_cost_points',
          rider_plan.value
            #>> '{integrated_phase_performance,adjusted_stamina_cost_points}',

        'fatigue_delta_basis',
          coalesce(
            rider_plan.value
              ->> 'fatigue_delta_basis',
            rider_plan.value
              #>> '{integrated_phase_performance,fatigue_delta_basis}'
          ),

        'final_fatigue_state_write',
          false
      )
      order by
        rider_plan.value
          ->> 'rider_id'
    ),
    '[]'::jsonb
  )
  into v_chase_rider_basis
  from jsonb_array_elements(
    v_rider_phase_plans
  ) rider_plan
  where lower(
          coalesce(
            rider_plan.value
              ->> 'integration_action_kind',
            rider_plan.value
              ->> 'action_kind',
            ''
          )
        ) = 'chase';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rider_id',
          rider_plan.value
            ->> 'rider_id',

        'participant_club_id',
          coalesce(
            rider_plan.value
              ->> 'participant_club_id',
            rider_plan.value
              ->> 'team_id'
          ),

        'action_kind',
          lower(
            coalesce(
              rider_plan.value
                ->> 'integration_action_kind',
              rider_plan.value
                ->> 'action_kind',
              ''
            )
          ),

        'integrated_speed_effort_multiplier',
          rider_plan.value
            #>> '{integrated_phase_performance,integrated_speed_effort_multiplier}',

        'adjusted_energy_cost_pct',
          rider_plan.value
            #>> '{integrated_phase_performance,adjusted_energy_cost_pct}',

        'adjusted_stamina_cost_points',
          rider_plan.value
            #>> '{integrated_phase_performance,adjusted_stamina_cost_points}',

        'fatigue_delta_basis',
          coalesce(
            rider_plan.value
              ->> 'fatigue_delta_basis',
            rider_plan.value
              #>> '{integrated_phase_performance,fatigue_delta_basis}'
          ),

        'final_fatigue_state_write',
          false
      )
      order by
        rider_plan.value
          ->> 'rider_id'
    ),
    '[]'::jsonb
  )
  into v_escape_rider_basis
  from jsonb_array_elements(
    v_rider_phase_plans
  ) rider_plan
  where lower(
          coalesce(
            rider_plan.value
              ->> 'integration_action_kind',
            rider_plan.value
              ->> 'action_kind',
            ''
          )
        ) in (
          'attack',
          'bridge'
        );

  v_result_without_hash :=
    jsonb_build_object(
      'planner_schema_version',
        'race_engine_locked_breakaway_peloton_control_v1',

      'status', 'planned',
      'stage_id', p_stage_id,
      'phase_number', p_phase_number,

      'source_contract',
        jsonb_build_object(
          'issue01d_physical_plan_hash',
            v_physical_result
              ->> 'physical_plan_hash',

          'issue01e_performance_hash',
            v_performance_result
              ->> 'integration_hash',

          'peloton_response_component_definition_hash',
            '173b3007157aaebf74a5b4ac3de8dc9c',

          'response_state_definition_hash',
            'bf63b5bca89446efadd75f23ea07e0a9',

          'escape_step_definition_hash',
            '3f04aad1eb145f8be206e5ed325789c4',

          'coefficients_copied_into_issue01f_planner',
            false,

          'coefficients_invented',
            false
        ),

      'runtime_state',
        jsonb_build_object(
          'stage_progress_fraction',
            v_stage_progress_fraction,
          'remaining_km',
            v_remaining_km,
          'current_gap_seconds',
            v_current_gap_seconds,
          'baseline_peloton_pace_kmh',
            v_baseline_peloton_pace_kmh,
          'escape_pace_kmh',
            v_escape_pace_kmh,
          'control_step_distance_km',
            v_control_step_distance_km,
          'previous_response_mode',
            v_previous_response_mode,
          'previous_mode_age_steps',
            v_previous_mode_age_steps,
          'is_point_gate_near',
            v_is_point_gate_near,
          'is_finish_near',
            v_is_finish_near
        ),

      'action_population',
        jsonb_build_object(
          'escape_rider_count',
            coalesce(
              v_escape_rider_count,
              0
            ),
          'escape_team_count',
            coalesce(
              v_escape_team_count,
              0
            ),
          'chasing_rider_count',
            coalesce(
              v_chasing_rider_count,
              0
            ),
          'chasing_team_count',
            coalesce(
              v_chasing_team_count,
              0
            ),
          'available_chase_assets',
            v_available_chase_assets,
          'total_sprint_assets',
            greatest(
              0,
              v_total_sprint_assets
            ),
          'total_protected_assets',
            greatest(
              0,
              v_total_protected_assets
            )
        ),

      'authoritative_response_components',
        v_response_components,

      'authoritative_response_state',
        v_response_state,

      'control_decision',
        jsonb_build_object(
          'candidate_response_mode',
            v_candidate_response_mode,

          'selected_response_mode',
            v_selected_response_mode,

          'target_gap_lower_seconds',
            v_response_components
              -> 'target_gap_lower_seconds',

          'target_gap_upper_seconds',
            v_response_components
              -> 'target_gap_upper_seconds',

          'required_hold_multiplier',
            v_response_components
              -> 'required_hold_multiplier',

          'maximum_pursuit_multiplier',
            v_maximum_pursuit_multiplier,

          'selected_response_multiplier',
            v_selected_response_multiplier,

          'chase_interest_score',
            v_response_components
              -> 'chase_interest_score',

          'chase_capacity_score',
            v_response_components
              -> 'chase_capacity_score',

          'coordination_factor',
            v_response_components
              -> 'coordination_factor',

          'chase_urgency_score',
            v_response_components
              -> 'chase_urgency_score',

          'peloton_work_intensity_fraction',
            v_response_components
              -> 'peloton_work_intensity_fraction'
        ),

      'physical_gap_projection',
        jsonb_build_object(
          'authoritative_step_components',
            v_step_components,

          'current_gap_seconds',
            v_current_gap_seconds,

          'projected_gap_delta_seconds',
            v_projected_gap_delta_seconds,

          'projected_next_gap_seconds',
            v_projected_next_gap_seconds,

          'projected_gap_closure_seconds',
            v_projected_gap_closure_seconds,

          'direct_gap_write',
            false,

          'direct_group_reassignment',
            false,

          'teleportation_allowed',
            false
        ),

      'escape_rider_energy_fatigue_basis',
        v_escape_rider_basis,

      'chase_rider_energy_fatigue_basis',
        v_chase_rider_basis,

      'write_contract',
        jsonb_build_object(
          'replay_write_allowed', false,
          'group_write_allowed', false,
          'gap_write_allowed', false,
          'speed_write_allowed', false,
          'live_energy_write_allowed', false,
          'fatigue_write_allowed', false,
          'support_consumption_allowed', false,
          'equipment_or_asset_wear_allowed', false,
          'runner_integration_allowed', false,
          'historical_processing_allowed', false
        )
    );

  v_planning_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status', 'planned',
    'stage_id', p_stage_id,
    'phase_number', p_phase_number,
    'planning_hash', v_planning_hash,
    'control_plan', v_result_without_hash
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_plan_locked_stage_state_transition_v1(p_stage_id uuid, p_phase_number integer, p_simulation_run_id uuid, p_transition_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_canary_mode boolean;
  v_context jsonb;

  v_runtime_state_rows jsonb;
  v_issue01f_control_context jsonb;

  v_performance_result jsonb;
  v_control_result jsonb;

  v_rider_phase_plans jsonb;
  v_chase_basis jsonb;
  v_escape_basis jsonb;

  v_transition_rows jsonb;
  v_blocked_rows jsonb;

  v_action_rider_count integer := 0;
  v_transition_row_count integer := 0;
  v_blocked_row_count integer := 0;
  v_unique_idempotency_key_count integer := 0;

  v_result_without_hash jsonb;
  v_plan_hash text;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_required'
    );
  end if;

  if p_simulation_run_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'simulation_run_id_required'
    );
  end if;

  if p_phase_number not between 1 and 4 then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'phase_number_must_be_between_1_and_4',
      'phase_number', p_phase_number
    );
  end if;

  v_context :=
    coalesce(
      p_transition_context_json,
      '{}'::jsonb
    );

  v_runtime_state_rows :=
    coalesce(
      v_context -> 'runtime_state_rows',
      '[]'::jsonb
    );

  v_issue01f_control_context :=
    coalesce(
      v_context -> 'issue01f_control_context',
      '{}'::jsonb
    );

  if jsonb_typeof(v_runtime_state_rows) <> 'array' then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'runtime_state_rows_must_be_array'
    );
  end if;

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01g_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if (
       v_context ? 'phase_performance_result'
       or v_context ? 'control_plan_result'
     )
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'precomputed_issue01_results_require_transaction_local_issue01g_canary_mode'
    );
  end if;

  if v_canary_mode
     and v_context ? 'phase_performance_result'
  then
    v_performance_result :=
      coalesce(
        v_context -> 'phase_performance_result',
        '{}'::jsonb
      );
  else
    v_performance_result :=
      public.race_engine_integrate_locked_phase_performance_v1(
        p_stage_id,
        p_phase_number,
        null
      );
  end if;

  if coalesce(
       v_performance_result ->> 'status',
       ''
     ) <> 'integrated'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01e_phase_performance_not_integrated',
      'performance_status',
        v_performance_result ->> 'status',
      'performance_reason',
        v_performance_result ->> 'reason'
    );
  end if;

  if v_canary_mode
     and v_context ? 'control_plan_result'
  then
    v_control_result :=
      coalesce(
        v_context -> 'control_plan_result',
        '{}'::jsonb
      );
  else
    v_control_result :=
      public.race_engine_plan_locked_breakaway_peloton_control_v1(
        p_stage_id,
        p_phase_number,
        v_issue01f_control_context
      );
  end if;

  if coalesce(
       v_control_result ->> 'status',
       ''
     ) <> 'planned'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01f_control_plan_not_planned',
      'control_status',
        v_control_result ->> 'status',
      'control_reason',
        v_control_result ->> 'reason'
    );
  end if;

  v_rider_phase_plans :=
    coalesce(
      v_performance_result
        #> '{integration_plan,rider_phase_plans}',
      '[]'::jsonb
    );

  v_chase_basis :=
    coalesce(
      v_control_result
        #> '{control_plan,chase_rider_energy_fatigue_basis}',
      '[]'::jsonb
    );

  v_escape_basis :=
    coalesce(
      v_control_result
        #> '{control_plan,escape_rider_energy_fatigue_basis}',
      '[]'::jsonb
    );

  if jsonb_typeof(v_rider_phase_plans) <> 'array'
     or jsonb_typeof(v_chase_basis) <> 'array'
     or jsonb_typeof(v_escape_basis) <> 'array'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01e_or_issue01f_rider_sections_must_be_arrays'
    );
  end if;

  v_action_rider_count :=
    jsonb_array_length(
      v_rider_phase_plans
    );

  /*
  Build one deterministic transition row per Issue 01E action rider.

  Numeric values come from:
  - Issue 01E for energy/stamina/fatigue deltas;
  - runtime_state_rows for current state and already-resolved recovery points;
  - calculate_rider_start_freshness_v1 for freshness.

  No table is written.
  */
  with
  performance_rows as (
    select
      performance_row.value as performance_json,

      nullif(
        performance_row.value
          ->> 'rider_id',
        ''
      )::uuid as rider_id,

      lower(
        coalesce(
          performance_row.value
            ->> 'integration_action_kind',
          performance_row.value
            ->> 'action_kind',
          ''
        )
      ) as action_kind,

      coalesce(
        nullif(
          performance_row.value
            #>> '{integrated_phase_performance,adjusted_energy_cost_pct}',
          ''
        )::numeric,
        0
      ) as adjusted_energy_cost_pct,

      coalesce(
        nullif(
          performance_row.value
            #>> '{integrated_phase_performance,adjusted_stamina_cost_points}',
          ''
        )::numeric,
        0
      ) as adjusted_stamina_cost_points,

      coalesce(
        nullif(
          performance_row.value
            ->> 'fatigue_delta_basis',
          ''
        )::numeric,

        nullif(
          performance_row.value
            #>> '{integrated_phase_performance,fatigue_delta_basis}',
          ''
        )::numeric,

        0
      ) as fatigue_delta_basis

    from jsonb_array_elements(
      v_rider_phase_plans
    ) performance_row

    where coalesce(
            performance_row.value
              ->> 'rider_id',
            ''
          ) ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),

  runtime_rows as (
    select
      runtime_row.value as runtime_json,

      nullif(
        runtime_row.value
          ->> 'rider_id',
        ''
      )::uuid as rider_id,

      nullif(
        runtime_row.value
          ->> 'current_live_energy',
        ''
      )::numeric as current_live_energy,

      nullif(
        runtime_row.value
          ->> 'current_stamina',
        ''
      )::numeric as current_stamina,

      nullif(
        runtime_row.value
          ->> 'current_fatigue',
        ''
      )::numeric as current_fatigue,

      nullif(
        runtime_row.value
          ->> 'race_sharpness',
        ''
      )::numeric as race_sharpness,

      nullif(
        runtime_row.value
          ->> 'authoritative_daily_recovery_points',
        ''
      )::numeric as authoritative_daily_recovery_points,

      nullif(
        runtime_row.value
          ->> 'daily_recovery_source',
        ''
      ) as daily_recovery_source

    from jsonb_array_elements(
      v_runtime_state_rows
    ) runtime_row

    where coalesce(
            runtime_row.value
              ->> 'rider_id',
            ''
          ) ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),

  chase_rows as (
    select
      nullif(
        chase_row.value
          ->> 'rider_id',
        ''
      )::uuid as rider_id,

      coalesce(
        (
          chase_row.value
            ->> 'front_position_required'
        )::boolean,
        false
      ) as front_position_required,

      chase_row.value
        ->> 'front_position_contract'
        as front_position_contract

    from jsonb_array_elements(
      v_chase_basis
    ) chase_row

    where coalesce(
            chase_row.value
              ->> 'rider_id',
            ''
          ) ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),

  escape_rows as (
    select
      nullif(
        escape_row.value
          ->> 'rider_id',
        ''
      )::uuid as rider_id,

      lower(
        coalesce(
          escape_row.value
            ->> 'action_kind',
          ''
        )
      ) as control_action_kind

    from jsonb_array_elements(
      v_escape_basis
    ) escape_row

    where coalesce(
            escape_row.value
              ->> 'rider_id',
            ''
          ) ~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ),

  joined_rows as (
    select
      performance.rider_id,
      performance.action_kind,

      performance.adjusted_energy_cost_pct,
      performance.adjusted_stamina_cost_points,
      performance.fatigue_delta_basis,

      runtime.current_live_energy,
      runtime.current_stamina,
      runtime.current_fatigue,
      runtime.race_sharpness,
      runtime.authoritative_daily_recovery_points,
      runtime.daily_recovery_source,

      chase.front_position_required,
      chase.front_position_contract,

      escape.control_action_kind,

      case
        when runtime.rider_id is null then
          'runtime_state_row_missing'

        when runtime.current_live_energy is null
          or runtime.current_live_energy < 0
          or runtime.current_live_energy > 100
        then
          'current_live_energy_must_be_between_0_and_100'

        when runtime.current_stamina is null
          or runtime.current_stamina < 0
          or runtime.current_stamina > 100
        then
          'current_stamina_must_be_between_0_and_100'

        when runtime.current_fatigue is null
          or runtime.current_fatigue < 0
          or runtime.current_fatigue > 100
        then
          'current_fatigue_must_be_between_0_and_100'

        when runtime.race_sharpness is null
          or runtime.race_sharpness < 0
          or runtime.race_sharpness > 100
        then
          'race_sharpness_must_be_between_0_and_100'

        when runtime.authoritative_daily_recovery_points is null
          or runtime.authoritative_daily_recovery_points < 0
        then
          'authoritative_daily_recovery_points_must_be_nonnegative'

        when runtime.daily_recovery_source is null then
          'daily_recovery_source_required'

        when performance.adjusted_energy_cost_pct < 0 then
          'issue01e_energy_cost_must_be_nonnegative'

        when performance.adjusted_stamina_cost_points < 0 then
          'issue01e_stamina_cost_must_be_nonnegative'

        when performance.fatigue_delta_basis < 0 then
          'issue01e_fatigue_delta_basis_must_be_nonnegative'

        when performance.action_kind = 'chase'
          and coalesce(
                chase.front_position_required,
                false
              ) = false
        then
          'issue01f_chase_front_position_contract_missing'

        else null
      end as blocked_reason

    from performance_rows performance

    left join runtime_rows runtime
      on runtime.rider_id =
        performance.rider_id

    left join chase_rows chase
      on chase.rider_id =
        performance.rider_id

    left join escape_rows escape
      on escape.rider_id =
        performance.rider_id
  ),

  projected_rows as (
    select
      joined.*,

      (
        -joined.adjusted_energy_cost_pct
      )::numeric as live_energy_delta_pct,

      greatest(
        0,
        joined.current_live_energy
        - joined.adjusted_energy_cost_pct
      )::numeric as projected_live_energy,

      (
        -joined.adjusted_stamina_cost_points
      )::numeric as stamina_delta_points,

      greatest(
        0,
        joined.current_stamina
        - joined.adjusted_stamina_cost_points
      )::numeric as projected_finish_stamina,

      joined.fatigue_delta_basis::numeric
        as post_stage_fatigue_delta,

      least(
        100,
        greatest(
          0,
          joined.current_fatigue
          + joined.fatigue_delta_basis
        )
      )::numeric as projected_post_stage_fatigue,

      least(
        100,
        greatest(
          0,
          joined.current_fatigue
          + joined.fatigue_delta_basis
        )
      )::integer as target_fatigue_integer

    from joined_rows joined
  ),

  freshness_rows as (
    select
      projected.*,

      public.calculate_rider_start_freshness_v1(
        projected.projected_post_stage_fatigue,
        projected.race_sharpness
      ) as projected_immediate_next_stage_freshness,

      greatest(
        0,
        projected.projected_post_stage_fatigue
        - projected.authoritative_daily_recovery_points
      )::numeric as projected_next_day_fatigue

    from projected_rows projected
  ),

  final_rows as (
    select
      freshness.*,

      public.calculate_rider_start_freshness_v1(
        freshness.projected_next_day_fatigue,
        freshness.race_sharpness
      ) as projected_next_day_freshness,

      md5(
        concat_ws(
          '|',
          'race_engine_locked_state_transition_v1',
          p_stage_id::text,
          p_simulation_run_id::text,
          p_phase_number::text,
          freshness.rider_id::text,
          coalesce(
            v_performance_result
              ->> 'integration_hash',
            ''
          ),
          coalesce(
            v_control_result
              ->> 'planning_hash',
            ''
          ),
          coalesce(
            freshness.action_kind,
            ''
          ),
          coalesce(
            freshness.current_live_energy::text,
            ''
          ),
          coalesce(
            freshness.current_stamina::text,
            ''
          ),
          coalesce(
            freshness.current_fatigue::text,
            ''
          ),
          coalesce(
            freshness.race_sharpness::text,
            ''
          ),
          coalesce(
            freshness.authoritative_daily_recovery_points::text,
            ''
          ),
          coalesce(
            freshness.daily_recovery_source,
            ''
          )
        )
      ) as idempotency_key

    from freshness_rows freshness
  )

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id',
            final_row.rider_id,

          'action_kind',
            final_row.action_kind,

          'issue01f_control_role',
            case
              when final_row.action_kind = 'chase'
                then 'peloton_chase'
              when final_row.action_kind in (
                'attack',
                'bridge'
              )
                then 'escape'
              else 'other'
            end,

          'issue01f_escape_action_kind',
            final_row.control_action_kind,

          'front_position_required',
            coalesce(
              final_row.front_position_required,
              false
            ),

          'front_position_contract',
            final_row.front_position_contract,

          'current_live_energy',
            final_row.current_live_energy,

          'live_energy_delta_pct',
            final_row.live_energy_delta_pct,

          'projected_live_energy',
            final_row.projected_live_energy,

          'current_stamina',
            final_row.current_stamina,

          'stamina_delta_points',
            final_row.stamina_delta_points,

          'projected_finish_stamina',
            final_row.projected_finish_stamina,

          'current_fatigue',
            final_row.current_fatigue,

          'post_stage_fatigue_delta',
            final_row.post_stage_fatigue_delta,

          'projected_post_stage_fatigue',
            final_row.projected_post_stage_fatigue,

          'target_fatigue_integer',
            final_row.target_fatigue_integer,

          'race_sharpness',
            final_row.race_sharpness,

          'projected_immediate_next_stage_freshness',
            final_row.projected_immediate_next_stage_freshness,

          'authoritative_daily_recovery_points',
            final_row.authoritative_daily_recovery_points,

          'daily_recovery_source',
            final_row.daily_recovery_source,

          'projected_next_day_fatigue',
            final_row.projected_next_day_fatigue,

          'projected_next_day_freshness',
            final_row.projected_next_day_freshness,

          'idempotency_key',
            final_row.idempotency_key,

          'blocked_reason',
            final_row.blocked_reason,

          'operational_write',
            false
        )
        order by final_row.rider_id
      ) filter (
        where final_row.blocked_reason is null
      ),
      '[]'::jsonb
    ),

    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id',
            final_row.rider_id,
          'action_kind',
            final_row.action_kind,
          'blocked_reason',
            final_row.blocked_reason
        )
        order by final_row.rider_id
      ) filter (
        where final_row.blocked_reason is not null
      ),
      '[]'::jsonb
    ),

    count(*) filter (
      where final_row.blocked_reason is null
    )::integer,

    count(*) filter (
      where final_row.blocked_reason is not null
    )::integer,

    count(
      distinct final_row.idempotency_key
    ) filter (
      where final_row.blocked_reason is null
    )::integer

  into
    v_transition_rows,
    v_blocked_rows,
    v_transition_row_count,
    v_blocked_row_count,
    v_unique_idempotency_key_count

  from final_rows final_row;

  v_result_without_hash :=
    jsonb_build_object(
      'planner_schema_version',
        'race_engine_locked_stage_state_transition_v1',

      'status',
        case
          when v_action_rider_count = 0
            then 'blocked'
          when v_blocked_row_count > 0
            then 'blocked'
          when v_transition_row_count <>
               v_action_rider_count
            then 'blocked'
          when v_unique_idempotency_key_count <>
               v_transition_row_count
            then 'blocked'
          else 'planned'
        end,

      'reason',
        case
          when v_action_rider_count = 0
            then 'no_issue01e_action_riders'
          when v_blocked_row_count > 0
            then 'one_or_more_transition_rows_blocked'
          when v_transition_row_count <>
               v_action_rider_count
            then 'transition_count_does_not_match_issue01e_action_count'
          when v_unique_idempotency_key_count <>
               v_transition_row_count
            then 'idempotency_keys_not_unique'
          else null
        end,

      'stage_id', p_stage_id,
      'phase_number', p_phase_number,
      'simulation_run_id',
        p_simulation_run_id,

      'source_contract',
        jsonb_build_object(
          'issue01e_integration_hash',
            v_performance_result
              ->> 'integration_hash',

          'issue01f_control_planning_hash',
            v_control_result
              ->> 'planning_hash',

          'official_command_state_writer_definition_hash',
            '84780caad843467d83364d6e190dbfc2',

          'official_fatigue_writer_definition_hash',
            '1fec51363749695054363d5d86d10fd5',

          'start_freshness_calculator_definition_hash',
            'ea54ec8766d01059f87e4531df42875c',

          'daily_fatigue_writer_definition_hash',
            '11e23d1c64dff520b1067166a977747e',

          'energy_stamina_fatigue_coefficients_recomputed',
            false,

          'freshness_coefficients_copied',
            false,

          'daily_recovery_coefficients_calculated_here',
            false,

          'invented_coefficients',
            false
        ),

      'counts',
        jsonb_build_object(
          'issue01e_action_rider_count',
            v_action_rider_count,

          'transition_row_count',
            v_transition_row_count,

          'blocked_row_count',
            v_blocked_row_count,

          'unique_idempotency_key_count',
            v_unique_idempotency_key_count
        ),

      'transition_rows',
        v_transition_rows,

      'blocked_rows',
        v_blocked_rows,

      'write_contract',
        jsonb_build_object(
          'replay_write_allowed', false,
          'group_write_allowed', false,
          'gap_write_allowed', false,
          'speed_write_allowed', false,
          'live_energy_write_allowed', false,
          'stamina_write_allowed', false,
          'fatigue_write_allowed', false,
          'freshness_write_allowed', false,
          'recovery_write_allowed', false,
          'support_consumption_allowed', false,
          'equipment_or_asset_wear_allowed', false,
          'result_or_classification_write_allowed', false,
          'runner_integration_allowed', false,
          'historical_processing_allowed', false
        )
    );

  v_plan_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status',
      v_result_without_hash ->> 'status',

    'reason',
      v_result_without_hash ->> 'reason',

    'stage_id', p_stage_id,
    'phase_number', p_phase_number,
    'simulation_run_id',
      p_simulation_run_id,

    'state_transition_plan_hash',
      v_plan_hash,

    'state_transition_plan',
      v_result_without_hash
  );

exception
  when invalid_text_representation
    or numeric_value_out_of_range
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'runtime_or_issue01_evidence_contains_invalid_numeric_or_uuid_value',
      'sqlstate', sqlstate,
      'message', sqlerrm
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_plan_locked_issue01_end_to_end_v1(p_race_stage_plan_id uuid, p_simulation_run_id uuid, p_orchestrator_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_canary_mode boolean;

  v_stage_id uuid;

  v_tactical_result jsonb;
  v_phase_results jsonb := '[]'::jsonb;

  v_phase integer;
  v_phase_key text;
  v_phase_context jsonb;
  v_precomputed_phase jsonb;

  v_wave_result jsonb;
  v_physical_result jsonb;
  v_performance_result jsonb;
  v_control_result jsonb;
  v_transition_result jsonb;

  v_control_context jsonb;
  v_transition_context jsonb;

  v_effective_wave_cap integer;
  v_selected_wave_count integer;

  v_attack_count integer;
  v_bridge_count integer;
  v_chase_count integer;
  v_escape_count integer;

  v_performance_action_count integer;
  v_performance_integrated_count integer;
  v_performance_blocked_count integer;

  v_control_escape_count integer;
  v_control_chase_count integer;
  v_selected_response_multiplier numeric;
  v_maximum_pursuit_multiplier numeric;
  v_chase_basis_count integer;

  v_transition_action_count integer;
  v_transition_row_count integer;
  v_transition_blocked_count integer;
  v_unique_idempotency_key_count integer;

  v_component_statuses_pass boolean;
  v_wave_cap_present boolean;
  v_wave_cap_respected boolean;
  v_mass_escape_guard_pass boolean;
  v_join_requires_attack_pass boolean;
  v_performance_population_pass boolean;
  v_control_population_pass boolean;
  v_pursuit_cap_pass boolean;
  v_chase_front_position_pass boolean;
  v_transition_population_pass boolean;
  v_transition_idempotency_pass boolean;
  v_phase_pass boolean;

  v_all_phase_statuses_pass boolean := true;
  v_all_wave_caps_present boolean := true;
  v_all_wave_caps_respected boolean := true;
  v_all_mass_escape_guards_pass boolean := true;
  v_all_join_requires_attack_pass boolean := true;
  v_all_performance_populations_pass boolean := true;
  v_all_control_populations_pass boolean := true;
  v_all_pursuit_caps_pass boolean := true;
  v_all_chase_front_positions_pass boolean := true;
  v_all_transition_populations_pass boolean := true;
  v_all_transition_idempotency_pass boolean := true;
  v_all_phases_pass boolean := true;

  v_result_without_hash jsonb;
  v_orchestrator_hash text;
begin
  if p_race_stage_plan_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'race_stage_plan_id_required'
    );
  end if;

  if p_simulation_run_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'simulation_run_id_required'
    );
  end if;

  v_context :=
    coalesce(
      p_orchestrator_context_json,
      '{}'::jsonb
    );

  v_canary_mode :=
    lower(
      coalesce(
        current_setting(
          'app.issue01h_canary_mode',
          true
        ),
        'false'
      )
    ) = 'true';

  if v_context ? 'precomputed_results'
     and not v_canary_mode
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'precomputed_issue01_results_require_transaction_local_issue01h_canary_mode'
    );
  end if;

  if v_canary_mode
     and v_context ? 'precomputed_results'
  then
    begin
      v_stage_id :=
        nullif(
          v_context
            #>> '{precomputed_results,stage_id}',
          ''
        )::uuid;
    exception
      when invalid_text_representation then
        return jsonb_build_object(
          'status', 'invalid_request',
          'reason',
            'precomputed_stage_id_invalid'
        );
    end;

    v_tactical_result :=
      coalesce(
        v_context
          #> '{precomputed_results,locked_tactical_plan_result}',
        '{}'::jsonb
      );

  else
    select stage_plan.stage_id
    into v_stage_id
    from public.race_stage_plans stage_plan
    where stage_plan.id =
      p_race_stage_plan_id;

    if v_stage_id is null then
      return jsonb_build_object(
        'status', 'not_found',
        'reason',
          'race_stage_plan_not_found_or_stage_id_missing',
        'race_stage_plan_id',
          p_race_stage_plan_id
      );
    end if;

    v_tactical_result :=
      public.race_engine_resolve_locked_stage_tactical_plan_v1(
        p_race_stage_plan_id
      );
  end if;

  if v_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'stage_id_unresolved'
    );
  end if;

  if coalesce(
       v_tactical_result ->> 'status',
       ''
     ) <> 'resolved'
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'issue01b_locked_tactical_plan_not_resolved',
      'issue01b_status',
        v_tactical_result ->> 'status'
    );
  end if;

  for v_phase in 1..4 loop
    v_phase_key := v_phase::text;

    v_phase_context :=
      coalesce(
        v_context #> array[
          'phase_contexts',
          v_phase_key
        ],
        '{}'::jsonb
      );

    if v_canary_mode
       and v_context ? 'precomputed_results'
    then
      v_precomputed_phase :=
        coalesce(
          v_context #> array[
            'precomputed_results',
            'phase_results',
            v_phase_key
          ],
          '{}'::jsonb
        );

      v_wave_result :=
        coalesce(
          v_precomputed_phase
            -> 'attack_wave_result',
          '{}'::jsonb
        );

      v_physical_result :=
        coalesce(
          v_precomputed_phase
            -> 'physical_result',
          '{}'::jsonb
        );

      v_performance_result :=
        coalesce(
          v_precomputed_phase
            -> 'performance_result',
          '{}'::jsonb
        );

      v_control_result :=
        coalesce(
          v_precomputed_phase
            -> 'control_result',
          '{}'::jsonb
        );

      v_transition_result :=
        coalesce(
          v_precomputed_phase
            -> 'transition_result',
          '{}'::jsonb
        );

    else
      v_control_context :=
        coalesce(
          v_phase_context
            -> 'control_context',
          '{}'::jsonb
        );

      v_transition_context :=
        coalesce(
          v_phase_context
            -> 'transition_context',
          '{}'::jsonb
        )
        || jsonb_build_object(
             'issue01f_control_context',
             v_control_context
           );

      v_wave_result :=
        public.race_engine_build_locked_attack_waves_v1(
          v_stage_id,
          v_phase,
          null
        );

      v_physical_result :=
        public.race_engine_plan_locked_breakaway_physics_v1(
          v_stage_id,
          v_phase,
          null
        );

      v_performance_result :=
        public.race_engine_integrate_locked_phase_performance_v1(
          v_stage_id,
          v_phase,
          null
        );

      v_control_result :=
        public.race_engine_plan_locked_breakaway_peloton_control_v1(
          v_stage_id,
          v_phase,
          v_control_context
        );

      v_transition_result :=
        public.race_engine_plan_locked_stage_state_transition_v1(
          v_stage_id,
          v_phase,
          p_simulation_run_id,
          v_transition_context
        );
    end if;

    begin
      v_effective_wave_cap :=
        nullif(
          v_wave_result
            #>> '{attack_wave_plan,selection_contract,effective_wave_cap}',
          ''
        )::integer;

      v_selected_wave_count :=
        coalesce(
          nullif(
            v_wave_result
              #>> '{attack_wave_plan,selection,selected_count}',
            ''
          )::integer,
          0
        );

      v_attack_count :=
        jsonb_array_length(
          coalesce(
            v_physical_result
              #> '{physical_plan,attack_plans}',
            '[]'::jsonb
          )
        );

      v_bridge_count :=
        jsonb_array_length(
          coalesce(
            v_physical_result
              #> '{physical_plan,bridge_plans}',
            '[]'::jsonb
          )
        );

      v_chase_count :=
        jsonb_array_length(
          coalesce(
            v_physical_result
              #> '{physical_plan,chase_plans}',
            '[]'::jsonb
          )
        );

      v_escape_count :=
        v_attack_count
        + v_bridge_count;

      v_performance_action_count :=
        coalesce(
          nullif(
            v_performance_result
              #>> '{integration_plan,counts,physical_action_count}',
            ''
          )::integer,
          0
        );

      v_performance_integrated_count :=
        coalesce(
          nullif(
            v_performance_result
              #>> '{integration_plan,counts,integrated_rider_plan_count}',
            ''
          )::integer,
          0
        );

      v_performance_blocked_count :=
        coalesce(
          nullif(
            v_performance_result
              #>> '{integration_plan,counts,blocked_rider_plan_count}',
            ''
          )::integer,
          0
        );

      v_control_escape_count :=
        coalesce(
          nullif(
            v_control_result
              #>> '{control_plan,action_population,escape_rider_count}',
            ''
          )::integer,
          0
        );

      v_control_chase_count :=
        coalesce(
          nullif(
            v_control_result
              #>> '{control_plan,action_population,chasing_rider_count}',
            ''
          )::integer,
          0
        );

      v_selected_response_multiplier :=
        nullif(
          v_control_result
            #>> '{control_plan,control_decision,selected_response_multiplier}',
          ''
        )::numeric;

      v_maximum_pursuit_multiplier :=
        nullif(
          v_control_result
            #>> '{control_plan,control_decision,maximum_pursuit_multiplier}',
          ''
        )::numeric;

      v_chase_basis_count :=
        jsonb_array_length(
          coalesce(
            v_control_result
              #> '{control_plan,chase_rider_energy_fatigue_basis}',
            '[]'::jsonb
          )
        );

      v_transition_action_count :=
        coalesce(
          nullif(
            v_transition_result
              #>> '{state_transition_plan,counts,issue01e_action_rider_count}',
            ''
          )::integer,
          0
        );

      v_transition_row_count :=
        coalesce(
          nullif(
            v_transition_result
              #>> '{state_transition_plan,counts,transition_row_count}',
            ''
          )::integer,
          0
        );

      v_transition_blocked_count :=
        coalesce(
          nullif(
            v_transition_result
              #>> '{state_transition_plan,counts,blocked_row_count}',
            ''
          )::integer,
          0
        );

      v_unique_idempotency_key_count :=
        coalesce(
          nullif(
            v_transition_result
              #>> '{state_transition_plan,counts,unique_idempotency_key_count}',
            ''
          )::integer,
          0
        );

    exception
      when invalid_text_representation
        or numeric_value_out_of_range
    then
      return jsonb_build_object(
        'status', 'blocked',
        'reason',
          'issue01_phase_result_contains_invalid_numeric_value',
        'phase_number', v_phase,
        'sqlstate', sqlstate,
        'message', sqlerrm
      );
    end;

    v_component_statuses_pass :=
      coalesce(
        v_wave_result ->> 'status',
        ''
      ) = 'built'

      and coalesce(
            v_physical_result ->> 'status',
            ''
          ) = 'planned'

      and coalesce(
            v_performance_result ->> 'status',
            ''
          ) = 'integrated'

      and coalesce(
            v_control_result ->> 'status',
            ''
          ) = 'planned'

      and coalesce(
            v_transition_result ->> 'status',
            ''
          ) = 'planned';

    v_wave_cap_present :=
      v_effective_wave_cap is not null
      and v_effective_wave_cap > 0;

    v_wave_cap_respected :=
      v_wave_cap_present
      and v_selected_wave_count
          <= v_effective_wave_cap;

    v_mass_escape_guard_pass :=
      v_wave_cap_present
      and v_escape_count
          <= v_effective_wave_cap
      and coalesce(
            (
              v_wave_result
                #>> '{attack_wave_plan,selection,mass_escape_guard_pass}'
            )::boolean,
            false
          );

    v_join_requires_attack_pass :=
      v_bridge_count = 0
      or v_attack_count > 0;

    v_performance_population_pass :=
      v_performance_action_count =
        (
          v_attack_count
          + v_bridge_count
          + v_chase_count
        )

      and v_performance_integrated_count =
          v_performance_action_count

      and v_performance_blocked_count = 0;

    v_control_population_pass :=
      v_control_escape_count =
        v_escape_count

      and v_control_chase_count =
          v_chase_count;

    v_pursuit_cap_pass :=
      v_selected_response_multiplier
        is not null

      and v_maximum_pursuit_multiplier
          is not null

      and v_selected_response_multiplier
          <= v_maximum_pursuit_multiplier;

    v_chase_front_position_pass :=
      case
        when v_chase_count = 0 then true
        else
          v_chase_basis_count =
            v_chase_count

          and not exists (
            select 1
            from jsonb_array_elements(
              coalesce(
                v_control_result
                  #> '{control_plan,chase_rider_energy_fatigue_basis}',
                '[]'::jsonb
              )
            ) chase_rider

            where coalesce(
                    (
                      chase_rider.value
                        ->> 'front_position_required'
                    )::boolean,
                    false
                  ) = false
          )
      end;

    v_transition_population_pass :=
      v_transition_action_count =
        v_performance_action_count

      and v_transition_row_count =
          v_performance_action_count

      and v_transition_blocked_count = 0;

    v_transition_idempotency_pass :=
      v_unique_idempotency_key_count =
        v_transition_row_count

      and not exists (
        select 1
        from jsonb_array_elements(
          coalesce(
            v_transition_result
              #> '{state_transition_plan,transition_rows}',
            '[]'::jsonb
          )
        ) transition_row

        where nullif(
                transition_row.value
                  ->> 'idempotency_key',
                ''
              ) is null
      )

      and (
        select count(
          distinct transition_row.value
            ->> 'idempotency_key'
        )
        from jsonb_array_elements(
          coalesce(
            v_transition_result
              #> '{state_transition_plan,transition_rows}',
            '[]'::jsonb
          )
        ) transition_row
      ) = v_transition_row_count;

    v_phase_pass :=
      v_component_statuses_pass
      and v_wave_cap_present
      and v_wave_cap_respected
      and v_mass_escape_guard_pass
      and v_join_requires_attack_pass
      and v_performance_population_pass
      and v_control_population_pass
      and v_pursuit_cap_pass
      and v_chase_front_position_pass
      and v_transition_population_pass
      and v_transition_idempotency_pass;

    v_all_phase_statuses_pass :=
      v_all_phase_statuses_pass
      and v_component_statuses_pass;

    v_all_wave_caps_present :=
      v_all_wave_caps_present
      and v_wave_cap_present;

    v_all_wave_caps_respected :=
      v_all_wave_caps_respected
      and v_wave_cap_respected;

    v_all_mass_escape_guards_pass :=
      v_all_mass_escape_guards_pass
      and v_mass_escape_guard_pass;

    v_all_join_requires_attack_pass :=
      v_all_join_requires_attack_pass
      and v_join_requires_attack_pass;

    v_all_performance_populations_pass :=
      v_all_performance_populations_pass
      and v_performance_population_pass;

    v_all_control_populations_pass :=
      v_all_control_populations_pass
      and v_control_population_pass;

    v_all_pursuit_caps_pass :=
      v_all_pursuit_caps_pass
      and v_pursuit_cap_pass;

    v_all_chase_front_positions_pass :=
      v_all_chase_front_positions_pass
      and v_chase_front_position_pass;

    v_all_transition_populations_pass :=
      v_all_transition_populations_pass
      and v_transition_population_pass;

    v_all_transition_idempotency_pass :=
      v_all_transition_idempotency_pass
      and v_transition_idempotency_pass;

    v_all_phases_pass :=
      v_all_phases_pass
      and v_phase_pass;

    v_phase_results :=
      v_phase_results
      || jsonb_build_array(
           jsonb_build_object(
             'phase_number', v_phase,

             'component_statuses',
               jsonb_build_object(
                 'attack_wave',
                   v_wave_result ->> 'status',
                 'physical',
                   v_physical_result ->> 'status',
                 'performance',
                   v_performance_result ->> 'status',
                 'peloton_control',
                   v_control_result ->> 'status',
                 'state_transition',
                   v_transition_result ->> 'status'
               ),

             'source_hashes',
               jsonb_build_object(
                 'wave_hash',
                   v_wave_result
                     ->> 'wave_hash',
                 'physical_plan_hash',
                   v_physical_result
                     ->> 'physical_plan_hash',
                 'integration_hash',
                   v_performance_result
                     ->> 'integration_hash',
                 'control_planning_hash',
                   v_control_result
                     ->> 'planning_hash',
                 'state_transition_plan_hash',
                   v_transition_result
                     ->> 'state_transition_plan_hash'
               ),

             'counts',
               jsonb_build_object(
                 'effective_wave_cap',
                   v_effective_wave_cap,
                 'selected_wave_count',
                   v_selected_wave_count,
                 'attack_count',
                   v_attack_count,
                 'bridge_count',
                   v_bridge_count,
                 'chase_count',
                   v_chase_count,
                 'escape_count',
                   v_escape_count,
                 'performance_action_count',
                   v_performance_action_count,
                 'performance_integrated_count',
                   v_performance_integrated_count,
                 'performance_blocked_count',
                   v_performance_blocked_count,
                 'control_escape_count',
                   v_control_escape_count,
                 'control_chase_count',
                   v_control_chase_count,
                 'transition_action_count',
                   v_transition_action_count,
                 'transition_row_count',
                   v_transition_row_count,
                 'transition_blocked_count',
                   v_transition_blocked_count,
                 'unique_idempotency_key_count',
                   v_unique_idempotency_key_count
               ),

             'control',
               jsonb_build_object(
                 'selected_response_multiplier',
                   v_selected_response_multiplier,
                 'maximum_pursuit_multiplier',
                   v_maximum_pursuit_multiplier,
                 'projected_gap_delta_seconds',
                   v_control_result
                     #> '{control_plan,physical_gap_projection,projected_gap_delta_seconds}',
                 'projected_next_gap_seconds',
                   v_control_result
                     #> '{control_plan,physical_gap_projection,projected_next_gap_seconds}',
                 'teleportation_allowed',
                   v_control_result
                     #> '{control_plan,physical_gap_projection,teleportation_allowed}'
               ),

             'checks',
               jsonb_build_object(
                 'component_statuses_pass',
                   v_component_statuses_pass,
                 'wave_cap_present',
                   v_wave_cap_present,
                 'wave_cap_respected',
                   v_wave_cap_respected,
                 'mass_escape_guard_pass',
                   v_mass_escape_guard_pass,
                 'join_requires_attack_pass',
                   v_join_requires_attack_pass,
                 'performance_population_pass',
                   v_performance_population_pass,
                 'control_population_pass',
                   v_control_population_pass,
                 'pursuit_cap_pass',
                   v_pursuit_cap_pass,
                 'chase_front_position_pass',
                   v_chase_front_position_pass,
                 'transition_population_pass',
                   v_transition_population_pass,
                 'transition_idempotency_pass',
                   v_transition_idempotency_pass,
                 'phase_pass',
                   v_phase_pass
               ),

             'attack_wave_result',
               v_wave_result,

             'physical_result',
               v_physical_result,

             'performance_result',
               v_performance_result,

             'control_result',
               v_control_result,

             'transition_result',
               v_transition_result
           )
         );
  end loop;

  v_result_without_hash :=
    jsonb_build_object(
      'orchestrator_schema_version',
        'race_engine_locked_issue01_end_to_end_v1',

      'status',
        case
          when v_all_phases_pass
            then 'planned'
          else 'blocked'
        end,

      'reason',
        case
          when v_all_phases_pass
            then null
          else
            'one_or_more_issue01_phase_contracts_failed'
        end,

      'race_stage_plan_id',
        p_race_stage_plan_id,

      'stage_id', v_stage_id,

      'simulation_run_id',
        p_simulation_run_id,

      'locked_tactical_plan',
        jsonb_build_object(
          'status',
            v_tactical_result
              ->> 'status',
          'snapshot_hash',
            v_tactical_result
              ->> 'snapshot_hash',
          'resolver_hash',
            v_tactical_result
              ->> 'resolver_hash',
          'result',
            v_tactical_result
        ),

      'phase_results',
        v_phase_results,

      'checks',
        jsonb_build_object(
          'phase_count',
            jsonb_array_length(
              v_phase_results
            ),

          'all_four_phases_present',
            jsonb_array_length(
              v_phase_results
            ) = 4,

          'all_phase_statuses_pass',
            v_all_phase_statuses_pass,

          'all_wave_caps_present',
            v_all_wave_caps_present,

          'all_wave_caps_respected',
            v_all_wave_caps_respected,

          'all_mass_escape_guards_pass',
            v_all_mass_escape_guards_pass,

          'all_join_requires_attack_pass',
            v_all_join_requires_attack_pass,

          'all_performance_populations_pass',
            v_all_performance_populations_pass,

          'all_control_populations_pass',
            v_all_control_populations_pass,

          'all_pursuit_caps_pass',
            v_all_pursuit_caps_pass,

          'all_chase_front_positions_pass',
            v_all_chase_front_positions_pass,

          'all_transition_populations_pass',
            v_all_transition_populations_pass,

          'all_transition_idempotency_pass',
            v_all_transition_idempotency_pass,

          'all_phases_pass',
            v_all_phases_pass
        ),

      'write_contract',
        jsonb_build_object(
          'replay_write_allowed', false,
          'group_write_allowed', false,
          'gap_write_allowed', false,
          'speed_write_allowed', false,
          'live_energy_write_allowed', false,
          'stamina_write_allowed', false,
          'fatigue_write_allowed', false,
          'freshness_write_allowed', false,
          'recovery_write_allowed', false,
          'support_consumption_allowed', false,
          'equipment_or_asset_wear_allowed', false,
          'result_or_classification_write_allowed', false,
          'legacy_breakaway_mutator_replacement_allowed', false,
          'runner_integration_allowed', false,
          'historical_processing_allowed', false
        ),

      'next_runtime_boundary',
        jsonb_build_object(
          'runtime_application_deferred',
            true,
          'legacy_breakaway_mutator_still_protected',
            true,
          'final_replay_acceptance_required_before_cutover',
            true
        )
    );

  v_orchestrator_hash :=
    md5(v_result_without_hash::text);

  return jsonb_build_object(
    'status',
      v_result_without_hash
        ->> 'status',

    'reason',
      v_result_without_hash
        ->> 'reason',

    'race_stage_plan_id',
      p_race_stage_plan_id,

    'stage_id', v_stage_id,

    'simulation_run_id',
      p_simulation_run_id,

    'issue01_orchestrator_hash',
      v_orchestrator_hash,

    'issue01_end_to_end_plan',
      v_result_without_hash
  );

exception
  when invalid_text_representation
    or numeric_value_out_of_range
  then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason',
        'orchestrator_context_contains_invalid_numeric_or_uuid_value',
      'sqlstate', sqlstate,
      'message', sqlerrm
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_locked_issue01_runtime_v1(p_race_stage_plan_id uuid, p_simulation_run_id uuid, p_runtime_context_json jsonb DEFAULT NULL::jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_context jsonb := coalesce(p_runtime_context_json, '{}'::jsonb);
  v_plan jsonb;
  v_application_plan jsonb := coalesce(v_context -> 'runtime_application_plan', '{}'::jsonb);
  v_replay_actions jsonb := coalesce(v_application_plan -> 'replay_actions', '[]'::jsonb);
  v_state_plan jsonb := coalesce(v_application_plan -> 'state_transition_plan', '{}'::jsonb);
  v_stage_id uuid;
  v_team_id uuid;
  v_plan_hash text;
  v_application_orchestrator_hash text;
  v_state_dry_run jsonb;
  v_canary_mode boolean := lower(coalesce(
    current_setting('app.issue01h_runtime_wrapper_canary_mode', true),
    'false'
  )) in ('1', 'true', 'on', 'yes');
  v_explicit_apply_permission boolean := lower(coalesce(
    v_context ->> 'allow_runtime_apply',
    'false'
  )) in ('1', 'true', 'on', 'yes');
  v_action_count integer := 0;
  v_unique_key_count integer := 0;
  v_invalid_action_count integer := 0;
  v_finished_mutation_count integer := 0;
  v_incoherent_motion_count integer := 0;
begin
  if p_race_stage_plan_id is null then
    raise exception 'Issue 01H runtime wrapper requires race_stage_plan_id.';
  end if;

  if p_simulation_run_id is null then
    raise exception 'Issue 01H runtime wrapper requires simulation_run_id.';
  end if;

  select stage_plan.stage_id
    into v_stage_id
  from public.race_stage_plans stage_plan
  where stage_plan.id = p_race_stage_plan_id;

  if v_stage_id is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'race_stage_plan_not_found_or_stage_missing',
      'race_stage_plan_id', p_race_stage_plan_id,
      'simulation_run_id', p_simulation_run_id,
      'runtime_writes', 0
    );
  end if;

  v_plan := public.race_engine_plan_locked_issue01_end_to_end_v1(
    p_race_stage_plan_id,
    p_simulation_run_id,
    v_context -> 'orchestrator_context'
  );

  if coalesce(v_plan ->> 'status', '') <> 'planned' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'issue01_orchestrator_not_planned',
      'race_stage_plan_id', p_race_stage_plan_id,
      'simulation_run_id', p_simulation_run_id,
      'apply_requested', p_apply,
      'canary_mode', v_canary_mode,
      'runtime_writes', 0,
      'orchestrator_result', v_plan
    );
  end if;

  v_plan_hash := v_plan ->> 'issue01_orchestrator_hash';

  if not p_apply then
    return jsonb_build_object(
      'status', 'planned_disabled',
      'wrapper_version', 'issue01h_canary_operational_boundary_v1',
      'race_stage_plan_id', p_race_stage_plan_id,
      'simulation_run_id', p_simulation_run_id,
      'apply_requested', false,
      'canary_mode', v_canary_mode,
      'runtime_apply_enabled', false,
      'runtime_writes', 0,
      'runner_called', false,
      'legacy_breakaway_mutator_called', false,
      'replay_writer_called', false,
      'official_state_writer_called', false,
      'official_state_writer_dry_run_called', false,
      'fatigue_writer_called', false,
      'finish_writer_called', false,
      'orchestrator_hash', v_plan_hash,
      'orchestrator_result', v_plan
    );
  end if;

  if not v_canary_mode then
    raise exception
      'Issue 01H runtime apply blocked: app.issue01h_runtime_wrapper_canary_mode is not enabled.';
  end if;

  if not v_explicit_apply_permission then
    raise exception
      'Issue 01H runtime apply blocked: allow_runtime_apply is not explicitly true.';
  end if;

  if jsonb_typeof(v_application_plan) <> 'object'
     or jsonb_typeof(v_replay_actions) <> 'array'
  then
    raise exception 'Issue 01H canary boundary requires an object runtime_application_plan with replay_actions array.';
  end if;

  v_application_orchestrator_hash := nullif(v_application_plan ->> 'orchestrator_hash', '');

  if v_application_orchestrator_hash is null
     or v_application_orchestrator_hash <> v_plan_hash
  then
    raise exception
      'Issue 01H canary boundary blocked: runtime application package orchestrator hash mismatch.';
  end if;

  select
    count(*)::integer,
    count(distinct nullif(action.value ->> 'idempotency_key', ''))::integer,
    count(*) filter (
      where coalesce(action.value ->> 'action_kind', '') not in ('attack', 'bridge', 'chase')
         or nullif(action.value ->> 'rider_id', '') is null
         or nullif(action.value ->> 'idempotency_key', '') is null
         or coalesce(nullif(action.value ->> 'phase_number', '')::integer, 0) not between 1 and 4
    )::integer,
    count(*) filter (
      where coalesce((action.value ->> 'rider_already_finished')::boolean, false)
    )::integer,
    count(*) filter (
      where coalesce(nullif(action.value ->> 'elapsed_seconds', '')::numeric, 0) <= 0
         or coalesce(nullif(action.value ->> 'distance_delta_km', '')::numeric, -1) < 0
         or coalesce(nullif(action.value ->> 'avg_speed_kmh', '')::numeric, -1) < 0
         or abs(
              coalesce(nullif(action.value ->> 'distance_delta_km', '')::numeric, 0)
              - (
                  coalesce(nullif(action.value ->> 'avg_speed_kmh', '')::numeric, 0)
                  * coalesce(nullif(action.value ->> 'elapsed_seconds', '')::numeric, 0)
                  / 3600.0
                )
            ) > 0.05
    )::integer
  into
    v_action_count,
    v_unique_key_count,
    v_invalid_action_count,
    v_finished_mutation_count,
    v_incoherent_motion_count
  from jsonb_array_elements(v_replay_actions) action;

  if v_action_count = 0 then
    raise exception 'Issue 01H canary boundary requires at least one reviewed replay action.';
  end if;

  if v_unique_key_count <> v_action_count then
    raise exception 'Issue 01H canary boundary blocked: replay action idempotency keys are missing or duplicated.';
  end if;

  if v_invalid_action_count > 0 then
    raise exception 'Issue 01H canary boundary blocked: invalid replay action contract rows: %.', v_invalid_action_count;
  end if;

  if v_finished_mutation_count > 0 then
    raise exception 'Issue 01H canary boundary blocked: finished riders are immutable.';
  end if;

  if v_incoherent_motion_count > 0 then
    raise exception 'Issue 01H canary boundary blocked: distance and speed are not physically coherent.';
  end if;

  if jsonb_typeof(v_state_plan) <> 'object' then
    raise exception 'Issue 01H canary boundary requires state_transition_plan object.';
  end if;

  v_team_id := nullif(v_application_plan ->> 'team_id', '')::uuid;

  /*
   * Authoritative writer is invoked only in dry-run mode. This proves the
   * official-state boundary and its existing idempotency contract without
   * changing rider state or marking outcomes consumed.
   */
  v_state_dry_run := public.race_engine_apply_stage_command_deltas_to_official_state_v1(
    v_stage_id,
    v_team_id,
    true,
    'issue01h_runtime_wrapper_canary_v1',
    false
  );

  return jsonb_build_object(
    'status', 'canary_validated_no_writes',
    'wrapper_version', 'issue01h_canary_operational_boundary_v1',
    'race_stage_plan_id', p_race_stage_plan_id,
    'stage_id', v_stage_id,
    'simulation_run_id', p_simulation_run_id,
    'apply_requested', true,
    'canary_mode', true,
    'runtime_apply_enabled', false,
    'runtime_writes', 0,
    'runner_called', false,
    'legacy_breakaway_mutator_called', false,
    'replay_writer_called', false,
    'official_state_writer_called', false,
    'official_state_writer_dry_run_called', true,
    'fatigue_writer_called', false,
    'finish_writer_called', false,
    'orchestrator_hash', v_plan_hash,
    'replay_action_count', v_action_count,
    'unique_idempotency_key_count', v_unique_key_count,
    'invalid_action_count', v_invalid_action_count,
    'finished_mutation_count', v_finished_mutation_count,
    'incoherent_motion_count', v_incoherent_motion_count,
    'state_transition_plan_present', v_state_plan <> '{}'::jsonb,
    'official_state_dry_run_result', v_state_dry_run,
    'orchestrator_result', v_plan
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enrich_missed_startlist_deadline_event_penalty_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance'
AS $function$
declare
  v_race_class_code text;
  v_score_delta integer := -10;
  v_cash_penalty bigint := 0;
  v_commitment_event_id uuid;
  v_penalty_result jsonb := '{}'::jsonb;
  v_finance_result jsonb := '{}'::jsonb;
begin
  if new.event_type <> 'missed_startlist' then
    return new;
  end if;

  select
    coalesce(
      rer.race_class_code,
      to_jsonb(r)->>'class',
      to_jsonb(r)->>'race_class',
      to_jsonb(r)->>'category'
    )
  into v_race_class_code
  from public.races r
  left join public.race_entry_rules rer
    on rer.race_id = r.id
  where r.id = new.race_id
  limit 1;

  select
    coalesce(pr.missed_startlist_score_delta, -10),
    coalesce(pr.missed_startlist_cash, 0)::bigint
  into
    v_score_delta,
    v_cash_penalty
  from public.race_application_penalty_rules pr
  where pr.race_class_code = v_race_class_code
  limit 1;

  v_score_delta := coalesce(v_score_delta, -10);
  v_cash_penalty := coalesce(v_cash_penalty, 0);

  if coalesce(new.score_delta, 0) = 0 then
    new.score_delta := v_score_delta;
  end if;

  if coalesce(new.cash_penalty, 0) = 0 then
    new.cash_penalty := v_cash_penalty;
  end if;

  new.notes := concat(
    coalesce(new.notes, ''),
    case when coalesce(new.notes, '') = '' then '' else ' ' end,
    'Official missed-startlist penalty: race class ',
    coalesce(v_race_class_code, 'unknown'),
    ', cash penalty $',
    coalesce(new.cash_penalty, 0)::text,
    ', commitment score ',
    case when coalesce(new.score_delta, 0) >= 0 then '+' else '' end,
    coalesce(new.score_delta, 0)::text,
    '.'
  );

  if new.race_team_entry_id is not null
    and new.club_id is not null
    and new.race_id is not null then

    v_penalty_result := public.apply_race_commitment_penalty_v1(
      new.club_id,
      new.race_id,
      new.race_team_entry_id,
      'missed_startlist',
      new.score_delta,
      new.cash_penalty::bigint,
      'Rider deadline passed with no valid submitted startlist.'
    );

    select e.id
    into v_commitment_event_id
    from public.race_commitment_score_events e
    where e.race_team_entry_id = new.race_team_entry_id
      and e.event_type = 'missed_startlist'
    order by e.created_at desc
    limit 1;

    if v_commitment_event_id is not null then
      v_finance_result :=
        public.finance_record_missed_startlist_fine_v1(v_commitment_event_id);
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_build_locked_issue01_runtime_package_v1(p_race_stage_plan_id uuid, p_simulation_run_id uuid, p_orchestrator_context_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_orchestrator jsonb;
  v_orchestrator_status text;
  v_orchestrator_hash text;
  v_stage_id uuid;

  v_phase_results jsonb;
  v_phase_record record;
  v_phase_number integer;
  v_phase_count integer := 0;
  v_all_phases_pass boolean := false;

  v_action_kind text;
  v_action_array_key text;
  v_action_record record;
  v_action_json jsonb;
  v_action_keys jsonb;
  v_action_rider_id uuid;
  v_action_key text;

  v_action_sources jsonb := '[]'::jsonb;
  v_transition_sources jsonb := '[]'::jsonb;
  v_field_inventory jsonb := '[]'::jsonb;

  v_attack_count integer := 0;
  v_bridge_count integer := 0;
  v_chase_count integer := 0;
  v_action_count integer := 0;
  v_invalid_action_rider_count integer := 0;

  v_transition_record record;
  v_transition_json jsonb;
  v_transition_rider_id uuid;
  v_transition_key text;
  v_transition_count integer := 0;
  v_invalid_transition_rider_count integer := 0;
  v_missing_transition_key_count integer := 0;

  v_distinct_action_key_count integer := 0;
  v_distinct_transition_key_count integer := 0;
  v_distinct_action_rider_count integer := 0;

  v_package_ready boolean := false;
  v_package_without_hash jsonb;
  v_package_hash text;
begin
  if p_race_stage_plan_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'race_stage_plan_id_required',
      'runtime_apply_enabled', false,
      'operational_writes', 0
    );
  end if;

  if p_simulation_run_id is null then
    return jsonb_build_object(
      'status', 'invalid_request',
      'reason', 'simulation_run_id_required',
      'race_stage_plan_id', p_race_stage_plan_id,
      'runtime_apply_enabled', false,
      'operational_writes', 0
    );
  end if;

  select stage_plan.stage_id
  into v_stage_id
  from public.race_stage_plans stage_plan
  where stage_plan.id = p_race_stage_plan_id;

  if v_stage_id is null then
    return jsonb_build_object(
      'status', 'not_found',
      'reason', 'race_stage_plan_not_found_or_stage_id_missing',
      'race_stage_plan_id', p_race_stage_plan_id,
      'simulation_run_id', p_simulation_run_id,
      'runtime_apply_enabled', false,
      'operational_writes', 0
    );
  end if;

  v_orchestrator :=
    public.race_engine_plan_locked_issue01_end_to_end_v1(
      p_race_stage_plan_id,
      p_simulation_run_id,
      p_orchestrator_context_json
    );

  v_orchestrator_status :=
    coalesce(
      v_orchestrator ->> 'status',
      ''
    );

  v_orchestrator_hash :=
    nullif(
      v_orchestrator ->> 'issue01_orchestrator_hash',
      ''
    );

  if v_orchestrator_status <> 'planned' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'issue01_orchestrator_not_planned',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_stage_id,
      'simulation_run_id', p_simulation_run_id,
      'orchestrator_status', v_orchestrator_status,
      'orchestrator_reason', v_orchestrator ->> 'reason',
      'orchestrator_checks',
        coalesce(
          v_orchestrator #> '{issue01_end_to_end_plan,checks}',
          '{}'::jsonb
        ),
      'runtime_apply_enabled', false,
      'operational_writes', 0
    );
  end if;

  v_phase_results :=
    coalesce(
      v_orchestrator
        #> '{issue01_end_to_end_plan,phase_results}',
      '[]'::jsonb
    );

  if jsonb_typeof(v_phase_results) is distinct from 'array' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason', 'orchestrator_phase_results_not_array',
      'race_stage_plan_id', p_race_stage_plan_id,
      'stage_id', v_stage_id,
      'simulation_run_id', p_simulation_run_id,
      'orchestrator_hash', v_orchestrator_hash,
      'runtime_apply_enabled', false,
      'operational_writes', 0
    );
  end if;

  v_phase_count := jsonb_array_length(v_phase_results);

  begin
    v_all_phases_pass :=
      coalesce(
        nullif(
          v_orchestrator
            #>> '{issue01_end_to_end_plan,checks,all_phases_pass}',
          ''
        )::boolean,
        false
      );
  exception
    when invalid_text_representation then
      v_all_phases_pass := false;
  end;

  for v_phase_record in
    select phase_row.value
    from jsonb_array_elements(v_phase_results) phase_row(value)
  loop
    begin
      v_phase_number :=
        nullif(
          v_phase_record.value ->> 'phase_number',
          ''
        )::integer;
    exception
      when invalid_text_representation then
        v_phase_number := null;
    end;

    for v_action_kind, v_action_array_key in
      select *
      from (
        values
          ('attack'::text, 'attack_plans'::text),
          ('bridge'::text, 'bridge_plans'::text),
          ('chase'::text, 'chase_plans'::text)
      ) action_type(action_kind, action_array_key)
    loop
      for v_action_record in
        select
          action_row.value,
          action_row.ordinality
        from jsonb_array_elements(
          coalesce(
            v_phase_record.value
              #> array[
                   'physical_result',
                   'physical_plan',
                   v_action_array_key
                 ],
            '[]'::jsonb
          )
        ) with ordinality action_row(value, ordinality)
      loop
        v_action_json :=
          coalesce(
            v_action_record.value,
            '{}'::jsonb
          );

        begin
          v_action_rider_id :=
            nullif(
              v_action_json ->> 'rider_id',
              ''
            )::uuid;
        exception
          when invalid_text_representation then
            v_action_rider_id := null;
        end;

        if v_action_rider_id is null then
          v_invalid_action_rider_count :=
            v_invalid_action_rider_count + 1;
        end if;

        select coalesce(
          jsonb_agg(key_row.key order by key_row.key),
          '[]'::jsonb
        )
        into v_action_keys
        from jsonb_object_keys(v_action_json) key_row(key);

        v_action_key :=
          md5(
            concat_ws(
              ':',
              'issue01-runtime-package-v1',
              coalesce(v_orchestrator_hash, ''),
              coalesce(v_phase_number::text, ''),
              v_action_kind,
              coalesce(v_action_rider_id::text, ''),
              v_action_record.ordinality::text
            )
          );

        v_action_sources :=
          v_action_sources
          || jsonb_build_array(
               jsonb_build_object(
                 'phase_number', v_phase_number,
                 'action_kind', v_action_kind,
                 'rider_id', v_action_rider_id,
                 'source_ordinality', v_action_record.ordinality,
                 'source_path',
                   format(
                     'issue01_end_to_end_plan.phase_results[%s].physical_result.physical_plan.%s[%s]',
                     coalesce(v_phase_number::text, '?'),
                     v_action_array_key,
                     v_action_record.ordinality
                   ),
                 'source_physical_plan_hash',
                   v_phase_record.value
                     #>> '{physical_result,physical_plan_hash}',
                 'source_transition_plan_hash',
                   v_phase_record.value
                     #>> '{transition_result,state_transition_plan_hash}',
                 'available_field_keys', v_action_keys,
                 'package_action_key', v_action_key,
                 'raw_action', v_action_json
               )
             );

        v_field_inventory :=
          v_field_inventory
          || jsonb_build_array(
               jsonb_build_object(
                 'phase_number', v_phase_number,
                 'action_kind', v_action_kind,
                 'rider_id', v_action_rider_id,
                 'source_ordinality', v_action_record.ordinality,
                 'available_field_keys', v_action_keys
               )
             );

        v_action_count := v_action_count + 1;

        if v_action_kind = 'attack' then
          v_attack_count := v_attack_count + 1;
        elsif v_action_kind = 'bridge' then
          v_bridge_count := v_bridge_count + 1;
        elsif v_action_kind = 'chase' then
          v_chase_count := v_chase_count + 1;
        end if;
      end loop;
    end loop;

    for v_transition_record in
      select
        transition_row.value,
        transition_row.ordinality
      from jsonb_array_elements(
        coalesce(
          v_phase_record.value
            #> '{transition_result,state_transition_plan,transition_rows}',
          '[]'::jsonb
        )
      ) with ordinality transition_row(value, ordinality)
    loop
      v_transition_json :=
        coalesce(
          v_transition_record.value,
          '{}'::jsonb
        );

      begin
        v_transition_rider_id :=
          nullif(
            v_transition_json ->> 'rider_id',
            ''
          )::uuid;
      exception
        when invalid_text_representation then
          v_transition_rider_id := null;
      end;

      if v_transition_rider_id is null then
        v_invalid_transition_rider_count :=
          v_invalid_transition_rider_count + 1;
      end if;

      v_transition_key :=
        nullif(
          v_transition_json ->> 'idempotency_key',
          ''
        );

      if v_transition_key is null then
        v_missing_transition_key_count :=
          v_missing_transition_key_count + 1;
      end if;

      v_transition_sources :=
        v_transition_sources
        || jsonb_build_array(
             jsonb_build_object(
               'phase_number', v_phase_number,
               'rider_id', v_transition_rider_id,
               'source_ordinality', v_transition_record.ordinality,
               'idempotency_key', v_transition_key,
               'source_path',
                 format(
                   'issue01_end_to_end_plan.phase_results[%s].transition_result.state_transition_plan.transition_rows[%s]',
                   coalesce(v_phase_number::text, '?'),
                   v_transition_record.ordinality
                 ),
               'raw_transition', v_transition_json
             )
           );

      v_transition_count := v_transition_count + 1;
    end loop;
  end loop;

  select count(distinct action_row.value ->> 'package_action_key')::integer
  into v_distinct_action_key_count
  from jsonb_array_elements(v_action_sources) action_row(value)
  where nullif(
          action_row.value ->> 'package_action_key',
          ''
        ) is not null;

  select count(distinct action_row.value ->> 'rider_id')::integer
  into v_distinct_action_rider_count
  from jsonb_array_elements(v_action_sources) action_row(value)
  where nullif(
          action_row.value ->> 'rider_id',
          ''
        ) is not null;

  select count(distinct transition_row.value ->> 'idempotency_key')::integer
  into v_distinct_transition_key_count
  from jsonb_array_elements(v_transition_sources) transition_row(value)
  where nullif(
          transition_row.value ->> 'idempotency_key',
          ''
        ) is not null;

  v_package_ready :=
    v_phase_count = 4
    and v_all_phases_pass
    and v_orchestrator_hash is not null
    and v_action_count > 0
    and v_action_count = v_distinct_action_key_count
    and v_invalid_action_rider_count = 0
    and v_transition_count > 0
    and v_invalid_transition_rider_count = 0
    and v_missing_transition_key_count = 0
    and v_transition_count = v_distinct_transition_key_count;

  v_package_without_hash :=
    jsonb_build_object(
      'package_schema_version',
        'race_engine_locked_issue01_runtime_package_v1',
      'race_stage_plan_id',
        p_race_stage_plan_id,
      'stage_id',
        v_stage_id,
      'simulation_run_id',
        p_simulation_run_id,
      'orchestrator_hash',
        v_orchestrator_hash,
      'runtime_apply_enabled',
        false,
      'operational_writes',
        0,
      'action_sources',
        v_action_sources,
      'state_transition_sources',
        v_transition_sources,
      'field_inventory',
        v_field_inventory,
      'counts',
        jsonb_build_object(
          'phase_count', v_phase_count,
          'action_count', v_action_count,
          'attack_count', v_attack_count,
          'bridge_count', v_bridge_count,
          'chase_count', v_chase_count,
          'distinct_action_rider_count',
            v_distinct_action_rider_count,
          'distinct_action_key_count',
            v_distinct_action_key_count,
          'transition_count', v_transition_count,
          'distinct_transition_key_count',
            v_distinct_transition_key_count,
          'invalid_action_rider_count',
            v_invalid_action_rider_count,
          'invalid_transition_rider_count',
            v_invalid_transition_rider_count,
          'missing_transition_key_count',
            v_missing_transition_key_count
        ),
      'source_checks',
        coalesce(
          v_orchestrator
            #> '{issue01_end_to_end_plan,checks}',
          '{}'::jsonb
        ),
      'writer_boundary',
        jsonb_build_object(
          'replay_motion_values_invented', false,
          'coefficients_invented', false,
          'source_actions_preserved_verbatim', true,
          'source_transitions_preserved_verbatim', true,
          'package_ready_for_isolated_writer_design',
            v_package_ready,
          'production_runtime_writer_enabled', false,
          'runner_integration_enabled', false,
          'legacy_mutator_replaced', false
        )
    );

  v_package_hash :=
    md5(
      v_package_without_hash::text
    );

  return jsonb_build_object(
    'status',
      case
        when v_package_ready
          then 'built'
        else 'blocked'
      end,
    'reason',
      case
        when v_package_ready
          then null
        else 'runtime_package_integrity_gate_failed'
      end,
    'race_stage_plan_id', p_race_stage_plan_id,
    'stage_id', v_stage_id,
    'simulation_run_id', p_simulation_run_id,
    'orchestrator_status', v_orchestrator_status,
    'orchestrator_hash', v_orchestrator_hash,
    'runtime_package_hash', v_package_hash,
    'runtime_apply_enabled', false,
    'operational_writes', 0,
    'runtime_application_package',
      v_package_without_hash
      || jsonb_build_object(
           'runtime_package_hash',
             v_package_hash
         ),
    'decision_gate',
      jsonb_build_object(
        'eligible_for_isolated_real_rio_stage1_rollback_acceptance',
          v_package_ready,
        'eligible_for_production_runner_integration',
          false,
        'eligible_to_replace_legacy_mutator',
          false,
        'next_step',
          case
            when v_package_ready then
              'run one isolated rollback-only real Rio Stage 1 package acceptance and inspect exact action fields before installing any operational writer'
            else
              'inspect the returned counts and field inventory; correct only the failed package-integrity contract'
          end
      )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_enqueue_rio_bk_issue01_phase1_deltas_v1(p_race_stage_plan_id uuid, p_simulation_run_id uuid, p_application_rows_json jsonb, p_context_json jsonb DEFAULT NULL::jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_plan_id constant uuid :=
    'b79f44d3-f309-441c-b39d-122725ac1496'::uuid;
  c_race_id constant uuid :=
    '65739034-f9e5-4b5c-8f21-4ea27451e0d4'::uuid;
  c_stage_id constant uuid :=
    '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid;
  c_club_id constant uuid :=
    '49caba57-9a5e-4820-b4bf-06cfc684e8b2'::uuid;
  c_phase_number constant integer := 1;
  c_source_version constant text :=
    'issue01_rio_bk_stage1_phase1_queue_v1';
  c_accepted_runtime_mapping_hash constant text :=
    '4df122c223d855c47969a5e4fbb78e01';

  v_context jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_rows jsonb := coalesce(p_application_rows_json, '[]'::jsonb);

  v_canary_mode boolean := lower(
    coalesce(
      current_setting(
        'app.issue01_rio_bk_phase1_queue_canary_mode',
        true
      ),
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_explicit_apply_permission boolean := lower(
    coalesce(
      v_context ->> 'allow_rio_bk_phase1_queue_apply',
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_runtime_mapping_hash text :=
    nullif(
      v_context ->> 'runtime_mapping_hash',
      ''
    );

  v_row_count integer := 0;
  v_attack_count integer := 0;
  v_chase_count integer := 0;
  v_bridge_count integer := 0;
  v_unique_rider_count integer := 0;
  v_unique_transition_key_count integer := 0;
  v_invalid_row_count integer := 0;
  v_distance_mismatch_count integer := 0;
  v_preserve_contract_failure_count integer := 0;
  v_consumed_conflict_count integer := 0;
  v_live_state_count integer := 0;
  v_finished_state_count integer := 0;
  v_upserted_rows integer := 0;

  v_application_rows_hash text;
  v_preview_rows jsonb := '[]'::jsonb;
begin
  if p_race_stage_plan_id is distinct from c_plan_id then
    raise exception
      'Rio BK Phase 1 queue adapter accepts only race_stage_plan_id %.',
      c_plan_id;
  end if;

  if p_simulation_run_id is null then
    raise exception
      'Rio BK Phase 1 queue adapter requires simulation_run_id.';
  end if;

  if jsonb_typeof(v_rows) <> 'array' then
    raise exception
      'Rio BK Phase 1 queue adapter requires application_rows_json to be a JSON array.';
  end if;

  if v_runtime_mapping_hash is distinct from
     c_accepted_runtime_mapping_hash
  then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: runtime mapping hash mismatch. Expected %, received %.',
      c_accepted_runtime_mapping_hash,
      v_runtime_mapping_hash;
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where lower(coalesce(row_data.value ->> 'action_kind', '')) =
        'attack'
    )::integer,
    count(*) filter (
      where lower(coalesce(row_data.value ->> 'action_kind', '')) =
        'chase'
    )::integer,
    count(*) filter (
      where lower(coalesce(row_data.value ->> 'action_kind', '')) =
        'bridge'
    )::integer,
    count(
      distinct nullif(
        row_data.value ->> 'rider_id',
        ''
      )
    )::integer,
    count(
      distinct nullif(
        row_data.value ->> 'transition_idempotency_key',
        ''
      )
    )::integer,

    count(*) filter (
      where nullif(row_data.value ->> 'rider_id', '') is null
         or nullif(row_data.value ->> 'transition_idempotency_key', '') is null
         or lower(coalesce(row_data.value ->> 'action_kind', ''))
              not in ('attack', 'chase', 'bridge')
         or coalesce(
              nullif(
                row_data.value ->> 'phase_number',
                ''
              )::integer,
              0
            ) <> c_phase_number
         or coalesce(
              nullif(
                row_data.value ->> 'avg_speed_kmh',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              nullif(
                row_data.value ->> 'elapsed_seconds',
                ''
              )::numeric,
              -1
            ) <= 0
         or coalesce(
              nullif(
                row_data.value ->> 'distance_delta_km',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              nullif(
                row_data.value ->> 'stamina_delta_points',
                ''
              )::numeric,
              1
            ) > 0
         or coalesce(
              nullif(
                row_data.value ->> 'post_stage_fatigue_delta',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              row_data.value ->> 'blocked_reason',
              ''
            ) <> ''
    )::integer,

    count(*) filter (
      where abs(
        coalesce(
          nullif(
            row_data.value ->> 'distance_delta_km',
            ''
          )::numeric,
          -999999
        )
        -
        (
          coalesce(
            nullif(
              row_data.value ->> 'avg_speed_kmh',
              ''
            )::numeric,
            0
          )
          *
          coalesce(
            nullif(
              row_data.value ->> 'elapsed_seconds',
              ''
            )::numeric,
            0
          )
          / 3600.0
        )
      ) > 0.000001
    )::integer,

    count(*) filter (
      where (
        lower(coalesce(row_data.value ->> 'action_kind', '')) =
          'attack'
        and (
          coalesce(
            nullif(
              row_data.value
                ->> 'attack_initial_separation_seconds',
              ''
            )::numeric,
            -1
          ) < 0
          or coalesce(
            nullif(
              row_data.value
                ->> 'attack_initial_separation_distance_km',
              ''
            )::numeric,
            -1
          ) < 0
        )
      )
      or (
        lower(coalesce(row_data.value ->> 'action_kind', '')) =
          'chase'
        and (
          coalesce(
            (
              row_data.value
                ->> 'preserve_live_gap_seconds'
            )::boolean,
            false
          ) is false
          or coalesce(
            (
              row_data.value
                ->> 'preserve_live_group_assignment'
            )::boolean,
            false
          ) is false
          or coalesce(
            (
              row_data.value
                ->> 'direct_gap_write'
            )::boolean,
            true
          ) is true
          or coalesce(
            (
              row_data.value
                ->> 'direct_group_reassignment'
            )::boolean,
            true
          ) is true
        )
      )
    )::integer

  into
    v_row_count,
    v_attack_count,
    v_chase_count,
    v_bridge_count,
    v_unique_rider_count,
    v_unique_transition_key_count,
    v_invalid_row_count,
    v_distance_mismatch_count,
    v_preserve_contract_failure_count

  from jsonb_array_elements(v_rows)
    row_data(value);

  if v_row_count <> 3
     or v_attack_count <> 1
     or v_chase_count <> 2
     or v_bridge_count <> 0
  then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: exact accepted population is 3 rows (1 attack, 2 chase, 0 bridge). Received rows %, attack %, chase %, bridge %.',
      v_row_count,
      v_attack_count,
      v_chase_count,
      v_bridge_count;
  end if;

  if v_unique_rider_count <> v_row_count
     or v_unique_transition_key_count <> v_row_count
     or v_invalid_row_count <> 0
     or v_distance_mismatch_count <> 0
     or v_preserve_contract_failure_count <> 0
  then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: row contract failed (unique riders %, unique keys %, invalid %, distance mismatch %, preserve-contract failures %).',
      v_unique_rider_count,
      v_unique_transition_key_count,
      v_invalid_row_count,
      v_distance_mismatch_count,
      v_preserve_contract_failure_count;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_rows) row_data(value)
    where nullif(
            row_data.value ->> 'rider_id',
            ''
          )::uuid not in (
            '1a29ac57-1fb8-4f7c-a24e-3f9e76b3ad51'::uuid,
            '35f9dedb-9eb6-4d7a-ab28-7289050843ca'::uuid,
            'acbbc56e-ea56-4d45-9e0e-5025ca73c2e5'::uuid
          )
  ) then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: application row contains a rider outside the exact accepted BK canary population.';
  end if;

  if not exists (
    select 1
    from public.race_stage_plans plan
    join public.race_preparations preparation
      on preparation.id = plan.race_preparation_id
    where plan.id = c_plan_id
      and plan.stage_id = c_stage_id
      and plan.stage_number = 1
      and preparation.race_id = c_race_id
      and preparation.club_id = c_club_id
  ) then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: exact accepted Stage Plan scope no longer exists.';
  end if;

  select count(*)::integer
  into v_consumed_conflict_count
  from public.race_engine_stage_command_outcome_delta_applications queue_row
  where queue_row.stage_id = c_stage_id
    and queue_row.club_id = c_club_id
    and queue_row.source_version = c_source_version
    and queue_row.application_status =
      'consumed_by_finalizer';

  if v_consumed_conflict_count > 0 then
    raise exception
      'Rio BK Phase 1 queue adapter blocked: % rows for this exact source were already consumed and may not be overwritten.',
      v_consumed_conflict_count;
  end if;

  v_application_rows_hash :=
    md5(v_rows::text);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'stage_id', c_stage_id,
        'club_id', c_club_id,
        'rider_id',
          nullif(
            row_data.value ->> 'rider_id',
            ''
          )::uuid,
        'source_version', c_source_version,
        'event_count', 1,
        'first_event_km',
          nullif(
            row_data.value ->> 'launch_km',
            ''
          )::numeric,
        'last_event_km',
          (
            nullif(
              row_data.value ->> 'launch_km',
              ''
            )::numeric
            +
            nullif(
              row_data.value ->> 'distance_delta_km',
              ''
            )::numeric
          ),
        'command_codes',
          jsonb_build_array(
            lower(row_data.value ->> 'action_kind')
          ),
        'outcome_types',
          jsonb_build_array(
            lower(row_data.value ->> 'action_kind')
          ),
        'tactical_success_count', 1,
        'stamina_delta_total',
          greatest(
            0,
            -nullif(
              row_data.value ->> 'stamina_delta_points',
              ''
            )::numeric
          ),
        'fatigue_delta_total',
          greatest(
            0,
            nullif(
              row_data.value
                ->> 'post_stage_fatigue_delta',
              ''
            )::numeric
          ),
        'attack_attempts_added',
          case
            when lower(row_data.value ->> 'action_kind') =
              'attack'
            then 1
            else 0
          end,
        'breakaway_km_added',
          case
            when lower(row_data.value ->> 'action_kind') =
              'attack'
            then nullif(
              row_data.value ->> 'distance_delta_km',
              ''
            )::numeric
            else 0
          end,
        'transition_idempotency_key',
          row_data.value ->> 'transition_idempotency_key',
        'distance_delta_km',
          nullif(
            row_data.value ->> 'distance_delta_km',
            ''
          )::numeric,
        'queue_apply_requested', p_apply
      )
      order by
        lower(row_data.value ->> 'action_kind'),
        row_data.value ->> 'rider_id'
    ),
    '[]'::jsonb
  )
  into v_preview_rows
  from jsonb_array_elements(v_rows)
    row_data(value);

  if not p_apply then
    return jsonb_build_object(
      'status',
        'validated_disabled',
      'adapter_version',
        c_source_version,
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'race_id',
        c_race_id,
      'stage_id',
        c_stage_id,
      'club_id',
        c_club_id,
      'phase_number',
        c_phase_number,
      'accepted_runtime_mapping_hash',
        c_accepted_runtime_mapping_hash,
      'application_rows_hash',
        v_application_rows_hash,
      'row_count',
        v_row_count,
      'canary_mode',
        v_canary_mode,
      'explicit_apply_permission',
        v_explicit_apply_permission,
      'runtime_apply_enabled',
        false,
      'queue_writes',
        0,
      'official_state_writer_called',
        false,
      'replay_writer_called',
        false,
      'direct_gap_write',
        false,
      'direct_group_reassignment',
        false,
      'preview_rows',
        v_preview_rows
    );
  end if;

  if not v_canary_mode
     or not v_explicit_apply_permission
  then
    return jsonb_build_object(
      'status',
        'blocked',
      'reason',
        'rio_bk_phase1_queue_apply_requires_canary_mode_and_explicit_permission',
      'adapter_version',
        c_source_version,
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'canary_mode',
        v_canary_mode,
      'explicit_apply_permission',
        v_explicit_apply_permission,
      'queue_writes',
        0,
      'official_state_writer_called',
        false,
      'replay_writer_called',
        false
    );
  end if;

  if not exists (
    select 1
    from public.race_stage_simulation_runs run_row
    where run_row.id = p_simulation_run_id
      and run_row.race_id = c_race_id
      and run_row.stage_id = c_stage_id
  ) then
    raise exception
      'Rio BK Phase 1 queue adapter apply blocked: simulation run does not match the exact Rio race/stage scope.';
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where lower(
        coalesce(state_row.stage_status, '')
      ) in (
        'finished',
        'dnf',
        'dns',
        'withdrawn',
        'outside_time_limit'
      )
    )::integer
  into
    v_live_state_count,
    v_finished_state_count
  from public.race_stage_rider_states state_row
  where state_row.simulation_run_id =
      p_simulation_run_id
    and state_row.stage_id = c_stage_id
    and state_row.team_id = c_club_id
    and state_row.rider_id in (
      select
        nullif(
          row_data.value ->> 'rider_id',
          ''
        )::uuid
      from jsonb_array_elements(v_rows)
        row_data(value)
    );

  if v_live_state_count <> v_row_count
     or v_finished_state_count <> 0
  then
    raise exception
      'Rio BK Phase 1 queue adapter apply blocked: live rider-state boundary mismatch (required %, found %, already-finished %).',
      v_row_count,
      v_live_state_count,
      v_finished_state_count;
  end if;

  insert into public.race_engine_stage_command_outcome_delta_applications (
    stage_id,
    club_id,
    rider_id,
    rider_name,
    event_count,
    first_event_km,
    last_event_km,
    command_codes,
    outcome_types,
    tactical_success_count,
    stamina_delta_total,
    fatigue_delta_total,
    attack_attempts_added,
    breakaway_km_added,
    support_work_added,
    protection_received_added,
    incident_count,
    mechanical_count,
    incident_types,
    mechanical_types,
    application_status,
    source_version,
    official_delta_json,
    metadata,
    prepared_at,
    consumed_at,
    updated_at
  )
  select
    c_stage_id,
    c_club_id,
    nullif(
      row_data.value ->> 'rider_id',
      ''
    )::uuid,
    null,
    1,
    nullif(
      row_data.value ->> 'launch_km',
      ''
    )::numeric,
    (
      nullif(
        row_data.value ->> 'launch_km',
        ''
      )::numeric
      +
      nullif(
        row_data.value ->> 'distance_delta_km',
        ''
      )::numeric
    ),
    jsonb_build_array(
      lower(row_data.value ->> 'action_kind')
    ),
    jsonb_build_array(
      lower(row_data.value ->> 'action_kind')
    ),
    1,
    greatest(
      0,
      -nullif(
        row_data.value ->> 'stamina_delta_points',
        ''
      )::numeric
    ),
    greatest(
      0,
      nullif(
        row_data.value ->> 'post_stage_fatigue_delta',
        ''
      )::numeric
    ),
    case
      when lower(row_data.value ->> 'action_kind') =
        'attack'
      then 1
      else 0
    end,
    case
      when lower(row_data.value ->> 'action_kind') =
        'attack'
      then nullif(
        row_data.value ->> 'distance_delta_km',
        ''
      )::numeric
      else 0
    end,
    0,
    0,
    0,
    0,
    '[]'::jsonb,
    '[]'::jsonb,
    'prepared',
    c_source_version,

    jsonb_build_object(
      'issue01_phase',
        c_phase_number,
      'action_kind',
        lower(row_data.value ->> 'action_kind'),
      'live_energy_delta_pct',
        nullif(
          row_data.value ->> 'live_energy_delta_pct',
          ''
        )::numeric,
      'stamina_delta_points',
        nullif(
          row_data.value ->> 'stamina_delta_points',
          ''
        )::numeric,
      'post_stage_fatigue_delta',
        nullif(
          row_data.value ->> 'post_stage_fatigue_delta',
          ''
        )::numeric,
      'target_fatigue_integer',
        nullif(
          row_data.value ->> 'target_fatigue_integer',
          ''
        )::integer,
      'avg_speed_kmh',
        nullif(
          row_data.value ->> 'avg_speed_kmh',
          ''
        )::numeric,
      'elapsed_seconds',
        nullif(
          row_data.value ->> 'elapsed_seconds',
          ''
        )::numeric,
      'distance_delta_km',
        nullif(
          row_data.value ->> 'distance_delta_km',
          ''
        )::numeric,
      'distance_derivation',
        'avg_speed_kmh * elapsed_seconds / 3600',
      'attack_initial_separation_seconds',
        nullif(
          row_data.value
            ->> 'attack_initial_separation_seconds',
          ''
        )::numeric,
      'attack_initial_separation_distance_km',
        nullif(
          row_data.value
            ->> 'attack_initial_separation_distance_km',
          ''
        )::numeric,
      'transition_idempotency_key',
        row_data.value ->> 'transition_idempotency_key'
    ),

    jsonb_build_object(
      'source',
        c_source_version,
      'race_id',
        c_race_id,
      'stage_id',
        c_stage_id,
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'phase_number',
        c_phase_number,
      'runtime_mapping_hash',
        c_accepted_runtime_mapping_hash,
      'application_rows_hash',
        v_application_rows_hash,
      'source_action_hash',
        row_data.value ->> 'source_action_hash',
      'transition_idempotency_key',
        row_data.value ->> 'transition_idempotency_key',
      'direct_gap_write',
        false,
      'direct_group_reassignment',
        false,
      'preserve_live_gap_seconds',
        coalesce(
          (
            row_data.value
              ->> 'preserve_live_gap_seconds'
          )::boolean,
          false
        ),
      'preserve_live_group_assignment',
        coalesce(
          (
            row_data.value
              ->> 'preserve_live_group_assignment'
          )::boolean,
          false
        ),
      'live_gap_source',
        'public.race_stage_rider_states.gap_seconds',
      'live_stage_status_source',
        'public.race_stage_rider_states.stage_status',
      'replay_group_source',
        'downstream replay/group derivation',
      'official_state_application',
        'pending_existing_race_engine_apply_stage_command_deltas_to_official_state_v1',
      'prepared_by',
        'race_engine_enqueue_rio_bk_issue01_phase1_deltas_v1'
    ),

    clock_timestamp(),
    null,
    clock_timestamp()

  from jsonb_array_elements(v_rows)
    row_data(value)

  on conflict (
    stage_id,
    club_id,
    rider_id,
    source_version
  )
  do update
  set
    event_count =
      excluded.event_count,
    first_event_km =
      excluded.first_event_km,
    last_event_km =
      excluded.last_event_km,
    command_codes =
      excluded.command_codes,
    outcome_types =
      excluded.outcome_types,
    tactical_success_count =
      excluded.tactical_success_count,
    stamina_delta_total =
      excluded.stamina_delta_total,
    fatigue_delta_total =
      excluded.fatigue_delta_total,
    attack_attempts_added =
      excluded.attack_attempts_added,
    breakaway_km_added =
      excluded.breakaway_km_added,
    support_work_added =
      excluded.support_work_added,
    protection_received_added =
      excluded.protection_received_added,
    incident_count =
      excluded.incident_count,
    mechanical_count =
      excluded.mechanical_count,
    incident_types =
      excluded.incident_types,
    mechanical_types =
      excluded.mechanical_types,
    application_status =
      'prepared',
    official_delta_json =
      excluded.official_delta_json,
    metadata =
      excluded.metadata,
    prepared_at =
      excluded.prepared_at,
    consumed_at =
      null,
    updated_at =
      excluded.updated_at
  where
    race_engine_stage_command_outcome_delta_applications.application_status =
      'prepared';

  get diagnostics v_upserted_rows = row_count;

  if v_upserted_rows <> v_row_count then
    raise exception
      'Rio BK Phase 1 queue adapter apply blocked: expected % prepared queue upserts, received %.',
      v_row_count,
      v_upserted_rows;
  end if;

  return jsonb_build_object(
    'status',
      'prepared_queue_rows',
    'adapter_version',
      c_source_version,
    'race_stage_plan_id',
      c_plan_id,
    'simulation_run_id',
      p_simulation_run_id,
    'race_id',
      c_race_id,
    'stage_id',
      c_stage_id,
    'club_id',
      c_club_id,
    'phase_number',
      c_phase_number,
    'runtime_mapping_hash',
      c_accepted_runtime_mapping_hash,
    'application_rows_hash',
      v_application_rows_hash,
    'prepared_queue_rows',
      v_upserted_rows,
    'official_state_writer_called',
      false,
    'fatigue_writer_called',
      false,
    'replay_writer_called',
      false,
    'direct_gap_write',
      false,
    'direct_group_reassignment',
      false,
    'next_step',
      'Rollback-test the queue apply branch, then separately call the existing official-state writer under rollback. Do not call the production runner.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_enqueue_rio_bk_issue01_stage1_deltas_v1(p_race_stage_plan_id uuid, p_simulation_run_id uuid, p_application_rows_json jsonb, p_context_json jsonb DEFAULT NULL::jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_plan_id constant uuid :=
    'b79f44d3-f309-441c-b39d-122725ac1496'::uuid;
  c_race_id constant uuid :=
    '65739034-f9e5-4b5c-8f21-4ea27451e0d4'::uuid;
  c_stage_id constant uuid :=
    '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid;
  c_club_id constant uuid :=
    '49caba57-9a5e-4820-b4bf-06cfc684e8b2'::uuid;
  c_source_version constant text :=
    'issue01_rio_bk_stage1_multiphase_queue_v2';

  v_rows jsonb :=
    coalesce(p_application_rows_json, '[]'::jsonb);
  v_context jsonb :=
    coalesce(p_context_json, '{}'::jsonb);

  v_canary_mode boolean := lower(
    coalesce(
      current_setting(
        'app.issue01_rio_bk_stage1_queue_canary_mode',
        true
      ),
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_explicit_apply_permission boolean := lower(
    coalesce(
      v_context
        ->> 'allow_rio_bk_stage1_queue_apply',
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_input_event_count integer := 0;
  v_unique_phase_rider_count integer := 0;
  v_unique_transition_key_count integer := 0;
  v_unique_rider_count integer := 0;
  v_expected_queue_row_count integer := 0;

  v_invalid_row_count integer := 0;
  v_distance_mismatch_count integer := 0;
  v_population_mismatch_count integer := 0;
  v_mapping_hash_mismatch_count integer := 0;
  v_transition_key_mismatch_count integer := 0;
  v_preserve_contract_failure_count integer := 0;

  v_phase1_count integer := 0;
  v_phase2_count integer := 0;
  v_phase3_count integer := 0;
  v_phase4_count integer := 0;
  v_attack_count integer := 0;
  v_chase_count integer := 0;
  v_bridge_count integer := 0;

  v_consumed_conflict_count integer := 0;
  v_live_state_count integer := 0;
  v_finished_state_count integer := 0;
  v_upserted_rows integer := 0;

  v_application_rows_hash text;
  v_preview_rows jsonb := '[]'::jsonb;
begin
  if p_race_stage_plan_id is distinct from c_plan_id then
    raise exception
      'Stage 1 adapter accepts only race_stage_plan_id %.',
      c_plan_id;
  end if;

  if p_simulation_run_id is null then
    raise exception
      'Stage 1 adapter requires simulation_run_id.';
  end if;

  if jsonb_typeof(v_rows) <> 'array' then
    raise exception
      'Stage 1 adapter requires application_rows_json to be a JSON array.';
  end if;

  /*
   * Validate the five accepted phase/action events exactly.
   */
  with
  expected(
    phase_number,
    rider_id,
    action_kind,
    phase_mapping_hash,
    transition_idempotency_key
  ) as (
    values
      (
        1,
        '1a29ac57-1fb8-4f7c-a24e-3f9e76b3ad51'::uuid,
        'attack'::text,
        '4df122c223d855c47969a5e4fbb78e01'::text,
        '42640f3916f1693e6e50fffa1e3425f8'::text
      ),
      (
        1,
        '35f9dedb-9eb6-4d7a-ab28-7289050843ca'::uuid,
        'chase'::text,
        '4df122c223d855c47969a5e4fbb78e01'::text,
        'e9261db85baaf191d9e640b0406c7146'::text
      ),
      (
        1,
        'acbbc56e-ea56-4d45-9e0e-5025ca73c2e5'::uuid,
        'chase'::text,
        '4df122c223d855c47969a5e4fbb78e01'::text,
        'feb50622b23426a39655bbc3298cd914'::text
      ),
      (
        2,
        'acbbc56e-ea56-4d45-9e0e-5025ca73c2e5'::uuid,
        'attack'::text,
        'cc641a7601ce3fb4d66487a5110954fe'::text,
        'b72b4141c47b031603a1bf0cb0ea7ab3'::text
      ),
      (
        4,
        '8218bf2c-b2c9-4873-8d6e-006f0a71621d'::uuid,
        'attack'::text,
        'efb5653df96426a3b2ea43a414745f1c'::text,
        'bd15a813d5fa16d43c64e1106c2f814d'::text
      )
  ),
  input_rows as (
    select
      row_data.value as row_json,
      nullif(
        row_data.value ->> 'phase_number',
        ''
      )::integer as phase_number,
      nullif(
        row_data.value ->> 'rider_id',
        ''
      )::uuid as rider_id,
      lower(
        coalesce(
          row_data.value ->> 'action_kind',
          ''
        )
      ) as action_kind,
      nullif(
        row_data.value ->> 'phase_mapping_hash',
        ''
      ) as phase_mapping_hash,
      nullif(
        row_data.value
          ->> 'transition_idempotency_key',
        ''
      ) as transition_idempotency_key
    from jsonb_array_elements(v_rows)
      row_data(value)
  )
  select
    count(*)::integer,
    count(
      distinct concat(
        input_rows.phase_number::text,
        ':',
        input_rows.rider_id::text
      )
    )::integer,
    count(
      distinct input_rows.transition_idempotency_key
    )::integer,
    count(
      distinct input_rows.rider_id
    )::integer,

    count(*) filter (
      where input_rows.rider_id is null
         or input_rows.phase_number is null
         or input_rows.action_kind not in (
              'attack',
              'chase'
            )
         or input_rows.phase_mapping_hash is null
         or input_rows.transition_idempotency_key is null
         or nullif(
              input_rows.row_json
                ->> 'source_action_hash',
              ''
            ) is null
         or coalesce(
              nullif(
                input_rows.row_json
                  ->> 'avg_speed_kmh',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              nullif(
                input_rows.row_json
                  ->> 'elapsed_seconds',
                ''
              )::numeric,
              -1
            ) <= 0
         or coalesce(
              nullif(
                input_rows.row_json
                  ->> 'distance_delta_km',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              nullif(
                input_rows.row_json
                  ->> 'stamina_delta_points',
                ''
              )::numeric,
              1
            ) > 0
         or coalesce(
              nullif(
                input_rows.row_json
                  ->> 'post_stage_fatigue_delta',
                ''
              )::numeric,
              -1
            ) < 0
         or coalesce(
              input_rows.row_json
                ->> 'blocked_reason',
              ''
            ) <> ''
         or coalesce(
              (
                input_rows.row_json
                  ->> 'direct_gap_write'
              )::boolean,
              true
            )
         or coalesce(
              (
                input_rows.row_json
                  ->> 'direct_group_reassignment'
              )::boolean,
              true
            )
    )::integer,

    count(*) filter (
      where abs(
        coalesce(
          nullif(
            input_rows.row_json
              ->> 'distance_delta_km',
            ''
          )::numeric,
          -999999
        )
        -
        (
          coalesce(
            nullif(
              input_rows.row_json
                ->> 'avg_speed_kmh',
              ''
            )::numeric,
            0
          )
          *
          coalesce(
            nullif(
              input_rows.row_json
                ->> 'elapsed_seconds',
              ''
            )::numeric,
            0
          )
          / 3600.0
        )
      ) > 0.000001
    )::integer,

    count(*) filter (
      where expected.rider_id is null
    )::integer,

    count(*) filter (
      where expected.rider_id is not null
        and input_rows.phase_mapping_hash
              is distinct from
            expected.phase_mapping_hash
    )::integer,

    count(*) filter (
      where expected.rider_id is not null
        and input_rows.transition_idempotency_key
              is distinct from
            expected.transition_idempotency_key
    )::integer,

    count(*) filter (
      where (
        input_rows.action_kind = 'attack'
        and (
          coalesce(
            nullif(
              input_rows.row_json
                ->> 'attack_initial_separation_seconds',
              ''
            )::numeric,
            -1
          ) < 0
          or coalesce(
            nullif(
              input_rows.row_json
                ->> 'attack_initial_separation_distance_km',
              ''
            )::numeric,
            -1
          ) < 0
        )
      )
      or (
        input_rows.action_kind = 'chase'
        and (
          coalesce(
            (
              input_rows.row_json
                ->> 'preserve_live_gap_seconds'
            )::boolean,
            false
          ) is false
          or coalesce(
            (
              input_rows.row_json
                ->> 'preserve_live_group_assignment'
            )::boolean,
            false
          ) is false
        )
      )
    )::integer,

    count(*) filter (
      where input_rows.phase_number = 1
    )::integer,
    count(*) filter (
      where input_rows.phase_number = 2
    )::integer,
    count(*) filter (
      where input_rows.phase_number = 3
    )::integer,
    count(*) filter (
      where input_rows.phase_number = 4
    )::integer,
    count(*) filter (
      where input_rows.action_kind = 'attack'
    )::integer,
    count(*) filter (
      where input_rows.action_kind = 'chase'
    )::integer,
    count(*) filter (
      where input_rows.action_kind = 'bridge'
    )::integer

  into
    v_input_event_count,
    v_unique_phase_rider_count,
    v_unique_transition_key_count,
    v_unique_rider_count,
    v_invalid_row_count,
    v_distance_mismatch_count,
    v_population_mismatch_count,
    v_mapping_hash_mismatch_count,
    v_transition_key_mismatch_count,
    v_preserve_contract_failure_count,
    v_phase1_count,
    v_phase2_count,
    v_phase3_count,
    v_phase4_count,
    v_attack_count,
    v_chase_count,
    v_bridge_count

  from input_rows
  left join expected
    on expected.phase_number =
       input_rows.phase_number
   and expected.rider_id =
       input_rows.rider_id
   and expected.action_kind =
       input_rows.action_kind;

  v_expected_queue_row_count := v_unique_rider_count;

  if v_input_event_count <> 5
     or v_phase1_count <> 3
     or v_phase2_count <> 1
     or v_phase3_count <> 0
     or v_phase4_count <> 1
     or v_attack_count <> 3
     or v_chase_count <> 2
     or v_bridge_count <> 0
  then
    raise exception
      'Stage 1 adapter population failed: events %, phase1 %, phase2 %, phase3 %, phase4 %, attack %, chase %, bridge %.',
      v_input_event_count,
      v_phase1_count,
      v_phase2_count,
      v_phase3_count,
      v_phase4_count,
      v_attack_count,
      v_chase_count,
      v_bridge_count;
  end if;

  if v_unique_phase_rider_count <> 5
     or v_unique_transition_key_count <> 5
     or v_unique_rider_count <> 4
     or v_invalid_row_count <> 0
     or v_distance_mismatch_count <> 0
     or v_population_mismatch_count <> 0
     or v_mapping_hash_mismatch_count <> 0
     or v_transition_key_mismatch_count <> 0
     or v_preserve_contract_failure_count <> 0
  then
    raise exception
      'Stage 1 adapter row contract failed: unique phase/rider %, unique keys %, unique riders %, invalid %, distance mismatch %, population mismatch %, mapping hash mismatch %, transition key mismatch %, preserve failures %.',
      v_unique_phase_rider_count,
      v_unique_transition_key_count,
      v_unique_rider_count,
      v_invalid_row_count,
      v_distance_mismatch_count,
      v_population_mismatch_count,
      v_mapping_hash_mismatch_count,
      v_transition_key_mismatch_count,
      v_preserve_contract_failure_count;
  end if;

  if not exists (
    select 1
    from public.race_stage_plans plan
    join public.race_preparations preparation
      on preparation.id = plan.race_preparation_id
    where plan.id = c_plan_id
      and plan.stage_id = c_stage_id
      and plan.stage_number = 1
      and preparation.race_id = c_race_id
      and preparation.club_id = c_club_id
  ) then
    raise exception
      'Stage 1 adapter blocked: exact accepted Stage Plan scope no longer exists.';
  end if;

  select count(*)::integer
  into v_consumed_conflict_count
  from public.race_engine_stage_command_outcome_delta_applications queue_row
  where queue_row.stage_id = c_stage_id
    and queue_row.club_id = c_club_id
    and queue_row.source_version = c_source_version
    and queue_row.application_status =
      'consumed_by_finalizer';

  if v_consumed_conflict_count > 0 then
    raise exception
      'Stage 1 adapter blocked: % aggregated rider row(s) were already consumed.',
      v_consumed_conflict_count;
  end if;

  v_application_rows_hash := md5(v_rows::text);

  /*
   * Preview the four rider-aggregated rows. All original phase/action evidence
   * remains in the ordered events array.
   */
  with input_rows as (
    select
      row_data.value as row_json,
      nullif(
        row_data.value ->> 'phase_number',
        ''
      )::integer as phase_number,
      nullif(
        row_data.value ->> 'rider_id',
        ''
      )::uuid as rider_id,
      lower(
        row_data.value ->> 'action_kind'
      ) as action_kind,
      nullif(
        row_data.value ->> 'launch_km',
        ''
      )::numeric as launch_km,
      nullif(
        row_data.value ->> 'distance_delta_km',
        ''
      )::numeric as distance_delta_km,
      greatest(
        0,
        -nullif(
          row_data.value
            ->> 'stamina_delta_points',
          ''
        )::numeric
      ) as stamina_delta_total,
      greatest(
        0,
        nullif(
          row_data.value
            ->> 'post_stage_fatigue_delta',
          ''
        )::numeric
      ) as fatigue_delta_total
    from jsonb_array_elements(v_rows)
      row_data(value)
  ),
  grouped as (
    select
      input_rows.rider_id,
      count(*)::integer as event_count,
      min(input_rows.launch_km) as first_event_km,
      max(
        input_rows.launch_km
        + input_rows.distance_delta_km
      ) as last_event_km,
      sum(input_rows.stamina_delta_total)
        as stamina_delta_total,
      sum(input_rows.fatigue_delta_total)
        as fatigue_delta_total,
      count(*) filter (
        where input_rows.action_kind = 'attack'
      )::integer as attack_attempts_added,
      sum(
        case
          when input_rows.action_kind = 'attack'
          then input_rows.distance_delta_km
          else 0
        end
      ) as breakaway_km_added,
      jsonb_agg(
        input_rows.row_json
        order by
          input_rows.phase_number,
          input_rows.action_kind,
          input_rows.rider_id
      ) as events
    from input_rows
    group by input_rows.rider_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'stage_id', c_stage_id,
        'club_id', c_club_id,
        'rider_id', grouped.rider_id,
        'source_version', c_source_version,
        'event_count', grouped.event_count,
        'first_event_km', grouped.first_event_km,
        'last_event_km', grouped.last_event_km,
        'stamina_delta_total',
          grouped.stamina_delta_total,
        'fatigue_delta_total',
          grouped.fatigue_delta_total,
        'attack_attempts_added',
          grouped.attack_attempts_added,
        'breakaway_km_added',
          grouped.breakaway_km_added,
        'queue_apply_requested', p_apply,
        'events', grouped.events
      )
      order by grouped.rider_id
    ),
    '[]'::jsonb
  )
  into v_preview_rows
  from grouped;

  if jsonb_array_length(v_preview_rows)
       <> v_expected_queue_row_count
  then
    raise exception
      'Stage 1 adapter aggregation failed: expected % rider rows, preview produced %.',
      v_expected_queue_row_count,
      jsonb_array_length(v_preview_rows);
  end if;

  if not p_apply then
    return jsonb_build_object(
      'status',
        'validated_disabled',
      'adapter_version',
        'issue01_rio_bk_stage1_multiphase_queue_v2',
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'race_id',
        c_race_id,
      'stage_id',
        c_stage_id,
      'club_id',
        c_club_id,
      'source_version',
        c_source_version,
      'application_rows_hash',
        v_application_rows_hash,
      'input_event_count',
        v_input_event_count,
      'prepared_queue_row_count',
        v_expected_queue_row_count,
      'unique_rider_count',
        v_unique_rider_count,
      'phase_event_counts',
        jsonb_build_object(
          'phase1', v_phase1_count,
          'phase2', v_phase2_count,
          'phase3', v_phase3_count,
          'phase4', v_phase4_count
        ),
      'action_event_counts',
        jsonb_build_object(
          'attack', v_attack_count,
          'chase', v_chase_count,
          'bridge', v_bridge_count
        ),
      'duplicate_rider_event_count',
        v_input_event_count
        - v_unique_rider_count,
      'canary_mode',
        v_canary_mode,
      'explicit_apply_permission',
        v_explicit_apply_permission,
      'runtime_apply_enabled',
        false,
      'queue_writes',
        0,
      'official_state_writer_called',
        false,
      'replay_writer_called',
        false,
      'direct_gap_write',
        false,
      'direct_group_reassignment',
        false,
      'preview_rows',
        v_preview_rows
    );
  end if;

  if not v_canary_mode
     or not v_explicit_apply_permission
  then
    return jsonb_build_object(
      'status',
        'blocked',
      'reason',
        'rio_bk_stage1_queue_apply_requires_canary_mode_and_explicit_permission',
      'adapter_version',
        'issue01_rio_bk_stage1_multiphase_queue_v2',
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'canary_mode',
        v_canary_mode,
      'explicit_apply_permission',
        v_explicit_apply_permission,
      'queue_writes',
        0,
      'official_state_writer_called',
        false,
      'replay_writer_called',
        false
    );
  end if;

  if not exists (
    select 1
    from public.race_stage_simulation_runs run_row
    where run_row.id = p_simulation_run_id
      and run_row.race_id = c_race_id
      and run_row.stage_id = c_stage_id
  ) then
    raise exception
      'Stage 1 adapter apply blocked: simulation run does not match exact Rio Stage 1 scope.';
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where lower(
        coalesce(state_row.stage_status, '')
      ) in (
        'finished',
        'dnf',
        'dns',
        'withdrawn',
        'outside_time_limit'
      )
    )::integer
  into
    v_live_state_count,
    v_finished_state_count
  from public.race_stage_rider_states state_row
  where state_row.simulation_run_id =
      p_simulation_run_id
    and state_row.stage_id = c_stage_id
    and state_row.team_id = c_club_id
    and state_row.rider_id in (
      select distinct
        nullif(
          row_data.value ->> 'rider_id',
          ''
        )::uuid
      from jsonb_array_elements(v_rows)
        row_data(value)
    );

  if v_live_state_count <> v_unique_rider_count
     or v_finished_state_count <> 0
  then
    raise exception
      'Stage 1 adapter apply blocked: live rider-state boundary mismatch (unique riders %, live states %, already-finished %).',
      v_unique_rider_count,
      v_live_state_count,
      v_finished_state_count;
  end if;

  /*
   * One established queue row per rider.
   */
  with input_rows as (
    select
      row_data.value as row_json,
      nullif(
        row_data.value ->> 'phase_number',
        ''
      )::integer as phase_number,
      nullif(
        row_data.value ->> 'rider_id',
        ''
      )::uuid as rider_id,
      lower(
        row_data.value ->> 'action_kind'
      ) as action_kind,
      nullif(
        row_data.value ->> 'launch_km',
        ''
      )::numeric as launch_km,
      nullif(
        row_data.value ->> 'distance_delta_km',
        ''
      )::numeric as distance_delta_km,
      greatest(
        0,
        -nullif(
          row_data.value
            ->> 'stamina_delta_points',
          ''
        )::numeric
      ) as stamina_delta_total,
      greatest(
        0,
        nullif(
          row_data.value
            ->> 'post_stage_fatigue_delta',
          ''
        )::numeric
      ) as fatigue_delta_total
    from jsonb_array_elements(v_rows)
      row_data(value)
  ),
  grouped as (
    select
      input_rows.rider_id,
      count(*)::integer as event_count,
      min(input_rows.launch_km) as first_event_km,
      max(
        input_rows.launch_km
        + input_rows.distance_delta_km
      ) as last_event_km,
      jsonb_agg(
        to_jsonb(input_rows.action_kind)
        order by
          input_rows.phase_number,
          input_rows.action_kind
      ) as command_codes,
      jsonb_agg(
        to_jsonb(input_rows.action_kind)
        order by
          input_rows.phase_number,
          input_rows.action_kind
      ) as outcome_types,
      count(*)::integer as tactical_success_count,
      sum(input_rows.stamina_delta_total)
        as stamina_delta_total,
      sum(input_rows.fatigue_delta_total)
        as fatigue_delta_total,
      count(*) filter (
        where input_rows.action_kind = 'attack'
      )::integer as attack_attempts_added,
      sum(
        case
          when input_rows.action_kind = 'attack'
          then input_rows.distance_delta_km
          else 0
        end
      ) as breakaway_km_added,
      jsonb_agg(
        input_rows.row_json
        order by
          input_rows.phase_number,
          input_rows.action_kind,
          input_rows.rider_id
      ) as events,
      jsonb_agg(
        to_jsonb(input_rows.phase_number)
        order by
          input_rows.phase_number,
          input_rows.action_kind
      ) as phase_numbers,
      jsonb_agg(
        to_jsonb(
          input_rows.row_json
            ->> 'source_action_hash'
        )
        order by
          input_rows.phase_number,
          input_rows.action_kind
      ) as source_action_hashes,
      jsonb_agg(
        to_jsonb(
          input_rows.row_json
            ->> 'transition_idempotency_key'
        )
        order by
          input_rows.phase_number,
          input_rows.action_kind
      ) as transition_idempotency_keys
    from input_rows
    group by input_rows.rider_id
  )
  insert into public.race_engine_stage_command_outcome_delta_applications (
    stage_id,
    club_id,
    rider_id,
    rider_name,
    event_count,
    first_event_km,
    last_event_km,
    command_codes,
    outcome_types,
    tactical_success_count,
    stamina_delta_total,
    fatigue_delta_total,
    attack_attempts_added,
    breakaway_km_added,
    support_work_added,
    protection_received_added,
    incident_count,
    mechanical_count,
    incident_types,
    mechanical_types,
    application_status,
    source_version,
    official_delta_json,
    metadata,
    prepared_at,
    consumed_at,
    updated_at
  )
  select
    c_stage_id,
    c_club_id,
    grouped.rider_id,
    null,
    grouped.event_count,
    grouped.first_event_km,
    grouped.last_event_km,
    grouped.command_codes,
    grouped.outcome_types,
    grouped.tactical_success_count,
    grouped.stamina_delta_total,
    grouped.fatigue_delta_total,
    grouped.attack_attempts_added,
    grouped.breakaway_km_added,
    0,
    0,
    0,
    0,
    '[]'::jsonb,
    '[]'::jsonb,
    'prepared',
    c_source_version,

    jsonb_build_object(
      'adapter_version',
        'issue01_rio_bk_stage1_multiphase_queue_v2',
      'event_count',
        grouped.event_count,
      'stamina_delta_total',
        grouped.stamina_delta_total,
      'fatigue_delta_total',
        grouped.fatigue_delta_total,
      'attack_attempts_added',
        grouped.attack_attempts_added,
      'breakaway_km_added',
        grouped.breakaway_km_added,
      'events',
        grouped.events,
      'phase_numbers',
        grouped.phase_numbers,
      'source_action_hashes',
        grouped.source_action_hashes,
      'transition_idempotency_keys',
        grouped.transition_idempotency_keys
    ),

    jsonb_build_object(
      'source',
        'issue01_rio_bk_stage1_multiphase_queue_v2',
      'race_id',
        c_race_id,
      'stage_id',
        c_stage_id,
      'race_stage_plan_id',
        c_plan_id,
      'simulation_run_id',
        p_simulation_run_id,
      'application_rows_hash',
        v_application_rows_hash,
      'input_event_count',
        v_input_event_count,
      'aggregated_rider_event_count',
        grouped.event_count,
      'phase_numbers',
        grouped.phase_numbers,
      'source_action_hashes',
        grouped.source_action_hashes,
      'transition_idempotency_keys',
        grouped.transition_idempotency_keys,
      'events',
        grouped.events,
      'direct_gap_write',
        false,
      'direct_group_reassignment',
        false,
      'phase3_no_action_contract',
        'no_issue01e_action_riders_zero_rows',
      'live_gap_source',
        'public.race_stage_rider_states.gap_seconds',
      'live_stage_status_source',
        'public.race_stage_rider_states.stage_status',
      'replay_group_source',
        'downstream replay/group derivation',
      'official_state_application',
        'pending_existing_official_state_writer',
      'prepared_by',
        'race_engine_enqueue_rio_bk_issue01_stage1_deltas_v1'
    ),

    clock_timestamp(),
    null,
    clock_timestamp()

  from grouped

  on conflict (
    stage_id,
    club_id,
    rider_id,
    source_version
  )
  do update
  set
    event_count =
      excluded.event_count,
    first_event_km =
      excluded.first_event_km,
    last_event_km =
      excluded.last_event_km,
    command_codes =
      excluded.command_codes,
    outcome_types =
      excluded.outcome_types,
    tactical_success_count =
      excluded.tactical_success_count,
    stamina_delta_total =
      excluded.stamina_delta_total,
    fatigue_delta_total =
      excluded.fatigue_delta_total,
    attack_attempts_added =
      excluded.attack_attempts_added,
    breakaway_km_added =
      excluded.breakaway_km_added,
    support_work_added =
      excluded.support_work_added,
    protection_received_added =
      excluded.protection_received_added,
    incident_count =
      excluded.incident_count,
    mechanical_count =
      excluded.mechanical_count,
    incident_types =
      excluded.incident_types,
    mechanical_types =
      excluded.mechanical_types,
    application_status =
      'prepared',
    official_delta_json =
      excluded.official_delta_json,
    metadata =
      excluded.metadata,
    prepared_at =
      excluded.prepared_at,
    consumed_at =
      null,
    updated_at =
      excluded.updated_at
  where
    race_engine_stage_command_outcome_delta_applications.application_status =
      'prepared';

  get diagnostics v_upserted_rows = row_count;

  if v_upserted_rows <> v_expected_queue_row_count then
    raise exception
      'Stage 1 adapter apply blocked: expected % aggregated rider queue upserts, received %.',
      v_expected_queue_row_count,
      v_upserted_rows;
  end if;

  return jsonb_build_object(
    'status',
      'prepared_queue_rows',
    'adapter_version',
      'issue01_rio_bk_stage1_multiphase_queue_v2',
    'race_stage_plan_id',
      c_plan_id,
    'simulation_run_id',
      p_simulation_run_id,
    'race_id',
      c_race_id,
    'stage_id',
      c_stage_id,
    'club_id',
      c_club_id,
    'source_version',
      c_source_version,
    'application_rows_hash',
      v_application_rows_hash,
    'input_event_count',
      v_input_event_count,
    'prepared_queue_rows',
      v_upserted_rows,
    'unique_rider_count',
      v_unique_rider_count,
    'phase_event_counts',
      jsonb_build_object(
        'phase1', v_phase1_count,
        'phase2', v_phase2_count,
        'phase3', v_phase3_count,
        'phase4', v_phase4_count
      ),
    'action_event_counts',
      jsonb_build_object(
        'attack', v_attack_count,
        'chase', v_chase_count,
        'bridge', v_bridge_count
      ),
    'duplicate_rider_event_count',
      v_input_event_count
      - v_unique_rider_count,
    'official_state_writer_called',
      false,
    'fatigue_writer_called',
      false,
    'replay_writer_called',
      false,
    'direct_gap_write',
      false,
    'direct_group_reassignment',
      false,
    'next_step',
      'Run the corrected V23B rollback acceptance: four prepared rider rows representing five events, one repeated-rider aggregate, writer dry run, writer apply, four consumed rows and exact rollback.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_apply_rio_stage1_issue01_controlled_execution_v1(p_simulation_run_id uuid, p_rider_state_rows_json jsonb, p_issue01_event_rows_json jsonb, p_context_json jsonb DEFAULT NULL::jsonb, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_race_id constant uuid :=
    '65739034-f9e5-4b5c-8f21-4ea27451e0d4'::uuid;
  c_stage_id constant uuid :=
    '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid;

  v_states jsonb :=
    coalesce(p_rider_state_rows_json, '[]'::jsonb);
  v_events jsonb :=
    coalesce(p_issue01_event_rows_json, '[]'::jsonb);
  v_context jsonb :=
    coalesce(p_context_json, '{}'::jsonb);

  v_canary_mode boolean := lower(
    coalesce(
      current_setting(
        'app.issue01_rio_stage1_full_execution_canary_mode',
        true
      ),
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_explicit_permission boolean := lower(
    coalesce(
      v_context
        ->> 'allow_rio_stage1_controlled_execution_apply',
      'false'
    )
  ) in ('1', 'true', 'on', 'yes');

  v_state_count integer;
  v_state_team_count integer;
  v_state_unique_rider_count integer;
  v_state_invalid_count integer;
  v_state_population_mismatch_count integer;
  v_event_count integer;
  v_event_unique_key_count integer;
  v_event_invalid_count integer;
  v_event_population_mismatch_count integer;
  v_phase1_count integer;
  v_phase2_count integer;
  v_phase3_count integer;
  v_phase4_count integer;
  v_attack_count integer;
  v_chase_count integer;
  v_bridge_count integer;
  v_bridge_exact_count integer;
  v_distance_km numeric;
  v_winner_seconds integer;

  v_run_inserted integer := 0;
  v_states_inserted integer := 0;
  v_overlay_rows_inserted integer := 0;
  v_run_completion_updated integer := 0;

  v_group_result jsonb := '{}'::jsonb;
  v_replay_result jsonb := '{}'::jsonb;
  v_result_result jsonb := '{}'::jsonb;
  v_tail_result jsonb := '{}'::jsonb;

  v_base_replay_count integer := 0;
  v_overlay_replay_count integer := 0;
  v_result_count integer := 0;
begin
  if p_simulation_run_id is null then
    raise exception
      'Controlled execution requires simulation_run_id.';
  end if;

  if jsonb_typeof(v_states) <> 'array'
     or jsonb_typeof(v_events) <> 'array'
  then
    raise exception
      'Controlled execution requires rider-state and event JSON arrays.';
  end if;

  with state_rows as (
    select
      row_data.value as row_json,
      nullif(row_data.value ->> 'rider_id', '')::uuid as rider_id,
      nullif(row_data.value ->> 'team_id', '')::uuid as team_id,
      nullif(row_data.value ->> 'finish_position', '')::integer as finish_position,
      nullif(row_data.value ->> 'finish_time_seconds', '')::integer as finish_time_seconds,
      nullif(row_data.value ->> 'gap_seconds', '')::integer as gap_seconds,
      nullif(row_data.value ->> 'start_stamina', '')::numeric as start_stamina,
      nullif(row_data.value ->> 'finish_stamina', '')::numeric as finish_stamina,
      nullif(row_data.value ->> 'stamina_spent', '')::numeric as stamina_spent,
      coalesce(row_data.value ->> 'stage_status', '') as stage_status
    from jsonb_array_elements(v_states) row_data(value)
  ),
  canonical as (
    select input_row.rider_id, input_row.team_id
    from public.race_engine_get_stage_rider_inputs_v1(c_stage_id) input_row
  ),
  population_mismatch as (
    select state_rows.rider_id, state_rows.team_id
    from state_rows
    left join canonical
      on canonical.rider_id = state_rows.rider_id
     and canonical.team_id = state_rows.team_id
    where canonical.rider_id is null

    union all

    select canonical.rider_id, canonical.team_id
    from canonical
    left join state_rows
      on state_rows.rider_id = canonical.rider_id
     and state_rows.team_id = canonical.team_id
    where state_rows.rider_id is null
  )
  select
    (select count(*)::integer from state_rows),
    (select count(distinct team_id)::integer from state_rows),
    (select count(distinct rider_id)::integer from state_rows),
    (
      select count(*)::integer
      from state_rows
      where rider_id is null
         or team_id is null
         or finish_position is null
         or finish_time_seconds is null
         or gap_seconds is null
         or start_stamina is null
         or finish_stamina is null
         or stamina_spent is null
         or stage_status <> 'finished'
         or finish_position < 1
         or finish_position > 96
         or finish_time_seconds <= 0
         or gap_seconds < 0
         or start_stamina < 0
         or start_stamina > 100
         or finish_stamina < 0
         or finish_stamina > start_stamina
         or stamina_spent < 0
         or abs(
              start_stamina
              - finish_stamina
              - stamina_spent
            ) > 0.001
    ),
    (select count(*)::integer from population_mismatch)
  into
    v_state_count,
    v_state_team_count,
    v_state_unique_rider_count,
    v_state_invalid_count,
    v_state_population_mismatch_count;

  if v_state_count <> 96
     or v_state_team_count <> 16
     or v_state_unique_rider_count <> 96
     or v_state_invalid_count <> 0
     or v_state_population_mismatch_count <> 0
  then
    raise exception
      'Controlled execution state contract failed: rows %, teams %, unique riders %, invalid %, population mismatch %.',
      v_state_count,
      v_state_team_count,
      v_state_unique_rider_count,
      v_state_invalid_count,
      v_state_population_mismatch_count;
  end if;

  if (
    select count(distinct nullif(row_data.value ->> 'finish_position', '')::integer)
    from jsonb_array_elements(v_states) row_data(value)
  ) <> 96
  or (
    select min(nullif(row_data.value ->> 'finish_position', '')::integer)
    from jsonb_array_elements(v_states) row_data(value)
  ) <> 1
  or (
    select max(nullif(row_data.value ->> 'finish_position', '')::integer)
    from jsonb_array_elements(v_states) row_data(value)
  ) <> 96
  then
    raise exception
      'Controlled execution finish-position contract failed.';
  end if;

  select min(
    nullif(row_data.value ->> 'finish_time_seconds', '')::integer
  )
  into v_winner_seconds
  from jsonb_array_elements(v_states) row_data(value);

  if exists (
    select 1
    from jsonb_array_elements(v_states) row_data(value)
    where nullif(row_data.value ->> 'finish_time_seconds', '')::integer
          <> v_winner_seconds
             + nullif(row_data.value ->> 'gap_seconds', '')::integer
  ) then
    raise exception
      'Controlled execution finish-time/gap coherence failed.';
  end if;

  with event_rows as (
    select
      row_data.value as row_json,
      nullif(row_data.value ->> 'phase_number', '')::integer as phase_number,
      lower(coalesce(row_data.value ->> 'action_kind', '')) as action_kind,
      nullif(row_data.value ->> 'rider_id', '')::uuid as rider_id,
      nullif(row_data.value ->> 'team_id', '')::uuid as team_id,
      nullif(row_data.value ->> 'launch_km', '')::numeric as launch_km,
      nullif(row_data.value ->> 'avg_speed_kmh', '')::numeric as avg_speed_kmh,
      nullif(row_data.value ->> 'elapsed_seconds', '')::numeric as elapsed_seconds,
      nullif(row_data.value ->> 'movement_distance_km', '')::numeric as movement_distance_km,
      nullif(row_data.value ->> 'transition_idempotency_key', '') as transition_key
    from jsonb_array_elements(v_events) row_data(value)
  ),
  canonical as (
    select input_row.rider_id, input_row.team_id
    from public.race_engine_get_stage_rider_inputs_v1(c_stage_id) input_row
  )
  select
    count(*)::integer,
    count(distinct event_rows.transition_key)::integer,
    count(*) filter (
      where event_rows.phase_number is null
         or event_rows.phase_number not in (1,2,3,4)
         or event_rows.action_kind not in ('attack','chase','bridge')
         or event_rows.rider_id is null
         or event_rows.team_id is null
         or event_rows.launch_km is null
         or event_rows.launch_km < 0
         or event_rows.avg_speed_kmh is null
         or event_rows.avg_speed_kmh <= 0
         or event_rows.elapsed_seconds is null
         or event_rows.elapsed_seconds <= 0
         or event_rows.movement_distance_km is null
         or event_rows.movement_distance_km <= 0
         or event_rows.transition_key is null
         or abs(
              event_rows.movement_distance_km
              - round(
                  (
                    event_rows.avg_speed_kmh
                    * event_rows.elapsed_seconds
                    / 3600.0
                  )::numeric,
                  6
                )
            ) > 0.000001
    )::integer,
    count(*) filter (
      where canonical.rider_id is null
    )::integer,
    count(*) filter (
      where event_rows.phase_number = 1
    )::integer,
    count(*) filter (
      where event_rows.phase_number = 2
    )::integer,
    count(*) filter (
      where event_rows.phase_number = 3
    )::integer,
    count(*) filter (
      where event_rows.phase_number = 4
    )::integer,
    count(*) filter (
      where event_rows.action_kind = 'attack'
    )::integer,
    count(*) filter (
      where event_rows.action_kind = 'chase'
    )::integer,
    count(*) filter (
      where event_rows.action_kind = 'bridge'
    )::integer
  into
    v_event_count,
    v_event_unique_key_count,
    v_event_invalid_count,
    v_event_population_mismatch_count,
    v_phase1_count,
    v_phase2_count,
    v_phase3_count,
    v_phase4_count,
    v_attack_count,
    v_chase_count,
    v_bridge_count
  from event_rows
  left join canonical
    on canonical.rider_id = event_rows.rider_id
   and canonical.team_id = event_rows.team_id;

  select count(*)::integer
  into v_bridge_exact_count
  from jsonb_array_elements(v_events) row_data(value)
  where row_data.value ->> 'action_kind' = 'bridge'
    and nullif(row_data.value ->> 'phase_number', '')::integer = 2
    and nullif(row_data.value ->> 'team_id', '')::uuid =
        'a08e0e49-8212-4d24-afa1-7ddf2564e9ce'::uuid
    and nullif(row_data.value ->> 'rider_id', '')::uuid =
        'e308a71d-9ccf-4a38-9991-7ceb657c20de'::uuid
    and nullif(row_data.value ->> 'launch_km', '')::numeric = 41
    and nullif(row_data.value ->> 'avg_speed_kmh', '')::numeric = 45.9474
    and nullif(row_data.value ->> 'elapsed_seconds', '')::numeric = 198
    and nullif(row_data.value ->> 'movement_distance_km', '')::numeric = 2.527107
    and nullif(row_data.value ->> 'bridge_gap_closure_distance_km', '')::numeric = 0.0055
    and coalesce(
          (row_data.value ->> 'bridge_teleport_allowed')::boolean,
          true
        ) is false
    and row_data.value ->> 'transition_idempotency_key' =
        'efd8d9bf1958354177d5745b40afa163';

  if v_event_count <> 24
     or v_event_unique_key_count <> 24
     or v_event_invalid_count <> 0
     or v_event_population_mismatch_count <> 0
     or v_phase1_count <> 10
     or v_phase2_count <> 8
     or v_phase3_count <> 4
     or v_phase4_count <> 2
     or v_attack_count <> 14
     or v_chase_count <> 9
     or v_bridge_count <> 1
     or v_bridge_exact_count <> 1
  then
    raise exception
      'Controlled execution event contract failed: rows %, unique keys %, invalid %, population mismatch %, phases %/%/%/%, actions %/%/%, bridge exact %.',
      v_event_count,
      v_event_unique_key_count,
      v_event_invalid_count,
      v_event_population_mismatch_count,
      v_phase1_count,
      v_phase2_count,
      v_phase3_count,
      v_phase4_count,
      v_attack_count,
      v_chase_count,
      v_bridge_count,
      v_bridge_exact_count;
  end if;

  select coalesce(sum(segment_row.distance_km), 0)
  into v_distance_km
  from public.race_engine_get_stage_segments_v1(c_stage_id) segment_row;

  if v_distance_km <= 0 then
    raise exception
      'Controlled execution could not resolve positive Stage 1 distance.';
  end if;

  if not p_apply then
    return jsonb_build_object(
      'status', 'validated_disabled',
      'adapter_version', 'issue01_rio_stage1_controlled_execution_v1',
      'simulation_run_id', p_simulation_run_id,
      'race_id', c_race_id,
      'stage_id', c_stage_id,
      'state_row_count', v_state_count,
      'state_team_count', v_state_team_count,
      'event_row_count', v_event_count,
      'phase_counts', jsonb_build_object(
        'phase1', v_phase1_count,
        'phase2', v_phase2_count,
        'phase3', v_phase3_count,
        'phase4', v_phase4_count
      ),
      'action_counts', jsonb_build_object(
        'attack', v_attack_count,
        'chase', v_chase_count,
        'bridge', v_bridge_count
      ),
      'bridge_exact_contract', v_bridge_exact_count = 1,
      'runtime_apply_enabled', false,
      'writes', 0,
      'runner_called', false
    );
  end if;

  if not v_canary_mode
     or not v_explicit_permission
  then
    return jsonb_build_object(
      'status', 'blocked',
      'reason',
        'controlled_execution_apply_requires_canary_mode_and_explicit_permission',
      'canary_mode', v_canary_mode,
      'explicit_permission', v_explicit_permission,
      'writes', 0
    );
  end if;

  if exists (
    select 1
    from public.race_stage_simulation_runs run_row
    where run_row.id = p_simulation_run_id
       or run_row.stage_id = c_stage_id
  )
  or exists (
    select 1
    from public.race_stage_rider_states state_row
    where state_row.stage_id = c_stage_id
  )
  or exists (
    select 1
    from public.race_stage_replay_frames replay_row
    where replay_row.stage_id = c_stage_id
  )
  or exists (
    select 1
    from public.race_stage_results result_row
    where result_row.stage_id = c_stage_id
  )
  then
    raise exception
      'Controlled execution apply blocked: exact Stage 1 output scope is not empty.';
  end if;

  insert into public.race_stage_simulation_runs (
    id,
    race_id,
    stage_id,
    status,
    engine_version,
    simulation_mode,
    started_at,
    input_snapshot_json,
    result_summary_json
  )
  values (
    p_simulation_run_id,
    c_race_id,
    c_stage_id,
    'running',
    'race_engine_v1_issue01_controlled_execution_v1',
    'issue01_controlled_full_stage_canary',
    clock_timestamp(),
    jsonb_build_object(
      'adapter_version',
        'issue01_rio_stage1_controlled_execution_v1',
      'rider_state_rows_hash',
        md5(v_states::text),
      'issue01_event_rows_hash',
        md5(v_events::text),
      'issue01_event_count',
        v_event_count,
      'physical_bridge_contract',
        'V24F accepted'
    ),
    '{}'::jsonb
  );

  get diagnostics v_run_inserted = row_count;

  insert into public.race_stage_rider_states (
    simulation_run_id,
    race_id,
    stage_id,
    rider_id,
    team_id,
    role_code,
    start_stamina,
    finish_stamina,
    stamina_spent,
    work_done_score,
    fatigue_before_stage,
    fatigue_gain,
    fatigue_after_stage,
    protection_received_score,
    support_work_done_score,
    attack_attempts,
    chase_work_score,
    leadout_work_score,
    breakaway_km,
    incident_risk_score,
    mechanical_risk_score,
    stage_status,
    finish_position,
    finish_time_seconds,
    gap_seconds,
    metadata
  )
  select
    p_simulation_run_id,
    c_race_id,
    c_stage_id,
    nullif(row_data.value ->> 'rider_id', '')::uuid,
    nullif(row_data.value ->> 'team_id', '')::uuid,
    coalesce(
      nullif(row_data.value ->> 'role_code', ''),
      'free_role'
    ),
    nullif(row_data.value ->> 'start_stamina', '')::numeric,
    nullif(row_data.value ->> 'finish_stamina', '')::numeric,
    nullif(row_data.value ->> 'stamina_spent', '')::numeric,
    coalesce(
      nullif(row_data.value ->> 'work_done_score', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'fatigue_before_stage', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'fatigue_gain', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'fatigue_after_stage', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'protection_received_score', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'support_work_done_score', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'attack_attempts', '')::integer,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'chase_work_score', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'leadout_work_score', '')::numeric,
      0
    ),
    coalesce(
      nullif(row_data.value ->> 'breakaway_km', '')::numeric,
      0
    ),
    0,
    0,
    'finished',
    nullif(row_data.value ->> 'finish_position', '')::integer,
    nullif(row_data.value ->> 'finish_time_seconds', '')::integer,
    nullif(row_data.value ->> 'gap_seconds', '')::integer,
    coalesce(row_data.value -> 'metadata', '{}'::jsonb)
    || jsonb_build_object(
         'issue01_controlled_execution',
           jsonb_build_object(
             'adapter_version',
               'issue01_rio_stage1_controlled_execution_v1',
             'simulation_run_id',
               p_simulation_run_id,
             'state_package_hash',
               md5(v_states::text),
             'event_package_hash',
               md5(v_events::text)
           )
       )
  from jsonb_array_elements(v_states) row_data(value);

  get diagnostics v_states_inserted = row_count;

  if v_run_inserted <> 1
     or v_states_inserted <> 96
  then
    raise exception
      'Controlled execution fixture insert failed: run %, states %.',
      v_run_inserted,
      v_states_inserted;
  end if;

  v_group_result :=
    public.race_engine_assign_result_groups_v1(
      p_simulation_run_id
    );

  v_replay_result :=
    public.race_engine_write_replay_frames_v1(
      p_simulation_run_id
    );

  /*
   * Two continuous replay overlay points per accepted Issue 01 event.
   * These rows do not update official state. The bridge completion point uses
   * 2.527107 km road movement, never the 0.0055 km relative gap closure as
   * road distance.
   */
  with event_rows as (
    select
      row_data.value as event_json,
      row_data.ordinality::integer as event_ordinality,
      nullif(row_data.value ->> 'rider_id', '')::uuid as rider_id,
      nullif(row_data.value ->> 'team_id', '')::uuid as team_id,
      lower(row_data.value ->> 'action_kind') as action_kind,
      nullif(row_data.value ->> 'launch_km', '')::numeric as launch_km,
      nullif(row_data.value ->> 'avg_speed_kmh', '')::numeric as avg_speed_kmh,
      nullif(row_data.value ->> 'elapsed_seconds', '')::numeric as elapsed_seconds,
      nullif(row_data.value ->> 'movement_distance_km', '')::numeric as movement_distance_km,
      row_data.value ->> 'transition_idempotency_key' as transition_key
    from jsonb_array_elements(v_events)
      with ordinality row_data(value, ordinality)
  ),
  input_rows as (
    select *
    from public.race_engine_get_stage_rider_inputs_v1(c_stage_id)
  ),
  state_rows as (
    select *
    from public.race_stage_rider_states
    where simulation_run_id = p_simulation_run_id
  ),
  points as (
    select
      event_rows.*,
      input_rows.rider_name,
      input_rows.team_name,
      state_rows.finish_position,
      state_rows.gap_seconds as final_gap_seconds,
      point.point_kind,
      point.point_order,
      case
        when point.point_kind = 'start'
        then event_rows.launch_km
        else event_rows.launch_km
             + event_rows.movement_distance_km
      end as point_km,
      case
        when point.point_kind = 'start'
        then greatest(
               0,
               round(
                 event_rows.launch_km
                 / v_distance_km
                 * v_winner_seconds
               )::integer
             )
        else greatest(
               0,
               round(
                 event_rows.launch_km
                 / v_distance_km
                 * v_winner_seconds
               )::integer
             )
             + round(event_rows.elapsed_seconds)::integer
      end as point_seconds,
      case
        when event_rows.action_kind = 'bridge'
         and point.point_kind = 'end'
        then 0
        when event_rows.action_kind = 'attack'
         and point.point_kind = 'end'
        then greatest(
               0,
               round(
                 coalesce(
                   nullif(
                     event_rows.event_json
                       ->> 'attack_initial_separation_seconds',
                     ''
                   )::numeric,
                   0
                 )
               )::integer
             )
        else coalesce(state_rows.gap_seconds, 0)
      end as point_gap_seconds
    from event_rows
    join input_rows
      on input_rows.rider_id = event_rows.rider_id
     and input_rows.team_id = event_rows.team_id
    join state_rows
      on state_rows.rider_id = event_rows.rider_id
     and state_rows.team_id = event_rows.team_id
    cross join lateral (
      values
        ('start'::text, 1::integer),
        ('end'::text, 2::integer)
    ) point(point_kind, point_order)
  )
  insert into public.race_stage_replay_frames (
    simulation_run_id,
    race_id,
    stage_id,
    frame_number,
    race_seconds,
    km_marker,
    group_code,
    group_label,
    group_order,
    gap_seconds,
    avg_speed_kmh,
    rider_ids,
    rider_names,
    team_names,
    metadata,
    replay_mode,
    entity_type,
    entity_id,
    entity_key,
    entity_label,
    entity_color_slot,
    start_order,
    competition_start_offset_seconds,
    replay_start_offset_seconds,
    entity_elapsed_seconds,
    provisional_rank,
    entity_finished
  )
  select
    p_simulation_run_id,
    c_race_id,
    c_stage_id,
    2000000
      + points.event_ordinality * 2
      + points.point_order
      - 2,
    points.point_seconds,
    points.point_km,
    'issue01_'
      || points.action_kind
      || '_'
      || points.point_kind,
    initcap(points.action_kind)
      || ' '
      || points.point_kind,
    0,
    points.point_gap_seconds,
    points.avg_speed_kmh,
    array[points.rider_id]::uuid[],
    array[coalesce(points.rider_name, points.rider_id::text)]::text[],
    array[coalesce(points.team_name, points.team_id::text)]::text[],
    jsonb_build_object(
      'issue01_overlay',
        true,
      'overlay_contract',
        'issue01_action_overlay_v1',
      'adapter_version',
        'issue01_rio_stage1_controlled_execution_v1',
      'event_point',
        points.point_kind,
      'event_ordinality',
        points.event_ordinality,
      'action_kind',
        points.action_kind,
      'transition_idempotency_key',
        points.transition_key,
      'launch_km',
        points.launch_km,
      'movement_distance_km',
        points.movement_distance_km,
      'elapsed_seconds',
        points.elapsed_seconds,
      'avg_speed_kmh',
        points.avg_speed_kmh,
      'physical_event',
        points.event_json,
      'bridge_no_teleportation',
        case
          when points.action_kind = 'bridge'
          then coalesce(
                 (
                   points.event_json
                     ->> 'bridge_teleport_allowed'
                 )::boolean,
                 true
               ) is false
          else null
        end,
      'replay_only_group_transition',
        points.action_kind = 'bridge'
        and points.point_kind = 'end'
    ),
    'road_race',
    'rider',
    points.rider_id,
    'issue01:'
      || points.transition_key
      || ':'
      || points.point_kind,
    coalesce(points.rider_name, points.rider_id::text),
    ((points.event_ordinality - 1) % 12) + 1,
    points.finish_position,
    0,
    points.point_seconds,
    case
      when points.point_kind = 'start'
      then 0
      else round(points.elapsed_seconds)::integer
    end,
    points.finish_position,
    false
  from points;

  get diagnostics v_overlay_rows_inserted = row_count;

  if v_overlay_rows_inserted <> 48 then
    raise exception
      'Controlled execution overlay insertion failed: expected 48, received %.',
      v_overlay_rows_inserted;
  end if;

  /*
   * Established result-writer boundary: stage results are written only for
   * an already completed simulation run. This completion exists solely
   * inside the controlled rollback/explicit-apply scope.
   */
  update public.race_stage_simulation_runs run_row
  set
    status = 'completed',
    completed_at = coalesce(
      run_row.completed_at,
      clock_timestamp()
    ),
    result_summary_json = jsonb_build_object(
      'adapter_version',
        'issue01_rio_stage1_controlled_execution_v1',
      'boundary_status',
        'states_and_replay_ready_for_stage_result_writer',
      'rider_state_count',
        v_states_inserted,
      'issue01_event_count',
        v_event_count,
      'issue01_overlay_count',
        v_overlay_rows_inserted
    ),
    updated_at = clock_timestamp()
  where run_row.id = p_simulation_run_id
    and run_row.race_id = c_race_id
    and run_row.stage_id = c_stage_id
    and run_row.status = 'running';

  get diagnostics v_run_completion_updated = row_count;

  if v_run_completion_updated <> 1 then
    raise exception
      'Controlled execution run-completion boundary failed: expected 1 updated run, received %.',
      v_run_completion_updated;
  end if;

  v_result_result :=
    public.race_engine_write_stage_results_v1(
      p_simulation_run_id
    );

  v_tail_result :=
    public.race_engine_repair_replay_finish_tail_v1(
      p_simulation_run_id,
      true,
      15
    );

  select count(*)::integer
  into v_base_replay_count
  from public.race_stage_replay_frames replay_row
  where replay_row.simulation_run_id =
      p_simulation_run_id
    and coalesce(
          (
            replay_row.metadata
              ->> 'issue01_overlay'
          )::boolean,
          false
        ) is false;

  select count(*)::integer
  into v_overlay_replay_count
  from public.race_stage_replay_frames replay_row
  where replay_row.simulation_run_id =
      p_simulation_run_id
    and coalesce(
          (
            replay_row.metadata
              ->> 'issue01_overlay'
          )::boolean,
          false
        )
    and replay_row.metadata
          ->> 'overlay_contract' =
        'issue01_action_overlay_v1';

  select count(*)::integer
  into v_result_count
  from public.race_stage_results result_row
  where result_row.stage_id = c_stage_id;

  update public.race_stage_simulation_runs run_row
  set
    status = 'completed',
    completed_at = clock_timestamp(),
    result_summary_json = jsonb_build_object(
      'adapter_version',
        'issue01_rio_stage1_controlled_execution_v1',
      'rider_state_count',
        v_states_inserted,
      'issue01_event_count',
        v_event_count,
      'base_replay_count',
        v_base_replay_count,
      'issue01_overlay_count',
        v_overlay_replay_count,
      'stage_result_count',
        v_result_count,
      'group_writer_result',
        v_group_result,
      'replay_writer_result',
        v_replay_result,
      'stage_result_writer_result',
        v_result_result,
      'tail_repair_result',
        v_tail_result
    ),
    updated_at = clock_timestamp()
  where run_row.id = p_simulation_run_id
    and run_row.race_id = c_race_id
    and run_row.stage_id = c_stage_id
    and run_row.status = 'completed';

  if v_base_replay_count <= 0
     or v_overlay_replay_count <> 48
     or v_result_count <> 96
  then
    raise exception
      'Controlled execution writer boundary failed: base replay %, overlay %, results %.',
      v_base_replay_count,
      v_overlay_replay_count,
      v_result_count;
  end if;

  return jsonb_build_object(
    'status',
      'controlled_execution_applied',
    'adapter_version',
      'issue01_rio_stage1_controlled_execution_v1',
    'simulation_run_id',
      p_simulation_run_id,
    'race_id',
      c_race_id,
    'stage_id',
      c_stage_id,
    'state_row_count',
      v_states_inserted,
    'issue01_event_count',
      v_event_count,
    'base_replay_count',
      v_base_replay_count,
    'issue01_overlay_count',
      v_overlay_replay_count,
    'stage_result_count',
      v_result_count,
    'bridge_exact_contract',
      v_bridge_exact_count = 1,
    'run_completed_before_stage_result_writer',
      v_run_completion_updated = 1,
    'runner_called',
      false,
    'production_runner_changed',
      false,
    'eligible_for_commit',
      false
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enrich_race_results_summary_notification_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type_code text;
  v_race_id_text text;
  v_race_id uuid;
  v_race record;
  v_action_url text;
  v_image_url text;
begin
  select nt.code
  into v_type_code
  from public.notification_types nt
  where nt.id = new.type_id
  limit 1;

  if v_type_code is distinct from 'RACE_RESULTS_SUMMARY' then
    return new;
  end if;

  new.payload_json := coalesce(new.payload_json, '{}'::jsonb);

  v_race_id_text := nullif(new.payload_json->>'race_id', '');

  if v_race_id_text is null then
    v_race_id_text := substring(
      coalesce(new.action_url, '')
      from '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})'
    );
  end if;

  if v_race_id_text is null
    or v_race_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return new;
  end if;

  v_race_id := v_race_id_text::uuid;

  select
    r.id,
    r.name,
    r.logo_url,
    r.profile_image_url,
    rer.race_class_code
  into v_race
  from public.races r
  left join public.race_entry_rules rer
    on rer.race_id = r.id
  where r.id = v_race_id
  limit 1;

  if v_race.id is null then
    return new;
  end if;

  v_action_url := '/dashboard/races/' || v_race.id::text;
  v_image_url := coalesce(
    nullif(v_race.logo_url, ''),
    nullif(v_race.profile_image_url, '')
  );

  -- Always normalize race-results notifications to the dashboard race page.
  new.action_url := v_action_url;

  -- Preserve existing result payload fields such as top_10, your_riders, stage data, etc.
  -- Add/refresh race metadata and image fields needed by the notification UI.
  new.payload_json := new.payload_json || jsonb_build_object(
    'race_id', v_race.id,
    'race_name', v_race.name,
    'race_class_code', v_race.race_class_code,
    'race_logo_url', v_race.logo_url,
    'race_profile_image_url', v_race.profile_image_url,
    'image_url', v_image_url,
    'action_url', v_action_url
  );

  new.title := coalesce(nullif(new.title, ''), 'Race results: ' || coalesce(v_race.name, 'Race'));
  new.message := coalesce(
    nullif(new.message, ''),
    'Race results are available for ' || coalesce(v_race.name, 'this race') || '. Open the race page to review the standings and your riders.'
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_race_stage_authoritative_run_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run public.race_stage_simulation_runs%rowtype;
  v_stage_race_id uuid;
  v_control public.race_engine_runtime_control_v1%rowtype;
begin
  select *
  into v_run
  from public.race_stage_simulation_runs
  where id = new.simulation_run_id;

  if not found then
    raise exception 'Simulation run % does not exist.', new.simulation_run_id;
  end if;

  if v_run.status is distinct from 'completed' then
    raise exception 'Simulation run % is not completed; current status is %.', v_run.id, v_run.status;
  end if;

  select race_id
  into v_stage_race_id
  from public.race_stages
  where id = new.stage_id;

  if not found then
    raise exception 'Race stage % does not exist.', new.stage_id;
  end if;

  if v_run.stage_id is distinct from new.stage_id then
    raise exception 'Simulation run % belongs to stage %, not stage %.', v_run.id, v_run.stage_id, new.stage_id;
  end if;

  if v_run.race_id is distinct from v_stage_race_id then
    raise exception 'Simulation run % race % does not match stage % race %.', v_run.id, v_run.race_id, new.stage_id, v_stage_race_id;
  end if;

  if nullif(btrim(v_run.engine_version), '') is null
     or nullif(btrim(v_run.simulation_mode), '') is null then
    raise exception 'Simulation run % has incomplete engine identity.', v_run.id;
  end if;

  new.race_id := v_run.race_id;
  new.engine_version := v_run.engine_version;
  new.simulation_mode := v_run.simulation_mode;
  new.updated_at := clock_timestamp();

  if new.authority_kind in ('legacy_activation', 'typescript_activation') then
    select *
    into v_control
    from public.race_engine_runtime_control_v1
    where singleton_id = true;

    if not found then
      raise exception 'Engine-control singleton row is missing.';
    end if;

    if new.authority_kind = 'legacy_activation' then
      if v_control.active_engine is distinct from 'legacy_sql'
         or v_control.legacy_execution_enabled is not true
         or v_control.typescript_execution_enabled is not false then
        raise exception 'Legacy authoritative activation is not permitted by engine control.';
      end if;
    elsif new.authority_kind = 'typescript_activation' then
      if v_control.active_engine is distinct from 'typescript_v1'
         or v_control.typescript_execution_enabled is not true
         or v_control.legacy_execution_enabled is not false then
        raise exception 'TypeScript authoritative activation is not permitted by engine control.';
      end if;

      if v_run.engine_version is distinct from 'race_engine_ts_v1'
         or v_run.simulation_mode is distinct from 'deterministic_road_race_v1' then
        raise exception
          'TypeScript activation requires engine_version=race_engine_ts_v1 and simulation_mode=deterministic_road_race_v1; run % has % / %.',
          v_run.id,
          v_run.engine_version,
          v_run.simulation_mode;
      end if;
    end if;
  end if;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.enrich_rider_unhappy_notification_payload_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type_code text;
  v_payload jsonb;
  v_rider_id uuid;
  v_rider_json jsonb;
  v_club_json jsonb;
  v_candidate_name text;
  v_rider_name text;
  v_rider_image_url text;
  v_club_name text;
  v_morale_score integer;
  v_previous_morale integer;
  v_morale_delta integer;
  v_rider_profile_path text;
  v_morale_page_path text;
  v_event_image_url text := 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/rider%20morale%20is%20low.png';
  v_key text;
begin
  select nt.code
  into v_type_code
  from public.notification_types nt
  where nt.id = new.type_id
  limit 1;

  if coalesce(v_type_code, '') <> 'RIDER_UNHAPPY' then
    return new;
  end if;

  v_payload := coalesce(new.payload_json, '{}'::jsonb);

  foreach v_key in array array[
    'rider_id',
    'target_rider_id',
    'club_rider_id',
    'rider_uuid'
  ]
  loop
    if v_rider_id is null and nullif(v_payload->>v_key, '') is not null then
      begin
        v_rider_id := nullif(v_payload->>v_key, '')::uuid;
      exception when invalid_text_representation then
        v_rider_id := null;
      end;
    end if;
  end loop;

  if v_rider_id is not null then
    select to_jsonb(r)
    into v_rider_json
    from public.riders r
    where r.id = v_rider_id
    limit 1;
  end if;

  if v_rider_json is null then
    v_candidate_name := coalesce(
      nullif(v_payload->>'rider_full_name', ''),
      nullif(v_payload->>'rider_name', ''),
      nullif(v_payload->>'full_name', ''),
      nullif(v_payload->>'display_name', ''),
      nullif(v_payload->>'name', ''),
      nullif(regexp_replace(coalesce(new.message, ''), '\s+is unhappy.*$', '', 'i'), ''),
      nullif(regexp_replace(coalesce(new.title, ''), '^Rider morale is low:\s*', '', 'i'), '')
    );

    if v_candidate_name is not null then
      select r.id, to_jsonb(r)
      into v_rider_id, v_rider_json
      from public.riders r
      where lower(coalesce(
        nullif(to_jsonb(r)->>'display_name', ''),
        nullif(to_jsonb(r)->>'full_name', ''),
        nullif(to_jsonb(r)->>'rider_full_name', ''),
        nullif(concat_ws(' ', nullif(to_jsonb(r)->>'first_name', ''), nullif(to_jsonb(r)->>'last_name', '')), ''),
        nullif(to_jsonb(r)->>'name', '')
      )) = lower(v_candidate_name)
      order by r.id
      limit 1;
    end if;
  end if;

  v_rider_name := coalesce(
    nullif(v_payload->>'rider_full_name', ''),
    nullif(v_payload->>'rider_name', ''),
    nullif(v_payload->>'full_name', ''),
    nullif(v_payload->>'display_name', ''),
    case
      when v_rider_json is not null then coalesce(
        nullif(v_rider_json->>'display_name', ''),
        nullif(v_rider_json->>'full_name', ''),
        nullif(v_rider_json->>'rider_full_name', ''),
        nullif(concat_ws(' ', nullif(v_rider_json->>'first_name', ''), nullif(v_rider_json->>'last_name', '')), ''),
        nullif(v_rider_json->>'name', '')
      )
      else null
    end,
    nullif(v_candidate_name, '')
  );

  v_rider_image_url := coalesce(
    nullif(v_payload->>'rider_image_url', ''),
    nullif(v_payload->>'rider_photo_url', ''),
    case when v_rider_json is not null then coalesce(
      nullif(v_rider_json->>'image_url', ''),
      nullif(v_rider_json->>'photo_url', ''),
      nullif(v_rider_json->>'profile_image_url', ''),
      nullif(v_rider_json->>'avatar_url', '')
    ) else null end
  );

  begin
    v_morale_score := coalesce(
      nullif(v_payload->>'morale_score', '')::integer,
      nullif(v_payload->>'morale', '')::integer,
      nullif(v_payload->>'current_morale', '')::integer,
      nullif(v_payload->>'morale_value', '')::integer
    );
  exception when invalid_text_representation then
    v_morale_score := null;
  end;

  if v_morale_score is null and v_rider_json is not null then
    begin
      v_morale_score := coalesce(
        nullif(v_rider_json->>'morale_score', '')::integer,
        nullif(v_rider_json->>'morale', '')::integer,
        nullif(v_rider_json->>'current_morale', '')::integer,
        nullif(v_rider_json->>'morale_value', '')::integer
      );
    exception when invalid_text_representation then
      v_morale_score := null;
    end;
  end if;

  begin
    v_previous_morale := coalesce(
      nullif(v_payload->>'previous_morale', '')::integer,
      nullif(v_payload->>'morale_before', '')::integer,
      nullif(v_payload->>'old_morale', '')::integer
    );
  exception when invalid_text_representation then
    v_previous_morale := null;
  end;

  if v_morale_score is not null and v_previous_morale is not null then
    v_morale_delta := v_morale_score - v_previous_morale;
  else
    begin
      v_morale_delta := coalesce(
        nullif(v_payload->>'morale_delta', '')::integer,
        nullif(v_payload->>'morale_change', '')::integer,
        nullif(v_payload->>'delta', '')::integer
      );
    exception when invalid_text_representation then
      v_morale_delta := null;
    end;
  end if;

  if v_rider_json is not null and nullif(v_rider_json->>'club_id', '') is not null then
    begin
      select to_jsonb(c)
      into v_club_json
      from public.clubs c
      where c.id = nullif(v_rider_json->>'club_id', '')::uuid
      limit 1;
    exception when invalid_text_representation then
      v_club_json := null;
    end;
  end if;

  v_club_name := coalesce(
    nullif(v_payload->>'club_name', ''),
    nullif(v_payload->>'team_name', ''),
    case when v_club_json is not null then coalesce(
      nullif(v_club_json->>'name', ''),
      nullif(v_club_json->>'club_name', '')
    ) else null end
  );

  v_rider_profile_path := coalesce(
    nullif(v_payload->>'my_rider_profile_path', ''),
    nullif(v_payload->>'rider_profile_path', ''),
    nullif(v_payload->>'profile_path', ''),
    case when v_rider_id is not null then '/dashboard/my-riders/' || v_rider_id::text else null end
  );

  v_morale_page_path := coalesce(
    nullif(v_payload->>'qr_page_path', ''),
    nullif(v_payload->>'morale_page_path', ''),
    nullif(v_payload->>'team_morale_path', ''),
    case
      when v_rider_id is not null then '/dashboard/squad?focus=morale&riderId=' || v_rider_id::text
      else '/dashboard/squad?focus=morale'
    end
  );

  v_payload := v_payload || jsonb_strip_nulls(jsonb_build_object(
    'event_type', 'rider_morale_low',
    'image_url', v_event_image_url,
    'event_image_url', v_event_image_url,
    'rider_id', v_rider_id,
    'rider_name', v_rider_name,
    'rider_full_name', v_rider_name,
    'rider_image_url', v_rider_image_url,
    'club_name', v_club_name,
    'morale_score', v_morale_score,
    'previous_morale', v_previous_morale,
    'morale_delta', v_morale_delta,
    'morale_status', coalesce(nullif(v_payload->>'morale_status', ''), 'low_morale'),
    'morale_reason', coalesce(nullif(v_payload->>'morale_reason', ''), nullif(v_payload->>'reason', ''), 'Low morale threshold reached'),
    'my_rider_profile_path', v_rider_profile_path,
    'rider_profile_path', v_rider_profile_path,
    'morale_page_path', v_morale_page_path,
    'qr_page_path', v_morale_page_path,
    'team_squad_path', coalesce(nullif(v_payload->>'team_squad_path', ''), '/dashboard/squad')
  ));

  new.payload_json := v_payload;

  if v_rider_profile_path is not null then
    new.action_url := v_rider_profile_path;
  elsif nullif(new.action_url, '') is null
     or new.action_url in ('/dashboard', '/dashboard/notifications', '#') then
    new.action_url := coalesce(v_morale_page_path, '/dashboard/squad?focus=morale');
  end if;

  if nullif(new.title, '') is null
     or lower(new.title) = 'rider morale is low' then
    new.title := case
      when v_rider_name is not null then 'Rider morale is low: ' || v_rider_name
      else 'Rider morale is low'
    end;
  end if;

  if v_rider_name is not null then
    new.message := v_rider_name || ' is unhappy. Review his morale, race selection, training load, role expectations, contract situation, and upcoming race opportunities.';
  elsif nullif(new.message, '') is null then
    new.message := 'A rider is unhappy. Review morale, race selection, training load, role expectations, contract situation, and upcoming race opportunities.';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_assert_output_write_allowed_v1(p_simulation_run_id uuid, p_race_id uuid, p_stage_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_writer_family text;
  v_run record;
  v_control record;
begin
  v_writer_family := nullif(current_setting('app.race_engine_writer_family', true), '');

  if v_writer_family not in ('legacy', 'typescript') then
    raise exception
      'Race-engine output write blocked: app.race_engine_writer_family must be legacy or typescript.';
  end if;

  select id, race_id, stage_id, engine_version, simulation_mode, status
  into v_run
  from public.race_stage_simulation_runs
  where id = p_simulation_run_id;

  if not found then
    raise exception 'Race-engine output write blocked: simulation run % does not exist.', p_simulation_run_id;
  end if;

  if v_run.race_id is distinct from p_race_id
     or v_run.stage_id is distinct from p_stage_id then
    raise exception
      'Race-engine output write blocked: output race/stage does not match simulation run %.',
      p_simulation_run_id;
  end if;

  select * into v_control
  from public.race_engine_runtime_control_v1
  where singleton_id = true;

  if v_writer_family = 'legacy' then
    if v_run.engine_version like 'race_engine_ts_%'
       or v_run.simulation_mode like 'deterministic_%' then
      raise exception 'Legacy writer cannot write to TypeScript run %.', p_simulation_run_id;
    end if;

    if v_control.active_engine <> 'legacy_sql'
       or not v_control.legacy_execution_enabled then
      raise exception 'Legacy writer blocked because legacy execution is disabled.';
    end if;
  else
    if v_run.engine_version <> 'race_engine_ts_v1'
       or v_run.simulation_mode <> 'deterministic_road_race_v1' then
      raise exception 'TypeScript writer cannot write to non-TypeScript run %.', p_simulation_run_id;
    end if;

    if v_control.active_engine <> 'typescript_v1'
       or not v_control.typescript_execution_enabled then
      raise exception 'TypeScript writer blocked because TypeScript execution is disabled.';
    end if;
  end if;
end
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_guard_simulation_run_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_writer_family text;
  v_control record;
begin
  v_writer_family := nullif(current_setting('app.race_engine_writer_family', true), '');

  if v_writer_family not in ('legacy', 'typescript') then
    raise exception 'Simulation-run write blocked: writer family not declared.';
  end if;

  select * into v_control
  from public.race_engine_runtime_control_v1
  where singleton_id = true;

  if v_writer_family = 'legacy' then
    if coalesce(new.engine_version, old.engine_version) like 'race_engine_ts_%'
       or coalesce(new.simulation_mode, old.simulation_mode) like 'deterministic_%' then
      raise exception 'Legacy writer cannot create, update, or delete a TypeScript run.';
    end if;

    if v_control.active_engine <> 'legacy_sql'
       or not v_control.legacy_execution_enabled then
      raise exception 'Legacy simulation-run write blocked because legacy execution is disabled.';
    end if;
  else
    if coalesce(new.engine_version, old.engine_version) <> 'race_engine_ts_v1'
       or coalesce(new.simulation_mode, old.simulation_mode) <> 'deterministic_road_race_v1' then
      raise exception 'TypeScript simulation-run write requires race_engine_ts_v1/deterministic_road_race_v1.';
    end if;

    if v_control.active_engine <> 'typescript_v1'
       or not v_control.typescript_execution_enabled then
      raise exception 'TypeScript simulation-run write blocked because TypeScript execution is disabled.';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_guard_run_scoped_output_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run_id uuid;
  v_race_id uuid;
  v_stage_id uuid;
begin
  if tg_op = 'DELETE' then
    v_run_id := old.simulation_run_id;
    v_race_id := old.race_id;
    v_stage_id := old.stage_id;
  else
    v_run_id := new.simulation_run_id;
    v_race_id := new.race_id;
    v_stage_id := new.stage_id;
  end if;

  perform public.race_engine_assert_output_write_allowed_v1(
    v_run_id,
    v_race_id,
    v_stage_id
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_guard_result_write_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' and old.simulation_run_id is null then
    raise exception 'Pre-run legacy result rows are immutable.';
  end if;

  if tg_op = 'UPDATE'
     and (old.simulation_run_id is null or new.simulation_run_id is null) then
    raise exception 'Pre-run legacy result rows are immutable and new unscoped results are forbidden.';
  end if;

  if tg_op = 'INSERT' and new.simulation_run_id is null then
    raise exception 'New result rows must be scoped to a simulation run.';
  end if;

  if tg_op = 'DELETE' then
    perform public.race_engine_assert_output_write_allowed_v1(
      old.simulation_run_id,
      old.race_id,
      old.stage_id
    );
    return old;
  end if;

  perform public.race_engine_assert_output_write_allowed_v1(
    new.simulation_run_id,
    new.race_id,
    new.stage_id
  );
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.create_rider_contract_expiry_notifications()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type_id bigint;
  v_notification_id bigint;
  v_rider_profile_path text;
  v_message text;
  r record;
begin
  select nt.id
  into v_type_id
  from public.notification_types nt
  where nt.code = 'RIDER_CONTRACT_EXPIRING'
    and nt.is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'create_rider_contract_expiry_notifications: notification type RIDER_CONTRACT_EXPIRING not found';
  end if;

  for r in
    select *
    from public.get_rider_contract_expiry_candidates()
  loop
    if exists (
      select 1
      from public.user_notifications un
      join public.notifications n
        on n.id = un.notification_id
      where un.user_id = r.user_id
        and un.deleted_at is null
        and n.type_id = v_type_id
        and coalesce(n.payload_json ->> 'rider_id', '') = r.rider_id::text
        and (
          coalesce(n.payload_json ->> 'season_number', '') = coalesce(r.season_number::text, '')
          or coalesce(n.payload_json ->> 'contract_expires_at', '') = coalesce(r.contract_expires_at::text, '')
        )
    ) then
      continue;
    end if;

    v_rider_profile_path := '/dashboard/my-riders/' || r.rider_id::text;

    v_message :=
      coalesce(r.rider_name, 'This rider')
      || '''s contract expires in '
      || coalesce(r.days_left, 0)
      || ' in-game day(s). Review renewal terms, squad role, and replacement planning before the deadline.';

    insert into public.notifications (
      type_id,
      title,
      message,
      source,
      created_by_user_id,
      action_url,
      payload_json,
      expires_at,
      created_at
    )
    values (
      v_type_id,
      'Rider contract expiring: ' || coalesce(r.rider_name, 'Rider'),
      v_message,
      'game',
      null,
      v_rider_profile_path,
      jsonb_build_object(
        'rider_id', r.rider_id,
        'rider_name', r.rider_name,
        'club_id', r.club_id,
        'club_name', r.club_name,
        'contract_expires_at', r.contract_expires_at,
        'days_left', r.days_left,
        'season_number', r.season_number,
        'warning_window_days', 60,
        'category', 'rider_status',
        'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Rider%20contract%20expiring.png',
        'my_rider_profile_path', v_rider_profile_path,
        'rider_profile_path', v_rider_profile_path,
        'team_squad_path', '/dashboard/squad'
      ),
      null,
      now()
    )
    returning id into v_notification_id;

    insert into public.user_notifications (
      user_id,
      notification_id,
      status,
      read_at,
      deleted_at,
      created_at
    )
    values (
      r.user_id,
      v_notification_id,
      'unread',
      null,
      null,
      now()
    );
  end loop;

  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_weather_cancellation_notification_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result_type_id bigint;
  v_stage_type_id bigint;
  v_race_type_id bigint;

  v_stage_id uuid;
  v_race_id uuid;

  v_race record;
  v_stage record;

  v_total_stage_count integer := 0;
  v_cancelled_stage_count integer := 0;
  v_active_stage_count integer := 0;
  v_effective_stage_count integer := 1;

  v_is_one_day boolean := false;
  v_is_race_fully_cancelled boolean := false;
  v_is_stage_cancelled boolean := false;

  v_reason text;
  v_reason_label text;
  v_race_path text;
  v_stage_path text;
  v_image_url text;
  v_event_type_code text;
begin
  select id into v_result_type_id
  from public.notification_types
  where code = 'RACE_RESULTS_SUMMARY'
  limit 1;

  select id into v_stage_type_id
  from public.notification_types
  where code = 'RACE_STAGE_WEATHER_CANCELLED'
  limit 1;

  select id into v_race_type_id
  from public.notification_types
  where code = 'RACE_WEATHER_CANCELLED'
  limit 1;

  if new.type_id is distinct from v_result_type_id
     and new.type_id is distinct from v_stage_type_id
     and new.type_id is distinct from v_race_type_id then
    return new;
  end if;

  begin
    v_stage_id := nullif(coalesce(new.payload_json ->> 'stage_id', ''), '')::uuid;
  exception when others then
    v_stage_id := null;
  end;

  begin
    v_race_id := nullif(coalesce(new.payload_json ->> 'race_id', ''), '')::uuid;
  exception when others then
    v_race_id := null;
  end;

  if v_stage_id is not null then
    select
      rs.id as stage_id,
      rs.race_id,
      rs.stage_number,
      rs.stage_date,
      rs.name as stage_name,
      rs.profile_image_url as stage_profile_image_url,
      coalesce(rs.weather_cancelled, false) as weather_cancelled,
      rs.weather_cancellation_reason,
      rs.weather_cancelled_at
    into v_stage
    from public.race_stages rs
    where rs.id = v_stage_id;

    if v_stage.stage_id is not null then
      v_race_id := v_stage.race_id;
    end if;
  end if;

  if v_race_id is null then
    return new;
  end if;

  select
    r.id as race_id,
    r.name as race_name,
    r.status as race_status,
    coalesce(r.is_stage_race, false) as is_stage_race,
    r.stage_count,
    coalesce(r.metadata, '{}'::jsonb) as race_metadata,
    r.logo_url,
    r.profile_image_url as race_profile_image_url
  into v_race
  from public.races r
  where r.id = v_race_id;

  if v_race.race_id is null then
    return new;
  end if;

  select
    count(*)::integer,
    count(*) filter (where coalesce(rs.weather_cancelled, false) = true)::integer,
    count(*) filter (where coalesce(rs.weather_cancelled, false) = false)::integer
  into v_total_stage_count, v_cancelled_stage_count, v_active_stage_count
  from public.race_stages rs
  where rs.race_id = v_race_id;

  v_effective_stage_count := greatest(coalesce(v_race.stage_count, v_total_stage_count, 1), 1);
  v_is_one_day := v_effective_stage_count <= 1 or coalesce(v_race.is_stage_race, false) = false;

  v_is_stage_cancelled :=
    coalesce(v_stage.weather_cancelled, false) = true
    or lower(coalesce(v_race.race_status, '')) in ('cancelled', 'canceled', 'weather_cancelled', 'weather_canceled');

  v_is_race_fully_cancelled :=
    lower(coalesce(v_race.race_status, '')) in ('cancelled', 'canceled', 'weather_cancelled', 'weather_canceled')
    or coalesce(v_race.race_metadata ->> 'weather_cancellation_status', '') = 'all_stages_weather_cancelled'
    or (
      v_total_stage_count > 0
      and v_cancelled_stage_count >= v_total_stage_count
    )
    or (
      v_is_one_day = true
      and v_is_stage_cancelled = true
    );

  -- RACE_RESULTS_SUMMARY should not remain a results notification when the stage/race is cancelled.
  if new.type_id = v_result_type_id and v_is_stage_cancelled = false and v_is_race_fully_cancelled = false then
    return new;
  end if;

  if v_is_race_fully_cancelled then
    new.type_id := v_race_type_id;
    v_event_type_code := 'race_weather_cancelled';
  else
    new.type_id := v_stage_type_id;
    v_event_type_code := 'stage_weather_cancelled';
  end if;

  v_reason := coalesce(
    nullif(new.payload_json ->> 'reason', ''),
    nullif(new.payload_json ->> 'weather_cancellation_reason', ''),
    nullif(v_stage.weather_cancellation_reason, ''),
    nullif(v_race.race_metadata ->> 'weather_cancellation_reason', ''),
    'unsafe_weather'
  );

  v_reason_label := public.weather_cancellation_reason_label_v1(v_reason);

  v_race_path := '/dashboard/races/' || v_race_id::text;
  v_stage_path := case
    when v_stage_id is not null then v_race_path || '?stageId=' || v_stage_id::text
    else null
  end;

  v_image_url := coalesce(
    nullif(new.payload_json ->> 'event_image_url', ''),
    nullif(new.payload_json ->> 'weather_cancelled_image_url', ''),
    nullif(new.payload_json ->> 'image_url', ''),
    nullif(v_stage.stage_profile_image_url, ''),
    nullif(v_race.logo_url, ''),
    nullif(v_race.race_profile_image_url, '')
  );

  new.action_url := v_race_path;

  if v_is_race_fully_cancelled then
    new.title := 'Race cancelled due to weather: ' || coalesce(v_race.race_name, 'Race');
    new.message := coalesce(v_race.race_name, 'This race')
      || ' was cancelled because of '
      || v_reason_label
      || '. No results, points, prize money, fatigue, or replay will be generated for the cancelled race.';
  else
    new.title := 'Stage cancelled due to weather: ' || coalesce(v_race.race_name, 'Race');
    new.message := 'Stage '
      || coalesce(v_stage.stage_number::text, '?')
      || ' of '
      || coalesce(v_race.race_name, 'this race')
      || ' was cancelled because of '
      || v_reason_label
      || '. The race can continue if other stages are still active.';
  end if;

  new.payload_json := coalesce(new.payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'source', coalesce(nullif(new.payload_json ->> 'source', ''), 'weather_cancellation_v1'),
      'event_type', v_event_type_code,
      'race_id', v_race_id,
      'race_name', v_race.race_name,
      'stage_id', v_stage_id,
      'stage_number', v_stage.stage_number,
      'stage_name', coalesce(nullif(new.payload_json ->> 'stage_name', ''), v_stage.stage_name),
      'stage_date', v_stage.stage_date,
      'reason', v_reason,
      'reason_label', v_reason_label,
      'race_cancelled', v_is_race_fully_cancelled,
      'race_fully_cancelled', v_is_race_fully_cancelled,
      'stage_cancelled', v_is_stage_cancelled,
      'race_path', v_race_path,
      'action_url', v_race_path,
      'stage_path', v_stage_path,
      'image_url', v_image_url,
      'race_logo_url', v_race.logo_url,
      'race_profile_image_url', v_race.race_profile_image_url,
      'stage_profile_image_url', v_stage.stage_profile_image_url,
      'total_stage_count', v_total_stage_count,
      'cancelled_stage_count', v_cancelled_stage_count,
      'active_stage_count', v_active_stage_count,
      'no_results', true,
      'no_points', true,
      'no_replay', true,
      'no_fatigue', true,
      'no_prize_money', true
    );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_priority_game_notification_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_payload jsonb;
  v_rider_id uuid;
  v_rider_name text;
  v_balance integer;
  v_sponsor_name text;
  v_objective_name text;
  v_bonus numeric;
  v_low_count integer;
begin
  select nt.code
  into v_code
  from public.notification_types nt
  where nt.id = new.type_id;

  if v_code not in (
    'RIDER_WANTS_MORE_RACE_SELECTION',
    'RIDER_REQUESTS_RELEASE',
    'COINS_LOW_WARNING',
    'MAIN_SPONSOR_OBJECTIVE_FAILED',
    'MAIN_SPONSOR_OBJECTIVE_ACHIEVED',
    'RACE_SUPPLIES_LOW_STOCK'
  ) then
    return new;
  end if;

  v_payload := coalesce(new.payload_json, '{}'::jsonb);

  if v_code = 'RIDER_WANTS_MORE_RACE_SELECTION' then
    v_rider_id := nullif(v_payload->>'rider_id', '')::uuid;
    v_rider_name := nullif(coalesce(v_payload->>'rider_name', v_payload->>'name'), '');

    new.action_url := coalesce(
      case
        when nullif(v_payload->>'my_rider_profile_path', '') is not null
         and nullif(v_payload->>'my_rider_profile_path', '') <> '/dashboard/squad'
          then nullif(v_payload->>'my_rider_profile_path', '')
        else null
      end,
      case
        when nullif(v_payload->>'rider_profile_path', '') is not null
         and nullif(v_payload->>'rider_profile_path', '') <> '/dashboard/squad'
          then nullif(v_payload->>'rider_profile_path', '')
        else null
      end,
      case when v_rider_id is not null then '/dashboard/my-riders/' || v_rider_id::text else null end,
      case
        when nullif(new.action_url, '') is not null
         and nullif(new.action_url, '') <> '/dashboard/squad'
          then nullif(new.action_url, '')
        else null
      end,
      '/dashboard/squad'
    );

    new.title := case
      when new.title is null or new.title ilike 'TEST — %' then
        'Rider wants more race selection' || coalesce(': ' || v_rider_name, '')
      else new.title
    end;

    new.message := case
      when new.message is null or new.title ilike 'TEST — %' then
        coalesce(v_rider_name || ' wants more chances to race. Review upcoming races and add the rider to suitable selections before morale drops further.',
                 'A rider wants more race opportunities. Review upcoming races and keep morale stable.')
      else new.message
    end;

    new.payload_json := v_payload || jsonb_build_object(
      'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Rider%20wants%20more%20race%20selection.png',
      'category', 'rider_status',
      'team_squad_path', '/dashboard/squad',
      'race_preparation_path', '/dashboard/race-preparation',
      'race_selection_path', '/dashboard/race-preparation'
    ) || case when v_rider_id is not null then jsonb_build_object(
      'my_rider_profile_path', '/dashboard/my-riders/' || v_rider_id::text,
      'rider_profile_path', '/dashboard/my-riders/' || v_rider_id::text
    ) else '{}'::jsonb end;

  elsif v_code = 'RIDER_REQUESTS_RELEASE' then
    v_rider_id := nullif(v_payload->>'rider_id', '')::uuid;
    v_rider_name := nullif(coalesce(v_payload->>'rider_name', v_payload->>'name'), '');

    new.action_url := coalesce(
      case
        when nullif(v_payload->>'my_rider_profile_path', '') is not null
         and nullif(v_payload->>'my_rider_profile_path', '') <> '/dashboard/squad'
          then nullif(v_payload->>'my_rider_profile_path', '')
        else null
      end,
      case
        when nullif(v_payload->>'rider_profile_path', '') is not null
         and nullif(v_payload->>'rider_profile_path', '') <> '/dashboard/squad'
          then nullif(v_payload->>'rider_profile_path', '')
        else null
      end,
      case when v_rider_id is not null then '/dashboard/my-riders/' || v_rider_id::text else null end,
      case
        when nullif(new.action_url, '') is not null
         and nullif(new.action_url, '') <> '/dashboard/squad'
          then nullif(new.action_url, '')
        else null
      end,
      '/dashboard/squad'
    );

    new.title := case
      when new.title is null or new.title ilike 'TEST — %' then
        'Rider requests release' || coalesce(': ' || v_rider_name, '')
      else new.title
    end;

    new.message := case
      when new.message is null or new.title ilike 'TEST — %' then
        coalesce(v_rider_name || ' has asked to leave the team. Review morale, contract status, and recent race selection before making a decision.',
                 'A rider has asked to leave the team. Review morale, contract status, and recent race selection before making a decision.')
      else new.message
    end;

    new.payload_json := v_payload || jsonb_build_object(
      'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Rider%20request%20release.png',
      'category', 'rider_status',
      'team_squad_path', '/dashboard/squad',
      'release_action_path', '/dashboard/transfers',
      'transfers_path', '/dashboard/transfers'
    ) || case when v_rider_id is not null then jsonb_build_object(
      'my_rider_profile_path', '/dashboard/my-riders/' || v_rider_id::text,
      'rider_profile_path', '/dashboard/my-riders/' || v_rider_id::text
    ) else '{}'::jsonb end;

  elsif v_code = 'COINS_LOW_WARNING' then
    v_balance := nullif(coalesce(v_payload->>'coin_balance', v_payload->>'coins_balance', v_payload->>'coins', v_payload->>'balance'), '')::integer;

    new.action_url := '/dashboard/pro-packages';
    new.title := case
      when new.title is null or new.title ilike 'TEST — %' then 'Coins are running low'
      else new.title
    end;
    new.message := case
      when new.message is null or new.title ilike 'TEST — %' then
        case when v_balance is not null
          then 'Your coin balance is down to ' || v_balance::text || ' coin' || case when v_balance = 1 then '' else 's' end || '. Add more coins before your balance reaches zero.'
          else 'Your coin balance is low. Add more coins before your balance reaches zero.'
        end
      else new.message
    end;
    new.payload_json := v_payload || jsonb_build_object(
      'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Coins%20Low%20Warning.png',
      'pro_packages_path', '/dashboard/pro-packages',
      'coin_packages_path', '/dashboard/pro-packages'
    );

  elsif v_code in ('MAIN_SPONSOR_OBJECTIVE_FAILED', 'MAIN_SPONSOR_OBJECTIVE_ACHIEVED') then
    v_sponsor_name := nullif(coalesce(v_payload->>'sponsor_name', v_payload->>'company_name', v_payload->>'main_sponsor_name'), '');
    v_objective_name := nullif(coalesce(v_payload->>'objective_name', v_payload->>'goal_name', v_payload->>'target_name'), '');
    v_bonus := nullif(coalesce(v_payload->>'bonus_amount_cash', v_payload->>'bonus_cash', v_payload->>'bonus_amount', v_payload->>'missed_bonus_cash'), '')::numeric;

    new.action_url := '/dashboard/finance?tab=sponsors';

    if v_code = 'MAIN_SPONSOR_OBJECTIVE_ACHIEVED' then
      new.title := case
        when new.title is null or new.title ilike 'TEST — %' then 'Sponsor objective achieved' || coalesce(': ' || v_objective_name, '')
        else new.title
      end;
      new.message := case
        when new.message is null or new.title ilike 'TEST — %' then
          coalesce(v_sponsor_name, 'Your main sponsor') || ' confirmed that your team achieved the objective' || coalesce(' "' || v_objective_name || '"', '') || '.'
        else new.message
      end;
      new.payload_json := v_payload || jsonb_build_object(
        'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Main%20sponsor%20objecitve%20achived.png',
        'finance_sponsor_path', '/dashboard/finance?tab=sponsors',
        'finance_sponsors_path', '/dashboard/finance?tab=sponsors',
        'sponsor_path', '/dashboard/finance?tab=sponsors',
        'sponsors_path', '/dashboard/finance?tab=sponsors',
        'objectives_path', '/dashboard/finance?tab=sponsors',
        'objective_result', 'achieved'
      );
    else
      new.title := case
        when new.title is null or new.title ilike 'TEST — %' then 'Sponsor objective failed' || coalesce(': ' || v_objective_name, '')
        else new.title
      end;
      new.message := case
        when new.message is null or new.title ilike 'TEST — %' then
          coalesce(v_sponsor_name, 'Your main sponsor') || ' marked an objective as failed' || coalesce(' "' || v_objective_name || '"', '') || '. Review the missed target and sponsor impact.'
        else new.message
      end;
      new.payload_json := v_payload || jsonb_build_object(
        'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Main%20sponsor%20objecitve%20faild.png',
        'finance_sponsor_path', '/dashboard/finance?tab=sponsors',
        'finance_sponsors_path', '/dashboard/finance?tab=sponsors',
        'sponsor_path', '/dashboard/finance?tab=sponsors',
        'sponsors_path', '/dashboard/finance?tab=sponsors',
        'objectives_path', '/dashboard/finance?tab=sponsors',
        'objective_result', 'failed'
      );
    end if;

  elsif v_code = 'RACE_SUPPLIES_LOW_STOCK' then
    v_low_count := nullif(coalesce(v_payload->>'low_stock_count', v_payload->>'low_supply_count', v_payload->>'item_count', v_payload->>'count'), '')::integer;

    new.action_url := '/dashboard/equipment?tab=race-supplies';
    new.title := case
      when new.title is null or new.title ilike 'TEST — %' then 'Race supplies low stock'
      else new.title
    end;
    new.message := case
      when new.message is null or new.title ilike 'TEST — %' then
        'Some race supplies are below the recommended stock level. Restock early so upcoming race preparation is not blocked.'
      else new.message
    end;
    new.payload_json := v_payload || jsonb_build_object(
      'image_url', 'https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Race%20Supplies%20low.png',
      'race_supplies_path', '/dashboard/equipment?tab=race-supplies',
      'supplies_path', '/dashboard/equipment?tab=race-supplies',
      'equipment_path', '/dashboard/equipment'
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_new_club_race_supplies_low_notification_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event_key text;
  v_is_low boolean := false;
begin
  if coalesce(new.is_ai,false)=true
     or new.owner_user_id is null
     or coalesce(new.club_type,'main') <> 'main' then
    return new;
  end if;

  -- Every newly created user main team starts with a usable supply baseline.
  perform public.equipment_ensure_starter_race_supplies_for_club_v1(new.id);

  -- Only warn if the team is still actually at/below a critical threshold.
  select exists (
    with expected_supplies(supply_key,threshold_quantity) as (
      values
        ('bidons_water_bottles'::text,10::integer),
        ('energy_gels'::text,10::integer),
        ('nutrition_packs'::text,20::integer),
        ('race_jersey_complete'::text,3::integer),
        ('rain_jackets'::text,3::integer)
    )
    select 1
    from expected_supplies e
    left join public.club_race_supplies s
      on s.club_id=new.id and s.supply_key=e.supply_key
    where coalesce(s.quantity_available,0) <= e.threshold_quantity
  ) into v_is_low;

  if not v_is_low then
    return new;
  end if;

  if not exists (
    select 1 from public.notification_types nt
    where nt.code='RACE_SUPPLIES_LOW' and nt.is_active is true
  ) then
    return new;
  end if;

  v_event_key := 'new_club_race_supplies_low:' || new.id::text;

  perform public.ppm_create_user_notification_direct_v1(
    new.owner_user_id,
    'RACE_SUPPLIES_LOW',
    'Race supplies critically low',
    'Your new team has not stocked enough race supplies yet. Open Race Supplies and prepare bidons, gels, nutrition packs, jerseys and weather gear before the first race.',
    '/dashboard/equipment?tab=race-supplies',
    jsonb_build_object(
      'source','new_club_setup_v2_with_starter_supplies',
      'event_type','new_club_race_supplies_low',
      'club_id',new.id,
      'club_name',new.name,
      'image_url','https://okuravitxocyevkexfgi.supabase.co/storage/v1/object/public/Admin%20Staff/Event%20images/Race%20Supplies%20low.png',
      'race_supplies_path','/dashboard/equipment?tab=race-supplies',
      'equipment_path','/dashboard/equipment',
      'first_day_warning',true,
      'recommended_action','stock_race_supplies'
    ),
    v_event_key
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.premium_set_updated_at_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_premium_subscription_state_v1(p_user_id uuid, p_plan_code text, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_stripe_status text, p_cancel_at_period_end boolean, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_canceled_at timestamp with time zone, p_ended_at timestamp with time zone, p_stripe_event_id text, p_stripe_event_created bigint, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.user_premium_subscriptions%rowtype;
  v_cancel_at_period_end boolean;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF NULLIF(btrim(p_plan_code), '') IS NULL THEN
    RAISE EXCEPTION 'p_plan_code is required';
  END IF;

  IF NULLIF(btrim(p_stripe_subscription_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_subscription_id is required';
  END IF;

  IF p_stripe_status NOT IN (
    'trialing',
    'active',
    'past_due',
    'canceled',
    'unpaid',
    'incomplete',
    'incomplete_expired',
    'paused'
  ) THEN
    RAISE EXCEPTION
      'Unsupported Stripe subscription status: %',
      p_stripe_status;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.premium_plans p
    WHERE p.code = p_plan_code
  ) THEN
    RAISE EXCEPTION
      'Premium plan not found: %',
      p_plan_code;
  END IF;

  /*
   * Once Stripe says the subscription is fully canceled or expired,
   * it is no longer merely scheduled to cancel at period end.
   */
  v_cancel_at_period_end :=
    CASE
      WHEN p_stripe_status IN (
        'canceled',
        'incomplete_expired'
      ) THEN false
      ELSE COALESCE(
        p_cancel_at_period_end,
        false
      )
    END;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'premium_subscription:' ||
      p_stripe_subscription_id,
      0
    )
  );

  INSERT INTO public.user_premium_subscriptions (
    user_id,
    plan_code,
    provider,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_price_id,
    stripe_status,
    cancel_at_period_end,
    current_period_start,
    current_period_end,
    canceled_at,
    ended_at,
    last_stripe_event_id,
    last_stripe_event_created,
    metadata
  )
  VALUES (
    p_user_id,
    p_plan_code,
    'stripe',
    NULLIF(btrim(p_stripe_customer_id), ''),
    p_stripe_subscription_id,
    NULLIF(btrim(p_stripe_price_id), ''),
    p_stripe_status,
    v_cancel_at_period_end,
    p_current_period_start,
    p_current_period_end,
    p_canceled_at,
    p_ended_at,
    NULLIF(btrim(p_stripe_event_id), ''),
    p_stripe_event_created,
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    plan_code = EXCLUDED.plan_code,
    provider = EXCLUDED.provider,
    stripe_customer_id = EXCLUDED.stripe_customer_id,
    stripe_subscription_id = EXCLUDED.stripe_subscription_id,
    stripe_price_id = EXCLUDED.stripe_price_id,
    stripe_status = EXCLUDED.stripe_status,
    cancel_at_period_end = EXCLUDED.cancel_at_period_end,
    current_period_start = EXCLUDED.current_period_start,
    current_period_end = EXCLUDED.current_period_end,
    canceled_at = EXCLUDED.canceled_at,
    ended_at = EXCLUDED.ended_at,
    last_stripe_event_id = EXCLUDED.last_stripe_event_id,
    last_stripe_event_created =
      EXCLUDED.last_stripe_event_created,
    metadata =
      public.user_premium_subscriptions.metadata
      || EXCLUDED.metadata
  WHERE
    public.user_premium_subscriptions
      .last_stripe_event_created IS NULL
    OR EXCLUDED.last_stripe_event_created IS NULL
    OR EXCLUDED.last_stripe_event_created >=
      public.user_premium_subscriptions
        .last_stripe_event_created
  RETURNING *
  INTO v_row;

  IF v_row.user_id IS NULL THEN
    SELECT *
    INTO v_row
    FROM public.user_premium_subscriptions s
    WHERE s.user_id = p_user_id;
  END IF;

  RETURN jsonb_build_object(
    'ok',
    true,
    'user_id',
    v_row.user_id,
    'plan_code',
    v_row.plan_code,
    'stripe_status',
    v_row.stripe_status,
    'cancel_at_period_end',
    v_row.cancel_at_period_end,
    'current_period_start',
    v_row.current_period_start,
    'current_period_end',
    v_row.current_period_end,
    'access_until',
    v_row.access_until,
    'last_stripe_event_id',
    v_row.last_stripe_event_id
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_premium_invoice_paid_v1(p_user_id uuid, p_plan_code text, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_stripe_status text, p_stripe_invoice_id text, p_stripe_event_id text, p_stripe_event_created bigint, p_billing_reason text, p_amount_paid_cents bigint, p_currency text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan public.premium_plans%rowtype;
  v_inserted_invoice_id text;
  v_system_key text;
  v_existing_access_until timestamptz;
  v_new_access_until timestamptz;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_invoice_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_invoice_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_event_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_event_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_subscription_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_subscription_id is required';
  END IF;

  IF p_period_start IS NULL OR p_period_end IS NULL THEN
    RAISE EXCEPTION
      'Paid invoice period_start and period_end are required';
  END IF;

  IF p_period_end <= p_period_start THEN
    RAISE EXCEPTION
      'Paid invoice period_end must be after period_start';
  END IF;

  SELECT *
  INTO v_plan
  FROM public.premium_plans p
  WHERE p.code = p_plan_code
    AND p.active = true
  FOR UPDATE;

  IF v_plan.code IS NULL THEN
    RAISE EXCEPTION
      'Active Premium plan not found: %',
      p_plan_code;
  END IF;

  IF v_plan.provider_price_id IS NOT NULL
     AND NULLIF(btrim(p_stripe_price_id), '')
       IS DISTINCT FROM v_plan.provider_price_id
  THEN
    RAISE EXCEPTION
      'Stripe price does not match Premium plan configuration';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'premium_invoice:' ||
      p_stripe_invoice_id,
      0
    )
  );

  v_system_key :=
    'stripe_invoice_' ||
    p_stripe_invoice_id;

  /*
   * Insert first. A duplicate invoice returns idempotently.
   * Any later failure rolls this insert back with the transaction.
   */
  INSERT INTO public.premium_invoice_payments (
    stripe_invoice_id,
    stripe_event_id,
    user_id,
    plan_code,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_price_id,
    billing_reason,
    amount_paid_cents,
    currency,
    period_start,
    period_end,
    coins_granted,
    ledger_system_key,
    stripe_event_created,
    raw_payload
  )
  VALUES (
    p_stripe_invoice_id,
    p_stripe_event_id,
    p_user_id,
    v_plan.code,
    NULLIF(btrim(p_stripe_customer_id), ''),
    p_stripe_subscription_id,
    NULLIF(btrim(p_stripe_price_id), ''),
    NULLIF(btrim(p_billing_reason), ''),
    p_amount_paid_cents,
    upper(NULLIF(btrim(p_currency), '')),
    p_period_start,
    p_period_end,
    v_plan.coins_per_paid_invoice,
    v_system_key,
    p_stripe_event_created,
    COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (stripe_invoice_id) DO NOTHING
  RETURNING stripe_invoice_id
  INTO v_inserted_invoice_id;

  IF v_inserted_invoice_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',
      true,
      'idempotent',
      true,
      'stripe_invoice_id',
      p_stripe_invoice_id,
      'coins_granted',
      0
    );
  END IF;

  SELECT s.access_until
  INTO v_existing_access_until
  FROM public.user_premium_subscriptions s
  WHERE s.user_id = p_user_id
  FOR UPDATE;

  v_new_access_until :=
    CASE
      WHEN v_existing_access_until IS NULL THEN
        p_period_end
      WHEN p_period_end > v_existing_access_until THEN
        p_period_end
      ELSE
        v_existing_access_until
    END;

  INSERT INTO public.user_premium_subscriptions (
    user_id,
    plan_code,
    provider,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_price_id,
    stripe_status,
    cancel_at_period_end,
    current_period_start,
    current_period_end,
    access_until,
    latest_invoice_id,
    last_paid_invoice_id,
    last_stripe_event_id,
    last_stripe_event_created,
    metadata
  )
  VALUES (
    p_user_id,
    v_plan.code,
    'stripe',
    NULLIF(btrim(p_stripe_customer_id), ''),
    p_stripe_subscription_id,
    NULLIF(btrim(p_stripe_price_id), ''),
    COALESCE(
      NULLIF(btrim(p_stripe_status), ''),
      'active'
    ),
    COALESCE(p_cancel_at_period_end, false),
    p_current_period_start,
    p_current_period_end,
    p_period_end,
    p_stripe_invoice_id,
    p_stripe_invoice_id,
    p_stripe_event_id,
    p_stripe_event_created,
    jsonb_build_object(
      'last_paid_billing_reason',
      p_billing_reason
    )
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    plan_code = EXCLUDED.plan_code,
    provider = EXCLUDED.provider,
    stripe_customer_id = EXCLUDED.stripe_customer_id,
    stripe_subscription_id = EXCLUDED.stripe_subscription_id,
    stripe_price_id = EXCLUDED.stripe_price_id,

    stripe_status =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.stripe_status
        ELSE
          public.user_premium_subscriptions
            .stripe_status
      END,

    cancel_at_period_end =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.cancel_at_period_end
        ELSE
          public.user_premium_subscriptions
            .cancel_at_period_end
      END,

    current_period_start =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.current_period_start
        ELSE
          public.user_premium_subscriptions
            .current_period_start
      END,

    current_period_end =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.current_period_end
        ELSE
          public.user_premium_subscriptions
            .current_period_end
      END,

    access_until = v_new_access_until,

    latest_invoice_id =
      CASE
        WHEN
          public.user_premium_subscriptions
            .access_until IS NULL
          OR p_period_end >=
            public.user_premium_subscriptions
              .access_until
        THEN p_stripe_invoice_id
        ELSE
          public.user_premium_subscriptions
            .latest_invoice_id
      END,

    last_paid_invoice_id =
      CASE
        WHEN
          public.user_premium_subscriptions
            .access_until IS NULL
          OR p_period_end >=
            public.user_premium_subscriptions
              .access_until
        THEN p_stripe_invoice_id
        ELSE
          public.user_premium_subscriptions
            .last_paid_invoice_id
      END,

    last_stripe_event_id =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.last_stripe_event_id
        ELSE
          public.user_premium_subscriptions
            .last_stripe_event_id
      END,

    last_stripe_event_created =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.last_stripe_event_created
        ELSE
          public.user_premium_subscriptions
            .last_stripe_event_created
      END,

    metadata =
      public.user_premium_subscriptions.metadata
      || EXCLUDED.metadata;

  /*
   * The repaired wallet function rejects invalid debits and deduplicates
   * automated entries by payload_json.system_key.
   */
  PERFORM public.apply_coin_delta(
    p_user_id,
    v_plan.coins_per_paid_invoice,
    'premium_monthly_grant',
    jsonb_build_object(
      'system_key',
      v_system_key,
      'category',
      'premium_monthly_grant',
      'provider',
      'stripe',
      'plan_code',
      v_plan.code,
      'stripe_invoice_id',
      p_stripe_invoice_id,
      'stripe_subscription_id',
      p_stripe_subscription_id,
      'stripe_event_id',
      p_stripe_event_id,
      'billing_reason',
      p_billing_reason,
      'period_start',
      p_period_start,
      'period_end',
      p_period_end,
      'amount_paid_cents',
      p_amount_paid_cents,
      'currency',
      upper(NULLIF(btrim(p_currency), ''))
    )
  );

  RETURN jsonb_build_object(
    'ok',
    true,
    'idempotent',
    false,
    'user_id',
    p_user_id,
    'plan_code',
    v_plan.code,
    'stripe_invoice_id',
    p_stripe_invoice_id,
    'access_until',
    v_new_access_until,
    'coins_granted',
    v_plan.coins_per_paid_invoice,
    'ledger_system_key',
    v_system_key
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_premium_payment_failed_v1(p_user_id uuid, p_plan_code text, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_stripe_status text, p_stripe_invoice_id text, p_stripe_event_id text, p_stripe_event_created bigint, p_attempt_count integer, p_next_payment_attempt timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted_event_id text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_invoice_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_invoice_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_event_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_event_id is required';
  END IF;

  IF NULLIF(btrim(p_stripe_subscription_id), '') IS NULL THEN
    RAISE EXCEPTION 'p_stripe_subscription_id is required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.premium_plans p
    WHERE p.code = p_plan_code
  ) THEN
    RAISE EXCEPTION
      'Premium plan not found: %',
      p_plan_code;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(
      'premium_payment_failure:' ||
      p_stripe_event_id,
      0
    )
  );

  INSERT INTO public.premium_payment_failures (
    stripe_event_id,
    stripe_invoice_id,
    user_id,
    plan_code,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_price_id,
    attempt_count,
    next_payment_attempt,
    stripe_event_created,
    raw_payload
  )
  VALUES (
    p_stripe_event_id,
    p_stripe_invoice_id,
    p_user_id,
    p_plan_code,
    NULLIF(btrim(p_stripe_customer_id), ''),
    p_stripe_subscription_id,
    NULLIF(btrim(p_stripe_price_id), ''),
    p_attempt_count,
    p_next_payment_attempt,
    p_stripe_event_created,
    COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (stripe_event_id) DO NOTHING
  RETURNING stripe_event_id
  INTO v_inserted_event_id;

  IF v_inserted_event_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',
      true,
      'idempotent',
      true,
      'stripe_event_id',
      p_stripe_event_id
    );
  END IF;

  INSERT INTO public.user_premium_subscriptions (
    user_id,
    plan_code,
    provider,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_price_id,
    stripe_status,
    last_payment_failed_at,
    latest_invoice_id,
    last_stripe_event_id,
    last_stripe_event_created,
    metadata
  )
  VALUES (
    p_user_id,
    p_plan_code,
    'stripe',
    NULLIF(btrim(p_stripe_customer_id), ''),
    p_stripe_subscription_id,
    NULLIF(btrim(p_stripe_price_id), ''),
    COALESCE(
      NULLIF(btrim(p_stripe_status), ''),
      'past_due'
    ),
    now(),
    p_stripe_invoice_id,
    p_stripe_event_id,
    p_stripe_event_created,
    jsonb_build_object(
      'last_failed_invoice_id',
      p_stripe_invoice_id
    )
  )
  ON CONFLICT (user_id) DO UPDATE
  SET
    plan_code = EXCLUDED.plan_code,
    provider = EXCLUDED.provider,
    stripe_customer_id = EXCLUDED.stripe_customer_id,
    stripe_subscription_id = EXCLUDED.stripe_subscription_id,
    stripe_price_id = EXCLUDED.stripe_price_id,

    stripe_status =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.stripe_status
        ELSE
          public.user_premium_subscriptions
            .stripe_status
      END,

    last_payment_failed_at = now(),
    latest_invoice_id = EXCLUDED.latest_invoice_id,

    last_stripe_event_id =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.last_stripe_event_id
        ELSE
          public.user_premium_subscriptions
            .last_stripe_event_id
      END,

    last_stripe_event_created =
      CASE
        WHEN
          public.user_premium_subscriptions
            .last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created IS NULL
          OR EXCLUDED.last_stripe_event_created >=
            public.user_premium_subscriptions
              .last_stripe_event_created
        THEN EXCLUDED.last_stripe_event_created
        ELSE
          public.user_premium_subscriptions
            .last_stripe_event_created
      END,

    metadata =
      public.user_premium_subscriptions.metadata
      || EXCLUDED.metadata;

  /*
   * Deliberately do not modify access_until and do not grant coins.
   * Existing paid access remains until its previously paid-through date.
   */
  RETURN jsonb_build_object(
    'ok',
    true,
    'idempotent',
    false,
    'user_id',
    p_user_id,
    'stripe_invoice_id',
    p_stripe_invoice_id,
    'coins_granted',
    0
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_calibrated_shadow_source_bundle_v1(p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_stage jsonb;
  v_profile_detail jsonb := '{}'::jsonb;
  v_teams jsonb := '[]'::jsonb;
  v_participants jsonb := '[]'::jsonb;
  v_rider_inputs jsonb := '[]'::jsonb;
  v_segments jsonb := '[]'::jsonb;
  v_phase_commands jsonb := '[]'::jsonb;
  v_phase_command_effects jsonb := '[]'::jsonb;

  v_preflight_raw jsonb := '{}'::jsonb;
  v_strategy_raw jsonb := '{}'::jsonb;
  v_processing_preflight jsonb := '{}'::jsonb;
  v_processing_strategy jsonb := '{}'::jsonb;

  v_latest_official_run jsonb := null;
  v_official_results jsonb := '[]'::jsonb;
  v_official_winner jsonb := null;

  v_race_id uuid;
  v_stage_format text;

  v_team_count integer := 0;
  v_accepted_team_count integer := 0;
  v_empty_accepted_team_count integer := 0;
  v_participant_rider_count integer := 0;
  v_rider_input_count integer := 0;
  v_segment_count integer := 0;
  v_phase_command_count integer := 0;
  v_official_result_count integer := 0;
begin
  if p_stage_id is null then
    return jsonb_build_object(
      'status', 'invalid_stage_id',
      'bundle_version', 'calibrated_shadow_source_bundle_compact_v2',
      'stage_id', null,
      'message', 'p_stage_id must not be null.'
    );
  end if;

  select
    s.race_id,
    coalesce(s.stage_format, 'road_race'),
    jsonb_build_object(
      'id', s.id,
      'race_id', s.race_id,
      'race_name', r.name,
      'race_category', r.category,
      'name', s.name,
      'stage_number', s.stage_number,
      'stage_date', s.stage_date,
      'stage_format', coalesce(s.stage_format, 'road_race'),
      'distance_km', s.distance_km,
      'terrain_type', s.terrain_type,
      'profile_type', s.profile_type,
      'finish_type', s.finish_type,
      'start_city', s.start_city,
      'finish_city', s.finish_city,
      'weather_snapshot', coalesce(s.weather_snapshot, '{}'::jsonb),
      'weather_summary', s.weather_summary
    )
  into
    v_race_id,
    v_stage_format,
    v_stage
  from public.race_stages s
  join public.races r
    on r.id = s.race_id
  where s.id = p_stage_id
  limit 1;

  if v_stage is null or v_race_id is null then
    return jsonb_build_object(
      'status', 'stage_not_found',
      'bundle_version', 'calibrated_shadow_source_bundle_compact_v2',
      'stage_id', p_stage_id,
      'message', 'The requested stage was not found.'
    );
  end if;

  if v_stage_format <> 'road_race' then
    return jsonb_build_object(
      'status', 'unsupported_stage_format',
      'bundle_version', 'calibrated_shadow_source_bundle_compact_v2',
      'stage_id', p_stage_id,
      'race_id', v_race_id,
      'stage_format', v_stage_format,
      'message', 'The calibrated shadow runner currently supports road_race only.'
    );
  end if;

  v_profile_detail :=
    coalesce(
      public.get_race_stage_profile_detail_v1(p_stage_id),
      '{}'::jsonb
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'team_id', rpt.team_id,
          'status', rpt.status,
          'team_name_snapshot', rpt.team_name_snapshot,
          'country_code_snapshot', rpt.country_code_snapshot,
          'logo_url_snapshot', rpt.logo_url_snapshot
        )
        order by rpt.team_name_snapshot, rpt.team_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer,
    count(*) filter (where rpt.status = 'accepted')::integer
  into
    v_teams,
    v_team_count,
    v_accepted_team_count
  from public.race_participant_teams rpt
  where rpt.race_id = v_race_id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id', rpr.rider_id,
          'team_id', rpr.team_id,
          'start_number', rpr.start_number,
          'role_snapshot', rpr.role_snapshot,
          'rider_name_snapshot', rpr.rider_name_snapshot,
          'team_name_snapshot', rpr.team_name_snapshot,
          'country_code_snapshot', rpr.country_code_snapshot
        )
        order by
          rpr.team_id,
          rpr.start_number nulls last,
          rpr.rider_name_snapshot,
          rpr.rider_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into
    v_participants,
    v_participant_rider_count
  from public.race_participant_riders rpr
  where rpr.race_id = v_race_id;

  select
    count(*)::integer
  into
    v_empty_accepted_team_count
  from public.race_participant_teams rpt
  where rpt.race_id = v_race_id
    and rpt.status = 'accepted'
    and not exists (
      select 1
      from public.race_participant_riders rpr
      where rpr.race_id = rpt.race_id
        and rpr.team_id = rpt.team_id
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'race_id', ri.race_id,
          'stage_id', ri.stage_id,
          'rider_id', ri.rider_id,
          'team_id', ri.team_id,
          'rider_name', ri.rider_name,
          'team_name', ri.team_name,
          'role_code', ri.role_code,
          'stage_role', ri.stage_role,
          'stage_tactic', ri.stage_tactic,
          'sprint', ri.sprint,
          'climbing', ri.climbing,
          'time_trial', ri.time_trial,
          'flat', ri.flat,
          'endurance', ri.endurance,
          'recovery', ri.recovery,
          'resistance', ri.resistance,
          'race_iq', ri.race_iq,
          'teamwork', ri.teamwork,
          'morale', ri.morale,
          'fatigue', ri.fatigue,
          'availability_status', ri.availability_status,
          'start_stamina', ri.start_stamina,
          'fatigue_before_stage', ri.fatigue_before_stage,
          'preparation_id', ri.preparation_id,
          'stage_plan_id', ri.stage_plan_id
        )
        order by ri.team_id, ri.rider_name, ri.rider_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into
    v_rider_inputs,
    v_rider_input_count
  from public.race_engine_get_stage_rider_inputs_v1(p_stage_id) ri;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'segment_order', seg.segment_order,
          'km_start', seg.km_start,
          'km_end', seg.km_end,
          'distance_km', seg.distance_km,
          'elevation_start_m', seg.elevation_start_m,
          'elevation_end_m', seg.elevation_end_m,
          'elevation_change_m', seg.elevation_change_m,
          'slope_percent', seg.slope_percent,
          'terrain_type', seg.terrain_type,
          'phase_number', seg.phase_number
        )
        order by seg.segment_order
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into
    v_segments,
    v_segment_count
  from public.race_engine_get_stage_segments_v1(p_stage_id) seg;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id', cmd.rider_id,
          'team_id', cmd.team_id,
          'rider_name', cmd.rider_name,
          'team_name', cmd.team_name,
          'role_code', cmd.role_code,
          'team_plan', cmd.team_plan,
          'phase_1_command', cmd.phase_1_command,
          'phase_2_command', cmd.phase_2_command,
          'phase_3_command', cmd.phase_3_command,
          'phase_4_command', cmd.phase_4_command
        )
        order by cmd.team_name, cmd.rider_name, cmd.rider_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into
    v_phase_commands,
    v_phase_command_count
  from public.race_engine_get_stage_phase_commands_v1(p_stage_id) cmd;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id', effect.rider_id,
          'team_id', effect.team_id,
          'role_code', effect.role_code,
          'weighted_effort_multiplier', effect.weighted_effort_multiplier,
          'weighted_performance_modifier', effect.weighted_performance_modifier
        )
        order by effect.team_name, effect.rider_name, effect.rider_id
      ),
      '[]'::jsonb
    )
  into
    v_phase_command_effects
  from public.race_engine_get_stage_phase_command_effects_v1(p_stage_id) effect;

  v_preflight_raw :=
    coalesce(
      public.race_engine_get_stage_processing_preflight_v1(p_stage_id),
      '{}'::jsonb
    );

  v_processing_preflight :=
    jsonb_build_object(
      'status', v_preflight_raw->>'status',
      'ready_for_road_runner',
        coalesce((v_preflight_raw->>'ready_for_road_runner')::boolean, false),
      'segment_rows',
        coalesce((v_preflight_raw->>'segment_rows')::integer, 0),
      'participant_team_rows',
        coalesce((v_preflight_raw->>'participant_team_rows')::integer, 0),
      'participant_rider_rows',
        coalesce((v_preflight_raw->>'participant_rider_rows')::integer, 0),
      'participant_rider_distinct_team_rows',
        coalesce(
          (v_preflight_raw->>'participant_rider_distinct_team_rows')::integer,
          0
        ),
      'missing_requirements',
        coalesce(v_preflight_raw->'missing_requirements', '[]'::jsonb),
      'warnings',
        coalesce(v_preflight_raw->'warnings', '[]'::jsonb)
    );

  v_strategy_raw :=
    coalesce(
      public.race_engine_get_stage_processing_strategy_v1(p_stage_id),
      '{}'::jsonb
    );

  v_processing_strategy :=
    jsonb_build_object(
      'status', v_strategy_raw->>'status',
      'stage_format', v_strategy_raw->>'stage_format',
      'selected_runner_function',
        v_strategy_raw->>'selected_runner_function',
      'selected_finalizer_function',
        v_strategy_raw->>'selected_finalizer_function',
      'runner_exists',
        coalesce((v_strategy_raw->>'runner_exists')::boolean, false),
      'finalizer_exists',
        coalesce((v_strategy_raw->>'finalizer_exists')::boolean, false)
    );

  select
    jsonb_build_object(
      'id', run_row.id,
      'race_id', run_row.race_id,
      'stage_id', run_row.stage_id,
      'status', run_row.status,
      'engine_version', run_row.engine_version,
      'simulation_mode', run_row.simulation_mode,
      'started_at', run_row.started_at,
      'completed_at', run_row.completed_at,
      'failed_at', run_row.failed_at,
      'created_at', run_row.created_at,
      'updated_at', run_row.updated_at
    )
  into
    v_latest_official_run
  from public.race_stage_simulation_runs run_row
  where run_row.stage_id = p_stage_id
  order by run_row.created_at desc, run_row.id desc
  limit 1;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rank', result_row.rank,
          'rider_id', result_row.rider_id,
          'team_id', result_row.team_id,
          'rider_name_snapshot', result_row.rider_name_snapshot,
          'team_name_snapshot', result_row.team_name_snapshot,
          'elapsed_seconds', result_row.elapsed_seconds,
          'gap_seconds', result_row.gap_seconds,
          'status', result_row.status,
          'simulation_run_id', result_row.simulation_run_id
        )
        order by
          result_row.rank nulls last,
          result_row.elapsed_seconds nulls last,
          result_row.rider_id
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  into
    v_official_results,
    v_official_result_count
  from public.race_stage_results result_row
  where result_row.stage_id = p_stage_id;

  select
    jsonb_build_object(
      'rank', result_row.rank,
      'rider_id', result_row.rider_id,
      'team_id', result_row.team_id,
      'rider_name_snapshot', result_row.rider_name_snapshot,
      'team_name_snapshot', result_row.team_name_snapshot,
      'elapsed_seconds', result_row.elapsed_seconds,
      'gap_seconds', result_row.gap_seconds,
      'status', result_row.status,
      'simulation_run_id', result_row.simulation_run_id
    )
  into
    v_official_winner
  from public.race_stage_results result_row
  where result_row.stage_id = p_stage_id
    and result_row.rank = 1
  order by result_row.elapsed_seconds nulls last, result_row.id
  limit 1;

  return jsonb_build_object(
    'status', 'source_bundle_ready',
    'bundle_version', 'calibrated_shadow_source_bundle_compact_v2',
    'generated_at', now(),

    'stage_id', p_stage_id,
    'race_id', v_race_id,
    'stage_format', v_stage_format,

    'stage', v_stage,
    'profile_detail', v_profile_detail,

    'teams', v_teams,
    'participants', v_participants,
    'rider_inputs', v_rider_inputs,
    'segments', v_segments,
    'phase_commands', v_phase_commands,
    'phase_command_effects', v_phase_command_effects,

    'processing_preflight', v_processing_preflight,
    'processing_strategy', v_processing_strategy,

    'latest_official_run', v_latest_official_run,
    'official_winner', v_official_winner,
    'official_results', v_official_results,

    'counts', jsonb_build_object(
      'team_rows', v_team_count,
      'accepted_team_rows', v_accepted_team_count,
      'empty_accepted_team_rows', v_empty_accepted_team_count,
      'participant_rider_rows', v_participant_rider_count,
      'rider_input_rows', v_rider_input_count,
      'segment_rows', v_segment_count,
      'phase_command_rows', v_phase_command_count,
      'official_result_rows', v_official_result_count
    ),

    'safety', jsonb_build_object(
      'read_only', true,
      'database_writes_performed', false,
      'typescript_engine_executed', false,
      'official_output_changed', false
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_calibrated_shadow_source_bundle_dev_v1(p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_club_id uuid;

  v_rio_stage_1_id constant uuid :=
    '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid;

  v_japan_hilly_stage_id constant uuid :=
    '3ca7d3dd-6a45-4829-b08e-6b118309fdd8'::uuid;

  v_mentougou_mountain_stage_id constant uuid :=
    '2d33de11-3a34-412a-b90a-847d4839c8d9'::uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception
      'Authentication is required for the calibrated shadow diagnostic.';
  end if;

  select public.get_my_club_id()
  into v_club_id;

  if v_club_id is null then
    raise exception
      'An active club is required for the calibrated shadow diagnostic.';
  end if;

  if p_stage_id is null then
    raise exception
      'p_stage_id must not be null.';
  end if;

  if p_stage_id not in (
    v_rio_stage_1_id,
    v_japan_hilly_stage_id,
    v_mentougou_mountain_stage_id
  ) then
    raise exception
      'This development diagnostic currently allows only Rio Stage 1, Japan Road Cup Stage 1, and Mentougou International Road Race Stage 3.';
  end if;

  return
    public.race_engine_get_calibrated_shadow_source_bundle_v1(
      p_stage_id
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.debit_user_coins_idempotent_v1(p_user_id uuid, p_amount integer, p_reason text, p_system_key text, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_balance integer := 0;
begin
  if p_user_id is null then
    raise exception 'Missing user id.';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Coin debit amount must be positive.';
  end if;

  if nullif(trim(p_reason), '') is null then
    raise exception 'Coin debit reason is required.';
  end if;

  if nullif(trim(p_system_key), '') is null then
    raise exception 'Coin debit system key is required.';
  end if;

  if exists (
    select 1
    from public.user_coin_ledger ledger
    where ledger.user_id = p_user_id
      and ledger.payload_json->>'system_key' = p_system_key
  ) then
    return false;
  end if;

  insert into public.user_wallets (user_id, balance)
  values (p_user_id, 0)
  on conflict (user_id) do nothing;

  select wallet.balance
  into v_balance
  from public.user_wallets wallet
  where wallet.user_id = p_user_id
  for update;

  v_balance := coalesce(v_balance, 0);

  if v_balance < p_amount then
    raise exception
      'Not enough coins. % coins are required; current balance is %.',
      p_amount,
      v_balance;
  end if;

  insert into public.user_coin_ledger (
    user_id,
    delta,
    reason,
    payload_json
  )
  values (
    p_user_id,
    -p_amount,
    p_reason,
    coalesce(p_payload_json, '{}'::jsonb)
      || jsonb_build_object('system_key', p_system_key)
  );

  update public.user_wallets
  set
    balance = balance - p_amount,
    updated_at = now()
  where user_id = p_user_id;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_developing_team_season_renewals_v1(p_target_season integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_target_season integer := coalesce(p_target_season, public.get_current_season_number(), public.get_current_game_season_number_safe_v1(), 1);
  v_cost integer := public.developing_team_renewal_coin_cost_v1();
  v_row record;
  v_balance integer := 0;
  v_system_key text;
  v_renewed integer := 0;
  v_expired_disabled integer := 0;
  v_expired_insufficient integer := 0;
  v_expired_unavailable integer := 0;
  v_already_processed integer := 0;
begin
  if v_target_season <= 0 then
    raise exception 'Target season must be a positive integer.';
  end if;

  -- Removed/ownerless clubs or deleted Developing Teams never renew and never charge coins.
  update public.developing_team_season_access a
  set access_status='expired', updated_at=now()
  where coalesce(a.expires_after_season,0) < v_target_season
    and a.access_status <> 'expired'
    and exists (
      select 1
      from public.clubs m
      left join public.clubs d on d.id=a.developing_club_id
      where m.id=a.main_club_id
        and (m.deleted_at is not null or m.owner_user_id is null or d.id is null or d.deleted_at is not null)
    );
  get diagnostics v_expired_unavailable=row_count;

  update public.developing_team_season_access a
  set access_status='expired', updated_at=now()
  where coalesce(a.expires_after_season,0) < v_target_season
    and a.auto_renew=false
    and a.access_status <> 'expired';
  get diagnostics v_expired_disabled=row_count;

  for v_row in
    select a.main_club_id,a.developing_club_id,m.owner_user_id
    from public.developing_team_season_access a
    join public.clubs m on m.id=a.main_club_id
    join public.clubs d on d.id=a.developing_club_id
    where coalesce(a.expires_after_season,0) < v_target_season
      and a.auto_renew=true
      and m.deleted_at is null
      and m.owner_user_id is not null
      and d.deleted_at is null
    for update of a
  loop
    perform pg_advisory_xact_lock(hashtext('developing_team_renewal:'||v_row.main_club_id::text||':season:'||v_target_season::text));
    if not public.user_has_premium_access_v1(v_row.owner_user_id) then
      update public.developing_team_season_access
      set access_status='expired', auto_renew=false, updated_at=now()
      where main_club_id=v_row.main_club_id;
      v_expired_disabled:=v_expired_disabled+1;
      continue;
    end if;

    v_system_key := 'developing_team_renewal:'||v_row.main_club_id::text||':season:'||v_target_season::text;

    if exists (
      select 1 from public.user_coin_ledger l
      where l.user_id=v_row.owner_user_id and l.payload_json->>'system_key'=v_system_key
    ) then
      update public.developing_team_season_access
      set access_status='active',active_season=v_target_season,expires_after_season=v_target_season,renewed_at=coalesce(renewed_at,now()),updated_at=now()
      where main_club_id=v_row.main_club_id;
      v_already_processed:=v_already_processed+1;
      continue;
    end if;

    insert into public.user_wallets(user_id,balance) values(v_row.owner_user_id,0) on conflict(user_id) do nothing;
    select coalesce(w.balance,0) into v_balance from public.user_wallets w where w.user_id=v_row.owner_user_id for update;

    if v_balance >= v_cost then
      perform public.debit_user_coins_idempotent_v1(
        v_row.owner_user_id,v_cost,'developing_team_season_renewal',v_system_key,
        jsonb_build_object('category','developing_team','main_club_id',v_row.main_club_id,'developing_club_id',v_row.developing_club_id,'season',v_target_season,'auto_renew',true,'coin_cost',v_cost)
      );
      update public.developing_team_season_access
      set access_status='active',active_season=v_target_season,expires_after_season=v_target_season,renewed_at=now(),updated_at=now()
      where main_club_id=v_row.main_club_id;
      v_renewed:=v_renewed+1;
    else
      update public.developing_team_season_access
      set access_status='expired',updated_at=now()
      where main_club_id=v_row.main_club_id;
      v_expired_insufficient:=v_expired_insufficient+1;
    end if;
  end loop;

  return jsonb_build_object('ok',true,'target_season',v_target_season,'renewal_coin_cost',v_cost,'renewed',v_renewed,
    'expired_auto_renew_disabled',v_expired_disabled,'expired_insufficient_balance',v_expired_insufficient,
    'expired_unavailable_club',v_expired_unavailable,'already_processed',v_already_processed);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_developing_team_season_renewals_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
begin
  if new.season_number > old.season_number then
    perform public.process_developing_team_season_renewals_v1(
      new.season_number
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.move_rider_between_main_and_developing(p_rider_id uuid, p_target_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_target_type text;
begin
  select coalesce(c.club_type,'main') into v_target_type from public.clubs c where c.id=p_target_club_id;
  if v_target_type is null then raise exception 'Target club is invalid.'; end if;
  -- Expired service is read-only, but moving riders OUT to the main squad remains allowed in valid windows.
  if v_target_type='developing' and not public.is_developing_team_access_active_v1(p_target_club_id) then
    raise exception 'Developing Team access is expired. Reactivate the service before moving riders into it.';
  end if;
  perform public.move_rider_between_main_and_developing_legacy_v1(p_rider_id,p_target_club_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_developing_team_status_base_v9()
 RETURNS TABLE(main_club_id uuid, main_club_name text, developing_club_id uuid, developing_club_name text, team_exists boolean, access_status text, is_active boolean, is_read_only boolean, current_season integer, active_season integer, expires_after_season integer, next_renewal_season integer, auto_renew boolean, activation_coin_cost integer, renewal_coin_cost integer, coin_balance integer, coin_requirement_met boolean, activation_coin_requirement_met boolean, renewal_coin_requirement_met boolean, real_days_played integer, game_days_played integer, time_requirement_met boolean, can_activate boolean, can_reactivate boolean, can_change_auto_renew boolean, movement_window_open boolean, current_window_label text, next_window_label text, current_competition_name text, current_competition_place integer, current_competition_total_teams integer, is_purchased boolean, coin_cost integer, can_purchase boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_main public.clubs%rowtype;
  v_developing public.clubs%rowtype;
  v_access public.developing_team_season_access%rowtype;

  v_game_date date;
  v_current_season integer := 1;
  v_month integer := 1;
  v_day integer := 1;

  v_real_days integer := 0;
  v_game_days integer := 0;
  v_time_met boolean := false;

  v_balance integer := 0;
  v_activation_cost integer :=
    public.developing_team_activation_coin_cost_v1();
  v_renewal_cost integer :=
    public.developing_team_renewal_coin_cost_v1();

  v_team_exists boolean := false;
  v_effective_status text := 'not_activated';
  v_active boolean := false;
  v_read_only boolean := false;
  v_action_cost integer := 0;

  v_window_open boolean := false;
  v_current_window text := null;
  v_next_window text := null;

  v_competition_name text := null;
  v_competition_place integer := null;
  v_competition_total_teams integer := null;
begin
  if v_user_id is null then
    raise exception
      'You must be signed in to view Developing Team status.';
  end if;

  select main_club.*
  into v_main
  from public.clubs main_club
  where main_club.owner_user_id = v_user_id
    and coalesce(main_club.club_type, 'main') = 'main'
  order by main_club.created_at asc
  limit 1;

  if v_main.id is null then
    return;
  end if;

  v_game_date := public.get_current_game_date_date();

  v_current_season := coalesce(
    public.get_current_season_number(),
    public.get_current_game_season_number_safe_v1(),
    case
      when v_game_date is not null
        then extract(year from v_game_date)::integer - 1999
      else 1
    end,
    1
  );

  if v_game_date is not null then
    v_month := extract(month from v_game_date)::integer;
    v_day := extract(day from v_game_date)::integer;
  end if;

  v_real_days := greatest(0, current_date - v_main.created_at::date);

  if v_game_date is not null
     and v_main.created_game_date is not null then
    v_game_days := greatest(0, v_game_date - v_main.created_game_date);
  end if;

  v_time_met := v_real_days >= 30 or v_game_days >= 60;

  select coalesce(
    (
      select wallet.balance
      from public.user_wallets wallet
      where wallet.user_id = v_user_id
      limit 1
    ),
    0
  )
  into v_balance;

  select developing.*
  into v_developing
  from public.clubs developing
  where developing.parent_club_id = v_main.id
    and developing.club_type = 'developing'
  order by developing.created_at asc
  limit 1;

  v_team_exists := v_developing.id is not null;

  if v_team_exists then
    select access_row.*
    into v_access
    from public.developing_team_season_access access_row
    where access_row.main_club_id = v_main.id
    limit 1;
  end if;

  if not v_team_exists then
    v_effective_status := 'not_activated';
    v_active := false;
    v_read_only := false;
  elsif v_access.main_club_id is null then
    v_effective_status := 'expired';
    v_active := false;
    v_read_only := true;
  elsif v_access.access_status = 'active'
        and coalesce(v_access.active_season, 0) = v_current_season
        and coalesce(v_access.expires_after_season, 0) >= v_current_season then
    v_effective_status := 'active';
    v_active := true;
    v_read_only := false;
  else
    v_effective_status := 'expired';
    v_active := false;
    v_read_only := true;
  end if;

  v_action_cost := case
    when v_effective_status = 'expired' then v_renewal_cost
    else v_activation_cost
  end;

  v_window_open :=
    v_month in (1, 4, 7, 10)
    and v_day between 1 and 14;

  if v_window_open then
    v_current_window := case v_month
      when 1 then 'January 1–14'
      when 4 then 'April 1–14'
      when 7 then 'July 1–14'
      when 10 then 'October 1–14'
    end;
  end if;

  v_next_window := case
    when v_month = 1 and v_day <= 14 then 'January 1–14'
    when v_month < 4 or (v_month = 1 and v_day > 14) then 'April 1–14'
    when v_month = 4 and v_day <= 14 then 'April 1–14'
    when v_month < 7 or (v_month = 4 and v_day > 14) then 'July 1–14'
    when v_month = 7 and v_day <= 14 then 'July 1–14'
    when v_month < 10 or (v_month = 7 and v_day > 14) then 'October 1–14'
    when v_month = 10 and v_day <= 14 then 'October 1–14'
    else format('Season %s · January 1–14', v_current_season + 1)
  end;

  /*
    Competition ranking is intentionally loaded through the separate
    get_club_current_ranking_position_v1() RPC. Keeping it out of this
    access/status RPC prevents ranking work from locking Squad navigation.
  */

  return query
  select
    v_main.id,
    v_main.name,
    v_developing.id,
    v_developing.name,

    v_team_exists,
    v_effective_status,
    v_active,
    v_read_only,

    v_current_season,
    v_access.active_season,
    v_access.expires_after_season,
    v_current_season + 1,

    coalesce(v_access.auto_renew, false),
    v_activation_cost,
    v_renewal_cost,

    v_balance,
    v_balance >= v_action_cost,
    v_balance >= v_activation_cost,
    v_balance >= v_renewal_cost,

    v_real_days,
    v_game_days,
    v_time_met,

    (
      not v_team_exists
      and v_time_met
      and v_balance >= v_activation_cost
    ),
    (
      v_team_exists
      and not v_active
      and v_time_met
      and v_balance >= v_renewal_cost
    ),
    (v_team_exists and v_active),

    v_window_open,
    v_current_window,
    v_next_window,

    v_competition_name,
    v_competition_place,
    v_competition_total_teams,

    v_team_exists,
    v_action_cost,
    (
      not v_team_exists
      and v_time_met
      and v_balance >= v_activation_cost
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_developing_team_for_season_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status record;
  v_created record;
  v_result jsonb;
  v_cost integer;
  v_system_key text;
  v_developing_club_id uuid;
begin
  if v_user_id is null then
    raise exception
      'You must be signed in to activate a Developing Team.';
  end if;

  if not public.current_user_has_premium_v1() then
    raise exception 'Developing Team is a Premium-only feature. Activate Premium before creating or reactivating the U23 team.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('developing_team_activation:' || v_user_id::text)
  );

  select *
  into v_status
  from public.get_developing_team_status()
  limit 1;

  if v_status.main_club_id is null then
    raise exception 'No main club found for current user.';
  end if;

  if v_status.is_active then
    select to_jsonb(current_status)
    into v_result
    from public.get_developing_team_status() current_status
    limit 1;

    return v_result;
  end if;

  if not v_status.time_requirement_met then
    raise exception
      'Developing Team requires 30 real-life days or 60 in-game days.';
  end if;

  if not v_status.team_exists then
    v_cost := v_status.activation_coin_cost;

    if v_status.coin_balance < v_cost then
      raise exception
        'Not enough coins. % coins are required; current balance is %.',
        v_cost,
        v_status.coin_balance;
    end if;

    /* Existing production creation/seed function, now configured at 200. */
    select *
    into v_created
    from public.create_developing_team_and_charge_activation_v1()
    limit 1;

    v_developing_club_id := v_created.developing_club_id;
  else
    v_cost := v_status.renewal_coin_cost;
    v_system_key :=
      'developing_team_reactivation:'
      || v_status.main_club_id::text
      || ':season:'
      || v_status.current_season::text;

    perform public.debit_user_coins_idempotent_v1(
      v_user_id,
      v_cost,
      'developing_team_season_reactivation',
      v_system_key,
      jsonb_build_object(
        'category', 'developing_team',
        'main_club_id', v_status.main_club_id,
        'developing_club_id', v_status.developing_club_id,
        'season', v_status.current_season,
        'auto_renew', true,
        'coin_cost', v_cost
      )
    );

    v_developing_club_id := v_status.developing_club_id;
  end if;

  insert into public.developing_team_season_access (
    main_club_id,
    developing_club_id,
    access_status,
    active_season,
    expires_after_season,
    auto_renew,
    activated_at,
    renewed_at,
    updated_at
  )
  values (
    v_status.main_club_id,
    v_developing_club_id,
    'active',
    v_status.current_season,
    v_status.current_season,
    true,
    now(),
    case when v_status.team_exists then now() else null end,
    now()
  )
  on conflict (main_club_id)
  do update set
    developing_club_id = excluded.developing_club_id,
    access_status = 'active',
    active_season = excluded.active_season,
    expires_after_season = excluded.expires_after_season,
    auto_renew = true,
    activated_at = coalesce(
      public.developing_team_season_access.activated_at,
      excluded.activated_at
    ),
    renewed_at = case
      when public.developing_team_season_access.active_season
        is distinct from excluded.active_season
        then now()
      else public.developing_team_season_access.renewed_at
    end,
    updated_at = now();

  select to_jsonb(final_status)
  into v_result
  from public.get_developing_team_status() final_status
  limit 1;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_developing_team_auto_renew_v1(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status record;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception
      'You must be signed in to change Developing Team renewal.';
  end if;

  if not public.current_user_has_premium_v1() then
    raise exception 'Premium membership is required to manage Developing Team renewal.';
  end if;

  if p_enabled is null then
    raise exception 'Automatic-renewal value is required.';
  end if;

  select *
  into v_status
  from public.get_developing_team_status()
  limit 1;

  if not coalesce(v_status.team_exists, false) then
    raise exception 'Developing Team does not exist yet.';
  end if;

  if not coalesce(v_status.is_active, false) then
    raise exception
      'Reactivate the Developing Team before changing automatic renewal.';
  end if;

  update public.developing_team_season_access access_row
  set
    auto_renew = p_enabled,
    updated_at = now()
  where access_row.main_club_id = v_status.main_club_id;

  select to_jsonb(final_status)
  into v_result
  from public.get_developing_team_status() final_status
  limit 1;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.purchase_developing_team()
 RETURNS TABLE(developing_club_id uuid, developing_club_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  v_result := public.activate_developing_team_for_season_v1();

  return query
  select
    nullif(v_result->>'developing_club_id', '')::uuid,
    v_result->>'developing_club_name';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_owned_rider_image_with_coins_v1(p_rider_id uuid, p_image_url text)
 RETURNS TABLE(rider_id uuid, image_url text, coins_charged integer, balance_after integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_main_club_id uuid;
  v_wallet_balance integer;
  v_cost constant integer := 2;
  v_normalized_url text;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  v_normalized_url := btrim(coalesce(p_image_url, ''));

  if v_normalized_url = ''
     or v_normalized_url !~* '^https?://'
     or length(v_normalized_url) > 2000 then
    raise exception 'A valid http or https image URL is required';
  end if;

  v_main_club_id := public.get_current_main_club_id();

  if v_main_club_id is null then
    raise exception 'No main club found for current user';
  end if;

  if not exists (
    select 1
    from public.club_roster cr
    where cr.rider_id = p_rider_id
      and cr.club_id in (
        select family.club_id
        from public.get_club_family_ids(v_main_club_id) family
      )
  ) then
    raise exception 'You can only change images for riders in your own club';
  end if;

  select uw.balance
  into v_wallet_balance
  from public.user_wallets uw
  where uw.user_id = v_user_id
  for update;

  if v_wallet_balance is null then
    raise exception 'Coin wallet not found';
  end if;

  if v_wallet_balance < v_cost then
    raise exception 'You need 2 coins to change this rider image';
  end if;

  update public.user_wallets
  set balance = balance - v_cost
  where user_id = v_user_id
  returning balance into v_wallet_balance;

  update public.riders
  set image_url = v_normalized_url
  where id = p_rider_id;

  if not found then
    raise exception 'Rider not found';
  end if;

  insert into public.user_coin_ledger (
    user_id,
    delta,
    reason,
    payload_json
  )
  values (
    v_user_id,
    -v_cost,
    'rider_image_change',
    jsonb_build_object(
      'category', 'rider_image_change',
      'rider_id', p_rider_id,
      'image_url', v_normalized_url,
      'coins_charged', v_cost
    )
  );

  return query
  select p_rider_id, v_normalized_url, v_cost, v_wallet_balance;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_rider_performance_analysis_v1(p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_main_club_id uuid;
  v_rider public.riders%rowtype;
  v_is_premium boolean := false;
  v_age integer;
  v_stage text;
  v_strengths jsonb;
  v_weaknesses jsonb;
  v_roles jsonb;
  v_race_suitability jsonb;
  v_training_focus text;
  v_training_reason text;
  v_coach_note text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select coalesce(status_row.is_premium, false)
  into v_is_premium
  from public.get_my_premium_status() status_row
  limit 1;

  if not coalesce(v_is_premium, false) then
    raise exception 'Premium membership required';
  end if;

  v_main_club_id := public.get_current_main_club_id();

  if v_main_club_id is null then
    raise exception 'No main club found for current user';
  end if;

  if not exists (
    select 1
    from public.club_roster cr
    where cr.rider_id = p_rider_id
      and cr.club_id in (
        select family.club_id
        from public.get_club_family_ids(v_main_club_id) family
      )
  ) then
    raise exception 'Performance Analysis is available only for riders in your own club';
  end if;

  select *
  into v_rider
  from public.riders
  where id = p_rider_id;

  if not found then
    raise exception 'Rider not found';
  end if;

  v_age :=
    case
      when v_rider.birth_date is null then null
      else extract(year from age(current_date, v_rider.birth_date))::integer
    end;

  v_stage :=
    case
      when v_age is null then 'stable'
      when v_age <= 23 and coalesce(v_rider.potential, 0) > coalesce(v_rider.overall, 0) then 'developing'
      when v_age <= 28 and coalesce(v_rider.potential, 0) > coalesce(v_rider.overall, 0) then 'improving'
      when v_age >= 35 then 'declining'
      when v_age >= 31 then 'near_peak'
      else 'stable'
    end;

  with skills as (
    select *
    from (
      values
        ('sprint', 'Sprint', coalesce(v_rider.sprint, 0)),
        ('climbing', 'Climbing', coalesce(v_rider.climbing, 0)),
        ('time_trial', 'Time Trial', coalesce(v_rider.time_trial, 0)),
        ('endurance', 'Endurance', coalesce(v_rider.endurance, 0)),
        ('flat', 'Flat', coalesce(v_rider.flat, 0)),
        ('recovery', 'Recovery', coalesce(v_rider.recovery, 0)),
        ('resistance', 'Resistance', coalesce(v_rider.resistance, 0)),
        ('race_iq', 'Race IQ', coalesce(v_rider.race_iq, 0)),
        ('teamwork', 'Teamwork', coalesce(v_rider.teamwork, 0))
    ) skill_rows(key, label, value)
  )
  select
    (
      select jsonb_agg(jsonb_build_object('key', key, 'label', label, 'value', value))
      from (select * from skills order by value desc, label limit 3) strongest
    ),
    (
      select jsonb_agg(jsonb_build_object('key', key, 'label', label, 'value', value))
      from (select * from skills order by value asc, label limit 3) weakest
    )
  into v_strengths, v_weaknesses;

  v_roles := jsonb_build_array(
    jsonb_build_object(
      'role', 'GC Leader',
      'score', round((
        coalesce(v_rider.climbing, 0) * 0.30 +
        coalesce(v_rider.endurance, 0) * 0.25 +
        coalesce(v_rider.recovery, 0) * 0.20 +
        coalesce(v_rider.time_trial, 0) * 0.15 +
        coalesce(v_rider.race_iq, 0) * 0.10
      )::numeric)
    ),
    jsonb_build_object(
      'role', 'Breakaway Rider',
      'score', round((
        coalesce(v_rider.endurance, 0) * 0.30 +
        coalesce(v_rider.resistance, 0) * 0.25 +
        coalesce(v_rider.race_iq, 0) * 0.20 +
        coalesce(v_rider.flat, 0) * 0.15 +
        coalesce(v_rider.climbing, 0) * 0.10
      )::numeric)
    ),
    jsonb_build_object(
      'role', 'Climbing Domestique',
      'score', round((
        coalesce(v_rider.climbing, 0) * 0.35 +
        coalesce(v_rider.teamwork, 0) * 0.25 +
        coalesce(v_rider.endurance, 0) * 0.20 +
        coalesce(v_rider.recovery, 0) * 0.20
      )::numeric)
    )
  );

  v_race_suitability := jsonb_build_array(
    jsonb_build_object(
      'race_type', 'Mountain',
      'score', round((coalesce(v_rider.climbing, 0) * 0.60 + coalesce(v_rider.endurance, 0) * 0.40)::numeric),
      'rating', case when coalesce(v_rider.climbing, 0) >= 80 then 'Elite' when coalesce(v_rider.climbing, 0) >= 70 then 'Strong' else 'Developing' end
    ),
    jsonb_build_object(
      'race_type', 'Flat',
      'score', round((coalesce(v_rider.flat, 0) * 0.55 + coalesce(v_rider.sprint, 0) * 0.45)::numeric),
      'rating', case when coalesce(v_rider.flat, 0) >= 80 then 'Elite' when coalesce(v_rider.flat, 0) >= 70 then 'Strong' else 'Developing' end
    ),
    jsonb_build_object(
      'race_type', 'Time Trial',
      'score', round((coalesce(v_rider.time_trial, 0) * 0.70 + coalesce(v_rider.resistance, 0) * 0.30)::numeric),
      'rating', case when coalesce(v_rider.time_trial, 0) >= 80 then 'Elite' when coalesce(v_rider.time_trial, 0) >= 70 then 'Strong' else 'Developing' end
    )
  );

  select skill_key, reason
  into v_training_focus, v_training_reason
  from (
    values
      ('sprint', coalesce(v_rider.sprint, 0), 'Sprint is currently one of the clearest development opportunities.'),
      ('climbing', coalesce(v_rider.climbing, 0), 'Climbing work would improve mountain-stage suitability.'),
      ('time_trial', coalesce(v_rider.time_trial, 0), 'Time-trial work would improve solo performance and GC resilience.'),
      ('endurance', coalesce(v_rider.endurance, 0), 'Endurance work would support longer races and stage consistency.'),
      ('recovery', coalesce(v_rider.recovery, 0), 'Recovery work would improve repeat performance across stage races.')
  ) focus_options(skill_key, skill_value, reason)
  order by skill_value asc
  limit 1;

  v_coach_note :=
    case
      when v_stage = 'developing' then 'This rider still has meaningful development room. Keep training consistent and avoid excessive fatigue.'
      when v_stage = 'improving' then 'The rider is in a productive development window and should benefit from focused training.'
      when v_stage = 'near_peak' then 'The rider is close to peak age. Prioritise race-specific preparation and role clarity.'
      when v_stage = 'declining' then 'Manage workload carefully and use the rider in roles that maximise current strengths.'
      else 'The rider is stable. Use targeted training to address the weakest relevant attribute.'
    end;

  return jsonb_build_object(
    'rider_id', p_rider_id,
    'generated_at', now(),
    'development_stage', v_stage,
    'recommended_roles', v_roles,
    'race_suitability', v_race_suitability,
    'strengths', coalesce(v_strengths, '[]'::jsonb),
    'weaknesses', coalesce(v_weaknesses, '[]'::jsonb),
    'training_recommendation', jsonb_build_object(
      'focus', v_training_focus,
      'intensity', case when coalesce(v_rider.fatigue, 0) >= 65 then 'light' else 'normal' end,
      'reason', v_training_reason
    ),
    'performance_trend', jsonb_build_object(
      'direction', 'stable',
      'recent_races_used', 0
    ),
    'coach_note', v_coach_note
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.record_rider_skill_weekly_snapshots_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_week_start date :=
    date_trunc('week', current_date)::date;
  v_inserted integer := 0;
begin
  insert into public.rider_skill_weekly_snapshots (
    rider_id,
    week_start_date,
    sprint,
    climbing,
    time_trial,
    endurance,
    flat,
    recovery,
    resistance,
    race_iq,
    teamwork,
    recorded_at
  )
  select
    r.id,
    v_week_start,
    coalesce(r.sprint, 0),
    coalesce(r.climbing, 0),
    coalesce(r.time_trial, 0),
    coalesce(r.endurance, 0),
    coalesce(r.flat, 0),
    coalesce(r.recovery, 0),
    coalesce(r.resistance, 0),
    coalesce(r.race_iq, 0),
    coalesce(r.teamwork, 0),
    now()
  from public.riders r
  on conflict (rider_id, week_start_date)
  do update
  set
    sprint = excluded.sprint,
    climbing = excluded.climbing,
    time_trial = excluded.time_trial,
    endurance = excluded.endurance,
    flat = excluded.flat,
    recovery = excluded.recovery,
    resistance = excluded.resistance,
    race_iq = excluded.race_iq,
    teamwork = excluded.teamwork,
    recorded_at = now();

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rider_last_12_month_points_v1(p_rider_id uuid, p_game_date date DEFAULT NULL::date)
 RETURNS TABLE(month_start date, month_label text, international_points integer, sprint_points integer, climb_points integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_main_club_id uuid;
  v_is_premium boolean := false;
  v_game_date date := coalesce(p_game_date, current_date);
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select coalesce(status_row.is_premium, false)
  into v_is_premium
  from public.get_my_premium_status() status_row
  limit 1;

  if not v_is_premium then
    raise exception 'Premium membership required';
  end if;

  v_main_club_id := public.get_current_main_club_id();

  if not exists (
    select 1
    from public.club_roster cr
    where cr.rider_id = p_rider_id
      and cr.club_id in (
        select family.club_id
        from public.get_club_family_ids(v_main_club_id) family
      )
  ) then
    raise exception 'Point history is available only for owned riders';
  end if;

  return query
  with month_axis as (
    select generate_series(
      date_trunc('month', v_game_date)::date - interval '11 months',
      date_trunc('month', v_game_date)::date,
      interval '1 month'
    )::date as month_start
  ),
  raw_results as (
    select to_jsonb(result_row) as payload
    from public.get_rider_last_five_races(p_rider_id, 1000) result_row
  ),
  normalized as (
    select
      coalesce(
        nullif(payload ->> 'race_end_date', '')::date,
        nullif(payload ->> 'end_date', '')::date,
        nullif(payload ->> 'race_start_date', '')::date,
        nullif(payload ->> 'start_date', '')::date,
        nullif(payload ->> 'race_date', '')::date,
        nullif(payload ->> 'event_date', '')::date,
        nullif(payload ->> 'date', '')::date
      ) as result_date,
      coalesce(
        nullif(payload ->> 'international_points', '')::numeric,
        nullif(payload ->> 'ci_points', '')::numeric,
        nullif(payload ->> 'rider_points', '')::numeric,
        nullif(payload ->> 'ranking_points', '')::numeric,
        nullif(payload ->> 'classification_points', '')::numeric,
        nullif(payload ->> 'points', '')::numeric,
        0
      ) as international_points,
      coalesce(
        nullif(payload ->> 'sprint_points', '')::numeric,
        nullif(payload ->> 'points_sprint', '')::numeric,
        nullif(payload ->> 'sprint_classification_points', '')::numeric,
        0
      ) as sprint_points,
      coalesce(
        nullif(payload ->> 'climb_points', '')::numeric,
        nullif(payload ->> 'climbing_points', '')::numeric,
        nullif(payload ->> 'points_climb', '')::numeric,
        nullif(payload ->> 'kom_points', '')::numeric,
        nullif(payload ->> 'mountain_points', '')::numeric,
        0
      ) as climb_points
    from raw_results
  ),
  grouped as (
    select
      date_trunc('month', result_date)::date as month_start,
      round(sum(international_points))::integer as international_points,
      round(sum(sprint_points))::integer as sprint_points,
      round(sum(climb_points))::integer as climb_points
    from normalized
    where result_date >= date_trunc('month', v_game_date)::date - interval '11 months'
      and result_date < date_trunc('month', v_game_date)::date + interval '1 month'
    group by 1
  )
  select
    axis.month_start,
    to_char(axis.month_start, 'Mon YY'),
    coalesce(grouped.international_points, 0),
    coalesce(grouped.sprint_points, 0),
    coalesce(grouped.climb_points, 0)
  from month_axis axis
  left join grouped using (month_start)
  order by axis.month_start;
end;
$function$
;

