CREATE OR REPLACE FUNCTION public.record_single_rider_skill_snapshot_v1(p_rider_id uuid, p_game_date date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_date date;
  v_game_week date;
begin
  v_game_date := coalesce(
    p_game_date,
    public.get_current_game_date_date()
  );

  if v_game_date is null then
    raise exception
      'record_single_rider_skill_snapshot_v1: current in-game date is unavailable';
  end if;

  v_game_week := date_trunc('week', v_game_date)::date;

  insert into public.rider_skill_weekly_snapshots (
    rider_id,
    week_start_date,
    sprint,
    climbing,
    time_trial,
    endurance,
    flat,
    recovery,
    resistance,
    race_iq,
    teamwork,
    recorded_at
  )
  select
    r.id,
    v_game_week,
    greatest(0, least(100, coalesce(r.sprint, 0)))::integer,
    greatest(0, least(100, coalesce(r.climbing, 0)))::integer,
    greatest(0, least(100, coalesce(r.time_trial, 0)))::integer,
    greatest(0, least(100, coalesce(r.endurance, 0)))::integer,
    greatest(0, least(100, coalesce(r.flat, 0)))::integer,
    greatest(0, least(100, coalesce(r.recovery, 0)))::integer,
    greatest(0, least(100, coalesce(r.resistance, 0)))::integer,
    greatest(0, least(100, coalesce(r.race_iq, 0)))::integer,
    greatest(0, least(100, coalesce(r.teamwork, 0)))::integer,
    now()
  from public.riders r
  where r.id = p_rider_id
  on conflict (rider_id, week_start_date)
  do update
  set
    sprint = excluded.sprint,
    climbing = excluded.climbing,
    time_trial = excluded.time_trial,
    endurance = excluded.endurance,
    flat = excluded.flat,
    recovery = excluded.recovery,
    resistance = excluded.resistance,
    race_iq = excluded.race_iq,
    teamwork = excluded.teamwork,
    recorded_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_record_rider_skill_snapshot_v1()
 RETURNS trigger
 LANGUAGE plpgsql
