CREATE OR REPLACE FUNCTION public.get_rider_skill_progress_history_v1(p_rider_id uuid, p_weeks integer DEFAULT 60, p_game_date date DEFAULT NULL::date)
 RETURNS TABLE(week_start_date date, week_label text, sprint integer, climbing integer, time_trial integer, endurance integer, flat integer, recovery integer, resistance integer, race_iq integer, teamwork integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_main_club_id uuid;
  v_is_premium boolean := false;
  v_game_date date;
  v_game_week date;
  v_limit integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select coalesce(status_row.is_premium, false)
  into v_is_premium
  from public.get_my_premium_status() status_row
  limit 1;

  if not v_is_premium then
    raise exception 'Premium membership required';
  end if;

  v_main_club_id := public.get_current_main_club_id();

  if v_main_club_id is null then
    raise exception 'No main club found for current user';
  end if;

  if not exists (
    select 1
    from public.club_roster cr
    where cr.rider_id = p_rider_id
      and cr.club_id in (
        select family.club_id
        from public.get_club_family_ids(v_main_club_id) family
      )
  ) then
    raise exception
      'Skill history is available only for riders in your own club';
  end if;

  v_game_date := coalesce(
    p_game_date,
    public.get_current_game_date_date()
  );

  if v_game_date is null then
    raise exception 'Current in-game date is unavailable';
  end if;

  v_game_week := date_trunc('week', v_game_date)::date;
  v_limit := least(greatest(coalesce(p_weeks, 60), 1), 60);

  return query
  select
    snapshot.week_start_date,
    to_char(snapshot.week_start_date, 'DD Mon') as week_label,
    snapshot.sprint,
    snapshot.climbing,
    snapshot.time_trial,
    snapshot.endurance,
    snapshot.flat,
    snapshot.recovery,
    snapshot.resistance,
    snapshot.race_iq,
    snapshot.teamwork
  from public.rider_skill_weekly_snapshots snapshot
  where snapshot.rider_id = p_rider_id
    and snapshot.week_start_date <= v_game_week
    and snapshot.week_start_date >=
      v_game_week - ((v_limit - 1) * interval '7 days')
  order by snapshot.week_start_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_external_rider_last_five_races_premium_v1(p_rider_id uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.current_user_has_premium_v1() then
    raise exception 'Premium membership required';
  end if;

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_result
  from public.get_rider_last_five_races(
    p_rider_id,
    least(greatest(coalesce(p_limit, 5), 1), 5)
  ) r;

  return coalesce(v_result, '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_external_rider_career_history_premium_v1(p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not public.current_user_has_premium_v1() then
    raise exception 'Premium membership required';
  end if;

  select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb)
  into v_result
  from public.get_rider_career_history(p_rider_id) r;

  return coalesce(v_result, '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.quote_unsolicited_ai_transfer_bid_v2(p_rider_id uuid, p_buyer_club_id uuid, p_offer_amount_cash numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_third_type text;
  v_available_signatures text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  /*
   * Find the installed three-argument v1 overload:
   *   uuid, uuid, <money type>
   *
   * PostgreSQL considers numeric, bigint and integer different signatures.
   * The previous wrapper called numeric directly, while the installed
   * production function uses another numeric type.
   */
  select format_type(p.proargtypes[2], null)
  into v_third_type
  from pg_proc p
  join pg_namespace n
    on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'quote_unsolicited_ai_transfer_bid_v1'
    and p.pronargs = 3
    and format_type(p.proargtypes[0], null) = 'uuid'
    and format_type(p.proargtypes[1], null) = 'uuid'
    and format_type(p.proargtypes[2], null) in (
      'smallint',
      'integer',
      'bigint',
      'numeric',
      'real',
      'double precision'
    )
  order by
    case format_type(p.proargtypes[2], null)
      when 'numeric' then 1
      when 'bigint' then 2
      when 'integer' then 3
      when 'smallint' then 4
      when 'double precision' then 5
      when 'real' then 6
      else 99
    end
  limit 1;

  if v_third_type is null then
    select string_agg(
      p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')',
      E'\n'
      order by p.oid
    )
    into v_available_signatures
    from pg_proc p
    join pg_namespace n
      on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = 'quote_unsolicited_ai_transfer_bid_v1';

    raise exception
      'No supported three-argument quote_unsolicited_ai_transfer_bid_v1 overload was found. Available signatures: %',
      coalesce(v_available_signatures, 'none');
  end if;

  execute format(
    'select to_jsonb(public.quote_unsolicited_ai_transfer_bid_v1($1, $2, $3::%s))',
    v_third_type
  )
  into v_result
  using
    p_rider_id,
    p_buyer_club_id,
    p_offer_amount_cash;

  v_result := coalesce(v_result, '{}'::jsonb);

  -- Premium users receive the complete negotiation analysis.
  if public.current_user_has_premium_v1() then
    return v_result;
  end if;

  -- Free users can still submit an offer, but do not receive predictive data.
  return v_result
    - 'selling_club_stance'
    - 'offer_strength'
    - 'predicted_public_outcome'
    - 'counteroffer_amount_cash'
    - 'reasons'
    - 'ai_counter'
    - 'ai_decision'
    - 'decision_score';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.health_sync_case_fatigue_floor_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_base_floor integer;
  v_staff_reduction integer;
  v_infrastructure_reduction integer;
  v_final_floor integer;
begin
  v_base_floor :=
    case lower(coalesce(new.severity, 'moderate'))
      when 'minor' then 45
      when 'moderate' then 60
      when 'major' then 75
      else 60
    end;

  v_staff_reduction := coalesce(
    nullif(new.notes #>> '{calculation,medical_staff,fatigue_floor_reduction}', '')::integer,
    0
  );

  v_infrastructure_reduction := coalesce(
    nullif(new.notes #>> '{calculation,infrastructure_fatigue_floor_reduction}', '')::integer,
    0
  );

  v_final_floor := greatest(
    0,
    least(100, v_base_floor - v_staff_reduction - v_infrastructure_reduction)
  );

  update public.rider_health_cases hc
  set fatigue_floor_on_return = v_final_floor::smallint
  where hc.id = new.health_case_id
    and coalesce(hc.fatigue_floor_on_return, 0) = 0;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assert_rider_race_selectable_v1(p_rider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status text;
  v_case_id uuid;
  v_case_code text;
begin
  if p_rider_id is null then raise exception 'Rider ID is required'; end if;

  select lower(coalesce(r.availability_status::text,'fit'))
  into v_status
  from public.riders r
  where r.id=p_rider_id;

  if not found then raise exception 'Unknown rider: %',p_rider_id; end if;

  if v_status in ('retired','injured','sick') then
    raise exception 'Rider % cannot be selected because availability status is %',p_rider_id,v_status using errcode='P0001';
  end if;

  select hc.id,hc.case_code into v_case_id,v_case_code
  from public.rider_health_cases hc
  where hc.rider_id=p_rider_id
    and hc.status in ('active','recovering')
    and hc.selection_blocked is true
  order by hc.created_at desc limit 1;

  if v_case_id is not null then
    raise exception 'Rider % cannot be selected because health case % (%) blocks race selection',p_rider_id,v_case_id,coalesce(v_case_code,'unknown') using errcode='P0001';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_race_preparation_rider_health_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_race_date date;
  v_is_national_championship boolean := false;
begin
  select
    coalesce(rp.participating_club_id,rp.club_id),
    r.start_date,
    coalesce((rp.metadata->>'national_championship')::boolean,false)
  into v_club_id,v_race_date,v_is_national_championship
  from public.race_preparations rp
  join public.races r on r.id=rp.race_id
  where rp.id=new.race_preparation_id;

  if v_is_national_championship then
    if not public.national_championship_rider_available_for_event_v1(
      new.rider_id,
      v_race_date
    ) then
      raise exception
        'Rider % cannot be selected for National Championship on % because the rider is unavailable on the event date',
        new.rider_id,
        v_race_date
        using errcode='P0001';
    end if;
  else
    perform public.assert_rider_race_selectable_v1(new.rider_id);
  end if;

  if v_club_id is not null then
    perform public.assert_developing_rider_race_eligibility_v1(
      new.rider_id,
      v_club_id,
      v_race_date
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_race_participant_rider_health_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_race_date date;
  v_is_national_championship boolean := false;
begin
  select
    r.start_date,
    coalesce((r.metadata->>'national_championship')::boolean,false)
  into
    v_race_date,
    v_is_national_championship
  from public.races r
  where r.id=new.race_id;

  if coalesce(v_is_national_championship,false) then
    if not public.national_championship_rider_available_for_event_v1(
      new.rider_id,
      v_race_date
    ) then
      raise exception
        'Rider % cannot be selected for National Championship on % because the rider is unavailable on the event date',
        new.rider_id,
        v_race_date
        using errcode='P0001';
    end if;
  else
    perform public.assert_rider_race_selectable_v1(new.rider_id);
    perform public.assert_developing_rider_race_eligibility_v1(
      new.rider_id,
      new.team_id,
      v_race_date
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rider_profile_health_v1(p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_my_club_id uuid;
  v_owner_club_id uuid;
  v_rider record;
  v_health record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_rider_id is null then
    raise exception 'Rider id is required';
  end if;

  v_my_club_id := public.get_my_primary_club_id();

  if v_my_club_id is null then
    raise exception 'No primary club found';
  end if;

  select cr.club_id
  into v_owner_club_id
  from public.club_riders cr
  where cr.rider_id = p_rider_id
  order by cr.created_at desc nulls last
  limit 1;

  if v_owner_club_id is distinct from v_my_club_id then
    raise exception 'Health details are available only for your own riders';
  end if;

  select
    r.id,
    r.availability_status,
    r.fatigue,
    r.unavailable_until,
    r.unavailable_reason
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if not found then
    raise exception 'Rider not found: %', p_rider_id;
  end if;

  select
    hc.id as health_case_id,
    hc.case_type,
    hc.case_code,
    hc.severity,
    hc.source,
    hc.status as case_status,
    hc.started_on,
    hc.active_until,
    hc.recovery_until,
    hc.resolved_on,
    hc.selection_blocked,
    hc.training_blocked,
    hc.development_blocked,
    hc.fatigue_floor_on_return,

    ctx.source_type,
    ctx.source_id,
    ctx.body_part,
    ctx.base_min_days,
    ctx.base_max_days,
    ctx.selected_base_days,
    ctx.medical_staff_reduction_pct,
    ctx.infrastructure_reduction_pct,
    ctx.total_reduction_pct,
    ctx.final_recovery_days,
    ctx.expected_full_recovery_on,
    ctx.notes
  into v_health
  from public.rider_health_cases hc
  left join public.rider_health_case_context_v1 ctx
    on ctx.health_case_id = hc.id
  where hc.rider_id = p_rider_id
    and hc.status in ('active', 'recovering')
  order by hc.created_at desc
  limit 1;

  return jsonb_build_object(
    'riderId', v_rider.id,

    'availability', jsonb_build_object(
      'status', v_rider.availability_status,
      'fatigue', v_rider.fatigue,
      'unavailableUntil', v_rider.unavailable_until,
      'reason', v_rider.unavailable_reason
    ),

    'hasOpenHealthCase', v_health.health_case_id is not null,

    'healthCase',
    case
      when v_health.health_case_id is null then null
      else jsonb_build_object(
        'id', v_health.health_case_id,
        'caseType', v_health.case_type,
        'caseCode', v_health.case_code,
        'severity', v_health.severity,
        'source', v_health.source,
        'sourceType', v_health.source_type,
        'sourceId', v_health.source_id,
        'status', v_health.case_status,
        'bodyPart', v_health.body_part,

        'startedOn', v_health.started_on,
        'activeUntil', v_health.active_until,
        'recoveryUntil', v_health.recovery_until,
        'resolvedOn', v_health.resolved_on,
        'expectedFullRecoveryOn',
          v_health.expected_full_recovery_on,

        'selectionBlocked', v_health.selection_blocked,
        'trainingBlocked', v_health.training_blocked,
        'developmentBlocked', v_health.development_blocked,

        'fatigueFloorOnReturn',
          v_health.fatigue_floor_on_return,

        'recoveryCalculation', jsonb_build_object(
          'baseMinDays', v_health.base_min_days,
          'baseMaxDays', v_health.base_max_days,
          'selectedBaseDays', v_health.selected_base_days,
          'medicalStaffReductionPct',
            v_health.medical_staff_reduction_pct,
          'infrastructureReductionPct',
            v_health.infrastructure_reduction_pct,
          'totalReductionPct',
            v_health.total_reduction_pct,
          'finalRecoveryDays',
            v_health.final_recovery_days
        ),

        'notes', coalesce(v_health.notes, '{}'::jsonb)
      )
    end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_training_accidents_v1(p_processed_date date DEFAULT NULL::date, p_force_rider_id uuid DEFAULT NULL::uuid, p_force_severity text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$declare
  v_current_game_date date;
  v_processed_date date;

  a record;

  v_club_id uuid;
  v_intensity text;
  v_weather_state text;
  v_fatigue integer;

  v_base_risk numeric;
  v_fatigue_multiplier numeric;
  v_weather_multiplier numeric;
  v_medical_risk_reduction_pct numeric;
  v_final_risk numeric;
  v_risk_roll numeric;

  v_severity_roll numeric;
  v_case_roll numeric;
  v_severity text;
  v_case_code text;
  v_body_part text;

  v_calc jsonb;
  v_result jsonb;
  v_health_case_id uuid;

  v_checked integer := 0;
  v_no_accident integer := 0;
  v_accidents_created integer := 0;
  v_skipped_open_case integer := 0;
  v_skipped_other integer := 0;
  v_failed integer := 0;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception
      'process_daily_training_accidents_v1: could not resolve current game date';
  end if;

  v_processed_date := coalesce(
    p_processed_date,
    (v_current_game_date - interval '1 day')::date
  );

  if p_force_severity is not null
     and lower(p_force_severity) not in ('minor', 'moderate', 'major')
  then
    raise exception
      'Invalid forced severity %. Expected minor, moderate or major.',
      p_force_severity;
  end if;

  for a in
    select
      act.rider_id,
      act.activity_date,
      act.participated,
      act.source,
      act.activity_type,
      act.intensity,
      act.fatigue_load,
      act.metadata,
      r.availability_status,
      coalesce(r.fatigue, 0) as current_fatigue
    from public.rider_daily_activity act
    join public.riders r
      on r.id = act.rider_id
    where act.activity_date = v_processed_date
      and act.source = 'regular_training'
      and (
        p_force_rider_id is null
        or act.rider_id = p_force_rider_id
      )
    order by act.rider_id
  loop
    -- The unique decision row makes the processor idempotent.
    if exists (
      select 1
      from public.rider_training_accident_decisions_v1 d
      where d.rider_id = a.rider_id
        and d.activity_date = v_processed_date
    ) then
      continue;
    end if;

    v_checked := v_checked + 1;

    select cr.club_id
    into v_club_id
    from public.club_riders cr
    where cr.rider_id = a.rider_id
    order by cr.created_at desc nulls last
    limit 1;

    v_intensity := lower(coalesce(a.intensity, 'normal'));
    v_weather_state := lower(
      coalesce(a.metadata->>'weather_state', 'normal')
    );

    v_fatigue := greatest(
      0,
      least(
        100,
        coalesce(
          nullif(a.metadata->>'fatigue_snapshot', '')::integer,
          a.current_fatigue,
          0
        )
      )
    );

    if coalesce(a.participated, false) is not true
       or a.activity_type <> 'training'
       or coalesce((a.metadata->>'is_day_off')::boolean, false) is true
    then
      insert into public.rider_training_accident_decisions_v1 (
        rider_id,
        club_id,
        activity_date,
        intensity,
        weather_state,
        fatigue_snapshot,
        outcome,
        metadata
      )
      values (
        a.rider_id,
        v_club_id,
        v_processed_date,
        v_intensity,
        v_weather_state,
        v_fatigue,
        'skipped_not_training',
        jsonb_build_object(
          'activity_type', a.activity_type,
          'participated', a.participated,
          'source', a.source
        )
      )
      on conflict (rider_id, activity_date) do nothing;

      v_skipped_other := v_skipped_other + 1;
      continue;
    end if;

    if lower(coalesce(a.availability_status::text, 'fit'))
       in ('injured', 'sick')
    then
      insert into public.rider_training_accident_decisions_v1 (
        rider_id,
        club_id,
        activity_date,
        intensity,
        weather_state,
        fatigue_snapshot,
        outcome,
        metadata
      )
      values (
        a.rider_id,
        v_club_id,
        v_processed_date,
        v_intensity,
        v_weather_state,
        v_fatigue,
        'skipped_unavailable',
        jsonb_build_object(
          'availability_status', a.availability_status
        )
      )
      on conflict (rider_id, activity_date) do nothing;

      v_skipped_other := v_skipped_other + 1;
      continue;
    end if;

    if exists (
      select 1
      from public.rider_health_cases hc
      where hc.rider_id = a.rider_id
        and hc.status in ('active', 'recovering')
    ) then
      insert into public.rider_training_accident_decisions_v1 (
        rider_id,
        club_id,
        activity_date,
        intensity,
        weather_state,
        fatigue_snapshot,
        outcome
      )
      values (
        a.rider_id,
        v_club_id,
        v_processed_date,
        v_intensity,
        v_weather_state,
        v_fatigue,
        'skipped_open_health_case'
      )
      on conflict (rider_id, activity_date) do nothing;

      v_skipped_open_case := v_skipped_open_case + 1;
      continue;
    end if;

    -- Base daily accident probability:
    -- light  0.02%
    -- normal 0.08%
    -- hard   0.20%
    v_base_risk :=
      case v_intensity
        when 'light' then 0.0002
        when 'hard' then 0.0020
        else 0.0008
      end;

    v_fatigue_multiplier :=
      case
        when v_fatigue >= 90 then 4.0
        when v_fatigue >= 75 then 2.5
        when v_fatigue >= 60 then 1.5
        else 1.0
      end;

    v_weather_multiplier :=
      case
        when v_weather_state in (
          'storm',
          'severe_storm',
          'snow',
          'ice',
          'freezing',
          'extreme_heat'
        ) then 1.75

        when v_weather_state in (
          'poor',
          'heavy_rain',
          'rain',
          'wet',
          'strong_wind',
          'heat'
        ) then 1.30

        when v_weather_state = 'mixed' then 1.12

        else 1.00
      end;

    -- Reuse the existing health calculation as the source of truth for
    -- medical-team risk reduction.
    v_medical_risk_reduction_pct := 0;

    if v_club_id is not null then
      begin
        v_calc := public.health_calculate_case_recovery_v1(
          v_club_id,
          'muscle_strain',
          'minor',
          v_processed_date
        );

        v_medical_risk_reduction_pct :=
          greatest(
            0,
            least(
              90,
              coalesce(
                nullif(
                  v_calc->'medical_staff'->>'risk_reduction_pct',
                  ''
                )::numeric,
                0
              )
            )
          );
      exception
        when others then
          v_medical_risk_reduction_pct := 0;
      end;
    end if;

    v_final_risk :=
      least(
        0.05,
        greatest(
          0,
          v_base_risk
          * v_fatigue_multiplier
          * v_weather_multiplier
          * (1 - v_medical_risk_reduction_pct / 100.0)
          * public.training_center_training_risk_multiplier_v1(v_club_id)
          * public.health_get_medical_center_risk_multiplier_v1(v_club_id)
        )
      );

    -- Deterministic values make same-day reruns reproducible.
    v_risk_roll :=
      (
        abs(
          hashtextextended(
            a.rider_id::text
            || '|'
            || v_processed_date::text
            || '|training_accident_risk_v1',
            0
          )
        ) % 1000000
      )::numeric / 1000000.0;

    if p_force_rider_id = a.rider_id then
      v_risk_roll := 0;
    end if;

    if v_risk_roll >= v_final_risk
       and p_force_rider_id is distinct from a.rider_id
    then
      insert into public.rider_training_accident_decisions_v1 (
        rider_id,
        club_id,
        activity_date,
        intensity,
        weather_state,
        fatigue_snapshot,
        base_risk,
        fatigue_multiplier,
        weather_multiplier,
        medical_risk_reduction_pct,
        final_risk,
        risk_roll,
        outcome,
        metadata
      )
      values (
        a.rider_id,
        v_club_id,
        v_processed_date,
        v_intensity,
        v_weather_state,
        v_fatigue,
        v_base_risk,
        v_fatigue_multiplier,
        v_weather_multiplier,
        v_medical_risk_reduction_pct,
        v_final_risk,
        v_risk_roll,
        'no_accident',
        jsonb_build_object(
          'processor_version', 'training_accident_processor_v1'
        )
      )
      on conflict (rider_id, activity_date) do nothing;

      v_no_accident := v_no_accident + 1;
      continue;
    end if;

    v_severity_roll :=
      (
        abs(
          hashtextextended(
            a.rider_id::text
            || '|'
            || v_processed_date::text
            || '|training_accident_severity_v1',
            0
          )
        ) % 1000000
      )::numeric / 1000000.0;

    v_case_roll :=
      (
        abs(
          hashtextextended(
            a.rider_id::text
            || '|'
            || v_processed_date::text
            || '|training_accident_case_v1',
            0
          )
        ) % 1000000
      )::numeric / 1000000.0;

    v_severity :=
      coalesce(
        lower(p_force_severity),
        case
          -- Major outcomes are intentionally very rare.
          when v_severity_roll < 0.005 then 'major'
          when v_severity_roll < 0.105 then 'moderate'
          else 'minor'
        end
      );

    if v_severity = 'major' then
      v_case_code :=
        case
          when v_case_roll < 0.15 then 'fracture'
          when v_case_roll < 0.55 then 'muscle_strain'
          else 'tendonitis'
        end;
    elsif v_severity = 'moderate' then
      v_case_code :=
        case
          when v_case_roll < 0.45 then 'muscle_strain'
          when v_case_roll < 0.75 then 'tendonitis'
          when v_case_roll < 0.90 then 'knee_pain'
          else 'wrist_sprain'
        end;
    else
      v_case_code :=
        case
          when v_case_roll < 0.35 then 'muscle_strain'
          when v_case_roll < 0.60 then 'knee_pain'
          when v_case_roll < 0.78 then 'saddle_sore'
          when v_case_roll < 0.92 then 'ankle_sprain'
          else 'wrist_sprain'
        end;
    end if;

    v_body_part := public.health_pick_default_body_part_v1(
      v_case_code
    );

    begin
      v_result := public.health_create_rider_case_v1(
        p_rider_id := a.rider_id,
        p_club_id := v_club_id,
        p_case_code := v_case_code,
        p_severity := v_severity,
        p_source_type := 'training',
        p_source_id := null::uuid,
        p_body_part := v_body_part,
        p_started_on := v_processed_date,
        p_notes := jsonb_build_object(
          'created_by', 'process_daily_training_accidents_v1',
          'processor_version', 'training_accident_processor_v1',
          'activity_date', v_processed_date,
          'intensity', v_intensity,
          'weather_state', v_weather_state,
          'fatigue_snapshot', v_fatigue,
          'base_risk', v_base_risk,
          'fatigue_multiplier', v_fatigue_multiplier,
          'weather_multiplier', v_weather_multiplier,
          'medical_risk_reduction_pct',
            v_medical_risk_reduction_pct,
          'final_risk', v_final_risk,
          'risk_roll', v_risk_roll,
          'forced_test',
            p_force_rider_id = a.rider_id
        )
      );

      v_health_case_id :=
        (v_result->>'health_case_id')::uuid;

      insert into public.rider_training_accident_decisions_v1 (
        rider_id,
        club_id,
        activity_date,
        intensity,
        weather_state,
        fatigue_snapshot,
        base_risk,
        fatigue_multiplier,
        weather_multiplier,
        medical_risk_reduction_pct,
        final_risk,
        risk_roll,
        outcome,
        case_code,
        severity,
        health_case_id,
        metadata
      )
      values (
        a.rider_id,
        v_club_id,
        v_processed_date,
        v_intensity,
        v_weather_state,
        v_fatigue,
        v_base_risk,
        v_fatigue_multiplier,
        v_weather_multiplier,
        v_medical_risk_reduction_pct,
        v_final_risk,
        v_risk_roll,
        'accident_created',
        v_case_code,
        v_severity,
        v_health_case_id,
        jsonb_build_object(
          'processor_version', 'training_accident_processor_v1',
          'forced_test', p_force_rider_id = a.rider_id
        )
      )
      on conflict (rider_id, activity_date) do nothing;

      v_accidents_created := v_accidents_created + 1;

    exception
      when unique_violation then
        insert into public.rider_training_accident_decisions_v1 (
          rider_id,
          club_id,
          activity_date,
          intensity,
          weather_state,
          fatigue_snapshot,
          base_risk,
          fatigue_multiplier,
          weather_multiplier,
          medical_risk_reduction_pct,
          final_risk,
          risk_roll,
          outcome,
          case_code,
          severity,
          metadata
        )
        values (
          a.rider_id,
          v_club_id,
          v_processed_date,
          v_intensity,
          v_weather_state,
          v_fatigue,
          v_base_risk,
          v_fatigue_multiplier,
          v_weather_multiplier,
          v_medical_risk_reduction_pct,
          v_final_risk,
          v_risk_roll,
          'skipped_open_health_case',
          v_case_code,
          v_severity,
          jsonb_build_object(
            'sqlstate', sqlstate,
            'message', sqlerrm
          )
        )
        on conflict (rider_id, activity_date) do nothing;

        v_skipped_open_case := v_skipped_open_case + 1;

      when others then
        insert into public.rider_training_accident_decisions_v1 (
          rider_id,
          club_id,
          activity_date,
          intensity,
          weather_state,
          fatigue_snapshot,
          base_risk,
          fatigue_multiplier,
          weather_multiplier,
          medical_risk_reduction_pct,
          final_risk,
          risk_roll,
          outcome,
          case_code,
          severity,
          metadata
        )
        values (
          a.rider_id,
          v_club_id,
          v_processed_date,
          v_intensity,
          v_weather_state,
          v_fatigue,
          v_base_risk,
          v_fatigue_multiplier,
          v_weather_multiplier,
          v_medical_risk_reduction_pct,
          v_final_risk,
          v_risk_roll,
          'creation_failed',
          v_case_code,
          v_severity,
          jsonb_build_object(
            'sqlstate', sqlstate,
            'message', sqlerrm
          )
        )
        on conflict (rider_id, activity_date) do nothing;

        v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'version', 'training_accident_processor_v1',
    'processed_date', v_processed_date,
    'checked_activities', v_checked,
    'no_accident', v_no_accident,
    'accidents_created', v_accidents_created,
    'skipped_open_health_case', v_skipped_open_case,
    'skipped_other', v_skipped_other,
    'failed', v_failed
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.equipment_current_user_has_premium_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_has_premium boolean := false;
begin
  if auth.uid() is null then
    return false;
  end if;

  if to_regprocedure('public.current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.current_user_has_premium_v1(), false)'
      into v_has_premium;
    return coalesce(v_has_premium, false);
  end if;

  if to_regclass('public.user_premium_subscriptions') is not null then
    begin
      execute $query$
        select exists (
          select 1
          from public.user_premium_subscriptions s
          where s.user_id = $1
            and coalesce(s.stripe_status, '') in ('active', 'trialing')
            and (s.access_until is null or s.access_until >= now())
        )
      $query$
      into v_has_premium
      using auth.uid();

      return coalesce(v_has_premium, false);
    exception
      when undefined_column then
        return false;
    end;
  end if;

  return false;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_get_premium_features_v1(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_is_premium boolean;
  v_coin_balance integer := 0;
  v_threshold integer := 80;
  v_auto_restock_enabled boolean := false;
begin
  v_club_id := public.equipment_assert_club_access(p_club_id);
  v_is_premium := public.equipment_current_user_has_premium_v1();

  select coalesce(w.balance, 0)
  into v_coin_balance
  from public.user_wallets w
  where w.user_id = auth.uid();

  select coalesce(p.maintenance_reminder_threshold, 80)
  into v_threshold
  from public.equipment_premium_preferences p
  where p.club_id = v_club_id;

  select exists (
    select 1
    from public.equipment_auto_restock_rules r
    where r.club_id = v_club_id
      and r.enabled = true
  )
  into v_auto_restock_enabled;

  return jsonb_build_object(
    'club_id', v_club_id,
    'is_premium', v_is_premium,
    'coin_balance', coalesce(v_coin_balance, 0),
    'slot_1_unlocked', true,
    'slot_2_unlocked', true,
    'slot_3_unlocked',
      v_is_premium
      or exists (
        select 1
        from public.equipment_setup_slot_unlocks u
        where u.club_id = v_club_id
          and u.setup_slot = 3
      ),
    'slot_4_unlocked',
      v_is_premium
      or exists (
        select 1
        from public.equipment_setup_slot_unlocks u
        where u.club_id = v_club_id
          and u.setup_slot = 4
      ),
    'auto_restock_enabled', v_is_premium and v_auto_restock_enabled,
    'maintenance_reminder_threshold', coalesce(v_threshold, 80)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_unlock_setup_slot_v1(p_club_id uuid, p_setup_slot smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_user_id uuid := auth.uid();
  v_balance integer;
  v_coin_cost integer := 10;
  v_system_key text;
begin
  if v_user_id is null then
    raise exception 'Authentication required.' using errcode = '28000';
  end if;

  v_club_id := public.equipment_assert_club_access(p_club_id);

  if p_setup_slot not in (3, 4) then
    raise exception 'Only setup slots 3 and 4 can be unlocked.';
  end if;

  if public.equipment_current_user_has_premium_v1() then
    return public.equipment_get_premium_features_v1(v_club_id);
  end if;

  if exists (
    select 1
    from public.equipment_setup_slot_unlocks u
    where u.club_id = v_club_id
      and u.setup_slot = p_setup_slot
  ) then
    return public.equipment_get_premium_features_v1(v_club_id);
  end if;

  insert into public.user_wallets (user_id, balance)
  values (v_user_id, 0)
  on conflict (user_id) do nothing;

  select w.balance
  into v_balance
  from public.user_wallets w
  where w.user_id = v_user_id
  for update;

  -- Recheck after locking the wallet so concurrent requests cannot double-charge.
  if exists (
    select 1
    from public.equipment_setup_slot_unlocks u
    where u.club_id = v_club_id
      and u.setup_slot = p_setup_slot
  ) then
    return public.equipment_get_premium_features_v1(v_club_id);
  end if;

  if coalesce(v_balance, 0) < v_coin_cost then
    raise exception 'You need % coins to unlock this setup slot. Current balance: %.',
      v_coin_cost,
      coalesce(v_balance, 0);
  end if;

  v_system_key := format(
    'equipment_setup_slot_unlock_%s_%s',
    v_club_id::text,
    p_setup_slot::text
  );

  if exists (
    select 1
    from public.user_coin_ledger l
    where l.user_id = v_user_id
      and l.payload_json ->> 'system_key' = v_system_key
  ) then
    insert into public.equipment_setup_slot_unlocks (
      club_id,
      setup_slot,
      unlocked_with,
      coin_cost,
      unlocked_by_user_id
    )
    values (
      v_club_id,
      p_setup_slot,
      'coins',
      v_coin_cost,
      v_user_id
    )
    on conflict (club_id, setup_slot) do nothing;

    return public.equipment_get_premium_features_v1(v_club_id);
  end if;

  insert into public.user_coin_ledger (
    user_id,
    delta,
    reason,
    payload_json
  )
  values (
    v_user_id,
    -v_coin_cost,
    'equipment_setup_slot_unlock',
    jsonb_build_object(
      'system_key', v_system_key,
      'category', 'equipment',
      'club_id', v_club_id,
      'setup_slot', p_setup_slot,
      'coin_cost', v_coin_cost,
      'permanent_unlock', true
    )
  );

  update public.user_wallets
  set balance = balance - v_coin_cost
  where user_id = v_user_id;

  insert into public.equipment_setup_slot_unlocks (
    club_id,
    setup_slot,
    unlocked_with,
    coin_cost,
    unlocked_by_user_id
  )
  values (
    v_club_id,
    p_setup_slot,
    'coins',
    v_coin_cost,
    v_user_id
  );

  return public.equipment_get_premium_features_v1(v_club_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_save_maintenance_reminder_v1(p_club_id uuid, p_condition_threshold integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  v_club_id := public.equipment_assert_club_access(p_club_id);

  if not public.equipment_current_user_has_premium_v1() then
    raise exception 'Premium membership is required for maintenance reminders.';
  end if;

  if p_condition_threshold not between 1 and 100 then
    raise exception 'Condition threshold must be between 1 and 100.';
  end if;

  insert into public.equipment_premium_preferences (
    club_id,
    maintenance_reminder_threshold,
    updated_by_user_id,
    updated_at
  )
  values (
    v_club_id,
    p_condition_threshold,
    auth.uid(),
    now()
  )
  on conflict (club_id) do update
  set maintenance_reminder_threshold = excluded.maintenance_reminder_threshold,
      updated_by_user_id = excluded.updated_by_user_id,
      updated_at = excluded.updated_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_get_auto_restock_rules_v1(p_club_id uuid)
 RETURNS TABLE(supply_key text, enabled boolean, minimum_stock integer, order_quantity integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  v_club_id := public.equipment_assert_club_access(p_club_id);

  if not public.equipment_current_user_has_premium_v1() then
    return;
  end if;

  return query
  with defaults(supply_key, minimum_stock, order_quantity) as (
    values
      ('bidons_water_bottles'::text, 50, 100),
      ('energy_gels'::text, 50, 100),
      ('nutrition_packs'::text, 30, 50),
      ('race_jersey_complete'::text, 10, 10),
      ('rain_jackets'::text, 10, 10)
  )
  select
    d.supply_key,
    coalesce(r.enabled, false),
    coalesce(r.minimum_stock, d.minimum_stock),
    coalesce(r.order_quantity, d.order_quantity)
  from defaults d
  left join public.equipment_auto_restock_rules r
    on r.club_id = v_club_id
   and r.supply_key = d.supply_key
  order by case d.supply_key
    when 'bidons_water_bottles' then 1
    when 'energy_gels' then 2
    when 'nutrition_packs' then 3
    when 'race_jersey_complete' then 4
    when 'rain_jackets' then 5
    else 99
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_save_auto_restock_rule_v1(p_club_id uuid, p_supply_key text, p_enabled boolean, p_minimum_stock integer, p_order_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  v_club_id := public.equipment_assert_club_access(p_club_id);

  if not public.equipment_current_user_has_premium_v1() then
    raise exception 'Premium membership is required for automatic restocking.';
  end if;

  if p_supply_key not in (
    'bidons_water_bottles',
    'energy_gels',
    'nutrition_packs',
    'race_jersey_complete',
    'rain_jackets'
  ) then
    raise exception 'Unsupported race supply key: %.', p_supply_key;
  end if;

  if p_minimum_stock not between 0 and 99999 then
    raise exception 'Minimum stock must be between 0 and 99999.';
  end if;

  if p_order_quantity not between 1 and 999 then
    raise exception 'Order quantity must be between 1 and 999.';
  end if;

  insert into public.equipment_auto_restock_rules (
    club_id,
    supply_key,
    enabled,
    minimum_stock,
    order_quantity,
    updated_by_user_id,
    updated_at
  )
  values (
    v_club_id,
    p_supply_key,
    coalesce(p_enabled, false),
    p_minimum_stock,
    p_order_quantity,
    auth.uid(),
    now()
  )
  on conflict (club_id, supply_key) do update
  set enabled = excluded.enabled,
      minimum_stock = excluded.minimum_stock,
      order_quantity = excluded.order_quantity,
      updated_by_user_id = excluded.updated_by_user_id,
      updated_at = excluded.updated_at;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.equipment_enforce_setup_slot_access_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
begin
  if new.setup_slot not in (3,4) then
    return new;
  end if;

  -- Technical National Team clubs use a system-provided, standardized
  -- equipment package. They never require Premium or a coin unlock.
  if public.is_national_team_club_v1(new.club_id) then
    return new;
  end if;

  -- Allow equipment_get_setup_presets() to create an empty placeholder row.
  if new.frame_catalog_item_id is null
     and new.wheelset_catalog_item_id is null
     and new.tires_catalog_item_id is null
     and new.groupset_catalog_item_id is null
     and new.helmet_catalog_item_id is null
     and new.shoes_catalog_item_id is null then
    return new;
  end if;

  if auth.role()='service_role' then
    return new;
  end if;

  if public.equipment_current_user_has_premium_v1() then
    return new;
  end if;

  if exists(
    select 1
    from public.equipment_setup_slot_unlocks u
    where u.club_id=new.club_id
      and u.setup_slot=new.setup_slot
  ) then
    return new;
  end if;

  raise exception 'Setup slot % requires Premium or a permanent coin unlock.',new.setup_slot;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.race_engine_get_live_equipment_transport_bundle_dev_v1(p_stage_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid;
  v_club_id uuid;

  v_rio_stage_1_id constant uuid :=
    '24709c46-b258-4db3-a3aa-fd92dc37630e'::uuid;

  v_japan_hilly_stage_id constant uuid :=
    '3ca7d3dd-6a45-4829-b08e-6b118309fdd8'::uuid;

  v_rio_stage_2_id constant uuid :=
    'b28d57bd-29bc-47aa-bace-59a2cf7732ab'::uuid;

  v_source_bundle jsonb;

  v_simulation_run_id uuid;
  v_race_id uuid;
  v_run_stage_id uuid;
  v_run_status text;
  v_completed_at timestamptz;
  v_created_at timestamptz;

  v_equipment_conditions jsonb;
  v_preparation_modifiers jsonb;
BEGIN
  v_user_id :=
    auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION
      'Authentication is required for the live equipment transport diagnostic.';
  END IF;

  SELECT
    public.get_my_club_id()
  INTO
    v_club_id;

  IF v_club_id IS NULL THEN
    RAISE EXCEPTION
      'An active club is required for the live equipment transport diagnostic.';
  END IF;

  IF p_stage_id IS NULL THEN
    RAISE EXCEPTION
      'p_stage_id must not be null.';
  END IF;

  IF p_stage_id NOT IN (
    v_rio_stage_1_id,
    v_japan_hilly_stage_id,
    v_rio_stage_2_id
  ) THEN
    RAISE EXCEPTION
      'This development diagnostic allows only Rio Stage 1, Japan Road Cup Stage 1, and Rio Stage 2.';
  END IF;

  v_source_bundle :=
    public.race_engine_get_calibrated_shadow_source_bundle_v1(
      p_stage_id
    );

  SELECT
    simulation_run.id,
    simulation_run.race_id,
    simulation_run.stage_id,
    simulation_run.status,
    simulation_run.completed_at,
    simulation_run.created_at
  INTO
    v_simulation_run_id,
    v_race_id,
    v_run_stage_id,
    v_run_status,
    v_completed_at,
    v_created_at
  FROM
    public.race_stage_simulation_runs simulation_run
  WHERE
    simulation_run.stage_id =
      p_stage_id
    AND simulation_run.status =
      'completed'
  ORDER BY
    simulation_run.completed_at
      DESC NULLS LAST,
    simulation_run.updated_at
      DESC NULLS LAST,
    simulation_run.created_at
      DESC NULLS LAST,
    simulation_run.id::text
      DESC
  LIMIT 1;

  IF v_simulation_run_id IS NULL THEN
    RAISE EXCEPTION
      'No completed simulation run exists for stage %.',
      p_stage_id;
  END IF;

  IF v_run_stage_id IS DISTINCT FROM p_stage_id THEN
    RAISE EXCEPTION
      'Resolved simulation run stage does not match p_stage_id.';
  END IF;

  IF
    NULLIF(
      v_source_bundle ->> 'race_id',
      ''
    )::uuid
    IS DISTINCT FROM
    v_race_id
  THEN
    RAISE EXCEPTION
      'Resolved simulation run race does not match calibrated source bundle.';
  END IF;

  SELECT
    COALESCE(
      jsonb_agg(
        to_jsonb(
          equipment_row
        )
        ORDER BY
          equipment_row.team_id::text,
          equipment_row.rider_id::text
      ),
      '[]'::jsonb
    )
  INTO
    v_equipment_conditions
  FROM
    public.race_engine_resolve_stage_rider_equipment_condition_v1(
      v_simulation_run_id
    ) equipment_row;

  SELECT
    COALESCE(
      jsonb_agg(
        to_jsonb(
          preparation_row
        )
        ORDER BY
          preparation_row.team_id::text,
          preparation_row.rider_id::text
      ),
      '[]'::jsonb
    )
  INTO
    v_preparation_modifiers
  FROM
    public.race_engine_get_stage_rider_preparation_modifiers_v2(
      p_stage_id
    ) preparation_row;

  RETURN
    jsonb_build_object(
      'status',
        'ok',

      'bundle_version',
        'phase_8h4c1_live_equipment_transport_bundle_dev_v1',

      'source_bundle',
        v_source_bundle,

      'simulation_run',
        jsonb_build_object(
          'id',
            v_simulation_run_id,
          'race_id',
            v_race_id,
          'stage_id',
            v_run_stage_id,
          'status',
            v_run_status,
          'completed_at',
            v_completed_at,
          'created_at',
            v_created_at
        ),

      'equipment_conditions',
        v_equipment_conditions,

      'preparation_modifiers',
        v_preparation_modifiers,

      'safety',
        jsonb_build_object(
          'authenticated_user_required',
            true,
          'active_club_required',
            true,
          'allowed_stage_count',
            3,
          'read_only',
            true,
          'persistent_writes',
            false,
          'technical_incident_execution',
            false,
          'technical_time_loss',
            false,
          'equipment_assignment',
            false,
          'equipment_wear',
            false,
          'equipment_damage',
            false,
          'production_execution_change',
            false
        )
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_current_user_has_premium_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_result boolean := false;
begin
  if auth.uid() is null then
    return false;
  end if;

  if to_regprocedure('public.current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  if to_regprocedure('public.equipment_current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.equipment_current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  return false;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_assert_club_access_v1(p_club_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_main_club_id uuid;
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select
    case
      when c.club_type = 'developing' and c.parent_club_id is not null
        then c.parent_club_id
      else c.id
    end
  into v_main_club_id
  from public.clubs c
  where c.id = p_club_id
    and (
      c.owner_user_id = v_user_id
      or exists (
        select 1
        from public.clubs main_club
        where main_club.id = c.parent_club_id
          and main_club.owner_user_id = v_user_id
      )
    )
  limit 1;

  if v_main_club_id is null then
    raise exception 'Club access denied.' using errcode = '42501';
  end if;

  return v_main_club_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_effective_asset_slots_v1(p_club_id uuid, p_asset_key text, p_is_premium boolean DEFAULT NULL::boolean)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_free integer;
  v_premium integer;
  v_absolute integer;
  v_permanent integer := 0;
  v_is_premium boolean;
begin
  select l.free_slots, l.premium_slots, l.absolute_max_slots
  into v_free, v_premium, v_absolute
  from public.infrastructure_asset_slot_limits_v1(p_asset_key) l;

  if v_absolute is null then
    raise exception 'Unsupported infrastructure asset key: %', p_asset_key;
  end if;

  v_is_premium := coalesce(
    p_is_premium,
    public.infrastructure_current_user_has_premium_v1()
  );

  select coalesce(max(u.slot_number), 0)
  into v_permanent
  from public.infrastructure_asset_slot_unlocks u
  where u.club_id = p_club_id
    and u.asset_key = p_asset_key;

  return least(
    v_absolute,
    greatest(
      v_free,
      case when v_is_premium then v_premium else 0 end,
      v_permanent
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_get_asset_slot_access_v1(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_is_premium boolean;
  v_coin_balance integer := 0;
  v_assets jsonb;
begin
  v_club_id := public.infrastructure_assert_club_access_v1(p_club_id);
  v_is_premium := public.infrastructure_current_user_has_premium_v1();

  select coalesce(w.balance, 0)
  into v_coin_balance
  from public.user_wallets w
  where w.user_id = auth.uid();

  select jsonb_agg(
    jsonb_build_object(
      'asset_key', k.asset_key,
      'free_slots', l.free_slots,
      'premium_slots', l.premium_slots,
      'absolute_max_slots', l.absolute_max_slots,
      'effective_slots',
        public.infrastructure_effective_asset_slots_v1(
          v_club_id,
          k.asset_key,
          v_is_premium
        ),
      'highest_permanent_slot',
        coalesce((
          select max(u.slot_number)
          from public.infrastructure_asset_slot_unlocks u
          where u.club_id = v_club_id
            and u.asset_key = k.asset_key
        ), 0),
      'permanently_unlocked_slots',
        coalesce((
          select jsonb_agg(u.slot_number order by u.slot_number)
          from public.infrastructure_asset_slot_unlocks u
          where u.club_id = v_club_id
            and u.asset_key = k.asset_key
        ), '[]'::jsonb),
      'is_premium', v_is_premium,
      'coin_balance', coalesce(v_coin_balance, 0),
      'coin_cost', 20
    )
    order by k.sort_order
  )
  into v_assets
  from (
    values
      ('team_car', 1),
      ('team_bus', 2),
      ('equipment_van', 3),
      ('mobile_workshop', 4),
      ('medical_van', 5)
  ) as k(asset_key, sort_order)
  cross join lateral public.infrastructure_asset_slot_limits_v1(k.asset_key) l;

  return jsonb_build_object(
    'club_id', v_club_id,
    'is_premium', v_is_premium,
    'coin_balance', coalesce(v_coin_balance, 0),
    'coin_cost', 20,
    'assets', coalesce(v_assets, '[]'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_unlock_asset_slot_v1(p_club_id uuid, p_asset_key text, p_slot_number smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_user_id uuid := auth.uid();
  v_free integer;
  v_premium integer;
  v_absolute integer;
  v_balance integer;
  v_coin_cost integer := 20;
  v_system_key text;
begin
  if v_user_id is null then
    raise exception 'Authentication required.' using errcode = '28000';
  end if;

  v_club_id := public.infrastructure_assert_club_access_v1(p_club_id);

  select l.free_slots, l.premium_slots, l.absolute_max_slots
  into v_free, v_premium, v_absolute
  from public.infrastructure_asset_slot_limits_v1(p_asset_key) l;

  if v_absolute is null then
    raise exception 'Unsupported infrastructure asset key.';
  end if;

  if p_slot_number <= v_free or p_slot_number > v_absolute then
    raise exception 'Slot % cannot be purchased for %.', p_slot_number, p_asset_key;
  end if;

  if exists (
    select 1
    from public.infrastructure_asset_slot_unlocks u
    where u.club_id = v_club_id
      and u.asset_key = p_asset_key
      and u.slot_number = p_slot_number
  ) then
    return public.infrastructure_get_asset_slot_access_v1(v_club_id);
  end if;

  -- Slots must be unlocked in order so highest unlocked slot fully defines capacity.
  if p_slot_number > v_free + 1
     and not exists (
       select 1
       from public.infrastructure_asset_slot_unlocks u
       where u.club_id = v_club_id
         and u.asset_key = p_asset_key
         and u.slot_number = p_slot_number - 1
     )
     and not (
       public.infrastructure_current_user_has_premium_v1()
       and p_slot_number <= v_premium + 1
     )
  then
    raise exception 'Unlock the previous garage slot first.';
  end if;

  insert into public.user_wallets (user_id, balance)
  values (v_user_id, 0)
  on conflict (user_id) do nothing;

  select w.balance
  into v_balance
  from public.user_wallets w
  where w.user_id = v_user_id
  for update;

  if exists (
    select 1
    from public.infrastructure_asset_slot_unlocks u
    where u.club_id = v_club_id
      and u.asset_key = p_asset_key
      and u.slot_number = p_slot_number
  ) then
    return public.infrastructure_get_asset_slot_access_v1(v_club_id);
  end if;

  if coalesce(v_balance, 0) < v_coin_cost then
    raise exception 'You need % coins to unlock this garage slot. Current balance: %.',
      v_coin_cost,
      coalesce(v_balance, 0);
  end if;

  v_system_key := format(
    'infrastructure_asset_slot_unlock_%s_%s_%s',
    v_club_id::text,
    p_asset_key,
    p_slot_number::text
  );

  if not exists (
    select 1
    from public.user_coin_ledger l
    where l.user_id = v_user_id
      and l.payload_json ->> 'system_key' = v_system_key
  ) then
    insert into public.user_coin_ledger (
      user_id,
      delta,
      reason,
      payload_json
    )
    values (
      v_user_id,
      -v_coin_cost,
      'infrastructure_asset_slot_unlock',
      jsonb_build_object(
        'system_key', v_system_key,
        'category', 'infrastructure',
        'club_id', v_club_id,
        'asset_key', p_asset_key,
        'slot_number', p_slot_number,
        'coin_cost', v_coin_cost,
        'permanent_unlock', true
      )
    );

    update public.user_wallets
    set balance = balance - v_coin_cost
    where user_id = v_user_id;
  end if;

  insert into public.infrastructure_asset_slot_unlocks (
    club_id,
    asset_key,
    slot_number,
    unlocked_with,
    coin_cost,
    unlocked_by_user_id
  )
  values (
    v_club_id,
    p_asset_key,
    p_slot_number,
    'coins',
    v_coin_cost,
    v_user_id
  )
  on conflict (club_id, asset_key, slot_number) do nothing;

  return public.infrastructure_get_asset_slot_access_v1(v_club_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.infrastructure_enforce_asset_delivery_capacity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_current integer := 0;
  v_pending integer := 0;
  v_effective integer;
begin
  if new.job_type <> 'asset_delivery'
     or new.status <> 'pending'
     or new.target_key not in (
       'team_car',
       'team_bus',
       'equipment_van',
       'mobile_workshop',
       'medical_van'
     )
  then
    return new;
  end if;

  select
    case new.target_key
      when 'team_car' then coalesce(i.team_car_fleet_quantity, 0)
      when 'team_bus' then coalesce(i.team_bus_quantity, 0)
      when 'equipment_van' then coalesce(i.equipment_van_quantity, 0)
      when 'mobile_workshop' then coalesce(i.mobile_workshop_quantity, 0)
      when 'medical_van' then coalesce(i.medical_van_quantity, 0)
      else 0
    end
  into v_current
  from public.club_infrastructure i
  where i.club_id = new.club_id;

  select coalesce(sum(greatest(coalesce(j.asset_quantity, 1), 1)), 0)
  into v_pending
  from public.club_infrastructure_jobs j
  where j.club_id = new.club_id
    and j.job_type = 'asset_delivery'
    and j.status = 'pending'
    and j.target_key = new.target_key
    and (tg_op = 'INSERT' or j.id <> new.id);

  v_effective := public.infrastructure_effective_asset_slots_v1(
    new.club_id,
    new.target_key,
    null
  );

  if coalesce(v_current, 0)
     + v_pending
     + greatest(coalesce(new.asset_quantity, 1), 1)
     > v_effective
  then
    raise exception
      'Garage capacity reached for %. Current/pending: %, available slots: %.',
      new.target_key,
      coalesce(v_current, 0) + v_pending,
      v_effective;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rename_club_team_car_v1(p_car_id uuid, p_display_name text)
 RETURNS TABLE(car_id uuid, club_id uuid, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_name text := btrim(coalesce(p_display_name, ''));
  v_car public.club_team_cars%rowtype;
begin
  if v_user_id is null then
    raise exception 'Not authenticated.' using errcode = '28000';
  end if;

  if p_car_id is null then
    raise exception 'Team Car id is required.';
  end if;

  if v_name = '' then
    raise exception 'Team Car name cannot be empty.';
  end if;

  if char_length(v_name) > 40 then
    raise exception 'Team Car name cannot exceed 40 characters.';
  end if;

  select car.*
  into v_car
  from public.club_team_cars car
  join public.clubs c
    on c.id = car.club_id
  where car.id = p_car_id
    and (
      c.owner_user_id = v_user_id
      or exists (
        select 1
        from public.clubs main_club
        where main_club.id = c.parent_club_id
          and main_club.owner_user_id = v_user_id
      )
    )
  for update;

  if not found then
    raise exception 'Team Car was not found or access was denied.'
      using errcode = '42501';
  end if;

  update public.club_team_cars car
  set
    display_name = v_name,
    updated_at = now()
  where car.id = p_car_id
  returning car.id, car.club_id, car.display_name
  into car_id, club_id, display_name;

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rename_club_asset_v1(p_asset_key text, p_asset_id uuid, p_display_name text)
 RETURNS TABLE(asset_key text, asset_id uuid, club_id uuid, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_asset_key text := lower(trim(coalesce(p_asset_key, '')));
  v_name text := btrim(coalesce(p_display_name, ''));
begin
  if v_user_id is null then
    raise exception 'Not authenticated.' using errcode = '28000';
  end if;

  if p_asset_id is null then
    raise exception 'Asset id is required.';
  end if;

  if v_name = '' then
    raise exception 'Asset name cannot be empty.';
  end if;

  if char_length(v_name) > 40 then
    raise exception 'Asset name cannot exceed 40 characters.';
  end if;

  if v_asset_key = 'team_bus' then
    update public.club_team_buses bus
    set display_name = v_name,
        updated_at = now()
    from public.clubs c
    where bus.id = p_asset_id
      and c.id = bus.club_id
      and (
        c.owner_user_id = v_user_id
        or exists (
          select 1
          from public.clubs main_club
          where main_club.id = c.parent_club_id
            and main_club.owner_user_id = v_user_id
        )
      )
    returning 'team_bus', bus.id, bus.club_id, bus.display_name
    into asset_key, asset_id, club_id, display_name;

  elsif v_asset_key = 'equipment_van' then
    update public.club_equipment_vans van
    set display_name = v_name,
        updated_at = now()
    from public.clubs c
    where van.id = p_asset_id
      and c.id = van.club_id
      and (
        c.owner_user_id = v_user_id
        or exists (
          select 1 from public.clubs main_club
          where main_club.id = c.parent_club_id
            and main_club.owner_user_id = v_user_id
        )
      )
    returning 'equipment_van', van.id, van.club_id, van.display_name
    into asset_key, asset_id, club_id, display_name;

  elsif v_asset_key = 'mobile_workshop' then
    update public.club_mobile_workshops workshop
    set display_name = v_name,
        updated_at = now()
    from public.clubs c
    where workshop.id = p_asset_id
      and c.id = workshop.club_id
      and (
        c.owner_user_id = v_user_id
        or exists (
          select 1 from public.clubs main_club
          where main_club.id = c.parent_club_id
            and main_club.owner_user_id = v_user_id
        )
      )
    returning 'mobile_workshop', workshop.id, workshop.club_id, workshop.display_name
    into asset_key, asset_id, club_id, display_name;

  elsif v_asset_key = 'medical_van' then
    update public.club_medical_vans van
    set display_name = v_name,
        updated_at = now()
    from public.clubs c
    where van.id = p_asset_id
      and c.id = van.club_id
      and (
        c.owner_user_id = v_user_id
        or exists (
          select 1 from public.clubs main_club
          where main_club.id = c.parent_club_id
            and main_club.owner_user_id = v_user_id
        )
      )
    returning 'medical_van', van.id, van.club_id, van.display_name
    into asset_key, asset_id, club_id, display_name;

  else
    raise exception 'Unsupported asset key: %', v_asset_key;
  end if;

  if asset_id is null then
    raise exception 'Asset was not found or access was denied.' using errcode = '42501';
  end if;

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_team_policy_user_has_premium_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_result boolean := false;
begin
  if auth.uid() is null then
    return false;
  end if;

  if to_regprocedure('public.current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  if to_regprocedure('public.equipment_current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.equipment_current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  return false;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_assert_free_policy_option_v1(p_policy_key text, p_selected_option text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_free_option text;
begin
  v_free_option := public.finance_first_free_policy_option_v1(p_policy_key);

  if v_free_option is null then
    raise exception 'No active policy option is configured for %.', p_policy_key;
  end if;

  if p_selected_option is distinct from v_free_option then
    raise exception
      'Premium is required for %. Free option: %.',
      p_policy_key,
      v_free_option
      using errcode = '42501';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_view_race_replay_frames_v1(p_race_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_participation_access boolean := false;
begin
  if v_user_id is null or p_race_id is null then
    return false;
  end if;

  if to_regprocedure(
    'public.can_view_race_replay_frames_participation_only_v1(uuid)'
  ) is not null
  then
    execute
      'select coalesce(public.can_view_race_replay_frames_participation_only_v1($1), false)'
      into v_participation_access
      using p_race_id;
  end if;

  return
    coalesce(v_participation_access, false)
    or exists (
      select 1
      from public.race_replay_coin_unlocks u
      where u.user_id = v_user_id
        and u.race_id = p_race_id
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_race_replay_coin_access_v1(p_race_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_balance integer := 0;
  v_coin_unlocked boolean := false;
  v_is_premium boolean := false;
begin
  if v_user_id is null then
    raise exception 'Not authenticated.' using errcode = '28000';
  end if;

  if p_race_id is null then
    raise exception 'Race id is required.';
  end if;

  select coalesce(w.balance, 0)
  into v_balance
  from public.user_wallets w
  where w.user_id = v_user_id;

  select exists (
    select 1
    from public.race_replay_coin_unlocks u
    where u.user_id = v_user_id
      and u.race_id = p_race_id
  )
  into v_coin_unlocked;

  v_is_premium := public.current_user_has_premium_v1();

  return jsonb_build_object(
    'race_id', p_race_id,
    'coin_cost', case when v_is_premium then 0 else 2 end,
    'coin_balance', coalesce(v_balance, 0),
    'has_coin_unlock', v_coin_unlocked,
    'has_premium_access', v_is_premium,
    'has_replay_access', v_coin_unlocked or v_is_premium
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.purchase_race_replay_access_v1(p_race_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_balance integer := 0;
  v_system_key text;
begin
  if v_user_id is null then
    raise exception 'Not authenticated.' using errcode = '28000';
  end if;

  if p_race_id is null then
    raise exception 'Race id is required.';
  end if;

  -- Premium membership includes world-race replay access. Never charge coins.
  if public.current_user_has_premium_v1() then
    return public.get_race_replay_coin_access_v1(p_race_id);
  end if;

  if exists (
    select 1
    from public.race_replay_coin_unlocks u
    where u.user_id = v_user_id
      and u.race_id = p_race_id
  ) then
    return public.get_race_replay_coin_access_v1(p_race_id);
  end if;

  insert into public.user_wallets (user_id, balance)
  values (v_user_id, 0)
  on conflict (user_id) do nothing;

  select w.balance
  into v_balance
  from public.user_wallets w
  where w.user_id = v_user_id
  for update;

  if coalesce(v_balance, 0) < 2 then
    raise exception
      'You need 2 coins to unlock this race replay. Current balance: %.',
      coalesce(v_balance, 0);
  end if;

  v_system_key := format(
    'race_replay_unlock_%s_%s',
    v_user_id::text,
    p_race_id::text
  );

  if not exists (
    select 1
    from public.user_coin_ledger l
    where l.user_id = v_user_id
      and l.payload_json ->> 'system_key' = v_system_key
  ) then
    insert into public.user_coin_ledger (
      user_id,
      delta,
      reason,
      payload_json
    )
    values (
      v_user_id,
      -2,
      'race_replay_unlock',
      jsonb_build_object(
        'system_key', v_system_key,
        'category', 'race_replay',
        'race_id', p_race_id,
        'coin_cost', 2,
        'permanent_unlock', true
      )
    );

    update public.user_wallets
    set balance = balance - 2
    where user_id = v_user_id;
  end if;

  insert into public.race_replay_coin_unlocks (
    user_id,
    race_id,
    coin_cost
  )
  values (
    v_user_id,
    p_race_id,
    2
  )
  on conflict (user_id, race_id) do nothing;

  return public.get_race_replay_coin_access_v1(p_race_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_assert_owned_main_club_v1(p_club_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated.' using errcode = '28000';
  end if;

  select c.id into v_club_id
  from public.clubs c
  where c.id = p_club_id
    and c.owner_user_id = auth.uid()
    and c.club_type = 'main'
  limit 1;

  if v_club_id is null then
    raise exception 'Main club access denied.' using errcode = '42501';
  end if;

  return v_club_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_user_has_premium_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_result boolean := false;
begin
  if auth.uid() is null then return false; end if;

  if to_regprocedure('public.current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  if to_regprocedure('public.equipment_current_user_has_premium_v1()') is not null then
    execute 'select coalesce(public.equipment_current_user_has_premium_v1(), false)'
      into v_result;
    return coalesce(v_result, false);
  end if;

  return false;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_get_intelligence_access_v1(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_is_premium boolean;
begin
  v_club_id := public.transfer_assert_owned_main_club_v1(p_club_id);
  v_is_premium := public.transfer_user_has_premium_v1();

  return jsonb_build_object(
    'is_premium', v_is_premium,
    'saved_search_limit', case when v_is_premium then 10 else 0 end,
    'shortlist_limit', case when v_is_premium then 30 else 0 end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_list_saved_searches_v1(p_club_id uuid)
 RETURNS SETOF transfer_saved_searches
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  v_club_id := public.transfer_assert_owned_main_club_v1(p_club_id);

  if not public.transfer_user_has_premium_v1() then
    return;
  end if;

  return query
  select *
  from public.transfer_saved_searches
  where club_id = v_club_id
  order by slot_number;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_save_market_search_v1(p_club_id uuid, p_slot_number smallint, p_search_name text, p_market_type text, p_criteria_json jsonb, p_alerts_enabled boolean)
 RETURNS transfer_saved_searches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_row public.transfer_saved_searches;
begin
  v_club_id := public.transfer_assert_owned_main_club_v1(p_club_id);

  if not public.transfer_user_has_premium_v1() then
    raise exception 'Premium is required for saved transfer searches.'
      using errcode = '42501';
  end if;

  if p_slot_number < 1 or p_slot_number > 10 then
    raise exception 'Premium saved-search slots are limited to 10.';
  end if;

  insert into public.transfer_saved_searches (
    club_id,
    slot_number,
    search_name,
    market_type,
    criteria_json,
    alerts_enabled,
    created_by_user_id
  )
  values (
    v_club_id,
    p_slot_number,
    btrim(p_search_name),
    p_market_type,
    coalesce(p_criteria_json, '{}'::jsonb),
    true,
    auth.uid()
  )
  on conflict (club_id, slot_number)
  do update set
    search_name = excluded.search_name,
    market_type = excluded.market_type,
    criteria_json = excluded.criteria_json,
    alerts_enabled = true,
    updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_delete_saved_search_v1(p_saved_search_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare v_count integer;
begin
  delete from public.transfer_saved_searches s
  using public.clubs c
  where s.id = p_saved_search_id
    and c.id = s.club_id
    and c.owner_user_id = auth.uid();

  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_list_shortlist_v1(p_club_id uuid)
 RETURNS SETOF transfer_shortlist
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
begin
  v_club_id := public.transfer_assert_owned_main_club_v1(p_club_id);

  if not public.transfer_user_has_premium_v1() then
    return;
  end if;

  return query
  select *
  from public.transfer_shortlist
  where club_id = v_club_id
  order by created_at desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_add_shortlist_target_v1(p_club_id uuid, p_target_type text, p_target_id uuid, p_target_name text, p_notes text)
 RETURNS transfer_shortlist
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_club_id uuid;
  v_count integer;
  v_row public.transfer_shortlist;
begin
  v_club_id := public.transfer_assert_owned_main_club_v1(p_club_id);

  if not public.transfer_user_has_premium_v1() then
    raise exception 'Premium is required for the transfer shortlist.'
      using errcode = '42501';
  end if;

  select count(*) into v_count
  from public.transfer_shortlist
  where club_id = v_club_id;

  if v_count >= 30 and not exists (
    select 1
    from public.transfer_shortlist
    where club_id = v_club_id
      and target_type = p_target_type
      and target_id = p_target_id
  ) then
    raise exception 'Premium shortlist limit reached (30).';
  end if;

  insert into public.transfer_shortlist (
    club_id,
    target_type,
    target_id,
    target_name,
    notes,
    created_by_user_id
  )
  values (
    v_club_id,
    p_target_type,
    p_target_id,
    btrim(p_target_name),
    nullif(btrim(coalesce(p_notes, '')), ''),
    auth.uid()
  )
  on conflict (club_id, target_type, target_id)
  do update set
    target_name = excluded.target_name,
    notes = excluded.notes
  returning * into v_row;

  return v_row;
end;
$function$
;

